window.__FULL_WORDS_DATA__ = [{"id":1,"unit":1,"lesson":1,"word":"ambition","pronunciation":"/æmˈbɪʃ(ə)n/","meaning":"n.野心;雄心;抱负","seq":1,"isStar":false,"memo":"谐音 单词发音类似“俺必胜”→雄心，抱负","example":"He found an outlet for his ambition in his work. 他在工作中找到了施展抱负的途径。"},{"id":2,"unit":1,"lesson":1,"word":"ambitious","pronunciation":"/æmˈbɪʃəs/","meaning":"adj.有雄心的，有抱负的","seq":2,"isStar":false},{"id":3,"unit":1,"lesson":1,"word":"aggressive","pronunciation":"/əˈɡresɪv/","meaning":"adj.好斗的，侵略的;有进取心的","seq":3,"isStar":false,"memo":"联想 ag-(一再地) + gress(走) + -ive(形容词后缀) → 一再地(为了梦想)向前走 → 有进取心的","example":"The dog is aggressive towards strangers. 这只狗对陌生人有攻击性。"},{"id":4,"unit":1,"lesson":1,"word":"aggression","pronunciation":"/əˈɡreʃ(ə)n/","meaning":"n.攻击性;侵略","seq":4,"isStar":false},{"id":5,"unit":1,"lesson":1,"word":"congress","pronunciation":"/ˈkɒŋɡres/","meaning":"n.国会，议会;代表大会","seq":5,"isStar":false,"memo":"构词 con-(一起) + gress(走) → 所有代表走到一起，参加大会 → 国会，议会；代表大会","example":"Congress has already taken some modest steps. 国会已经采取了一些温和的措施。"},{"id":6,"unit":1,"lesson":1,"word":"congressional","pronunciation":"/kənˈɡreʃən(ə)l/","meaning":"adj.国会的;代表大会的","seq":6,"isStar":false},{"id":7,"unit":1,"lesson":1,"word":"parliament","pronunciation":"/ˈpɑːləmənt/","meaning":"n.议会，国会","seq":7,"isStar":false,"memo":"联想 parlia(音似“怕了”) + -ment(名词后缀) → “国会”是该国最大的权力机构，有些人看到就怕了。","example":"The issue was debated in Parliament. 议会就这个问题进行了辩论。"},{"id":8,"unit":1,"lesson":1,"word":"parliamentary","pronunciation":"/ˌpɑːləˈmentri/","meaning":"adj.议会的，国会的","seq":8,"isStar":false},{"id":9,"unit":1,"lesson":1,"word":"ambassador","pronunciation":"/æmˈbæsədə(r)/","meaning":"n.大使,使节;代表","seq":9,"isStar":false,"memo":"对照 embassy n.大使馆 → ambassador n.大使，使节","example":"The ambassador refused all interviews. 该大使拒绝了所有的采访。"},{"id":10,"unit":1,"lesson":1,"word":"conquer","pronunciation":"/ˈkɒŋkə(r)/","meaning":"v.战胜，征服;攻克","seq":10,"isStar":false,"memo":"联想 con-(所有) + quer(音似“克”) → 他攻克了所有的困难 → 战胜，征服","example":"The only way to conquer a fear is to face it. 战胜恐惧的唯一方法是正视恐惧。"},{"id":11,"unit":1,"lesson":1,"word":"conquest","pronunciation":"/ˈkɒŋkwest/","meaning":"n.征服;占领;占领的地区","seq":11,"isStar":false},{"id":12,"unit":1,"lesson":1,"word":"conqueror","pronunciation":"/ˈkɒŋkərə(r)/","meaning":"n.征服者;占领者;胜利者","seq":12,"isStar":false},{"id":13,"unit":1,"lesson":1,"word":"eminent","pronunciation":"/ˈemɪnənt/","meaning":"adj.杰出的，有名的;明显的","seq":13,"isStar":false,"memo":"联想 e-(出去)+min(联想“敏”,人名)+ent(联想enter)→敏外出打工,进入城市待了几年,变化是很“明显的”。","example":"His description even fits the views of the majority of eminent scholars.他的描述甚至符合大多数杰出学者的观点。"},{"id":14,"unit":1,"lesson":1,"word":"eminence","pronunciation":"/ˈemɪnəns/","meaning":"n.卓越，著名","seq":14,"isStar":false},{"id":15,"unit":1,"lesson":1,"word":"prominent","pronunciation":"/ˈprɒmɪnənt/","meaning":"adj.突出的;卓越的，著名的;重要的","seq":15,"isStar":false,"memo":"联想 pro-(提前) + minent(联想 eminent)→提前变得杰出的→突出的","example":"He played a prominent part in the campaign. 他在这次运动中发挥了重要作用。"},{"id":16,"unit":1,"lesson":1,"word":"prominence","pronunciation":"/ˈprɒmɪnəns/","meaning":"n.重要;突出;卓越，出名","seq":16,"isStar":false},{"id":17,"unit":1,"lesson":1,"word":"outstanding","pronunciation":"/aʊtˈstændɪŋ/","meaning":"adj.杰出的;突出的;重要的","seq":17,"isStar":false,"memo":"构词 out(向外) + stand(站) + -ing(形容词后缀)→站出来的→突出的","example":"He is an outstanding speaker. 他是一位杰出的演说家。"},{"id":18,"unit":1,"lesson":1,"word":"remark","pronunciation":"/rɪˈmɑːk/","meaning":"n.言论;评论 v.谈到;评论","seq":18,"isStar":false,"memo":"构词 re-(重复) + mark(标记)→重复标记→谈到;评论","example":"How does the woman feel about his remarks? 这位女士对他的言论有什么感想?"},{"id":19,"unit":1,"lesson":1,"word":"remarkable","pronunciation":"/rɪˈmɑːkəb(ə)l/","meaning":"adj.显著的;非凡的","seq":19,"isStar":false,"memo":"构词+联想：re-（再）+mark（标记）+able→值得你‘再标记一遍’的亮点！就像朋友圈刷到神级笔记，必须双击+截图+转发。","example":"The research team achieved a remarkable breakthrough in renewable battery technology. 研究团队在可充电电池技术领域取得了非凡的突破。"},{"id":20,"unit":1,"lesson":1,"word":"comment","pronunciation":"/ˈkɒment/","meaning":"n.评论;批评 v.评论;表达意见","seq":20,"isStar":false,"memo":"联想 com-(共同) + men(人) + t(联想“他”)→所有人共同“评论”他。","example":"There was a lot of comment about his behaviour. 对他的行为举止有很多的指责。"},{"id":21,"unit":1,"lesson":1,"word":"commentary","pronunciation":"/ˈkɒmənt(ə)ri/","meaning":"n.现场解说，实况报道;评注;批评","seq":21,"isStar":false,"memo":"构词 comment(评论) + -ary(名词后缀)→评注","example":"I can't hear the football commentary. 我听不到足球比赛的现场解说。"},{"id":22,"unit":1,"lesson":1,"word":"commentator","pronunciation":"/ˈkɒmənteɪtə(r)/","meaning":"n.评论员;实况解说员","seq":22,"isStar":false,"memo":"构词 comment(评论)+-ator(表示人的后缀)→评论员","example":"Some commentators were quick to raise this problem.一些评论员很快提出了这个问题。"},{"id":23,"unit":1,"lesson":1,"word":"brilliant","pronunciation":"/ˈbrɪliənt/","meaning":"adj.明亮的;巧妙的;聪颖的","seq":23,"isStar":false,"memo":"联想 bri（联想 bright）+ (l) lian（联想“脸”）+ t(联想“他”)→他的脸很亮→明亮的","example":"She had no patience for brilliant but irrelevant figures of speech. 她对那些巧妙但无关紧要的修辞手法没有耐心。"},{"id":24,"unit":1,"lesson":1,"word":"brilliance","pronunciation":"/ˈbrɪliəns/","meaning":"n.才华;光彩","seq":24,"isStar":false},{"id":25,"unit":1,"lesson":1,"word":"fabulous","pronunciation":"/ˈfæbjələs/","meaning":"adj.极好的，绝妙的;巨大的","seq":25,"isStar":false,"memo":"谐音 单词发音类似“发布乐死”→那个歌手发布了反响“极好的”专辑,他极为高兴。","example":"I could not have imagined how fabulous a real Chinese banquet could be.我无法想象一场正宗的中国宴会有多么精彩。"},{"id":26,"unit":1,"lesson":1,"word":"terrific","pronunciation":"/təˈrɪfɪk/","meaning":"adj.极好的;了不起的;巨大的","seq":26,"isStar":false,"memo":"联想 ter(音似“特”)+ ri(联想“日”)+ fic (音似“非可”)→特别的日子里非提不可的事,一定是“极好的”事。\n对照 没有可怕的(terrible)事情发生就是极好的(terrific)。","example":"I've got a terrific amount of work to do. 我有大量的工作要做。"},{"id":27,"unit":1,"lesson":1,"word":"grand","pronunciation":"/ɡrænd/","meaning":"adj.壮丽的，堂皇的;宏大的;极好的","seq":27,"isStar":false,"memo":"联想 联想 grandfather 和 grandmother→祖父母比父母的辈分大→宏大的;极好的","example":"She attended the supermarket's grand opening ceremony. 她参加了超市盛大的开业典礼。"},{"id":28,"unit":1,"lesson":1,"word":"magnificent","pronunciation":"/mæɡˈnɪfɪs(ə)nt/","meaning":"adj.壮丽的，宏伟的","seq":28,"isStar":false,"memo":"联想 ma(联想“妈”)+ g(联想“哥”)+ ni (联想“你”)+ ficent(音似“飞身”)→妈妈、哥哥和你等一家人观看空中飞人表演,场面很壮观→壮丽的,宏伟的","example":"They praised the magnificent architecture of the Imperial Palace. 他们称赞故宫的宏伟建筑。"},{"id":29,"unit":1,"lesson":1,"word":"magnitude","pronunciation":"/ˈmæɡnɪtjuːd/","meaning":"n.重大，重要性","seq":29,"isStar":false,"memo":"对照 壮丽的(magnificent)场面体现了文化传承的重要性(magnitude)。","example":"They didn't seem to appreciate the magnitude of the problem. 他们似乎没有意识到这个问题的重要性。"},{"id":30,"unit":1,"lesson":1,"word":"magnify","pronunciation":"/ˈmæɡnɪfaɪ/","meaning":"v.放大，扩大;增强;夸大","seq":30,"isStar":false,"memo":"构词 magn(大，同 magnitude 巨大)+-ify(使…化)→使变大→放大，扩大；增强","example":"The microscope can magnify the object 100 times in diameter. 这台显微镜能把物体的直径放大 100 倍。"},{"id":31,"unit":1,"lesson":1,"word":"exception","pronunciation":"/ɪkˈsepʃ(ə)n/","meaning":"n.例外","seq":31,"isStar":false,"memo":"构词 ex-(向外)+cept(拿，同 capture 抓取)+-ion(名词后缀)→被单独拿出来的那一个→例外","example":"Nobody had much money at the time and I was no exception. 那时候谁都没有很多钱,我也不例外。"},{"id":32,"unit":1,"lesson":1,"word":"exceptional","pronunciation":"/ɪkˈsepʃən(ə)l/","meaning":"adj.杰出的;不寻常的，罕见的;特别的","seq":32,"isStar":false,"memo":"构词 exception(例外)+ -al(形容词后缀)→例外的→杰出的;不寻常的","example":"Capital punishment is allowable only under exceptional circumstances. 只有在特殊情况下才允许判死刑。"},{"id":33,"unit":1,"lesson":1,"word":"exemplary","pronunciation":"/ɪɡˈzempləri/","meaning":"adj.典范的，可作楷模的","seq":33,"isStar":false,"memo":"构词 exempl(例子，即 example 的词干)+-ary(形容词后缀)→能当例子用的→典范的，可作楷模的","example":"She is exemplary of the new generation of film-makers.她是新一代电影制作人的典范。"},{"id":34,"unit":1,"lesson":1,"word":"exemplify","pronunciation":"/ɪɡˈzemplɪfaɪ/","meaning":"v.举例说明;是……的典范/榜样","seq":34,"isStar":false},{"id":35,"unit":1,"lesson":1,"word":"instance","pronunciation":"/ˈɪnstəns/","meaning":"n.例子，事例 v.举……为例","seq":35,"isStar":false,"memo":"谐音：单词发音类似“因事谈事”→我们要就事论事，举“例子”谈事。","example":"The creative aspects of advertisement, for instance, often cover up the defects in products. 例如，广告的创意往往掩盖了产品的缺陷。"},{"id":36,"unit":1,"lesson":1,"word":"tremendous","pronunciation":"/trəˈmendəs/","meaning":"adj.巨大的，极大的;极好的","seq":36,"isStar":false,"memo":"联想：tre(联想 tree) + men(联想“门”) + dou(联想“都”) + s(联想“死”) → 门前两棵树都死了，这给她造成了“极大的”心理伤害。","example":"One of humans’ key characteristics is tremendous linguistic and cognitive diversity. 人类的一个重要特征是庞大的语言和认知多样性。"},{"id":37,"unit":1,"lesson":1,"word":"coordinate","pronunciation":"/kəʊˈɔːdɪneɪt/","meaning":"n.坐标;套装 v.使协调;使相配合","seq":37,"isStar":false,"memo":"对照：普通的(ordinary)我们需要努力协调(coordinate)自己的心态。","example":"Goal-setting does help coordinate and motivate people. 设定目标确实有助于协调和激励人们。"},{"id":38,"unit":1,"lesson":1,"word":"coordination","pronunciation":"/kəʊˌɔːdɪˈneɪʃ(ə)n/","meaning":"n.协作;协调;配合","seq":38,"isStar":false},{"id":39,"unit":1,"lesson":1,"word":"coordinator","pronunciation":"/kəʊˈɔːdɪneɪtə(r)/","meaning":"n.协调者","seq":39,"isStar":false},{"id":40,"unit":1,"lesson":1,"word":"subordinate","pronunciation":"/səˈbɔːdɪnət/","meaning":"n.下属 adj.下级的","seq":40,"isStar":false,"memo":"联想：sub-(在……下面) + ordinate(联想 ordinary)→在一般的下面→下级的；次要的","example":"He had been under attack for shifting responsibility to his subordinates. 他因将责任推卸给下属而受到抨击。"},{"id":41,"unit":1,"lesson":1,"word":"subordination","pronunciation":"/səˌbɔːdɪˈneɪʃn/","meaning":"n.附属;从属","seq":41,"isStar":false},{"id":42,"unit":1,"lesson":1,"word":"commonplace","pronunciation":"/ˈkɒmənpleɪs/","meaning":"n.常见的事，平常的事","seq":42,"isStar":false,"memo":"构词：common(普通的) + place(地方) → 常见的事；普通的","example":"Such actions were regarded as commonplace during the war. 这样的行为被认为是战争期间常见的事。"},{"id":43,"unit":1,"lesson":2,"word":"surface","pronunciation":"/ˈsɜːfɪs/","meaning":"n.表面 v.升到水面;显露，暴露","seq":1,"isStar":false,"memo":"构词 sur-(上面)+face(脸,面)→表面","example":"The chance of these bacteria being on most surfaces is very low. 这些细菌出现在大多数物体表面的概率非常低。"},{"id":44,"unit":1,"lesson":2,"word":"surf","pronunciation":"/sɜːf/","meaning":"v.冲浪;漫游 n.激浪","seq":2,"isStar":false,"memo":"联想 与 surface(表面)同源：在海水表面(surface)上滑行→冲浪；在网上四处滑动即“漫游”","example":"They surf, ski and ride.他们冲浪、滑雪和骑车。"},{"id":45,"unit":1,"lesson":2,"word":"surfing","pronunciation":"/ˈsɜːfɪŋ/","meaning":"n.冲浪运动;(互联网上)冲浪","seq":3,"isStar":false},{"id":46,"unit":1,"lesson":2,"word":"surplus","pronunciation":"/ˈsɜːpləs/","meaning":"n.剩余，过剩 adj.过剩的，剩余的","seq":4,"isStar":false,"memo":"联想 sur(音似“蛇”)+p(联想“扑”)+lu(联想“鹿”)+s(联想“死”)→蛇扑向一头鹿并把它咬死了,吃了很久还有“剩余”。","example":"If you have surplus vegetables, you'll do a vegetable soup. 如果你有剩余的蔬菜,你可以做蔬菜汤。"},{"id":47,"unit":1,"lesson":2,"word":"surpass","pronunciation":"/səˈpɑːs/","meaning":"v.超过;胜过，优于","seq":5,"isStar":false,"memo":"构词 sur-(上面)+pass(通过)→从上面通过→超过;胜过","example":"No physicist is likely to surpass Einstein in the next 100 years. 在未来的100年里,没有物理学家能够超过爱因斯坦。"},{"id":48,"unit":1,"lesson":2,"word":"transcend","pronunciation":"/trænˈsend/","meaning":"v.超出，超越","seq":6,"isStar":false,"memo":"联想 trans-(从……到……)+ce(=cess,走)+nd→他走南闯北,能力“超越”了许多人。","example":"The film transcends national and cultural barriers. 这部电影超越国家和文化界限。"},{"id":49,"unit":1,"lesson":2,"word":"precede","pronunciation":"/prɪˈsiːd/","meaning":"v.先于，在……前面","seq":7,"isStar":false,"memo":"联想 pre-(在前)+ce(走)+de→先于,在……前面","example":"He was preceded in birth by one sister. 他有一个先于他出生的姐姐。 preceding /prɪˈsiːdɪŋ/ adj.在先的,前面的"},{"id":50,"unit":1,"lesson":2,"word":"preceding","pronunciation":"/prɪˈsiːdɪŋ/","meaning":"adj.在先的，前面的","seq":8,"isStar":false},{"id":51,"unit":1,"lesson":2,"word":"precedent","pronunciation":"/ˈpresɪdənt/","meaning":"n.前例，先例;惯例","seq":9,"isStar":false,"memo":"联想 pre-(在前)+ce(走)+d+-ent(名词后缀)→走在前面的就是“先例”。","example":"The achievements of this period were without precedent in history.这一时期的成就在历史上是史无前例的。"},{"id":52,"unit":1,"lesson":2,"word":"unprecedented","pronunciation":"/ʌnˈpresɪdentɪd/","meaning":"adj.前所未有的，空前的","seq":10,"isStar":false,"memo":"[构词] un-(否定前缀) + precedent(先例) + -ed(形容词后缀)→前所未有的,空前的","example":"It will face challenges unprecedented in its history. 它将面临历史上前所未有的挑战。"},{"id":53,"unit":1,"lesson":2,"word":"predecessor","pronunciation":"/ˈpriːdəsesə(r)/","meaning":"n.前任，前辈;前身，原先的东西","seq":11,"isStar":false,"memo":"[联想] pre-(在前) + de(联想“的”) + cess(走) + -or(表示人的后缀)→在前面走的人→前任,前辈","example":"He is sure to surpass the achievements of his predecessor. 他的成就一定会超过他的前辈。"},{"id":54,"unit":1,"lesson":2,"word":"concede","pronunciation":"/kənˈsiːd/","meaning":"v.承认;让步","seq":12,"isStar":false,"memo":"[联想] con-(都) + ce(走) + de→都走开,退让→让步","example":"He concedes his research runs counter to a very large body of literature. 他承认他的研究与大量文献背道而驰。"},{"id":55,"unit":1,"lesson":2,"word":"concession","pronunciation":"/kənˈseʃ(ə)n/","meaning":"n.承认，许可;让步，妥协","seq":13,"isStar":false},{"id":56,"unit":1,"lesson":2,"word":"succeed","pronunciation":"/səkˈsiːd/","meaning":"v.成功，有成就;达到目的，实现目标","seq":14,"isStar":false,"memo":"[联想] suc-(在下) + ce(走) + ed→从下往上走→成功","example":"You will have to work hard if you are to succeed. 要想有成就,你必须苦干。"},{"id":57,"unit":1,"lesson":2,"word":"successor","pronunciation":"/səkˈsesə(r)/","meaning":"n.继承者，接任者;接替的事物","seq":15,"isStar":false,"memo":"[联想] success(成功) + -or(表示人的后缀)→成功继承王位的人就是“继承者”。","example":"The program has just come to an end, with no successor. 这个计划刚结束,没有接替的计划。"},{"id":58,"unit":1,"lesson":2,"word":"succession","pronunciation":"/səkˈseʃ(ə)n/","meaning":"n.连续的人(或事物);一连串，一系列","seq":16,"isStar":false,"memo":"[联想] success(成功) + -ion(名词后缀)→成功无法“继任”,努力才有明天。","example":"For the next ten years a succession of books sounded the alarm. 在接下来的十年里,一系列书籍敲响了警钟。"},{"id":59,"unit":1,"lesson":2,"word":"successive","pronunciation":"/səkˈsesɪv/","meaning":"adj.连接的，连续的","seq":17,"isStar":false,"memo":"success（成功）+ -ive → 连续成功？不！是‘接二连三’像赶ddl：周一交报告、周二做pre、周三考小测…","example":"The team won three successive championships. 该队连续三次夺得冠军。"},{"id":60,"unit":1,"lesson":2,"word":"exceed","pronunciation":"/ɪkˈsiːd/","meaning":"v.超过(数目或数量)","seq":18,"isStar":false,"memo":"[联想] ex-(往外) + ce(走) + ed→往外走→青出于蓝而胜于蓝→超过","example":"In China, the household-savings rate exceeds 20%. 在中国,家庭储蓄率超过20%。"},{"id":61,"unit":1,"lesson":2,"word":"exceedingly","pronunciation":"/ɪkˈsiːdɪŋli/","meaning":"adv.极其，非常","seq":19,"isStar":false,"memo":"[构词] exceed(超过) + -ing(形容词后缀) + -ly(副词后缀)→超过地→极其,非常","example":"The task proved to be exceedingly difficult, requiring all our skills and patience. 这项任务极其艰巨,需要我们所有的技能和耐心。"},{"id":62,"unit":1,"lesson":2,"word":"excess","pronunciation":"/ɪkˈses/","meaning":"n.超过;过度，过分 adj.过分的","seq":20,"isStar":false,"memo":"[联想] ex-(往外) + cess(走)→因为他的“过度”消费,他口袋里的钱都往外走了。","example":"These diseases have much to do with excess weight. 这些疾病与超重有很大关系。"},{"id":63,"unit":1,"lesson":2,"word":"excessive","pronunciation":"/ɪkˈsesɪv; ekˈsesɪv/","meaning":"adj.过多的，过度的","seq":21,"isStar":false,"memo":"[构词] excess(过度) + -ive(形容词后缀)→过多的,过度的","example":"In this city, the excessive rain comes at early spring. 在该市,早春时节雨水过多。"},{"id":64,"unit":1,"lesson":2,"word":"recede","pronunciation":"/rɪˈsiːd/","meaning":"v.逐渐远去;逐渐减弱;消退","seq":22,"isStar":false,"memo":"联想 re-(回)+ce(走)+de→他转身往回走,焦虑渐渐“消退”。","example":"Currently, the Dead Sea recedes each year.目前，死海每年都在后退。"},{"id":65,"unit":1,"lesson":2,"word":"recession","pronunciation":"/rɪˈseʃ(ə)n/","meaning":"n.经济衰退;退后","seq":23,"isStar":false,"memo":"【构词】re-（回）+ cess-（走）+ -ion → ‘往回走’→经济倒退→衰退；谐音‘瑞信崩’——瑞信一崩，全球 recession！","example":"Many startups struggled to survive during the recent economic recession. 许多初创企业在最近的经济衰退中艰难求生。"},{"id":66,"unit":1,"lesson":2,"word":"proceed","pronunciation":"/prəˈsiːd/","meaning":"v.继续做(或从事、进行);前进","seq":24,"isStar":false,"memo":"[构词] pro-(往前)+ceed(走)→前进","example":"Out of 20 such requests, six customers proceeded with the purchase. 在20个这样的请求中,有六个客户继续购买。"},{"id":67,"unit":1,"lesson":2,"word":"proceeding","pronunciation":"/prəˈsiːdɪŋ/","meaning":"n.事件;诉讼","seq":25,"isStar":false},{"id":68,"unit":1,"lesson":2,"word":"procession","pronunciation":"/prəˈseʃ(ə)n/","meaning":"n.队列;列队行进","seq":26,"isStar":false,"memo":"[构词] process(列队行进)+-ion(名词后缀)→队列;列队行进","example":"The procession passed right by my front door. 队伍正好从我家门前经过。"},{"id":69,"unit":1,"lesson":2,"word":"procedure","pronunciation":"/prəˈsiːdʒə(r)/","meaning":"n.(正常)程序，步骤;手术","seq":27,"isStar":false,"memo":"[联想] proced(联想 proceed)+-ure(名词后缀)→他前进的每一步都按“程序”进行。","example":"The next day I repeated the procedure. 第二天我重复了这个步骤。"},{"id":70,"unit":1,"lesson":2,"word":"ancestor","pronunciation":"/ˈænsestə(r)/","meaning":"n.祖先;原始种型;原型","seq":28,"isStar":false,"memo":"[联想] an-(一个)+cest(走)+-or(表示人的后缀)→一个走在前面的人→祖先","example":"They call out their ancestors' names. 他们喊出他们祖先的名字。"},{"id":71,"unit":1,"lesson":2,"word":"ancestry","pronunciation":"/ˈænsestri/","meaning":"n.祖宗，祖先","seq":29,"isStar":false},{"id":72,"unit":1,"lesson":2,"word":"access","pronunciation":"/ˈækses/","meaning":"n.进入权;使用权;人口，通道","seq":30,"isStar":false,"memo":"[联想] ac-(一再地)+cess(走)→他一再地走进去→进入","example":"They will be denied access to confidential records. 他们将无权获取机密档案。"},{"id":73,"unit":1,"lesson":2,"word":"accessible","pronunciation":"/əkˈsesəb(ə)l/","meaning":"adj.易达到的;易进入的;易使用的","seq":31,"isStar":false,"memo":"构词 access(进入;使用)+-ible(形容词后缀)→易进入的;易使用的","example":"E-books are more accessible to readers.电子书对读者来说更容易获得。"},{"id":74,"unit":1,"lesson":2,"word":"accessory","pronunciation":"/əkˈsesəri/","meaning":"n.附件，附属品;配件;同谋","seq":32,"isStar":false,"memo":"构词 ac-(加强)+cess(走，同 access 进入)+-ory(名词后缀)→跟着主体一起走来的附带物→附件，配件；同谋","example":"We stock a large range of bicycle accessories. 我们贮存了各类自行车配件。"},{"id":75,"unit":1,"lesson":2,"word":"ascend","pronunciation":"/əˈsend/","meaning":"v.上升;登上;晋升","seq":33,"isStar":false,"memo":"[联想] as-(一再地)+ce(走)+nd→一再地朝上走→上升","example":"Colorful balloons ascended slowly into the sky. 五颜六色的气球慢慢升上天空。"},{"id":76,"unit":1,"lesson":2,"word":"ascendancy","pronunciation":"/əˈsendənsi/","meaning":"n.优势;支配地位","seq":34,"isStar":false},{"id":77,"unit":1,"lesson":2,"word":"soar","pronunciation":"/sɔː(r)/","meaning":"v.急升，猛增;高飞","seq":35,"isStar":false,"memo":"[谐音] 单词发音类似“嗖”→烟花“嗖”的一声飞上天→急升;高飞","example":"The prices of imported goods will soar. 进口商品的价格将飙升。"},{"id":78,"unit":1,"lesson":2,"word":"surge","pronunciation":"/sɜːdʒ/","meaning":"n.&v.急剧上升;激增","seq":36,"isStar":false,"memo":"[联想] sur-(上面)+ge(联想“哥”)→当你成功时,哥哥对你的赞美次数会“激增”。","example":"Unemployment rate has surged in every occupational category. 失业率在各工种中急剧上升。"},{"id":79,"unit":1,"lesson":2,"word":"stable","pronunciation":"/ˈsteɪb(ə)l/","meaning":"adj.稳定的，稳固的 n.马厩","seq":37,"isStar":false,"memo":"[联想] s(联想“似”)+table(桌子)→它的结构似桌子一样稳定→稳定的,稳固的","example":"The current conditions were set fair for stable economic development. 现状适合经济稳定发展。"},{"id":80,"unit":1,"lesson":2,"word":"stabilise/-ize","pronunciation":"/ˈsteɪbəlaɪz/","meaning":"v.(使)稳定，稳固","seq":38,"isStar":false,"memo":"构词 stabil(稳定，同 stable)+-ise/-ize(使…化)→使稳下来→(使)稳定，稳固","example":"The government acted quickly to stabilise prices. 政府迅速采取行动稳定物价。"},{"id":81,"unit":1,"lesson":2,"word":"stability","pronunciation":"/stəˈbɪləti/","meaning":"n.稳定(性);稳固(性)","seq":39,"isStar":false},{"id":82,"unit":1,"lesson":2,"word":"descend","pronunciation":"/dɪˈsend/","meaning":"v.下降，下来;下斜;降临","seq":40,"isStar":false,"memo":"[联想] de-(往下)+s+ce(走)+nd→下降","example":"She descended the stairs slowly. 她缓慢地走下楼梯。"},{"id":83,"unit":1,"lesson":2,"word":"descent","pronunciation":"/dɪˈsent/","meaning":"n.下降，降落;降下;斜坡;出身","seq":41,"isStar":false,"memo":"[联想] de-(往下)+scent(音同 sent)→往下发送→下降,降落","example":"The plane began its descent to Heathrow. 飞机开始向希思罗机场降落。"},{"id":84,"unit":1,"lesson":2,"word":"descendant","pronunciation":"/dɪˈsendənt/","meaning":"n.后代","seq":42,"isStar":false,"memo":"[构词] descend(下降;降临)+-ant(表示人的后缀)→接下来的人或即将来临的人→后代","example":"Our descendants might at last live in a world at peace with itself. 我们的后代可能最终生活在一个和平相处的世界里。"},{"id":85,"unit":1,"lesson":2,"word":"offspring","pronunciation":"/ˈɒfsprɪŋ/","meaning":"n.子女;后代;幼崽","seq":43,"isStar":false,"memo":"构词 off(离开)+spring(生长、泉源)→从父母身上长出来又离开的→子女，后代","example":"His offspring are diligent and intelligent. 他的后代既勤奋又聪明。"},{"id":86,"unit":1,"lesson":2,"word":"inherit","pronunciation":"/ɪnˈherɪt/","meaning":"v.继承(遗产);经遗传获得;接替，继任","seq":44,"isStar":false,"memo":"构词 in-(进入)+herit(继承，同 heritage 遗产)→把遗产接进自己手里→继承；经遗传获得","example":"He has inherited his mother's patience. 他继承了他母亲的耐心。"},{"id":87,"unit":1,"lesson":2,"word":"inheritance","pronunciation":"/ɪnˈherɪtəns/","meaning":"n.继承物;遗产;继承","seq":45,"isStar":false},{"id":88,"unit":1,"lesson":2,"word":"inherent","pronunciation":"/ɪnˈherənt/","meaning":"adj.内在的，固有的","seq":46,"isStar":false,"memo":"联想 inher(联想 inherit) + -ent(形容词后缀)→经遗传获得的→内在的,固有的","example":"Conflict is inherent in our society. 在我们的社会中冲突是难免的。"},{"id":89,"unit":1,"lesson":2,"word":"coherent","pronunciation":"/kəʊˈhɪərənt/","meaning":"adj.连贯的，一致的;有条理的","seq":47,"isStar":false,"memo":"联想 co-(共同) + her(e)(在这儿) + -ent(形容词后缀)→连贯的,一致的","example":"You're not being very coherent. 你的话前后不太一致。"},{"id":90,"unit":1,"lesson":2,"word":"coherence","pronunciation":"/kəʊˈhɪərəns/","meaning":"n.连贯性;条理性","seq":48,"isStar":false},{"id":91,"unit":1,"lesson":2,"word":"cohesion","pronunciation":"/kəʊˈhiːʒ(ə)n/","meaning":"n.黏合，结合;凝聚力","seq":49,"isStar":false,"memo":"联想 co-(共同)+hesion(音似“核心”)→大家共同以他为核心,紧密地“结合”在一起。","example":"The team's cohesion was built on mutual trust. 这个团队的凝聚力建立在相互信任之上。"},{"id":92,"unit":1,"lesson":2,"word":"cohesive","pronunciation":"/kəʊˈhiːsɪv/","meaning":"adj.使结合的;使凝结的;有凝聚力的","seq":50,"isStar":false,"memo":"构词 co-(共同)+hes(粘，同 adhesive 粘合的)+-ive(形容词后缀)→粘在一起的→有凝聚力的","example":"They are a remarkably cohesive group. 他们是一个非常有凝聚力的集体。"},{"id":93,"unit":1,"lesson":2,"word":"heir","pronunciation":"/eə(r)/","meaning":"n.继承人;后嗣","seq":51,"isStar":false,"memo":"谐音 单词发音类似“爱儿”→他很爱他的儿子,所以把儿子列为他财产的“继承人”。","example":"He is going to be heir to a large fortune. 他即将成为一大笔财产的继承人。"},{"id":94,"unit":1,"lesson":2,"word":"heiress","pronunciation":"/eəˈres; ˈeərəs/","meaning":"n.女继承人;嗣女","seq":52,"isStar":false},{"id":95,"unit":1,"lesson":2,"word":"heritage","pronunciation":"/ˈherɪtɪdʒ/","meaning":"n.遗产","seq":53,"isStar":false,"memo":"联想 her(她) + it(它) + age(年龄)→她到了一定年龄才能继承它,这是父母留给她的“遗产”。","example":"Everyone can be welcomed on Mauna Kea to embrace their cultural heritage. 欢迎每个人来到莫纳克亚山,拥抱他们的文化遗产。"},{"id":96,"unit":1,"lesson":2,"word":"legacy","pronunciation":"/ˈleɡəsi/","meaning":"n.遗产;遗留问题;后遗症","seq":54,"isStar":false,"memo":"谐音 单词发音类似“赖哥死”→赖哥死后留下了“遗产”。","example":"The invasion left a legacy of hatred and fear. 这次入侵留下的是仇恨和恐惧。"},{"id":97,"unit":1,"lesson":2,"word":"gene","pronunciation":"/dʒiːn/","meaning":"n.基因","seq":55,"isStar":false,"memo":"谐音 单词发音类似“基因”。","example":"Genes determine much of our physical appearance. 基因在很大程度上决定了我们的外貌。"},{"id":98,"unit":1,"lesson":2,"word":"genetic","pronunciation":"/dʒəˈnetɪk/","meaning":"adj.基因的;遗传学的","seq":56,"isStar":false,"memo":"构词 gene(基因)+-tic(形容词后缀)→与基因有关的→基因的，遗传学的","example":"The disease is caused by a genetic defect. 这种疾病是由基因缺陷引起的。"},{"id":99,"unit":1,"lesson":2,"word":"genetically","pronunciation":"/dʒəˈnetɪkli/","meaning":"adv.从遗传学角度;从基因方面","seq":57,"isStar":false},{"id":100,"unit":1,"lesson":2,"word":"genre","pronunciation":"/ˈʒɒnrə/","meaning":"n.体裁;类型","seq":58,"isStar":false,"memo":"记 (对照) 这两种小花的基因(gene)一样,属于同一种类型(genre)。","example":"Jazz is an incredibly rich genre.爵士乐是一种极其丰富的音乐类型。"},{"id":101,"unit":1,"lesson":2,"word":"generate","pronunciation":"/ˈdʒenəreɪt/","meaning":"v.产生;引起","seq":59,"isStar":false,"memo":"[联想] gene(基因) + rat(老鼠) + e → 老鼠的基因决定了其繁殖能力很强，这会“产生”一些问题。","example":"How is the field generated? 电场是如何产生的？"},{"id":102,"unit":1,"lesson":2,"word":"generator","pronunciation":"/ˈdʒenəreɪtə(r)/","meaning":"n.发电机;发生器","seq":60,"isStar":false},{"id":103,"unit":1,"lesson":2,"word":"homogeneous","pronunciation":"/ˌhɒməˈdʒiːniəs/","meaning":"adj.同种类的","seq":61,"isStar":false,"memo":"[联想] homo-(同一的) + gene(基因) + -ous (形容词后缀) → 同一基因的 → 同种类的","example":"Old people are not a homogeneous group. 老年人不都是同一类型的。"},{"id":104,"unit":1,"lesson":2,"word":"degenerate","pronunciation":"/dɪˈdʒenəreɪt/","meaning":"v.使退化;恶化","seq":62,"isStar":false,"memo":"[构词] de-(往下，偏离) + generate(产生) → 向下产生，偏离常态 → 使退化；恶化","example":"His health degenerated quickly. 他的健康状况迅速恶化。"},{"id":105,"unit":1,"lesson":2,"word":"degeneration","pronunciation":"/dɪˌdʒenəˈreɪʃn/","meaning":"n.蜕化;衰退;堕落","seq":63,"isStar":false},{"id":106,"unit":1,"lesson":2,"word":"deteriorate","pronunciation":"/dɪˈtɪəriəreɪt/","meaning":"v.恶化，退化","seq":64,"isStar":false,"memo":"[联想] de(联想“弟”) + teri(联想“特日”) + o(形似矿井口) + rate → 在这特殊的日子，弟弟想起矿井环境“恶化”前的景象。","example":"If he worked hard, his health would deteriorate. 如果他工作太辛苦，他的健康状况会恶化。"},{"id":107,"unit":1,"lesson":2,"word":"deterioration","pronunciation":"/dɪˌtɪəriəˈreɪʃ(ə)n/","meaning":"n.恶化","seq":65,"isStar":false},{"id":108,"unit":1,"lesson":3,"word":"terror","pronunciation":"/ˈterə(r)/","meaning":"n.惊恐，恐惧;恐怖活动","seq":1,"isStar":false,"memo":"[谐音] 单词发音类似“太弱”→如果一个国家太软弱，它就会对恐怖分子的“恐怖活动”感到“恐惧”。","example":"Her eyes were wild with terror. 她的眼睛里充满了恐惧。"},{"id":109,"unit":1,"lesson":3,"word":"terrorism","pronunciation":"/ˈterərɪzəm/","meaning":"n.恐怖主义","seq":2,"isStar":false},{"id":110,"unit":1,"lesson":3,"word":"terrorist","pronunciation":"/ˈterərɪst/","meaning":"n.恐怖分子","seq":3,"isStar":false},{"id":111,"unit":1,"lesson":3,"word":"terrify","pronunciation":"/ˈterɪfaɪ/","meaning":"v.使恐惧，使害怕","seq":4,"isStar":false,"memo":"[联想] terr(联想 terror) + -ify(动词后缀) →使恐惧,使害怕","example":"They could sometimes terrify adults. 它们有时会吓到成年人。"},{"id":112,"unit":1,"lesson":3,"word":"terrible","pronunciation":"/ˈterəb(ə)l/","meaning":"adj.可怕的;非常严重的","seq":5,"isStar":false},{"id":113,"unit":1,"lesson":3,"word":"terribly","pronunciation":"/ˈterəbli/","meaning":"adv.非常，很","seq":6,"isStar":false},{"id":114,"unit":1,"lesson":3,"word":"frighten","pronunciation":"/ˈfraɪt(ə)n/","meaning":"v.使惊吓，使惊恐","seq":7,"isStar":false,"memo":"[对照] 他打架(fight)时用花打人，只是为了使对方惊恐(frighten)。","example":"I didn't mean to frighten you. 我没有吓唬你的意思。"},{"id":115,"unit":1,"lesson":3,"word":"fright","pronunciation":"/fraɪt/","meaning":"n.惊吓;恐怖","seq":8,"isStar":false},{"id":116,"unit":1,"lesson":3,"word":"embody","pronunciation":"/ɪmˈbɒdi/","meaning":"v.具体表现，体现;代表;包含;收录","seq":9,"isStar":false,"memo":"[构词] em-(使) + body(身体)→赋予形体，使有形化→体现","example":"They embody the most sophisticated technology. 它们体现了最先进的技术。"},{"id":117,"unit":1,"lesson":3,"word":"embed","pronunciation":"/ɪmˈbed/","meaning":"v.把……牢牢地嵌入(或插入、埋入)","seq":10,"isStar":false,"memo":"[联想] em(音似“一木”) + bed(床)→他把一根木头牢牢地嵌入了床板→把……牢牢地嵌入","example":"Consumption has become a central pillar of life in industrial areas and is even embedded in social values. 消费已成为工业化地区生活的核心支柱，甚至已嵌入社会价值观之中。"},{"id":118,"unit":1,"lesson":3,"word":"scare","pronunciation":"/skeə(r)/","meaning":"n.恐慌，惊吓，惊恐 v.害怕;使惊恐","seq":11,"isStar":false,"memo":"联想 与 scar(伤疤)形近：受了惊吓(scare)容易留下伤疤(scar)→惊恐，害怕","example":"Don't you realise what a scare you've given us all? 难道你没有意识到你给我们所有人带来了多大的惊吓吗？"},{"id":119,"unit":1,"lesson":3,"word":"scary","pronunciation":"/ˈskeəri/","meaning":"adj.恐怖的，吓人的","seq":12,"isStar":false},{"id":120,"unit":1,"lesson":3,"word":"panic","pronunciation":"/ˈpænɪk/","meaning":"n.惊慌，恐慌 v.(使)恐慌","seq":13,"isStar":false,"memo":"[联想] pa(联想“怕”) + ni(联想“你”) + c (音似“磕”)→小时候，奶奶很怕你磕到→恐慌","example":"They were in a state of panic. 他们处于恐慌的状态中。"},{"id":121,"unit":1,"lesson":3,"word":"deter","pronunciation":"/dɪˈtɜː(r)/","meaning":"v.制止，阻止;威慑，使不敢","seq":14,"isStar":false,"memo":"谐音：单词发音类似“弟特”→弟弟特别淘气，总是做出格的事，我要及时“制止”他。","example":"Will this harsher punishment effectively deter criminals? 这种更严厉的惩罚能有效威慑罪犯吗？"},{"id":122,"unit":1,"lesson":3,"word":"deterrent","pronunciation":"/dɪˈterənt/","meaning":"n.威慑物 adj.威慑的;制止的","seq":15,"isStar":false},{"id":123,"unit":1,"lesson":3,"word":"alert","pronunciation":"/əˈlɜːt/","meaning":"n.警报;警戒，警惕 adj.警觉的","seq":16,"isStar":false,"memo":"联想：a(一个) + ler(音似“乐”) + t(联想“他”)→他是一个很“警惕的”人，少有快乐时光。","example":"There is a bomb alert on the rail link. 铁路线上有炸弹警报。"},{"id":124,"unit":1,"lesson":3,"word":"caution","pronunciation":"/ˈkɔːʃ(ə)n/","meaning":"n.小心，谨慎;警告 v.警告","seq":17,"isStar":false,"memo":"谐音：单词发音类似“靠心”→走路时要靠心，保持“谨慎”，以免摔倒。","example":"She got off with a caution. 她受到了警告。"},{"id":125,"unit":1,"lesson":3,"word":"cautious","pronunciation":"/ˈkɔːʃəs/","meaning":"adj.谨慎的，小心的","seq":18,"isStar":false},{"id":126,"unit":1,"lesson":3,"word":"precaution","pronunciation":"/prɪˈkɔːʃ(ə)n/","meaning":"n.预防措施，防备","seq":19,"isStar":false,"memo":"构词：pre-(提前) + caution(小心)→预防措施，防备","example":"I hope all the precautions against air pollution will be seriously considered. 我希望所有预防空气污染的措施都被认真考虑。"},{"id":127,"unit":1,"lesson":3,"word":"precautionary","pronunciation":"/prɪˈkɔːʃənəri/","meaning":"adj.预先警戒的;小心的","seq":20,"isStar":false},{"id":128,"unit":1,"lesson":3,"word":"rise","pronunciation":"/raɪz/","meaning":"n.上涨，增高 v.上升，增长;起身","seq":21,"isStar":false,"memo":"联想：ri(联想“日”) + se(联想“色”)→等太阳升起后，我们会在山顶上看到别样的景色→上升","example":"Everybody loves a fat pay rise. 人人都喜欢大幅涨薪。"},{"id":129,"unit":1,"lesson":3,"word":"arise","pronunciation":"/əˈraɪz/","meaning":"v.出现，产生;起身","seq":22,"isStar":false,"memo":"对照：后羿射日的故事中，十个太阳本应轮流上升(rise)到天空中，但是后来同时出现(arise)了。","example":"They arise from the advances in technology. 它们源于技术的进步。"},{"id":130,"unit":1,"lesson":3,"word":"arouse","pronunciation":"/əˈraʊz/","meaning":"v.唤醒;引起，激起","seq":23,"isStar":false,"memo":"联想：a-(一再地) + rouse(音似“热死”)→十个太阳同现后，一再地热死人，“引起”了大家的反感。","example":"His strange behaviour aroused our suspicions. 他奇怪的举动引起了我们的怀疑。"},{"id":131,"unit":1,"lesson":3,"word":"arousal","pronunciation":"/əˈraʊz(ə)l/","meaning":"n.激起，引起(感情、态度)","seq":24,"isStar":false,"memo":"构词 arouse(唤醒，激起)+-al(名词后缀)→被激起的那个状态→激起，唤起","example":"The drug can produce a state of arousal. 这种药物能使人进入兴奋状态。"},{"id":132,"unit":1,"lesson":3,"word":"raise","pronunciation":"/reɪz/","meaning":"v.提高，增加;举起;筹集;引起，导致","seq":25,"isStar":false,"memo":"[对照] 十个太阳同时出现(arise)在天空,后羿举起(raise)手表示要去射掉其中九个太阳。","example":"They have raised fund to improve the road condition. 他们已筹集资金来改善道路状况。"},{"id":133,"unit":1,"lesson":3,"word":"uprising","pronunciation":"/ˈʌpraɪzɪŋ/","meaning":"n.起义，暴动","seq":26,"isStar":false,"memo":"构词 up(向上)+rising(起身)→众人一起站起来反抗→起义，暴动","example":"The people of the country were staging an uprising against the corrupt government.该国人民正在举行起义反对腐败政府。"},{"id":134,"unit":1,"lesson":3,"word":"praise","pronunciation":"/preɪz/","meaning":"n.&v.称赞，赞美，表扬","seq":27,"isStar":false,"memo":"联想 与 prize(奖品)形近：先被表扬(praise)才拿得到奖(prize)→称赞，表扬","example":"She was praised for her hard work. 她因努力工作而受到表扬。"},{"id":135,"unit":1,"lesson":3,"word":"compliment","pronunciation":"/ˈkɒmplɪmənt/","meaning":"n.赞扬，称赞 v.赞扬，称赞","seq":28,"isStar":false,"memo":"[联想] com-(所有)+p(联想“扑”)+li(联想“立”)+men(联想“门”)+t→所有人扑向门口,“赞扬”打虎归来立在门口的武松。","example":"She received several compliments on her speech. 她的演讲得到了一些人的称赞。"},{"id":136,"unit":1,"lesson":3,"word":"complimentary","pronunciation":"/ˌkɒmplɪˈmentri/","meaning":"adj.表示钦佩的;赞美的","seq":29,"isStar":false},{"id":137,"unit":1,"lesson":3,"word":"appraise","pronunciation":"/əˈpreɪz/","meaning":"v.估量;评估;估价;作出评价","seq":30,"isStar":false,"memo":"[构词] ap-(去)+prais(价格,价值)+-e→去给出价格→评估;估价","example":"He stepped back to appraise his workmanship. 他后退一步,评估自己的手艺。"},{"id":138,"unit":1,"lesson":3,"word":"appraisal","pronunciation":"/əˈpreɪz(ə)l/","meaning":"n.评价;估价","seq":31,"isStar":false},{"id":139,"unit":1,"lesson":3,"word":"prize","pronunciation":"/praɪz/","meaning":"n.奖品，奖赏 v.珍视，高度重视","seq":32,"isStar":false,"memo":"联想 与 praise(表扬)形近音近：表扬(praise)到位了才有奖(prize)→奖品；珍视","example":"She won the 1945 Nobel Prize in Literature. 她获得了1945年的诺贝尔文学奖。"},{"id":140,"unit":1,"lesson":3,"word":"comprise","pronunciation":"/kəmˈpraɪz/","meaning":"v.包括，包含;由……组成","seq":33,"isStar":false,"memo":"[联想] com-(一起)+prise(音同 prize)→“包括”我在内,全班同学都得到了奖品。","example":"The main labor force is comprised of students working part-time. 主要劳动力是由兼职工作的学生组成的。"},{"id":141,"unit":1,"lesson":3,"word":"award","pronunciation":"/əˈwɔːd/","meaning":"n.奖品;奖金 v.授予;给予奖励","seq":34,"isStar":false,"memo":"[谐音] 单词发音类似“a word”→快要下课了,老师多讲了一个表示“奖品”的单词。","example":"You could apply for an award if you have a patent. 如果你有一项专利,你就可以申请一笔奖金。"},{"id":142,"unit":1,"lesson":3,"word":"reward","pronunciation":"/rɪˈwɔːd/","meaning":"n.奖励;回报;报酬 v.奖赏;给以报酬","seq":35,"isStar":false,"memo":"[联想] re-(回)+ward(音似 word)→作为“回报”,学生也给老师讲了个单词。","example":"Rewards can improve performance at work and school. 奖励可以改进工作和学校的表现。"},{"id":143,"unit":1,"lesson":3,"word":"rewarding","pronunciation":"/rɪˈwɔːdɪŋ/","meaning":"adj.值得的;有益的","seq":36,"isStar":false},{"id":144,"unit":1,"lesson":3,"word":"ward","pronunciation":"/wɔːd/","meaning":"n.病房 v.防止，避免","seq":37,"isStar":false,"memo":"[对照] 战争(war)中的医院会设置很多病房(ward)。","example":"We have one bed available in Ward 3. 我们3号病房还有一张空床。"},{"id":145,"unit":1,"lesson":3,"word":"trophy","pronunciation":"/ˈtrəʊfi/","meaning":"n.奖品;奖杯;战利品","seq":38,"isStar":false,"memo":"记 (谐音) 单词发音类似“除非”→他小时候不愿意做家务,除非妈妈能给个“奖品”。","example":"He captured virtually every major skiing trophy.他几乎赢得了每一项重要的滑雪奖杯。"},{"id":146,"unit":1,"lesson":3,"word":"catastrophe","pronunciation":"/kəˈtæstrəfi/","meaning":"n.灾难，灾祸;困难","seq":39,"isStar":false,"memo":"联想 cat(猫) + as + trophe(联想 trophy)→“灾难”过后,这只猫因为救了同类而得到了奖品。","example":"It is a psychological catastrophe. 这是一场心理灾难。"},{"id":147,"unit":1,"lesson":3,"word":"catastrophic","pronunciation":"/ˌkætəˈstrɒfɪk/","meaning":"adj.灾难性的","seq":40,"isStar":false},{"id":148,"unit":1,"lesson":3,"word":"applaud","pronunciation":"/əˈplɔːd/","meaning":"v.称赞;鼓掌，拍手喝彩","seq":41,"isStar":false,"memo":"联想 ap-(一再地) + p(联想“扑”) + laud (音似“老的”)→小狮子一再地扑向大老虎,大家都为它的勇敢“鼓掌”。","example":"For the first time, my father applauded my hard work. 我父亲第一次称赞我的努力工作。"},{"id":149,"unit":1,"lesson":3,"word":"applause","pronunciation":"/əˈplɔːz/","meaning":"n.掌声;喝彩","seq":42,"isStar":false},{"id":150,"unit":1,"lesson":3,"word":"celebrate","pronunciation":"/ˈselɪbreɪt/","meaning":"v.庆祝，庆贺;赞美，颂扬","seq":43,"isStar":false,"memo":"联想 cele(音似“赛了”) + br(联想“必然”) + ate(cat 的过去式)→比赛完了必然要吃一顿,“庆祝”一下。","example":"Women's progress can be celebrated across a range of fields. 女性在各个领域取得的进步都值得庆祝。"},{"id":151,"unit":1,"lesson":3,"word":"celebration","pronunciation":"/ˌselɪˈbreɪʃn/","meaning":"n.庆典;庆祝活动","seq":44,"isStar":false,"memo":"构词 celebr(庆祝，同 celebrate)+-ation(名词后缀)→庆祝的场合→庆典，庆祝活动","example":"The whole city held a big celebration for the festival. 全市为这个节日举行了盛大的庆祝活动。"},{"id":152,"unit":1,"lesson":3,"word":"celebrity","pronunciation":"/səˈlebrəti/","meaning":"n.名人，名流;名望，名誉;著名","seq":45,"isStar":false,"memo":"构词 celebr(著名)+-ity(名词后缀)→很有名的人→名人，名流；名望","example":"His particular brand of celebrity is not a good fit for the values of a university.他那种特有的名人效应并不符合大学的价值观。"},{"id":153,"unit":1,"lesson":3,"word":"ceremony","pronunciation":"/ˈserəməni/","meaning":"n.仪式，典礼","seq":46,"isStar":false,"memo":"谐音 单词发音类似“赛罗蒙你”→赛罗说为你举行一个“典礼”,结果蒙(骗)了你。","example":"Many people attended the ceremony. 很多人出席了该仪式。"},{"id":154,"unit":1,"lesson":3,"word":"ceremonial","pronunciation":"/ˌserɪˈməʊniəl/","meaning":"adj.礼仪的;礼节的","seq":47,"isStar":false},{"id":155,"unit":1,"lesson":3,"word":"ritual","pronunciation":"/ˈrɪtʃuəl/","meaning":"n.仪式，仪规，礼节;习惯","seq":48,"isStar":false,"memo":"谐音 单词发音类似“瑞秋”→瑞秋在举行“仪式”。","example":"She objects to the ritual of organised religion. 她反对有组织宗教的仪规。"},{"id":156,"unit":1,"lesson":3,"word":"uphold","pronunciation":"/ʌpˈhəʊld/","meaning":"v.支持，维护;维持(原则)","seq":49,"isStar":false,"memo":"构词 up-(向上) + hold(持有)→支持,维护\n对照 hold up 举起;支持→uphold v.","example":"We have a duty to uphold the law. 维护法律是我们的责任。"},{"id":157,"unit":1,"lesson":3,"word":"hoist","pronunciation":"/hɔɪst/","meaning":"n.起重机;吊车 v.吊起，升起，提起","seq":50,"isStar":false,"memo":"联想 ho(联想 hold) + -ist(后缀)→抓住东西使其升起的设备→起重机","example":"They hoisted the flag at sunrise. 他们在日出时升起了旗帜。"},{"id":158,"unit":1,"lesson":3,"word":"elevate","pronunciation":"/ˈelɪveɪt/","meaning":"v.举起，抬起;提拔，晋升;提升","seq":51,"isStar":false,"memo":"谐音 单词发音类似“爱丽喂特”→爱丽要喂特高的巨人吃饭,必须踮起脚尖,并“举起”手臂。","example":"I built a platform to elevate the bed. 我搭了一个台子,把床抬高了。"},{"id":159,"unit":1,"lesson":3,"word":"elevator","pronunciation":"/ˈelɪveɪtə(r)/","meaning":"n.电梯;升降机","seq":52,"isStar":false},{"id":160,"unit":1,"lesson":3,"word":"elevation","pronunciation":"/ˌelɪˈveɪʃ(ə)n/","meaning":"n.升高;提拔;提升","seq":53,"isStar":false},{"id":161,"unit":1,"lesson":3,"word":"eligible","pronunciation":"/ˈelɪdʒəb(ə)l/","meaning":"adj.有资格的;合适的","seq":54,"isStar":false,"memo":"联想 eli(音似“爱丽”)+g(联想“格”)+ -ible(形容词后缀)→爱丽是一名“合格的”员工。","example":"They are not eligible for a student loan. 他们没有资格申请学生贷款。"},{"id":162,"unit":1,"lesson":3,"word":"eligibility","pronunciation":"/ˌelɪdʒəˈbɪləti/","meaning":"n.资格;合格","seq":55,"isStar":false},{"id":163,"unit":1,"lesson":3,"word":"element","pronunciation":"/ˈelɪmənt/","meaning":"n.元素;因素，要素","seq":56,"isStar":false,"memo":"联想 elemen(音似“爱丽妹”)+t→爱丽的妹妹知道,成功需要很多“因素”。","example":"Cost was a key element in our decision. 成本是我们决策时考虑的一个重要因素。"},{"id":164,"unit":1,"lesson":3,"word":"elementary","pronunciation":"/ˌelɪˈmentri/","meaning":"adj.基本的;初级的","seq":57,"isStar":false,"memo":"element（元素）+ -ary（…的）→化学课上‘元素级’知识！adj.基础的，像ABC一样‘原初又简单’。","example":"Elementary coding skills are now required across disciplines. 基础编程能力如今已成为各学科的必备技能。"},{"id":165,"unit":1,"lesson":3,"word":"factor","pronunciation":"/ˈfæktə(r)/","meaning":"n.因素，要素 v.把……化为因素","seq":58,"isStar":false,"memo":"联想 fact(事实)+-or(后缀)→影响事实的东西→因素,要素","example":"Obesity is a major risk factor for heart disease. 肥胖是心脏病的主要风险因素。"},{"id":166,"unit":1,"lesson":3,"word":"ingredient","pronunciation":"/ɪnˈɡriːdiənt/","meaning":"n.成分，原料;因素，要素","seq":59,"isStar":false,"memo":"联想 in(里面)+gredi(联想“搁点”)+ent (联想 enter)→做饭时要往锅里搁(放)“原料”。","example":"Topsoil contains few of the ingredients needed for farming. 表层土壤含有少量耕作所必需的成分。"},{"id":167,"unit":1,"lesson":3,"word":"ally","pronunciation":"/ˈælaɪ/","meaning":"n.同盟国;盟友 v.与……结盟","seq":60,"isStar":false,"memo":"谐音 单词发音类似“爱莱”→爱莱是我的“盟友”。","example":"She will regret losing a close political ally. 她将为失去一个亲密的政治盟友而懊悔。"},{"id":168,"unit":1,"lesson":3,"word":"alliance","pronunciation":"/əˈlaɪəns/","meaning":"n.联盟","seq":61,"isStar":false},{"id":169,"unit":1,"lesson":3,"word":"coalition","pronunciation":"/ˌkəʊəˈlɪʃ(ə)n/","meaning":"n.联合政府;联合体;联盟;联合","seq":62,"isStar":false,"memo":"谐音 单词发音类似“靠我累心”→只依靠我太心累,组成“联盟”才高效。","example":"It will be able to put together a governing coalition. 它将能够组建一个执政联盟。"},{"id":170,"unit":1,"lesson":3,"word":"log","pronunciation":"/lɒɡ/","meaning":"n.原木;航海日志;日记 v.记录;行驶","seq":63,"isStar":false,"memo":"谐音 单词发音类似“捞个”→他从河里捞上来一块“原木”。","example":"The captain logged the ship's position every hour. 船长每小时记录一次船的位置。"},{"id":171,"unit":1,"lesson":3,"word":"barrier","pronunciation":"/ˈbæriə(r)/","meaning":"n.屏障，障碍物;关卡;分界线;隔阂","seq":64,"isStar":false,"memo":"联想 bar(棒,木条)+rier→用木条做的东西→屏障,障碍物","example":"They have some barriers on their way to academic success. 他们在取得学术成功的道路上有一些障碍。"},{"id":172,"unit":1,"lesson":3,"word":"timber","pronunciation":"/ˈtɪmbə(r)/","meaning":"n.树木，林木;木材，木料","seq":65,"isStar":false,"memo":"谐音 单词发音类似“挺拔”→“林木”很挺拔。","example":"Timber was still cheap because it could be brought in any quantity from distant woodlands. 木材仍然很便宜,因为可以从遥远的森林里大量地运送过来。"},{"id":173,"unit":1,"lesson":3,"word":"embarrass","pronunciation":"/ɪmˈbærəs/","meaning":"v.使尴尬，使难堪","seq":66,"isStar":false,"memo":"联想 em-(使)+bar(木条)+r+ass(屁股)→他调皮时,妈妈吓唬他要拿木条打他的屁股,这使他很尴尬→使尴尬","example":"The speech was a deliberate attempt to embarrass him. 这一发言蓄意使他难堪。"},{"id":174,"unit":1,"lesson":3,"word":"embarrassment","pronunciation":"/ɪmˈbærəsmənt/","meaning":"n.尴尬，困境","seq":67,"isStar":false},{"id":175,"unit":1,"lesson":3,"word":"awkward","pronunciation":"/ˈɔːkwəd/","meaning":"adj.令人尴尬的;笨拙的","seq":68,"isStar":false,"memo":"联想 awk(音似“拗口”)+ward(音似 word)→他读错了一个拗口的单词,那场面真是“令人尴尬的”。","example":"There was an awkward silence. 有一阵令人尴尬的沉寂。"},{"id":176,"unit":1,"lesson":3,"word":"barren","pronunciation":"/ˈbærən/","meaning":"adj.贫瘠的;不育的;不结果实的","seq":69,"isStar":false,"memo":"联想 bar(木条)+ren(联想“人”)→那个人用木条围起来一块“贫瘠的”土地。","example":"Many people think of deserts as barren regions. 许多人认为沙漠是贫瘠地区。"},{"id":177,"unit":1,"lesson":3,"word":"bargain","pronunciation":"/ˈbɑːɡən/","meaning":"n.便宜货;协议;交易 v.讨价还价","seq":70,"isStar":false,"memo":"联想 bar(木条)+gain(得到)→他用木条指着别人卖的东西说想要得到它,于是便开始“讨价还价”。","example":"In fact, the bargain is very pure. 事实上,这种交易非常纯粹。"},{"id":178,"unit":1,"lesson":3,"word":"bare","pronunciation":"/beə(r)/","meaning":"adj.赤裸的，裸露的","seq":71,"isStar":false,"memo":"联想 bar(木条)+e(字母音似“姨”)→木条划破了阿姨的衣袖,使她露出了胳膊→裸露的","example":"I got in the habit of going around with bare feet. 我养成了赤脚走路的习惯。"},{"id":179,"unit":1,"lesson":3,"word":"barely","pronunciation":"/ˈbeəli/","meaning":"adv.仅仅;勉强可能;几乎不","seq":72,"isStar":false},{"id":180,"unit":1,"lesson":3,"word":"bald","pronunciation":"/bɔːld/","meaning":"adj.秃头的;光秃秃的;简单的","seq":73,"isStar":false,"memo":"联想 bal(联想 ball)+d(联想“的”)→那个球面很光滑,没有毛刺,“光秃秃的”。","example":"He started going bald in his twenties. 他二十几岁便开始谢顶。"},{"id":181,"unit":1,"lesson":3,"word":"bold","pronunciation":"/bəʊld/","meaning":"adj.勇敢的，大胆的;鲁莽的","seq":74,"isStar":false,"memo":"联想 b(联想“不”)+old(老的)→不老的人(年轻人)具有冒险精神,做事往往是“大胆的”。","example":"She knew she had to make a bold move to fully commit to her new future. 她知道她必须采取大胆的行动,全身心地投入她的新未来。"},{"id":182,"unit":1,"lesson":3,"word":"cricket","pronunciation":"/ˈkrɪkɪt/","meaning":"n.板球(运动);蟋蟀","seq":75,"isStar":false,"memo":"联想 cr(联想“超人”)+i(我)+cket(音似“剋它”)→超人和我剋(打)它→板球","example":"The standard of professional cricket has never been lower. 职业板球的标准从来没这么低过。"},{"id":183,"unit":1,"lesson":4,"word":"emerge","pronunciation":"/ɪˈmɜːdʒ/","meaning":"v.出现，浮现;暴露;幸存下来","seq":1,"isStar":false,"memo":"联想 e-(出来) + merge(音似“磨叽”)→妈妈让他别磨叽了,赶紧出来吃饭→出现","example":"He finally emerged from his room. 他终于从房间里出来了。"},{"id":184,"unit":1,"lesson":4,"word":"emergence","pronunciation":"/ɪˈmɜːdʒəns/","meaning":"n.出现","seq":2,"isStar":false},{"id":185,"unit":1,"lesson":4,"word":"emergency","pronunciation":"/ɪˈmɜːdʒənsi/","meaning":"n.突发事件，紧急情况 adj.紧急的","seq":3,"isStar":false,"memo":"构词 emerg(出现) + -ency(后缀)→突然出现的事→突发事件,紧急情况","example":"Employees should be fully acquainted with emergency procedures. 雇员们应当十分熟悉应急措施。"},{"id":186,"unit":1,"lesson":4,"word":"urgent","pronunciation":"/ˈɜːdʒənt/","meaning":"adj.紧急的，急切的","seq":4,"isStar":false,"memo":"谐音 单词发音类似“饿紧它”→他太饿了,急切地需要食物→紧急的,急切的","example":"He was called away for some urgent business abroad. 他因国外的一些紧急事务被叫走了。"},{"id":187,"unit":1,"lesson":4,"word":"urgency","pronunciation":"/ˈɜːdʒənsi/","meaning":"n.紧急，迫切","seq":5,"isStar":false},{"id":188,"unit":1,"lesson":4,"word":"haste","pronunciation":"/heɪst/","meaning":"n.匆忙，仓促","seq":6,"isStar":false,"memo":"谐音 单词发音类似“恨死他”→她被骗后恨死他了,就“匆忙”离开了他。","example":"Haste makes waste. 欲速则不达。"},{"id":189,"unit":1,"lesson":4,"word":"hasten","pronunciation":"/ˈheɪs(ə)n/","meaning":"v.促进，使加快","seq":7,"isStar":false,"memo":"构词 hast(快，同 haste 匆忙)+-en(使…)→使变快→促进，使加快","example":"The bad news hastened his departure. 这个坏消息促使他提前动身。"},{"id":190,"unit":1,"lesson":4,"word":"hasty","pronunciation":"/ˈheɪsti/","meaning":"adj.匆忙的;草率的","seq":8,"isStar":false,"memo":"构词 hast(快，同 haste 匆忙)+-y(形容词后缀)→图快的→匆忙的；草率的","example":"They had to eat a hasty meal, or they would be too late for the concert. 他们不得不匆匆吃顿饭,否则就赶不上音乐会了。"},{"id":191,"unit":1,"lesson":4,"word":"submerge","pronunciation":"/səbˈmɜːdʒ/","meaning":"v.淹没，浸没;掩盖","seq":9,"isStar":false,"memo":"联想 sub-(在下面) + merge(联想 emerge)→在下面出现→淹没","example":"The region will be submerged. 这个地区将被淹没。"},{"id":192,"unit":1,"lesson":4,"word":"submarine","pronunciation":"/ˌsʌbməˈriːn/","meaning":"n.潜艇 adj.海底的;水下的","seq":10,"isStar":false,"memo":"构词 sub-(在下面) + marine(海洋的)→海底的","example":"We were trying to plot the course of the submarine. 我们当时正试图标绘出那艘潜艇的航线。"},{"id":193,"unit":1,"lesson":4,"word":"marine","pronunciation":"/məˈriːn/","meaning":"adj.海洋的","seq":11,"isStar":false,"memo":"构词 mar(海，同 maritime 海事的)+-ine(形容词后缀)→海的→海洋的","example":"Marine biologists are looking for the secret of turtles’ reproduction. 海洋生物学家正在寻找海龟繁殖的秘密。"},{"id":194,"unit":1,"lesson":4,"word":"swamp","pronunciation":"/swɒmp/","meaning":"v.使陷入;淹没 n.沼泽(地)","seq":12,"isStar":false,"memo":"联想 swam (swim 的过去式) + p (联想“扑”)→他扑到水里游泳,被水“淹没”了。","example":"I was swamped with work last week. 上周我被工作淹没了。"},{"id":195,"unit":1,"lesson":4,"word":"overwhelm","pronunciation":"/ˌəʊvəˈwelm/","meaning":"v.压倒;击败;难以承受;淹没","seq":13,"isStar":false,"memo":"[联想] over(上面)+whel(联想 wheel)+m(联想 me)→上面的轮子把我“压倒”了。","example":"The little boat was swamped by the waves. 小船被大浪淹没了。 At that moment, grief overwhelmed me. 那时，我不胜悲伤。"},{"id":196,"unit":1,"lesson":4,"word":"overwhelming","pronunciation":"/ˌəʊvəˈwelmɪŋ/","meaning":"adj.巨大的;压倒性的","seq":14,"isStar":false},{"id":197,"unit":1,"lesson":4,"word":"overwhelmingly","pronunciation":"/ˌəʊvəˈwelmɪŋli/","meaning":"adv.巨大地;压倒性地","seq":15,"isStar":false},{"id":198,"unit":1,"lesson":4,"word":"reel","pronunciation":"/riːl/","meaning":"n.卷轴;卷盘;卷筒 v.眩晕，天旋地转","seq":16,"isStar":false,"memo":"[对照] 轮子(wheel)一直旋转,让人眩晕(reel)。","example":"When he opened his eyes, the room was reeling. 他睁开眼睛时,房间在旋转。"},{"id":199,"unit":1,"lesson":4,"word":"adore","pronunciation":"/əˈdɔː(r)/","meaning":"v.爱慕;热爱","seq":17,"isStar":false,"memo":"联想 ad-(一再地)+o(形似圆圈)+re(字母音似“阿姨”)→孩子们因为喜欢阿姨,一再地把她围在圈中→爱慕;热爱","example":"All the children adored the girl.所有孩子都很喜欢那个女孩。"},{"id":200,"unit":1,"lesson":4,"word":"adorable","pronunciation":"/əˈdɔːrəb(ə)l/","meaning":"adj.可爱的;讨人喜爱的","seq":18,"isStar":false},{"id":201,"unit":1,"lesson":4,"word":"admire","pronunciation":"/ədˈmaɪə(r)/","meaning":"v.赞美;欣赏;钦佩","seq":19,"isStar":false,"memo":"[联想] ad-(一再地)+m(联想“妹”)+i(我)+re(字母音似“阿姨”)→妹妹和我一再地围着阿姨,因为我们都很“钦佩”她。","example":"She admired his beautiful blue eyes. 她羡慕他那双美丽的蓝眼睛。"},{"id":202,"unit":1,"lesson":4,"word":"admirable","pronunciation":"/ˈædmərəb(ə)l/","meaning":"adj.值得赞赏的，可钦佩的","seq":20,"isStar":false},{"id":203,"unit":1,"lesson":4,"word":"eradicate","pronunciation":"/ɪˈrædɪkeɪt/","meaning":"v.根除，消灭;杜绝","seq":21,"isStar":false,"memo":"[联想] e(字母音似“姨”) + ra(联想“让”) + di(联想“弟”) + cate(音似“它”)→阿姨让弟弟剋它(打苍蝇)→根除,消灭","example":"We will aim to finally eradicate disease and poverty. 我们的最终目标是根除疾病和贫穷。"},{"id":204,"unit":1,"lesson":4,"word":"eradication","pronunciation":"/ɪˌrædɪˈkeɪʃ(ə)n/","meaning":"n.根除;消灭;杜绝","seq":22,"isStar":false},{"id":205,"unit":1,"lesson":4,"word":"refrain","pronunciation":"/rɪˈfreɪn/","meaning":"v.克制;避免 n.经常重复的评价","seq":23,"isStar":false,"memo":"[联想] re(字母音似“阿姨”) + frain(音似“夫人”)→阿姨要和那位夫人去旅行了,我舍不得她离开,但我“克制”住了。","example":"Please refrain from smoking. 请勿吸烟。"},{"id":206,"unit":1,"lesson":4,"word":"regulate","pronunciation":"/ˈreɡjuleɪt/","meaning":"v.控制，管理;调整，调节","seq":24,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + gu(联想“故”) + late(迟到)→阿姨因故迟到，她的秘书马上“调整”了会议的流程。","example":"Their emotions were much harder to regulate. 他们的情绪很难调节。"},{"id":207,"unit":1,"lesson":4,"word":"regulation","pronunciation":"/ˌreɡjuˈleɪʃ(ə)n/","meaning":"n.规则;条例","seq":25,"isStar":false},{"id":208,"unit":1,"lesson":4,"word":"regulator","pronunciation":"/ˈreɡjuleɪtə(r)/","meaning":"n.监管者;调节器","seq":26,"isStar":false},{"id":209,"unit":1,"lesson":4,"word":"regulatory","pronunciation":"/ˈreɡjələtəri/","meaning":"adj.具有监管权的，监管的","seq":27,"isStar":false},{"id":210,"unit":1,"lesson":4,"word":"regular","pronunciation":"/ˈreɡjələ(r)/","meaning":"adj.规则的;有规律的 n.常客","seq":28,"isStar":false,"memo":"对照 regulate v.控制，管理；调整，调节→ regular adj. & n.","example":"We hold a regular monthly meeting. 我们每月定期举行会议。"},{"id":211,"unit":1,"lesson":4,"word":"regularity","pronunciation":"/ˌreɡjuˈlærəti/","meaning":"n.规律性;经常性;有规律的事物","seq":29,"isStar":false},{"id":212,"unit":1,"lesson":4,"word":"irregular","pronunciation":"/ɪˈreɡjələ(r)/","meaning":"adj.不整齐的;不规则的;不正常的","seq":30,"isStar":false,"memo":"构词 ir-(否定前缀，用在 r 前)+regular(规则的)→不合规则的→不规则的，不整齐的","example":"He had bad teeth, which were irregular. 他的牙齿不好，参差不齐。"},{"id":213,"unit":1,"lesson":4,"word":"deregulate","pronunciation":"/ˌdiːˈreɡjuleɪt/","meaning":"v.解除控制，撤销管制","seq":31,"isStar":false,"memo":"构词 de-(去除)+regulate(管制)→把管制去掉→解除控制，撤销管制","example":"The government decided to deregulate the airline industry. 政府决定解除对航空业的管制。"},{"id":214,"unit":1,"lesson":4,"word":"deregulation","pronunciation":"/ˌdiːˌreɡjuˈleɪʃn/","meaning":"n.解除控制","seq":32,"isStar":false,"memo":"构词 de-(去除)+regul(规则)+-ation(名词后缀)→取消规则→解除控制","example":"Deregulation brought more competition into the market. 放松管制给市场带来了更多竞争。"},{"id":215,"unit":1,"lesson":4,"word":"relate","pronunciation":"/rɪˈleɪt/","meaning":"v.有联系，有关联;讲述","seq":33,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + late(迟到)→阿姨迟到了，她要向我“讲述”理由，因为我们“有关联”。","example":"It is directly related to your commitment. 这直接关系到你的承诺。"},{"id":216,"unit":1,"lesson":4,"word":"relation","pronunciation":"/rɪˈleɪʃ(ə)n/","meaning":"n.关系，联系;亲属","seq":34,"isStar":false,"memo":"构词 re-(回)+lat(带来，同 relate 关联)+-ion(名词后缀)→把双方连回来的东西→关系；亲属","example":"There is a close relation between diet and health. 饮食与健康之间存在密切关系。"},{"id":217,"unit":1,"lesson":4,"word":"relationship","pronunciation":"/rɪˈleɪʃ(ə)nʃɪp/","meaning":"n.关系，联系","seq":35,"isStar":false},{"id":218,"unit":1,"lesson":4,"word":"relative","pronunciation":"/ˈrelətɪv/","meaning":"n.亲戚，亲属 adj.相关联的;比较的","seq":36,"isStar":false,"memo":"构词 re-(回)+lat(带来)+-ive(形容词后缀)→可相互牵连的→相关的，相对的；亲属","example":"Mary is going to get a little dog from one of her relatives. 玛丽打算从她的一个亲戚那里领养一只小狗。"},{"id":219,"unit":1,"lesson":4,"word":"relativity","pronunciation":"/ˌreləˈtɪvəti/","meaning":"n.相对论;相对性","seq":37,"isStar":false},{"id":220,"unit":1,"lesson":4,"word":"correlate","pronunciation":"/ˈkɒrəleɪt; ˈkɒrələt/","meaning":"v.相互关联影响;相互依赖","seq":38,"isStar":false,"memo":"构词 cor-( = com-, 共同) + relate (有关联)→相互关联影响","example":"The figures do not seem to correlate. 这些数字似乎毫不相干。"},{"id":221,"unit":1,"lesson":4,"word":"correlation","pronunciation":"/ˌkɒrəˈleɪʃ(ə)n/","meaning":"n.相关;关联","seq":39,"isStar":false},{"id":222,"unit":1,"lesson":4,"word":"correlative","pronunciation":"/kəˈrelətɪv/","meaning":"adj.密切相关的;互相依赖的","seq":40,"isStar":false},{"id":223,"unit":1,"lesson":4,"word":"resort","pronunciation":"/rɪˈzɔːt/","meaning":"n.求助;旅游胜地 v.(~to)求助于","seq":41,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + sort(分类)→阿姨让她把各种豆子分类后才能出去，她却“求助”他人。","example":"Meetings at resorts are suddenly unacceptable. 在旅游胜地开会突然变得不可接受。"},{"id":224,"unit":1,"lesson":4,"word":"haunt","pronunciation":"/hɔːnt/","meaning":"v.萦绕于脑际","seq":42,"isStar":false,"memo":"谐音 “嚎嗯特”：夜里嚎叫的幽灵在屋里转→萦绕于脑际，使难以忘却","example":"For years she was haunted by guilt. 多年来她一直感到愧疚。"},{"id":225,"unit":1,"lesson":4,"word":"hound","pronunciation":"/haʊnd/","meaning":"n.猎(狐)犬 v.追踪;追逐;纠缠","seq":43,"isStar":false,"memo":"联想 与 hunt(打猎)形近：猎犬(hound)就是打猎(hunt)的伙伴→猎犬；追踪，纠缠","example":"Reporters hounded him for months. 记者们纠缠了他好几个月。"},{"id":226,"unit":1,"lesson":4,"word":"forth","pronunciation":"/fɔːθ/","meaning":"adv.向前;往外","seq":44,"isStar":false,"memo":"[联想] for(为了)+th(音似“死”)→他“不见黄河心不死”,誓要“向前”达成目标。","example":"They set forth at dawn. 他们黎明时出发了。"},{"id":227,"unit":1,"lesson":4,"word":"forthcoming","pronunciation":"/ˌfɔːθˈkʌmɪŋ/","meaning":"adj.即将发生的，即将出现的","seq":45,"isStar":false,"memo":"[构词] forth(向前)+coming(到来)→前面要到来的→即将发生的","example":"Financial support was not forthcoming. 财政支援尚未到手。"},{"id":228,"unit":1,"lesson":4,"word":"forecast","pronunciation":"/ˈfɔːkɑːst/","meaning":"n.&v.预测，预报","seq":46,"isStar":false,"memo":"[构词] fore-(先,前)+cast(投)→事情发生之前就投出来→预测,预报","example":"Experts are forecasting a recovery in the economy. 专家预测经济将复苏。"},{"id":229,"unit":1,"lesson":4,"word":"cast","pronunciation":"/kɑːst/","meaning":"v.投射;扔;浇铸 n.演员表;全体演员","seq":47,"isStar":false,"memo":"联想 与 broadcast(广播)同根：把东西或信息“投”出去→投射；扔；演员表","example":"I cast an angry look at him. 我愤怒地看着他。"},{"id":230,"unit":1,"lesson":4,"word":"broadcast","pronunciation":"/ˈbrɔːdkɑːst/","meaning":"v.广播;散布，传播 n.广播节目","seq":48,"isStar":false,"memo":"[构词] broad(宽阔的,广泛的)+cast(投)→广播;散布","example":"Broadcasting his ambition was very much his decision. 宣扬他的抱负在很大程度上是他的决定。"},{"id":231,"unit":1,"lesson":4,"word":"foretell","pronunciation":"/fɔːˈtel/","meaning":"v.预言，预测","seq":49,"isStar":false,"memo":"构词 fore-(先,前)+tell(说)→预言,预测","example":"Ancient people were good at foretelling the weather.古人善于预测天气。"},{"id":232,"unit":1,"lesson":4,"word":"foremost","pronunciation":"/ˈfɔːməʊst/","meaning":"adj.最重要的;最前的 adv.首先","seq":50,"isStar":false,"memo":"[构词] fore-(先,前)+most(最)→最重要的;最前的","example":"This question has been foremost in our minds recently. 近来,我们心中一直认为这个问题最重要。"},{"id":233,"unit":1,"lesson":4,"word":"beforehand","pronunciation":"/bɪˈfɔːhænd/","meaning":"adv.预先，事先","seq":51,"isStar":false,"memo":"[构词] before(在……之前)+hand(手)→我们习惯于在着手做一件事之前要“预先”做准备。","example":"They make careful preparations beforehand. 他们事先做了周密的准备。"},{"id":234,"unit":1,"lesson":4,"word":"foresee","pronunciation":"/fɔːˈsiː/","meaning":"v.预料，预见，预知","seq":52,"isStar":false,"memo":"[构词] fore-(先,前)+see(看见)→预料,预见,预知","example":"He failed to foresee major problems. 他没能预见到主要问题。"},{"id":235,"unit":1,"lesson":4,"word":"foreseeable","pronunciation":"/fɔːˈsiːəb(ə)l/","meaning":"adj.可预见的，可预知的","seq":53,"isStar":false},{"id":236,"unit":1,"lesson":4,"word":"foresight","pronunciation":"/ˈfɔːsaɪt/","meaning":"n.深谋远虑;先见之明","seq":54,"isStar":false,"memo":"构词 forc-(先,前) + sight(看到)→先见之明","example":"The UN had the foresight to convene a “world assembly on ageing” back in 1982. 早在1982年,联合国就有先见之明地召开了一次“世界老龄问题大会”。"},{"id":237,"unit":1,"lesson":4,"word":"sight","pronunciation":"/saɪt/","meaning":"n.视力，视觉;景象 v.看到，发现","seq":55,"isStar":false,"memo":"联想 s(联想 see) + ight(联想 light)→可以看见光线→视力,视觉;景象","example":"The accident deprived him of his sight. 这次事故使他失明。"},{"id":238,"unit":1,"lesson":4,"word":"sightseeing","pronunciation":"/ˈsaɪtsiːɪŋ/","meaning":"n.观光","seq":56,"isStar":false,"memo":"构词 sight(景物)+seeing(看)→一路看景物→观光","example":"While I’m there, I’d also like to do some sightseeing. 当我在那里的时候,我也希望能参观一下。"},{"id":239,"unit":1,"lesson":4,"word":"oversight","pronunciation":"/ˈəʊvəsaɪt/","meaning":"n.监督;疏忽，失察","seq":57,"isStar":false,"memo":"(构词) over-(超越)+sight(看到)→监督","example":"He has general oversight of all training courses.他全面监督所有的培训课程。"},{"id":240,"unit":1,"lesson":4,"word":"insight","pronunciation":"/ˈɪnsaɪt/","meaning":"n.洞察力;领悟，了解","seq":58,"isStar":false,"memo":"构词 in-(进入) + sight(看到)→看进去→洞察力","example":"These excursions will give you an even deeper insight into our language and culture. 这些短途旅行将会让你对我们的语言和文化有更深入的了解。"},{"id":241,"unit":1,"lesson":4,"word":"insightful","pronunciation":"/ɪnˈsaɪtf(ə)l/","meaning":"adj.富有洞察力的","seq":59,"isStar":false},{"id":242,"unit":1,"lesson":4,"word":"horizon","pronunciation":"/həˈraɪz(ə)n/","meaning":"n.地平线;范围，视野","seq":60,"isStar":false,"memo":"联想 ho(音似“好”) + riz(音似 rise) + on →好大的太阳从“地平线”升起来了。","example":"She wanted to travel to broaden her horizons. 她想旅行,以开阔眼界。"},{"id":243,"unit":1,"lesson":4,"word":"horizontal","pronunciation":"/ˌhɒrɪˈzɒnt(ə)l/","meaning":"adj.水平的;与地面平行的 n.水平面","seq":61,"isStar":false},{"id":244,"unit":1,"lesson":4,"word":"orient","pronunciation":"/ˈɔːrient/","meaning":"v.确定方向;适应 n.东方","seq":62,"isStar":false,"memo":"联想 o-(表方向) + ri(联想“日”) + ent(联想 enter)→太阳从“东方”进来(升起)了。","example":"The mountaineers found it hard to orient themselves in the fog. 登山者发现在大雾中很难辨认方向。"},{"id":245,"unit":1,"lesson":4,"word":"orientation","pronunciation":"/ˌɔːriənˈteɪʃ(ə)n/","meaning":"n.方向;目标;观点","seq":63,"isStar":false},{"id":246,"unit":1,"lesson":4,"word":"oriental","pronunciation":"/ˌɔːriˈent(ə)l/","meaning":"adj.东方的;东方人的","seq":64,"isStar":false},{"id":247,"unit":1,"lesson":4,"word":"scene","pronunciation":"/siːn/","meaning":"n.风景，景色;舞台布景;情景;现场","seq":65,"isStar":false,"memo":"对照 同音词 scen→我看见了(seen)美丽的风景(scene)。","example":"The human mind can glimpse a rapidly changing scene. 人类的大脑可以瞥见一个迅速变化的场景。"},{"id":248,"unit":1,"lesson":4,"word":"scenic","pronunciation":"/ˈsiːnɪk/","meaning":"adj.风景优美的","seq":66,"isStar":false},{"id":249,"unit":1,"lesson":4,"word":"scenario","pronunciation":"/səˈnɑːriəʊ/","meaning":"n.设想;方案;场景","seq":67,"isStar":false,"memo":"联想 sce(联想 scene) + nario(音似“哪里”)→去哪里看风景要先有个“设想”。","example":"Medical students are not blind to this scenario. 医学生对这种场景并非视而不见。"},{"id":250,"unit":1,"lesson":4,"word":"landscape","pronunciation":"/ˈlændskeɪp/","meaning":"n.风景，景色","seq":68,"isStar":false,"memo":"联想 land(陆地) + sc(联想“四看”) + ape (猿猴)→陆地上“风景”优美,四周都能看到猿猴。","example":"He loves the beautiful landscape of Australia very much. 他非常喜欢澳大利亚美丽的风景。"},{"id":251,"unit":2,"lesson":1,"word":"ecology","pronunciation":"/iˈkɒlədʒi/","meaning":"n.生态;生态学","seq":1,"isStar":false,"memo":"[联想] e(字母音似“姨”) + cology(音似“靠了鸡”)→阿姨是养鸡能手，办了一个绿色有机“生态”农场来养鸡。","example":"Oil pollution could damage the fragile ecology of the coral reefs. 石油污染可能破坏珊瑚礁脆弱的生态环境。"},{"id":252,"unit":2,"lesson":1,"word":"ecological","pronunciation":"/ˌiːkəˈlɒdʒɪk(ə)l/","meaning":"adj.生态的;生态学的","seq":2,"isStar":false,"memo":"构词 ecolog(y)(生态;生态学) + -ical(形容词后缀)→生态的;生态学的","example":"They are living beyond our ecological means.我们正以超出生态承载力的方式生活。"},{"id":253,"unit":2,"lesson":1,"word":"ecosystem","pronunciation":"/ˈiːkəʊsɪstəm/","meaning":"n.生态系统","seq":3,"isStar":false,"memo":"构词 eco-(生态，同 ecology 生态学)+system(系统)→生态系统","example":"The pond is a small but complete ecosystem.这个池塘是一个小而完整的生态系统。"},{"id":254,"unit":2,"lesson":1,"word":"system","pronunciation":"/ˈsɪstəm/","meaning":"n.体系,制度;系统","seq":4,"isStar":false,"memo":"联想 sy-(一起)+stem(茎、主干)→许多部分连在同一根主干上→体系，系统","example":"How does the system work? 系统是如何工作的?"},{"id":255,"unit":2,"lesson":1,"word":"systematic","pronunciation":"/ˌsɪstəˈmætɪk/","meaning":"adj.系统的;有条理的","seq":5,"isStar":false},{"id":256,"unit":2,"lesson":1,"word":"stalk","pronunciation":"/stɔːk/","meaning":"n.茎,杆,柄 v.跟踪;盯梢","seq":6,"isStar":false,"memo":"联想 s(联想“蛇”) + talk(交谈)→两条蛇盘在两棵草的“秆”上交谈。","example":"He has been stalking her over a period of three years.他跟踪她已经三年了。"},{"id":257,"unit":2,"lesson":1,"word":"stem","pronunciation":"/stem/","meaning":"n.茎,梗 v.阻止,遏制;堵住;起源于","seq":7,"isStar":false,"memo":"[对照] 他用塞子堵住(stem)了出水蒸气(steam)的气孔。","example":"The stem of the plant looks ugly. 这株植物的茎看起来很丑。"},{"id":258,"unit":2,"lesson":1,"word":"limb","pronunciation":"/lɪm/","meaning":"n.肢,翼;大树枝","seq":8,"isStar":false,"memo":"[联想] li(联想“立”) + m(联想“妹”) + b(联想“臂”)→一只鸟站立在妹妹的手臂上,像站在树枝上一样→肢;大树枝","example":"For a while, she lost the use of her limbs. 好一会儿她四肢都动弹不得。"},{"id":259,"unit":2,"lesson":1,"word":"bark","pronunciation":"/bɑːk/","meaning":"n.树皮;(狗等的)吠声 v.(狗)吠叫","seq":9,"isStar":false,"memo":"对照 酒吧 (bar) 后面 (back) 传来狗吠声 (bark)。","example":"I could hear a dog barking.我能听到狗在叫。"},{"id":260,"unit":2,"lesson":1,"word":"breast","pronunciation":"/brest/","meaning":"n.胸部,胸脯;(女子的)乳房","seq":10,"isStar":false,"memo":"联想 b(联想“不”) + reast(联想 rest)→心脏在“胸部”中间偏左的地方跳动,不休息。","example":"It helps people to avoid developing breast cancer.它有助于人们避免患上乳腺癌。"},{"id":261,"unit":2,"lesson":1,"word":"abreast","pronunciation":"/əˈbrest/","meaning":"adv.并列,并排,并肩","seq":11,"isStar":false,"memo":"构词 a-(在) + breast(胸部)→在与胸部齐平的位置→并排","example":"A police car drew abreast of us and signalled us to stop.一辆警车与我们并排行驶，示意我们停车。"},{"id":262,"unit":2,"lesson":1,"word":"belly","pronunciation":"/ˈbeli/","meaning":"n.腹部;圆形或凸起部分","seq":12,"isStar":false,"memo":"对照 肚子饿的时候,腹部(belly)会发声,像铃(bell)一样响。","example":"They crawled along on their bellies.他们匍匐前进。"},{"id":263,"unit":2,"lesson":1,"word":"weed","pronunciation":"/wiːd/","meaning":"n.杂草,野草 v.除草","seq":13,"isStar":false,"memo":"联想 wee(音似 we) + d(联想“的”)→我们的花园里长满了“野草”。","example":"The yard was overgrown with weeds.院子里杂草丛生。"},{"id":264,"unit":2,"lesson":1,"word":"yard","pronunciation":"/jɑːd/","meaning":"n.院子;码(长度单位)","seq":14,"isStar":false,"memo":"联想 与 garden(花园)同源：房子周围圈起来的那块地→院子；也作长度单位“码”","example":"Which door leads to the yard?哪扇门通往院子？"},{"id":265,"unit":2,"lesson":1,"word":"insect","pronunciation":"/ˈɪnsekt/","meaning":"n.昆虫","seq":15,"isStar":false,"memo":"联想 in(里面) + sect(音似“塞个它”)→他耳朵不舒服去医院，结果医生发现他的耳朵里塞了一只“昆虫”。","example":"Most birds spend most of the day eating insects. 大多数鸟一天大部分时间都在吃昆虫。"},{"id":266,"unit":2,"lesson":1,"word":"vegetation","pronunciation":"/ˌvedʒəˈteɪʃ(ə)n/","meaning":"n.植物,植被","seq":16,"isStar":false,"memo":"对照 这里的蔬菜（vegetable）和植被（vegetation）都生长得很好。","example":"Unburnt vegetation rots quickly. 未燃烧的植被很快就会腐烂。"},{"id":267,"unit":2,"lesson":1,"word":"bleak","pronunciation":"/bliːk/","meaning":"adj.不乐观的,无望的;阴冷的;荒凉的","seq":17,"isStar":false,"memo":"谐音 单词发音类似“不立刻”→他不能立刻离开那个“荒凉的”地方。","example":"Don't ask for evidence that justifies this bleak view. 别去找证明这种悲观观点的证据了。"},{"id":268,"unit":2,"lesson":1,"word":"blink","pronunciation":"/blɪŋk/","meaning":"v.眨眼睛;(灯光)闪烁 n.眨眼","seq":18,"isStar":false,"memo":"联想 blin(音似“布灵”) + k(音似“可”)→她“眨眼睛”时,眼睛“布灵布灵”的,很可爱。","example":"My eyes only blink for you.我的眼睛只为你闪烁。"},{"id":269,"unit":2,"lesson":1,"word":"brisk","pronunciation":"/brɪsk/","meaning":"adj.轻快的;敏捷的;麻利的;清新的","seq":19,"isStar":false,"memo":"联想 b(联想“不”) + risk(冒险)→不想冒险,就要快点离开→麻利的","example":"They set off at a brisk pace. 他们踏着轻快的步伐出发了。"},{"id":270,"unit":2,"lesson":1,"word":"humid","pronunciation":"/ˈhjuːmɪd/","meaning":"adj.温暖潮湿的,湿热的","seq":20,"isStar":false,"memo":"对照：传说人类(human)是女娲用潮湿的(humid)泥土捏成的。","example":"These plants will grow best in a humid atmosphere. 这些植物在湿热的环境中长得最好。"},{"id":271,"unit":2,"lesson":1,"word":"humidity","pronunciation":"/hjuːˈmɪdəti/","meaning":"n.湿度;湿热","seq":21,"isStar":false},{"id":272,"unit":2,"lesson":1,"word":"moist","pronunciation":"/mɔɪst/","meaning":"adj.潮湿的,湿润的","seq":22,"isStar":false,"memo":"联想：mo(音似“毛”) + ist→长毛是因为天气潮湿，发霉了→潮湿的","example":"The warm moist air is perfect for growing fruit trees. 温暖湿润的空气最适于果树生长。"},{"id":273,"unit":2,"lesson":1,"word":"moisture","pronunciation":"/ˈmɔɪstʃə(r)/","meaning":"n.潮气;水汽","seq":23,"isStar":false},{"id":274,"unit":2,"lesson":1,"word":"damp","pronunciation":"/dæmp/","meaning":"adj.潮湿的 n.潮湿","seq":24,"isStar":false,"memo":"联想：dam(大坝) + p(联想“趴”)→趴在大坝上，一会儿就感觉到“潮湿”了。","example":"The cottage was cold and damp. 这小屋又冷又湿。"},{"id":275,"unit":2,"lesson":1,"word":"dampen","pronunciation":"/ˈdæmpən/","meaning":"v.弄湿;抑制,减弱","seq":25,"isStar":false},{"id":276,"unit":2,"lesson":1,"word":"render","pronunciation":"/ˈrendə(r)/","meaning":"v.使变得,使处于某状态;给予,回报","seq":26,"isStar":false,"memo":"谐音：单词发音类似“润的”→潮湿的天气往往使人的皮肤变得润润的→使变得","example":"It renders us unable to concentrate. 它使我们无法集中注意力。"},{"id":277,"unit":2,"lesson":1,"word":"rendering","pronunciation":"/ˈrendərɪŋ/","meaning":"n.演奏;扮演;翻译","seq":27,"isStar":false},{"id":278,"unit":2,"lesson":1,"word":"surrender","pronunciation":"/səˈrendə(r)/","meaning":"v.投降;自首,放弃,交出 n.投降","seq":28,"isStar":false,"memo":"构词 sur-(在…之上)+render(交出、给予)→把武器举过头顶交上去→投降，屈服，交出","example":"They demanded unconditional surrender. 他们要求无条件投降。"},{"id":279,"unit":2,"lesson":1,"word":"drought","pronunciation":"/draʊt/","meaning":"n.久旱;旱灾","seq":29,"isStar":false,"memo":"谐音 “抓特”：久旱时最想“抓住”水龙头→久旱，旱灾","example":"Their eggs can survive years of drought. 它们的卵能经受多年的干旱。"},{"id":280,"unit":2,"lesson":1,"word":"humble","pronunciation":"/ˈhʌmb(ə)l/","meaning":"adj.谦逊的;卑微的","seq":30,"isStar":false,"memo":"构词：hum(泥土) + -ble(形容词后缀)→接近泥土的→谦逊的；卑微的","example":"The main character is a young man of humble origin. 主人公是一个出身卑微的年轻人。"},{"id":281,"unit":2,"lesson":1,"word":"humbly","pronunciation":"/ˈhʌmbli/","meaning":"adv.卑微地;谦逊地","seq":31,"isStar":false},{"id":282,"unit":2,"lesson":1,"word":"tumble","pronunciation":"/ˈtʌmb(ə)l/","meaning":"n.跌倒 v.跌倒;倒塌;骤降","seq":32,"isStar":false,"memo":"对照：他现在很卑微(humble)，因为他跌倒(tumble)了。","example":"The price of oil is still tumbling. 油价仍在急剧下跌。"},{"id":283,"unit":2,"lesson":1,"word":"humiliate","pronunciation":"/hjuːˈmɪlieɪt/","meaning":"v.羞辱,使丧失尊严","seq":33,"isStar":false,"memo":"联想 hum(泥土) + i(我) + li(联想“离”) + -ate(动词后缀) → 使我的脸离泥土很近 → 羞辱;使丧失尊严","example":"Why do they feel humiliated?他们为什么感到受辱？"},{"id":284,"unit":2,"lesson":1,"word":"humiliation","pronunciation":"/hjuːˌmɪliˈeɪʃn/","meaning":"n.丢脸;羞辱,耻辱","seq":34,"isStar":false},{"id":285,"unit":2,"lesson":1,"word":"humane","pronunciation":"/hjuːˈmeɪn/","meaning":"adj.善良的,仁慈的;人道的","seq":35,"isStar":false,"memo":"对照 human n.人→humane adj.","example":"The elderly need humane help from society.老年人需要社会给予人道的帮助。"},{"id":286,"unit":2,"lesson":1,"word":"humanist","pronunciation":"/ˈhjuːmənɪst/","meaning":"n.人文主义者;人文学者","seq":36,"isStar":false,"memo":"构词 human(人类) + -ist(表示人的后缀) →人文主义者","example":"Humanists are usually among the lowest-paid faculty members at most institutions.在大多数院校，人文主义者通常属于薪酬最低的教员之列。"},{"id":287,"unit":2,"lesson":1,"word":"humanism","pronunciation":"/ˈhjuːmənɪzəm/","meaning":"n.人文主义","seq":37,"isStar":false},{"id":288,"unit":2,"lesson":1,"word":"humanitarian","pronunciation":"/hjuːˌmænɪˈteəriən/","meaning":"adj.人道主义的;慈善的","seq":38,"isStar":false},{"id":289,"unit":2,"lesson":1,"word":"humanity","pronunciation":"/hjuːˈmænəti/","meaning":"n.人类;人道;仁慈;人文学科","seq":39,"isStar":false},{"id":290,"unit":2,"lesson":1,"word":"feminine","pronunciation":"/ˈfemənɪn/","meaning":"adj.女性特有的,妇女的;阴性的","seq":40,"isStar":false,"memo":"构词 femin (= female) + -ine (形容词后缀)→女性特有的,妇女的","example":"She loved pretty feminine things. 她喜爱漂亮有女人味的东西。"},{"id":291,"unit":2,"lesson":1,"word":"feminism","pronunciation":"/ˈfemənɪzəm/","meaning":"n.女权主义;女性主义","seq":41,"isStar":false},{"id":292,"unit":2,"lesson":1,"word":"feminist","pronunciation":"/ˈfemənɪst/","meaning":"n.女权主义者;女性主义者","seq":42,"isStar":false},{"id":293,"unit":2,"lesson":1,"word":"famine","pronunciation":"/ˈfæmɪn/","meaning":"n.饥荒,饥饿","seq":43,"isStar":false,"memo":"联想 fam(联想 farm) + in(里面) + e(字母音似“姨”)→农场里的阿姨“饥饿”了。","example":"The government has to make sure people don’t die of famine. 政府必须确保人们不会死于饥饿。"},{"id":294,"unit":2,"lesson":1,"word":"species","pronunciation":"/ˈspiːʃiːz/","meaning":"n.种,物种","seq":44,"isStar":false,"memo":"对照 每个物种(species)都有独特的(special)外观。","example":"This preference represents a built-in advantage for the human species. 这种偏好代表了人类物种的内在优势。"},{"id":295,"unit":2,"lesson":1,"word":"exist","pronunciation":"/ɪɡˈzɪst/","meaning":"v.存在;实际上有;生存","seq":45,"isStar":false,"memo":"构词 ex-(向外)+sist(站立，同 insist 坚持)→站出来立在那儿→存在，生存","example":"Does life exist on other planets? 其他行星上有生命吗?"},{"id":296,"unit":2,"lesson":1,"word":"existence","pronunciation":"/ɪɡˈzɪstəns/","meaning":"n.存在;生活,生活方式","seq":46,"isStar":false},{"id":297,"unit":2,"lesson":1,"word":"existent","pronunciation":"/ɪɡˈzɪstənt/","meaning":"adj.存在的 n.存在(或实有)的事物","seq":47,"isStar":false},{"id":298,"unit":2,"lesson":1,"word":"existing","pronunciation":"/ɪɡˈzɪstɪŋ/","meaning":"adj.现存的;现行的","seq":48,"isStar":false},{"id":299,"unit":2,"lesson":1,"word":"irrigate","pronunciation":"/ˈɪrɪɡeɪt/","meaning":"v.灌溉","seq":49,"isStar":false,"memo":"[联想] i(形似人)+rr(形似两朵花)+i(形似人)+gate(大门)→两个人站在大门口浇花→灌溉","example":"He wants to use the water to irrigate barren desert land. 他想用这些水来灌溉贫瘠的沙漠土地。"},{"id":300,"unit":2,"lesson":1,"word":"irrigation","pronunciation":"/ˌɪrɪˈɡeɪʃ(ə)n/","meaning":"n.灌溉","seq":50,"isStar":false},{"id":301,"unit":2,"lesson":1,"word":"irritable","pronunciation":"/ˈɪrɪtəb(ə)l/","meaning":"adj.急躁的,易怒的","seq":51,"isStar":false,"memo":"构词 irrit(刺激，同 irritate 使恼怒)+-able(可…的)→一点就着的→急躁的，易怒的","example":"I have been waiting for a long time, and I am beginning to feel irritable.我已经等了很久，开始变得烦躁。"},{"id":302,"unit":2,"lesson":1,"word":"irritate","pronunciation":"/ˈɪrɪteɪt/","meaning":"v.使烦恼;刺激","seq":52,"isStar":false,"memo":"ir-（不）+rit（刮擦）+ate（使）→‘刮’得你‘不爽’！像粉笔划黑板、微信弹窗连跳3次——物理刮擦+心理刮擦=暴躁源头。","example":"Constant notifications from social media irritate many users. 社交媒体的持续通知让许多用户感到烦躁。"},{"id":303,"unit":2,"lesson":1,"word":"irritation","pronunciation":"/ˌɪrɪˈteɪʃ(ə)n/","meaning":"n.刺激;刺激物;恼人的事","seq":53,"isStar":false},{"id":304,"unit":2,"lesson":1,"word":"irritating","pronunciation":"/ˈɪrɪteɪtɪŋ/","meaning":"adj.气人的,使人不愉快的","seq":54,"isStar":false},{"id":305,"unit":2,"lesson":1,"word":"outrage","pronunciation":"/ˈaʊtreɪdʒ/","meaning":"n.愤怒,愤慨;暴行 v.使震怒,激怒","seq":55,"isStar":false,"memo":"构词 out-(超出)+rage(狂怒)→超出常理的愤怒，也指激起众怒的暴行→愤怒，愤慨；暴行","example":"Many people have been outraged by some of the things that have been said.许多人被一些言论激怒了。"},{"id":306,"unit":2,"lesson":1,"word":"outrageous","pronunciation":"/aʊtˈreɪdʒəs/","meaning":"adj.骇人的;无法容忍的","seq":56,"isStar":false},{"id":307,"unit":2,"lesson":1,"word":"temper","pronunciation":"/ˈtempə(r)/","meaning":"n.脾气;心情","seq":57,"isStar":false,"memo":"[对照] 他的脾气(temper)就像气温(temperature)一样起伏不定。","example":"She cannot stand her boss's bad temper. 她无法忍受老板的坏脾气。"},{"id":308,"unit":2,"lesson":1,"word":"temperament","pronunciation":"/ˈtemprəmənt/","meaning":"n.气质,秉性;暴躁;喜怒无常","seq":58,"isStar":false,"memo":"构词 temper(脾气)+-ament(名词后缀)→与生俱来的脾气→气质，秉性","example":"His only weakness is his temperament. 他唯一的弱点是他的脾气。"},{"id":309,"unit":2,"lesson":1,"word":"inevitable","pronunciation":"/ɪnˈevɪtəb(ə)l/","meaning":"adj.不可避免的;惯常的","seq":59,"isStar":false,"memo":"[联想] in-(否定前缀)+evi(音似“俺为”)+table(桌子)→俺为了买那一张桌子付钱了,这是“不可避免的”。","example":"Sometimes, it is inevitable that the attention is focused elsewhere. 有时,注意力不可避免地被集中在其他地方。"},{"id":310,"unit":2,"lesson":1,"word":"organ","pronunciation":"/ˈɔːɡən/","meaning":"n.器官;风琴;(官方的)机构,机关","seq":60,"isStar":false,"memo":"[谐音] 单词发音类似“呕肝”→肝就是人体的“器官”。","example":"Some operations may damage the heart or other organs. 有些手术或许会损伤心脏或其他器官。"},{"id":311,"unit":2,"lesson":1,"word":"organic","pronunciation":"/ɔːˈɡænɪk/","meaning":"adj.有机的;绿色的;器官的","seq":61,"isStar":false,"memo":"[构词] organ(器官)+-ic(形容词后缀)→器官的","example":"The farm went fully organic in 1996. 这个农场在1996年就全部采用有机耕作了。"},{"id":312,"unit":2,"lesson":1,"word":"organism","pronunciation":"/ˈɔːɡənɪzəm/","meaning":"n.生物;有机体;(尤指)微生物","seq":62,"isStar":false,"memo":"[构词] organ(器官)+-ism(名词后缀)→生物;有机体","example":"It seems simple enough to distinguish between the organism and the surrounding environment. 区分生物体和周围的环境似乎很简单。"},{"id":313,"unit":2,"lesson":1,"word":"sanctuary","pronunciation":"/ˈsæŋktʃuəri/","meaning":"n.避难所;庇护;鸟兽保护区,禁猎区","seq":63,"isStar":false,"memo":"sanct(神圣的)+-(u)ary(表示场所的后缀)→神圣的地方→避难所","example":"The island was declared a wildlife sanctuary in 1969.该岛于1969年被宣布为野生动物保护区。"},{"id":314,"unit":2,"lesson":1,"word":"geology","pronunciation":"/dʒiˈɒlədʒi/","meaning":"n.地质学;(某地区的)地质","seq":64,"isStar":false,"memo":"(构词) geo-(地球，大地) + -logy(表示学科的名词后缀)→地质学","example":"We went on a geology field trip. 我们去进行野外地质考察。"},{"id":315,"unit":2,"lesson":1,"word":"geological","pronunciation":"/ˌdʒiːəˈlɒdʒɪkl/","meaning":"adj.地质(学)的","seq":65,"isStar":false},{"id":316,"unit":2,"lesson":1,"word":"geologically","pronunciation":"/ˌdʒiːəˈlɒdʒɪkli/","meaning":"adv.地质学上","seq":66,"isStar":false},{"id":317,"unit":2,"lesson":1,"word":"zoology","pronunciation":"/zuˈɒlədʒi/","meaning":"n.动物学","seq":67,"isStar":false,"memo":"zoo(动物)+-logy(表示学科的名词后缀)→动物学","example":"He is deeply interested in zoology.他对动物学有浓厚的兴趣。"},{"id":318,"unit":2,"lesson":1,"word":"zoological","pronunciation":"/ˌzuːəˈlɒdʒɪk(ə)l/","meaning":"adj.动物学的","seq":68,"isStar":false},{"id":319,"unit":2,"lesson":1,"word":"diagnose","pronunciation":"/ˈdaɪəɡnəʊz/","meaning":"v.诊断(疾病);判断","seq":69,"isStar":false,"memo":"(联想) dia(音似“打”) + g(联想“哥”) + nose(鼻子)→我不小心打了哥哥的鼻子，他得去医院“诊断”一下有无受伤。","example":"He was not aware of his illness until diagnosed with it. 直到被诊断出患有此病，他才意识到自己的病情。"},{"id":320,"unit":2,"lesson":1,"word":"diagnosis","pronunciation":"/ˌdaɪəɡˈnəʊsɪs/","meaning":"n.诊断;判断","seq":70,"isStar":false},{"id":321,"unit":2,"lesson":1,"word":"clinic","pronunciation":"/ˈklɪnɪk/","meaning":"n.诊所;临床实习","seq":71,"isStar":false,"memo":"(对照) 野餐(picnic)时吃坏了肚子得就近找个诊所(clinic)看病。","example":"The clinic provides free consultations for patients. 这个诊所为病患提供免费咨询。"},{"id":322,"unit":2,"lesson":1,"word":"clinical","pronunciation":"/ˈklɪnɪk(ə)l/","meaning":"adj.诊所的;临床的","seq":72,"isStar":false},{"id":323,"unit":2,"lesson":1,"word":"chronic","pronunciation":"/ˈkrɒnɪk/","meaning":"adj.慢性的;长期的","seq":73,"isStar":false,"memo":"[谐音] 单词发音类似“困扰你的”→慢性病可把人害苦了,让人深感困扰→慢性的","example":"Let's follow that example to battle the acute and chronic challenges that lie ahead. 让我们以此为榜样,与摆在面前的严峻和长期挑战作斗争。"},{"id":324,"unit":2,"lesson":1,"word":"chronically","pronunciation":"/ˈkrɒnɪkli/","meaning":"adv.慢性地;长期地","seq":74,"isStar":false},{"id":325,"unit":2,"lesson":1,"word":"chronicle","pronunciation":"/ˈkrɒnɪk(ə)l/","meaning":"n.编年史,大事记 v.把……载入编年史","seq":75,"isStar":false,"memo":"[联想] chronic(长期的)+(c)le(联想 circle) →历史就是一个环绕的、缓慢发展的过程→编年史,大事记","example":"Her achievements are chronicled in a new biography out this week. 她的成就已载入本周出版的一本新传记中。"},{"id":326,"unit":2,"lesson":1,"word":"benign","pronunciation":"/bɪˈnaɪn/","meaning":"adj.善良的,和善的,慈祥的;良性的","seq":76,"isStar":false,"memo":"[联想] be(是)+nign(音似“奶”)→我的奶奶是很“和善的”。","example":"You would never have guessed his intentions from the benign expression on his face. 从他脸上温和的表情你绝对猜不到他的意图。"},{"id":327,"unit":2,"lesson":1,"word":"wholesome","pronunciation":"/ˈhəʊlsəm/","meaning":"adj.有益健康的","seq":77,"isStar":false,"memo":"构词 whole(完整、健全)+-some(有…性质的)→使身体健全的→有益健康的","example":"Eating a variety of fruits and vegetables is a wholesome way to maintain good health.多吃各种水果和蔬菜是保持健康的一种有益方式。"},{"id":328,"unit":2,"lesson":1,"word":"malice","pronunciation":"/ˈmælɪs/","meaning":"n.恶意;怨恨","seq":78,"isStar":false,"memo":"[联想] ma(联想“妈”)+lice(联想 Alice,人名)→后妈对爱丽丝没有“恶意”。","example":"She is entirely without malice. 她完全没有恶意。"},{"id":329,"unit":2,"lesson":1,"word":"malicious","pronunciation":"/məˈlɪʃəs/","meaning":"adj.怀有恶意的,恶毒的","seq":79,"isStar":false,"memo":"构词 mal(坏，同 malignant 恶性的)+-icious(形容词后缀)→心里揣着坏水的→怀有恶意的","example":"It is the most malicious social evil of our time.这是我们这个时代最恶毒的社会弊端。"},{"id":330,"unit":2,"lesson":1,"word":"malignant","pronunciation":"/məˈlɪɡnənt/","meaning":"adj.恶性的,恶意的,恶毒的","seq":80,"isStar":false,"memo":"构词 malign(恶意、有害)+-ant(形容词后缀)→性质坏的→恶性的，恶毒的","example":"The doctors are worried that the tumor may be malignant.医生们担心肿瘤可能是恶性的。"},{"id":331,"unit":2,"lesson":1,"word":"contagious","pronunciation":"/kənˈteɪdʒəs/","meaning":"adj.接触传染的","seq":81,"isStar":false,"memo":"[构词] con-(一起)+tag(接触)+-ious(形容词后缀)→接触传染的","example":"The new disease proved contagious. 这种新的疾病证明具有传染性。"},{"id":332,"unit":2,"lesson":1,"word":"acute","pronunciation":"/əˈkjuːt/","meaning":"adj.严重的;敏锐的;急性的","seq":82,"isStar":false,"memo":"[对照] 一个可爱的(cute)孩子得了很严重的(acute)病。","example":"Punishment can never be an effective cure for acute social problems. 惩罚绝不是解决严重社会问题的有效办法。"},{"id":333,"unit":2,"lesson":1,"word":"fatal","pronunciation":"/ˈfeɪt(ə)l/","meaning":"adj.致命的;灾难性的","seq":83,"isStar":false,"memo":"谐音 单词发音类似“肥头”→婴儿得了肥头(大头病)是很“致命的”。","example":"There was a fatal flaw in the plan. 计划中有一个致命的缺陷。"},{"id":334,"unit":2,"lesson":1,"word":"fatality","pronunciation":"/fəˈtæləti/","meaning":"n.致命性;死亡;宿命","seq":84,"isStar":false},{"id":335,"unit":2,"lesson":1,"word":"severe","pronunciation":"/sɪˈvɪə(r)/","meaning":"adj.十分严重的;严厉的,苛刻的","seq":85,"isStar":false,"memo":"联想 sever(联想 seven)+e(联想 e-,出来)→七处隐患被排查出来,这是“十分严重的”问题。","example":"The storm caused severe damage. 这场暴风雨造成了严重的破坏。"},{"id":336,"unit":2,"lesson":1,"word":"severity","pronunciation":"/sɪˈverəti/","meaning":"n.严格,严厉;严重","seq":86,"isStar":false},{"id":337,"unit":2,"lesson":1,"word":"terminal","pronunciation":"/ˈtɜːmɪn(ə)l/","meaning":"n.航站楼;终点站;终端 adj.晚期的","seq":87,"isStar":false,"memo":"联想 term(学期,期限)+inal→属于某个时间期限的末端→终点站;晚期的","example":"He was eventually diagnosed as suffering from terminal cancer. 他最后被诊断患有晚期癌症。"},{"id":338,"unit":2,"lesson":1,"word":"terminate","pronunciation":"/ˈtɜːmɪneɪt/","meaning":"v.(使)结束;到达终点站","seq":88,"isStar":false,"memo":"谐音+构词：‘特敏内特’→特别敏感，一碰就‘终止’！term（界限）+inate→划到终点线，立刻停！","example":"The company will terminate the contract if the software fails security audits. 如果该软件未能通过安全审计，公司将终止合同。"},{"id":339,"unit":2,"lesson":1,"word":"perish","pronunciation":"/ˈperɪʃ/","meaning":"v.死亡;丧失;毁灭,毁灭;碎裂","seq":89,"isStar":false,"memo":"谐音 单词发音类似“拍蕊死”→把花朵的花蕊拍死,花朵就会“死亡”。","example":"Most of the butterflies perish in the first frosts of autumn. 大多数蝴蝶在秋季初霜来临时死亡。"},{"id":340,"unit":2,"lesson":1,"word":"destroy","pronunciation":"/dɪˈstrɔɪ/","meaning":"v.摧毁,毁灭;破坏","seq":90,"isStar":false,"memo":"构词 de-(向下、去除)+stroy(堆积)→把堆起来的东西推倒→摧毁，毁灭，破坏","example":"Destroying the machines that are coming for our jobs would be nuts. 摧毁即将取代我们工作的机器将是疯狂的。"},{"id":341,"unit":2,"lesson":1,"word":"destruction","pronunciation":"/dɪˈstrʌkʃ(ə)n/","meaning":"n.摧毁,毁灭;破坏","seq":91,"isStar":false},{"id":342,"unit":2,"lesson":1,"word":"destructive","pronunciation":"/dɪˈstrʌktɪv/","meaning":"adj.破坏性的","seq":92,"isStar":false},{"id":343,"unit":2,"lesson":1,"word":"devastate","pronunciation":"/ˈdevəsteɪt/","meaning":"v.摧毁,毁灭;使震惊;使极为忧伤","seq":93,"isStar":false,"memo":"联想 de-(向下;除去)+vast(广阔的)+-ate(动词后缀)→人们砍伐树木后,广阔的绿地被破坏→摧毁,毁灭","example":"The bomb devastated much of the old part of the city. 这颗炸弹炸毁了旧城的一大片地方。"},{"id":344,"unit":2,"lesson":1,"word":"devastating","pronunciation":"/ˈdevəsteɪtɪŋ/","meaning":"adj.毁灭性的;令人震惊的","seq":94,"isStar":false},{"id":345,"unit":2,"lesson":1,"word":"devastation","pronunciation":"/ˌdevəˈsteɪʃn/","meaning":"n.毁灭;破坏","seq":95,"isStar":false},{"id":346,"unit":2,"lesson":1,"word":"remedy","pronunciation":"/ˈremədi/","meaning":"n.治疗,疗法;解决办法 v.改正;改进","seq":96,"isStar":false,"memo":"对照 把悲剧(tragedy)变成喜剧(comedy)是一种解决办法(remedy)。","example":"The best remedy for grief is hard work. 排解忧伤的最好办法就是努力工作。"},{"id":347,"unit":2,"lesson":1,"word":"remedial","pronunciation":"/rɪˈmiːdiəl/","meaning":"adj.补救的;辅导的","seq":97,"isStar":false},{"id":348,"unit":2,"lesson":1,"word":"therapy","pronunciation":"/ˈθerəpi/","meaning":"n.治疗,疗法","seq":98,"isStar":false,"memo":"构词 therap(治疗，同 therapeutic)+-y(名词后缀)→治疗的办法→治疗，疗法","example":"I was ready for a little retail therapy. 我准备去进行一下购物治疗。"},{"id":349,"unit":2,"lesson":1,"word":"therapist","pronunciation":"/ˈθerəpɪst/","meaning":"n.(某治疗法的)治疗专家","seq":99,"isStar":false},{"id":350,"unit":2,"lesson":1,"word":"therapeutic(al)","pronunciation":"/ˌθerəˈpjuːtɪk/","meaning":"adj.治疗的","seq":100,"isStar":false,"memo":"构词 therap(治疗)+-eutic(形容词后缀)→与治疗有关的→治疗的","example":"The hot springs are famous for their therapeutic effects. 这些温泉以疗效闻名。"},{"id":351,"unit":2,"lesson":1,"word":"salvation","pronunciation":"/sælˈveɪʃ(ə)n/","meaning":"n.解救;解救途径","seq":101,"isStar":false,"memo":"(记) (联想) salv(联想 save)+-ation(名词后缀)→解救","example":"Group therapy classes have been his salvation.集体治疗课程成了他的救赎。"},{"id":352,"unit":2,"lesson":1,"word":"surgery","pronunciation":"/ˈsɜːdʒəri/","meaning":"n.外科手术;外科学","seq":102,"isStar":false,"memo":"构词 surg(外科，同 surgeon 外科医生)+-ery(名词后缀)→外科医生做的事→外科手术；外科学","example":"Good news. I'm not going to have surgery. 好消息,我不需要做手术了。"},{"id":353,"unit":2,"lesson":1,"word":"surgical","pronunciation":"/ˈsɜːdʒɪkl/","meaning":"adj.外科的,外科手术的","seq":103,"isStar":false},{"id":354,"unit":2,"lesson":1,"word":"surgeon","pronunciation":"/ˈsɜːdʒən/","meaning":"n.外科医生","seq":104,"isStar":false,"example":"I knew that I owed the surgeon my life.我知道我欠这位外科医生一条命。"},{"id":355,"unit":2,"lesson":1,"word":"physician","pronunciation":"/fɪˈzɪʃ(ə)n/","meaning":"n.医生,(尤指)内科医生","seq":105,"isStar":false,"memo":"【构词】physic(身体,医学)+-ian(表示人的后缀)→内科医生","example":"My father is busy because he is a physician. 我父亲很忙,因为他是一名医生。"},{"id":356,"unit":2,"lesson":1,"word":"medication","pronunciation":"/ˌmedɪˈkeɪʃn/","meaning":"n.药,药物","seq":106,"isStar":false,"memo":"构词 medic(医，同 medicine)+-ation(名词后缀)→医生开的药→药物，药","example":"Exposure to excessive medication may increase emotional tears.过度接触药物可能会增加情绪性流泪。"},{"id":357,"unit":2,"lesson":1,"word":"tablet","pronunciation":"/ˈtæblət/","meaning":"n.药片","seq":107,"isStar":false,"memo":"【谐音】单词发音类似“他不离它”→他生病后离不开吃“药片”。","example":"She took a couple of headache tablets. 她吃了几片治头痛的药。"},{"id":358,"unit":2,"lesson":1,"word":"portable","pronunciation":"/ˈpɔːtəb(ə)l/","meaning":"adj.便携式的;手提的 n.手提电脑","seq":108,"isStar":false,"memo":"【谐音】单词发音类似“泡腾的”→维生素泡腾片很容易携带→便携式的","example":"We bought a portable last week. 我们上周买了一台手提电脑。"},{"id":359,"unit":2,"lesson":1,"word":"rescue","pronunciation":"/ˈreskjuː/","meaning":"n.&v.营救,救赎","seq":109,"isStar":false,"memo":"【联想】re-(回)+s(联想“女孩”)+cue(联想cute)→快回去“营救”那个可爱的女孩。","example":"Robots are coming to the rescue. 机器人正前来救援。"},{"id":360,"unit":2,"lesson":1,"word":"obscure","pronunciation":"/əbˈskjʊə(r)/","meaning":"adj.鲜为人知的;模糊的","seq":110,"isStar":false,"memo":"【联想】ob-(表示方向,对)+s(联想“女孩”)+cure(治疗)→他对那个视线“模糊的”女孩进行治疗。","example":"Differences between races are deliberately obscured. 种族之间的差异被刻意掩盖。"},{"id":361,"unit":2,"lesson":1,"word":"obscurity","pronunciation":"/əbˈskjʊərəti/","meaning":"n.费解,晦涩;默默无闻","seq":111,"isStar":false,"memo":"构词 ob-(在…上)+scur(遮盖，同 obscure 模糊的)+-ity(名词后缀)→被盖住看不清→费解，晦涩；默默无闻","example":"He lived in obscurity for many years. 他默默无闻地生活了很多年。"},{"id":362,"unit":2,"lesson":1,"word":"vague","pronunciation":"/veɪɡ/","meaning":"adj.模糊的,不清楚的","seq":112,"isStar":false,"memo":"【谐音】单词发音类似“喂哥”→他听见有个“模糊的”声音喊“喂,哥”。","example":"Through the mist I could just make out a vague figure. 透过薄雾,我只能看见一个模糊的人影。"},{"id":363,"unit":2,"lesson":1,"word":"secure","pronunciation":"/sɪˈkjʊə(r)/","meaning":"adj.安全的;可靠的,稳固的 v.保护","seq":113,"isStar":false,"memo":"【构词】se-(分开)+cure(=care)→把担心分开,即不需要担心了→安全的","example":"Your foundation is already secure. 你的基础已经稳固了。"},{"id":364,"unit":2,"lesson":1,"word":"security","pronunciation":"/sɪˈkjʊərəti/","meaning":"n.安全;抵押品;安保","seq":114,"isStar":false,"memo":"构词 se-(分离，此处表没有)+cur(关心，同 cure 治疗)+-ity(名词后缀)→不用再担忧的状态→安全；抵押品，安保","example":"The airport has tightened its security. 机场已经加强了安保。"},{"id":365,"unit":2,"lesson":1,"word":"consecutive","pronunciation":"/kənˈsekjətɪv/","meaning":"adj.连续不断的","seq":115,"isStar":false,"memo":"【联想】con-(所有的)+secu(联想secure)+-tive(形容词后缀)→所有的日子都是安全的→连续不断的","example":"Most people in the business would agree that consecutive interpreting is more stressful. 业内大多数人都认为交替传译的压力更大。"},{"id":366,"unit":2,"lesson":2,"word":"carbohydrate","pronunciation":"/ˌkɑːbəʊˈhaɪdreɪt/","meaning":"n.碳水化合物","seq":1,"isStar":false,"memo":"构词 carbo(n)(碳) + hydr(水、氢) + -ate (名词后缀)→碳水化合物","example":"Nuts are high in carbohydrates.坚果中碳水化合物含量很高。"},{"id":367,"unit":2,"lesson":2,"word":"saturate","pronunciation":"/ˈsætʃəreɪt/","meaning":"v.使湿透;使充满;使饱和","seq":2,"isStar":false,"memo":"[联想] sa(音似“塞”) + tur(联想 true) + -ate (动词后缀) → 我的包真的塞满了 → 使充满;使饱和","example":"The continuous rain had saturated the soil. 连绵不断的雨使土地湿透了。"},{"id":368,"unit":2,"lesson":2,"word":"saturation","pronunciation":"/ˌsætʃəˈreɪʃn/","meaning":"n.饱和;饱和状态;饱和度","seq":3,"isStar":false},{"id":369,"unit":2,"lesson":2,"word":"drain","pronunciation":"/dreɪn/","meaning":"n.排水;下水道;消耗 v.排出;使耗尽","seq":4,"isStar":false,"memo":"[对照] 他们把雨水(rain)倒进了下水道(drain)。","example":"We can drain the rivers today. 今天我们可以排干河水。"},{"id":370,"unit":2,"lesson":2,"word":"drainage","pronunciation":"/ˈdreɪnɪdʒ/","meaning":"n.排水;放水","seq":5,"isStar":false},{"id":371,"unit":2,"lesson":2,"word":"mud","pronunciation":"/mʌd/","meaning":"n.泥,淤泥","seq":6,"isStar":false,"memo":"[联想] mu(联想“木”) + d(联想“的”) → 树木的根在“泥”土里。","example":"The car wheels got stuck in the mud. 汽车轮子陷到泥里去了。"},{"id":372,"unit":2,"lesson":2,"word":"muddy","pronunciation":"/ˈmʌdi/","meaning":"adj.多泥的,泥泞的","seq":7,"isStar":false},{"id":373,"unit":2,"lesson":2,"word":"dirt","pronunciation":"/dɜːt/","meaning":"n.污物;泥土;灰尘;丑闻","seq":8,"isStar":false,"memo":"[联想] di(联想“敌”) + r(联想“人”) + t(联想“特”) → 敌人被我们打得满身“泥土”,特别狼狈。","example":"Dirt from the road made him cough. 路上的灰尘使他咳嗽起来。"},{"id":374,"unit":2,"lesson":2,"word":"dirty","pronunciation":"/ˈdɜːti/","meaning":"adj.肮脏的,龌龊的;污秽的","seq":9,"isStar":false},{"id":375,"unit":2,"lesson":2,"word":"trench","pronunciation":"/trentʃ/","meaning":"n.沟,渠;战壕;海沟","seq":10,"isStar":false,"memo":"[联想] tren(音似“蹭”) + ch(联想“吃”) → 骗子被踹到“沟”里,吃了一嘴泥。","example":"With virtual reality we’ll be able to put a surgeon in every trench. 有了虚拟现实技术,我们就可以在每条战壕里安插一名外科医生。"},{"id":376,"unit":2,"lesson":2,"word":"renew","pronunciation":"/rɪˈnjuː/","meaning":"v.重新开始;延长期限;更新","seq":11,"isStar":false,"memo":"构词 re-(重新) + new(新)→重新开始;更新","example":"The man is going to renew his membership in a fitness center. 这位男士打算续订他在健身中心的会员资格。"},{"id":377,"unit":2,"lesson":2,"word":"renewable","pronunciation":"/rɪˈnjuːəb(ə)l/","meaning":"n.可再生能源 adj.可更新的","seq":12,"isStar":false},{"id":378,"unit":2,"lesson":2,"word":"renewal","pronunciation":"/rɪˈnjuːəl/","meaning":"n.恢复;更新;重新开始","seq":13,"isStar":false},{"id":379,"unit":2,"lesson":2,"word":"refresh","pronunciation":"/rɪˈfreʃ/","meaning":"v.使恢复精力;使清凉;更新","seq":14,"isStar":false,"memo":"构词 re-(重新) + fresh(精力充沛;凉爽的)→使恢复精力;使清凉","example":"The lotion cools and refreshes the skin. 这款润肤液使皮肤凉爽清新。"},{"id":380,"unit":2,"lesson":2,"word":"refreshment","pronunciation":"/rɪˈfreʃmənt/","meaning":"n.点心;恢复精力","seq":15,"isStar":false,"memo":"re-（再）+ fresh（新鲜）+ -ment → ‘再新鲜一下’！茶歇不是吃，是给脑子‘刷新缓存’。","example":"Students grabbed refreshments between exam sessions in the library lounge. 学生们在考试间隙到图书馆休息区取用茶点。"},{"id":381,"unit":2,"lesson":2,"word":"stale","pronunciation":"/steɪl/","meaning":"adj.不新鲜的;厌倦的;没有新意的","seq":16,"isStar":false,"memo":"联想 s(联想“美女蛇”)+tale(故事)→关于美女蛇的故事太多了,没人想听这种“没有新意”的故事了。","example":"They prohibit the sale of foods that have gone stale. 他们禁止出售变质的食品。"},{"id":382,"unit":2,"lesson":2,"word":"outdated","pronunciation":"/ˌaʊtˈdeɪtɪd/","meaning":"adj.过时的,陈旧的","seq":17,"isStar":false,"memo":"对照 out of date 过时的;过期的 → outdated adj.","example":"This outdated equipment is dangerous. 这台过时的设备很危险。"},{"id":383,"unit":2,"lesson":2,"word":"old-fashioned","pronunciation":"/ˌəʊld ˈfæʃ(ə)nd/","meaning":"adj.陈旧的,过时的;守旧的","seq":18,"isStar":false,"memo":"构词 old(旧的)+fashioned(……样式的)→陈旧的,过时的","example":"The whole room looked old-fashioned.整个房间看起来过时了。"},{"id":384,"unit":2,"lesson":2,"word":"update","pronunciation":"/ˌʌpˈdeɪt/","meaning":"n.最新消息;更新 v.使现代化;更新","seq":19,"isStar":false,"memo":"构词 up(往上) + date(日期)→更新\n对照 up to date 最新的,现代的→update n. & v.","example":"It's about time we updated our software. 是时候更新我们的软件了。"},{"id":385,"unit":2,"lesson":2,"word":"upgrade","pronunciation":"/ˌʌpˈɡreɪd/","meaning":"v.升级;提高;改进 n.升级","seq":20,"isStar":false,"memo":"构词 up(往上) + grade(等级) → 升级","example":"We are constantly upgrading our software to meet customers’ needs. 我们不断升级软件，以满足用户的需要。"},{"id":386,"unit":2,"lesson":2,"word":"recur","pronunciation":"/rɪˈkɜː(r)/","meaning":"v.再发生;反复出现","seq":21,"isStar":false,"memo":"构词 re-(再) + (oc)cur(发生) → 再发生","example":"Otherwise, the overtraining syndrome is likely to recur. 否则，过度训练综合征很可能会复发。"},{"id":387,"unit":2,"lesson":2,"word":"recurrence","pronunciation":"/rɪˈkʌrəns/","meaning":"n.重现;复发","seq":22,"isStar":false},{"id":388,"unit":2,"lesson":2,"word":"occur","pronunciation":"/əˈkɜː(r)/","meaning":"v.发生;出现","seq":23,"isStar":false,"memo":"谐音 单词发音类似“我磕”→我磕到腿了，“发生”事故了。","example":"Improvement of an athlete’s performance occurs in the course of training. 运动员成绩的提高是在训练过程中出现的。"},{"id":389,"unit":2,"lesson":2,"word":"occurrence","pronunciation":"/əˈkʌrəns/","meaning":"n.出现;发生","seq":24,"isStar":false},{"id":390,"unit":2,"lesson":2,"word":"curb","pronunciation":"/kɜːb/","meaning":"n.&v.控制,抑制;约束","seq":25,"isStar":false,"memo":"联想 cur(联想 occur) + b(联想“不”) → 不让一件事情发生，我们就要“控制”它。","example":"High taxes on alcohol are meant to curb excessive drinking. 对酒征收高额税款旨在限制过度饮酒。"},{"id":391,"unit":2,"lesson":2,"word":"incur","pronunciation":"/ɪnˈkɜː(r)/","meaning":"v.招致;遭受;引起","seq":26,"isStar":false,"memo":"联想 in(里面) + cur(联想 occur) → 家里面发生了事，可能会“引起”很大的麻烦。","example":"It incurs a high environmental price. 它会招致高昂的环境代价。"},{"id":392,"unit":2,"lesson":2,"word":"resource","pronunciation":"/rɪˈsɔːs/","meaning":"n.资源;财力;资料;智谋","seq":27,"isStar":false,"memo":"联想 re-(重复) + source(源头) → 想要重复找到金矿的源头，是需要很多“资源”和“财力”的。","example":"We are learning, that forest is a natural resource and must be protected by law. 我们认识到，森林是一种自然资源，必须受到法律保护。"},{"id":393,"unit":2,"lesson":2,"word":"resourceful","pronunciation":"/rɪˈsɔːsf(ə)l/","meaning":"adj.机敏的;足智多谋的","seq":28,"isStar":false},{"id":394,"unit":2,"lesson":2,"word":"recycle","pronunciation":"/ˌriːˈsaɪkl/","meaning":"v.回收,再循环","seq":29,"isStar":false,"memo":"联想 re-(再，重复) + cycle(音似 circle) → 让事物再次循环转起来 → 回收，再循环","example":"We should try to recycle the waste to save resources. 为了节约资源，我们应该设法回收废物。"},{"id":395,"unit":2,"lesson":2,"word":"recyclable","pronunciation":"/ˌriːˈsaɪkləbl/","meaning":"adj.可回收利用的,可再循环的","seq":30,"isStar":false,"memo":"构词 recycl(e)(再循环)+-able(形容词后缀)→可再循环的","example":"Their products are recyclable.他们的产品是可回收的。"},{"id":396,"unit":2,"lesson":2,"word":"triple","pronunciation":"/ˈtrɪp(ə)l/","meaning":"v.成为三倍,使增至三倍 adj.三倍的","seq":31,"isStar":false,"memo":"构词 tri(三) + -ple(表示倍数) → 三倍的","example":"It expects its revenues almost to triple this year. 该公司预计今年的收入将增至三倍。"},{"id":397,"unit":2,"lesson":2,"word":"tribe","pronunciation":"/traɪb/","meaning":"n.部落;一大群人","seq":32,"isStar":false,"memo":"联想 tri(三) + be(音似“部”) → 三个部 → 部落","example":"He wanted to amuse the people of the local tribes. 他想逗当地部落的人开心。"},{"id":398,"unit":2,"lesson":2,"word":"tribal","pronunciation":"/ˈtraɪb(ə)l/","meaning":"adj.部落成员 adj.部落的","seq":33,"isStar":false},{"id":399,"unit":2,"lesson":2,"word":"trivial","pronunciation":"/ˈtrɪviəl/","meaning":"adj.不重要的,琐碎的,微不足道的","seq":34,"isStar":false,"memo":"tri(三) + vi(形似罗马数字6) + al(联想all)→三姑六婆关心的通常都是些“琐碎的”事情。","example":"Yet that is a rather trivial aspect of the matter. 然而，那只是事情的一个相当微不足道的方面。"},{"id":400,"unit":2,"lesson":2,"word":"via","pronunciation":"/ˈvaɪə/","meaning":"prep.经过;通过","seq":35,"isStar":false,"memo":"vi(形似罗马数字6) + a(形似小乌龟) →兔子去河对岸吃草要“经过”六只小乌龟。","example":"The news programme came to us via satellite. 新闻节目通过卫星传送到我们这里来。"},{"id":401,"unit":2,"lesson":2,"word":"virtue","pronunciation":"/ˈvɜːtʃuː/","meaning":"n.美德;优点","seq":36,"isStar":false,"memo":"vi(形似罗马数字6) + r(形似花) + tue(音似true)→我们得到六朵小红花,说明我们的“优点”和“美德”真的多。","example":"Patience is a virtue. 耐心是一种美德。"},{"id":402,"unit":2,"lesson":2,"word":"virtuous","pronunciation":"/ˈvɜːtʃuəs/","meaning":"adj.品行端正的,有德行的","seq":37,"isStar":false},{"id":403,"unit":2,"lesson":2,"word":"navigate","pronunciation":"/ˈnævɪɡeɪt/","meaning":"v.导航;航行,航海","seq":38,"isStar":false,"memo":"联想 na(联想“那”)+vi(形似罗马数字6)+","example":"The river became too narrow and shallow to navigate. 河水变得又窄又浅，无法通航。"},{"id":404,"unit":2,"lesson":2,"word":"navigation","pronunciation":"/ˌnævɪˈɡeɪʃ(ə)n/","meaning":"n.导航,领航;航行","seq":39,"isStar":false},{"id":405,"unit":2,"lesson":2,"word":"deviate","pronunciation":"/ˈdiːvieɪt/","meaning":"v.背离;偏离;违背","seq":40,"isStar":false,"memo":"de(音似“弟”) + vi(形似罗马数字6) + -ate(动词后缀)→弟弟和他的六个小伙伴走散了,“偏离”了目的地。","example":"Each workday, the workers followed the same schedules and rarely deviated from this routine. 每个工作日,工人们都遵循着同样的时间表,很少偏离这种常规。"},{"id":406,"unit":2,"lesson":2,"word":"deviation","pronunciation":"/ˌdiːviˈeɪʃn/","meaning":"n.偏离;违背;偏差","seq":41,"isStar":false},{"id":407,"unit":2,"lesson":2,"word":"indispensable","pronunciation":"/ˌɪndɪˈspensəb(ə)l/","meaning":"adj.不可或缺的,必不可少的","seq":42,"isStar":false,"memo":"in-(表否定) + dis-(表否定) + pens (钢笔) + -able(形容词后缀)→不能没有钢笔的→不可或缺的,必不可少的","example":"High-price drugs are indispensable in curing some chronic diseases. 高价药物对于治疗某些慢性疾病不可或缺。"},{"id":408,"unit":2,"lesson":2,"word":"essence","pronunciation":"/ˈes(ə)ns/","meaning":"n.本质;精髓;精华;精油","seq":43,"isStar":false,"memo":"构词 ess(存在，同 essential)+-ence(名词后缀)→真正存在的那一部分→本质，精髓，精华","example":"His theory was not new in essence. 他的理论实质上并不新颖。"},{"id":409,"unit":2,"lesson":2,"word":"essential","pronunciation":"/ɪˈsenʃ(ə)l/","meaning":"n.必需品;必不可少的东西;要素","seq":44,"isStar":false,"memo":"构词 ess(存在)+-ential(形容词后缀)→非存在不可的→必不可少的；要素，要点","example":"Pursuing a career is an essential part of adolescent development. 追求职业生涯是青少年发展的一个必不可少的部分。"},{"id":410,"unit":2,"lesson":2,"word":"fundamental","pronunciation":"/ˌfʌndəˈment(ə)l/","meaning":"adj.根本的;基本的","seq":45,"isStar":false,"memo":"联想 fund(资金)+a+mental(精神的)→物质和精神对人的发展都是“必不可少的”。","example":"Diversity, it seems, has not helped to address fundamental weaknesses in business leadership. 多元化似乎并没有帮助解决企业领导力的根本弱点。"},{"id":411,"unit":2,"lesson":2,"word":"foundation","pronunciation":"/faʊnˈdeɪʃ(ə)n/","meaning":"n.基础;根据;创办;基金会;地基","seq":46,"isStar":false,"memo":"构词 found(建立)+-ation(名词后缀)→基础;创办;地基","example":"This provided a solid foundation for their marriage. 这为他们的婚姻提供了坚实的基础。"},{"id":412,"unit":2,"lesson":2,"word":"cornerstone","pronunciation":"/ˈkɔːnəstəʊn/","meaning":"n.基石;基础","seq":47,"isStar":false,"memo":"构词 corner(角落)+stone(石头)→基石;基础","example":"The college students had cultivated the ability to ask questions, the cornerstone of critical thinking.大学生培养了提问的能力，这是批判性思维的基石。"},{"id":413,"unit":2,"lesson":2,"word":"milestone","pronunciation":"/ˈmaɪlstəʊn/","meaning":"n.重要事件;里程碑","seq":48,"isStar":false,"memo":"构词 mile(英里)+stone(石头)→每英里设置的界石,用来标记距离→里程碑","example":"It's one of the greatest milestones in my life. 这是我生命中的重要事件之一。"},{"id":414,"unit":2,"lesson":2,"word":"landmark","pronunciation":"/ˈlændmɑːk/","meaning":"n.地标;里程碑","seq":49,"isStar":false,"memo":"构词 land(陆地)+mark(标记)→地标;里程碑","example":"Streets, landmarks and places of interest are included. 街道、地标和名胜都被包括在内。"},{"id":415,"unit":2,"lesson":2,"word":"crucial","pronunciation":"/ˈkruːʃ(ə)l/","meaning":"adj.至关重要的,关键的","seq":50,"isStar":false,"memo":"谐音 单词发音类似“可入手”→可以入手的东西是“至关重要的”。","example":"And with such purchases, price is only one of many crucial factors to consider. 对于这样的购买行为,价格只是需要考虑的众多关键因素之一。"},{"id":416,"unit":2,"lesson":2,"word":"cardinal","pronunciation":"/ˈkɑːdɪn(ə)l/","meaning":"adj.最重要的;基本的 n.枢机主教","seq":51,"isStar":false,"memo":"联想 card(卡片)+in(在……里面)+al(联想 all)→这张卡是所有卡里“最重要的”。","example":"As a salesman, your cardinal rule is to do everything you can to satisfy a customer. 作为一名推销员,你的首要原则就是要尽你所能使客户满意。"},{"id":417,"unit":2,"lesson":2,"word":"imperative","pronunciation":"/ɪmˈperətɪv/","meaning":"adj.重要紧急的","seq":52,"isStar":false,"memo":"联想 i(我)+m(联想“妹”)+per(每)+ative(联想 active)→我妹妹每天都很积极、主动地工作,因为她在做“重要紧急的事”。","example":"It is most imperative to focus our efforts on the elimination of income inequality. 最重要的是,我们要集中力量消除收入不平等。"},{"id":418,"unit":2,"lesson":2,"word":"necessary","pronunciation":"/ˈnesəsəri/","meaning":"adj.必需的,必要的","seq":53,"isStar":false,"memo":"谐音 单词发音类似“奶是色弱”→奶奶色弱,帮她辨别颜色是“必要的”。","example":"Food is necessary for survival. 食物是生存所必需的。"},{"id":419,"unit":2,"lesson":2,"word":"necessarily","pronunciation":"/ˌnesəˈserəli/","meaning":"adv.必然地,不可避免地","seq":54,"isStar":false,"memo":"构词 necess(必要，同 necessary)+-ary+-ly(副词后缀)→按必要的逻辑推下去→必然地","example":"A good teacher is not necessarily a popular one. 好老师未必受欢迎。"},{"id":420,"unit":2,"lesson":2,"word":"necessity","pronunciation":"/nəˈsesəti/","meaning":"n.必然;必要;需要","seq":55,"isStar":false,"memo":"【谐音】'内需丝提'——内需是刚需！词根 nec-（need）+ -ess（名词）+ -ity（性质），直指‘必须性’。","example":"Clean water is a basic necessity for all human communities. 清洁水源是所有人类社区的基本必需品。"},{"id":421,"unit":2,"lesson":2,"word":"necessitate","pronunciation":"/nəˈsesɪteɪt/","meaning":"v.使成为必要","seq":56,"isStar":false,"memo":"构词 necess(必要)+-itate(动词后缀)→使某事成为必要→使成为必要","example":"Increased traffic necessitated widening the road.交通量的增加使拓宽道路成为必要。"},{"id":422,"unit":2,"lesson":2,"word":"primary","pronunciation":"/ˈpraɪməri/","meaning":"adj.主要的;最重要的","seq":57,"isStar":false,"memo":"对照 小学(primary school)教育是最初的(primary)教育。","example":"Primary care should be the backbone of any health care system. 初级保健应该成为任何卫生保健系统的支柱。"},{"id":423,"unit":2,"lesson":2,"word":"primarily","pronunciation":"/praɪˈmerəli/","meaning":"adv.主要地;根本地","seq":58,"isStar":false},{"id":424,"unit":2,"lesson":2,"word":"secondary","pronunciation":"/ˈsekənd(ə)ri/","meaning":"adj.次要的;从属的;中学的","seq":59,"isStar":false,"memo":"构词 second(第二)+-ary(形容词后缀)→次要的","example":"Concepts and contextual implications are of secondary importance to journalistic interviewing. 对于新闻采访来说,概念和语境的暗示是次要的。"},{"id":425,"unit":2,"lesson":2,"word":"primitive","pronunciation":"/ˈprɪmətɪv/","meaning":"adj.原始的;本能的","seq":60,"isStar":false,"memo":"构词 prim(最初,原始)+-itive(形容词后缀)→原始的","example":"In primitive times, human beings did not travel for pleasure but to find a more favourable climate. 在原始时期,人类旅行不是为了乐趣,而是为了寻找更有利的气候环境。"},{"id":426,"unit":2,"lesson":2,"word":"prime","pronunciation":"/praɪm/","meaning":"adj.最重要的,首要的","seq":61,"isStar":false,"memo":"联想 pri(第一,首要)+me(我)→我是“首要的”。","example":"The emotional and physical stress that occurs due to odd working hours is a prime reason for a large amount of career dissatisfaction. 由于不规律的工作时间产生的情绪和身体压力是造成大量职业不满的主要原因。"},{"id":427,"unit":2,"lesson":2,"word":"prior","pronunciation":"/ˈpraɪə(r)/","meaning":"adj.先前的;较早的;优先的","seq":62,"isStar":false,"memo":"联想 pri-(=pre-,前)+or(联想“表示人的后缀”)→先前的;较早的","example":"Please give us prior notice if you need an evening meal. 如果您需要用晚餐,请预先通知我们。"},{"id":428,"unit":2,"lesson":2,"word":"priority","pronunciation":"/praɪˈɒrəti/","meaning":"n.优先事项,当务之急","seq":63,"isStar":false,"memo":"构词 pri(前，同 prior 在先的)+-ority(名词后缀)→排在前面的事→优先事项，优先权","example":"Priority should be given to the economic needs of senior citizens. 应该优先考虑老年人的经济需求。"},{"id":429,"unit":2,"lesson":3,"word":"spot","pronunciation":"/spɒt/","meaning":"n.斑点;污渍;场所 v.看见,注意到","seq":1,"isStar":false,"memo":"s(联想“美女”)+pot(音似“泡它”)→一个美女泡茶时把“污渍”弄到身上了。","example":"On a trip, a person can learn directly by visiting museums and historic spots. 在旅行中,一个人可以通过参观博物馆和历史景点直接学习。"},{"id":430,"unit":2,"lesson":3,"word":"pottery","pronunciation":"/ˈpɒtəri/","meaning":"n.陶器;陶土;制陶手艺;制陶厂","seq":2,"isStar":false,"memo":"对照 我们这个做泡菜用的坛子(pot)是用陶土(pottery)烧制而成的。","example":"The widespread presence of pottery confirms the soil’s human origins.陶器的大范围出现证实了这片土壤有人类起源。"},{"id":431,"unit":2,"lesson":3,"word":"spotlight","pronunciation":"/ˈspɒtlaɪt/","meaning":"n.聚光灯 v.使突出,使显眼","seq":3,"isStar":false,"memo":"构词 spot(点)+light(光)→聚光灯","example":"The budget crisis also spotlighted a weakening economy.预算危机也凸显了经济疲软。"},{"id":432,"unit":2,"lesson":3,"word":"potential","pronunciation":"/pəˈtenʃ(ə)l/","meaning":"n.潜能,潜力 adj.潜在的,可能的","seq":4,"isStar":false,"memo":"单词发音类似“陪他瘦”→陪他一起瘦,我有这个“潜能”。","example":"As incomes rise among low-income consumers, the potential for further grain consumption is huge. 随着低收入消费者的收入增加,粮食消费进一步增加的潜力巨大。"},{"id":433,"unit":2,"lesson":3,"word":"potentiality","pronunciation":"/pəˌtenʃiˈæləti/","meaning":"n.潜力;潜在的可能性","seq":5,"isStar":false},{"id":434,"unit":2,"lesson":3,"word":"permanent","pronunciation":"/ˈpɜːmənənt/","meaning":"adj.永久的,永恒的","seq":6,"isStar":false,"memo":"per(每)+man(人)+ent(联想enter)→每个人都想进入这座房子,让它成为自己“永久的”住所。","example":"The only real solution appears to be to hand over the night shift to a number of permanent night workers. 唯一的真正解决方法似乎是将夜班交给一些长期的夜间工作者。"},{"id":435,"unit":2,"lesson":3,"word":"permanence","pronunciation":"/ˈpɜːmənəns/","meaning":"n.永久;持久性","seq":7,"isStar":false},{"id":436,"unit":2,"lesson":3,"word":"perpetual","pronunciation":"/pəˈpetʃuəl/","meaning":"adj.不间断的,持续的;永久的","seq":8,"isStar":false,"memo":"per(每)+pet(宠物)+-ual(形容词后缀)→她每天喂养她的宠物,从不间断→不间断的","example":"Because of the perpetual noise of traffic, I couldn't get to sleep last night. 由于交通噪声不断,我昨晚无法入睡。"},{"id":437,"unit":2,"lesson":3,"word":"perpetuate","pronunciation":"/pəˈpetʃueɪt/","meaning":"v.使永久化;使持久化;使持续","seq":9,"isStar":false},{"id":438,"unit":2,"lesson":3,"word":"eternal","pronunciation":"/ɪˈtɜːn(ə)l/","meaning":"adj.永恒的,永远的","seq":10,"isStar":false,"memo":"联想 eter(音似“一特”) + n(形似门) + -al (形容词后缀) → 这一扇特色之门是城市“永恒 的”印记。","example":"A wedding ring is a symbol of eternal love. 结婚戒指是永恒爱情的象征。"},{"id":439,"unit":2,"lesson":3,"word":"eternity","pronunciation":"/ɪˈtɜːnəti/","meaning":"n.永恒;永生;不朽","seq":11,"isStar":false},{"id":440,"unit":2,"lesson":3,"word":"permeate","pronunciation":"/ˈpɜːmieɪt/","meaning":"v.弥漫,渗透","seq":12,"isStar":false,"memo":"联想 per(每) + meat(肉) + e(联想“鹅”) → 每次我在家炖鹅肉，香味都会“弥漫”于整个房间。","example":"Eventually, the water will permeate through the surrounding concrete. 最终，水会渗透进周围的混凝土中。"},{"id":441,"unit":2,"lesson":3,"word":"permeation","pronunciation":"/ˌpɜːmiˈeɪʃn/","meaning":"n.渗透","seq":13,"isStar":false},{"id":442,"unit":2,"lesson":3,"word":"blend","pronunciation":"/blend/","meaning":"v.使混合,融合 n.混合物","seq":14,"isStar":false,"memo":"联想 b(联想“不”) + lend(借) → 不要把书借给他，因为他会把书弄混的 → 使混合","example":"It is a delicacy blended with bread. 这是一种与面包混合而成的美食。"},{"id":443,"unit":2,"lesson":3,"word":"tangle","pronunciation":"/ˈtæŋɡ(ə)l/","meaning":"n.乱糟糟的一堆;混乱","seq":15,"isStar":false,"memo":"谐音 单词发音类似“探戈”→很多人在一起跳探戈，场面有点“混乱”。","example":"Her hair tends to tangle. 她的头发易打结。"},{"id":444,"unit":2,"lesson":3,"word":"mess","pronunciation":"/mes/","meaning":"n.肮脏;杂乱 v.弄乱","seq":16,"isStar":false,"memo":"联想 me(我) + ss(音似“死”) → 回到家看到“杂乱”的一堆衣服，我烦得要死。","example":"The kids made a mess in the bathroom. 孩子们把浴室搞得一塌糊涂。"},{"id":445,"unit":2,"lesson":3,"word":"messy","pronunciation":"/ˈmesi/","meaning":"adj.肮脏的;凌乱的","seq":17,"isStar":false},{"id":446,"unit":2,"lesson":3,"word":"chaos","pronunciation":"/ˈkeɪɒs/","meaning":"n.混乱,杂乱","seq":18,"isStar":false,"memo":"联想 chao(联想“吵”) + s(联想“死”) → 这条街上吵死了，场面很“混乱”。","example":"Heavy snow has caused total chaos on the roads. 大雪导致道路上交通一片混乱。"},{"id":447,"unit":2,"lesson":3,"word":"chaotic","pronunciation":"/keɪˈɒtɪk/","meaning":"adj.混乱的","seq":19,"isStar":false},{"id":448,"unit":2,"lesson":3,"word":"chore","pronunciation":"/tʃɔː(r)/","meaning":"n.日常事务;乏味无聊的工作","seq":20,"isStar":false,"memo":"谐音 单词发音类似“瞧”→他每天瞧着妈妈做“日常事务”。","example":"Paying an allowance for completing chores benefits children. 为完成家务支付零花钱对孩子有益。"},{"id":449,"unit":2,"lesson":3,"word":"disorder","pronunciation":"/dɪsˈɔːdə(r)/","meaning":"n.混乱,骚乱;失调","seq":21,"isStar":false,"memo":"【构词】dis-(否定前缀)+order(顺序)→没有顺序→混乱;失调","example":"This is a rare disorder of the liver. 这是一种罕见的肝功能紊乱。"},{"id":450,"unit":2,"lesson":3,"word":"joint","pronunciation":"/dʒɔɪnt/","meaning":"adj.联合的,共同的 n.关节;接头","seq":22,"isStar":false,"memo":"【对照】两根骨头连接(join)的地方就是关节(joint)。","example":"The report was a joint effort. 这个报告是大家共同努力的成果。"},{"id":451,"unit":2,"lesson":3,"word":"adjacent","pronunciation":"/əˈdʒeɪs(ə)nt/","meaning":"adj.毗连的,邻近的","seq":23,"isStar":false,"memo":"【谐音】单词发音类似“爱近身的”→爱身边的人→邻近的","example":"This occurs almost exclusively between classes which are adjacent to each other. 这种情况几乎只发生在彼此相邻的类别之间。"},{"id":452,"unit":2,"lesson":3,"word":"compound","pronunciation":"/ˈkɒmpaʊnd/","meaning":"n.混合物","seq":24,"isStar":false,"memo":"【联想】com-(所有的)+pound(音似“泡的”)→我们早晨吃泡的牛奶、坚果等“混合物”。","example":"A compound sentence contains two or more clauses. 复合句包含两个或两个以上从句。"},{"id":453,"unit":2,"lesson":3,"word":"hybrid","pronunciation":"/ˈhaɪbrɪd/","meaning":"n.杂种动物;杂交植物","seq":25,"isStar":false,"memo":"记 (谐音) 单词发音类似“海哺育的”→这是它在海边哺育的“杂种动物”。","example":"Hybrid rice was first successfully developed and planted widely in China.杂交水稻首先在中国被成功培育并广泛种植。"},{"id":454,"unit":2,"lesson":3,"word":"turbulent","pronunciation":"/ˈtɜːbjələnt/","meaning":"adj.动荡的,动乱的;汹涌的","seq":26,"isStar":false,"memo":"【联想】tur(音似“他”)+bu(联想“不”)+lent(借)→在“动荡的”年代,他不愿意把自己的东西借出去,因为可能永远都要不回来了。","example":"Even during the turbulent years of last century, youth rebellion was often exaggerated in the media. 即使是在上个世纪的动荡年代,关于青少年叛逆的现象也经常被媒体夸大。"},{"id":455,"unit":2,"lesson":3,"word":"turbulence","pronunciation":"/ˈtɜːbjələns/","meaning":"n.骚乱;(空气或水的)湍流,紊流","seq":27,"isStar":false},{"id":456,"unit":2,"lesson":3,"word":"turmoil","pronunciation":"/ˈtɜːmɔɪl/","meaning":"n.混乱;动乱;骚动;焦虑","seq":28,"isStar":false,"memo":"记 (对照) 音近词 tomorrow → 我猜明天(tomorrow)的现场可能是一片混乱(turmoil)。","example":"His statement threw the court into turmoil.他的发言让法庭陷入混乱。"},{"id":457,"unit":2,"lesson":3,"word":"fluctuate","pronunciation":"/ˈflʌktʃueɪt/","meaning":"v.(大小、数量、质量等)波动,起伏","seq":29,"isStar":false,"memo":"【联想】flu(感冒)+c(音似“咳”)+t(联想“他”)+uate→他感冒了,咳嗽得厉害,情绪“波动”也较大。","example":"The analysis reveals that intensity appears to fluctuate with a clear, well-defined rhythm. 分析表明,强度似乎以清晰、明确的节奏波动。"},{"id":458,"unit":2,"lesson":3,"word":"fluctuation","pronunciation":"/ˌflʌktʃuˈeɪʃ(ə)n/","meaning":"n.波动,起伏","seq":30,"isStar":false},{"id":459,"unit":2,"lesson":3,"word":"stationary","pronunciation":"/ˈsteɪʃənri/","meaning":"adj.不动的,静止的;固定的","seq":31,"isStar":false,"memo":"【联想】sta(联想 stay)+-tion(名词后缀)+-ary(形容词后缀)→一个人一直待在一个地方,就是“不动的”。","example":"As an excellent shooter, Peter practised aiming at both stationary targets and moving targets. 作为一名出色的射手,彼得练习瞄准静止目标和移动目标。"},{"id":460,"unit":2,"lesson":3,"word":"station","pronunciation":"/ˈsteɪʃ(ə)n/","meaning":"n.站;地位;身份;驻地 v.配置;驻扎","seq":32,"isStar":false,"memo":"构词 stat(站立，同 stand)+-ion(名词后缀)→站着的位置→车站；地位，身份","example":"The train pulled slowly into the station. 火车缓缓驶进车站。"},{"id":461,"unit":2,"lesson":3,"word":"static","pronunciation":"/ˈstætɪk/","meaning":"adj.静止的;停滞的 n.静电","seq":33,"isStar":false,"memo":"联想 sta(联想 stay) + -tic → 有个人一直待在一个地方站着不动，像是“静止的”。","example":"Don't view things as static and isolated. 不要静止地、孤立地看待事物。"},{"id":462,"unit":2,"lesson":3,"word":"statute","pronunciation":"/ˈstætʃuːt/","meaning":"n.成文法;法规;章程,条例","seq":34,"isStar":false,"memo":"联想 sta (联想 state) + tute (音似“突他”) → 国家要突击检查他，需要有“法规”的依据。","example":"Penalties are laid down in the statute. 法规中有关于惩罚措施的规定。"},{"id":463,"unit":2,"lesson":3,"word":"statutory","pronunciation":"/ˈstætʃətri/","meaning":"adj.法定的;依法必须执行的","seq":35,"isStar":false,"memo":"构词 statut(法规，同 statute 法令)+-ory(形容词后缀)→法规规定的→法定的","example":"There is a statutory limit on working hours. 工作时间有法定上限。"},{"id":464,"unit":2,"lesson":3,"word":"status","pronunciation":"/ˈsteɪtəs/","meaning":"n.地位;身份;状况","seq":36,"isStar":false,"memo":"联想 stat(联想 state) + us(我们) → 在我们国家，我们的“地位”都是平等的。","example":"People's earnings are closely related to people's social status. 人们的收入与其社会地位密切相关。"},{"id":465,"unit":2,"lesson":3,"word":"statistic","pronunciation":"/stəˈtɪstɪk/","meaning":"n.统计数字;统计资料;(一项)统计数据","seq":37,"isStar":false,"memo":"谐音 单词发音类似“死待踢死踢磕”→做“统计数据”工作的人为了处理复杂的数据,要一直待在那里,踢开各种困难,死磕数据。","example":"An important statistic is that 94 percent of crime relates to property.一个重要的统计数据是94%的犯罪都与财产有关。"},{"id":466,"unit":2,"lesson":3,"word":"statistical","pronunciation":"/stəˈtɪstɪk(ə)l/","meaning":"adj.统计的","seq":38,"isStar":false},{"id":467,"unit":2,"lesson":3,"word":"fierce","pronunciation":"/fɪəs/","meaning":"adj.凶猛的;猛烈的;强烈的","seq":39,"isStar":false,"memo":"谐音 单词发音类似“飞蛾死”→飞蛾扑火的劲头是“猛烈的”。","example":"It was one of the fiercest battles of the 19th century. 这是19世纪最激烈的战役之一。"},{"id":468,"unit":2,"lesson":3,"word":"harsh","pronunciation":"/hɑːʃ/","meaning":"adj.残酷的;严厉的;恶劣的","seq":40,"isStar":false,"memo":"联想 har(联想 hard) + sh(音似“事”) → 艰难的事 → 残酷的","example":"Some species develop a unique life pattern to survive in extremely harsh conditions. 一些物种发展出一种独特的生存模式，以在极端恶劣的条件下生存。"},{"id":469,"unit":2,"lesson":3,"word":"rigorous","pronunciation":"/ˈrɪɡərəs/","meaning":"adj.缜密的;严酷的;严格的","seq":41,"isStar":false,"memo":"联想 ri(联想“日”) + go(去) + rous → 日子一天天过去了，时间还是很“严酷的”。","example":"The rigorous requirements placed on the writing of poetry stimulate the poet's creativity. 对诗歌创作的严格要求激发了诗人的创造力。"},{"id":470,"unit":2,"lesson":3,"word":"rigo(u)r","pronunciation":"/ˈrɪɡə(r)/","meaning":"n.严酷;缜密,严谨","seq":42,"isStar":false,"memo":"构词 rig(僵硬，同 rigid 僵硬的)+-our(名词后缀)→硬到不留余地→严酷；缜密，严谨","example":"They cannot adapt to the rigour of the school.他们无法适应学校的严格。"},{"id":471,"unit":2,"lesson":3,"word":"savage","pronunciation":"/ˈsævɪdʒ/","meaning":"n.野蛮人 v.凶猛地攻击(或伤害)","seq":43,"isStar":false,"memo":"联想 sav(联想 save) + age(年龄) → 他从那个“凶残的”人手上救出了年幼的孩子。","example":"She was savaged to death by a bear. 她遭熊袭击而丧命。"},{"id":472,"unit":2,"lesson":4,"word":"bureau","pronunciation":"/ˈbjʊərəʊ/","meaning":"n.(美国政府部门的)局,处,科;办事处","seq":1,"isStar":false,"memo":"谐音 单词发音类似“不弱”→在“局”里办公的人,能力真不弱。","example":"The Census Bureau has estimated statistics similar to the administration's proposal. 人口普查局估计的统计数据与政府的提议类似。"},{"id":473,"unit":2,"lesson":4,"word":"bureaucrat","pronunciation":"/ˈbjʊərəkræt/","meaning":"n.官僚主义者;官僚","seq":2,"isStar":false,"memo":"[记] (构词) bureau(机构)+-crat(统治,管理)→官僚主义者","example":"The economy is still controlled by bureaucrats.经济仍由官僚控制。"},{"id":474,"unit":2,"lesson":4,"word":"bureaucratic","pronunciation":"/ˌbjʊərəˈkrætɪk/","meaning":"adj.官僚的","seq":3,"isStar":false},{"id":475,"unit":2,"lesson":4,"word":"bureaucracy","pronunciation":"/bjʊəˈrɒkrəsi/","meaning":"n.官僚主义;官僚体制;官僚作风","seq":4,"isStar":false},{"id":476,"unit":2,"lesson":4,"word":"headquarters","pronunciation":"/ˌhedˈkwɔːtəz/","meaning":"n.总部,总公司;指挥部","seq":5,"isStar":false,"memo":"联想 head(头部)+quarter(四分之一)+s →四分之一的人物在头部公司→总部,总公司","example":"Its headquarters houses some 3,000 works of art. 它的总部收藏了大约3,000件艺术品。"},{"id":477,"unit":2,"lesson":4,"word":"council","pronunciation":"/ˈkaʊns(ə)l/","meaning":"n.政务委员会;地方议会","seq":6,"isStar":false,"memo":"联想 coun(联想 con-,都)+cil(音似“搜”) →每次去“地方议会”,都会被搜身。","example":"The city council has finally voted the funds to build a new high school. 市议会终于表决通过了建造一所新高中的拨款。"},{"id":478,"unit":2,"lesson":4,"word":"council(l)or","pronunciation":"/ˈkaʊns(ə)lə(r)/","meaning":"n.市议员;政务委员会委员","seq":7,"isStar":false,"memo":"构词 council(议会)+-or(表人)→议会里的人→市议员，政务委员会委员","example":"She was elected as a borough councillor. 她当选为区议员。"},{"id":479,"unit":2,"lesson":4,"word":"institute","pronunciation":"/ˈɪnstɪtjuːt/","meaning":"v.制定(体系、政策等);实行 n.学院","seq":8,"isStar":false,"memo":"联想 in(里面)+stitute(=stand)→耸立在大学里的那个建筑物是他们“学院”的。","example":"The new management intends to institute a number of changes. 新的管理层打算实行一些改革。"},{"id":480,"unit":2,"lesson":4,"word":"institution","pronunciation":"/ˌɪnstɪˈtjuːʃ(ə)n/","meaning":"n.机构;制度","seq":9,"isStar":false,"memo":"构词 institut(e)(机构)+-ion(名词后缀) →机构","example":"The region boasts several institutions of higher education. 该地区拥有几所高等教育机构。"},{"id":481,"unit":2,"lesson":4,"word":"institutional","pronunciation":"/ˌɪnstɪˈtjuːʃənl/","meaning":"adj.机构的;慈善机构的;惯例的","seq":10,"isStar":false},{"id":482,"unit":2,"lesson":4,"word":"agent","pronunciation":"/ˈeɪdʒənt/","meaning":"n.代理人,经纪人","seq":11,"isStar":false,"memo":"谐音+联想：'agent'→ '阿金特'——007代号？不，是'行动金特使'，代表别人干活的执行者！","example":"The university's career agent helps graduates find internships abroad. 学校的职业代理人为毕业生寻找海外实习机会。"},{"id":483,"unit":2,"lesson":4,"word":"agency","pronunciation":"/ˈeɪdʒənsi/","meaning":"n.代理机构;(政府的)专门机构","seq":12,"isStar":false,"memo":"[联想] agen(t)(代理人) + c + -y(名词后缀) → 代理机构","example":"Our agent in New York deals with all US sales. 我们在纽约的代理商经办在整个美国的销售。I just called the travel agency. It's all set. 我刚给旅行社打了电话。都安排好了。"},{"id":484,"unit":2,"lesson":4,"word":"substitute","pronunciation":"/ˈsʌbstɪtjuːt/","meaning":"n.代替者,代替物 v.(以……)代替","seq":13,"isStar":false,"memo":"[构词] sub-(下面) + stitute(= stand)→站在下面→候补→代替者","example":"Multivitamins are no substitute for exercise and a balanced diet, of course. 当然,复合维生素不能代替运动和均衡的饮食。"},{"id":485,"unit":2,"lesson":4,"word":"substitution","pronunciation":"/ˌsʌbstɪˈtjuːʃ(ə)n/","meaning":"n.替代;代替物","seq":14,"isStar":false},{"id":486,"unit":2,"lesson":4,"word":"constitute","pronunciation":"/ˈkɒnstɪtjuːt/","meaning":"v.组成,构成;设立;被视为,被算作","seq":15,"isStar":false,"memo":"[构词] con-(一起) + stitute( = stand)→站在一起→组成,构成","example":"Their behaviours do not constitute a warning signal. 他们的行为并不构成警告信号。"},{"id":487,"unit":2,"lesson":4,"word":"constitution","pronunciation":"/ˌkɒnstɪˈtjuːʃ(ə)n/","meaning":"n.宪法;组成;结构","seq":16,"isStar":false,"memo":"con（共同）+stitut（建立）+ion→大家共同建立的‘宪法’，就像班规是全班立的‘班级宪法’！","example":"The new constitution guarantees digital privacy rights. 新宪法保障数字隐私权。"},{"id":488,"unit":2,"lesson":4,"word":"constitutional","pronunciation":"/ˌkɒnstɪˈtjuːʃənl/","meaning":"adj.宪法的;体质的,体格","seq":17,"isStar":false},{"id":489,"unit":2,"lesson":4,"word":"constituent","pronunciation":"/kənˈstɪtʃuənt/","meaning":"n.(选区的)选民;成分 adj.组成的","seq":18,"isStar":false,"memo":"[构词] constitu(te)(组成) + -ent(后缀)→组成选举的人→选民;组成的","example":"She has the full support of her constituents. 她得到了她的选民们的全力支持。"},{"id":490,"unit":2,"lesson":4,"word":"constituency","pronunciation":"/kənˈstɪtʃuənsi/","meaning":"n.选区;选区的选民;支持者","seq":19,"isStar":false},{"id":491,"unit":2,"lesson":4,"word":"federal","pronunciation":"/ˈfedərəl/","meaning":"adj.联邦政府的","seq":20,"isStar":false,"memo":"[构词] feder(联盟,同盟) + -al(形容词后缀)→联邦政府的","example":"However, federal rules forbid the practice of making ads louder than the programming. 然而,联邦法规禁止广告音量超过节目音量的做法。"},{"id":492,"unit":2,"lesson":4,"word":"federation","pronunciation":"/ˌfedəˈreɪʃ(ə)n/","meaning":"n.联邦;联合会;联盟","seq":21,"isStar":false},{"id":493,"unit":2,"lesson":4,"word":"commonwealth","pronunciation":"/ˈkɒmənwelθ/","meaning":"n.英联邦;联合体","seq":22,"isStar":false,"memo":"[构词] common(共同的) + wealth(富裕)→所有地方都追求共同富裕→英联邦;联合体","example":"The Queen was the ceremonial head of the Commonwealth. 女王曾是英联邦的仪式性领袖。"},{"id":494,"unit":2,"lesson":4,"word":"minister","pronunciation":"/ˈmɪnɪstə(r)/","meaning":"n.(英国及其他许多国家的)部长","seq":23,"isStar":false,"memo":"联想 mini(小的) + st(联想 stand) + -er(表示人的后缀) → 古代的“大臣”站在皇帝面前会自称“小人”。","example":"He has been successfully elected Prime Minister. 他已成功当选首相。"},{"id":495,"unit":2,"lesson":4,"word":"ministerial","pronunciation":"/ˌmɪnɪˈstɪəriəl/","meaning":"adj.部长的;大臣的","seq":24,"isStar":false},{"id":496,"unit":2,"lesson":4,"word":"administer","pronunciation":"/ədˈmɪnɪstə(r)/","meaning":"v.管理;治理;执行","seq":25,"isStar":false,"memo":"构词 ad-(朝，向) + minister(部长) → 部长所为 → 管理","example":"The pension funds are administered by commercial banks. 养老基金由商业银行经营。"},{"id":497,"unit":2,"lesson":4,"word":"administrative","pronunciation":"/ədˈmɪnɪstrətɪv/","meaning":"adj.管理的;行政的","seq":26,"isStar":false},{"id":498,"unit":2,"lesson":4,"word":"administration","pronunciation":"/ədˌmɪnɪˈstreɪʃ(ə)n/","meaning":"n.(企业、学校等的)管理部门,行政部门","seq":27,"isStar":false},{"id":499,"unit":2,"lesson":4,"word":"harness","pronunciation":"/ˈhɑːnɪs/","meaning":"v.控制,给(马等)上挽具 n.挽具","seq":28,"isStar":false,"memo":"联想 harne(音似 honey) + ss(联想“蛇”) → 想吃蜂蜜的两条蛇被他“控制”了。","example":"The most promising strategy has become to harness one foe against the other. 最有希望的策略已经变成利用一个敌人来控制另一个敌人。"},{"id":500,"unit":2,"lesson":4,"word":"ministry","pronunciation":"/ˈmɪnɪstri/","meaning":"n.(政府的)部;牧师","seq":29,"isStar":false,"memo":"对照 部长(minister)努力工作的地方就是部(ministry)。","example":"They are responsible merely to their Ministry of Education. 他们只对他们的教育部负责。"},{"id":501,"unit":2,"lesson":4,"word":"secretary","pronunciation":"/ˈsekrət(ə)ri/","meaning":"n.秘书;干事,文书;部长","seq":30,"isStar":false,"memo":"构词 secret(秘密) + -ary(表示人的后缀) → 秘书","example":"She can't do without a secretary. 她不能没有秘书。"},{"id":502,"unit":2,"lesson":4,"word":"secretarial","pronunciation":"/ˌsekrəˈteəriəl/","meaning":"adj.秘书的;文秘工作的","seq":31,"isStar":false},{"id":503,"unit":2,"lesson":4,"word":"mayor","pronunciation":"/meə(r)/","meaning":"n.市长","seq":32,"isStar":false,"memo":"谐音 “迈尔”：迈着步子管全城的人→市长","example":"The mayor was asked to condense his speech. 市长被要求精简他的讲话。"},{"id":504,"unit":2,"lesson":4,"word":"official","pronunciation":"/əˈfɪʃ(ə)l/","meaning":"adj.公务的,公职的;正式的","seq":33,"isStar":false,"memo":"构词 offic(职责，同 office)+-ial(形容词后缀)→与公职有关的→公务的，官方的；官员","example":"He was an official from the community. 他是社区的一名官员。"},{"id":505,"unit":2,"lesson":4,"word":"casual","pronunciation":"/ˈkæʒuəl/","meaning":"adj.随意的,偶然的;非正式的","seq":34,"isStar":false,"memo":"联想 casu(联想“卡苏”，人名) + -al(形容词后缀) → 卡苏穿得很随意 → 随意的 构词 cas(e)(特殊情况) + -ual(形容词后缀) → 发生特殊情况的 → 偶然的；随意的","example":"The author felt as a boy that his life in a separated neighbourhood was casual and cosy. 作者觉得，作为一个男孩，他在独立社区的生活是随意和舒适的。"},{"id":506,"unit":2,"lesson":4,"word":"casualty","pronunciation":"/ˈkæʒuəlti/","meaning":"n.伤员;受害者;急诊室","seq":35,"isStar":false,"memo":"构词 cas(e)(病例) + -ual(形容词后缀) + -ty(名词后缀) → 伤员","example":"Our primary objective is reducing road casualties. 我们的首要目标是减少交通事故伤亡。"},{"id":507,"unit":2,"lesson":4,"word":"knight","pronunciation":"/naɪt/","meaning":"n.骑士;爵士 v.封(某人)为爵士","seq":36,"isStar":false,"memo":"记 (联想) dele(联想 delete)+gate(门)→删除门,即清除壁垒→产生壁垒的时候,双方一般会派“代表”进行沟通。","example":"Here, from a window, did he see a knight standing in a woodman's cart.在这里，他从一扇窗看到一位骑士站在樵夫的马车里。"},{"id":508,"unit":2,"lesson":4,"word":"delegate","pronunciation":"/ˈdelɪɡət/","meaning":"n.代表;参会人员 v.授权;委派","seq":37,"isStar":false,"memo":"[联想] dele(联想 delete) + gate(门)→删除门,即清除壁垒→产生壁垒的时候,双方一般会派“代表”进行沟通。","example":"Many delegates were in favor of his proposal. 许多代表都赞成他的建议。"},{"id":509,"unit":2,"lesson":4,"word":"delegation","pronunciation":"/ˌdelɪˈɡeɪʃn/","meaning":"n.代表团;委托","seq":38,"isStar":false},{"id":510,"unit":2,"lesson":4,"word":"threshold","pronunciation":"/ˈθreʃhəʊld/","meaning":"n.门槛,门口;起点;开端","seq":39,"isStar":false,"memo":"[构词] thres(h)(打→根) + hold(支撑)→支撑在门下的根→门槛→起点","example":"She felt as though she was on the threshold of a new life. 她觉得好像就要开始新生活了。"},{"id":511,"unit":2,"lesson":4,"word":"propagate","pronunciation":"/ˈprɒpəɡeɪt/","meaning":"v.传播,宣传;繁殖","seq":40,"isStar":false,"memo":"[联想] pro-(提前) + pa(联想“爸”) + gate(大门)→爸爸提前在大门口发传单,“宣传”垃圾分类。","example":"Plants won't propagate in these conditions. 植物在这些条件下不能繁殖。"},{"id":512,"unit":2,"lesson":4,"word":"propagation","pronunciation":"/ˌprɒpəˈɡeɪʃn/","meaning":"n.传播;繁殖","seq":41,"isStar":false},{"id":513,"unit":2,"lesson":4,"word":"propaganda","pronunciation":"/ˌprɒpəˈɡændə/","meaning":"n.宣传;鼓吹","seq":42,"isStar":false,"memo":"[联想] pro-(提前) + pa(联想“爸”) + gan (联想“干”) + da(联想“大”)→爸爸提前说要干番大事业,还没行动就开始“鼓吹”了。","example":"The new indicator is a “propaganda device” to promote income redistribution. 这个新指标是一种“宣传手段”,能促进收入再分配。"},{"id":514,"unit":2,"lesson":4,"word":"publicise/-ize","pronunciation":"/ˈpʌblɪsaɪz/","meaning":"v.宣传,推广","seq":43,"isStar":false,"memo":"构词 public(公众)+-ise/-ize(使…化)→让公众都知道→宣传，推广","example":"The event was widely publicised online. 这场活动在网上被广泛宣传。"},{"id":515,"unit":2,"lesson":4,"word":"public","pronunciation":"/ˈpʌblɪk/","meaning":"adj.大众的;公开的 n.百姓;公众","seq":44,"isStar":false},{"id":516,"unit":2,"lesson":4,"word":"publicly","pronunciation":"/ˈpʌblɪkli/","meaning":"adv.公开地","seq":45,"isStar":false},{"id":517,"unit":2,"lesson":4,"word":"publicity","pronunciation":"/pʌbˈlɪsəti/","meaning":"n.(媒体的)关注,宣传,报道","seq":46,"isStar":false},{"id":518,"unit":2,"lesson":4,"word":"vote","pronunciation":"/vəʊt/","meaning":"n.选票;投票权 v.选举,投票","seq":47,"isStar":false,"memo":"[谐音] 单词发音类似“我他”→我为他“投票”。","example":"Only members may vote on the proposal. 只有成员才能对这项提案投票。"},{"id":519,"unit":2,"lesson":4,"word":"voter","pronunciation":"/ˈvəʊtə(r)/","meaning":"n.投票人,选举人","seq":48,"isStar":false},{"id":520,"unit":2,"lesson":4,"word":"veto","pronunciation":"/ˈviːtəʊ/","meaning":"n.否决权 v.禁止;反对,否定","seq":49,"isStar":false,"memo":"[谐音] 单词发音类似“未投”→未投票就是否决了→否决权;反对","example":"A girl may veto the spouse her parents have chosen. 一个女孩可以拒绝父母为她选择的对象。"},{"id":521,"unit":2,"lesson":4,"word":"regime","pronunciation":"/reɪˈʒiːm/","meaning":"n.政权;政体;制度","seq":50,"isStar":false,"memo":"[谐音] 单词发音类似“叠积木”→建立“制度”也像搭建积木一样,要一层一层地建立起来。","example":"Changes to next year's funding regime are forcing universities to justify charging students up to £9,000 in fees. 明年经费制度的变化迫使大学证明向学生收取高达9,000英镑的费用是合理的。"},{"id":522,"unit":2,"lesson":4,"word":"reign","pronunciation":"/reɪn/","meaning":"n.(君主)统治时期;任期 v.统治","seq":51,"isStar":false,"memo":"[对照] 同音词 rain→古时候人们认为龙王具有统治(reign)力和支配力,可以决定下雨(rain)与否。","example":"The house was built during the reign of Henry VIII. 那栋房子是亨利八世统治时期建造的。"},{"id":523,"unit":2,"lesson":4,"word":"loyal","pronunciation":"/ˈlɔɪəl/","meaning":"adj.忠诚的,忠实的","seq":52,"isStar":false,"memo":"[谐音] 单词发音类似“老友”→老友一般都是很“忠诚的”。","example":"The middle class used to be loyal to the free enterprise system. 中产阶级曾经忠于自由企业制度。"},{"id":524,"unit":2,"lesson":4,"word":"loyalty","pronunciation":"/ˈlɔɪəlti/","meaning":"n.忠诚,忠实","seq":53,"isStar":false},{"id":525,"unit":2,"lesson":4,"word":"royal","pronunciation":"/ˈrɔɪəl/","meaning":"n.王室成员 adj.王室的;皇家的","seq":54,"isStar":false,"memo":"[谐音] 单词发音类似“荣耀”→荣耀的→王室的;皇家的","example":"She is from the royal family. 她来自皇室。"},{"id":526,"unit":2,"lesson":4,"word":"royalty","pronunciation":"/ˈrɔɪəlti/","meaning":"n.王室成员;版税","seq":55,"isStar":false},{"id":527,"unit":2,"lesson":4,"word":"salute","pronunciation":"/səˈluːt/","meaning":"v.&n.敬礼;致敬","seq":56,"isStar":false,"memo":"[联想] sa(联想“啥”) + lu(联想“路”) + te(联想“他”)→为啥在路上见到他要“敬礼”?","example":"The sergeant stood to attention and saluted. 中士立正敬礼。"},{"id":528,"unit":2,"lesson":4,"word":"salutation","pronunciation":"/ˌsæljuˈteɪʃ(ə)n/","meaning":"n.招呼;致意;打招呼;致意的动作","seq":57,"isStar":false},{"id":529,"unit":2,"lesson":4,"word":"sovereign","pronunciation":"/ˈsɒvrɪn/","meaning":"n.君主;元首 adj.有主权的","seq":58,"isStar":false,"memo":"[构词] sover-( = super-, 在……上面) + reign(统治)→最上面的统治者→君主;元首","example":"Today, the European Union is creating a $580 billion fund to ward off sovereign collapse. 如今,欧盟正在创建一个5,800亿美元的基金,以防止主权崩溃。"},{"id":530,"unit":2,"lesson":4,"word":"sovereignty","pronunciation":"/ˈsɒvrənti/","meaning":"n.主权;最高统治权","seq":59,"isStar":false},{"id":531,"unit":2,"lesson":4,"word":"emperor","pronunciation":"/ˈempərə(r)/","meaning":"n.皇帝","seq":60,"isStar":false,"memo":"[联想] em(联想“俺妹”) + per(联想“怕”) + -or(表示人的后缀)→俺妹怕的人是“皇帝”。","example":"It is the tomb of the first real emperor of China, Emperor Qin Shi Huang. 它是中国第一位真正的皇帝秦始皇的坟墓。"},{"id":532,"unit":2,"lesson":4,"word":"empress","pronunciation":"/ˈemprəs/","meaning":"n.女皇;皇后","seq":61,"isStar":false},{"id":533,"unit":2,"lesson":4,"word":"imperial","pronunciation":"/ɪmˈpɪəriəl/","meaning":"adj.帝国的,皇帝的","seq":62,"isStar":false,"memo":"构词 imper(统治，同 emperor 皇帝)+-ial(形容词后缀)→与皇帝、帝国有关的→帝国的，皇帝的","example":"The Imperial Palace is a magnificent building with a long history. 故宫是一座有着悠久历史的宏伟建筑。"},{"id":534,"unit":2,"lesson":4,"word":"imperialism","pronunciation":"/ɪmˈpɪəriəlɪzəm/","meaning":"n.帝国统治;帝国主义","seq":63,"isStar":false,"memo":"构词 imperial(帝国的)+-ism(主义)→帝国对外扩张的主张→帝国统治；帝国主义","example":"The book analyses the rise of imperialism. 这本书分析了帝国主义的兴起。"},{"id":535,"unit":2,"lesson":4,"word":"imperialist","pronunciation":"/ɪmˈpɪəriəlɪst/","meaning":"n.帝国主义者;帝国统治拥护者","seq":64,"isStar":false,"memo":"构词 imperial(帝国的)+-ist(表人)→主张帝国扩张的人→帝国主义者","example":"He was a fierce imperialist in his youth. 他年轻时是个狂热的帝国主义者。"},{"id":536,"unit":2,"lesson":4,"word":"civil","pronunciation":"/ˈsɪv(ə)l/","meaning":"adj.国内的;公民的;平民的,民用的","seq":65,"isStar":false,"memo":"[谐音] 单词发音类似“是我”→“国内的”最“有礼貌的”公民是我。","example":"We have been actively exercising our civil rights. 我们一直在积极行使我们的公民权利。"},{"id":537,"unit":2,"lesson":4,"word":"civilise/-ize","pronunciation":"/ˈsɪvəlaɪz/","meaning":"v.教化;开化;使文明","seq":66,"isStar":false,"memo":"构词 civil(文明的)+-ise/-ize(使…化)→使变得文明→教化，开化","example":"The Romans set out to civilise the tribes. 罗马人着手开化这些部落。"},{"id":538,"unit":2,"lesson":4,"word":"civilisation/-zation","pronunciation":"/ˌsɪvəlaɪˈzeɪʃ(ə)n/","meaning":"n.文明;文明世界;文明社会","seq":67,"isStar":false,"memo":"构词 civil(文明的)+-isation/-ization(名词后缀)→文明的状态→文明，文明社会","example":"Ancient Chinese civilisation is one of the oldest in the world. 中国古代文明是世界上最古老的文明之一。"},{"id":539,"unit":2,"lesson":4,"word":"civic","pronunciation":"/ˈsɪvɪk/","meaning":"adj.市政的;城市的;市民的","seq":68,"isStar":false,"memo":"记 (构词) civ(公民)+-ic(形容词后缀)→市民的","example":"The competition would be an opportunity to foster civic pride.这次比赛将是培养公民自豪感的机会。"},{"id":540,"unit":2,"lesson":4,"word":"civilian","pronunciation":"/səˈvɪliən/","meaning":"n.平民;老百姓 adj.平民的","seq":69,"isStar":false,"memo":"[构词] civil(公民的;平民的) + -ian(后缀)→平民","example":"Two soldiers and one civilian were killed in the explosion. 在爆炸中有两个士兵和一个平民被炸死。"},{"id":541,"unit":3,"lesson":1,"word":"donate","pronunciation":"/dəʊˈneɪt/","meaning":"v.捐赠,赠予,捐献","seq":1,"isStar":false,"memo":"构词 don(给予，同 donor 捐赠者)+-ate(动词后缀)→把东西给出去→捐赠，捐献","example":"They donated blood to the local hospital. 他们向当地医院捐献了血液。"},{"id":542,"unit":3,"lesson":1,"word":"donation","pronunciation":"/dəʊˈneɪʃ(ə)n/","meaning":"n.捐赠,捐款;献(血)","seq":2,"isStar":false},{"id":543,"unit":3,"lesson":1,"word":"donor","pronunciation":"/ˈdəʊnə(r)/","meaning":"n.捐赠者;捐赠机构","seq":3,"isStar":false},{"id":544,"unit":3,"lesson":1,"word":"endow","pronunciation":"/ɪnˈdaʊ/","meaning":"v.捐赠;资助","seq":4,"isStar":false,"memo":"构词 en-(使)+dow(给，同 dowry 嫁妆)→使某人拥有，把财物给出去→捐赠；资助","example":"He endowed the college with a large sum of money. 他向这所学院捐赠了一大笔钱。"},{"id":545,"unit":3,"lesson":1,"word":"endowment","pronunciation":"/ɪnˈdaʊmənt/","meaning":"n.捐款,捐赠;资助","seq":5,"isStar":false,"memo":"构词 endow(捐赠)+-ment(名词后缀)→捐出来的那笔东西→捐款，捐赠；资助","example":"The school depends on a private endowment. 这所学校依靠私人捐赠办学。"},{"id":546,"unit":3,"lesson":1,"word":"charity","pronunciation":"/ˈtʃærəti/","meaning":"n.慈善;慈善机构;宽容","seq":6,"isStar":false,"memo":"构词 char(爱，同 cherish 珍爱)+-ity(名词后缀)→出于爱心的给予→慈善；慈善机构；宽容","example":"She gave most of her money to charity. 她把大部分钱都捐给了慈善事业。"},{"id":547,"unit":3,"lesson":1,"word":"charitable","pronunciation":"/ˈtʃærətəbl/","meaning":"adj.慈善的;宽容的","seq":7,"isStar":false,"memo":"构词 charit(慈善)+-able(形容词后缀)→乐于施与的→慈善的；宽容的","example":"He made a charitable donation to the orphanage. 他向孤儿院做了一笔慈善捐款。"},{"id":548,"unit":3,"lesson":1,"word":"contribute","pronunciation":"/kənˈtrɪbjuːt/","meaning":"v.捐献,捐赠;促成","seq":8,"isStar":false,"memo":"[构词] con-(所有) + tribute(给)→给出所","example":"Everyone contributed ideas to the project. 每个人都为这个项目贡献了想法。"},{"id":549,"unit":3,"lesson":1,"word":"contribution","pronunciation":"/ˌkɒntrɪˈbjuːʃ(ə)n/","meaning":"n.贡献;促成作用;捐款","seq":9,"isStar":false},{"id":550,"unit":3,"lesson":1,"word":"contributor","pronunciation":"/kənˈtrɪbjətə(r)/","meaning":"n.捐款者;捐赠者;撰稿人;嘉宾","seq":10,"isStar":false},{"id":551,"unit":3,"lesson":1,"word":"tribute","pronunciation":"/ˈtrɪbjuːt/","meaning":"n.礼物,赠品;贡品;致敬,悼念","seq":11,"isStar":false,"memo":"构词 tribut(给予，同 contribute 贡献)+-e→献上去的东西→礼物，贡品；致敬，悼念","example":"The concert was a tribute to the late singer. 这场音乐会是向已故歌手致敬。"},{"id":552,"unit":3,"lesson":1,"word":"attribute","pronunciation":"/əˈtrɪbjuːt; ˈætrɪbjuːt/","meaning":"n.属性,特征 v.把……归因于……","seq":12,"isStar":false,"memo":"拆解：a（to）+ tribut（给予）+ e → 把功劳‘给’到某人头上！所以v.归因于——不是你干的？偏说‘This success is attributed to you!’","example":"Scientists attribute climate change to human activities. 科学家将气候变化归因于人类活动。"},{"id":553,"unit":3,"lesson":1,"word":"attributable","pronunciation":"/əˈtrɪbjətəb(ə)l/","meaning":"adj.可归因于……的","seq":13,"isStar":false,"memo":"构词 at-(加强)+tribut(给予，同 attribute 把……归于)+-able(可…的)→可归给某一方的→可归因于……的","example":"Most of the damage is attributable to human error. 大部分损坏可归因于人为失误。"},{"id":554,"unit":3,"lesson":1,"word":"distribute","pronunciation":"/dɪˈstrɪbjuːt/","meaning":"v.分发,分配","seq":14,"isStar":false,"memo":"构词 dis-(分开) + tribute(给) → 分发,分配","example":"The newspaper is distributed free. 本报免费派发。"},{"id":555,"unit":3,"lesson":1,"word":"distributive","pronunciation":"/dɪˈstrɪbjətɪv/","meaning":"adj.经销的,分销的","seq":15,"isStar":false},{"id":556,"unit":3,"lesson":1,"word":"distribution","pronunciation":"/ˌdɪstrɪˈbjuːʃn/","meaning":"n.分配,分发","seq":16,"isStar":false},{"id":557,"unit":3,"lesson":1,"word":"transmit","pronunciation":"/trænzˈmɪt/","meaning":"v.传送,输送;传播;传染","seq":17,"isStar":false,"memo":"联想 trans-(从……到……) + m(联想“妹”) + it(联想“它”)→纸条从妹妹手里传到它手里→传送","example":"It is keen on transmitting sensational information. 它热衷于传播耸人听闻的信息。"},{"id":558,"unit":3,"lesson":1,"word":"transmitter","pronunciation":"/trænzˈmɪtə(r); trænsˈmɪtə(r)/","meaning":"n.传送者;发射机","seq":18,"isStar":false},{"id":559,"unit":3,"lesson":1,"word":"transmission","pronunciation":"/trænzˈmɪʃ(ə)n/","meaning":"n.传送;传播","seq":19,"isStar":false},{"id":560,"unit":3,"lesson":1,"word":"freight","pronunciation":"/freɪt/","meaning":"n.货物 v.运送(货物)","seq":20,"isStar":false,"memo":"对照 航班(flight)经常运送货物(freight)。","example":"Most freight goes by sea and rail. 多数货物都是通过海路和铁路运输的。"},{"id":561,"unit":3,"lesson":1,"word":"admit","pronunciation":"/ədˈmɪt/","meaning":"v.承认;准许……进入;接收(入学)","seq":21,"isStar":false,"memo":"联想 ad-(一再地) + mit(送)→他一再给邻居送礼,邻居就收下并准许他进入了→准许……进入","example":"I must admit that I felt sleepy during the two hours. 我必须承认,在这两个小时里我感到很困。"},{"id":562,"unit":3,"lesson":1,"word":"admission","pronunciation":"/ədˈmɪʃ(ə)n/","meaning":"n.准许加入;承认;门票费","seq":22,"isStar":false},{"id":563,"unit":3,"lesson":1,"word":"admittance","pronunciation":"/ədˈmɪt(ə)ns/","meaning":"n.进入权,进入","seq":23,"isStar":false},{"id":564,"unit":3,"lesson":1,"word":"admittedly","pronunciation":"/ədˈmɪtɪdli/","meaning":"adv.诚然,无可否认","seq":24,"isStar":false,"memo":"标：记忆] 构词 admit(承认) + -(t)ed(表示被动) + -ly(副词后缀)→被承认地→诚然，无可否认","example":"Admittedly, there are different purposes behind this phenomenon.诚然，这种现象背后有不同的目的。"},{"id":565,"unit":3,"lesson":1,"word":"acknowledge","pronunciation":"/əkˈnɒlɪdʒ/","meaning":"v.承认;告知收到;(公开)感谢","seq":25,"isStar":false,"memo":"联想 ac-(一再地) + knowledge(知识)→他一再地“承认”知识是有用的。","example":"But we can't acknowledge that our obsession is more about us than them. 但我们不能承认,我们的痴迷更多的是关于我们自己,而不是他们。"},{"id":566,"unit":3,"lesson":1,"word":"acknowledgement","pronunciation":"/əkˈnɒlɪdʒmənt/","meaning":"n.承认;感谢,谢礼","seq":26,"isStar":false},{"id":567,"unit":3,"lesson":1,"word":"permit","pronunciation":"/pəˈmɪt/","meaning":"v.允许,准许;使有可能 n.许可证","seq":27,"isStar":false,"memo":"构词 per-(穿过)+mit(送，同 mission 派遣)→让某事穿过去→允许，准许；许可证","example":"The rules do not permit smoking here. 这里的规定不允许吸烟。"},{"id":568,"unit":3,"lesson":1,"word":"permission","pronunciation":"/pəˈmɪʃ(ə)n/","meaning":"n.准许,许可,批准","seq":28,"isStar":false,"memo":"构词 per-(穿过)+miss(送)+-ion(名词后缀)→放行的行为→准许，许可，批准","example":"You need written permission to enter the area. 进入该区域需要书面许可。"},{"id":569,"unit":3,"lesson":1,"word":"permissible","pronunciation":"/pəˈmɪsəb(ə)l/","meaning":"adj.容许的,许可的","seq":29,"isStar":false,"memo":"构词 permiss(允许)+-ible(可…的)→可以被允许的→容许的，许可的","example":"Is it permissible to park here? 这里可以停车吗？"},{"id":570,"unit":3,"lesson":1,"word":"permissive","pronunciation":"/pəˈmɪsɪv/","meaning":"adj.放任的,纵容的,姑息的","seq":30,"isStar":false,"memo":"构词 permiss(允许)+-ive(形容词后缀)→什么都点头的→放任的，纵容的","example":"The school has a permissive attitude to dress. 这所学校对着装持放任态度。"},{"id":571,"unit":3,"lesson":1,"word":"submit","pronunciation":"/səbˈmɪt/","meaning":"v.提交,呈递;服从","seq":31,"isStar":false,"memo":"构词 sub-(下) + mit(= send,送)→自下而上传送→提交,呈递;服从","example":"When are we supposed to submit our project proposals? 我们应该什么时候提交项目提案?"},{"id":572,"unit":3,"lesson":1,"word":"submission","pronunciation":"/səbˈmɪʃn/","meaning":"n.屈服;提交","seq":32,"isStar":false},{"id":573,"unit":3,"lesson":1,"word":"submissive","pronunciation":"/səbˈmɪsɪv/","meaning":"adj.服从的,驯服的;听话的","seq":33,"isStar":false,"memo":"对照 submission n.屈服→submissive adj.服从的","example":"She followed him like a submissive child.她像个顺从的孩子一样跟着他。"},{"id":574,"unit":3,"lesson":1,"word":"commission","pronunciation":"/kəˈmɪʃ(ə)n/","meaning":"n.委员会;佣金,回扣","seq":34,"isStar":false,"memo":"联想 com-(所有) + mission(任务)→把所有任务都送给它→委员会","example":"The town planning commission said that their financial outlook for the next year was optimistic. 城市规划委员会表示,他们对明年的财政前景持乐观态度。"},{"id":575,"unit":3,"lesson":1,"word":"committee","pronunciation":"/kəˈmɪti/","meaning":"n.委员会","seq":35,"isStar":false,"memo":"联想 com-(共同) + mit(联想 meet) + tee (联想 team)→共同开会的一组成员→委员会","example":"He recommended the constitution of a review committee. 他建议设立审查委员会。"},{"id":576,"unit":3,"lesson":1,"word":"dismiss","pronunciation":"/dɪsˈmɪs/","meaning":"v.拒绝考虑;开除,解雇;解散","seq":36,"isStar":false,"memo":"构词 dis-( = away,离开) + miss( = mit,送)→送走→开除;解散","example":"She has been dismissed for her poor performance. 她因表现不佳而被解雇了。"},{"id":577,"unit":3,"lesson":1,"word":"dismissal","pronunciation":"/dɪsˈmɪs(ə)l/","meaning":"n.开除;不予理会","seq":37,"isStar":false,"memo":"构词 dismiss(开除)+-al(名词后缀)→开除","example":"Her casual dismissal of the threats seemed irresponsible.她对威胁轻描淡写的态度似乎不负责任。"},{"id":578,"unit":3,"lesson":1,"word":"mission","pronunciation":"/ˈmɪʃ(ə)n/","meaning":"n.使命,任务;使团,代表团","seq":38,"isStar":false,"memo":"[构词] miss(派) + -ion(名词后缀)→分派的事务→使命,任务","example":"I must forget these side issues and remember my mission. 我必须忘记这些次要问题,记住我的使命。"},{"id":579,"unit":3,"lesson":1,"word":"summit","pronunciation":"/ˈsʌmɪt/","meaning":"n.顶点;山顶;首脑会议;峰会","seq":39,"isStar":false,"memo":"[联想] sum(形似 sun) + mit(送)→送到太阳上去→顶点;峰会","example":"Let's talk about the day you reached the summit of Mt. Qomolangma. 让我们来谈谈你登顶珠穆朗玛峰的那一天。"},{"id":580,"unit":3,"lesson":1,"word":"climax","pronunciation":"/ˈklaɪmæks/","meaning":"n.顶点,高潮","seq":40,"isStar":false,"memo":"[联想] cli(联想“可立”) + max(最大值)→可立在最大值了→终于站在最高处了→顶点","example":"The climax of his career was director. 他职业生涯的顶点就是做导演。"},{"id":581,"unit":3,"lesson":1,"word":"peak","pronunciation":"/piːk/","meaning":"n.顶点,高峰 v.达到高峰","seq":41,"isStar":false,"memo":"[谐音] 单词发音类似“匹克”→奥林匹克是顶尖运动员的比赛→顶点","example":"Since August 2008, when household debt peaked at $12.41 trillion, it has declined by about $1.2 trillion. 自2008年8月家庭债务达到12.41万亿美元的峰值以来,它已经下降了约1.2万亿美元。"},{"id":582,"unit":3,"lesson":1,"word":"emit","pronunciation":"/iˈmɪt/","meaning":"v.发出;散发(光、热、声音、气等)","seq":42,"isStar":false,"memo":"[构词] e-(向外) + mit(送)→发出,散发","example":"Our air quality now suffers from the effects of pollutants emitted directly from our cars. 我们的空气质量现在受到汽车直接排放的污染物的影响。"},{"id":583,"unit":3,"lesson":1,"word":"emission","pronunciation":"/ɪˈmɪʃ(ə)n/","meaning":"n.(光、热、气等的)发出,排放;排放物","seq":43,"isStar":false},{"id":584,"unit":3,"lesson":1,"word":"omit","pronunciation":"/əˈmɪt/","meaning":"v.删除;忽略;漏掉,遗漏","seq":44,"isStar":false,"memo":"[联想] o(形似圈) + mit(送)→把圈中的送出去→删除;忽略","example":"However, that comparison omits other relevant factors. 然而,那种比较忽略了其他相关因素。"},{"id":585,"unit":3,"lesson":1,"word":"omission","pronunciation":"/əˈmɪʃ(ə)n/","meaning":"n.省略;删除","seq":45,"isStar":false},{"id":586,"unit":3,"lesson":1,"word":"intermittent","pronunciation":"/ˌɪntəˈmɪtənt/","meaning":"adj.断断续续的,间歇的","seq":46,"isStar":false,"memo":"[构词] inter-(在……之间) + mit(t)(送) + -ent(形容词后缀)→在……之间来来回回地送→断断续续的,间歇的","example":"After three hours of intermittent rain, the game was abandoned. 在雨断断续续地下了3个小时之后,比赛被取消了。"},{"id":587,"unit":3,"lesson":1,"word":"commit","pronunciation":"/kəˈmɪt/","meaning":"v.犯(罪或错误等);承诺,保证","seq":47,"isStar":false,"memo":"[联想] com-(都) + mit(送)→我很喜欢他的这几本书,于是他“承诺”在我生日时把它们都送给我。","example":"You are pointing out the errors he has committed. 你正在指出他所犯的错误。"},{"id":588,"unit":3,"lesson":1,"word":"commitment","pronunciation":"/kəˈmɪtmənt/","meaning":"n.承诺;奉献","seq":48,"isStar":false},{"id":589,"unit":3,"lesson":1,"word":"suicide","pronunciation":"/ˈsuːɪsaɪd/","meaning":"n.自杀","seq":49,"isStar":false,"memo":"[构词] sui(自己) + cide(杀)→自杀","example":"He committed suicide for unknown reasons. 他自杀的原因不明。"},{"id":590,"unit":3,"lesson":1,"word":"suicidal","pronunciation":"/ˌsuːɪˈsaɪd(ə)l/","meaning":"adj.自杀性的;毁灭性的","seq":50,"isStar":false,"memo":"构词 sui(自己，同 suicide 自杀)+-cidal(杀的)→杀死自己的→自杀性的；毁灭性的","example":"Driving so fast is suicidal. 开这么快车无异于自杀。"},{"id":591,"unit":3,"lesson":1,"word":"pesticide","pronunciation":"/ˈpestɪsaɪd/","meaning":"n.杀虫剂,农药","seq":51,"isStar":false,"memo":"[联想] pesti(音似“拍死它”) + cide(杀)→拍死、杀死它(害虫)→杀虫剂;农药","example":"Pesticides are widely used in agriculture. 农药在农业中被广泛使用。"},{"id":592,"unit":3,"lesson":1,"word":"precise","pronunciation":"/prɪˈsaɪs/","meaning":"adj.准确的,精确的;明确的","seq":52,"isStar":false,"memo":"[构词] pre-(在……之前) + cise(= cide,切割)→提前切割好→精确的","example":"Measuring emissions is not a precise science. 测量排放量并不是一门精确的科学。"},{"id":593,"unit":3,"lesson":1,"word":"precisely","pronunciation":"/prɪˈsaɪsli/","meaning":"adv.准确地,恰好地","seq":53,"isStar":false},{"id":594,"unit":3,"lesson":1,"word":"precision","pronunciation":"/prɪˈsɪʒ(ə)n/","meaning":"n.精确,准确;细致","seq":54,"isStar":false},{"id":595,"unit":3,"lesson":1,"word":"concise","pronunciation":"/kənˈsaɪs/","meaning":"adj.简明的;简洁的","seq":55,"isStar":false,"memo":"[构词] con-(表加强) + cise( = cide,切割,削减)→简明的","example":"The new secretary has written a remarkably concise report. 新任秘书撰写了一份简明扼要的报告。"},{"id":596,"unit":3,"lesson":1,"word":"subtle","pronunciation":"/ˈsʌt(ə)l/","meaning":"adj.微妙的;敏锐的","seq":56,"isStar":false,"memo":"[谐音] 单词发音类似“杀头”→伴君如伴虎,大臣跟君主的关系是“微妙的”,事情办不好要被杀头。","example":"But why such subtle shifts make some people depressed and not others is a mystery. 但为什么这种微妙的变化会让一些人感到抑郁,而另一些人却不会,这是一个谜。"},{"id":597,"unit":3,"lesson":1,"word":"subtlety","pronunciation":"/ˈsʌt(ə)lti/","meaning":"n.微妙;狡猾;敏锐","seq":57,"isStar":false},{"id":598,"unit":3,"lesson":1,"word":"sacrifice","pronunciation":"/ˈsækrɪfaɪs/","meaning":"n.牺牲;祭品 v.牺牲;献祭","seq":58,"isStar":false,"memo":"[谐音] 单词发音类似“杀可就非死”→读起来有种“为有牺牲多壮志,敢教日月换新天”的感觉→牺牲","example":"The pursuit of a fulfilling career involves personal sacrifice. 追求使人有成就感的事业需要个人的牺牲。"},{"id":599,"unit":3,"lesson":1,"word":"sacrificial","pronunciation":"/ˌsækrɪˈfɪʃ(ə)l/","meaning":"adj.用于祭献的","seq":59,"isStar":false},{"id":600,"unit":3,"lesson":1,"word":"deadly","pronunciation":"/ˈdedli/","meaning":"adj.致命的;非常的 adv.极其","seq":60,"isStar":false,"memo":"构词 dead(死)+-ly(形容词后缀)→能致死的→致命的；也作副词“极其”","example":"He has a deadly defect. 他有一个致命的缺点。"},{"id":601,"unit":3,"lesson":1,"word":"maintain","pronunciation":"/meɪnˈteɪn/","meaning":"v.维持,保持;保养;坚持(意见)","seq":61,"isStar":false,"memo":"联想 main(主要的) + tain( = take,拿)→家中主要的东西(钱财)由一家之主拿着,用以“维持”一家人的生活。","example":"There were no longer enough fish in the sea for the stock to maintain itself, let alone an industry. 海洋里已经没有足够的鱼来维持鱼类种群的生存,更不用说维持一个产业了。"},{"id":602,"unit":3,"lesson":1,"word":"maintenance","pronunciation":"/ˈmeɪntənəns/","meaning":"n.维护;保养;维持;抚养费","seq":62,"isStar":false,"memo":"联想 main(主要的)+tenance(联想“特难吃”)→她所购买的主要的食物特难吃,因为“抚养费”不够“维持”生活。","example":"A maintenance worker at the Louvre walked out of the museum with the Mona Lisa, hidden under his smock.卢浮宫的一名维修工身披工作服，把《蒙娜丽莎》带出了博物馆。"},{"id":603,"unit":3,"lesson":1,"word":"mainstream","pronunciation":"/ˈmeɪnstriːm/","meaning":"n.主流思想;主流群体","seq":63,"isStar":false,"memo":"构词 main(主要的)+stream(潮流)→主流思想;主流群体","example":"The technology is just now becoming the mainstream.这项技术正成为主流。"},{"id":604,"unit":3,"lesson":1,"word":"remain","pronunciation":"/rɪˈmeɪn/","meaning":"v.继续;保持不变;剩下;留下","seq":64,"isStar":false,"memo":"联想 re-(重复) + main(主要的)→重复主要的→保持不变","example":"The main character remains the same. 主角保持不变。"},{"id":605,"unit":3,"lesson":1,"word":"remainder","pronunciation":"/rɪˈmeɪndə(r)/","meaning":"n.剩余物,剩余部分;差数;余数","seq":65,"isStar":false,"memo":"构词 remain(剩下) + -(d)er(名词后缀)→剩余物,剩余部分","example":"He was silent throughout the remainder of the journey. 在余下的旅程中,他很沉默。"},{"id":606,"unit":3,"lesson":1,"word":"remnant","pronunciation":"/ˈremnənt/","meaning":"n.残余部分,剩余部分","seq":66,"isStar":false,"memo":"联想 re-(重复) + m(联想“妹”) + nant(音似“拿它”)→妹妹重复去拿它(玩具)的“残余部分”。","example":"Beneath the present church were remnants of Roman flooring. 现在的教堂下面是古罗马时期地面的遗迹。"},{"id":607,"unit":3,"lesson":1,"word":"retain","pronunciation":"/rɪˈteɪn/","meaning":"v.保持;保留","seq":67,"isStar":false,"memo":"联想 re-(重复) + tain(拿)→重复地拿或一直拿→保持;保留","example":"This is great for her, and for us as we retain someone highly qualified. 这对她来说很好,对我们来说也很好,因为我们可以留住一位高素质的人才。"},{"id":608,"unit":3,"lesson":1,"word":"retention","pronunciation":"/rɪˈtenʃ(ə)n/","meaning":"n.保持;保留","seq":68,"isStar":false},{"id":609,"unit":3,"lesson":1,"word":"detain","pronunciation":"/dɪˈteɪn/","meaning":"v.拘留;耽搁","seq":69,"isStar":false,"memo":"联想 de-(往下)+tain(拿)→把人或事情往下拿→拘留;耽搁","example":"The police detained a man.警方拘留了一名男子。"},{"id":610,"unit":3,"lesson":1,"word":"detention","pronunciation":"/dɪˈtenʃn/","meaning":"n.拘留;课后留校","seq":70,"isStar":false},{"id":611,"unit":3,"lesson":1,"word":"sustain","pronunciation":"/səˈsteɪn/","meaning":"v.维持(生命、生存);支持,支撑","seq":71,"isStar":false,"memo":"构词 sus-( = sub-,下面) + tain(拿)→从下面拿着→从下面支撑着→支持;支撑","example":"Which planets can sustain life? 哪些行星可以维持生命的存在?"},{"id":612,"unit":3,"lesson":1,"word":"sustainable","pronunciation":"/səˈsteɪnəb(ə)l/","meaning":"adj.可持续的","seq":72,"isStar":false},{"id":613,"unit":3,"lesson":1,"word":"sustainability","pronunciation":"/səˌsteɪnəˈbɪləti/","meaning":"n.可持续性","seq":73,"isStar":false},{"id":614,"unit":3,"lesson":1,"word":"attain","pronunciation":"/əˈteɪn/","meaning":"v.(通常指经过努力)获得;达到,实现","seq":74,"isStar":false,"memo":"[联想] at-(一再地)+tain(拿)→当你“获得”了你特别喜欢的东西时,一定会天天拿着,爱不释手。","example":"Students with high hopes set themselves higher goals and know how to work to attain them. 满怀希望的学生会给自己设定更高的目标,并知道如何努力实现这些目标。"},{"id":615,"unit":3,"lesson":1,"word":"attainment","pronunciation":"/əˈteɪnmənt/","meaning":"n.成就;达到;获得","seq":75,"isStar":false},{"id":616,"unit":3,"lesson":1,"word":"entertain","pronunciation":"/ˌentəˈteɪn/","meaning":"v.(尤指在自己家中)招待;使快乐,娱乐","seq":76,"isStar":false,"memo":"[联想] enter(进入)+tain(拿)→一个同学进入教室就拿着麦克风唱歌,“娱乐”大家。","example":"There are more avenues for us to entertain ourselves than ever before. 我们自我娱乐的途径比以往任何时候都多。"},{"id":617,"unit":3,"lesson":1,"word":"entertainment","pronunciation":"/ˌentəˈteɪnmənt/","meaning":"n.娱乐活动;招待","seq":77,"isStar":false},{"id":618,"unit":3,"lesson":1,"word":"entertaining","pronunciation":"/ˌentəˈteɪnɪŋ/","meaning":"adj.娱乐的;使人愉快的","seq":78,"isStar":false},{"id":619,"unit":3,"lesson":1,"word":"pastime","pronunciation":"/ˈpɑːstaɪm/","meaning":"n.消遣,休闲活动","seq":79,"isStar":false,"memo":"[联想] pas(联想 past)+time(时光)→过去的时光很美好,因为我把大部分时间都用来学习而不是“消遣”了。","example":"By nature, Americans are enthusiastic and energetic about hobbies or pastimes. 美国人天生对爱好和休闲活动充满热情和活力。"},{"id":620,"unit":3,"lesson":1,"word":"recreation","pronunciation":"/ˌriːkriˈeɪʃn; ˌrekriˈeɪʃən/","meaning":"n.消遣,娱乐","seq":80,"isStar":false,"memo":"[联想] re-(重复)+creat(e)(创造)+-ion(名词后缀)→他重复创造好的作品供大众“消遣”。","example":"His only form of recreation is playing football. 他唯一的娱乐就是踢足球。"},{"id":621,"unit":3,"lesson":1,"word":"recreational","pronunciation":"/ˌrekriˈeɪʃən(ə)l/","meaning":"adj.娱乐的,消遣的","seq":81,"isStar":false},{"id":622,"unit":3,"lesson":1,"word":"amuse","pronunciation":"/əˈmjuːz/","meaning":"v.逗乐,逗笑","seq":82,"isStar":false,"memo":"[联想] a(一)+muse(联想“缪斯”)→缪斯是希腊神话中掌管艺术的神,通常会给人们带来欢乐→逗乐,逗笑","example":"My funny drawings amused the kids. 我的滑稽图画把孩子们逗乐了。"},{"id":623,"unit":3,"lesson":1,"word":"amusement","pronunciation":"/əˈmjuːzmənt/","meaning":"n.娱乐,消遣活动","seq":83,"isStar":false},{"id":624,"unit":3,"lesson":1,"word":"amusing","pronunciation":"/əˈmjuːzɪŋ/","meaning":"adj.逗人笑的;有乐趣的;好笑的","seq":84,"isStar":false},{"id":625,"unit":3,"lesson":1,"word":"amaze","pronunciation":"/əˈmeɪz/","meaning":"v.使惊奇;使惊愕","seq":85,"isStar":false,"memo":"[谐音] 单词发音类似“啊妹子”→啊,妹子上大学后变化好大啊→使惊奇","example":"Just the size of the place amazed her. 仅仅地方之大就使她十分惊奇。"},{"id":626,"unit":3,"lesson":1,"word":"amazing","pronunciation":"/əˈmeɪzɪŋ/","meaning":"adj.令人惊奇的;令人惊喜的","seq":86,"isStar":false},{"id":627,"unit":3,"lesson":1,"word":"amazement","pronunciation":"/əˈmeɪzmənt/","meaning":"n.惊奇;惊愕","seq":87,"isStar":false},{"id":628,"unit":3,"lesson":1,"word":"startle","pronunciation":"/ˈstɑːt(ə)l/","meaning":"v.使惊吓,使吓一跳","seq":88,"isStar":false,"memo":"[联想] start(开始)+le(联想“了”)→他一到学校,班主任就说考试开始了,把他吓了一跳→使惊吓","example":"The sound of the explosion startled me. 爆炸声把我吓了一跳。"},{"id":629,"unit":3,"lesson":1,"word":"obtain","pronunciation":"/əbˈteɪn/","meaning":"v.(尤指经努力)获得,赢得","seq":89,"isStar":false,"memo":"[联想] ob-(表示方向)+tain(拿)→朝某个方向拿着→获得,赢得","example":"I've been trying to obtain permission to publish this material. 我一直在试图获得出版这份材料的许可。"},{"id":630,"unit":3,"lesson":1,"word":"obtainment","pronunciation":"/əbˈteɪnmənt/","meaning":"n.获得","seq":90,"isStar":false},{"id":631,"unit":3,"lesson":2,"word":"disturb","pronunciation":"/dɪˈstɜːb/","meaning":"v.打扰;弄乱;使不安","seq":1,"isStar":false,"memo":"[谐音] 单词发音类似“弟,是他不”→“打扰”弟弟学习的人是他不?","example":"Don't disturb the papers on my desk. 别把我桌上的论文弄乱了。"},{"id":632,"unit":3,"lesson":2,"word":"disturbance","pronunciation":"/dɪˈstɜːbəns/","meaning":"n.(受)干扰;骚乱","seq":2,"isStar":false,"memo":"[构词] disturb(打扰) + -ance(名词后缀)→干扰;骚乱","example":"During the disturbance which followed, three Englishmen were hurt. 在随后的骚乱中,三个英国人受伤了。"},{"id":633,"unit":3,"lesson":2,"word":"offend","pronunciation":"/əˈfend/","meaning":"v.得罪;冒犯;违反;犯罪","seq":3,"isStar":false,"memo":"[联想] off(离开) + end(最后)→他最后离开了,因为他感觉到被“冒犯”了。","example":"Neil did not mean to offend anybody with his joke. 尼尔开那个玩笑并非想冒犯谁。"},{"id":634,"unit":3,"lesson":2,"word":"offence/-se","pronunciation":"/əˈfens/","meaning":"n.犯罪;冒犯","seq":4,"isStar":false,"memo":"构词 of-(向)+fens(打击，同 defend 防御)+-e→反过来打击别人→犯罪；冒犯","example":"He was arrested for a serious offence. 他因一项严重罪行被捕。"},{"id":635,"unit":3,"lesson":2,"word":"offensive","pronunciation":"/əˈfensɪv/","meaning":"n.进攻;攻击 adj.冒犯的;攻击性的","seq":5,"isStar":false},{"id":636,"unit":3,"lesson":2,"word":"offender","pronunciation":"/əˈfendə(r)/","meaning":"n.罪犯;妨害……的人(或事物)","seq":6,"isStar":false},{"id":637,"unit":3,"lesson":2,"word":"defend","pronunciation":"/dɪˈfend/","meaning":"v.防御;保卫","seq":7,"isStar":false,"memo":"[联想] de(音似“弟”) + f(联想“飞”) + end(最后)→弟弟飞奔过来“保卫”我们,坚持到最后。","example":"Humans can defend themselves against any potential danger. 人类能够保护自己,抵御任何潜在的危险。"},{"id":638,"unit":3,"lesson":2,"word":"defence/-se","pronunciation":"/dɪˈfens/","meaning":"n.防御;辩护","seq":8,"isStar":false,"memo":"构词 de-(去除)+fens(打击)+-e→把打击挡回去→防御；辩护","example":"The walls were built for defence. 这些城墙是为防御而建的。"},{"id":639,"unit":3,"lesson":2,"word":"defensive","pronunciation":"/dɪˈfensɪv/","meaning":"adj.防御的;自卫的","seq":9,"isStar":false},{"id":640,"unit":3,"lesson":2,"word":"defendant","pronunciation":"/dɪˈfendənt/","meaning":"n.被告人","seq":10,"isStar":false},{"id":641,"unit":3,"lesson":2,"word":"intrude","pronunciation":"/ɪnˈtruːd/","meaning":"v.闯入,侵入;打扰","seq":11,"isStar":false,"memo":"[联想] in-(里面) + tru(联想 true) + de(联想“弟”)→弟弟真的在屋里面,他没打声招呼就“闯入”了屋里。","example":"Arizona had thus intruded on the federal's powers. 亚利桑那州因此侵犯了联邦政府的权力。"},{"id":642,"unit":3,"lesson":2,"word":"intrusion","pronunciation":"/ɪnˈtruːʒ(ə)n/","meaning":"n.侵扰性的事物;扰乱","seq":12,"isStar":false},{"id":643,"unit":3,"lesson":2,"word":"intruder","pronunciation":"/ɪnˈtruːdə(r)/","meaning":"n.闯入者,侵入者","seq":13,"isStar":false},{"id":644,"unit":3,"lesson":2,"word":"invade","pronunciation":"/ɪnˈveɪd/","meaning":"v.侵略;入侵;涌入","seq":14,"isStar":false,"memo":"[对照] 有人入侵(invade),快点逃走(evade)。","example":"They invaded the house at all hours and without warning. 他们随时会入侵这所房子,不会有任何预警。"},{"id":645,"unit":3,"lesson":2,"word":"invasion","pronunciation":"/ɪnˈveɪʒ(ə)n/","meaning":"n.侵略;入侵","seq":15,"isStar":false},{"id":646,"unit":3,"lesson":2,"word":"invasive","pronunciation":"/ɪnˈveɪsɪv/","meaning":"adj.侵入的;侵袭的","seq":16,"isStar":false},{"id":647,"unit":3,"lesson":2,"word":"invader","pronunciation":"/ɪnˈveɪdə(r)/","meaning":"n.武装入侵的军队(或国家);侵略者","seq":17,"isStar":false},{"id":648,"unit":3,"lesson":2,"word":"shield","pronunciation":"/ʃiːld/","meaning":"n.盾(牌);保护人;掩护物 v.保护","seq":18,"isStar":false,"memo":"联想 shi(音似 she)+eld(联想 elder)→她老了,需要人“保护”。","example":"His successes seemed to act as a shield against this.他的成功似乎成了对抗这一切的盾牌。"},{"id":649,"unit":3,"lesson":2,"word":"helmet","pronunciation":"/ˈhelmɪt/","meaning":"n.头盔,防护帽","seq":19,"isStar":false,"memo":"联想 hel(联想 help,帮助)+me(我)+t(联想“头”)→“头盔”能帮助我保护头部。","example":"Surgeons wear virtual reality helmets to receive feedback provided by a computer.外科医生佩戴虚拟现实头盔,接收计算机提供的反馈。"},{"id":650,"unit":3,"lesson":2,"word":"safeguard","pronunciation":"/ˈseɪfɡɑːd/","meaning":"n.保障条款;保护措施 v.保护,保卫","seq":20,"isStar":false,"memo":"构词 safe(安全的)+guard(保卫)→保卫","example":"Whether it's possible to program a robot with safeguards such as Asimov's laws is debatable.是否有可能为机器人编写像阿西莫夫定律这样的保护程序是有争议的。"},{"id":651,"unit":3,"lesson":2,"word":"guard","pronunciation":"/ɡɑːd/","meaning":"n.卫兵,警卫;警戒,保卫 v.守卫","seq":21,"isStar":false,"memo":"联想 与 garden(花园)形近：守在花园门口的人→卫兵，警卫；守卫","example":"She is the daughter of a prison guard.她是一个狱警的女儿。"},{"id":652,"unit":3,"lesson":2,"word":"guardian","pronunciation":"/ˈɡɑːdiən/","meaning":"n.保护者;监护人","seq":22,"isStar":false},{"id":653,"unit":3,"lesson":2,"word":"regard","pronunciation":"/rɪˈɡɑːd/","meaning":"n.关注;尊重 v.将……认为;看待","seq":23,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+gard(联想 guard)→阿姨每次出门都向警卫打招呼,以示“尊重”。","example":"He was driving without regard to speed limits.他开着车,根本不理会速度限制。"},{"id":654,"unit":3,"lesson":2,"word":"disregard","pronunciation":"/ˌdɪsrɪˈɡɑːd/","meaning":"n.忽视 v.不理会;漠视","seq":24,"isStar":false,"memo":"构词 dis-(表否定)+regard(注视)→不注视→漠视","example":"He totally disregarded all the advice he was given.他完全无视别人给他的所有建议。"},{"id":655,"unit":3,"lesson":2,"word":"regarding","pronunciation":"/rɪˈɡɑːdɪŋ/","meaning":"prep.关于,至于","seq":25,"isStar":false,"memo":"构词 regard(看待、关于)+-ing(分词转介词)→就……而言→关于，至于","example":"Nature is quite fair regarding the survival of turtles. 在海龟的生存方面,大自然是很公平的。"},{"id":656,"unit":3,"lesson":2,"word":"regardless","pronunciation":"/rɪˈɡɑːdləs/","meaning":"adv.不顾;不管怎样","seq":26,"isStar":false,"memo":"构词 regard(顾及)+-less(无…的)→一点不顾及的→不顾；不管怎样","example":"The law requires equal treatment for all, regardless of race, religion or sex. 法律规定人人平等,不分种族、宗教或性别。"},{"id":657,"unit":3,"lesson":2,"word":"endanger","pronunciation":"/ɪnˈdeɪndʒə(r)/","meaning":"v.危及,危害","seq":27,"isStar":false,"memo":"[构词] en-(使) + danger(危险)→危及","example":"They endanger lots of water life. 它们危及了许多水生生物。"},{"id":658,"unit":3,"lesson":2,"word":"hazard","pronunciation":"/ˈhæzəd/","meaning":"n.危险,危害 v.冒……的风险","seq":28,"isStar":false,"memo":"[谐音] 单词发音类似“害咱的”→这种行为会危害咱们的利益,所以千万别冒险→危害;冒……的风险","example":"Careless drivers hazard other people's lives as well as their own. 粗心大意的驾驶员拿他人和自己的生命冒险。"},{"id":659,"unit":3,"lesson":2,"word":"hazardous","pronunciation":"/ˈhæzədəs/","meaning":"adj.危险的;有害的","seq":29,"isStar":false},{"id":660,"unit":3,"lesson":2,"word":"harass","pronunciation":"/ˈhærəs/","meaning":"v.侵扰;骚扰;不断攻击(敌人)","seq":30,"isStar":false,"memo":"谐音 单词发音类似“害汝思”→他的“骚扰”害你思路被打断。","example":"He claims he has been harassed at work.他声称自己工作中受到骚扰。"},{"id":661,"unit":3,"lesson":2,"word":"harassment","pronunciation":"/ˈhærəsmənt/","meaning":"n.侵扰;骚扰","seq":31,"isStar":false},{"id":662,"unit":3,"lesson":2,"word":"stake","pronunciation":"/steɪk/","meaning":"n.股份;赌注 v.以……打赌","seq":32,"isStar":false,"memo":"[联想] s(联想“蛇”) + take(拿)→拿蛇很危险,不要拿生命作“赌注”。","example":"She staked her career on tax reform, and lost. 她把自己的前程押在税制改革上,结果赌输了。"},{"id":663,"unit":3,"lesson":2,"word":"venture","pronunciation":"/ˈventʃə(r)/","meaning":"n.投机活动;冒险事业,企业 v.冒险","seq":33,"isStar":false,"memo":"[联想] vent(联想 went) + (t)ure 联想(true) →他真的去“冒险”了。","example":"It might be a venture for me to take part in the match. 参加这场比赛对我来说可能是一种冒险。"},{"id":664,"unit":3,"lesson":2,"word":"adventure","pronunciation":"/ədˈventʃə(r)/","meaning":"n.冒险,奇遇;大胆开拓","seq":34,"isStar":false,"memo":"[构词] ad-(=to,朝向) + venture(冒险)→冒险","example":"Age hasn't blunted his passion for adventure. 岁月没有冲淡他的冒险激情。"},{"id":665,"unit":3,"lesson":2,"word":"adventurer","pronunciation":"/ədˈventʃərə(r)/","meaning":"n.冒险者;冒险家","seq":35,"isStar":false},{"id":666,"unit":3,"lesson":2,"word":"adventurous","pronunciation":"/ədˈventʃərəs/","meaning":"adj.有冒险精神的;大胆开拓的","seq":36,"isStar":false},{"id":667,"unit":3,"lesson":2,"word":"experience","pronunciation":"/ɪkˈspɪəriəns/","meaning":"n.经验;经历,体验 v.经历,体验","seq":37,"isStar":false,"memo":"[联想] ex-(出) + per(每) + (r)i(联想“日”) + -ence(后缀)→每日都出去“经历”不同的事,以获得更多的人生“经验”。","example":"The experience makes us feel less successful and leads us to discount our ability to change in the future. 这种经历使我们越来越没有成功感,也导致我们低估了改变未来的能力。"},{"id":668,"unit":3,"lesson":2,"word":"experienced","pronunciation":"/ɪkˈspɪəriənst/","meaning":"adj.有经验的,熟练的;有阅历的","seq":38,"isStar":false},{"id":669,"unit":3,"lesson":2,"word":"advent","pronunciation":"/ˈædvent/","meaning":"n.(重要事件、人物、发明的)出现;到来","seq":39,"isStar":false,"memo":"[联想] ad-(一再地) + vent(联想 went)→一再地朝着你的方向去→他“出现”在你面前。","example":"The advent of the new government resulted in many changes. 新政府的到来引发了许多变化。"},{"id":670,"unit":3,"lesson":2,"word":"vent","pronunciation":"/vent/","meaning":"n.(空气、气体、液体的)出口","seq":40,"isStar":false,"memo":"对照 音近词 went→我心情不好,去(went)发泄(vent)一下。","example":"She telephoned her best friend to vent her frustration. 她打电话给自己最好的朋友来发泄她的沮丧。"},{"id":671,"unit":3,"lesson":2,"word":"ventilate","pronunciation":"/ˈventɪleɪt/","meaning":"v.使通风;(用呼吸机)给……供氧","seq":41,"isStar":false,"memo":"联想 vent(联想 went)+i(我)+late(晚)→我去晚了,热得不行,需要打开窗户透透气→使通风","example":"The bathroom is ventilated by means of an extractor fan. 这个浴室使用抽风扇通风。"},{"id":672,"unit":3,"lesson":2,"word":"ventilation","pronunciation":"/ˌventɪˈleɪʃn/","meaning":"n.通风;通风系统","seq":42,"isStar":false},{"id":673,"unit":3,"lesson":2,"word":"circulate","pronunciation":"/ˈsɜːkjəleɪt/","meaning":"v.(使)循环;传播","seq":43,"isStar":false,"memo":"联想 circul(联想 circle)+-ate(动词后缀)→使环绕→循环;传播","example":"The condition prevents the blood from circulating freely. 这种病阻碍了血液的畅通循环。"},{"id":674,"unit":3,"lesson":2,"word":"circulation","pronunciation":"/ˌsɜːkjəˈleɪʃ(ə)n/","meaning":"n.血液循环;流通;发行量","seq":44,"isStar":false},{"id":675,"unit":3,"lesson":2,"word":"circuit","pronunciation":"/ˈsɜːkɪt/","meaning":"n.环形道路;环行;电路;巡回","seq":45,"isStar":false,"memo":"联想 circu(联想 circle)+it(它)→它是圆形或环形的→环形道路;环行","example":"The judge made a circuit of the courtroom before starting the hearing. 法官在开始听证会之前在法庭上巡视了一圈。"},{"id":676,"unit":3,"lesson":2,"word":"whirl","pronunciation":"/wɜːl/","meaning":"n.旋转;接连不断的活动 v.旋转;恍惚","seq":46,"isStar":false,"memo":"对照 音近词 world→地球(world)是宇宙的一部分,是旋转(whirl)的。","example":"All these thoughts whirled through his brain. 所有的这些想法都在他的脑子里转来转去。"},{"id":677,"unit":3,"lesson":2,"word":"gamble","pronunciation":"/ˈɡæmb(ə)l/","meaning":"n.冒险 v.冒险;赌博","seq":47,"isStar":false,"memo":"谐音 单词发音类似“干部”→这部电影讲述了一个干部“冒险”实施禁毒行动的故事。","example":"So if you have a long-term goal in mind, it may be worth taking a gamble. 所以,如果你心中有一个长期目标,那么也许值得冒险。"},{"id":678,"unit":3,"lesson":2,"word":"jeopardy","pronunciation":"/ˈdʒepədi/","meaning":"n.危险,风险;危险境地","seq":48,"isStar":false,"memo":"谐音 单词发音类似“姐怕弟”→姐姐为弟弟担惊受怕,因为他处境很“危险”。","example":"Thousands of jobs could be in jeopardy.成千上万的工作岗位可能面临危险。"},{"id":679,"unit":3,"lesson":2,"word":"jeopardise/-ize","pronunciation":"/ˈdʒepədaɪz/","meaning":"v.损害,危及","seq":49,"isStar":false,"memo":"构词 jeopard(危险，同 jeopardy 危险)+-ise/-ize(使…化)→使陷进危险里→损害，危及","example":"Careless spending could jeopardise the whole project. 花钱不慎可能危及整个项目。"},{"id":680,"unit":3,"lesson":2,"word":"peril","pronunciation":"/ˈperəl/","meaning":"n.巨大的危险,危难","seq":50,"isStar":false,"memo":"谐音 单词发音类似“派弱”→派弱者应战,团队会陷入“危难”之中。","example":"Yet, there are signs of peril within American higher education.然而，美国高等教育内部出现了危险的迹象。"},{"id":681,"unit":3,"lesson":2,"word":"perilous","pronunciation":"/ˈperələs/","meaning":"adj.危险的,艰险的","seq":51,"isStar":false},{"id":682,"unit":3,"lesson":2,"word":"fortune","pronunciation":"/ˈfɔːtʃuːn/","meaning":"n.机会,运气;巨款;命运","seq":52,"isStar":false,"memo":"联想 for(为了) + tune(联想“吃”) → 为了孩子吃得好一些,父母去大城市碰“运气”找工作。","example":"Soon after, Andreasen went to seek his fortune in Silicon Valley. 不久之后,安德烈亚森就去硅谷寻求发迹机会了。"},{"id":683,"unit":3,"lesson":2,"word":"fortunate","pronunciation":"/ˈfɔːtʃənət/","meaning":"adj.幸运的;吉利的","seq":53,"isStar":false},{"id":684,"unit":3,"lesson":2,"word":"misfortune","pronunciation":"/ˌmɪsˈfɔːtʃuːn/","meaning":"n.不幸;不幸的事故;厄运","seq":54,"isStar":false,"memo":"构词 mis-(否定前缀) + fortune(运气) → 不幸;厄运","example":"She bore her misfortunes bravely. 她勇敢地承受不幸的遭遇。"},{"id":685,"unit":3,"lesson":2,"word":"mislead","pronunciation":"/ˌmɪsˈliːd/","meaning":"v.误导,引人歧途","seq":55,"isStar":false,"memo":"构词 mis-(错误) + lead(领导) → 误导,引入歧途","example":"He deliberately misled us about the nature of their relationship. 他故意就他们关系的本质误导了我们。"},{"id":686,"unit":3,"lesson":2,"word":"misleading","pronunciation":"/ˌmɪsˈliːdɪŋ/","meaning":"adj.误导的,引人歧途的","seq":56,"isStar":false},{"id":687,"unit":3,"lesson":2,"word":"steer","pronunciation":"/stɪə(r)/","meaning":"v.驾驶;引导","seq":57,"isStar":false,"memo":"联想 st(联想 street) + ee(形似两只眼睛) + r(联想“人”) → 刚学会“驾驶”的人在街上开车时,常会瞪着两只眼睛紧张地看着前方。","example":"He steered the boat into the harbour. 他把船开进港。"},{"id":688,"unit":3,"lesson":3,"word":"pretext","pronunciation":"/ˈpriːtekst/","meaning":"n.借口,托辞","seq":1,"isStar":false,"memo":"pre-(预先)+text(文本)→预先准备好的文本→借口","example":"Very often landlords don't return tenants' deposits on the pretext that tenants have done damage to the house. 房东经常以房客损坏房屋为借口,不退还房客的押金。"},{"id":689,"unit":3,"lesson":3,"word":"protest","pronunciation":"/ˈprəʊtest/","meaning":"n.抗议,反对","seq":2,"isStar":false,"memo":"pro-(提前)+test(考试)→老师把考试时间提前了,学生们表示“抗议”,以争取更多的复习时间。","example":"I'm the action organiser and arrange any protests. 我是行动组织者,安排一切抗议活动。"},{"id":690,"unit":3,"lesson":3,"word":"contest","pronunciation":"/ˈkɒntest/","meaning":"n.竞争;比赛 v.争辩","seq":3,"isStar":false,"memo":"con-(一起)+test(考试)→当一起考试的时候,我们之间是“竞争”关系。","example":"In 1995, the CIA held a contest to see who could compile the most data about Burundi. 1995年,美国中央情报局举办了一场比赛,看谁能收集到最多关于布隆迪的数据。"},{"id":691,"unit":3,"lesson":3,"word":"contestant","pronunciation":"/kənˈtestənt/","meaning":"n.比赛者;竞争者","seq":4,"isStar":false},{"id":692,"unit":3,"lesson":3,"word":"provoke","pronunciation":"/prəˈvəʊk/","meaning":"v.激起,引起;激怒","seq":5,"isStar":false,"memo":"pro-(提前)+voke(联想“我”)→拳击比赛开始之前,我就剋(打)了对手一拳,“激怒”了他。","example":"Dream activity may be provoked by external influences. 梦的活动可能是由外界影响引起的。"},{"id":693,"unit":3,"lesson":3,"word":"provocation","pronunciation":"/ˌprɒvəˈkeɪʃ(ə)n/","meaning":"n.挑衅,激怒","seq":6,"isStar":false},{"id":694,"unit":3,"lesson":3,"word":"provocative","pronunciation":"/prəˈvɒkətɪv/","meaning":"adj.挑衅的,激起争端的","seq":7,"isStar":false},{"id":695,"unit":3,"lesson":3,"word":"evoke","pronunciation":"/ɪˈvəʊk/","meaning":"v.引起,唤起(感情、记忆或形象)","seq":8,"isStar":false,"memo":"e(字母音似“姨”)+voke(联想“我剋”)→姨和我都出去剋(打)他,“引起”了他的愤怒。","example":"The music evoked memories of her youth. 这乐曲勾起了她对青年时代的回忆。"},{"id":696,"unit":3,"lesson":3,"word":"advocate","pronunciation":"/ˈædvəkeɪt/","meaning":"n.支持者;辩护律师 v.支持;提倡","seq":9,"isStar":false,"memo":"ad-(一再地)+voc(说)+-ate(动词后缀)→一再地说→支持;提倡","example":"It is evident that the writer advocates the idea of returning to nature. 很明显,作者提倡回归自然的思想。"},{"id":697,"unit":3,"lesson":3,"word":"advocacy","pronunciation":"/ˈædvəkəsi/","meaning":"n.拥护,支持;提倡","seq":10,"isStar":false},{"id":698,"unit":3,"lesson":3,"word":"profound","pronunciation":"/prəˈfaʊnd/","meaning":"adj.巨大的;深远的;知识渊博的","seq":11,"isStar":false,"memo":"pro-(提前)+found(建立)→提前建立的学校根基深厚,影响就是“巨大的”。","example":"Young people's social environment has a profound effect on their academic progress. 年轻人所处的社会环境对他们的学业进步有着深远的影响。"},{"id":699,"unit":3,"lesson":3,"word":"profile","pronunciation":"/ˈprəʊfaɪl/","meaning":"n.概述,简介;(侧面)轮廓;面部的侧影","seq":12,"isStar":false,"memo":"pro-(前面)+file(文件)→前面文件中有项目“简介”。","example":"I only saw her in profile. 我只看到了她的侧脸。"},{"id":700,"unit":3,"lesson":3,"word":"previous","pronunciation":"/ˈpriːviəs/","meaning":"adj.先前的,以前的","seq":13,"isStar":false,"memo":"pre-(在……之前)+vi(音似 we)+-ous(形容词后缀)→之前的我们→先前的,以前的","example":"Do they face more challenges than any previous generation? 他们比以往任何一代人都面临更多的挑战吗?"},{"id":701,"unit":3,"lesson":3,"word":"prevalent","pronunciation":"/ˈprevələnt/","meaning":"adj.普遍存在的;盛行的,流行的","seq":14,"isStar":false,"memo":"pre-(提前)+va(音似“我”)+lent(lend 的过去式,借)→我提前借到“普遍存在的”案例书籍学习。","example":"Taking charge of yourself involves putting to rest some very prevalent myths. 掌控自我需要摒弃一些非常普遍的谬论。"},{"id":702,"unit":3,"lesson":3,"word":"prevalence","pronunciation":"/ˈprevələns/","meaning":"n.流行,普遍","seq":15,"isStar":false},{"id":703,"unit":3,"lesson":3,"word":"pop","pronunciation":"/pɒp/","meaning":"v.蹦出;发出爆裂声 adj.流行的","seq":16,"isStar":false,"memo":"popular adj.流行的→pop adj.","example":"Nowadays most people like to listen to pop and rock music. 现在,多数人喜欢听流行音乐和摇滚乐。"},{"id":704,"unit":3,"lesson":3,"word":"prevail","pronunciation":"/prɪˈveɪl/","meaning":"v.盛行,流行;获胜,战胜,压倒","seq":17,"isStar":false,"memo":"pre-(在……之前)+vail(力量,强大)→盛行","example":"Fortunately, common sense prevailed. 幸而理智占了上风。"},{"id":705,"unit":3,"lesson":3,"word":"avail","pronunciation":"/əˈveɪl/","meaning":"n.效用,利益 v.有帮助,有益;利用","seq":18,"isStar":false,"memo":"available adj.可获得的→avail n.&v.","example":"Your ability to argue is of little avail if the facts are wrong. 如果事实是错误的,那么你的辩论能力就没什么用处了。"},{"id":706,"unit":3,"lesson":3,"word":"available","pronunciation":"/əˈveɪləb(ə)l/","meaning":"adj.可获得的,可购得的;可找到的","seq":19,"isStar":false,"memo":"谐音+构词：a-vail-able → '哎！我来able！'——资源一喊就到，随时可用！","example":"The new AI tools are now available to all registered students. 新的人工智能工具现已向所有注册学生开放。"},{"id":707,"unit":3,"lesson":3,"word":"availability","pronunciation":"/əˌveɪləˈbɪləti/","meaning":"n.可用性;实用性","seq":20,"isStar":false,"memo":"联想 ad-(一再地) + voc(说) + -ate(动词后缀)→一再地说→支持;提倡","example":"The widespread availability of broadband is making the introduction of remote working a piece of cake.宽带的普及使远程工作的引入变得轻而易举。"},{"id":708,"unit":3,"lesson":3,"word":"proficient","pronunciation":"/prəˈfɪʃ(ə)nt/","meaning":"adj.熟练的;精通的;训练有素的","seq":21,"isStar":false,"memo":"联想 pro-(提前)+ficient(音似“费心地”)→他比其他同学提前一年费心地背单词,对单词的掌握必然是“熟练的”。","example":"She's proficient in several languages.她精通几门语言。"},{"id":709,"unit":3,"lesson":3,"word":"proficiency","pronunciation":"/prəˈfɪʃ(ə)nsi/","meaning":"n.精通;熟练","seq":22,"isStar":false},{"id":710,"unit":3,"lesson":3,"word":"artificial","pronunciation":"/ˌɑːtɪˈfɪʃ(ə)l/","meaning":"adj.人工的,人为的;虚假的","seq":23,"isStar":false,"memo":"联想 art(艺术) + i(形似人) + ficial(音似“费心”)→艺术是人费心创造出来的→人工的","example":"Artificial intelligence is the key to future technological innovation. 人工智能是未来技术创新的关键。"},{"id":711,"unit":3,"lesson":3,"word":"sufficient","pronunciation":"/səˈfɪʃ(ə)nt/","meaning":"adj.足够的,充足的","seq":24,"isStar":false,"memo":"谐音 单词发音类似“血费心”→如果你为一件事费尽心血，那就很有可能做得足够好→足够的，充足的","example":"Whether all that attention has translated into sufficient action is another question. 所有的关注是否已经转化为足够的行动，这是另一个问题。"},{"id":712,"unit":3,"lesson":3,"word":"suffice","pronunciation":"/səˈfaɪs/","meaning":"v.足够,足以","seq":25,"isStar":false,"memo":"对照 sufficient adj. 足够的，充足的 → suffice v.","example":"Numerous examples can be given, but this will suffice. 可以举出许多例子，但这个例子就足够了。"},{"id":713,"unit":3,"lesson":3,"word":"efficient","pronunciation":"/ɪˈfɪʃ(ə)nt/","meaning":"adj.效率高的;有能力的","seq":26,"isStar":false,"memo":"谐音 单词发音类似“一飞身他”→别人爬楼梯来上课，而他一飞身就上来了，说明他是“效率高的”。","example":"The emergency services are efficient. 应急服务机构很有效率。"},{"id":714,"unit":3,"lesson":3,"word":"efficiency","pronunciation":"/ɪˈfɪʃ(ə)nsi/","meaning":"n.效率","seq":27,"isStar":false},{"id":715,"unit":3,"lesson":3,"word":"deficient","pronunciation":"/dɪˈfɪʃ(ə)nt/","meaning":"adj.缺乏的;有缺陷的","seq":28,"isStar":false,"memo":"谐音 单词发音类似“弟费心的”→弟弟做什么都不费心思，做的事总是“有缺陷的”。","example":"The agricultural commodities were deficient that year. 那年的农业产品供应不足。"},{"id":716,"unit":3,"lesson":3,"word":"deficiency","pronunciation":"/dɪˈfɪʃ(ə)nsi/","meaning":"n.缺乏;缺点","seq":29,"isStar":false,"memo":"构词 de-(向下)+fic(做，同 efficient 高效的)+-iency(名词后缀)→做得不到位→缺乏；缺点","example":"Vitamin deficiency in the diet can cause illness. 饮食中缺乏维生素会导致疾病。"},{"id":717,"unit":3,"lesson":3,"word":"flaw","pronunciation":"/flɔː/","meaning":"n.瑕疵,缺点;错误;缺陷","seq":30,"isStar":false,"memo":"f(联想 false,错误的)+law(法律)→法律意义上的“瑕疵”可能会引发错误决策。","example":"I am writing this letter to express my complaint against the flaws in your product. 我写这封信是为了表达我对你们产品缺陷的不满。"},{"id":718,"unit":3,"lesson":3,"word":"flawless","pronunciation":"/ˈflɔːləs/","meaning":"adj.完美的;无瑕的","seq":31,"isStar":false},{"id":719,"unit":3,"lesson":3,"word":"drawback","pronunciation":"/ˈdrɔːbæk/","meaning":"n.缺点;不利条件","seq":32,"isStar":false,"memo":"draw(拖)+back(后面)→做事时拖你后腿的往往是自身的“缺点”。","example":"Many pure metals have little use because they are too soft, rust too easily, or have some other drawbacks. 许多纯金属用处不大,因为它们太软,太容易生锈,或有一些其他缺点。"},{"id":720,"unit":3,"lesson":3,"word":"setback","pronunciation":"/ˈsetbæk/","meaning":"n.挫折,阻碍","seq":33,"isStar":false,"memo":"set(设置)+back(后退)→游戏中设置的让玩家后退的是“挫折”。","example":"Recently we have had a number of setbacks with the machinery. 最近我们在机械方面遇到了一些阻碍。"},{"id":721,"unit":3,"lesson":3,"word":"handicap","pronunciation":"/ˈhændikæp/","meaning":"n.残疾,生理缺陷;障碍 v.妨碍","seq":34,"isStar":false,"memo":"hand(手)+i(我)+cap(帽子)→我手上总盖着一个帽子,是为了遮掩手上的“残疾”。","example":"Despite her handicap, Jane is able to hold down a full-time job. 简尽管有生理缺陷,也能够保住一份全职工作。"},{"id":722,"unit":3,"lesson":3,"word":"handicapped","pronunciation":"/ˈhændikæpt/","meaning":"adj.有生理缺陷的,残疾的","seq":35,"isStar":false,"memo":"联想 源自旧时残疾者手拿帽子(cap)乞讨→hand+i+cap+-ed→手拿帽子的→有生理缺陷的，残疾的","example":"The stadium has seats for handicapped visitors. 体育场设有残疾人专座。"},{"id":723,"unit":3,"lesson":3,"word":"fault","pronunciation":"/fɔːlt/","meaning":"n.责任;过失;缺点;故障 v.找出缺点","seq":36,"isStar":false,"memo":"fau(音似 for)+l(联想“了”)+t(联想“他”)→为了他的“过失”,我也负了相应“责任”。","example":"But who's at fault for its overuse? 但谁该为它的过度使用负责呢?"},{"id":724,"unit":3,"lesson":3,"word":"default","pronunciation":"/dɪˈfɔːlt; ˈdiːfɔːlt/","meaning":"n.违约;拖欠;(术语)默认 v.违约","seq":37,"isStar":false,"memo":"de(音似“弟”)+fault(错误)→弟弟的错误在于“违约”。","example":"The company is in default on the loan. 这家公司拖欠借款。"},{"id":725,"unit":3,"lesson":3,"word":"infringe","pronunciation":"/ɪnˈfrɪndʒ/","meaning":"v.违反(法律);侵犯(他人权利)","seq":38,"isStar":false,"memo":"in(里面)+fr(联想“夫人”)+inge→夫人被关在里面,因为她“违反”了法律。","example":"The company is punished for infringing on small farmers' interests.该公司因侵犯小农户的利益而受到处罚。"},{"id":726,"unit":3,"lesson":3,"word":"infringement","pronunciation":"/ɪnˈfrɪndʒmənt/","meaning":"n.侵犯;违背","seq":39,"isStar":false},{"id":727,"unit":3,"lesson":3,"word":"breach","pronunciation":"/briːtʃ/","meaning":"n.&v.违背;违反;破坏","seq":40,"isStar":false,"memo":"brea(联想 break,破坏)+ch→违反;破坏","example":"They sued the company for breach of contract.他们以违约为由起诉该公司。"},{"id":728,"unit":3,"lesson":3,"word":"refer","pronunciation":"/rɪˈfɜː(r)/","meaning":"v.提到,谈及;参考;涉及","seq":41,"isStar":false,"memo":"[联想] re-(重复) + fer(音似“佛”)→他反复地“提到”佛。","example":"The report refers to this as the coming of the “18-hour city”. 该报告称这是“18小时城市”的到来。"},{"id":729,"unit":3,"lesson":3,"word":"reference","pronunciation":"/ˈrefrəns/","meaning":"n.谈及;参考;参考书目","seq":42,"isStar":false,"memo":"构词 re-(回)+fer(带来，同 refer 提及)+-ence(名词后缀)→把话带回某处→谈及；参考，参考书目","example":"Nowadays, his reading material has changed from science fiction and reference books. 如今,他的阅读材料已经不再是科幻小说和参考书了。"},{"id":730,"unit":3,"lesson":3,"word":"referee","pronunciation":"/ˌrefəˈriː/","meaning":"n.裁判员;介绍人;推荐人 v.当裁判","seq":43,"isStar":false,"memo":"记 (构词) refer(提到)+-ee(表示人的后缀)→提到或谈及的人→介绍人;推荐人","example":"Restrict yourself to one or two pages, and list any publications or referees on a separate sheet.把自己限制在一两页内，把任何出版物或推荐人列在单独一页上。"},{"id":731,"unit":3,"lesson":3,"word":"confer","pronunciation":"/kənˈfɜː(r)/","meaning":"v.协商;授予(奖项、学位、荣誉或权利)","seq":44,"isStar":false,"memo":"[联想] con-(所有) + fer(音似“佛”)→所有这类情况都可以佛系地“协商”解决。","example":"I'll confer with him on the subject. 我将和他商议这件事。"},{"id":732,"unit":3,"lesson":3,"word":"conference","pronunciation":"/ˈkɒnfərəns/","meaning":"n.会议;商讨会","seq":45,"isStar":false,"memo":"构词 con-(一起)+fer(带来)+-ence(名词后缀)→把各方的意见带到一起→会议，商讨会","example":"She attended an international conference on climate. 她出席了一个关于气候的国际会议。"},{"id":733,"unit":3,"lesson":3,"word":"fertile","pronunciation":"/ˈfɜːtaɪl/","meaning":"adj.肥沃的;能结果的","seq":46,"isStar":false,"memo":"[谐音] 单词发音类似“佛头”→《西游记》中有一棵“能结果的”树,树上结了很多人参果,长得酷似佛头。","example":"They turned the wasteland into fertile farmland. 他们把那片荒地变成了肥沃的农田。"},{"id":734,"unit":3,"lesson":3,"word":"fertiliser/-izer","pronunciation":"/ˈfɜːtəlaɪzə(r)/","meaning":"n.肥料,化肥","seq":47,"isStar":false,"memo":"构词 fertil(肥沃，同 fertile 肥沃的)+-iser/-izer(表物)→使土地肥沃的东西→肥料，化肥","example":"Farmers spread fertiliser over the fields. 农民在田里撒了化肥。"},{"id":735,"unit":3,"lesson":3,"word":"fertility","pronunciation":"/fəˈtɪləti/","meaning":"n.富饶;能生育性;可繁殖性","seq":48,"isStar":false},{"id":736,"unit":3,"lesson":3,"word":"infer","pronunciation":"/ɪnˈfɜː(r)/","meaning":"v.推断;暗示","seq":49,"isStar":false,"memo":"[联想] in(里面) + fer(音似“佛”)→佛的心里在想什么,我们不知道,只能“推断”。","example":"What can be inferred from the woman's answer? 从女士的回答中,我们可以推断出什么?"},{"id":737,"unit":3,"lesson":3,"word":"inference","pronunciation":"/ˈɪnfərəns/","meaning":"n.推断,推理,推论","seq":50,"isStar":false},{"id":738,"unit":3,"lesson":3,"word":"denote","pronunciation":"/dɪˈnəʊt/","meaning":"v.意指;表示,代表","seq":51,"isStar":false,"memo":"[谐音] 单词发音类似“弟闹他”→他“代表”闹情绪的弟弟去与人交涉。","example":"A rising line denotes growth. 上升的曲线表示增长。"},{"id":739,"unit":3,"lesson":3,"word":"denotation","pronunciation":"/ˌdiːnəʊˈteɪʃn/","meaning":"n.指称,指称之物,指称意义;外延","seq":52,"isStar":false,"memo":"构词 de-(加强)+not(标记，同 note 记录)+-ation(名词后缀)→标记出来的意思→指称，指称意义；外延","example":"The denotation of a word is its literal meaning. 一个词的字面含义就是它的外延。"},{"id":740,"unit":3,"lesson":3,"word":"imply","pronunciation":"/ɪmˈplaɪ/","meaning":"v.暗示,暗指;意味着","seq":53,"isStar":false,"memo":"联想 i(我)+m(联想“妹”)+ply(音似“扑来”)→我妹妹扑过来,“暗示”她受了委屈。","example":"What does the man imply? 这位男士暗示什么?"},{"id":741,"unit":3,"lesson":3,"word":"implication","pronunciation":"/ˌɪmplɪˈkeɪʃn/","meaning":"n.可能的影响(后果);含意,暗示;牵涉","seq":54,"isStar":false,"memo":"对照 imply v.暗示→implication n.","example":"And this finding could have important implications for how we think about educating adolescents. 这一发现对于我们如何看待青少年教育可能有重要的影响。"},{"id":742,"unit":3,"lesson":3,"word":"implicit","pronunciation":"/ɪmˈplɪsɪt/","meaning":"adj.含蓄的;内含的;隐含其中的","seq":55,"isStar":false,"memo":"对照 imply v.暗示→implicit adj.","example":"They found that implicit bias had fallen by as much as 90% compared with the level found in a similar study in 2006. 他们发现,与2006年的一项类似研究相比,内隐偏见下降了高达90%。"},{"id":743,"unit":3,"lesson":3,"word":"explicit","pronunciation":"/ɪkˈsplɪsɪt/","meaning":"adj.清楚明确的;直截了当的","seq":56,"isStar":false,"memo":"联想 ex-(向外)+plicit(联想 implicit)→不含蓄的→清楚明确的;直截了当的","example":"Creating so much confusion, Mason realised he had better make explicit what he was trying to tell the audience. 制造了这么多困惑后,梅森意识到他最好还是清楚明确地表达他想对观众说的内容。"},{"id":744,"unit":3,"lesson":3,"word":"exquisite","pronunciation":"/ɪkˈskwɪzɪt/","meaning":"adj.精美的,精致的;雅致的;敏锐的","seq":57,"isStar":false,"memo":"联想 ex-(出)+quis(联想 quire)+-ite(形容词后缀)→他出去探寻,发现无比“精致的”东西。","example":"We admired her exquisite handiwork. 我们欣赏了她精美的手工艺品。"},{"id":745,"unit":3,"lesson":3,"word":"elicit","pronunciation":"/ɪˈlɪsɪt/","meaning":"v.引出;探出","seq":58,"isStar":false,"memo":"联想 e-(出)+licit(引诱)→引出;探出","example":"I could elicit no response from him. 我从他那里探不出任何反应。"},{"id":746,"unit":3,"lesson":3,"word":"manifest","pronunciation":"/ˈmænɪfest/","meaning":"v.表明;显现 adj.明显的","seq":59,"isStar":false,"memo":"联想 ma(联想“妈”)+ni(联想“你”)+fest(音似“烦死他”)→妈妈和你都烦死他了,这是很“明显的”。","example":"Fear was manifest on her face. 她的脸上显露出惧怕的神情。"},{"id":747,"unit":3,"lesson":3,"word":"manifestation","pronunciation":"/ˌmænɪfeˈsteɪʃ(ə)n/","meaning":"n.显示;表明;表示","seq":60,"isStar":false},{"id":748,"unit":3,"lesson":3,"word":"indicate","pronunciation":"/ˈɪndɪkeɪt/","meaning":"v.表明,显示;指出;指示","seq":61,"isStar":false,"memo":"谐音 单词发音类似“硬递给他”→妈妈把书硬递给他,“指示”他今天要看完。","example":"Research indicates that eating habits are changing fast. 研究显示,饮食习惯正迅速改变。"},{"id":749,"unit":3,"lesson":3,"word":"indication","pronunciation":"/ˌɪndɪˈkeɪʃn/","meaning":"n.表明;显示;象征","seq":62,"isStar":false},{"id":750,"unit":3,"lesson":3,"word":"indicative","pronunciation":"/ɪnˈdɪkətɪv/","meaning":"adj.象征的;表明的","seq":63,"isStar":false,"memo":"对照 indicate v.表明;指示→indicative adj.","example":"Picasso gained popularity in the mid-20th century, which was indicative of a new attitude towards modern art. 毕加索在20世纪中期名声大噪,这象征着对现代艺术的新态度。"},{"id":751,"unit":3,"lesson":3,"word":"indicator","pronunciation":"/ˈɪndɪkeɪtə(r)/","meaning":"n.指示物;指示者;指针","seq":64,"isStar":false,"memo":"对照 indicate v.表明;指示→indicator n.","example":"He flipped his indicator, and took a left.他打了转向灯，然后左转。"},{"id":752,"unit":3,"lesson":3,"word":"demonstrate","pronunciation":"/ˈdemənstreɪt/","meaning":"v.证明,说明;演示;示威游行;表现","seq":65,"isStar":false,"memo":"联想 demon(精力充沛的人)+st(联想 street)+rate(速度)→一群精力充沛的人在街上快速狂奔,“证明”自己的能力。","example":"They do not often demonstrate risky behaviours as their peers. 他们不像同龄人那样经常表现出危险行为。"},{"id":753,"unit":3,"lesson":3,"word":"demonstration","pronunciation":"/ˌdemənˈstreɪʃ(ə)n/","meaning":"n.论证;示范;游行示威;表露","seq":66,"isStar":false},{"id":754,"unit":3,"lesson":3,"word":"demonstrative","pronunciation":"/dɪˈmɒnstrətɪv/","meaning":"adj.感情外露的;指示的 n.指示代词","seq":67,"isStar":false},{"id":755,"unit":3,"lesson":3,"word":"illustrate","pronunciation":"/ˈɪləstreɪt/","meaning":"v.(用示例、图画等)说明,解释","seq":68,"isStar":false,"memo":"联想 ill(有病的)+us(我们)+trate(音同 trait,特征)→他向我们举例“说明”有这种病的人的特征。","example":"Let me give an example to illustrate the point. 让我举个例子来说明这一点。"},{"id":756,"unit":3,"lesson":3,"word":"illustration","pronunciation":"/ˌɪləˈstreɪʃ(ə)n/","meaning":"n.图解;插图;示例","seq":69,"isStar":false},{"id":757,"unit":3,"lesson":3,"word":"illustrative","pronunciation":"/ˈɪləstrətɪv/","meaning":"adj.说明的;解释性的","seq":70,"isStar":false},{"id":758,"unit":3,"lesson":3,"word":"deduce","pronunciation":"/dɪˈdjuːs/","meaning":"v.推论,推断,演绎","seq":71,"isStar":false,"memo":"联想 de(音似“弟”)+du(联想“读”)+ce(音似“思”)→弟弟边读书边思考,最终“推断”出了问题的答案。","example":"We can deduce a lot from what people choose to buy. 从人们选购的东西中我们可以推断出很多信息。"},{"id":759,"unit":3,"lesson":3,"word":"deducible","pronunciation":"/dɪˈdjuːsəbl/","meaning":"adj.可推论的","seq":72,"isStar":false},{"id":760,"unit":3,"lesson":3,"word":"introduce","pronunciation":"/ˌɪntrəˈdjuːs/","meaning":"v.介绍;采用;引进","seq":73,"isStar":false,"memo":"构词 intro-(向内,进入)+duce(引导)→引导进入→介绍","example":"Before considering this question, it will be useful to introduce some related concepts. 在考虑这个问题之前,先介绍一些相关的概念是有益的。"},{"id":761,"unit":3,"lesson":3,"word":"introduction","pronunciation":"/ˌɪntrəˈdʌkʃn/","meaning":"n.介绍;采用;引进","seq":74,"isStar":false},{"id":762,"unit":3,"lesson":3,"word":"deduct","pronunciation":"/dɪˈdʌkt/","meaning":"v.扣除,减去","seq":75,"isStar":false,"memo":"联想 de-(往下)+duct(音似“打个它”)→往下打个它(价格)→扣除,减去","example":"What we paid in advance last month should be deducted from the bill.我们上个月预付的钱应该从账单中扣除。"},{"id":763,"unit":3,"lesson":3,"word":"deduction","pronunciation":"/dɪˈdʌkʃn/","meaning":"n.演绎;推论,推理;扣除","seq":76,"isStar":false},{"id":764,"unit":3,"lesson":3,"word":"deductive","pronunciation":"/dɪˈdʌktɪv/","meaning":"adj.演绎的;推论的,推理的","seq":77,"isStar":false},{"id":765,"unit":3,"lesson":3,"word":"deductible","pronunciation":"/dɪˈdʌktəbl/","meaning":"adj.可扣除的,可减免的 n.免赔额","seq":78,"isStar":false},{"id":766,"unit":3,"lesson":3,"word":"conduct","pronunciation":"/kənˈdʌkt/","meaning":"v.组织;实施;引导;举止","seq":79,"isStar":false,"memo":"联想 con-(所有) + duct(音似“打个他”) → 所有人都打他，这种“行为”是不对的，要加以“引导”。","example":"The sport has a strict code of conduct. 这种体育运动有严格的行为规范。"},{"id":767,"unit":3,"lesson":3,"word":"conductor","pronunciation":"/kənˈdʌktə(r)/","meaning":"n.(管弦乐队、合唱队等的)指挥;列车长","seq":80,"isStar":false},{"id":768,"unit":3,"lesson":3,"word":"conducive","pronunciation":"/kənˈdjuːsɪv/","meaning":"adj.有助于……,有益于……","seq":81,"isStar":false,"memo":"con-（共同）+ duce（引导，词根duc=lead）+ -ive → 共同引向好结果！比如安静自习室就conducive to focus～","example":"A calm environment is conducive to deep thinking. 宁静的环境有助于深度思考。"},{"id":769,"unit":3,"lesson":3,"word":"induce","pronunciation":"/ɪnˈdjuːs/","meaning":"v.劝诱,诱使;引起","seq":82,"isStar":false,"memo":"联想 in(里面) + du(联想“毒”) + ce(音似“死”) → 潘金莲被王婆“劝诱”，在家里毒死武大郎。","example":"People may be induced to eat more than is necessary. 人们可能会被诱导吃得比需要的多。"},{"id":770,"unit":3,"lesson":3,"word":"inducement","pronunciation":"/ɪnˈdjuːsmənt/","meaning":"n.引诱;刺激;诱因","seq":83,"isStar":false},{"id":771,"unit":3,"lesson":3,"word":"seduce","pronunciation":"/sɪˈdjuːs/","meaning":"v.引诱,诱惑;诱奸;勾引","seq":84,"isStar":false,"memo":"构词 se-(分开)+duce(引导)→引诱","example":"I was young and seduced by New York.我当时很年轻，被纽约迷住了。"},{"id":772,"unit":3,"lesson":3,"word":"seduction","pronunciation":"/sɪˈdʌkʃn/","meaning":"n.诱奸;诱惑力,吸引力","seq":85,"isStar":false},{"id":773,"unit":3,"lesson":3,"word":"seductive","pronunciation":"/sɪˈdʌktɪv/","meaning":"adj.诱人的,迷人的,有魅力的","seq":86,"isStar":false},{"id":774,"unit":3,"lesson":3,"word":"lure","pronunciation":"/lʊə(r)/","meaning":"v.引诱,诱惑;吸引","seq":87,"isStar":false,"memo":"谐音 单词发音类似“路饵”→路上的诱饵“引诱”了贪吃的老鼠。","example":"Young people are lured to the city by the prospect of a job and money. 年轻人希望打工赚钱，从而被吸引到城市。"},{"id":775,"unit":3,"lesson":3,"word":"tempt","pronunciation":"/tempt/","meaning":"v.引诱,诱惑;怂恿;利诱","seq":88,"isStar":false,"memo":"谐音 单词发音类似“甜蜜扑他”→甜蜜的回忆扑向他，企图“引诱”他安于现状。","example":"People are unlikely to be tempted by such offers. 人们不太可能被这样的提议所诱惑。"},{"id":776,"unit":3,"lesson":3,"word":"attempt","pronunciation":"/əˈtempt/","meaning":"n.&v.企图,试图,尝试","seq":89,"isStar":false,"memo":"构词 at-(=to) + tempt(试探) → 企图，试图，尝试","example":"The problem with such a view is that some people actually attempt to live by it. 这种观点的问题是，有些人实际上试图按这种观点去生活。"},{"id":777,"unit":3,"lesson":3,"word":"temptation","pronunciation":"/tempˈteɪʃ(ə)n/","meaning":"n.引诱,诱惑","seq":90,"isStar":false,"memo":"构词 tempt(诱惑) + -ation(名词后缀) → 引诱，诱惑","example":"He can’t resist the temptation of TV either. 他也抵挡不住电视的诱惑。"},{"id":778,"unit":3,"lesson":4,"word":"inject","pronunciation":"/ɪnˈdʒekt/","meaning":"v.(给……)注射(药物等)","seq":1,"isStar":false,"memo":"构词 in(里面)+ject(扔,投掷)→向里面扔→注射;投入","example":"The doctors injected the newly approved drug into the patient when he was critically ill. 医生在病人病情危重时给他注射了新获批的药物。"},{"id":779,"unit":3,"lesson":4,"word":"injection","pronunciation":"/ɪnˈdʒekʃ(ə)n/","meaning":"n.注射;(液体)注入","seq":2,"isStar":false},{"id":780,"unit":3,"lesson":4,"word":"project","pronunciation":"/ˈprɒdʒekt; prəˈdʒekt/","meaning":"n.项目;方案;工程;计划 v.预计","seq":3,"isStar":false,"memo":"构词 pro-(前面)+ject(扔,投掷)→投掷到前面→方案;计划","example":"There are several projects underway to commercialise space travel. 目前有几个将太空旅行商业化的项目正在进行中。"},{"id":781,"unit":3,"lesson":4,"word":"reject","pronunciation":"/rɪˈdʒekt/","meaning":"v.拒绝;不录用;不予考虑","seq":4,"isStar":false,"memo":"构词 re-(回)+ject(扔,投掷)→往回扔→拒绝接受;拒收","example":"Freedom of contract is possible only if both parties are free to accept and reject it. 合同自由只有在双方都能自由接受和拒绝的情况下才有可能实现。"},{"id":782,"unit":3,"lesson":4,"word":"rejection","pronunciation":"/rɪˈdʒekʃ(ə)n/","meaning":"n.拒绝;不录用","seq":5,"isStar":false},{"id":783,"unit":3,"lesson":4,"word":"refusal","pronunciation":"/rɪˈfjuːz(ə)l/","meaning":"n.拒绝,回绝","seq":6,"isStar":false,"memo":"对照 refuse v.拒绝,回绝→refusal n.","example":"Her answer amounted to a complete refusal. 她的答复等于完全拒绝。"},{"id":784,"unit":3,"lesson":4,"word":"refuse","pronunciation":"/rɪˈfjuːz/","meaning":"n.废弃物,垃圾 v.拒绝,回绝","seq":7,"isStar":false},{"id":785,"unit":3,"lesson":4,"word":"object","pronunciation":"/ˈɒbdʒɪkt; ˈɒbdʒekt; əbˈdʒekt/","meaning":"n.物品,东西;对象;宾语 v.反对","seq":8,"isStar":false,"memo":"联想 ob-(表示方向)+ject(扔,投掷)→人们将“东西”扔向了自己“反对”的人。","example":"He objected to her proposal. 他反对她的提议。"},{"id":786,"unit":3,"lesson":4,"word":"objective","pronunciation":"/əbˈdʒektɪv/","meaning":"n.目标,目的 adj.客观的","seq":9,"isStar":false},{"id":787,"unit":3,"lesson":4,"word":"stuff","pronunciation":"/stʌf/","meaning":"n.东西,物品;事情 v.填满;给……塞","seq":10,"isStar":false,"memo":"谐音 “士大夫”：士大夫家里杂物、物品最多→东西，物品；填满，塞","example":"Some animals shed tears to get rid of irritating stuff in their eyes. 一些动物会通过流泪来清除眼中的刺激物。"},{"id":788,"unit":3,"lesson":4,"word":"stuffy","pronunciation":"/ˈstʌfi/","meaning":"adj.闷热的;一本正经的,古板的","seq":11,"isStar":false},{"id":789,"unit":3,"lesson":4,"word":"stuffing","pronunciation":"/ˈstʌfɪŋ/","meaning":"n.填料;填充物","seq":12,"isStar":false},{"id":790,"unit":3,"lesson":4,"word":"staff","pronunciation":"/stɑːf/","meaning":"n.全体职员;拐杖","seq":13,"isStar":false,"memo":"构词 sub-(往下)+ject(扔,投掷)→扔到下面去→使顺从;易遭受……的","example":"The unusual history of these people has subjected them to unique evolutionary pressures.这些人不寻常的历史使他们承受了独特的进化压力。"},{"id":791,"unit":3,"lesson":4,"word":"personnel","pronunciation":"/ˌpɜːsəˈnel/","meaning":"n.(组织或军队中的)人员,职员;人事部","seq":14,"isStar":false,"memo":"构词 person(人,个体)+-(n)el(名词后缀)→与人有关的事物或团队→人员,职员;人事部","example":"Only authorised personnel have access to the computer system.只有经授权的人员才能使用这台计算机系统。"},{"id":792,"unit":3,"lesson":4,"word":"subject","pronunciation":"/ˈsʌbdʒɪkt/","meaning":"v.使顺从 n.主题","seq":15,"isStar":false,"memo":"【构词】sub-(往下)+ject(扔,投掷)→扔到下面去→使顺从;易遭受……的","example":"The unusual history of these people has subjected them to unique evolutionary pressures. 这些人不同寻常的经历使他们承受着独特的进化压力。"},{"id":793,"unit":3,"lesson":4,"word":"subjective","pronunciation":"/səbˈdʒektɪv/","meaning":"adj.主观的;主语的","seq":16,"isStar":false,"memo":"【构词】sub-（在下）+ ject（投掷）+ -ive →想法‘被投射到你心里’，只属于你自己的视角！比如你嫌食堂菜咸，纯主观～","example":"Art criticism is often highly subjective and varies from person to person. 艺术批评往往高度主观，因人而异。"},{"id":794,"unit":3,"lesson":4,"word":"eject","pronunciation":"/ɪˈdʒekt/","meaning":"v.驱逐,逐出;喷射,射出","seq":17,"isStar":false,"memo":"【构词】e-(出)+ject(扔,投掷)→扔出去→驱逐;射出","example":"He was ejected from a restaurant. 他被逐出餐厅。"},{"id":795,"unit":3,"lesson":4,"word":"ejection","pronunciation":"/ɪˈdʒekʃ(ə)n/","meaning":"n.驱逐;喷射","seq":18,"isStar":false},{"id":796,"unit":3,"lesson":4,"word":"visual","pronunciation":"/ˈvɪʒuəl/","meaning":"adj.视力的,视觉的 n.视觉资料","seq":19,"isStar":false,"memo":"【构词】vis(看)+-(u)al(形容词后缀)→视力的,视觉的","example":"He used striking visuals to get his point across. 他用醒目的视觉资料解释他的观点。"},{"id":797,"unit":3,"lesson":4,"word":"devise","pronunciation":"/dɪˈvaɪz/","meaning":"v.设计,发明,想出","seq":20,"isStar":false,"memo":"【联想】de-(往下)+vis(e)(看)→他只要低下头眼睛转一圈,就能“想出”一个点子。","example":"It was at that moment that I devised an idea to run away. 就在那一刻,我想出了一个逃跑的主意。"},{"id":798,"unit":3,"lesson":4,"word":"device","pronunciation":"/dɪˈvaɪs/","meaning":"n.装置,仪器;手段","seq":21,"isStar":false,"memo":"【联想】de(音似“弟”)+vi(形似罗马数字6)+ce(联想“车”)→弟弟用六辆车拉“仪器”。","example":"Sending advertising by email is very successful as a marketing device. 通过电子邮件发送广告是非常成功的营销手段。"},{"id":799,"unit":3,"lesson":4,"word":"revise","pronunciation":"/rɪˈvaɪz/","meaning":"v.改变,修改;复习;修订(文稿)","seq":22,"isStar":false,"memo":"构词 re-(再)+vis(看，同 vision 视觉)+-e→再看一遍→修改；复习","example":"The country would need to revise its current economic policy. 该国需要修改其目前的经济政策。"},{"id":800,"unit":3,"lesson":4,"word":"revision","pronunciation":"/rɪˈvɪʒ(ə)n/","meaning":"n.修改;修订;复习","seq":23,"isStar":false},{"id":801,"unit":3,"lesson":4,"word":"visualise/-ize","pronunciation":"/ˈvɪʒʊəˌlaɪz; -zjʊ-/","meaning":"v.想象,构思,设想","seq":24,"isStar":false,"memo":"构词 vis(看，同 vision)+-ual+-ise/-ize(使…化)→使在脑子里看得见→想象，构思，设想","example":"Try to visualise the scene before you write. 动笔之前先试着在脑中构想这个场景。"},{"id":802,"unit":3,"lesson":4,"word":"envisage","pronunciation":"/ɪnˈvɪzɪdʒ/","meaning":"v.设想,展望","seq":25,"isStar":false,"memo":"[构词] en-(进入) + vis(看) + -age(后缀)→使进入看的状态→设想","example":"What level of profit do you envisage? 你预计会有什么样的利润水平?"},{"id":803,"unit":3,"lesson":4,"word":"vision","pronunciation":"/ˈvɪʒ(ə)n/","meaning":"n.视力;视野;想象,幻想;(电视)图像","seq":26,"isStar":false,"memo":"[构词] vis(看) + -ion(名词后缀)→视力;幻想","example":"He had a vision of a world in which there would be no wars. 他幻想一个没有战争的世界。"},{"id":804,"unit":3,"lesson":4,"word":"visionary","pronunciation":"/ˈvɪʒənri/","meaning":"adj.有眼力的","seq":27,"isStar":false},{"id":805,"unit":3,"lesson":4,"word":"visible","pronunciation":"/ˈvɪzəb(ə)l/","meaning":"adj.看得见的,可见的;明显的","seq":28,"isStar":false,"memo":"[构词] vis(看) + -ible(可以……的)→看得见的,可见的","example":"There is no visible evidence to support his idea. 没有明显的证据支持他的观点。"},{"id":806,"unit":3,"lesson":4,"word":"visibility","pronunciation":"/ˌvɪzəˈbɪləti/","meaning":"n.可见度,能见度;可见性;明显性","seq":29,"isStar":false},{"id":807,"unit":3,"lesson":4,"word":"invisible","pronunciation":"/ɪnˈvɪzəb(ə)l/","meaning":"adj.看不见的;无形的","seq":30,"isStar":false,"memo":"构词：in-（不）+ vis-（看）+ -ible（能…的）→ 看不见的！哈利·波特披上斗篷秒变'in-see-bull'。","example":"Microplastics in drinking water are invisible but pose serious health risks. 饮用水中的微塑料肉眼不可见，却带来严重健康风险。"},{"id":808,"unit":3,"lesson":4,"word":"interview","pronunciation":"/ˈɪntəvjuː/","meaning":"n.&v.面试;采访;会见","seq":31,"isStar":false,"memo":"[构词] inter-(相互) + view(看)→相互看→面试;采访","example":"I've got another job interview tomorrow. 我明天还有一个求职面试。"},{"id":809,"unit":3,"lesson":4,"word":"interviewer","pronunciation":"/ˈɪntəvjuːə(r)/","meaning":"n.主持面试者;采访者","seq":32,"isStar":false},{"id":810,"unit":3,"lesson":4,"word":"interviewee","pronunciation":"/ˌɪntəvjuːˈiː/","meaning":"n.参加面试者;被采访者","seq":33,"isStar":false},{"id":811,"unit":3,"lesson":4,"word":"preview","pronunciation":"/ˈpriːvjuː/","meaning":"v.预演;预展;写评介 n.预映;预展","seq":34,"isStar":false,"memo":"记 (构词) pre-(提前)+view(看)→预演;预展","example":"The exhibition was previewed in last week's issue.上周的一期杂志对这次展览做了预览。"},{"id":812,"unit":3,"lesson":4,"word":"interfere","pronunciation":"/ˌɪntəˈfɪə(r)/","meaning":"v.干涉,干预","seq":35,"isStar":false,"memo":"联想 inter-(在……中间) + fere(音似“飞”)→他学习时，有只苍蝇在中间来来回回地飞，它在“干预”他的学习。","example":"I try not to let work interfere with my personal life. 我尽量不让工作干扰我的私生活。"},{"id":813,"unit":3,"lesson":4,"word":"interference","pronunciation":"/ˌɪntəˈfɪərəns/","meaning":"n.干涉,干预,介入","seq":36,"isStar":false},{"id":814,"unit":3,"lesson":4,"word":"intervene","pronunciation":"/ˌɪntəˈviːn/","meaning":"v.干预,介入;打扰,插话;阻碍","seq":37,"isStar":false,"memo":"构词 inter-(在……中间) + ven(e)(= to come)→来到两者之间→干预，介入","example":"The government intervened effectively. 政府进行了有效的干预。"},{"id":815,"unit":3,"lesson":4,"word":"intervention","pronunciation":"/ˌɪntəˈvenʃ(ə)n/","meaning":"n.出面;干预;打断(别人的话)","seq":38,"isStar":false},{"id":816,"unit":3,"lesson":4,"word":"interact","pronunciation":"/ˌɪntərˈækt/","meaning":"v.交流;交往;相互影响;相互作用","seq":39,"isStar":false,"memo":"构词 inter-(相互) + act(行动)→相互地行动→交流；相互影响","example":"Perfume interacts with the skin's natural chemicals. 香水和皮肤的天然化学物质相互作用。"},{"id":817,"unit":3,"lesson":4,"word":"interactive","pronunciation":"/ˌɪntərˈæktɪv/","meaning":"adj.交互的,合作的;相互影响的","seq":40,"isStar":false},{"id":818,"unit":3,"lesson":4,"word":"interaction","pronunciation":"/ˌɪntərˈækʃ(ə)n/","meaning":"n.相互作用;交流;互动","seq":41,"isStar":false,"memo":"inter-（互相）+ act（行动）+ -ion → 大家一起动起来！像宿舍里抢WiFi时你戳我、我戳你，纯纯的‘互动’现场。","example":"Online learning requires frequent student-teacher interaction. 在线学习需要师生频繁互动。"},{"id":819,"unit":3,"lesson":4,"word":"supervise","pronunciation":"/ˈsuːpəvaɪz/","meaning":"v.监管;管理;指导","seq":42,"isStar":false,"memo":"构词 super-(在……上) + vise(看)→在上面看→监督","example":"She supervises a number of important projects. 她管理着许多重要的项目。"},{"id":820,"unit":3,"lesson":4,"word":"supervision","pronunciation":"/ˌsuːpəˈvɪʒ(ə)n/","meaning":"n.监管;管理;指导","seq":43,"isStar":false},{"id":821,"unit":3,"lesson":4,"word":"supervisor","pronunciation":"/ˈsuːpəvaɪzə(r)/","meaning":"n.监管人;指导者;主管","seq":44,"isStar":false,"memo":"构词 supervis(e)(监督) + -or(表示人的后缀)→监督人","example":"All work is done under the guidance of a supervisor.所有工作都在导师的指导下进行。"},{"id":822,"unit":3,"lesson":4,"word":"monitor","pronunciation":"/ˈmɒnɪtə(r)/","meaning":"n.班长,监督员;显示器","seq":45,"isStar":false,"memo":"构词 monit(警告) + -or(后缀)→班长；监督员；监视器","example":"The government is monitoring the situation closely. 政府正密切关注着局势。"},{"id":823,"unit":3,"lesson":4,"word":"superior","pronunciation":"/suːˈpɪəriə(r)/","meaning":"adj.更好的;更强的","seq":46,"isStar":false,"memo":"联想 super(在……上面) + i(我) + -or(后缀)→职级在我上面的人→上级，上司","example":"You should let your superiors know how good you are. 你应该让你的上级知道你有多优秀。"},{"id":824,"unit":3,"lesson":4,"word":"superiority","pronunciation":"/suːˌpɪəriˈɒrəti/","meaning":"n.优越;优势;优越感","seq":47,"isStar":false},{"id":825,"unit":3,"lesson":4,"word":"inferior","pronunciation":"/ɪnˈfɪəriə(r)/","meaning":"adj.级别低的,下级的;较差的","seq":48,"isStar":false,"memo":"联想 in(里面) + fer(音似“废”) + i(我) + -or(后缀)→他一个人每天在家里荒废日子，沦为了“低于他人者”。","example":"It was a gentleman's duty always to be civil, even to his inferiors. 一个绅士的责任是一直保持彬彬有礼，即使是对比自己地位低的人。"},{"id":826,"unit":3,"lesson":4,"word":"inferiority","pronunciation":"/ɪnˌfɪəriˈɒrəti/","meaning":"n.低等,劣等;劣势","seq":49,"isStar":false,"memo":"构词 infer(低，同 inferior 较低的)+-ior+-ity(名词后缀)→处在低位的状态→低等，劣势","example":"He suffers from a sense of inferiority. 他有一种自卑感。"},{"id":827,"unit":3,"lesson":4,"word":"superb","pronunciation":"/suːˈpɜːb/","meaning":"adj.极佳的,卓越的,出色的","seq":50,"isStar":false,"memo":"super（超越）+ b（联想“不”）→ 不能再超越的 → 极佳的","example":"His artistic taste is superb. 他的艺术品位极佳。"},{"id":828,"unit":3,"lesson":4,"word":"supreme","pronunciation":"/suːˈpriːm; sjuːˈpriːm/","meaning":"adj.(权力、重要性或影响力)最高的","seq":51,"isStar":false,"memo":"supre（联想 super，超越）+ me（我）→ 超越自我 → 最高的","example":"It required a supreme effort to stay awake. 要保持清醒需要极大的努力。"},{"id":829,"unit":3,"lesson":4,"word":"supremacy","pronunciation":"/suːˈpreməsi; sjuːˈpreməsi/","meaning":"n.至高无上;最大权力;最高地位","seq":52,"isStar":false},{"id":830,"unit":3,"lesson":4,"word":"superstition","pronunciation":"/ˌsuːpəˈstɪʃ(ə)n/","meaning":"n.迷信","seq":53,"isStar":false,"memo":"super（在……上）+ stit（站）+ -ion（名词后缀）→ 站在我们理性之上的观念 → 迷信","example":"It's all superstition, and there's nothing to it. 这都是迷信，不是真的。"},{"id":831,"unit":3,"lesson":4,"word":"superstitious","pronunciation":"/ˌsuːpəˈstɪʃəs/","meaning":"adj.迷信的","seq":54,"isStar":false},{"id":832,"unit":3,"lesson":4,"word":"religion","pronunciation":"/rɪˈlɪdʒən/","meaning":"n.宗教,宗教信仰","seq":55,"isStar":false,"memo":"re（字母音似“阿姨”）+ ligion（音似“历尽”）→ 阿姨历尽沧桑之后，开始研究“宗教”。","example":"Religion informs every aspect of their lives. 宗教影响着他们生活的各个方面。"},{"id":833,"unit":3,"lesson":4,"word":"religious","pronunciation":"/rɪˈlɪdʒəs/","meaning":"adj.宗教的;虔诚的","seq":56,"isStar":false},{"id":834,"unit":4,"lesson":1,"word":"scholar","pronunciation":"/ˈskɒlə(r)/","meaning":"n.学者;奖学金获得者","seq":1,"isStar":false,"memo":"单词发音类似“死靠了”→他要想有出路,就得靠努力学习知识,成为“学者”。","example":"These scholars are worried about education today. 这些学者们对当今的教育感到担忧。"},{"id":835,"unit":4,"lesson":1,"word":"scholarly","pronunciation":"/ˈskɒləli/","meaning":"adj.学术性的;有学问的","seq":2,"isStar":false},{"id":836,"unit":4,"lesson":1,"word":"scholarship","pronunciation":"/ˈskɒləʃɪp/","meaning":"n.奖学金;学问;学术研究","seq":3,"isStar":false},{"id":837,"unit":4,"lesson":1,"word":"scholastic","pronunciation":"/skəˈlæstɪk/","meaning":"adj.学校的;教育的;学业的","seq":4,"isStar":false},{"id":838,"unit":4,"lesson":1,"word":"expert","pronunciation":"/ˈekspɜːt/","meaning":"n.专家,行家 adj.专家的,内行的","seq":5,"isStar":false,"memo":"ex-(往外)+pert(音似“破它”)→往外突破它→专家","example":"I don't pretend to be an expert on the subject. 我不想要称自己是该学科的专家。"},{"id":839,"unit":4,"lesson":1,"word":"expertise","pronunciation":"/ˌekspɜːˈtiːz/","meaning":"n.专门知识,专门技能;专长","seq":6,"isStar":false,"memo":"expert(专家)+-ise(名词后缀)→专门知识,专门技能","example":"What he brought to the company is financial expertise. 他给公司带来的是金融专业知识。"},{"id":840,"unit":4,"lesson":1,"word":"mentor","pronunciation":"/ˈmentɔː(r)/","meaning":"n.导师;顾问","seq":7,"isStar":false,"memo":"ment(联想 mental)+-or(表示人的后缀)→在思想上指导我们的人是那个“导师”。","example":"Talented executives need mentors to help them climb the ladder. 有才华的高管需要导师帮助他们攀登职业阶梯。"},{"id":841,"unit":4,"lesson":1,"word":"tutor","pronunciation":"/ˈtjuːtə(r)/","meaning":"n.导师;家庭教师 v.辅导","seq":8,"isStar":false,"memo":"tu(联想“土”)+tor(音似“特”)→毕业后,我们有时会带着土特产去看望“导师”。","example":"He can serve as the woman's tutor. 他可以担当这位女士的家庭教师。"},{"id":842,"unit":4,"lesson":1,"word":"tutorial","pronunciation":"/tjuːˈtɔːriəl/","meaning":"n.个别辅导时间,辅导课 adj.导师的","seq":9,"isStar":false},{"id":843,"unit":4,"lesson":1,"word":"professor","pronunciation":"/prəˈfesə(r)/","meaning":"n.教授;(大学的)讲师,教员","seq":10,"isStar":false,"memo":"对照 教授(professor)就是在某个行业(profession)特别专业的人。","example":"He was made a professor at the age of 40. 他40岁时就成了教授。"},{"id":844,"unit":4,"lesson":1,"word":"profession","pronunciation":"/prəˈfeʃn/","meaning":"n.职业;行业;表白","seq":11,"isStar":false,"memo":"记 (对照) 教授(professor)就是在某个行业(profession)特别专业的人。","example":"All nurses are aware of that before they enter the profession.所有护士在进入这个职业之前都明白这一点。"},{"id":845,"unit":4,"lesson":1,"word":"professional","pronunciation":"/prəˈfeʃən(ə)l/","meaning":"adj.专业的;职业的 n.专业人员","seq":12,"isStar":false},{"id":846,"unit":4,"lesson":1,"word":"faculty","pronunciation":"/ˈfæk(ə)lti/","meaning":"n.(高等院校的)系,院;全体教师;天赋","seq":13,"isStar":false,"memo":"联想 fa(联想“发”)+cu(联想“醋”)+l(联想“了”)+ty(名词后缀)→学“院”给“全体教师”发了一箱醋。","example":"They will bring with them more international faculty. 他们将带来更多国际化的师资。"},{"id":847,"unit":4,"lesson":1,"word":"colleague","pronunciation":"/ˈkɒliːɡ/","meaning":"n.同事;同僚","seq":14,"isStar":false,"memo":"对照 他们是在同一所大学(college)里工作的同事(colleague)。","example":"Tom is disliked by his colleagues. 汤姆的同事们不喜欢他。"},{"id":848,"unit":4,"lesson":1,"word":"occupy","pronunciation":"/ˈɒkjupaɪ/","meaning":"v.使用,占用;忙着(做某事)","seq":15,"isStar":false,"memo":"构词 oc-(加强)+cup(拿，同 capture 抓住)+-y→把地方拿到手里→占用；忙着(做某事)","example":"Nowadays, games occupy his time. 如今,游戏占据了他的时间。"},{"id":849,"unit":4,"lesson":1,"word":"occupancy","pronunciation":"/ˈɒkjəpənsi/","meaning":"n.占用,使用,居住","seq":16,"isStar":false},{"id":850,"unit":4,"lesson":1,"word":"occupant","pronunciation":"/ˈɒkjəpənt/","meaning":"n.使用者,居住者;乘坐者","seq":17,"isStar":false},{"id":851,"unit":4,"lesson":1,"word":"occupation","pronunciation":"/ˌɒkjuˈpeɪʃ(ə)n/","meaning":"n.职业,工作","seq":18,"isStar":false,"memo":"构词 oc-(加强)+cup(拿)+-ation(名词后缀)→占用你时间的事→职业，工作","example":"Please state your name, age and occupation below. 请在下面写明姓名、年龄和职业。"},{"id":852,"unit":4,"lesson":1,"word":"occupational","pronunciation":"/ˌɒkjuˈpeɪʃən(ə)l/","meaning":"adj.职业的","seq":19,"isStar":false},{"id":853,"unit":4,"lesson":1,"word":"preoccupy","pronunciation":"/priˈɒkjupaɪ/","meaning":"v.使全神贯注;使日夜思考;使忧心忡忡","seq":20,"isStar":false,"memo":"记 (构词) pre-(预先)+occupy(占据)→预先占据注意力→使全神贯注;使忧心忡忡","example":"Thoughts of failure preoccupied him.失败的念头占据了他的脑海。"},{"id":854,"unit":4,"lesson":1,"word":"confession","pronunciation":"/kənˈfeʃ(ə)n/","meaning":"n.供认,坦白;承认","seq":21,"isStar":false,"memo":"记 (构词) con-(都)+fess(说)+-ion(名词后缀)→供认,坦白;承认","example":"I have a confession.我要坦白一件事。"},{"id":855,"unit":4,"lesson":1,"word":"confess","pronunciation":"/kənˈfes/","meaning":"v.供认;承认(错误或罪行);忏悔","seq":22,"isStar":false},{"id":856,"unit":4,"lesson":1,"word":"seminar","pronunciation":"/ˈsemɪnɑː(r)/","meaning":"n.(大学教师带领学生作专题讨论的)研讨","seq":23,"isStar":false,"memo":"谐音 单词发音类似“私密呢”→他们正在“研讨会”上讨论一些私密的问题呢。","example":"He thinks the seminar won't be open to the public. 他认为研讨会不会向公众开放。"},{"id":857,"unit":4,"lesson":1,"word":"workshop","pronunciation":"/ˈwɜːkʃɒp/","meaning":"n.研讨会;讲习班;车间,工场,作坊","seq":24,"isStar":false,"memo":"构词 work(工作)+shop(工坊)→车间,工场","example":"The special workshop was presided over by a famous scientist. 那次专题研讨会是由一位著名的科学家主持的。"},{"id":858,"unit":4,"lesson":1,"word":"forum","pronunciation":"/ˈfɔːrəm/","meaning":"n.论坛,讨论会","seq":25,"isStar":false,"memo":"联想 fo(联想for)+rum(音似room)→他为了找个合适的房间备考,去学校“论坛”上浏览合租信息。","example":"The government should not brush aside ideas from the World Economic Forum. 政府不应无视世界经济论坛的观点。"},{"id":859,"unit":4,"lesson":1,"word":"academic","pronunciation":"/ˌækəˈdemɪk/","meaning":"n.大学教师 adj.学术的,学业的","seq":26,"isStar":false,"memo":"谐音 单词发音类似“挨个点名”→有的“大学教师”一上课先挨个点名。","example":"Maintaining high academic standards is the priority of the university. 维持高学术标准是该大学首先考虑的事情。"},{"id":860,"unit":4,"lesson":1,"word":"academician","pronunciation":"/əˌkædəˈmɪʃn/","meaning":"n.院士;学会会员","seq":27,"isStar":false},{"id":861,"unit":4,"lesson":1,"word":"academy","pronunciation":"/əˈkædəmi/","meaning":"n.专科院校","seq":28,"isStar":false,"memo":"联想 a(一)+cade(音似“开导”)+my(我的)→一个开导我的地方→研究院;学会","example":"She trained at the Royal Academy of Music. 她在皇家音乐学院培训过。"},{"id":862,"unit":4,"lesson":1,"word":"epidemic","pronunciation":"/ˌepɪˈdemɪk/","meaning":"n.传染病;(坏事)泛滥","seq":29,"isStar":false,"memo":"联想 epi(音似“爱陪”)+demic(联想 academic)→很多学生爱陪同学搞学术研究,这是很“流行的”。","example":"That kind of epidemic disease has long been stamped out. 那种传染病早已根除。"},{"id":863,"unit":4,"lesson":1,"word":"vaccine","pronunciation":"/ˈvæksiːn/","meaning":"n.疫苗","seq":30,"isStar":false,"memo":"谐音 单词发音类似“完可神”→打完“疫苗”就能预防疾病,可神了。","example":"The search for a new vaccine will take priority over all other medical research. 研制新的疫苗将排在其他一切医学研究之前。"},{"id":864,"unit":4,"lesson":1,"word":"vaccinate","pronunciation":"/ˈvæksɪneɪt/","meaning":"v.给……接种疫苗","seq":31,"isStar":false},{"id":865,"unit":4,"lesson":1,"word":"vaccination","pronunciation":"/ˌvæksɪˈneɪʃ(ə)n/","meaning":"n.疫苗接种","seq":32,"isStar":false},{"id":866,"unit":4,"lesson":1,"word":"immune","pronunciation":"/ɪˈmjuːn/","meaning":"adj.有免疫力的;不受影响的;豁免的","seq":33,"isStar":false,"memo":"联想 i(我)+mmune(联想“木讷”)→我比较木讷,不易受外界影响→不受影响的","example":"You'll eventually become immune to criticism. 你终有一日会不再在意批评。"},{"id":867,"unit":4,"lesson":1,"word":"immunity","pronunciation":"/ɪˈmjuːnəti/","meaning":"n.免疫力","seq":34,"isStar":false},{"id":868,"unit":4,"lesson":1,"word":"immunise/-ize","pronunciation":"/ˈɪmjuːnaɪz/","meaning":"v.(尤指通过注射疫苗)使免疫","seq":35,"isStar":false,"memo":"构词 immun(免疫，同 immune 免疫的)+-ise/-ize(使…化)→使身体有免疫力→使免疫","example":"All children should be immunised against measles. 所有儿童都应接种麻疹疫苗。"},{"id":869,"unit":4,"lesson":1,"word":"insulate","pronunciation":"/ˈɪnsjuleɪt/","meaning":"v.使隔热;使隔音;使绝缘","seq":36,"isStar":false,"memo":"构词：in-（使进入）+ sula（=sulcus沟槽，引申为‘隔开’）+ -ate→往缝隙里填料‘使绝缘/隔音’，像给墙打‘胶’！","example":"New buildings must insulate walls to reduce energy consumption. 新建筑必须对墙体进行隔热处理以降低能耗。"},{"id":870,"unit":4,"lesson":1,"word":"insulation","pronunciation":"/ˌɪnsjuˈleɪʃ(ə)n/","meaning":"n.隔绝;绝缘材料","seq":37,"isStar":false},{"id":871,"unit":4,"lesson":1,"word":"insulator","pronunciation":"/ˈɪnsjuleɪtə(r)/","meaning":"n.隔热(或绝缘、隔音等)的材料","seq":38,"isStar":false,"memo":"构词 insula(岛，同 isolate 使隔离)+-tor(表物)→把电流“孤立”起来的东西→绝缘(隔热、隔音)材料","example":"Rubber is a good insulator. 橡胶是一种良好的绝缘体。"},{"id":872,"unit":4,"lesson":1,"word":"section","pronunciation":"/ˈsekʃ(ə)n/","meaning":"n.部分;部门","seq":39,"isStar":false,"memo":"构词 sect(切)+-ion(后缀)→分开的部分→部分;部门;节","example":"Business services are listed in a special section. 企业服务被列在一个特别的部分。"},{"id":873,"unit":4,"lesson":1,"word":"sector","pronunciation":"/ˈsektə(r)/","meaning":"n.(尤指商业、贸易等的)部门;行业","seq":40,"isStar":false,"memo":"谐音 单词发音类似“塞个他”→领导把他塞到自己的“部门”。","example":"She works in the voluntary sector. 她在志愿部门工作。"},{"id":874,"unit":4,"lesson":1,"word":"segment","pronunciation":"/ˈseɡmənt/","meaning":"n.部分;瓣;弓形 v.分割;划分","seq":41,"isStar":false,"memo":"构词 seg(分开)+-ment(后缀)→部分;分割","example":"It displays only small segments of books that are in copyright. 它只展示了受版权保护的书籍的一小部分内容。"},{"id":875,"unit":4,"lesson":1,"word":"segmental","pronunciation":"/seɡˈmentl/","meaning":"adj.音段的","seq":42,"isStar":false},{"id":876,"unit":4,"lesson":1,"word":"senior","pronunciation":"/ˈsiːniə(r)/","meaning":"adj.级别(或地位)高的;资深的","seq":43,"isStar":false,"memo":"谐音 单词发音类似“似泥人”→那个“毕业班学生”呆板得像泥人一样。","example":"They never lose time in upgrading products for seniors. 他们总是争分夺秒地为老年人升级产品。"},{"id":877,"unit":4,"lesson":1,"word":"seniority","pronunciation":"/ˌsiːniˈɒrəti/","meaning":"n.资历;年长;级别高","seq":44,"isStar":false,"memo":"构词 senior(年长的、资深的)+-ity(名词后缀)→资深的程度→资历；年长","example":"Promotion here is based on seniority. 这里的晋升以资历为依据。"},{"id":878,"unit":4,"lesson":1,"word":"undergraduate","pronunciation":"/ˌʌndəˈɡrædʒuət/","meaning":"n.(在读的)大学本科生","seq":45,"isStar":false,"memo":"构词 under(在……以下)+graduate(毕业)→没有毕业→(在读的)大学本科生","example":"Over a lecture course, the teacher showed undergraduates works of Impressionism. 在一次演讲中,老师向本科生展示了印象派作品。"},{"id":879,"unit":4,"lesson":1,"word":"bachelor","pronunciation":"/ˈbætʃələ(r)/","meaning":"n.未婚男子,单身汉;学士","seq":46,"isStar":false,"memo":"联想 bache(联想“爸车”)+I(形似1)+-or(表示人的后缀)→爸爸车里坐着一个人,他是个“单身汉”。","example":"Students earn their Bachelor of Science in nursing in a year. 学生们在一年内获得护理学学士学位。"},{"id":880,"unit":4,"lesson":1,"word":"master","pronunciation":"/ˈmɑːstə(r)/","meaning":"n.大师,能手;主人,雇主","seq":47,"isStar":false,"memo":"联想 与 magister(教师)同源：能教别人的那个人→大师，能手；主人；硕士；精通","example":"It was a skill that required lots of practice to master. 这是一项需要大量练习才能掌握的技能。"},{"id":881,"unit":4,"lesson":1,"word":"mastery","pronunciation":"/ˈmɑːstəri/","meaning":"n.精通;熟练掌握","seq":48,"isStar":false},{"id":882,"unit":4,"lesson":1,"word":"masterpiece","pronunciation":"/ˈmɑːstəpiːs/","meaning":"n.代表作;杰作;名著","seq":49,"isStar":false,"memo":"构词 master(大师)+piece(一件作品)→大师的一件作品→杰作","example":"They found inspiration in the greatest masterpieces. 他们从最伟大的杰作中找到了灵感。"},{"id":883,"unit":4,"lesson":1,"word":"grasp","pronunciation":"/ɡrɑːsp/","meaning":"n.紧握;理解(力) v.抓紧;理解","seq":50,"isStar":false,"memo":"联想 gras(联想 grass)+p(联想“趴”)→小宝宝趴在地上,“抓紧”一撮草使劲拔。","example":"She felt a firm grasp on her arm. 她感到手臂被紧紧地抓住。"},{"id":884,"unit":4,"lesson":1,"word":"adolescent","pronunciation":"/ˌædəˈles(ə)nt/","meaning":"n.青少年","seq":51,"isStar":false,"memo":"联想 ado(音似“爱逗”) + lescent(音似 lesson)→课后爱遛狗的是那个“青少年”。","example":"Many industries are going out of infancy and becoming adolescents. 许多行业正在走出婴儿期，步入青少年时期。"},{"id":885,"unit":4,"lesson":1,"word":"adolescence","pronunciation":"/ˌædəˈles(ə)ns/","meaning":"n.青春期;青春","seq":52,"isStar":false,"memo":"对照 adolescent n.青少年→adolescence n.","example":"It tracked their eating habits since their adolescence.它追踪了他们自青春期以来的饮食习惯。"},{"id":886,"unit":4,"lesson":1,"word":"idle","pronunciation":"/ˈaɪd(ə)l/","meaning":"v.无所事事","seq":53,"isStar":false,"memo":"谐音 单词发音类似“爱逗”→在这儿逗留的是个“空闲的”人。","example":"She was bored with her idle life at home. 她对在家里无所事事的生活感到厌倦。"},{"id":887,"unit":4,"lesson":1,"word":"idly","pronunciation":"/ˈaɪdli/","meaning":"adv.毫无目的地;漫不经心地;闲散地","seq":54,"isStar":false},{"id":888,"unit":4,"lesson":1,"word":"private","pronunciation":"/ˈpraɪvət/","meaning":"adj.私有的;秘密的,私人的","seq":55,"isStar":false,"memo":"构词 priv(个别，同 privilege 特权)+-ate(形容词后缀)→只属于个别人的→私有的；私人的，秘密的","example":"Private colleges and universities can offer smaller classes and more personal attention. 私立学院和大学能提供更小的班级和更多的个人关注。"},{"id":889,"unit":4,"lesson":1,"word":"privacy","pronunciation":"/ˈprɪvəsi/","meaning":"n.隐私;私密","seq":56,"isStar":false},{"id":890,"unit":4,"lesson":1,"word":"privatise/-ize","pronunciation":"/ˈpraɪvətaɪz/","meaning":"v.使私有化;将……私营化","seq":57,"isStar":false,"memo":"构词 privat(私有的)+-ise/-ize(使…化)→使归私人所有→使私有化，将……私营化","example":"The government plans to privatise the railway. 政府计划将铁路私有化。"},{"id":891,"unit":4,"lesson":1,"word":"privatisation/-zation","pronunciation":"/ˌpraɪvətaɪˈzeɪʃn/","meaning":"n.私有化","seq":58,"isStar":false,"memo":"构词 privat(私有的)+-isation/-ization(名词后缀)→变成私有的过程→私有化","example":"The privatisation of the port was controversial. 这个港口的私有化曾引起争议。"},{"id":892,"unit":4,"lesson":1,"word":"whisper","pronunciation":"/ˈwɪspə(r)/","meaning":"n.耳语,低语;谣言 v.耳语,低语","seq":59,"isStar":false,"memo":"联想 whi(音似 we) + sper(音似“撕破”)→“我们撕破脸了。”她在我耳边“小声说”。","example":"He whispered something in her ear. 他在她的耳边低声说了些什么。"},{"id":893,"unit":4,"lesson":1,"word":"gossip","pronunciation":"/ˈɡɒsɪp/","meaning":"n.流言蜚语;闲聊","seq":60,"isStar":false,"memo":"谐音 单词发音类似“搞事婆”→她像个搞事婆,喜欢在人背后“说闲话”。","example":"We must be willing to be the terminator of gossip. 我们必须愿意成为流言蜚语的终结者。"},{"id":894,"unit":4,"lesson":1,"word":"mutter","pronunciation":"/ˈmʌtə(r)/","meaning":"n.嘀咕;低语声 v.嘀咕;(私下)抱怨","seq":61,"isStar":false,"memo":"谐音 单词发音类似“妈特”→妈妈年龄大了,特别喜欢“嘀咕”。","example":"He just sat there muttering to himself. 他坐在那儿独自嘀嘀咕咕的。"},{"id":895,"unit":4,"lesson":1,"word":"image","pronunciation":"/ˈɪmɪdʒ/","meaning":"n.图像,影像;形象,声誉","seq":62,"isStar":false,"memo":"联想 i(我)+m(联想“妈”)+age(年龄)→我对妈妈年轻时在灯下补衣服的“形象”记忆犹新。","example":"The company is trying to improve its public image. 这家公司正努力改善公众形象。"},{"id":896,"unit":4,"lesson":1,"word":"imaging","pronunciation":"/ˈɪmɪdʒɪŋ/","meaning":"n.成像","seq":63,"isStar":false},{"id":897,"unit":4,"lesson":1,"word":"mature","pronunciation":"/məˈtʃʊə(r)/","meaning":"adj.成熟的;理智的,明白事理的","seq":64,"isStar":false,"memo":"联想 ma(联想“妈”) + ture(联想 true)→做了妈妈以后,她才真的成熟了→成熟的","example":"He has a mature and responsible attitude to work. 他对待工作的态度成熟,有责任心。"},{"id":898,"unit":4,"lesson":1,"word":"maturity","pronunciation":"/məˈtʃʊərəti/","meaning":"n.成熟(期);到期(应付款)","seq":65,"isStar":false},{"id":899,"unit":4,"lesson":1,"word":"premature","pronunciation":"/ˈpremətʃə(r)/","meaning":"adj.过早的;早产的;仓促的","seq":66,"isStar":false,"memo":"构词 pre-(在前) + mature(成熟的)→在成熟之前的→过早的;早产的","example":"Because of injury, her playing career came to a premature end. 因为受伤,她的演奏生涯过早结束了。"},{"id":900,"unit":4,"lesson":1,"word":"moral","pronunciation":"/ˈmɒrəl/","meaning":"n.道德准则(标准);寓意","seq":67,"isStar":false,"memo":"联想 m(联想“妈”) + oral(口头的)→妈妈口头上教育我们要遵守“道德准则”。","example":"The story has a clear moral. 这个故事有明确的寓意。"},{"id":901,"unit":4,"lesson":1,"word":"morality","pronunciation":"/məˈræləti/","meaning":"n.道德,道德观;道德规范","seq":68,"isStar":false,"memo":"构词 moral(道德的)+-ity(名词后缀)→道德的总和→道德，道德观；道德规范","example":"The moral is that crime doesn’t pay. 寓意就是犯罪得不偿失。"},{"id":902,"unit":4,"lesson":1,"word":"mortal","pronunciation":"/ˈmɔːt(ə)l/","meaning":"adj.凡人的;终有一死的","seq":69,"isStar":false,"memo":"谐音 单词发音类似“没头”→干活没有头脑是他“致命的”缺点。","example":"Her reputation suffered a mortal blow as a result of the scandal. 由于丑闻,她的名誉受到了致命的打击。"},{"id":903,"unit":4,"lesson":1,"word":"mortality","pronunciation":"/mɔːˈtæləti/","meaning":"n.死亡数量;死亡率","seq":70,"isStar":false},{"id":904,"unit":4,"lesson":1,"word":"campus","pronunciation":"/ˈkæmpəs/","meaning":"n.(大学、学院的)校园,校区","seq":71,"isStar":false,"memo":"联想 camp(露营) + us(我们)→我们一起在“校园”里露营。","example":"The statue stands on the campus of the university. 这座雕像矗立在这所大学的校园里。"},{"id":905,"unit":4,"lesson":1,"word":"campaign","pronunciation":"/kæmˈpeɪn/","meaning":"n.运动;战役 v.参加运动,领导运动","seq":72,"isStar":false,"memo":"谐音 单词发音类似“肯拼”→在这场“战役”中,每个战士都肯为国拼命。","example":"They began a campaign to encourage people to shop locally. 他们开展运动,鼓励人们购买本地产品。"},{"id":906,"unit":4,"lesson":2,"word":"scope","pronunciation":"/skəʊp/","meaning":"n.(活动、书籍等的)范围,领域;机会","seq":1,"isStar":false,"memo":"对照:那个美女(s)能解决(cope)这个领域(scope)的问题。","example":"This question is outside the scope of scientific research. 这个问题不在科学研究的范围之内。"},{"id":907,"unit":4,"lesson":2,"word":"terrain","pronunciation":"/təˈreɪn/","meaning":"n.地形,地势","seq":2,"isStar":false,"memo":"联想:ter(音似“特”)+rain(雨)→一场特别大的雨改变了这里的“地形”。","example":"The terrain changed quickly from arable land to desert. 这处地形很快由耕地变成了沙漠。"},{"id":908,"unit":4,"lesson":2,"word":"realm","pronunciation":"/relm/","meaning":"n.领域;王国","seq":3,"isStar":false,"memo":"对照:他认为,真正的(real)男人(man)会在某个领域(realm)做出成绩。","example":"This idea belongs in the realm of science fiction. 这是属于科幻小说领域的构思。"},{"id":909,"unit":4,"lesson":2,"word":"sphere","pronunciation":"/sfɪə(r)/","meaning":"n.球形;范围,领域","seq":4,"isStar":false,"memo":"联想:s(联想“蛇”)+p(联想“趴”)+here(这儿)→那条蛇趴在这儿,宣告这是它的势力“范围”。","example":"Its principal advantage would be the improvement of freedom in every sphere of daily life. 它的主要优点是提高日常生活各个领域的自由度。"},{"id":910,"unit":4,"lesson":2,"word":"spherical","pronunciation":"/ˈsferɪkl/","meaning":"adj.球形的;球状的","seq":5,"isStar":false,"memo":"构词 sphere(球，同 sphere 球体)+-ical(形容词后缀)→具有球体形状的→球形的，球状的","example":"The earth is not perfectly spherical. 地球并不是完美的球体。"},{"id":911,"unit":4,"lesson":2,"word":"domain","pronunciation":"/dəˈmeɪn/","meaning":"n.(知识、活动的)领域,范围;领土","seq":6,"isStar":false,"memo":"联想:do(做)+main(主要的)→我们的成绩主要是在这个“领域”内做出来的。","example":"It is important to realize that fashion covers a much wider domain. 重要的是要意识到时尚涵盖了一个更广泛的领域。"},{"id":912,"unit":4,"lesson":2,"word":"hemisphere","pronunciation":"/ˈhemɪsfɪə(r)/","meaning":"n.(地球或大脑的)半球","seq":7,"isStar":false,"memo":"构词:hemi-(半)+sphere(球)→半球","example":"In the northern hemisphere, December is a winter month. 在北半球,十二月是冬季。"},{"id":913,"unit":4,"lesson":2,"word":"atmosphere","pronunciation":"/ˈætməsfɪə(r)/","meaning":"n.大气层;气氛,氛围;气体","seq":8,"isStar":false,"memo":"联想:atmo(联想“阿童木”)+sphere(领域)→他说阿童木的活动领域是整个“大气层”。","example":"It will take a bit longer to transform the atmosphere so that human beings could live there. 要转变大气层使人类能够在那里生活,还需要更久。"},{"id":914,"unit":4,"lesson":2,"word":"atmospheric","pronunciation":"/ˌætməsˈferɪk/","meaning":"adj.大气的,大气层的","seq":9,"isStar":false},{"id":915,"unit":4,"lesson":2,"word":"circumstance","pronunciation":"/ˈsɜːkəmstəns/","meaning":"n.环境;境遇;状况;命运;客观环境","seq":10,"isStar":false,"memo":"联想 circum(联想 circle) + st(联想 stand) + -ance(名词后缀) → 周围站立的事物等 → 环境","example":"I know I can trust her in any circumstance. 我知道我在任何情况下都能信任她。"},{"id":916,"unit":4,"lesson":2,"word":"surround","pronunciation":"/səˈraʊnd/","meaning":"v.围绕;围住","seq":11,"isStar":false,"memo":"构词 sur-(上面) + round(环绕) → 从上面环绕着 → 围绕；围住","example":"The trees surround the lake. 环湖都是大树。"},{"id":917,"unit":4,"lesson":2,"word":"surroundings","pronunciation":"/səˈraʊndɪŋz/","meaning":"n.环境","seq":12,"isStar":false},{"id":918,"unit":4,"lesson":2,"word":"mood","pronunciation":"/muːd/","meaning":"n.情绪;气氛,氛围","seq":13,"isStar":false,"memo":"对照 独(d)自坐着看月亮(moon)，是很有氛围(mood)的。","example":"The foggy weather has affected Mary's mood. 雾蒙蒙的天气影响了玛丽的情绪。"},{"id":919,"unit":4,"lesson":2,"word":"moody","pronunciation":"/ˈmuːdi/","meaning":"adj.情绪多变的,喜怒无常的","seq":14,"isStar":false},{"id":920,"unit":4,"lesson":2,"word":"climate","pronunciation":"/ˈklaɪmət/","meaning":"n.气候(区);环境气氛;风气,氛围","seq":15,"isStar":false,"memo":"联想 c(形似半圆) + li(联想“立”) + mate(伙伴) → 伙伴们在我周围站立成了半圆，营造出节日的“氛围”。","example":"We need to adjust to this changing climate. 我们需要适应这种不断变化的气候。"},{"id":921,"unit":4,"lesson":2,"word":"climatic","pronunciation":"/klaɪˈmætɪk/","meaning":"adj.气候的","seq":16,"isStar":false},{"id":922,"unit":4,"lesson":2,"word":"universe","pronunciation":"/ˈjuːnɪvɜːs/","meaning":"n.宇宙;天地万物,万象","seq":17,"isStar":false,"memo":"构词 uni(one 一)+vers(转，同 reverse)+-e→转成一体的全部→宇宙，天地万物","example":"Could there be intelligent life elsewhere in the universe? 宇宙中别的地方还会有智慧生命吗？"},{"id":923,"unit":4,"lesson":2,"word":"universal","pronunciation":"/ˌjuːnɪˈvɜːs(ə)l/","meaning":"adj.普遍的,全体的;全世界的","seq":18,"isStar":false,"memo":"对照 universe n.宇宙 → universal adj.","example":"Agreement on this issue is almost universal. 这个问题几乎取得全体一致的意见。"},{"id":924,"unit":4,"lesson":2,"word":"widespread","pronunciation":"/ˈwaɪdspred/","meaning":"adj.分布广的;普遍的,广泛的","seq":19,"isStar":false,"memo":"构词 wide(广) + spread(传播) → 分布广的；普遍的；广泛的","example":"There is widespread support for the new proposals. 这些新提案得到广泛的支持。"},{"id":925,"unit":4,"lesson":2,"word":"anniversary","pronunciation":"/ˌænɪˈvɜːsəri/","meaning":"n.周年纪念日","seq":20,"isStar":false,"memo":"构词：anni-（年，如annual）+ vers-（转，如reverse）+ -ary→一年‘转’一圈的纪念日！别记成‘爱人纪念日’——那是‘anniversary’不是‘anniversary’！","example":"The university celebrated its 100th anniversary with a global forum. 大学举办全球论坛庆祝建校百年。"},{"id":926,"unit":4,"lesson":2,"word":"annual","pronunciation":"/ˈænjuəl/","meaning":"adj.每年的,一年一次的 n.年刊","seq":21,"isStar":false,"memo":"(记) (谐音) 单词发音类似“按年”→按年计次数 即“每年的”次数。","example":"The Consumer Technology Association is the sponsor of the annual Consumer Electronics Show.美国消费技术协会是年度国际消费电子展的主办方。"},{"id":927,"unit":4,"lesson":2,"word":"diverse","pronunciation":"/daɪˈvɜːs/","meaning":"adj.各种各样的,形形色色的","seq":22,"isStar":false,"memo":"【构词】di-（分开）+ verse（转）→各转各的方向→千差万别！像食堂窗口：川菜、粤菜、轻食、甜品——diverse到选不过来。","example":"Our university welcomes diverse cultural backgrounds. 我校欢迎多元文化背景的学生。"},{"id":928,"unit":4,"lesson":2,"word":"diversify","pronunciation":"/daɪˈvɜːsɪfaɪ/","meaning":"v.(使)多样化,变化","seq":23,"isStar":false,"memo":"构词 di-(分离)+vers(转)+-ify(使…化)→转向不同方向→(使)多样化，变化","example":"The company decided to diversify its products. 公司决定使产品多样化。"},{"id":929,"unit":4,"lesson":2,"word":"diversity","pronunciation":"/daɪˈvɜːsəti/","meaning":"n.差异,不同;多样性","seq":24,"isStar":false},{"id":930,"unit":4,"lesson":2,"word":"divert","pronunciation":"/daɪˈvɜːt/","meaning":"v.使转向;使绕道;改变","seq":25,"isStar":false,"memo":"【谐音+联想】‘迪维特’→ 迪士尼乐园游客太多，广播：‘Please divert to Exit B’（请转向B出口），路一转，方向就变！","example":"Traffic was diverted due to road construction near campus. 因校园附近道路施工，交通被临时改道。"},{"id":931,"unit":4,"lesson":2,"word":"diversion","pronunciation":"/daɪˈvɜːʃ(ə)n/","meaning":"n.转移,转向;消遣,娱乐","seq":26,"isStar":false,"memo":"(记) (构词) con-(一起)+verse(转换)→一起互相转换思想→交谈","example":"A smoke bomb created a diversion while the robbery took place.抢劫发生时，一枚烟雾弹制造了混乱。"},{"id":932,"unit":4,"lesson":2,"word":"converse","pronunciation":"/kənˈvɜːs/","meaning":"v.交谈","seq":27,"isStar":false,"memo":"构词 con-(一起) + verse(转换)→一起互相转换思想→交谈","example":"The converse of this concern is that the prospects of becoming a multi-paycheck household could encourage marriages. 成为多薪家庭的前景可能会鼓励人们结婚。"},{"id":933,"unit":4,"lesson":2,"word":"controversy","pronunciation":"/ˈkɒntrəvɜːsi/","meaning":"n.争议,论战;辩论","seq":28,"isStar":false,"memo":"构词 contro-(相反) + vers(e)(转) + -y(名词后缀)→相反的观点来回转→争议;论战","example":"There is always controversy in educational circles. 教育界一直存在争议。"},{"id":934,"unit":4,"lesson":2,"word":"controversial","pronunciation":"/ˌkɒntrəˈvɜːʃ(ə)l/","meaning":"adj.引起争论的,有争议的","seq":29,"isStar":false},{"id":935,"unit":4,"lesson":2,"word":"conversation","pronunciation":"/ˌkɒnvəˈseɪʃ(ə)n/","meaning":"n.(非正式的)交谈,谈话","seq":30,"isStar":false,"memo":"联想 conver(音似“看我”) + sa(音似 say) + tion(音似“什”)→请先看看我说过什么,再和我“交谈”。","example":"None of that is the topic of conversation in the dining room. 那些都不是在该餐厅里讨论的话题。"},{"id":936,"unit":4,"lesson":2,"word":"convert","pronunciation":"/kənˈvɜːt/","meaning":"v.(使)转变,转换","seq":31,"isStar":false,"memo":"构词 con-(一起,相互) + vert(= verse,转化)→转变","example":"You need to ensure that you've converted the data properly. 你需要确保已经正确转换了数据。"},{"id":937,"unit":4,"lesson":2,"word":"conversion","pronunciation":"/kənˈvɜːʃ(ə)n/","meaning":"n.转变,转换;转化","seq":32,"isStar":false},{"id":938,"unit":4,"lesson":2,"word":"convertible","pronunciation":"/kənˈvɜːtəb(ə)l/","meaning":"adj.可改变的;可转换的","seq":33,"isStar":false},{"id":939,"unit":4,"lesson":2,"word":"avert","pronunciation":"/əˈvɜːt/","meaning":"v.防止;避免(危险、坏事);转移目光","seq":34,"isStar":false,"memo":"[构词] a-(= away) + vert(转)→避免;转移目光","example":"A disaster was narrowly averted. 一场灾难被及时避免了。"},{"id":940,"unit":4,"lesson":2,"word":"aversion","pronunciation":"/əˈvɜːʃ(ə)n/","meaning":"n.厌恶,憎恶","seq":35,"isStar":false,"memo":"构词 a-(离开)+vers(转)+-ion(名词后缀)→把头转开不想看→厌恶，憎恶","example":"She has a strong aversion to noise. 她对噪音深恶痛绝。"},{"id":941,"unit":4,"lesson":2,"word":"invert","pronunciation":"/ɪnˈvɜːt/","meaning":"v.(使)倒转,颠倒,倒置","seq":36,"isStar":false,"memo":"[构词] in-(表加强) + vert(转)→彻底改变→颠倒","example":"Place a plate over the cake tin and invert it. 在蛋糕烤模上盖一个盘子,然后将其翻过来。"},{"id":942,"unit":4,"lesson":2,"word":"inversion","pronunciation":"/ɪnˈvɜːʃ(ə)n/","meaning":"n.倒置,颠倒,倒转","seq":37,"isStar":false,"memo":"构词 in-(向内)+vers(转)+-ion(名词后缀)→往里翻过来→倒置，颠倒，倒转","example":"The inversion of the word order changes the meaning. 词序颠倒会改变意思。"},{"id":943,"unit":4,"lesson":2,"word":"reverse","pronunciation":"/rɪˈvɜːs/","meaning":"n.相反的情况(或事物)","seq":38,"isStar":false,"memo":"[构词] re-(回,反) + verse(转)→往回转→彻底转变,使反转","example":"This problem is the reverse of the previous one. 这个问题和上一个问题相反。"},{"id":944,"unit":4,"lesson":2,"word":"reversal","pronunciation":"/rɪˈvɜːs(ə)l/","meaning":"n.颠倒;彻底转变;倒退","seq":39,"isStar":false,"memo":"构词 re-(回)+vers(转)+-al(名词后缀)→转回去→颠倒；彻底转变；倒退","example":"The decision was a complete reversal of policy. 这个决定是政策的彻底转变。"},{"id":945,"unit":4,"lesson":2,"word":"reversible","pronunciation":"/rɪˈvɜːsəb(ə)l/","meaning":"adj.可逆的;可翻转的;可两面穿的","seq":40,"isStar":false,"memo":"对照 reverse v.使反转→reversible adj.","example":"Is the trend reversible?这一趋势是可逆的吗？"},{"id":946,"unit":4,"lesson":2,"word":"adverse","pronunciation":"/ˈædvɜːs/","meaning":"adj.不利的;有害的;反面的","seq":41,"isStar":false,"memo":"[联想] ad(一再地)+verse(转)→孩子叛逆,一再地把头转向一边,如果家长引导不好,会产生“不利的”影响。","example":"Their state of mind can have adverse effect on their judgment. 他们的心理状态可能会对他们的判断产生不利影响。"},{"id":947,"unit":4,"lesson":2,"word":"adversity","pronunciation":"/ədˈvɜːsəti/","meaning":"n.困境,逆境;不幸","seq":42,"isStar":false,"memo":"构词 ad-(向)+vers(转)+-ity(名词后缀)→命运转向不利的一面→困境，逆境；不幸","example":"She showed great courage in adversity. 她在逆境中表现得非常勇敢。"},{"id":948,"unit":4,"lesson":2,"word":"adversary","pronunciation":"/ˈædvəsəri/","meaning":"n.(辩论、战斗中的)敌手,对手","seq":43,"isStar":false,"memo":"构词 advers(e)(反面的)+-ary(名词后缀)→敌手,对手","example":"The two of them were old adversaries.他们俩是老对手。"},{"id":949,"unit":4,"lesson":2,"word":"versatile","pronunciation":"/ˈvɜːsətaɪl/","meaning":"adj.多才多艺的;多功能的","seq":44,"isStar":false,"memo":"[联想] vers(转) + atile→能转得开的→多才多艺的","example":"He is a very versatile person. 他多才多艺。"},{"id":950,"unit":4,"lesson":2,"word":"verse","pronunciation":"/vɜːs/","meaning":"n.诗,诗节;韵文;歌曲的段落","seq":45,"isStar":false,"memo":"[谐音] 单词发音类似“我诗”→诗;诗节","example":"She has written enough poetry to put together a slender book of verse. 她写的诗足够编成一本薄薄的诗集了。"},{"id":951,"unit":4,"lesson":2,"word":"verbal","pronunciation":"/ˈvɜːb(ə)l/","meaning":"adj.口头的,言语的","seq":46,"isStar":false,"memo":"[谐音] 单词发音类似“我不”→这个小男孩不想做妈妈安排的事情时,常说“我不”→口头的","example":"These can be verbal cues or even body language. 这些可以是口头上的提示,甚至是肢体语言。"},{"id":952,"unit":4,"lesson":2,"word":"vocal","pronunciation":"/ˈvəʊk(ə)l/","meaning":"adj.嗓音的;发声的;歌唱的","seq":47,"isStar":false,"memo":"[联想] voc(联想 voice) + -al(形容词后缀)→嗓音的","example":"If a singer coughs, this can result in the bruising of the vocal chords. 歌手如果咳嗽,可能会导致声带损伤。"},{"id":953,"unit":4,"lesson":2,"word":"innovate","pronunciation":"/ˈɪnəveɪt/","meaning":"v.创新;改革","seq":48,"isStar":false,"memo":"in-(入) + nov(新) + -ate(动词后缀)→使新事物进入→创新,改革","example":"He called on graduates to innovate in his commencement address. 他在他的毕业典礼演讲中呼吁毕业生们创新。"},{"id":954,"unit":4,"lesson":2,"word":"innovation","pronunciation":"/ˌɪnəˈveɪʃ(ə)n/","meaning":"n.创造,创新;改革","seq":49,"isStar":false},{"id":955,"unit":4,"lesson":2,"word":"innovative","pronunciation":"/ˈɪnəveɪtɪv; ˈɪnəvətɪv/","meaning":"adj.革新的;创新的","seq":50,"isStar":false},{"id":956,"unit":4,"lesson":2,"word":"legend","pronunciation":"/ˈledʒənd/","meaning":"n.传说,传奇故事;传奇人物","seq":51,"isStar":false,"memo":"构词 leg(读，同 legible 可读的)+-end(名词后缀)→被代代传读的故事→传说；传奇人物","example":"What made him the legend he still is today? 是什么让他成为今天依旧传奇的人物呢?"},{"id":957,"unit":4,"lesson":2,"word":"legendary","pronunciation":"/ˈledʒəndri/","meaning":"adj.传奇的;传说的","seq":52,"isStar":false},{"id":958,"unit":4,"lesson":2,"word":"renovate","pronunciation":"/ˈrenəveɪt/","meaning":"v.修复;翻新;重新粉刷","seq":53,"isStar":false,"memo":"re-(再) + nov(新) + -ate(动词后缀)→使再次变新→翻新","example":"They spent the summer renovating the farmhouse. 他们花了一个夏天翻新农舍。"},{"id":959,"unit":4,"lesson":2,"word":"renovation","pronunciation":"/ˌrenəˈveɪʃ(ə)n/","meaning":"n.修复;翻新;重新粉刷","seq":54,"isStar":false},{"id":960,"unit":4,"lesson":2,"word":"evolve","pronunciation":"/ɪˈvɒlv/","meaning":"v.进化;逐步发展;逐渐演变","seq":55,"isStar":false,"memo":"e-(向外) + volve(转)→向外回转→螺旋式上升→进化;逐步发展","example":"The company has evolved into a major chemical manufacture. 这家公司已逐步发展成一个主要的化工厂。"},{"id":961,"unit":4,"lesson":2,"word":"evolution","pronunciation":"/ˌiːvəˈluːʃ(ə)n/","meaning":"n.进化;演变;发展","seq":56,"isStar":false},{"id":962,"unit":4,"lesson":3,"word":"evolutionary","pronunciation":"/ˌiːvəˈluːʃən(ə)ri/","meaning":"adj.进化的;逐渐发展的","seq":1,"isStar":false},{"id":963,"unit":4,"lesson":3,"word":"involve","pronunciation":"/ɪnˈvɒlv/","meaning":"v.涉及;包含;需要;参与","seq":2,"isStar":false,"memo":"in-(= in) + volve (转) →转入→涉及;包含","example":"It has to involve spending a lot of money and time. 这需要花费大量的金钱和时间。"},{"id":964,"unit":4,"lesson":3,"word":"involvement","pronunciation":"/ɪnˈvɒlvmənt/","meaning":"n.参与;加入;插手","seq":3,"isStar":false},{"id":965,"unit":4,"lesson":3,"word":"involved","pronunciation":"/ɪnˈvɒlvd/","meaning":"adj.卷入的,有关的;复杂的","seq":4,"isStar":false},{"id":966,"unit":4,"lesson":3,"word":"revolve","pronunciation":"/rɪˈvɒlv/","meaning":"v.旋转;环绕","seq":5,"isStar":false,"memo":"[对照] revolve v.旋转→revolution n.","example":"Contrast this with farming since the start of the industrial revolution. 将这与工业革命开始以来的农业对比一下。"},{"id":967,"unit":4,"lesson":3,"word":"revolution","pronunciation":"/ˌrevəˈluːʃn/","meaning":"n.革命,巨变;大变革","seq":6,"isStar":false,"memo":"对照 revolve v.旋转→revolution n.","example":"Contrast this with farming since the start of the industrial revolution.与工业革命以来的农业相比，情况截然不同。"},{"id":968,"unit":4,"lesson":3,"word":"revolutionary","pronunciation":"/ˌrevəˈluːʃənəri/","meaning":"adj.革命的 n.改革者;革命者","seq":7,"isStar":false},{"id":969,"unit":4,"lesson":3,"word":"revolt","pronunciation":"/rɪˈvəʊlt/","meaning":"n.反抗;起义;造反 v.叛逆;反抗","seq":8,"isStar":false,"memo":"[构词] re-(回)+volt(转)→往回转,反转过来(对抗自己人)→反抗,反叛","example":"The people revolted against foreign rule. 人们起来反抗外来统治。"},{"id":970,"unit":4,"lesson":3,"word":"renaissance","pronunciation":"/rɪˈneɪs(ə)ns/","meaning":"n.(尤指某种艺术形式、音乐形式等的)复","seq":9,"isStar":false,"memo":"[联想] re(字母音似“阿姨”)+nai(联想“奶”)+ssance(音似“神似”)→阿姨和奶奶年轻时候的穿着神似,说明了中式审美的“复兴”。","example":"Hawaiian culture is a living culture undergoing a renaissance today. 夏威夷文化是一种蓬勃复兴的活态文明。"},{"id":971,"unit":4,"lesson":3,"word":"revive","pronunciation":"/rɪˈvaɪv/","meaning":"v.(使)苏醒,使复苏;重新上演","seq":10,"isStar":false,"memo":"[构词] re-(重新)+vive(=live)→重新活过来→(使)苏醒;使复苏","example":"Robots help companies to revive. 机器人帮助企业复苏。"},{"id":972,"unit":4,"lesson":3,"word":"revival","pronunciation":"/rɪˈvaɪv(ə)l/","meaning":"n.复兴;复苏;再流行;重演","seq":11,"isStar":false},{"id":973,"unit":4,"lesson":3,"word":"vivid","pronunciation":"/ˈvɪvɪd/","meaning":"adj.生动的,逼真的;鲜艳的","seq":12,"isStar":false,"memo":"[谐音] 单词发音类似“娓娓的”→娓娓动听的→生动的","example":"This doesn't make my emotions any more vivid. 这并未让我的情感体验变得更加鲜活。"},{"id":974,"unit":4,"lesson":3,"word":"survive","pronunciation":"/səˈvaɪv/","meaning":"v.生存,幸存,生还","seq":13,"isStar":false,"memo":"[构词] sur-(超过)+vive(=live)→超过(困境)生存下来→幸存","example":"They can only survive in parts of the Americas. 他们只能在美洲部分地区生存。"},{"id":975,"unit":4,"lesson":3,"word":"survivor","pronunciation":"/səˈvaɪvə(r)/","meaning":"n.生还者,幸存者","seq":14,"isStar":false},{"id":976,"unit":4,"lesson":3,"word":"survival","pronunciation":"/səˈvaɪv(ə)l/","meaning":"n.幸存,存活;残存物","seq":15,"isStar":false},{"id":977,"unit":4,"lesson":3,"word":"reform","pronunciation":"/rɪˈfɔːm/","meaning":"n.改革,改良 v.改革,改进","seq":16,"isStar":false,"memo":"[构词] re-(再)+form(形成)→再形成一种形态→改革,改进","example":"The law needs to be reformed. 法律需要进行改革。"},{"id":978,"unit":4,"lesson":3,"word":"reformation","pronunciation":"/ˌrefəˈmeɪʃn/","meaning":"n.改革,改进","seq":17,"isStar":false},{"id":979,"unit":4,"lesson":3,"word":"reformist","pronunciation":"/rɪˈfɔːmɪst/","meaning":"n.改良者,改革者 adj.主张改革的","seq":18,"isStar":false},{"id":980,"unit":4,"lesson":3,"word":"conform","pronunciation":"/kənˈfɔːm/","meaning":"v.遵守,顺从;相一致,相吻合","seq":19,"isStar":false,"memo":"[构词] con-(共同) + form(形式)→使形式统一→相一致","example":"We must conform to the rules. 我们必须遵守规定。"},{"id":981,"unit":4,"lesson":3,"word":"conformity","pronunciation":"/kənˈfɔːməti/","meaning":"n.(对社会规则的)遵从,遵守","seq":20,"isStar":false},{"id":982,"unit":4,"lesson":3,"word":"uniform","pronunciation":"/ˈjuːnɪfɔːm/","meaning":"n.校服;制服","seq":21,"isStar":false,"memo":"[构词] uni-(单一，统一) + form(形式)→校服；制服","example":"He quickly put on his uniform. 他迅速穿上制服。"},{"id":983,"unit":4,"lesson":3,"word":"uniformity","pronunciation":"/ˌjuːnɪˈfɔːməti/","meaning":"n.一致;统一","seq":22,"isStar":false},{"id":984,"unit":4,"lesson":3,"word":"platform","pronunciation":"/ˈplætfɔːm/","meaning":"n.站台;讲台;舞台;平台","seq":23,"isStar":false,"memo":"[构词] plat(平坦的) + form(形式)→平台","example":"What platform does it go from? 它从哪个站台发车？"},{"id":985,"unit":4,"lesson":3,"word":"formula","pronunciation":"/ˈfɔːmjələ/","meaning":"n.公式;配方","seq":24,"isStar":false,"memo":"构词 form(形式)+-ula(小词后缀)→固定下来的一小串形式→公式；配方","example":"This formula is used to calculate the area of a circle. 这个公式用于计算圆的面积。"},{"id":986,"unit":4,"lesson":3,"word":"formulate","pronunciation":"/ˈfɔːmjuleɪt/","meaning":"v.制定;规划;构想;确切表达","seq":25,"isStar":false,"memo":"[联想] for(音似 four) + mu(联想“母”) + late(晚)→开家长会时，四个妈妈迟到了，她们“确切表达”了理由。","example":"Governments need to formulate energy policies. 各国政府需要制定能源政策。"},{"id":987,"unit":4,"lesson":3,"word":"formulation","pronunciation":"/ˌfɔːmjuˈleɪʃ(ə)n/","meaning":"n.制定;规划;构想;确切表达","seq":26,"isStar":false},{"id":988,"unit":4,"lesson":3,"word":"formal","pronunciation":"/ˈfɔːm(ə)l/","meaning":"adj.正规的,正式的;形式上的;整齐的","seq":27,"isStar":false,"memo":"[构词] form(形式) + -al(形容词后缀)→正式的；形式上的","example":"He kept the tone of the letter formal and businesslike. 他使这封信保持正式公文的语气。"},{"id":989,"unit":4,"lesson":3,"word":"formality","pronunciation":"/fɔːˈmæləti/","meaning":"n.正式手续;例行公事","seq":28,"isStar":false},{"id":990,"unit":4,"lesson":3,"word":"inform","pronunciation":"/ɪnˈfɔːm/","meaning":"v.通知,通告;了解,熟悉","seq":29,"isStar":false,"memo":"[对照] information n.信息→inform v.","example":"Please inform us of any changes of address. 地址若有变动，请通知我们。"},{"id":991,"unit":4,"lesson":3,"word":"information","pronunciation":"/ˌɪnfəˈmeɪʃ(ə)n/","meaning":"n.信息,消息,情报;资料","seq":30,"isStar":false},{"id":992,"unit":4,"lesson":3,"word":"informative","pronunciation":"/ɪnˈfɔːmətɪv/","meaning":"adj.提供有用信息的;给予知识的","seq":31,"isStar":false},{"id":993,"unit":4,"lesson":3,"word":"informant","pronunciation":"/ɪnˈfɔːmənt/","meaning":"n.告密者;合作者","seq":32,"isStar":false},{"id":994,"unit":4,"lesson":3,"word":"perform","pronunciation":"/pəˈfɔːm/","meaning":"v.演出,表演;做;执行;工作,运转","seq":33,"isStar":false,"memo":"对照 每一个(per)人都来表演(perform)。","example":"The tasks had to be performed in a particular sequence.这些任务必须按特定顺序完成。"},{"id":995,"unit":4,"lesson":3,"word":"performance","pronunciation":"/pəˈfɔːməns/","meaning":"n.表演,演出;表现;业绩","seq":34,"isStar":false},{"id":996,"unit":4,"lesson":3,"word":"performer","pronunciation":"/pəˈfɔːmə(r)/","meaning":"n.表演者,演出者","seq":35,"isStar":false},{"id":997,"unit":4,"lesson":3,"word":"inspect","pronunciation":"/ɪnˈspekt/","meaning":"v.仔细检查,检验;视察","seq":36,"isStar":false,"memo":"[构词] in-(入) + spect(看)→看入内部→仔细检查;视察","example":"The police will inspect the venue for safety. 警察将仔细检查会场是否安全。"},{"id":998,"unit":4,"lesson":3,"word":"inspection","pronunciation":"/ɪnˈspekʃ(ə)n/","meaning":"n.视察;检查","seq":37,"isStar":false},{"id":999,"unit":4,"lesson":3,"word":"inspector","pronunciation":"/ɪnˈspektə(r)/","meaning":"n.检查员;视察员,巡视员;(警察)巡官","seq":38,"isStar":false,"memo":"构词 inspect(仔细检查;视察)+-or(表示","example":"Standards of discipline were criticized in the report. 纪律标准在报告中受到批评。"},{"id":1000,"unit":4,"lesson":3,"word":"expect","pronunciation":"/ɪkˈspekt/","meaning":"v.预期;期待;要求,期望;猜想","seq":39,"isStar":false,"memo":"构词 ex-(向外)+pect(看，同 spectacle 景象)→向外张望着等→预期；期待；要求","example":"Its results were just as expected. 结果正如预期的那样。"},{"id":1001,"unit":4,"lesson":3,"word":"expectation","pronunciation":"/ˌekspekˈteɪʃ(ə)n/","meaning":"n.预料;预期;期望","seq":40,"isStar":false},{"id":1002,"unit":4,"lesson":3,"word":"expectancy","pronunciation":"/ɪkˈspektənsi/","meaning":"n.预期;期待;期望","seq":41,"isStar":false,"memo":"构词 expect(预期;期待)+-ancy(名词后","example":"I saw the look of expectancy in children's eyes.我在孩子们眼中看到了期待的神情。"},{"id":1003,"unit":4,"lesson":3,"word":"life expectancy","pronunciation":"/ˈlaɪf ɪkspektənsi/","meaning":"n.预期寿命","seq":42,"isStar":false,"memo":"构词 expect(期待)+-ancy(名词后缀)→人们预计能活的年数→预期寿命","example":"Life expectancy has risen steadily. 预期寿命在稳步上升。"},{"id":1004,"unit":4,"lesson":3,"word":"longevity","pronunciation":"/lɒnˈdʒevəti/","meaning":"n.长寿;持续时间","seq":43,"isStar":false,"memo":"构词 long(长的)+ev(=age)+-ity(名词","example":"The longevity effect is also seen in Nobel Prize winners. 长寿效应在诺贝尔奖获得者中也能看到。"},{"id":1005,"unit":4,"lesson":3,"word":"prolong","pronunciation":"/prəˈlɒŋ/","meaning":"v.延长","seq":44,"isStar":false,"memo":"[构词] pro-(往前) + long(长)→往前变长→延长","example":"Surgery for cancer may cure or prolong someone's life. 癌症手术可能会治愈疾病或延长某人的生命。"},{"id":1006,"unit":4,"lesson":3,"word":"lengthy","pronunciation":"/ˈleŋθi/","meaning":"adj.长时间的,冗长的","seq":45,"isStar":false,"memo":"构词 length(长度)+-y(形容词后缀)→长","example":"An athlete with overtraining syndrome should rest. 患有过度训练综合征的运动员应该多休息。"},{"id":1007,"unit":4,"lesson":3,"word":"aspect","pronunciation":"/ˈæspekt/","meaning":"n.方面;方位;外观,外表","seq":46,"isStar":false,"memo":"[联想] a(一) + spect(看) → 看一眼,只能了解事物的一个“方面”。","example":"Every aspect of our lives will be transformed. 我们生活的方方面面都将被改变。"},{"id":1008,"unit":4,"lesson":3,"word":"suspect","pronunciation":"/səˈspekt/","meaning":"n.犯罪嫌疑人 adj.可疑的 v.猜想","seq":47,"isStar":false,"memo":"[构词] sus-(在下) + spect(看) → 在下面看→暗暗打量→怀疑;犯罪嫌疑人","example":"He is suspected of having slipped something in her bag. 他涉嫌在她的包里塞了什么东西。"},{"id":1009,"unit":4,"lesson":3,"word":"suspicion","pronunciation":"/səˈspɪʃ(ə)n/","meaning":"n.怀疑,嫌疑","seq":48,"isStar":false,"memo":"[谐音] 单词发音类似“瑟斯陪审”→这个人有“嫌疑”,瑟斯在陪审。","example":"They drove away slowly to avoid arousing suspicion. 他们驾车缓缓离去,以免引起怀疑。"},{"id":1010,"unit":4,"lesson":3,"word":"suspicious","pronunciation":"/səˈspɪʃəs/","meaning":"adj.怀疑的;可疑的","seq":49,"isStar":false},{"id":1011,"unit":4,"lesson":3,"word":"susceptible","pronunciation":"/səˈseptəb(ə)l/","meaning":"adj.易受影响的;易得病的","seq":50,"isStar":false,"memo":"[构词] sus-(在下) + cept(拿) + -ible(能……的) → 能被拿下的→易受影响的","example":"Some of these plants are more susceptible to frost damage than others. 其中的一些植物比其他植物更容易受到霜冻损害。"},{"id":1012,"unit":4,"lesson":3,"word":"spectator","pronunciation":"/spekˈteɪtə(r)/","meaning":"n.观看者,观众","seq":51,"isStar":false,"memo":"[联想] spect(看) + at(在) + -or(表示人的后缀) → 在看比赛的人→观看者,观众","example":"They try hard to meet the spectators' expectations. 他们努力满足观众的期望。"},{"id":1013,"unit":4,"lesson":3,"word":"respect","pronunciation":"/rɪˈspekt/","meaning":"n.尊敬;方面 v.尊敬;遵守","seq":52,"isStar":false,"memo":"[构词] re-(再;反复) + spect(看) → 反复看(对方)→尊敬","example":"He should show respect for the interviewer. 他应该尊重面试官。"},{"id":1014,"unit":4,"lesson":3,"word":"respectable","pronunciation":"/rɪˈspektəbl/","meaning":"adj.体面的;值得尊敬的","seq":53,"isStar":false},{"id":1015,"unit":4,"lesson":3,"word":"respectful","pronunciation":"/rɪˈspektfl/","meaning":"adj.有礼貌的,尊敬的","seq":54,"isStar":false},{"id":1016,"unit":4,"lesson":3,"word":"respective","pronunciation":"/rɪˈspektɪv/","meaning":"adj.各自的,分别的","seq":55,"isStar":false,"memo":"【构词】re-（回）+ spec（看）+ -ive→各自回头‘看’自己的那份→各自的！小组汇报时：A讲方法，B讲数据，C讲结论——respectively对应。","example":"The three departments submitted their reports respectively. 三个部门分别提交了各自的报告。"},{"id":1017,"unit":4,"lesson":3,"word":"respectively","pronunciation":"/rɪˈspektɪvli/","meaning":"adv.各自,分别;依次为;顺序为","seq":56,"isStar":false},{"id":1018,"unit":4,"lesson":3,"word":"spectacular","pronunciation":"/spekˈtækjələ(r)/","meaning":"adj.壮观的","seq":57,"isStar":false,"memo":"[联想] spec(t)(看) + tacular(音似“太酷了”) → 看起来太酷了→壮观的;令人惊叹的","example":"With creativity, even old-fashioned instruments may produce spectacular sound effects. 有了创造力,即使是老式乐器也可能产生令人惊叹的音效。"},{"id":1019,"unit":4,"lesson":3,"word":"spectacle","pronunciation":"/ˈspektək(ə)l/","meaning":"n.壮观的场面(景象)","seq":58,"isStar":false,"memo":"[联想] spec(t)(看) + tacle(音似“特酷”) → 我们看到“壮观的场面”会觉得特别酷。","example":"It was a spectacle not to be missed. 这是一个不可错过的奇观。"},{"id":1020,"unit":4,"lesson":3,"word":"prosperity","pronunciation":"/prɒˈsperəti/","meaning":"n.兴旺,繁荣,昌盛","seq":59,"isStar":false,"memo":"[记] (联想) pro-(前面)+sper(联想 spect)+-ity (名词后缀)→向前看中国的经济,看到的是一片“繁荣”景象。","example":"The prosperity of a nation is largely dependent upon the quality of education of its people.一个国家的繁荣很大程度上取决于其人民的教育质量。"},{"id":1021,"unit":4,"lesson":3,"word":"prosper","pronunciation":"/ˈprɒspə(r)/","meaning":"v.繁荣,兴旺,发达","seq":60,"isStar":false},{"id":1022,"unit":4,"lesson":3,"word":"prosperous","pronunciation":"/ˈprɒspərəs/","meaning":"adj.繁荣的,兴旺的,发达的","seq":61,"isStar":false},{"id":1023,"unit":4,"lesson":3,"word":"spectrum","pronunciation":"/ˈspektrəm/","meaning":"n.(观点、人、情况等的)范围,幅度","seq":62,"isStar":false,"memo":"联想 spec(t)(看)+trum(音似“戳目”)→这部分“光谱”的光会看得戳目(刺眼)。","example":"The colours of the spectrum can be seen in a rainbow. 光谱中的颜色都可以在彩虹中见到。"},{"id":1024,"unit":4,"lesson":3,"word":"conspicuous","pronunciation":"/kənˈspɪkjuəs/","meaning":"adj.明显的,引人注目的","seq":63,"isStar":false,"memo":"构词 con-(一起)+spic(=spect,看)+(u)ous(形容词后缀)→有目共睹的→明显的,引人注目的","example":"A visitor to a museum today would notice conspicuous changes in the way museums are operated. 今天参观博物馆的游客会注意到博物馆运作方式的明显变化。"},{"id":1025,"unit":4,"lesson":4,"word":"despise","pronunciation":"/dɪˈspaɪz/","meaning":"v.鄙视,蔑视","seq":1,"isStar":false,"memo":"构词 de-(向下)+spise(=spect,看)→向下看→鄙视,蔑视","example":"I despise such people; they've no character. 我藐视这种人;他们没骨气。"},{"id":1026,"unit":4,"lesson":4,"word":"scorn","pronunciation":"/skɔːn/","meaning":"n.&v.轻视,鄙视,蔑视","seq":2,"isStar":false,"memo":"对照 吃着人家的玉米(corn)还鄙视(scorn)人家,这是不对的。","example":"The man looked at him with scorn. 那人轻蔑地看着他。"},{"id":1027,"unit":4,"lesson":4,"word":"scornful","pronunciation":"/ˈskɔːnf(ə)l/","meaning":"adj.轻蔑的,鄙视的","seq":3,"isStar":false},{"id":1028,"unit":4,"lesson":4,"word":"perspective","pronunciation":"/pəˈspektɪv/","meaning":"n.角度,观点,看法;透视法;景观","seq":4,"isStar":false,"memo":"构词 per(透过)+spect(看)+-ive(名词后缀)→看透了→观点,看法","example":"It inspired them to view things from broader perspectives. 这激励他们从更广阔的角度看待事物。"},{"id":1029,"unit":4,"lesson":4,"word":"stance","pronunciation":"/stæns/","meaning":"n.(公开表明的)观点,立场,看法;站姿","seq":5,"isStar":false,"memo":"对照 思想上站(stand)的那个点,就是我们的观点(stance)。","example":"An open-science stance can also add complexity to a collaboration. 开放科学的立场也会增加合作的复杂性。"},{"id":1030,"unit":4,"lesson":4,"word":"standpoint","pronunciation":"/ˈstændpɔɪnt/","meaning":"n.立场,观点","seq":6,"isStar":false,"memo":"[构词] stand(站) + point(点)→立场,观点","example":"We must approach the problem from a different standpoint. 我们必须换一种角度来处理这个问题。"},{"id":1031,"unit":4,"lesson":4,"word":"substance","pronunciation":"/ˈsʌbstəns/","meaning":"n.物质;主旨;实质","seq":7,"isStar":false,"memo":"[构词] sub-(在下) + stance(观点)→站在(观点等的)下面→物质;主旨","example":"Some brand-name coffees contain harmful substances. 一些名牌咖啡含有有害物质。"},{"id":1032,"unit":4,"lesson":4,"word":"substantial","pronunciation":"/səbˈstænʃ(ə)l/","meaning":"adj.大量的;重大的","seq":8,"isStar":false},{"id":1033,"unit":4,"lesson":4,"word":"stereotype","pronunciation":"/ˈsteriətaɪp/","meaning":"n.刻板印象","seq":9,"isStar":false,"memo":"[联想] ste(音似“死呆”) + reo(音似 real) + type(类型)→如果认为他真的是死呆类型的人,那就是“刻板印象”了。","example":"A stereotype is a simplistic or exaggerated image that human carries in their minds about groups of people. 刻板印象是人们头脑中对一群人持有的一种简单化或夸张的印象。"},{"id":1034,"unit":4,"lesson":4,"word":"prototype","pronunciation":"/ˈprəʊtətaɪp/","meaning":"n.原型,雏形","seq":10,"isStar":false,"memo":"[构词] proto-(最初的,原始的) + type(类型)→原型,雏形","example":"The prototype is athletic and super smart. 这个原型体格健壮、非常聪明。"},{"id":1035,"unit":4,"lesson":4,"word":"speculate","pronunciation":"/ˈspekjuleɪt/","meaning":"v.猜测,推测;投机","seq":11,"isStar":false,"memo":"[联想] spec(联想 spect,看) + u(联想 you) + late(迟)→他看完你的信迟迟未动,开始“推测”后面的事。","example":"It is useless to speculate why he did it. 对他为什么这么做妄加猜测毫无用处。"},{"id":1036,"unit":4,"lesson":4,"word":"speculation","pronunciation":"/ˌspekjuˈleɪʃ(ə)n/","meaning":"n.猜测;投机买卖","seq":12,"isStar":false},{"id":1037,"unit":4,"lesson":4,"word":"speculative","pronunciation":"/ˈspekjələtɪv/","meaning":"adj.猜测的;投机的","seq":13,"isStar":false},{"id":1038,"unit":4,"lesson":4,"word":"articulate","pronunciation":"/ɑːˈtɪkjuleɪt/","meaning":"v.清楚地表达","seq":14,"isStar":false,"memo":"[联想] art(艺术) + i(我) + culate→我能用艺术性的语言把事物表达出来,他说我是“能说会道的”。","example":"He was too drunk to articulate properly. 他醉得连话都说不清楚。"},{"id":1039,"unit":4,"lesson":4,"word":"articulation","pronunciation":"/ɑːˌtɪkjuˈleɪʃn/","meaning":"n.表达;说话;发音;清晰","seq":15,"isStar":false},{"id":1040,"unit":4,"lesson":4,"word":"prospect","pronunciation":"/ˈprɒspekt/","meaning":"n.前景,展望;希望;可能性 v.勘探","seq":16,"isStar":false,"memo":"[构词] pro-(往前) + spect(看)→前景,展望","example":"I'm very excited at the prospect of joining the team. 我对加入这个团队的前景感到非常兴奋。"},{"id":1041,"unit":4,"lesson":4,"word":"prospective","pronunciation":"/prəˈspektɪv/","meaning":"adj.有望的;预期的;潜在的","seq":17,"isStar":false,"memo":"[构词] prospect(展望) + -ive(形容词后缀)→有望的;潜在的","example":"I had a phone call from a prospective client today. 我今天接到一个潜在客户打来的电话。"},{"id":1042,"unit":4,"lesson":4,"word":"retrospect","pronunciation":"/ˈretrəspekt/","meaning":"n.回顾,回想,追溯往事","seq":18,"isStar":false,"memo":"[构词] retro-(向后) + spect(看)→回顾","example":"In retrospect, I think that I was wrong. 回首往事,我觉得当时我错了。"},{"id":1043,"unit":4,"lesson":4,"word":"retrospective","pronunciation":"/ˌretrəˈspektɪv/","meaning":"adj.回顾的;有追溯效力的","seq":19,"isStar":false},{"id":1044,"unit":4,"lesson":4,"word":"portray","pronunciation":"/pɔːˈtreɪ/","meaning":"v.描写,描绘;画(人物、景象等)","seq":20,"isStar":false,"memo":"por(音似“破”)+tray(音似tree)→他能把一棵残破的树“描绘”得活灵活现。","example":"It portrayed western train trips as wonderful adventures. 它把西部的火车旅行描绘成美妙的冒险。"},{"id":1045,"unit":4,"lesson":4,"word":"portrait","pronunciation":"/ˈpɔːtreɪt/","meaning":"n.(人的)肖像,画像;(对事物的)描绘","seq":21,"isStar":false},{"id":1046,"unit":4,"lesson":4,"word":"portrayal","pronunciation":"/pɔːˈtreɪəl/","meaning":"n.描绘,描写","seq":22,"isStar":false},{"id":1047,"unit":4,"lesson":4,"word":"sculpture","pronunciation":"/ˈskʌlptʃə(r)/","meaning":"n.雕像;雕塑品","seq":23,"isStar":false,"memo":"sculp(音似“思刻”)+ture(名词后缀)→他思考片刻后雕刻出来一个“雕像”。","example":"She has learned to appreciate sculptures. 她已学会欣赏雕塑。"},{"id":1048,"unit":4,"lesson":4,"word":"carve","pronunciation":"/kɑːv/","meaning":"v.雕,刻","seq":24,"isStar":false,"memo":"他在山洞(cave)的壁上雕刻(carve)了一朵花。","example":"The statue was carved out of a single piece of stone. 这座雕像是用整块石料雕成的。"},{"id":1049,"unit":4,"lesson":4,"word":"carving","pronunciation":"/ˈkɑːvɪŋ/","meaning":"n.雕刻品;雕刻图案;雕像","seq":25,"isStar":false},{"id":1050,"unit":4,"lesson":4,"word":"describe","pronunciation":"/dɪˈskraɪb/","meaning":"v.描述,形容;描写","seq":26,"isStar":false,"memo":"de-(往下)+scribe(写)→写下来→描述","example":"Reporters gathered in the hall to hear her describe the plan. 记者聚集在大厅里,听她描述这一计划。"},{"id":1051,"unit":4,"lesson":4,"word":"description","pronunciation":"/dɪˈskrɪpʃn/","meaning":"n.描写(文字),形容;说明;类型","seq":27,"isStar":false},{"id":1052,"unit":4,"lesson":4,"word":"descriptive","pronunciation":"/dɪˈskrɪptɪv/","meaning":"adj.描写的;叙述的;说明的","seq":28,"isStar":false},{"id":1053,"unit":4,"lesson":4,"word":"depict","pronunciation":"/dɪˈpɪkt/","meaning":"v.描绘;描写,描述;刻画","seq":29,"isStar":false,"memo":"de-(表加强)+pict(联想picture)→这是一幅“描绘”乡村美景的画。","example":"The novel depicts French society in the 1930s. 这部小说描述了20世纪30年代的法国社会。"},{"id":1054,"unit":4,"lesson":4,"word":"ascribe","pronunciation":"/əˈskraɪb/","meaning":"v.把……归因于","seq":30,"isStar":false,"memo":"a-(=to)+scribe(写,记)→把……记在某人头上→把……归因于","example":"The famous scientist ascribed his success to hard work. 这位著名的科学家把他的成功归功于努力工作。"},{"id":1055,"unit":4,"lesson":4,"word":"prescribe","pronunciation":"/prɪˈskraɪb/","meaning":"v.给……开药(开处方);规定","seq":31,"isStar":false,"memo":"pre-(在前)+scribe(写)→拿药前,(请医生)提前写好处方→给……开药(开处方)","example":"We should all do as the law prescribes. 我们都应该依法办事。"},{"id":1056,"unit":4,"lesson":4,"word":"prescription","pronunciation":"/prɪˈskrɪpʃn/","meaning":"n.处方,药方;(医生开的)处方药","seq":32,"isStar":false},{"id":1057,"unit":4,"lesson":4,"word":"subscribe","pronunciation":"/səbˈskraɪb/","meaning":"v.订购;订阅;申请;报名;认购(股份)","seq":33,"isStar":false,"memo":"构词 sub-(在下面)+scrib(写，同 describe 描述)+-e→在单子下面签字→订购，订阅；报名；认购","example":"I subscribe to two weekly magazines. 我订阅了两本周刊。"},{"id":1058,"unit":4,"lesson":4,"word":"subscriber","pronunciation":"/səbˈskraɪbə(r)/","meaning":"n.订阅人;消费者;用户","seq":34,"isStar":false},{"id":1059,"unit":4,"lesson":4,"word":"subscription","pronunciation":"/səbˈskrɪpʃ(ə)n/","meaning":"n.(报刊等的)订阅费;订阅;捐助","seq":35,"isStar":false,"example":"Subscriptions are due annually by the end of January.订阅费须在每年一月底前缴清。"},{"id":1060,"unit":4,"lesson":4,"word":"script","pronunciation":"/skrɪpt/","meaning":"n.剧本,讲稿;笔迹,手迹 v.写剧本","seq":36,"isStar":false,"memo":"构词 sub-(下面)+scribe(写)→在下面写(名字、地址)→订购；订阅；报名","example":"We're currently working on a script. 我们目前正在写剧本。"},{"id":1061,"unit":4,"lesson":4,"word":"scripture","pronunciation":"/ˈskrɪptʃə(r)/","meaning":"n.(某宗教的)经文,经籍;《圣经》","seq":37,"isStar":false,"memo":"构词 script(写，同 script 手稿)+-ure(名词后缀)→写下来的神圣文本→经文，经籍","example":"He reads scripture every morning. 他每天早晨诵读经文。"},{"id":1062,"unit":4,"lesson":4,"word":"manuscript","pronunciation":"/ˈmænjuskrɪpt/","meaning":"n.手稿,原稿;手抄本","seq":38,"isStar":false,"memo":"构词 manu (= hand) + script (讲稿) → 手写的讲稿 → 手稿，原稿","example":"I read her poems in manuscript. 我读过她的诗作的手稿。"},{"id":1063,"unit":4,"lesson":4,"word":"transcript","pronunciation":"/ˈtrænskrɪpt/","meaning":"n.抄本;誊本","seq":39,"isStar":false,"memo":"构词 trans-(转移，同 transfer)+script(写)→转写下来的东西→抄本，誊本","example":"The White House posted a transcript of the speech on its website.白宫在其网站上发布了这篇讲话的文字记录。"},{"id":1064,"unit":4,"lesson":4,"word":"manual","pronunciation":"/ˈmænjuəl/","meaning":"adj.手工的;手动的","seq":40,"isStar":false,"memo":"构词 manu(手)+-al(后缀)→手工的","example":"They can avoid doing much of the manual labor. 他们可以避免做大量的体力劳动。"},{"id":1065,"unit":4,"lesson":4,"word":"manufacture","pronunciation":"/ˌmænjuˈfæktʃə(r)/","meaning":"v.(用机器)大量生产","seq":41,"isStar":false,"memo":"构词 manu(手)+fact(做)+-ure(后缀)→手工制作→大量生产；成批制造","example":"This company manufactures the equipment used to make contact lenses. 这家公司生产用以制造隐形眼镜片的设备。"},{"id":1066,"unit":4,"lesson":4,"word":"manufacturer","pronunciation":"/ˌmænjuˈfæktʃərə(r)/","meaning":"n.生产者,制造者,生产商","seq":42,"isStar":false,"memo":"构词 manufacture(大量生产)+-(e)r(表示人的后缀)→生产者","example":"One British manufacturer accepted this suggestion. 一家英国的制造商接受了这一建议。"},{"id":1067,"unit":4,"lesson":4,"word":"mandate","pronunciation":"/ˈmændeɪt/","meaning":"v.强制执行;授权 n.授权","seq":43,"isStar":false,"memo":"联想 man(联想“慢”) + date(日期) → 虽然很慢，但他们最终确定了“授权”的日期。","example":"The law mandates that imported goods be identified as such. 法律规定，进口货物必须如实标明。"},{"id":1068,"unit":4,"lesson":4,"word":"mandatory","pronunciation":"/ˈmændətəri/","meaning":"adj.强制的;法定的;义务的","seq":44,"isStar":false},{"id":1069,"unit":4,"lesson":4,"word":"emancipate","pronunciation":"/ɪˈmænsɪpeɪt/","meaning":"v.解放","seq":45,"isStar":false,"memo":"构词 e-(出)+man(u)(手)+cip(拿取)+-ate(动词后缀)→把手从束缚中拿出来→解放;使不受束缚","example":"They were not emancipated until 1863.他们直到1863年才获得解放。"},{"id":1070,"unit":4,"lesson":4,"word":"emancipation","pronunciation":"/ɪˌmænsɪˈpeɪʃ(ə)n/","meaning":"n.解放","seq":46,"isStar":false},{"id":1071,"unit":4,"lesson":4,"word":"manoeuvre/maneuver","pronunciation":"/məˈnuːvə(r)/","meaning":"n.机动动作;策略,手段 v.操纵,控制","seq":47,"isStar":false,"memo":"构词 man(手)+oeuvre(操作，同 operate)→用手调度摆布→机动动作；策略；操纵，控制","example":"He manoeuvred the car into the narrow space. 他巧妙地把车开进了那个狭窄的空位。"},{"id":1072,"unit":4,"lesson":4,"word":"affection","pronunciation":"/əˈfekʃn/","meaning":"n.感情;喜爱;爱情","seq":48,"isStar":false,"memo":"构词 af-(=to) + fect(做) + -ion(名词后缀) → 做某事可能会对其产生“感情”。","example":"People of different ages and genders show affection in different ways. 不同年龄和性别的人表达爱意的方式不同。"},{"id":1073,"unit":4,"lesson":4,"word":"affectionate","pronunciation":"/əˈfekʃənət/","meaning":"adj.表示关爱的","seq":49,"isStar":false},{"id":1074,"unit":4,"lesson":4,"word":"facility","pronunciation":"/fəˈsɪləti/","meaning":"n.设备,设施;天赋,才能","seq":50,"isStar":false,"memo":"构词 facil(e)(容易的) + -ity(名词后缀) → 做事容易的能力 → 天赋，才能","example":"Facilities management has greatly improved in recent years. 近年来，设施管理有了很大改善。"},{"id":1075,"unit":4,"lesson":4,"word":"facilitate","pronunciation":"/fəˈsɪlɪteɪt/","meaning":"v.促进,促使;使便利","seq":51,"isStar":false},{"id":1076,"unit":4,"lesson":4,"word":"facilitation","pronunciation":"/fəˌsɪlɪˈteɪʃn/","meaning":"n.促进","seq":52,"isStar":false},{"id":1077,"unit":4,"lesson":4,"word":"infect","pronunciation":"/ɪnˈfekt/","meaning":"v.传染;影响","seq":53,"isStar":false,"memo":"构词 in-(入) + fect(做→起作用) → 进入（肌体）起作用 → 传染","example":"Once infected, one will become immune to Ebola. 一旦感染，人们就会对埃博拉病毒产生免疫。"},{"id":1078,"unit":4,"lesson":4,"word":"infection","pronunciation":"/ɪnˈfekʃ(ə)n/","meaning":"n.传染;(身体某部位的)感染","seq":54,"isStar":false},{"id":1079,"unit":4,"lesson":4,"word":"infectious","pronunciation":"/ɪnˈfekʃəs/","meaning":"adj.传染性的;感染的","seq":55,"isStar":false},{"id":1080,"unit":4,"lesson":4,"word":"defect","pronunciation":"/ˈdiːfekt/","meaning":"n.缺点,缺陷 v.背叛,叛变","seq":56,"isStar":false,"memo":"联想 de(音似“弟”) + fect(做) → 弟弟年轻，做事不周到，有“缺陷”。","example":"She suffers from a sight defect. 她的视力有缺陷。"},{"id":1081,"unit":4,"lesson":4,"word":"defective","pronunciation":"/dɪˈfektɪv/","meaning":"adj.有缺点的,有缺陷的,有毛病的","seq":57,"isStar":false},{"id":1082,"unit":4,"lesson":4,"word":"effect","pronunciation":"/ɪˈfekt/","meaning":"n.生效;效果 v.实现;引起","seq":58,"isStar":false,"memo":"构词 ef-(出) + fect(做) → 做出来 → 生效；实现","example":"I can certainly feel the effects of too many late nights. 我当然能感觉到熬夜太多产生的影响。"},{"id":1083,"unit":4,"lesson":4,"word":"effective","pronunciation":"/ɪˈfektɪv/","meaning":"adj.有效的;产生预期效果的","seq":59,"isStar":false},{"id":1084,"unit":4,"lesson":4,"word":"void","pronunciation":"/vɔɪd/","meaning":"adj.无效的;缺乏……的 n.空虚感","seq":60,"isStar":false,"memo":"联想 vo(音似“我”) + id(联想“身份”) → 我的身份是“无效的”，这让我有一种“空虚感”。","example":"The agreement was declared void. 该协议被宣布无效。"},{"id":1085,"unit":4,"lesson":4,"word":"fake","pronunciation":"/feɪk/","meaning":"n.假货;骗子 adj.假的 v.伪造","seq":61,"isStar":false,"memo":"谐音 “费克”：花了钱(fee)买到的“名牌”其实是克扣出来的仿货→假货；伪造","example":"All the paintings proved to be fakes. 所有这些画结果证实都是品。"},{"id":1086,"unit":4,"lesson":4,"word":"deceive","pronunciation":"/dɪˈsiːv/","meaning":"v.欺骗;误导","seq":62,"isStar":false,"memo":"[谐音]单词发音类似“弟媳妇”→这部电影里,主角的弟媳妇是个骗子,“欺骗”了弟弟。","example":"If he deceives the world, the world often deceives him. 如果他欺骗世人,那世人往往也会欺骗他。"},{"id":1087,"unit":4,"lesson":4,"word":"deceit","pronunciation":"/dɪˈsiːt/","meaning":"n.欺骗;欺诈","seq":63,"isStar":false},{"id":1088,"unit":4,"lesson":4,"word":"deception","pronunciation":"/dɪˈsepʃn/","meaning":"n.欺骗(行为)","seq":64,"isStar":false},{"id":1089,"unit":4,"lesson":4,"word":"deceptive","pronunciation":"/dɪˈseptɪv/","meaning":"adj.欺骗性的;误导的","seq":65,"isStar":false},{"id":1090,"unit":4,"lesson":4,"word":"perceive","pronunciation":"/pəˈsiːv/","meaning":"v.看待;察觉,发觉","seq":66,"isStar":false,"memo":"[谐音]单词发音类似“破媳妇”→他想破坏媳妇的计划,被媳妇“察觉”到了。","example":"I perceived a change in his behaviour. 我注意到他的举止有些改变。"},{"id":1091,"unit":4,"lesson":4,"word":"perception","pronunciation":"/pəˈsepʃ(ə)n/","meaning":"n.知觉;感知;洞察力;认识,看法","seq":67,"isStar":false},{"id":1092,"unit":4,"lesson":4,"word":"perceptive","pronunciation":"/pəˈseptɪv/","meaning":"adj.理解力强的;有洞察力的","seq":68,"isStar":false},{"id":1093,"unit":4,"lesson":4,"word":"conceive","pronunciation":"/kənˈsiːv/","meaning":"v.设想,构思;怀孕","seq":69,"isStar":false,"memo":"[联想] con-(一起) + ceive(音似“媳妇”)→他和媳妇一起“设想”着“怀孕”生子的美好生活。","example":"I cannot conceive what it must be like. 我设想不出它会是什么样子。"},{"id":1094,"unit":4,"lesson":4,"word":"conception","pronunciation":"/kənˈsepʃ(ə)n/","meaning":"n.构思,设想;概念","seq":70,"isStar":false,"memo":"[对照] conceive v.设想→conception n.","example":"I had to reassess my conception that she was basically an honest person. 我不得不重新评估我的想法,她基本上是一个诚实的人。"},{"id":1095,"unit":4,"lesson":4,"word":"detect","pronunciation":"/dɪˈtekt/","meaning":"v.发现;查明;侦察出","seq":71,"isStar":false,"memo":"[联想] de-(往下) + tect(音似“探个它”)→向地下钻孔勘探是为了“查明”地层构造。","example":"The tests are designed to detect the disease early. 这些检查旨在早查出疾病。"},{"id":1096,"unit":4,"lesson":4,"word":"detection","pronunciation":"/dɪˈtekʃ(ə)n/","meaning":"n.探测;察觉;发现","seq":72,"isStar":false},{"id":1097,"unit":4,"lesson":4,"word":"detective","pronunciation":"/dɪˈtektɪv/","meaning":"n.侦探;警探;私人侦探","seq":73,"isStar":false},{"id":1098,"unit":4,"lesson":4,"word":"scout","pronunciation":"/skaʊt/","meaning":"n.侦察员;侦察机(舰) v.搜索,侦察","seq":74,"isStar":false,"memo":"[联想] sc(联想“死看”) + out(出去)→侦察","example":"Scouts are trained to navigate through the forest. 侦察员被训练穿越森林。"},{"id":1099,"unit":4,"lesson":4,"word":"appeal","pronunciation":"/əˈpiːl/","meaning":"n.呼吁,恳求;上诉 v.有吸引力;呼吁","seq":75,"isStar":false,"memo":"[联想] ap-(= to) + peal(音同 peel,剥皮)→古代有些贪官污吏被抓起来后，百姓会“恳求”官府将之剥皮。","example":"An appeal is being made for help for those who lost their homes in the earthquake. 人们正在呼吁大家援助那些在地震中失去家园的人。"},{"id":1100,"unit":4,"lesson":4,"word":"appealing","pronunciation":"/əˈpiːlɪŋ/","meaning":"adj.有吸引力的,令人感兴趣的;恳求的","seq":76,"isStar":false},{"id":1101,"unit":4,"lesson":4,"word":"appal(l)","pronunciation":"/əˈpɔːl/","meaning":"v.使大为震惊,使惊骇","seq":77,"isStar":false,"memo":"联想 a(-) + (p)pal(音似“炮”)→春节一放鞭炮,婴儿就会被吓着→使惊骇","example":"I was appalled by his behaviour.我对他的行为感到震惊。"},{"id":1102,"unit":4,"lesson":4,"word":"appalling","pronunciation":"/əˈpɔːlɪŋ/","meaning":"adj.令人震惊的;极为恶劣的","seq":78,"isStar":false},{"id":1103,"unit":4,"lesson":4,"word":"accuse","pronunciation":"/əˈkjuːz/","meaning":"v.控告,控诉;谴责","seq":79,"isStar":false,"memo":"[联想] ac-(一再地) + cuse(联想 curse,诅咒)→一再地诅咒他人这种行为应受“谴责”。","example":"He was accused of family violence. 他被指控家庭暴力。"},{"id":1104,"unit":4,"lesson":4,"word":"accusation","pronunciation":"/ˌækjuˈzeɪʃ(ə)n/","meaning":"n.控告,起诉;告发;谴责","seq":80,"isStar":false},{"id":1105,"unit":4,"lesson":4,"word":"blame","pronunciation":"/bleɪm/","meaning":"v.责备,责怪;把……归咎于 n.责任","seq":81,"isStar":false,"memo":"[联想] b(音似“不”) + la(联想“拉”) + me(我)→一旦弟弟在马路上乱跑，不想拉着我，我就会“责备”他。","example":"Police are blaming the accident on dangerous driving. 警方把事故原因归咎于危险驾驶。"},{"id":1106,"unit":4,"lesson":4,"word":"verdict","pronunciation":"/ˈvɜːdɪkt/","meaning":"n.(法庭作出的)裁定,裁决;决定;意见","seq":82,"isStar":false,"memo":"[谐音] 单词发音类似“我抵抗它”→我对“裁决”不服，想提起诉讼进行抵抗。","example":"The jury’s verdict went against him. 陪审团的裁决对他不利。"},{"id":1107,"unit":4,"lesson":4,"word":"convict","pronunciation":"/kənˈvɪkt/","meaning":"v.定罪,证明……有罪 n.已决犯","seq":83,"isStar":false,"memo":"[联想] con-(共同) + vi(形似罗马数字 6) + ct(联想“剋他”)→六个人都剋(打)了他，证明这六个人都有罪→证明……有罪","example":"He was convicted of fraud. 他被判定犯有诈骗罪。"},{"id":1108,"unit":4,"lesson":4,"word":"conviction","pronunciation":"/kənˈvɪkʃn/","meaning":"n.判罪;坚定的信念","seq":84,"isStar":false},{"id":1109,"unit":4,"lesson":4,"word":"indict","pronunciation":"/ɪnˈdaɪt/","meaning":"v.控告,起诉","seq":85,"isStar":false,"memo":"in(里面)+dict(说)→咱们进法庭里说,我要“控告”你。","example":"They were indicted on a number of corruption charges. 他们被控多项贪腐罪名。"},{"id":1110,"unit":4,"lesson":4,"word":"indictment","pronunciation":"/ɪnˈdaɪtmənt/","meaning":"n.控告;衰败迹象","seq":86,"isStar":false},{"id":1111,"unit":4,"lesson":4,"word":"guilt","pronunciation":"/ɡɪlt/","meaning":"n.内疚;犯罪,罪行","seq":87,"isStar":false,"memo":"谐音 “鬼偶特”：心里有鬼才会不安→内疚；犯罪，罪行","example":"They seem to be quite accustomed to such waste and don’t have a feeling of guilt.他们似乎对这样的浪费习以为常，毫无愧疚感。"},{"id":1112,"unit":4,"lesson":4,"word":"guilty","pronunciation":"/ˈɡɪlti/","meaning":"adj.内疚的;有罪的","seq":88,"isStar":false},{"id":1113,"unit":4,"lesson":4,"word":"crime","pronunciation":"/kraɪm/","meaning":"n.犯罪,犯罪行为","seq":89,"isStar":false,"memo":"cri(音同 cry)+me(我)→那个罪犯被审判的时候向我痛哭流涕,悔恨他的“犯罪行为”。","example":"Stores spend more and more on crime prevention. 商店在防止犯罪方面的花费越来越多。"},{"id":1114,"unit":4,"lesson":4,"word":"criminal","pronunciation":"/ˈkrɪmɪn(ə)l/","meaning":"n.罪犯,犯罪者 adj.犯罪的,犯法的","seq":90,"isStar":false},{"id":1115,"unit":4,"lesson":4,"word":"discriminate","pronunciation":"/dɪˈskrɪmɪneɪt/","meaning":"v.区分,辨别;歧视,偏袒","seq":91,"isStar":false,"memo":"dis-(分开)+crimin(区别)+-ate(动词后缀)→区分,辨别","example":"Newborn babies can discriminate between a man's and a woman's voice. 新生儿能辨别男人和女人的声音。"},{"id":1116,"unit":4,"lesson":4,"word":"discrimination","pronunciation":"/dɪˌskrɪmɪˈneɪʃn/","meaning":"n.区别对待;歧视;辨别力","seq":92,"isStar":false},{"id":1117,"unit":4,"lesson":4,"word":"discriminatory","pronunciation":"/dɪˈskrɪmɪnətəri/","meaning":"adj.区别对待的;不公正的;歧视的","seq":93,"isStar":false},{"id":1118,"unit":4,"lesson":4,"word":"prison","pronunciation":"/ˈprɪz(ə)n/","meaning":"n.监狱,牢笼;监禁","seq":94,"isStar":false,"memo":"构词 pris(抓住，同 prize 缴获)+-on(名词后缀)→把人抓住关起来的地方→监狱，牢笼；监禁","example":"He was sent to prison for five years. 他被关押了五年。"},{"id":1119,"unit":4,"lesson":4,"word":"prisoner","pronunciation":"/ˈprɪz(ə)nə(r)/","meaning":"n.囚犯,犯人;羁押候审者","seq":95,"isStar":false},{"id":1120,"unit":4,"lesson":4,"word":"imprison","pronunciation":"/ɪmˈprɪzn/","meaning":"v.监禁,关押;束缚","seq":96,"isStar":false,"memo":"im-(= in,入)+prison(监狱)→监禁;关押","example":"He was wrongly imprisoned. 他被判入狱是冤枉的。"},{"id":1121,"unit":4,"lesson":4,"word":"imprisonment","pronunciation":"/ɪmˈprɪznmənt/","meaning":"n.监禁","seq":97,"isStar":false},{"id":1122,"unit":4,"lesson":4,"word":"blackmail","pronunciation":"/ˈblækmeɪl/","meaning":"n.&v.勒索,敲诈;胁迫","seq":98,"isStar":false,"memo":"black(黑色的)+mail(邮件)→黑色的邮件不要打开,可能被“敲诈”。","example":"She says she was virtually blackmailed into giving up her claim to the property. 她说自己实际上是受人胁迫而放弃了财产所有权。"},{"id":1123,"unit":4,"lesson":4,"word":"kidnap","pronunciation":"/ˈkɪdnæp/","meaning":"v.&n.劫持;绑架","seq":99,"isStar":false,"memo":"kid(孩子) + nap(音似“奶扑”)→孩子被“绑架”后,奶奶扑向匪徒。","example":"He was kidnapped eight months ago.他八个月前被绑架了。"},{"id":1124,"unit":4,"lesson":4,"word":"hijack","pronunciation":"/ˈhaɪdʒæk/","meaning":"v.劫持;操纵","seq":100,"isStar":false,"memo":"联想 源自劫匪喊“Hi, Jack!”引人开窗/开门的黑话→劫持；操纵","example":"The airliner was hijacked by a group of terrorists. 该客机被一帮恐怖分子劫持。"},{"id":1125,"unit":4,"lesson":4,"word":"hack","pronunciation":"/hæk/","meaning":"n.砍,劈;入侵 v.砍,劈","seq":101,"isStar":false,"memo":"谐音 单词发音类似“黑客”→电脑黑客就是“非法侵入”他人计算机系统的人。","example":"The order essentially asks Apple to hack its own devices. 该命令本质上是要求苹果公司入侵自己的设备。"},{"id":1126,"unit":4,"lesson":4,"word":"hacker","pronunciation":"/ˈhækə(r)/","meaning":"n.黑客","seq":102,"isStar":false},{"id":1127,"unit":4,"lesson":4,"word":"database","pronunciation":"/ˈdeɪtəbeɪs/","meaning":"n.(储存在计算机中的)数据库","seq":103,"isStar":false,"memo":"记 (构词) data(数据) + base(基础)→数据库","example":"This information is combined with a map database.这些信息与地图数据库相结合。"},{"id":1128,"unit":4,"lesson":4,"word":"smuggle","pronunciation":"/ˈsmʌɡ(ə)l/","meaning":"v.走私,偷运","seq":104,"isStar":false,"memo":"谐音 单词发音类似“私马哥”→“走私”马匹的哥哥被逮捕了。","example":"He was caught smuggling diamonds into the country. 他走私钻石入境时被发现了。"},{"id":1129,"unit":4,"lesson":4,"word":"smuggler","pronunciation":"/ˈsmʌɡ(ə)lə(r)/","meaning":"n.走私者","seq":105,"isStar":false},{"id":1130,"unit":4,"lesson":4,"word":"smuggling","pronunciation":"/ˈsmʌɡlɪŋ/","meaning":"n.走私(罪)","seq":106,"isStar":false},{"id":1131,"unit":4,"lesson":4,"word":"rob","pronunciation":"/rɒb/","meaning":"v.抢劫,掠夺;盗取","seq":107,"isStar":false,"memo":"谐音 单词发音类似“弱不”→弱不禁风的她遭到了“抢劫”。","example":"The tomb has been robbed of its treasures. 这座坟墓里的财宝早已被盗。"},{"id":1132,"unit":4,"lesson":4,"word":"robbery","pronunciation":"/ˈrɒbəri/","meaning":"n.盗窃;抢劫,掠夺","seq":108,"isStar":false},{"id":1133,"unit":4,"lesson":4,"word":"grab","pronunciation":"/ɡræb/","meaning":"n.抓取;抢夺 v.抓住;攫取","seq":109,"isStar":false,"memo":"联想 g(联想“哥”) + rab(联想 rob) → 抢劫哥哥的人被“抓住”了。","example":"You should grab this chance. 你应该抓住这次机会。"},{"id":1134,"unit":4,"lesson":4,"word":"snatch","pronunciation":"/snætʃ/","meaning":"n.抓;抢夺 v.一把抓起;一下夺过","seq":110,"isStar":false,"memo":"谐音 单词发音类似“死拿吃”→拼死也要拿来吃→抢夺","example":"She managed to snatch the gun from his hand. 她设法从他手里夺过了枪。"},{"id":1135,"unit":4,"lesson":4,"word":"snap","pronunciation":"/snæp/","meaning":"n.(尤指关上或断裂的声音)啪嗒声","seq":111,"isStar":false,"memo":"谐音 单词发音类似“四男扑”→四个小男孩突然扑过去抢木棍,把木棍弄断了→仓促的;使断裂","example":"After she snapped a photo and started using her phone, he asked her a serious question. 在她拍了一张照片并开始看手机后,他问了她一个严肃的问题。"},{"id":1136,"unit":4,"lesson":4,"word":"penalty","pronunciation":"/ˈpenəlti/","meaning":"n.惩罚,处罚;害处","seq":112,"isStar":false,"memo":"联想 pena (音似“拍那”) + l + ty (音似“提”) → 这架飞机上是不允许拍这拍那的,经提醒后不改的乘客会受到“处罚”。","example":"The penalty for travelling without a ticket is £200. 无票乘车的罚款为 200 英镑。"},{"id":1137,"unit":4,"lesson":4,"word":"penalise/-ize","pronunciation":"/ˈpiːnəlaɪz/","meaning":"v.惩罚,(体育运动中的)判罚","seq":113,"isStar":false,"memo":"构词 penal(惩罚，同 penalty 处罚)+-ise/-ize(使…化)→使受到处罚→惩罚，判罚","example":"Players who cheat will be penalised. 作弊的球员将被判罚。"},{"id":1138,"unit":4,"lesson":4,"word":"sue","pronunciation":"/suː/","meaning":"v.控告;提起诉讼","seq":114,"isStar":false,"memo":"谐音 单词发音类似“诉”→提起诉讼","example":"These injured workers could sue for damages in a court of law. 这些受伤的工人可以在法庭上提起赔偿诉讼。"},{"id":1139,"unit":4,"lesson":4,"word":"ensue","pronunciation":"/ɪnˈsjuː/","meaning":"v.接着发生;因而产生","seq":115,"isStar":false,"memo":"联想 en-(使)+sue(提起诉讼)→他提起诉讼后,“接着发生”了很多事情。","example":"An argument ensued. 紧接着的是一场争论。"},{"id":1140,"unit":4,"lesson":4,"word":"lawsuit","pronunciation":"/ˈlɔːsuːt/","meaning":"n.诉讼,起诉","seq":116,"isStar":false,"memo":"构词 law(法律)+suit(诉讼)→依法提起的诉讼→诉讼，起诉","example":"His lawyer filed a lawsuit against the airline. 他的律师对该航空公司提起了诉讼。"},{"id":1141,"unit":4,"lesson":4,"word":"prove","pronunciation":"/pruːv/","meaning":"v.证明,证实;显示","seq":117,"isStar":false,"memo":"联想 pro-(向前)+ve(音似“五”)→要向前推进这件事,需要先“证实”这五点。","example":"What are you trying to prove? 你想证明什么?"},{"id":1142,"unit":4,"lesson":4,"word":"proof","pronunciation":"/pruːf/","meaning":"n.证据;证明 adj.能抵御的","seq":118,"isStar":false,"memo":"对照 prove v.证明→proof n.&adj.&v.","example":"So far, there is little proof one way or the other.到目前为止，无论哪种说法都几乎没有证据。"},{"id":1143,"unit":4,"lesson":4,"word":"approve","pronunciation":"/əˈpruːv/","meaning":"v.赞成,同意;批准","seq":119,"isStar":false,"memo":"构词 ap-(=to)+prove(证明)→对……出具证明→赞成,批准","example":"Do you approve of my idea? 你赞成我的想法吗?"},{"id":1144,"unit":4,"lesson":4,"word":"approval","pronunciation":"/əˈpruːv(ə)l/","meaning":"n.赞成,同意;批准","seq":120,"isStar":false},{"id":1145,"unit":4,"lesson":4,"word":"sanction","pronunciation":"/ˈsæŋkʃn/","meaning":"n.批准,同意;制裁 v.批准,同意","seq":121,"isStar":false,"memo":"联想 sanc(音似“赛课”)+tion(名词后缀)→学校里开展课程比赛要经过校领导的“批准”。","example":"The economic sanctions have been lifted. 经济制裁已被解除。"},{"id":1146,"unit":4,"lesson":4,"word":"testimony","pronunciation":"/ˈtestɪməni/","meaning":"n.证据;(尤指法庭上的)证词","seq":122,"isStar":false,"memo":"联想 test(检验)+i+mony(音似“摸你”)→我摸你的衣兜是为了检验他的“证词”是否正确。","example":"This increase in exports bears testimony to the successes of industry. 出口增长证明了产业的成功。"},{"id":1147,"unit":4,"lesson":4,"word":"testify","pronunciation":"/ˈtestɪfaɪ/","meaning":"v.(尤指出席)作证,证明","seq":123,"isStar":false,"memo":"testi（test测试/证据）+fy（使…）→‘使成证据’！法庭上举手说‘I swear to tell the truth’就是在用生命‘作证’，test=试真伪，fy=搞定。","example":"She testified that she saw the suspect near the scene. 她作证称曾在案发现场附近看到嫌疑人。"},{"id":1148,"unit":4,"lesson":4,"word":"witness","pronunciation":"/ˈwɪtnəs/","meaning":"n.证人,目击者;证据 v.目击","seq":124,"isStar":false,"memo":"对照:证人(witness)需要有一定的智力(wit)水平。","example":"Many factors influence the accuracy of witness testimony. 许多因素影响目击者证词的准确性。"},{"id":1149,"unit":4,"lesson":4,"word":"evidence","pronunciation":"/ˈevɪdəns/","meaning":"n.证据;迹象","seq":125,"isStar":false,"memo":"构词:e-(出)+vid(看)+-ence(名词后缀)→(从……中)看得出来的东西→证据;迹象","example":"Have you any evidence to support this allegation? 你有证据支持这种说法吗?"},{"id":1150,"unit":4,"lesson":4,"word":"evident","pronunciation":"/ˈevɪdənt/","meaning":"adj.明显的,显然的","seq":126,"isStar":false,"memo":"构词：e-（出）+ vid-（看，如video）+ -ent→一眼‘看出’来的东西，就是‘明显的’！Evident=eye-vident！","example":"It is evident that climate change affects agricultural output. 显然，气候变化影响农业产量。"},{"id":1151,"unit":4,"lesson":4,"word":"rebel","pronunciation":"/ˈreb(ə)l; rɪˈbel/","meaning":"n.反叛者 v.造反;反抗;背叛","seq":127,"isStar":false,"memo":"联想:re-(再次)+bel(联想bell)→警铃再次响了,警察抓到了反复闹事的“反叛者”。","example":"The teenager finds something to rebel against. 那个青少年有反抗意识。"},{"id":1152,"unit":4,"lesson":4,"word":"rebellion","pronunciation":"/rɪˈbeljən/","meaning":"n.叛乱;反抗","seq":128,"isStar":false},{"id":1153,"unit":4,"lesson":4,"word":"rebellious","pronunciation":"/rɪˈbeljəs/","meaning":"adj.反叛的;桀骜不驯的","seq":129,"isStar":false},{"id":1154,"unit":4,"lesson":4,"word":"sequence","pronunciation":"/ˈsiːkwəns/","meaning":"n.一系列;顺序,次序 v.按顺序排列","seq":130,"isStar":false,"memo":"联想 set(联想 see) + quen(联想 queen) + ce(走)→他看见女王后面的人在有“顺序”地排队往前走。","example":"Spider-Man is a sequence of stories.《蜘蛛侠》是系列故事。"},{"id":1155,"unit":4,"lesson":4,"word":"sequential","pronunciation":"/sɪˈkwenʃ(ə)l/","meaning":"adj.按次序的,顺序的;序列的","seq":131,"isStar":false},{"id":1156,"unit":4,"lesson":4,"word":"consequence","pronunciation":"/ˈkɒnsɪkwəns/","meaning":"n.结果,后果;重要性","seq":132,"isStar":false,"memo":"构词 con-(一起) + sequence(连续)→一起连续发生的事→结果","example":"Focusing on output alone can have unintended consequences. 只关注产出可能会产生意想不到的后果。"},{"id":1157,"unit":4,"lesson":4,"word":"consequent","pronunciation":"/ˈkɒnsɪkwənt/","meaning":"adj.随之发生的;作为结果的","seq":133,"isStar":false,"memo":"【构词】con-(一起)+sequ-(跟随)+ent→事情一跟到底→自然随之而来的结果。","example":"Heavy rainfall was a consequent cause of the widespread flooding. 大雨是此次大面积洪涝的直接原因。"},{"id":1158,"unit":4,"lesson":4,"word":"consequently","pronunciation":"/ˈkɒnsɪkwəntli/","meaning":"adv.因此,所以","seq":134,"isStar":false},{"id":1159,"unit":4,"lesson":4,"word":"subsequent","pronunciation":"/ˈsʌbsɪkwənt/","meaning":"adj.随后的;后来的","seq":135,"isStar":false,"memo":"构词 sub-(下面) + sequent(连续的)→下面连续的→随后的;后来的","example":"More on this study will appear in a subsequent post. 关于这项研究的更多信息将出现在随后的帖子中。"},{"id":1160,"unit":4,"lesson":4,"word":"judge","pronunciation":"/dʒʌdʒ/","meaning":"n.法官;裁判员;鉴定人 v.判断,断定","seq":136,"isStar":false,"memo":"构词 jud(判断，同 judicial 司法的)+-ge→做出判断的人→法官；裁判员；判断","example":"The judge reversed his original decision. 法官推翻了他原来的判决。"},{"id":1161,"unit":4,"lesson":4,"word":"judg(e)ment","pronunciation":"/ˈdʒʌdʒmənt/","meaning":"n.判断力;看法;裁决","seq":137,"isStar":false,"memo":"构词 judg(判断)+-ment(名词后缀)→判断的结果→判断力；看法；裁决","example":"I trust her judgement on this matter. 在这件事上我相信她的判断。"},{"id":1162,"unit":4,"lesson":4,"word":"judicial","pronunciation":"/dʒuːˈdɪʃəl/","meaning":"adj.审判的;法庭的,法官的;司法的","seq":138,"isStar":false,"memo":"构词 jud(判断)+-icial(形容词后缀)→与审判相关的→审判的，法庭的，司法的","example":"The judicial system has much room for improvement.司法制度还有很大的改进空间。"},{"id":1163,"unit":4,"lesson":4,"word":"justice","pronunciation":"/ˈdʒʌstɪs/","meaning":"n.公平;正义;司法制度;审判","seq":139,"isStar":false,"memo":"构词 just(公正的) + -ice(名词后缀)→公平;正义","example":"Children often have a highly developed sense of justice. 孩子们通常有高度发达的正义感。"},{"id":1164,"unit":4,"lesson":4,"word":"justify","pronunciation":"/ˈdʒʌstɪfaɪ/","meaning":"v.证明……是正当的;为……辩护","seq":140,"isStar":false,"memo":"构词 just(公正的) + -ify(动词后缀)→使公正→证明……是正当的","example":"He must justify the arrests he makes of criminals. 他必须证明他逮捕罪犯是正当的。"},{"id":1165,"unit":4,"lesson":4,"word":"justification","pronunciation":"/ˌdʒʌstɪfɪˈkeɪʃ(ə)n/","meaning":"n.正当理由","seq":141,"isStar":false,"memo":"构词 just(正当的)+-ific+-ation(名词后缀)→使之显得正当的理由→正当理由","example":"There is no justification for such rudeness. 这种粗鲁毫无道理可言。"},{"id":1166,"unit":4,"lesson":4,"word":"adjust","pronunciation":"/əˈdʒʌst/","meaning":"v.适应;调整,调节;(使)习惯","seq":142,"isStar":false,"memo":"构词 ad-(= to) + just (正好) → 使……达到正好→调整","example":"America is a competitive society; the kids need to adjust to that. 美国是一个竞争激烈的社会；孩子们需要适应这一点。"},{"id":1167,"unit":4,"lesson":4,"word":"adjustment","pronunciation":"/əˈdʒʌstmənt/","meaning":"n.调整,调节;适应","seq":143,"isStar":false},{"id":1168,"unit":4,"lesson":4,"word":"court","pronunciation":"/kɔːt/","meaning":"n.法院,法庭;球场 v.讨好,争取","seq":144,"isStar":false,"memo":"构词 cour(围起来的地方，同 courtyard 庭院)+-t→围起来审案的地方→法院，法庭；球场；讨好","example":"Some witnesses failed to appear in court. 一些证人未能出庭。"},{"id":1169,"unit":4,"lesson":4,"word":"courtesy","pronunciation":"/ˈkɜːtəsi/","meaning":"n.礼貌","seq":145,"isStar":false,"memo":"联想 court(法庭) + (e)sy(音似 say) → 他在法庭上讲话时很有“礼貌”。","example":"My job title made people treat me with courtesy. 我的职位头衔让人们对我以礼相待。"},{"id":1170,"unit":4,"lesson":4,"word":"jury","pronunciation":"/ˈdʒʊəri/","meaning":"n.陪审团","seq":146,"isStar":false,"memo":"构词 jur(发誓，同 juror 陪审员)+-y(名词后缀)→宣过誓的一群人→陪审团","example":"The defending lawyer made a great impression on the jury. 辩护律师给陪审团留下了深刻的印象。"},{"id":1171,"unit":4,"lesson":4,"word":"juror","pronunciation":"/ˈdʒʊərə(r)/","meaning":"n.陪审团成员;陪审员","seq":147,"isStar":false},{"id":1172,"unit":4,"lesson":4,"word":"judiciary","pronunciation":"/dʒuˈdɪʃəri/","meaning":"n.审判人员;司法部门;司法系统","seq":148,"isStar":false,"memo":"构词 judic(i)(判断,审判)+-ary(名词后缀)→审判人员;司法部门;司法系统","example":"The independence of the judiciary is essential for a just society.司法独立对一个公正的社会至关重要。"},{"id":1173,"unit":4,"lesson":4,"word":"jurisdiction","pronunciation":"/ˌdʒʊərɪsˈdɪkʃn/","meaning":"n.司法权,审判权;管辖权,管辖范围","seq":149,"isStar":false,"memo":"构词 juris(法律)+dict(说,宣称)+-ion (名词后缀)→依据法律宣称或判断的权力范围→司法权","example":"These matters do not fall within our jurisdiction.这些事务不属于我们的管辖范围。"},{"id":1174,"unit":4,"lesson":4,"word":"outlaw","pronunciation":"/ˈaʊtlɔː/","meaning":"v.宣布……不合法","seq":150,"isStar":false,"memo":"构词 out(在……之外,超出)+law(法律) →超出法律允许范围→宣布……不合法;逃犯","example":"Commercial whaling has been outlawed by international agreement.国际协议已禁止商业捕鲸。"},{"id":1175,"unit":4,"lesson":4,"word":"attorney","pronunciation":"/əˈtɜːni/","meaning":"n.律师;代理人","seq":151,"isStar":false,"memo":"谐音 单词发音类似“额托你”→在遇到法律难题时，他着急地对一位“律师”说：“额（我）把这件事托付给你了。”","example":"Acting on the advice of his attorney, he remained silent. 按照律师的建议，他保持了沉默。"},{"id":1176,"unit":4,"lesson":4,"word":"entrust","pronunciation":"/ɪnˈtrʌst/","meaning":"v.委托,托付","seq":152,"isStar":false,"memo":"构词 en-(使)+trust(信任)→使……处于被信任的状态→委托,托付","example":"He entrusted the task to his nephew.他把任务托付给了他的侄子。"},{"id":1177,"unit":4,"lesson":4,"word":"trial","pronunciation":"/ˈtraɪəl/","meaning":"n.审判;试验,试用 v.测试,试验","seq":153,"isStar":false,"memo":"对照 审判(trial)就是在试图(try)确定被告人有罪。","example":"We learn, in a sense, by trial and error. 从某种意义上说，我们是通过反复实验来学习的。"},{"id":1178,"unit":4,"lesson":4,"word":"condemn","pronunciation":"/kənˈdem/","meaning":"v.谴责;宣判;证明……有罪","seq":154,"isStar":false,"memo":"联想 con-(所有的) + demn(音似 damn,骂)→所有人都骂他,“谴责”他。","example":"The president condemns their greed. 总统谴责了他们的贪婪。"},{"id":1179,"unit":4,"lesson":4,"word":"condemnation","pronunciation":"/ˌkɒndemˈneɪʃ(ə)n/","meaning":"n.谴责;指责","seq":155,"isStar":false},{"id":1180,"unit":4,"lesson":4,"word":"warrant","pronunciation":"/ˈwɒrənt/","meaning":"n.授权令;许可,正当理由 v.需要","seq":156,"isStar":false,"memo":"联想 war(战争) + r + ant(蚂蚁)→动物大战中,蚂蚁有“授权令”。","example":"Further investigation is clearly warranted. 进一步调查显然是必要的。"},{"id":1181,"unit":4,"lesson":4,"word":"warranty","pronunciation":"/ˈwɒrənti/","meaning":"n.(商品)保用卡,保修单","seq":157,"isStar":false,"memo":"谐音：'沃兰蒂'→'我烂了？它保你！' 保修单就是厂家拍胸脯说'我烂了？它保你！'的契约小纸条。","example":"The laptop comes with a two-year manufacturer's warranty. 这台笔记本附带厂商提供的两年保修服务。"},{"id":1182,"unit":4,"lesson":4,"word":"tenant","pronunciation":"/ˈtenənt/","meaning":"n.房客;租户;佃户","seq":158,"isStar":false,"memo":"联想 ten(十) + ant(蚂蚁)→十个像蚂蚁一样生活忙碌的低收入者是他的“租户”。","example":"The decorating was done by a previous tenant. 装修是一位前房客搞的。"},{"id":1183,"unit":4,"lesson":4,"word":"abundant","pronunciation":"/əˈbʌndənt/","meaning":"adj.大量的,充裕的","seq":159,"isStar":false,"memo":"联想 a(一) + bund(音似“帮的”) + ant(蚂蚁)→一大帮蚂蚁→大量的","example":"It filled its stores with abundant supply of merchandise. 它商店的商品备货充足。"},{"id":1184,"unit":4,"lesson":4,"word":"abundance","pronunciation":"/əˈbʌndəns/","meaning":"n.大量,充裕","seq":160,"isStar":false,"example":"The country has an abundance of natural resources.这个国家拥有丰富的自然资源。"},{"id":1185,"unit":4,"lesson":4,"word":"ample","pronunciation":"/ˈæmpl/","meaning":"adj.足够的,丰裕的;硕大的","seq":161,"isStar":false,"memo":"对照 苹果(apple)在这里并不是稀有水果,大众吃是足够的(ample)。","example":"Let's produce ample food and clothing with our own hands. 让我们用自己的双手生产出足够多的食物和衣服。"},{"id":1186,"unit":4,"lesson":4,"word":"sample","pronunciation":"/ˈsɑːmp(ə)l/","meaning":"n.样本,样品 v.抽样检验;取样;尝试","seq":162,"isStar":false,"memo":"联想 我们要简单(simple)测试一下这批机器的样品(sample)。","example":"Women in our sample tend to over-perceive their weight. 我们样本中的女性往往会过度关注自己的体重。"},{"id":1187,"unit":4,"lesson":4,"word":"scarce","pronunciation":"/skeəs/","meaning":"adj.缺乏的,稀少的","seq":163,"isStar":false,"memo":"联想 与 rare(稀有的)近义；scarce=scar(伤疤)+ce：伤疤少见才显眼→缺乏的，稀少的","example":"Details of the accident are scarce. 事故的详细情况了解不多。"},{"id":1188,"unit":4,"lesson":4,"word":"scarcely","pronunciation":"/ˈskeəsli/","meaning":"adv.勉强;刚;几乎不;简直不","seq":164,"isStar":false},{"id":1189,"unit":4,"lesson":4,"word":"scarcity","pronunciation":"/ˈskeəsəti/","meaning":"n.缺乏,稀少","seq":165,"isStar":false,"memo":"构词 scarc(e)(缺乏的,稀少的)+-ity(名词后缀)→缺乏,稀少","example":"Diamond's price depends almost entirely on their scarcity.钻石的价格几乎完全取决于它们的稀缺性。"},{"id":1190,"unit":4,"lesson":4,"word":"carton","pronunciation":"/ˈkɑːtn/","meaning":"n.(尤指装食品或液体的)硬纸盒,塑料罐","seq":166,"isStar":false,"memo":"联想 car(汽车)+ton(吨)→汽车上拉着一吨“塑料罐”。","example":"He went to the shop for a carton of milk.他去商店买了一盒牛奶。"},{"id":1191,"unit":4,"lesson":4,"word":"scar","pronunciation":"/skɑː(r)/","meaning":"n.伤疤,伤痕 v.在……上结疤","seq":167,"isStar":false,"memo":"联想 s(联想“死”)+car(车)→他从车下死里逃生,但是留下了“伤疤”。","example":"Will the operation leave a scar? 手术会不会留下疤痕?"},{"id":1192,"unit":4,"lesson":4,"word":"quantity","pronunciation":"/ˈkwɒntəti/","meaning":"n.数量;众多","seq":168,"isStar":false,"memo":"构词 quant(多少)+-ity(名词后缀)→可以计出多少→数量；众多","example":"African or small island states produce a very small quantity of emissions. 非洲或小岛屿国家产生的排放量非常少。"},{"id":1193,"unit":4,"lesson":4,"word":"quantitative","pronunciation":"/ˈkwɒntɪtətɪv/","meaning":"adj.数量的;量化的;定量的","seq":169,"isStar":false},{"id":1194,"unit":4,"lesson":4,"word":"quality","pronunciation":"/ˈkwɒləti/","meaning":"n.质量,品质","seq":170,"isStar":false,"memo":"构词 qual(性质，同 qualify 使合格)+-ity(名词后缀)→具备的性质→质量，品质","example":"The quality of air will surely change for the better. 空气质量肯定会变得更好。"},{"id":1195,"unit":4,"lesson":4,"word":"qualitative","pronunciation":"/ˈkwɒlɪtətɪv/","meaning":"adj.质量的;定性的;性质的","seq":171,"isStar":false},{"id":1196,"unit":5,"lesson":1,"word":"ascertain","pronunciation":"/ˌæsəˈteɪn/","meaning":"v.查明,弄清","seq":1,"isStar":false,"memo":"[构词] as-(一再地) + certain(确定)→一再地确定某件事→查明，弄清","example":"We shall probably never be able to ascertain the exact nature of it. 我们可能永远无法弄清它的确切性质。"},{"id":1197,"unit":5,"lesson":1,"word":"certify","pronunciation":"/ˈsɜːtɪfaɪ/","meaning":"v.(尤指书面)证明,证实","seq":2,"isStar":false,"memo":"[联想] cert(联想certain) + -ify(动词后缀) →使确定→证明，证实","example":"The plants must be certified to be virus free. 这些植物必须具备无病毒证明。"},{"id":1198,"unit":5,"lesson":1,"word":"certificate","pronunciation":"/səˈtɪfɪkət/","meaning":"n.证明(书);(毕业)文凭;合格证书","seq":3,"isStar":false,"memo":"[对照] 合格证书(certificate)是能证明(certify)一个人部分能力的东西。","example":"They're in preparation for exams like the Cambridge Certificates. 他们在为剑桥证书等考试做准备。"},{"id":1199,"unit":5,"lesson":1,"word":"certification","pronunciation":"/ˌsɜːtɪfɪˈkeɪʃ(ə)n/","meaning":"n.证明;鉴定","seq":4,"isStar":false},{"id":1200,"unit":5,"lesson":1,"word":"diploma","pronunciation":"/dɪˈpləʊmə/","meaning":"n.文凭课程;毕业文凭","seq":5,"isStar":false,"memo":"构词 di-(二)+ploma(折)→对折的官方文书→文凭，毕业文凭","example":"She is taking a diploma in management studies. 她在攻读管理学文凭课程。"},{"id":1201,"unit":5,"lesson":1,"word":"thesis","pronunciation":"/ˈθiːsɪs/","meaning":"n.论文,毕业论文;论题","seq":6,"isStar":false,"memo":"[联想] the(这,那) + s(联想“蛇”) + i(形似一个人) + s(联想“蛇”)→那个学生写了一篇人与蛇的“论文”。","example":"The basic thesis of the book is fairly simple. 这本书的基本论题相当简单。"},{"id":1202,"unit":5,"lesson":1,"word":"diplomat","pronunciation":"/ˈdɪpləmæt/","meaning":"n.外交官;善于交际的人,圆通的人","seq":7,"isStar":false,"memo":"联想 diploma (毕业文凭) + t (联想“他”)→他拿到毕业文凭以后成了一名“外交官”。","example":"He was the most distinguished diplomat in history.他是历史上最杰出的外交家。"},{"id":1203,"unit":5,"lesson":1,"word":"diplomatic","pronunciation":"/ˌdɪpləˈmætɪk/","meaning":"adj.外交的;有手腕的;圆通的","seq":8,"isStar":false},{"id":1204,"unit":5,"lesson":1,"word":"diplomacy","pronunciation":"/dɪˈpləʊməsi/","meaning":"n.外交;外交技巧;外交手腕","seq":9,"isStar":false},{"id":1205,"unit":5,"lesson":1,"word":"verify","pronunciation":"/ˈverɪfaɪ/","meaning":"v.核实,证实,证明","seq":10,"isStar":false,"memo":"联想 veri(联想 very,恰好的) + fy(联想“反应”)→恰好他反应快,“证明”了自己。","example":"They need the facts to verify the existence of a black hole. 他们需要证实黑洞存在的事实。"},{"id":1206,"unit":5,"lesson":1,"word":"verification","pronunciation":"/ˌverɪfɪˈkeɪʃ(ə)n/","meaning":"n.核实;查对;核准","seq":11,"isStar":false},{"id":1207,"unit":5,"lesson":1,"word":"rectify","pronunciation":"/ˈrektɪfaɪ/","meaning":"v.矫正,纠正,改正","seq":12,"isStar":false,"memo":"联想 rect(联想 correct) + -ify(动词后缀)→使正确→矫正,纠正","example":"I hope that everyone in this class should rectify their errors before it is too late. 我希望这个班上的每个人都能趁早改正他们的错误。"},{"id":1208,"unit":5,"lesson":1,"word":"rectification","pronunciation":"/ˌrektɪfɪˈkeɪʃn/","meaning":"n.纠正","seq":13,"isStar":false},{"id":1209,"unit":5,"lesson":1,"word":"simplify","pronunciation":"/ˈsɪmplɪfaɪ/","meaning":"v.使简化","seq":14,"isStar":false,"memo":"构词 simpl(e)(简单的) + -ify(动词后缀)→使简化","example":"He tried to simplify the story. 他试图简化这个故事。"},{"id":1210,"unit":5,"lesson":1,"word":"simplicity","pronunciation":"/sɪmˈplɪsəti/","meaning":"n.简单;淳朴","seq":15,"isStar":false},{"id":1211,"unit":5,"lesson":1,"word":"simply","pronunciation":"/ˈsɪmpli/","meaning":"adv.仅仅,只,不过;简单地","seq":16,"isStar":false},{"id":1212,"unit":5,"lesson":1,"word":"purify","pronunciation":"/ˈpjʊərɪfaɪ/","meaning":"v.使(某物)洁净,净化","seq":17,"isStar":false,"memo":"构词 pur(e)(纯净的) + -ify(动词后缀)→净化","example":"We use filters to purify the water. 我们用过滤器净化水。"},{"id":1213,"unit":5,"lesson":1,"word":"pure","pronunciation":"/pjʊə(r)/","meaning":"adj.纯的;纯净的;完全的","seq":18,"isStar":false,"memo":"【谐音】‘扑儿’→扑向纯净水！喝一口‘扑儿’——纯得没杂质，连气泡都害羞！","example":"The lab requires pure water for preparing sensitive chemical solutions. 实验室配制敏感化学溶液需用纯水。"},{"id":1214,"unit":5,"lesson":1,"word":"purity","pronunciation":"/ˈpjʊərəti/","meaning":"n.纯洁;纯净;纯粹","seq":19,"isStar":false},{"id":1215,"unit":5,"lesson":1,"word":"crystal","pronunciation":"/ˈkrɪst(ə)l/","meaning":"n.水晶;结晶体 adj.清澈透明的","seq":20,"isStar":false,"memo":"联想 cry(哭) + st(联想 street) + al→那个女孩在街上哭了,眼泪变成了“水晶”。","example":"She wore a delicate crystal necklace. 她戴着一条精致的水晶项链。"},{"id":1216,"unit":5,"lesson":1,"word":"clarify","pronunciation":"/ˈklærəfaɪ/","meaning":"v.澄清,阐明","seq":21,"isStar":false,"memo":"构词 clar(= clear) + -ify(动词后缀)→使清楚→澄清,阐明","example":"Its meaning was finally clarified. 它的意义最终得到了澄清。"},{"id":1217,"unit":5,"lesson":1,"word":"clarification","pronunciation":"/ˌklærəfɪˈkeɪʃn/","meaning":"n.澄清,阐明","seq":22,"isStar":false},{"id":1218,"unit":5,"lesson":1,"word":"clarity","pronunciation":"/ˈklærəti/","meaning":"n.清晰,清楚,明确","seq":23,"isStar":false,"memo":"clari（clear清晰）+ty（状态）→‘清啦！’一声，雾散光来！就像戴眼镜前揉眼喊‘擦亮！’，立马世界高清。","example":"His explanation brought clarity to a complex theory. 他的解释让一个复杂理论变得清晰明了。"},{"id":1219,"unit":5,"lesson":1,"word":"classify","pronunciation":"/ˈklæsɪfaɪ/","meaning":"v.将……分类","seq":24,"isStar":false,"memo":"构词 class(种类,等级) + -ify(动词后缀)→使分类,使等级化→将……归入一类(一个等级)","example":"He objected to classifying parenting as a personal choice. 他反对将养育子女归为个人选择。"},{"id":1220,"unit":5,"lesson":1,"word":"classified","pronunciation":"/ˈklæsɪfaɪd/","meaning":"adj.分类的,归类的","seq":25,"isStar":false},{"id":1221,"unit":5,"lesson":1,"word":"classic","pronunciation":"/ˈklæsɪk/","meaning":"adj.最优秀的,第一流的","seq":26,"isStar":false,"memo":"构词 class(等级)+-ic(形容词后缀)→属最高等级的→第一流的，典型的；经典作品","example":"This novel is a classic of modern literature. 这部小说是现代文学的经典之作。"},{"id":1222,"unit":5,"lesson":1,"word":"classical","pronunciation":"/ˈklæsɪk(ə)l/","meaning":"adj.古典的;经典的;传统的","seq":27,"isStar":false,"memo":"构词 classic(经典的)+-al(形容词后缀)→属于经典传统的→古典的，传统的","example":"She studies classical music at the conservatory. 她在音乐学院学习古典音乐。"},{"id":1223,"unit":5,"lesson":1,"word":"grade","pronunciation":"/ɡreɪd/","meaning":"n.品级;级别;成绩","seq":28,"isStar":false,"memo":"构词 grad(步、等级，同 gradual 逐渐的)+-e→一级一级往上走→等级，年级，成绩","example":"She got good grades in all her subjects. 她各科成绩都很优秀。"},{"id":1224,"unit":5,"lesson":1,"word":"ratify","pronunciation":"/ˈrætɪfaɪ/","meaning":"v.正式批准;使正式生效","seq":29,"isStar":false,"memo":"构词 rat(认定，同 rate 评定)+-ify(使…化)→使正式认定下来→正式批准，使正式生效","example":"Parliament refused to ratify the treaty. 议会拒绝批准该条约。"},{"id":1225,"unit":5,"lesson":1,"word":"ratification","pronunciation":"/ˌrætɪfɪˈkeɪʃ(ə)n/","meaning":"n.正式批准;正式生效","seq":30,"isStar":false,"memo":"构词 ratify(批准)变 y 为 i 加 -cation→批准的行为","example":"The agreement needs ratification by both sides. 该协议需要双方批准。"},{"id":1226,"unit":5,"lesson":1,"word":"rating","pronunciation":"/ˈreɪtɪŋ/","meaning":"n.等级;评分;收视率","seq":31,"isStar":false,"memo":"构词 rate(评定)+-ing(名词后缀)→评定的结果→等级，评分，收视率","example":"The show's ratings have fallen sharply. 这个节目的收视率大幅下降。"},{"id":1227,"unit":5,"lesson":1,"word":"ratio","pronunciation":"/ˈreɪʃiəʊ/","meaning":"n.比率;比例","seq":32,"isStar":false,"memo":"谐音‘瑞求’→你求神拜佛都想‘瑞’（好）运，但命运得看‘比率’！拉丁词根rat-（计算）+ -io（名词后缀），算出来的数就是比例。","example":"The student-to-teacher ratio in this lab is 12 to 1. 这间实验室的师生比为12比1。"},{"id":1228,"unit":5,"lesson":1,"word":"ration","pronunciation":"/ˈræʃ(ə)n/","meaning":"n.配给量;正常量 v.定量供应;配给","seq":33,"isStar":false,"memo":"构词 rat(计算，同 rate)+-ion(名词后缀)→算好了才发放的量→配给量，定量供应","example":"During the war food was rationed. 战争期间食物实行定量供应。"},{"id":1229,"unit":5,"lesson":1,"word":"modify","pronunciation":"/ˈmɒdɪfaɪ/","meaning":"v.更改,改进;修改","seq":34,"isStar":false,"memo":"【构词】mod-（模式，方式）+ -ify（使…化）→ 使方式‘变样’→修改；谐音‘摸迪飞’——摸着迪斯科节奏边跳边改PPT！","example":"The software automatically modifies font size to fit different screen resolutions. 该软件会自动调整字体大小以适配不同屏幕分辨率。"},{"id":1230,"unit":5,"lesson":1,"word":"modification","pronunciation":"/ˌmɒdɪfɪˈkeɪʃ(ə)n/","meaning":"n.修改;改进;改变","seq":35,"isStar":false},{"id":1231,"unit":5,"lesson":1,"word":"alter","pronunciation":"/ˈɔːltə(r)/","meaning":"v.(使)改变,更改","seq":36,"isStar":false,"memo":"【谐音】‘噢特儿’→噢，这事儿得特儿改！v.改变。","example":"The committee voted to alter the original proposal after receiving expert feedback. 委员会收到专家反馈后投票修改原提案。"},{"id":1232,"unit":5,"lesson":1,"word":"alteration","pronunciation":"/ˌɔːltəˈreɪʃ(ə)n/","meaning":"n.改变;变化","seq":37,"isStar":false},{"id":1233,"unit":5,"lesson":1,"word":"alternate","pronunciation":"/ɔːlˈtɜːnət;ˈɔːltəneɪt/","meaning":"n.代替者","seq":38,"isStar":false,"memo":"构词 altern(其他的，同 alternative 可替代的)+-ate→一个接一个轮着来→交替的；代替者","example":"Day alternates with night. 昼夜交替。"},{"id":1234,"unit":5,"lesson":1,"word":"alternative","pronunciation":"/ɔːlˈtɜːnətɪv/","meaning":"n.可供选择的事物 adj.可替代的","seq":39,"isStar":false,"memo":"谐音‘奥特人替他’——超人不在时，奥特人替他上！指可替代的选项。","example":"Students should consider alternative energy sources for their research projects. 学生应在研究项目中考虑替代能源。"},{"id":1235,"unit":5,"lesson":1,"word":"alternatively","pronunciation":"/ɔːlˈtɜːnətɪvli/","meaning":"adv.要不,或者","seq":40,"isStar":false},{"id":1236,"unit":5,"lesson":1,"word":"alternation","pronunciation":"/ˌɔːltəˈneɪʃn/","meaning":"n.交替;轮流","seq":41,"isStar":false,"memo":"构词 altern(交替)+-ation(名词后缀)→交替的状态","example":"The alternation of seasons is caused by the tilt of the earth. 四季交替由地轴的倾斜造成。"},{"id":1237,"unit":5,"lesson":1,"word":"alternately","pronunciation":"/ɔːlˈtɜːnətli/","meaning":"adv.交替出现","seq":42,"isStar":false,"memo":"构词 altern(交替)+-ate+-ly(副词后缀)→交替地，轮流地","example":"The two dancers moved alternately. 两位舞者交替移动。"},{"id":1238,"unit":5,"lesson":1,"word":"vary","pronunciation":"/ˈveəri/","meaning":"v.相异;变化","seq":43,"isStar":false,"memo":"构词 var(不同，同 various 各种各样的)+-y→变得不一样→相异，变化","example":"Prices vary from shop to shop. 各家商店的价格不同。"},{"id":1239,"unit":5,"lesson":1,"word":"variable","pronunciation":"/ˈveəriəb(ə)l/","meaning":"n.变量,可变因素 adj.可变的","seq":44,"isStar":false,"memo":"构词 vari(变化)+-able(可…的)→会变的那一个→变量；可变的","example":"The results depend on several variables. 结果取决于几个变量。"},{"id":1240,"unit":5,"lesson":1,"word":"variant","pronunciation":"/ˈveəriənt/","meaning":"n.变种;变体;变形 adj.不同的","seq":45,"isStar":false,"memo":"构词 vari(变化)+-ant(名词后缀)→变化出来的一支→变种，变体","example":"This is a variant of the same gene. 这是同一基因的一种变体。"},{"id":1241,"unit":5,"lesson":1,"word":"variation","pronunciation":"/ˌveəriˈeɪʃ(ə)n/","meaning":"n.差异;变化;变更","seq":46,"isStar":false,"memo":"构词 vari(变化)+-ation(名词后缀)→变化的幅度与情形→差异，变更","example":"There is wide variation in price. 价格差异很大。"},{"id":1242,"unit":5,"lesson":1,"word":"shift","pronunciation":"/ʃɪft/","meaning":"v.转移,转变 n.转变;(轮班或换)班","seq":47,"isStar":false,"memo":"联想 键盘上的 Shift 键就是用来“切换”大小写的→转移，转变；(轮)班","example":"He shifted the bag to his other shoulder. 他把包换到了另一边肩上。"},{"id":1243,"unit":5,"lesson":1,"word":"draft","pronunciation":"/drɑːft/","meaning":"n.草稿,草案,草图 v.起草,草拟","seq":48,"isStar":false,"memo":"联想 与 draw(拉、画)同源：先把线条“拉”出来的版本→草稿，草案；起草","example":"She drafted a letter of complaint. 她起草了一封投诉信。"},{"id":1244,"unit":5,"lesson":1,"word":"bill","pronunciation":"/bɪl/","meaning":"n.账单;议案,法案;票据","seq":49,"isStar":false,"memo":"联想 与 bull(正式诏书)同源：盖了章的正式文书→账单；议案，法案","example":"The bill for the meal came to fifty pounds. 这顿饭的账单共计50英镑。"},{"id":1245,"unit":5,"lesson":1,"word":"mend","pronunciation":"/mend/","meaning":"v.修理;缝补","seq":50,"isStar":false,"memo":"联想 与 amend(修正)同源，去掉前缀 a- 就是“修补”→修理，缝补","example":"He mended the broken chair. 他修好了那把破椅子。"},{"id":1246,"unit":5,"lesson":1,"word":"amend","pronunciation":"/əˈmend/","meaning":"v.修正,修订(法律文件、声明等)","seq":51,"isStar":false,"memo":"a-men-d：‘阿门，得改！’——祈祷后立刻修订错误，超有画面感！","example":"The committee voted to amend the outdated regulation. 委员会投票修改了过时的规定。"},{"id":1247,"unit":5,"lesson":1,"word":"amendment","pronunciation":"/əˈmendmənt/","meaning":"n.(法律、文件的)改动,修正,修订","seq":52,"isStar":false},{"id":1248,"unit":5,"lesson":1,"word":"commend","pronunciation":"/kəˈmend/","meaning":"v.(尤指公开地)赞扬,表扬;推荐,举荐","seq":53,"isStar":false,"memo":"【构词】com-（一起）+ mend-（思考，源自mind）→ ‘用心一起想’谁值得夸→赞扬；谐音‘肯门德’——肯德基门德老师，超赞！","example":"The dean commended the student for her outstanding contribution to campus sustainability. 校长表扬该生为校园可持续发展作出的杰出贡献。"},{"id":1249,"unit":5,"lesson":1,"word":"commendation","pronunciation":"/ˌkɒmenˈdeɪʃn/","meaning":"n.赞扬,称赞;奖励","seq":54,"isStar":false},{"id":1250,"unit":5,"lesson":1,"word":"recommend","pronunciation":"/ˌrekəˈmend/","meaning":"v.推荐,举荐;建议,劝告","seq":55,"isStar":false,"memo":"【谐音+构词】‘瑞可门德’——瑞（re-再）+可（com-一起）+门德（mend=建议），再一起给建议，就是推荐！","example":"The professor recommended this textbook for advanced linguistics. 教授为高级语言学课程推荐了这本教材。"},{"id":1251,"unit":5,"lesson":1,"word":"recommendation","pronunciation":"/ˌrekəmenˈdeɪʃn/","meaning":"n.正式建议,提议;推荐,介绍","seq":56,"isStar":false},{"id":1252,"unit":5,"lesson":1,"word":"amplify","pronunciation":"/ˈæmplɪfaɪ/","meaning":"v.放大,增强(声音等)","seq":57,"isStar":false,"memo":"构词 ampl(大，同 ample 充足的)+-ify(使…化)→使变大→放大，增强；充实","example":"The speakers amplified the sound. 扬声器把声音放大了。"},{"id":1253,"unit":5,"lesson":1,"word":"amplification","pronunciation":"/ˌæmplɪfɪˈkeɪʃn/","meaning":"n.扩大;充实","seq":58,"isStar":false,"memo":"构词 ampl(大)+-ific+-ation(名词后缀)→放大的过程","example":"The amplification made every whisper audible. 放大之后每一声低语都听得见。"},{"id":1254,"unit":5,"lesson":1,"word":"qualify","pronunciation":"/ˈkwɒlɪfaɪ/","meaning":"v.取得资格(或学历);使合格","seq":59,"isStar":false,"memo":"构词 qual(性质，同 quality 质量)+-ify(使…化)→使具备某种性质→使合格，取得资格","example":"She qualified as a doctor last year. 她去年取得了医生资格。"},{"id":1255,"unit":5,"lesson":1,"word":"qualification","pronunciation":"/ˌkwɒlɪfɪˈkeɪʃ(ə)n/","meaning":"n.资格;资历;合格","seq":60,"isStar":false,"memo":"构词 qualific(使合格)+-ation(名词后缀)→使人合格的东西→资格，资历","example":"He has no formal qualifications. 他没有正式的资历。"},{"id":1256,"unit":5,"lesson":1,"word":"quantify","pronunciation":"/ˈkwɒntɪfaɪ/","meaning":"v.量化","seq":61,"isStar":false,"memo":"构词 quant(多少，同 quantity 数量)+-ify(使…化)→使能用数量表示→量化","example":"It is hard to quantify the damage. 这些损失很难量化。"},{"id":1257,"unit":5,"lesson":1,"word":"quantification","pronunciation":"/ˌkwɒntɪfɪˈkeɪʃn/","meaning":"n.量化","seq":62,"isStar":false,"memo":"构词 quantific(量化)+-ation(名词后缀)→量化的过程","example":"The quantification of risk is essential. 风险的量化至关重要。"},{"id":1258,"unit":5,"lesson":1,"word":"unify","pronunciation":"/ˈjuːnɪfaɪ/","meaning":"v.统一;使成一体","seq":63,"isStar":false,"memo":"构词 uni(one 一)+-fy(使…化)→使成为一体→统一","example":"The leader tried to unify the party. 这位领袖试图把全党统一起来。"},{"id":1259,"unit":5,"lesson":1,"word":"unification","pronunciation":"/ˌjuːnɪfɪˈkeɪʃ(ə)n/","meaning":"n.统一;联合","seq":64,"isStar":false,"memo":"构词 unific(统一)+-ation(名词后缀)→统一的过程","example":"The unification of the two regions took years. 两个地区的统一用了很多年。"},{"id":1260,"unit":5,"lesson":1,"word":"unite","pronunciation":"/juˈnaɪt/","meaning":"v.联合,联手;联结,统一","seq":65,"isStar":false,"memo":"构词 uni(one 一)+-te(动词后缀)→变成一体→联合，联手，统一","example":"The two parties united to fight the election. 两党联合起来参加竞选。"},{"id":1261,"unit":5,"lesson":1,"word":"unity","pronunciation":"/ˈjuːnəti/","meaning":"n.团结一致;联合;统一","seq":66,"isStar":false,"memo":"构词 uni(one 一)+-ty(名词后缀)→成为一体的状态→团结一致，统一","example":"The team showed great unity. 这个团队表现出高度的团结。"},{"id":1262,"unit":5,"lesson":1,"word":"reunite","pronunciation":"/ˌriːjuˈnaɪt/","meaning":"v.(使)再结合,再联合;(使)重逢","seq":67,"isStar":false,"memo":"构词 re-(再)+unite(联合)→再次联合→(使)重逢","example":"The family was reunited after the war. 战后一家人重新团聚。"},{"id":1263,"unit":5,"lesson":1,"word":"reunification","pronunciation":"/ˌriːˌjuːnɪfɪˈkeɪʃn/","meaning":"n.重新统一","seq":68,"isStar":false,"memo":"构词 re-(再)+unific(统一)+-ation(名词后缀)→重新统一","example":"Reunification changed the country's economy. 重新统一改变了这个国家的经济。"},{"id":1264,"unit":5,"lesson":1,"word":"reunion","pronunciation":"/ˌriːˈjuːniən/","meaning":"n.重逢;团聚;聚会","seq":69,"isStar":false,"memo":"构词 re-(再)+union(联合)→再次相聚→重逢，团聚，聚会","example":"We hold a family reunion every summer. 我们每年夏天举行一次家庭聚会。"},{"id":1265,"unit":5,"lesson":1,"word":"specify","pronunciation":"/ˈspesɪfaɪ/","meaning":"v.具体说明;明确规定;详述","seq":70,"isStar":false,"memo":"speci（看）+fy（使…）→‘让你盯准一点看’！比如老师说‘Specify your sources’=别写‘网上查的’，要‘指定’哪篇论文第几页。","example":"Please specify the date and location for the meeting. 请注明会议的日期和地点。"},{"id":1266,"unit":5,"lesson":1,"word":"specification","pronunciation":"/ˌspesɪfɪˈkeɪʃ(ə)n/","meaning":"n.规格;规范;明细单;说明书","seq":71,"isStar":false},{"id":1267,"unit":5,"lesson":1,"word":"specific","pronunciation":"/spəˈsɪfɪk/","meaning":"adj.特定的;明确的;具体的;特有的","seq":72,"isStar":false,"memo":"拆解：speci（看）+ fic（做）→ 看准了再做！所以‘具体的、特定的’——不是瞎蒙，是盯着目标精准打击！","example":"The professor gave us specific instructions for the lab experiment. 教授给了我们实验的具体操作指示。"},{"id":1268,"unit":5,"lesson":1,"word":"specifically","pronunciation":"/spəˈsɪfɪkli/","meaning":"adv.特意;专门地;明确地;具体地","seq":73,"isStar":false,"memo":"构词 specific(具体的)+-ally(副词后缀)→把话落实到自己身上→特意，专门地，具体地","example":"The book was written specifically for children. 这本书是专门为孩子写的。"},{"id":1269,"unit":5,"lesson":1,"word":"special","pronunciation":"/ˈspeʃ(ə)l/","meaning":"adj.特殊的,特别的;不寻常的","seq":74,"isStar":false,"memo":"构词 spec(看，同 spectacle 景象)+-ial(形容词后缀)→值得另眼相看的→特殊的，特别的","example":"Today is a special day for us. 今天对我们来说是很特别的一天。"},{"id":1270,"unit":5,"lesson":1,"word":"specialise/-ize","pronunciation":"/ˈspeʃəlaɪz/","meaning":"v.专门研究;专攻","seq":75,"isStar":false,"memo":"构词 special(专门的)+-ise/-ize(使…化)→使自己专门化→专门研究，专攻","example":"She specialises in criminal law. 她专门研究刑法。"},{"id":1271,"unit":5,"lesson":1,"word":"specialisation/-zation","pronunciation":"/ˌspeʃəlaɪˈzeɪʃən/","meaning":"n.特别化;专门化","seq":76,"isStar":false,"memo":"构词 specialis(使专门化)+-ation(名词后缀)→专门化的过程","example":"Modern medicine demands increasing specialisation. 现代医学要求越来越高的专门化。"},{"id":1272,"unit":5,"lesson":1,"word":"specialist","pronunciation":"/ˈspeʃəlɪst/","meaning":"n.专家;专科医生","seq":77,"isStar":false,"memo":"构词 special(专门的)+-ist(表人)→只钻研某一行的人→专家，专科医生","example":"She was referred to a heart specialist. 她被转诊给一位心脏专科医生。"},{"id":1273,"unit":5,"lesson":1,"word":"speciality","pronunciation":"/ˌspeʃiˈæləti/","meaning":"n.特产;专业;专长","seq":78,"isStar":false,"memo":"构词 special(特别的)+-ity(名词后缀)→特别拿手的东西→特长，专业，特产","example":"Seafood is the speciality of this restaurant. 海鲜是这家餐厅的特色菜。"},{"id":1274,"unit":5,"lesson":1,"word":"especially","pronunciation":"/ɪˈspeʃəli/","meaning":"adv.尤其,特别;专门;非常","seq":79,"isStar":false,"memo":"构词 e-(加强)+special(特别的)+-ly(副词后缀)→格外地→尤其，特别","example":"I love fruit, especially mangoes. 我喜欢水果，尤其是芒果。"},{"id":1275,"unit":5,"lesson":1,"word":"specimen","pronunciation":"/ˈspesɪmən/","meaning":"n.样品;样本,标本","seq":80,"isStar":false,"memo":"谐音+联想：‘四皮门’——解剖课上老师掀开盖子喊‘四皮门！标本来了！’；词根spec（看）+imen→让你盯着看的东西。","example":"Students observed a preserved frog specimen under the dissecting microscope. 学生们在解剖显微镜下观察了一只保存完好的青蛙标本。"},{"id":1276,"unit":5,"lesson":1,"word":"burst","pronunciation":"/bɜːst/","meaning":"n.半身像;突击检查 v.打破,摔碎","seq":81,"isStar":false,"memo":"提示 本词条释义对应的是 bust(半身像；突击搜查；破产的)，与 burst(爆裂)形近易混，认词时务必区分","example":"The police bust the illegal gambling den. 警方突击搜查了那个非法赌场。"},{"id":1277,"unit":5,"lesson":1,"word":"burst","pronunciation":"/bɜːst/","meaning":"v.爆炸,爆裂;突然发生 n.爆炸;突发","seq":82,"isStar":false,"memo":"联想 与 bust 形近：burst 里的 u 像裂开的口子→爆炸，爆裂；突然发生","example":"The balloon burst with a loud bang. 气球砰的一声爆了。"},{"id":1278,"unit":5,"lesson":1,"word":"robust","pronunciation":"/rəʊˈbʌst/","meaning":"adj.强健的,强壮的,结实的;坚定的","seq":83,"isStar":false,"memo":"【谐音】‘肉不瘦’——肌肉结实、身体壮实；【构词】robust ← Latin robur（橡树，象征坚固）→像橡树一样结实。","example":"A robust immune system helps students resist seasonal flu during exams. 强健的免疫系统有助于学生在考试期间抵御季节性流感。"},{"id":1279,"unit":5,"lesson":1,"word":"blast","pronunciation":"/blɑːst/","meaning":"n.一阵疾风;爆炸;响亮的声音 v.炸毁","seq":84,"isStar":false,"memo":"谐音‘爆死’——爆炸当然让人想‘爆死’！b+last（最后），爆炸后啥都没了，只剩‘最后’。","example":"The demolition team set off a controlled blast to clear the old building. 拆除队引爆定向爆破来清理旧楼。"},{"id":1280,"unit":5,"lesson":1,"word":"plastic","pronunciation":"/ˈplæstɪk/","meaning":"n.塑料 adj.塑料制的;可塑的","seq":85,"isStar":false,"memo":"【谐音】‘拍死踢’→塑料袋一拍就瘪、一踢就飞，n./adj.塑料（的）。","example":"Many campuses have banned single-use plastic bottles to reduce environmental impact. 许多校园已禁用一次性塑料瓶以减轻环境影响。"},{"id":1281,"unit":5,"lesson":1,"word":"elastic","pronunciation":"/ɪˈlæstɪk/","meaning":"adj.有弹性的;灵活的 n.橡皮圈","seq":86,"isStar":false,"memo":"构词 e-(加强)+last(持续)+-ic(形容词后缀)→能持续被拉伸的→有弹性的；橡皮圈","example":"The waistband is made of elastic. 这条腰带是弹性材料做的。"},{"id":1282,"unit":5,"lesson":1,"word":"elasticity","pronunciation":"/ˌiːlæˈstɪsəti/","meaning":"n.弹性;弹力","seq":87,"isStar":false,"memo":"构词 elastic(有弹性的)+-ity(名词后缀)→能伸能缩的性质→弹性，弹力","example":"Rubber has great elasticity. 橡胶的弹性很好。"},{"id":1283,"unit":5,"lesson":1,"word":"flexible","pronunciation":"/ˈfleksəb(ə)l/","meaning":"adj.柔韧的,易弯曲的;灵活的","seq":88,"isStar":false,"memo":"谐音+联想：'flexi-布勒'——布勒（布料）能弯能折，身体软、计划软、思维也软！","example":"A flexible schedule helps students balance part-time jobs and coursework. 灵活的时间安排有助于学生兼顾兼职工作与课程学习。"},{"id":1284,"unit":5,"lesson":1,"word":"flexibility","pronunciation":"/ˌfleksəˈbɪləti/","meaning":"n.灵活性;弹性,柔韧","seq":89,"isStar":false},{"id":1285,"unit":5,"lesson":1,"word":"reflect","pronunciation":"/rɪˈflekt/","meaning":"v.反射;反映;反省","seq":90,"isStar":false,"memo":"构词 re-(回)+flect(弯曲，同 flexible 易弯曲的)→把光“弯”回去→反射；反映；反省","example":"The mirror reflects the light. 镜子反射光线。"},{"id":1286,"unit":5,"lesson":1,"word":"reflection","pronunciation":"/rɪˈflekʃ(ə)n/","meaning":"n.反射;反映;影像","seq":91,"isStar":false,"memo":"构词 reflect(反射)+-ion(名词后缀)→反射出来的影像→倒影；反映","example":"She saw her reflection in the water. 她在水中看到了自己的倒影。"},{"id":1287,"unit":5,"lesson":1,"word":"reflective","pronunciation":"/rɪˈflektɪv/","meaning":"adj.沉思的,深思的;反射热的,反光的","seq":92,"isStar":false,"memo":"构词 reflect(反射、深思)+-ive(形容词后缀)→能反光的，也指爱回头思索的→沉思的，反光的","example":"He was in a reflective mood. 他陷入了沉思。"},{"id":1288,"unit":5,"lesson":1,"word":"distort","pronunciation":"/dɪˈstɔːt/","meaning":"v.使变形,扭曲;歪曲,曲解","seq":93,"isStar":false,"memo":"dis-（歪）+tort（扭曲，同torture）→歪着折磨，不就是‘歪曲’真相嘛！","example":"Sensational headlines often distort the facts. 耸人听闻的标题常常歪曲事实。"},{"id":1289,"unit":5,"lesson":1,"word":"distorted","pronunciation":"/dɪˈstɔːtɪd/","meaning":"adj.扭曲的","seq":94,"isStar":false,"memo":"构词 dis-(坏、离)+tort(扭，同 torture 折磨)+-ed(形容词后缀)→被扭歪了的→扭曲的","example":"The report gave a distorted picture of events. 这份报告扭曲了事件的真相。"},{"id":1290,"unit":5,"lesson":1,"word":"distortion","pronunciation":"/dɪˈstɔːʃ(ə)n/","meaning":"n.歪曲;变形,扭曲","seq":95,"isStar":false},{"id":1291,"unit":5,"lesson":1,"word":"retort","pronunciation":"/rɪˈtɔːt/","meaning":"v.反驳,回嘴 n.回应,反驳","seq":96,"isStar":false,"memo":"构词 re-(回)+tort(扭，同 distort 扭曲)→把话原样“扭”回去→反驳，回嘴","example":"She retorted that it was not true. 她反驳说那不是真的。"},{"id":1292,"unit":5,"lesson":1,"word":"torture","pronunciation":"/ˈtɔːtʃə(r)/","meaning":"n.拷打,拷问;折磨 v.拷打,拷问","seq":97,"isStar":false,"memo":"构词 tort(扭，同 distort 扭曲)+-ure(名词后缀)→把身体扭拧的痛苦→拷打，折磨","example":"He was tortured by guilt. 他深受内疚的折磨。"},{"id":1293,"unit":5,"lesson":2,"word":"breakdown","pronunciation":"/ˈbreɪkdaʊn/","meaning":"n.(汽车或机器的)故障,损坏","seq":1,"isStar":false,"memo":"【构词】break（坏掉）+ down（垮下）→‘啪嗒垮掉’→机器故障、情绪崩溃都用它！修车师傅最爱说breakdown～","example":"The server breakdown delayed online registration for over two hours. 服务器故障导致在线报名延迟超两小时。"},{"id":1294,"unit":5,"lesson":2,"word":"bankrupt","pronunciation":"/ˈbæŋkrʌpt/","meaning":"n.破产者 v.使破产 adj.破产的","seq":2,"isStar":false,"memo":"构词 bank(银行)+rupt(断裂，同 erupt 爆发)→银行的资金链断了→破产的；使破产","example":"The company went bankrupt last year. 这家公司去年破产了。"},{"id":1295,"unit":5,"lesson":2,"word":"bankruptcy","pronunciation":"/ˈbæŋkrʌptsi/","meaning":"n.破产,倒闭;(名誉等的)彻底消失","seq":3,"isStar":false,"memo":"构词 bankrupt(破产的)+-cy(名词后缀)→破产的状态","example":"The firm filed for bankruptcy. 该公司申请了破产。"},{"id":1296,"unit":5,"lesson":2,"word":"deficit","pronunciation":"/ˈdefɪsɪt/","meaning":"n.赤字,亏损,逆差","seq":4,"isStar":false,"memo":"de-（向下）+fic（做）+it→钱‘做’少了，账上亏空啦！","example":"The national budget deficit reached record levels last year. 去年国家财政赤字达到历史最高水平。"},{"id":1297,"unit":5,"lesson":2,"word":"interrupt","pronunciation":"/ˌɪntəˈrʌpt/","meaning":"v.打断(某人的)讲话;打扰;使中断","seq":5,"isStar":false,"memo":"in-ter-rupt：‘in’冲进去+‘ter’（=terr-恐）+‘rupt’（破）→硬闯+吓人+撕裂对话！","example":"Please don’t interrupt the speaker during the Q&A session. 问答环节请勿打断发言者。"},{"id":1298,"unit":5,"lesson":2,"word":"interruption","pronunciation":"/ˌɪntəˈrʌpʃ(ə)n/","meaning":"n.打扰,插嘴;阻断物;中断时间","seq":6,"isStar":false},{"id":1299,"unit":5,"lesson":2,"word":"erupt","pronunciation":"/ɪˈrʌpt/","meaning":"v.突然发生;爆发;喷发;迸发","seq":7,"isStar":false,"memo":"构词 e-(向外)+rupt(断裂)→像火山裂开向外喷→爆发，喷发，迸发","example":"The volcano erupted without warning. 火山毫无预警地喷发了。"},{"id":1300,"unit":5,"lesson":2,"word":"eruption","pronunciation":"/ɪˈrʌpʃ(ə)n/","meaning":"n.突然发生;爆发;喷发","seq":8,"isStar":false,"memo":"构词 erupt(喷发)+-ion(名词后缀)→喷发这一事件","example":"The eruption destroyed the whole village. 火山喷发摧毁了整个村庄。"},{"id":1301,"unit":5,"lesson":2,"word":"disrupt","pronunciation":"/dɪsˈrʌpt/","meaning":"v.扰乱,使混乱,打乱","seq":9,"isStar":false,"memo":"dis-（分开）+rupt（破裂，如erupt）→啪一下撕裂流程，‘扰乱’没商量！","example":"A cyberattack disrupted the hospital's booking system. 一次网络攻击扰乱了医院预约系统。"},{"id":1302,"unit":5,"lesson":2,"word":"disruptive","pronunciation":"/dɪsˈrʌptɪv/","meaning":"adj.引起混乱的;扰乱性的;破坏性的","seq":10,"isStar":false,"memo":"构词 dis-(分开)+rupt(断裂)+-ive(形容词后缀)→把秩序打断的→扰乱性的，引起混乱的","example":"His behaviour was disruptive in class. 他在课堂上的行为扰乱了秩序。"},{"id":1303,"unit":5,"lesson":2,"word":"disruption","pronunciation":"/dɪsˈrʌpʃn/","meaning":"n.中断,分裂,破坏","seq":11,"isStar":false},{"id":1304,"unit":5,"lesson":2,"word":"abrupt","pronunciation":"/əˈbrʌpt/","meaning":"adj.突然的,意外的;粗鲁的,生硬的","seq":12,"isStar":false,"memo":"a-b-rupt（‘啊！不rupt？’）→ 突然中断！rupt=break（断裂），前缀ab-=away，一断就‘away’消失，毫无预兆！","example":"His abrupt departure left the team unprepared for the deadline. 他突然离职，导致团队无法按时完成任务。"},{"id":1305,"unit":5,"lesson":2,"word":"corrupt","pronunciation":"/kəˈrʌpt/","meaning":"v.使腐化;破坏 adj.腐败的","seq":13,"isStar":false,"memo":"构词 cor-(加强)+rupt(断裂)→把原则彻底打断→使腐化；腐败的","example":"He was accused of corrupt practices. 他被指控有腐败行为。"},{"id":1306,"unit":5,"lesson":2,"word":"corruption","pronunciation":"/kəˈrʌpʃ(ə)n/","meaning":"n.腐败;受贿;堕落","seq":14,"isStar":false,"memo":"构词 corrupt(腐败的)+-ion(名词后缀)→腐败的行为与状况","example":"The official was arrested for corruption. 这名官员因腐败被捕。"},{"id":1307,"unit":5,"lesson":2,"word":"rot","pronunciation":"/rɒt/","meaning":"n.腐烂;腐败 v.(使)腐烂","seq":15,"isStar":false,"memo":"联想 与 rotten(腐烂的)同根，rot 是它的动词与名词形式→腐烂，腐败","example":"The fruit began to rot in the heat. 酷热中水果开始腐烂。"},{"id":1308,"unit":5,"lesson":2,"word":"rotten","pronunciation":"/ˈrɒt(ə)n/","meaning":"adj.腐烂的,腐败的","seq":16,"isStar":false,"memo":"构词 rot(腐烂)+-t+-en(形容词后缀)→已经烂掉的→腐烂的，腐败的","example":"The wood was completely rotten. 那块木头完全腐烂了。"},{"id":1309,"unit":5,"lesson":2,"word":"rotate","pronunciation":"/rəʊˈteɪt/","meaning":"v.(使)旋转,(使)转动;由……轮值","seq":17,"isStar":false,"memo":"构词 rot(转，同 rotary 旋转的)+-ate(动词后缀)→转动；也指轮流值班","example":"The earth rotates on its axis. 地球绕轴自转。"},{"id":1310,"unit":5,"lesson":2,"word":"rotation","pronunciation":"/rəʊˈteɪʃ(ə)n/","meaning":"n.旋转,转动;轮换","seq":18,"isStar":false,"memo":"构词 rotat(旋转)+-ion(名词后缀)→旋转或轮换","example":"The rotation of crops keeps the soil rich. 轮作能让土壤保持肥沃。"},{"id":1311,"unit":5,"lesson":2,"word":"erode","pronunciation":"/ɪˈrəʊd/","meaning":"v.腐蚀;风化;逐渐毁坏;削弱","seq":19,"isStar":false,"memo":"【构词】e-（出）+ rode（路？错！实为rod-根，同corrode）→水把石头‘啃出来’→侵蚀！浪花天天舔崖壁，崖就悄悄erode。","example":"Coastal erosion threatens many seaside villages. 海岸侵蚀正威胁许多海滨村庄。"},{"id":1312,"unit":5,"lesson":2,"word":"decay","pronunciation":"/dɪˈkeɪ/","meaning":"v.(力量、影响等)衰弱,衰退","seq":20,"isStar":false,"memo":"构词 de-(向下)+cay(落下，同 cadence 韵律/下落)→一路往下掉→衰弱，衰退，腐烂","example":"The old house has fallen into decay. 那座老房子已经破败不堪。"},{"id":1313,"unit":5,"lesson":2,"word":"bribe","pronunciation":"/braɪb/","meaning":"n.贿赂 v.贿赂,收买","seq":21,"isStar":false,"memo":"谐音 “不来吧”：塞了好处对方才肯“来吧”→贿赂，收买","example":"He was accused of taking bribes. 他被指控收受贿赂。"},{"id":1314,"unit":5,"lesson":2,"word":"bribery","pronunciation":"/ˈbraɪbəri/","meaning":"n.贿赂","seq":22,"isStar":false,"memo":"构词 bribe(贿赂)+-ery(名词后缀)→行贿受贿的行为","example":"She was charged with bribery. 她被控行贿。"},{"id":1315,"unit":5,"lesson":2,"word":"debt","pronunciation":"/det/","meaning":"n.借款,欠款,债务","seq":23,"isStar":false,"memo":"【谐音】'贷'它→你找银行'贷'款，结果背上'债'（debt）！d-e-b-t，四个字母像四张欠条。","example":"Student debt in the US has exceeded one trillion dollars. 美国学生债务已超一万亿美元。"},{"id":1316,"unit":5,"lesson":2,"word":"debtor","pronunciation":"/ˈdetə(r)/","meaning":"n.债务人;借方","seq":24,"isStar":false},{"id":1317,"unit":5,"lesson":2,"word":"indebted","pronunciation":"/ɪnˈdetɪd/","meaning":"adj.负债的;感激的,蒙恩的","seq":25,"isStar":false,"memo":"【构词】in-（进入）+debt（债务）+ed→‘陷进债务里’→负债；引申为‘情感上陷进感激里’→感激不尽！","example":"She felt deeply indebted to her mentor for career guidance. 她深深感激导师的职业指导。"},{"id":1318,"unit":5,"lesson":2,"word":"levy","pronunciation":"/ˈlevi/","meaning":"n.征收额;税款 v.征收,征(税)","seq":26,"isStar":false,"memo":"【谐音】'来税'——税务局一来，税就来了！v.征税，n.税款，和'levitate'（升空）同源，本义‘抬起来’→把钱抬走。","example":"The government plans to levy a new carbon tax on heavy industries. 政府计划对重工业征收新的碳税。"},{"id":1319,"unit":5,"lesson":2,"word":"lever","pronunciation":"/ˈliːvə(r)/","meaning":"n.操纵杆,杠杆;方法","seq":27,"isStar":false,"memo":"构词 lev(举起，同 elevate 提升)+-er(表物)→用来把东西举起来的工具→杠杆，操纵杆","example":"He pulled the lever to start the machine. 他拉下操纵杆启动了机器。"},{"id":1320,"unit":5,"lesson":2,"word":"leverage","pronunciation":"/ˈliːvərɪdʒ/","meaning":"n.影响力;杠杆作用 v.充分利用","seq":28,"isStar":false,"memo":"构词 lever(杠杆)+-age(名词后缀)→杠杆撬动的力量，引申为可借用的影响力","example":"They used their leverage to win the deal. 他们利用自身影响力拿下了这笔交易。"},{"id":1321,"unit":5,"lesson":2,"word":"inflate","pronunciation":"/ɪnˈfleɪt/","meaning":"v.使充气,膨胀","seq":29,"isStar":false,"memo":"构词 in-(向内)+flat(吹，同 blow 吹)+-e→往里吹气→使充气，膨胀","example":"He inflated the tyres before the trip. 出发前他给轮胎充了气。"},{"id":1322,"unit":5,"lesson":2,"word":"inflation","pronunciation":"/ɪnˈfleɪʃ(ə)n/","meaning":"n.通货膨胀;充气","seq":30,"isStar":false,"memo":"构词 inflat(膨胀)+-ion(名词后缀)→物价不断膨胀→通货膨胀；充气","example":"Inflation has reached a ten-year high. 通胀率已达到十年来的最高点。"},{"id":1323,"unit":5,"lesson":2,"word":"shrink","pronunciation":"/ʃrɪŋk/","meaning":"v.(使)缩水,(使)缩小,(使)收缩","seq":31,"isStar":false,"memo":"【谐音+联想】‘神缩水’——毛衣洗完‘神缩水’，衣服小一圈，人也想‘缩’着躲尴尬！","example":"Many small businesses have shrunk or closed due to rising operational costs. 许多小微企业因运营成本上升而缩减规模或倒闭。"},{"id":1324,"unit":5,"lesson":2,"word":"fade","pronunciation":"/feɪd/","meaning":"v.褪色;逐渐消失,淡出","seq":32,"isStar":false,"memo":"谐音 “费德”：颜色“费”掉了、光鲜的德性也褪去→褪色，逐渐消失，淡出","example":"The colour faded in the sun. 颜色在阳光下褪去了。"},{"id":1325,"unit":5,"lesson":2,"word":"shred","pronunciation":"/ʃred/","meaning":"n.细条,碎片","seq":33,"isStar":false,"memo":"联想 与 thread(线)形近：撕得只剩线一样的细条→碎片；撕成碎片","example":"He shredded the documents. 他把文件粉碎了。"},{"id":1326,"unit":5,"lesson":2,"word":"sheet","pronunciation":"/ʃiːt/","meaning":"n.床单,被单;纸张;薄片,一片","seq":34,"isStar":false,"memo":"联想 与 shaft/shift 同源：铺开来的一大片→床单；一张(纸)，薄片","example":"Give each student a sheet of paper. 给每个学生发一张纸。"},{"id":1327,"unit":5,"lesson":2,"word":"shell","pronunciation":"/ʃel/","meaning":"n.壳;贝壳;炮弹","seq":35,"isStar":false,"memo":"谐音 “晒哦”：贝壳都晒在沙滩上→壳，贝壳；也指炮弹外壳","example":"We collected shells on the beach. 我们在沙滩上捡贝壳。"},{"id":1328,"unit":5,"lesson":2,"word":"coast","pronunciation":"/kəʊst/","meaning":"n.海岸,海滨","seq":36,"isStar":false,"memo":"联想 与 coastal(沿海的)同根：水与陆并行的那条线→海岸，海滨","example":"We drove along the coast. 我们沿着海岸开车。"},{"id":1329,"unit":5,"lesson":2,"word":"coastal","pronunciation":"/ˈkəʊst(ə)l/","meaning":"adj.沿海的;靠近海岸的","seq":37,"isStar":false,"memo":"coast（海岸）+ -al（形容词后缀）→字面就是‘海岸的’！记成‘靠死它’——海边房子太抢手，靠海就得拼命抢！","example":"Coastal communities face increasing risks from sea-level rise. 沿海社区正面临日益加剧的海平面上升风险。"},{"id":1330,"unit":5,"lesson":2,"word":"deposit","pronunciation":"/dɪˈpɒzɪt/","meaning":"n.押金,订金;存款;沉积物 v.使沉积","seq":38,"isStar":false,"memo":"de-（下）+posit（放，=put）→把钱‘往下放’进银行是定金，泥沙‘往下放’堆成沉积物。","example":"Scientists analyzed sediment deposits to reconstruct ancient climate patterns. 科学家分析沉积物以重建古代气候模式。"},{"id":1331,"unit":5,"lesson":2,"word":"compose","pronunciation":"/kəmˈpəʊz/","meaning":"v.组成,构成;作曲;创作","seq":39,"isStar":false,"memo":"【构词】com-（一起）+ pose（放）→把东西放在一起→组成；写歌也是把音符‘放一起’！","example":"The composer will compose a new symphony for the university's centennial. 这位作曲家将为大学百年校庆创作一部新交响曲。"},{"id":1332,"unit":5,"lesson":2,"word":"composition","pronunciation":"/ˌkɒmpəˈzɪʃ(ə)n/","meaning":"n.成分,构成;作品,作曲","seq":40,"isStar":false},{"id":1333,"unit":5,"lesson":2,"word":"composer","pronunciation":"/kəmˈpəʊzə(r)/","meaning":"n.作曲家","seq":41,"isStar":false},{"id":1334,"unit":5,"lesson":2,"word":"composite","pronunciation":"/ˈkɒmpəzɪt/","meaning":"n.合成物,混合物","seq":42,"isStar":false,"memo":"com-（一起）+ posite（放）→ ‘一起放’的东西就是合成物！像奶茶加珍珠+布丁+芋圆，复合式快乐～","example":"Engineers used a lightweight composite material for the drone’s frame. 工程师为无人机机架采用了轻质复合材料。"},{"id":1335,"unit":5,"lesson":2,"word":"compile","pronunciation":"/kəmˈpaɪl/","meaning":"v.编写,编纂;汇编;编译","seq":43,"isStar":false,"memo":"谐音+构词：‘康破了’——程序员编译代码时电脑卡到崩溃！com-（一起）+pile（堆）→把零散资料堆成一本手册。","example":"The team compiled survey data into a comprehensive report for the university. 团队将调查数据汇编成一份供大学使用的综合报告。"},{"id":1336,"unit":5,"lesson":2,"word":"compilation","pronunciation":"/ˌkɒmpɪˈleɪʃn/","meaning":"n.收集;编纂,编写","seq":44,"isStar":false},{"id":1337,"unit":5,"lesson":2,"word":"pile","pronunciation":"/paɪl/","meaning":"n.摞,堆;成堆的东西 v.堆放,叠放","seq":45,"isStar":false,"memo":"谐音‘派尔’——派你去堆‘尔’（一堆）书！pil-（= pile 堆，同源pill 原义‘小块’）+ -e，摞起来像小山包。","example":"Students piled textbooks on the desk before the final exam. 考前学生们把教科书堆在课桌上。"},{"id":1338,"unit":5,"lesson":2,"word":"file","pronunciation":"/faɪl/","meaning":"n.文件夹;卷宗","seq":46,"isStar":false,"memo":"构词 fil(线，同 filament 细丝)+-e→用线把资料串起来→文件夹，档案；归档；提起(诉讼)","example":"Please file these documents. 请把这些文件归档。"},{"id":1339,"unit":5,"lesson":2,"word":"posture","pronunciation":"/ˈpɒstʃə(r)/","meaning":"n.(坐、立的)姿势;态度","seq":47,"isStar":false,"memo":"构词 pos(放，同 position 位置)+-ture(名词后缀)→身体摆放的样子→姿势；态度，立场","example":"Good posture protects your back. 良好的姿势能保护腰背。"},{"id":1340,"unit":5,"lesson":2,"word":"pose","pronunciation":"/pəʊz/","meaning":"n.(为画像、拍照等摆的)姿势 v.造成","seq":48,"isStar":false,"memo":"【构词】po-（=put, 放）+ -se → 把身体‘放’成某个样子→姿势；引申为‘放’个难题给你→造成（麻烦）。","example":"The rapid AI development poses serious ethical questions for educators. 人工智能的快速发展给教育工作者提出了严峻的伦理问题。"},{"id":1341,"unit":5,"lesson":2,"word":"propose","pronunciation":"/prəˈpəʊz/","meaning":"v.提议,建议;打算;求婚","seq":49,"isStar":false,"memo":"pro（向前）+pose（放）→‘把方案往前一放’=提议！求婚也是‘把戒指往前一放’，同源！","example":"He proposed a novel framework for cross-disciplinary research. 他提出了一种跨学科研究的新框架。"},{"id":1342,"unit":5,"lesson":2,"word":"proposal","pronunciation":"/prəˈpəʊz(ə)l/","meaning":"n.提议,建议;求婚","seq":50,"isStar":false},{"id":1343,"unit":5,"lesson":2,"word":"proposition","pronunciation":"/ˌprɒpəˈzɪʃ(ə)n/","meaning":"n.提议,建议;(美国)法律修正议案","seq":51,"isStar":false,"memo":"构词 pro-(向前)+posit(放)+-ion(名词后缀)→摆到前面供讨论的→提议，建议，观点","example":"She accepted his proposition. 她接受了他的提议。"},{"id":1344,"unit":5,"lesson":2,"word":"position","pronunciation":"/pəˈzɪʃ(ə)n/","meaning":"n.观点,立场;位置,地方;职务","seq":52,"isStar":false,"memo":"构词 posit(放，同 pose 摆放)+-ion(名词后缀)→摆放的地方，引申为立场、职位","example":"What is your position on this issue? 你对这个问题持什么立场？"},{"id":1345,"unit":5,"lesson":2,"word":"expose","pronunciation":"/ɪkˈspəʊz/","meaning":"v.使接触;暴露;揭露","seq":53,"isStar":false,"memo":"【构词】ex-（外）+ pose（放）→ 把东西‘放出来’让人看见→暴露；谐音‘一克死泡丝’——曝光后病毒一克就死！","example":"Investigative journalists exposed corruption in the city's public housing system. 调查记者揭发了该市公共住房系统的腐败问题。"},{"id":1346,"unit":5,"lesson":2,"word":"exposure","pronunciation":"/ɪkˈspəʊʒə(r)/","meaning":"n.暴露,曝光;接触;揭露","seq":54,"isStar":false},{"id":1347,"unit":5,"lesson":2,"word":"exposition","pronunciation":"/ˌekspəˈzɪʃ(ə)n/","meaning":"n.解释,说明,阐述;商品交易会","seq":55,"isStar":false,"memo":"构词 ex-(向外)+posit(放)+-ion(名词后缀)→把内容摆出来讲→阐述，说明；博览会","example":"The book is a clear exposition of the theory. 这本书清晰地阐述了这一理论。"},{"id":1348,"unit":5,"lesson":2,"word":"dispose","pronunciation":"/dɪˈspəʊz/","meaning":"v.使倾向于;布置,安排;处理,扔掉","seq":56,"isStar":false,"memo":"【构词】dis-（分开）+ pose（放）→ 把东西‘分开放好’→ 布置安排！就像宿舍长dispose床位：上铺A，下铺B，井井有条～","example":"The lab director disposed equipment neatly across three workbenches. 实验室主任将设备整齐布置在三张工作台上。"},{"id":1349,"unit":5,"lesson":2,"word":"disposition","pronunciation":"/ˌdɪspəˈzɪʃn/","meaning":"n.性格,性情;倾向,意向","seq":57,"isStar":false,"memo":"构词 dis-(分开)+posit(放)+-ion(名词后缀)→天性摆在那儿的样子→性格，性情；倾向","example":"She has a cheerful disposition. 她性情开朗。"},{"id":1350,"unit":5,"lesson":2,"word":"disposal","pronunciation":"/dɪˈspəʊz(ə)l/","meaning":"n.清除;处理;(企业、财产等的)变卖","seq":58,"isStar":false},{"id":1351,"unit":5,"lesson":2,"word":"impose","pronunciation":"/ɪmˈpəʊz/","meaning":"v.推行,采用;强制实行,把……强加于","seq":59,"isStar":false,"memo":"【构词】im-（in-, 进入）+ pose（放）→ 把规则‘放进去’你生活里→强加；联想‘俺怕死’——领导 impose 加班，俺怕死也得干！","example":"The government imposed strict data privacy regulations on tech firms. 政府对科技公司施加了严格的数据隐私监管。"},{"id":1352,"unit":5,"lesson":2,"word":"imposition","pronunciation":"/ˌɪmpəˈzɪʃ(ə)n/","meaning":"n.颁布,实施;征收","seq":60,"isStar":false},{"id":1353,"unit":5,"lesson":2,"word":"imposing","pronunciation":"/ɪmˈpəʊzɪŋ/","meaning":"adj.壮观的;使人印象深刻的","seq":61,"isStar":false,"memo":"构词 im-(在…上)+pos(放)+-ing→“放”在你面前压过来的→壮观的，令人印象深刻的","example":"The castle is an imposing building. 这座城堡是一座壮观的建筑。"},{"id":1354,"unit":5,"lesson":2,"word":"oppose","pronunciation":"/əˈpəʊz/","meaning":"v.反对,对抗;与……角逐","seq":62,"isStar":false,"memo":"op-pose：‘op-’（against）+‘pose’（摆姿势）→面对面‘摆pose’对峙！反对就是站对面凹造型。","example":"Many citizens oppose the new policy on data privacy. 许多市民反对这项新的数据隐私政策。"},{"id":1355,"unit":5,"lesson":2,"word":"opposition","pronunciation":"/ˌɒpəˈzɪʃ(ə)n/","meaning":"n.(强烈的)反对,反抗,对抗","seq":63,"isStar":false},{"id":1356,"unit":5,"lesson":2,"word":"opposite","pronunciation":"/ˈɒpəzɪt/","meaning":"adj.对面的,相反的 n.对立面,反面","seq":64,"isStar":false,"memo":"【构词】op-（反）+ posite（放）→反着放→相反的！就像你妈让你往东，你偏往西，纯纯反向操作。","example":"The opposite of 'optimistic' is 'pessimistic'. '乐观'的反义词是'悲观'。"},{"id":1357,"unit":5,"lesson":2,"word":"opponent","pronunciation":"/əˈpəʊnənt/","meaning":"n.对手,竞争者;反对者","seq":65,"isStar":false},{"id":1358,"unit":5,"lesson":2,"word":"component","pronunciation":"/kəmˈpəʊnənt/","meaning":"n.组成部分;成分,部件","seq":66,"isStar":false,"memo":"com（一起）+ pon（放）+ ent → ‘放在一起的东西’！机器零件、课程模块、性格要素…全是被‘放进来’的组成分子～","example":"Each component of the software must be tested before integration. 软件每个组件集成前都必须经过测试。"},{"id":1359,"unit":5,"lesson":2,"word":"exponent","pronunciation":"/ɪkˈspəʊnənt/","meaning":"n.拥护者,倡导者;能手,大师;指数","seq":67,"isStar":false,"memo":"构词 ex-(向外)+pon(放)+-ent(表人)→把观点摆出来的人→倡导者，拥护者；能手；指数","example":"He is a leading exponent of jazz. 他是爵士乐的代表性人物。"},{"id":1360,"unit":5,"lesson":2,"word":"rival","pronunciation":"/ˈraɪv(ə)l/","meaning":"n.竞争对手 v.与……相匹敌,比得上","seq":68,"isStar":false,"memo":"拆成 rive（撕裂）+ al（人）→ 把对手‘撕裂’成平手？不，是旗鼓相当的对手！","example":"Two tech giants are fierce rivals in the AI research field. 两家科技巨头在人工智能研究领域是激烈的竞争对手。"},{"id":1361,"unit":5,"lesson":2,"word":"rivalry","pronunciation":"/ˈraɪv(ə)lri/","meaning":"n.竞争,竞赛,较量","seq":69,"isStar":false},{"id":1362,"unit":5,"lesson":2,"word":"positive","pronunciation":"/ˈpɒzətɪv/","meaning":"adj.赞同的;积极乐观的,有信心的","seq":70,"isStar":false,"memo":"构词 posit(放、确定)+-ive(形容词后缀)→把态度定下来的→肯定的，赞同的，积极乐观的","example":"She has a positive attitude to life. 她对生活态度积极。"},{"id":1363,"unit":5,"lesson":2,"word":"negative","pronunciation":"/ˈneɡətɪv/","meaning":"adj.有害的,消极的,负面的;否定的","seq":71,"isStar":false,"memo":"构词 neg(否定，同 neglect 忽视)+-ative(形容词后缀)→带否定色彩的→否定的，消极的，负面的","example":"Don't be so negative about the future. 别对未来这么消极。"},{"id":1364,"unit":5,"lesson":2,"word":"optimistic","pronunciation":"/ˌɒptɪˈmɪstɪk/","meaning":"adj.乐观的,乐观主义的","seq":72,"isStar":false},{"id":1365,"unit":5,"lesson":2,"word":"optimism","pronunciation":"/ˈɒptɪmɪzəm/","meaning":"n.乐观;乐观主义","seq":73,"isStar":false,"memo":"【谐音+联想】‘噢！提我ism’——乐观主义就是总喊‘噢！提我一把吧！’还坚信能行！","example":"His optimism helped the team stay motivated during the tough project. 他的乐观主义帮助团队在艰难项目中保持动力。"},{"id":1366,"unit":5,"lesson":2,"word":"optimist","pronunciation":"/ˈɒptɪmɪst/","meaning":"n.乐观的人;乐天派","seq":74,"isStar":false},{"id":1367,"unit":5,"lesson":2,"word":"passive","pronunciation":"/ˈpæsɪv/","meaning":"adj.被动的,消极的","seq":75,"isStar":false,"memo":"构词 pass(承受，同 passion 激情)+-ive(形容词后缀)→只会承受不会争取的→被动的，消极的","example":"He played a passive role in the discussion. 他在讨论中处于被动。"},{"id":1368,"unit":5,"lesson":2,"word":"reluctant","pronunciation":"/rɪˈlʌktənt/","meaning":"adj.不情愿的","seq":76,"isStar":false,"memo":"re-（反）+ luc-（光，引申为‘显露意愿’）+ -tant → 反光不愿露脸？其实是‘不情愿的’——像早八课赖床的你！","example":"Many faculty members remain reluctant to adopt AI grading tools. 许多教师仍不愿采用人工智能评分工具。"},{"id":1369,"unit":5,"lesson":2,"word":"reluctance","pronunciation":"/rɪˈlʌktəns/","meaning":"n.勉强,不情愿","seq":77,"isStar":false},{"id":1370,"unit":5,"lesson":2,"word":"attitude","pronunciation":"/ˈætɪtjuːd/","meaning":"n.态度,看法;姿势","seq":78,"isStar":false,"memo":"谐音+联想：'爱踢图度'→爱踢足球的人态度超硬核！at-（表强调）+titude（=tude，姿态）→内心姿态即态度。","example":"Her positive attitude toward feedback greatly impressed the thesis advisor. 她对反馈所持的积极态度给论文导师留下深刻印象。"},{"id":1371,"unit":5,"lesson":2,"word":"latitude","pronunciation":"/ˈlætɪtjuːd/","meaning":"n.纬度","seq":79,"isStar":false,"memo":"构词 lat(宽，同 lateral 侧面的)+-itude(名词后缀)→横向的宽度，引申为回旋余地→纬度；自由度","example":"The island lies at a latitude of 40 degrees north. 这座岛位于北纬40度。"},{"id":1372,"unit":5,"lesson":2,"word":"aptitude","pronunciation":"/ˈæptɪtjuːd/","meaning":"n.天资,天赋","seq":80,"isStar":false,"memo":"拆成a-pti-tude：'a'像‘啊’，‘pti’谐音‘体’，‘tude’像‘天赋’——一看到它就‘啊！这身体自带天赋！’","example":"Her aptitude for coding became obvious during the AI club hackathon. 她在AI社团编程马拉松中展现出惊人的编程天赋。"},{"id":1373,"unit":5,"lesson":3,"word":"export","pronunciation":"/ɪkˈspɔːt; ˈekspɔːt/","meaning":"n.出口,输出;出口产品 v.出口,输出","seq":1,"isStar":false,"memo":"构词 ex-(向外)+port(运，同 transport 运输)→往外面运→出口，输出；出口产品","example":"The country exports coffee to Europe. 这个国家向欧洲出口咖啡。"},{"id":1374,"unit":5,"lesson":3,"word":"exportation","pronunciation":"/ˌekspɔːˈteɪʃn/","meaning":"n.出口,输出","seq":2,"isStar":false,"memo":"构词 export(出口)+-ation(名词后缀)→出口这一行为","example":"The exportation of rare timber is banned. 珍稀木材禁止出口。"},{"id":1375,"unit":5,"lesson":3,"word":"import","pronunciation":"/ˈɪmpɔːt/","meaning":"n.进口,输入的产品或劳务 v.进口","seq":3,"isStar":false,"memo":"构词 im-(向内)+port(运)→往国内运→进口，输入","example":"The country has to import most of its oil. 这个国家大部分石油依赖进口。"},{"id":1376,"unit":5,"lesson":3,"word":"importation","pronunciation":"/ˌɪmpɔːˈteɪʃn/","meaning":"n.进口,输入,引进","seq":4,"isStar":false,"memo":"构词 import(进口)+-ation(名词后缀)→进口这一行为","example":"The importation of cheap steel rose sharply. 廉价钢材的进口量急剧上升。"},{"id":1377,"unit":5,"lesson":3,"word":"porter","pronunciation":"/ˈpɔːtə(r)/","meaning":"n.行李员,搬运工;护工;门卫","seq":5,"isStar":false,"memo":"构词 port(运，同 portable 便携的)+-er(表人)→负责搬运的人→行李员，搬运工；门卫","example":"The porter carried our bags upstairs. 行李员把我们的包搬上了楼。"},{"id":1378,"unit":5,"lesson":3,"word":"deport","pronunciation":"/dɪˈpɔːt/","meaning":"v.驱逐出境,递解出境","seq":6,"isStar":false,"memo":"构词 de-(离开)+port(运)→把人运出国境→驱逐出境，递解出境","example":"He was deported for overstaying his visa. 他因签证过期被驱逐出境。"},{"id":1379,"unit":5,"lesson":3,"word":"deportation","pronunciation":"/ˌdiːpɔːˈteɪʃn/","meaning":"n.驱逐出境;放逐","seq":7,"isStar":false,"memo":"构词 deport(驱逐)+-ation(名词后缀)→驱逐出境这一处置","example":"He now faces deportation to his home country. 他现在面临被驱逐回国。"},{"id":1380,"unit":5,"lesson":3,"word":"support","pronunciation":"/səˈpɔːt/","meaning":"n.支持,拥护;支撑物 v.支持;支撑","seq":8,"isStar":false,"memo":"构词 sup-(在下面)+port(拿、托)→从下面托住→支持；支撑；养活","example":"Her family supported her decision. 她的家人支持她的决定。"},{"id":1381,"unit":5,"lesson":3,"word":"supportive","pronunciation":"/səˈpɔːtɪv/","meaning":"adj.给予帮助的;支持的;鼓励的","seq":9,"isStar":false,"memo":"构词 support(支持)+-ive(形容词后缀)→愿意托着你的→支持的，鼓励的，同情的","example":"My parents were very supportive. 我父母非常支持我。"},{"id":1382,"unit":5,"lesson":3,"word":"supporter","pronunciation":"/səˈpɔːtə(r)/","meaning":"n.支持者,拥护者","seq":10,"isStar":false,"memo":"构词 support(支持)+-er(表人)→支持者，拥护者","example":"He is a lifelong supporter of the club. 他是这家俱乐部的终身支持者。"},{"id":1383,"unit":5,"lesson":3,"word":"endorse","pronunciation":"/ɪnˈdɔːs/","meaning":"v.(公开)赞同,支持,认可","seq":11,"isStar":false,"memo":"en-（使）+ dors（背，后背）+ -e → 在文件背面‘签’字支持！背书= endorse～","example":"The professor publicly endorsed the student-led climate initiative. 教授公开支持了由学生发起的气候倡议。"},{"id":1384,"unit":5,"lesson":3,"word":"endorsement","pronunciation":"/ɪnˈdɔːsmənt/","meaning":"n.支持,认可","seq":12,"isStar":false},{"id":1385,"unit":5,"lesson":3,"word":"transport","pronunciation":"/ˈtrænspɔːt/","meaning":"n.交通运输系统;运输工具 v.运输","seq":13,"isStar":false,"memo":"构词 trans-(横越)+port(运)→在这头那头之间运→运输；交通运输系统","example":"The goods were transported by rail. 货物通过铁路运输。"},{"id":1386,"unit":5,"lesson":3,"word":"transportation","pronunciation":"/ˌtrænspɔːˈteɪʃ(ə)n/","meaning":"n.交通运输系统","seq":14,"isStar":false,"memo":"构词 transport(运输)+-ation(名词后缀)→交通运输系统","example":"Public transportation here is cheap. 这里的公共交通很便宜。"},{"id":1387,"unit":5,"lesson":3,"word":"portion","pronunciation":"/ˈpɔːʃ(ə)n/","meaning":"n.部分;(食物的)一份","seq":15,"isStar":false,"memo":"构词 port(拿、分，同 proportion 比例)+-ion(名词后缀)→分出来的那一份→部分；(食物的)一份","example":"Give each child a small portion of rice. 给每个孩子一小份米饭。"},{"id":1388,"unit":5,"lesson":3,"word":"proportion","pronunciation":"/prəˈpɔːʃ(ə)n/","meaning":"n.比例;部分,份额","seq":16,"isStar":false,"memo":"pro-（向前）+ port（搬运，词根port=carry）+ -ion → 把‘比例’像快递一样精准‘搬运’进数据图里！饼图切几块？看proportion！","example":"The proportion of remote workers has increased sharply. 远程工作者的比例已急剧上升。"},{"id":1389,"unit":5,"lesson":3,"word":"proportional","pronunciation":"/prəˈpɔːʃən(ə)l/","meaning":"adj.成比例的;相称的","seq":17,"isStar":false},{"id":1390,"unit":5,"lesson":3,"word":"opportunity","pronunciation":"/ˌɒpəˈtjuːnəti/","meaning":"n.机会;时机","seq":18,"isStar":false,"memo":"构词 op-(朝向)+port(港口)+-unity→顺风进港的好时机→机会，时机","example":"This is a great opportunity to learn. 这是个极好的学习机会。"},{"id":1391,"unit":5,"lesson":3,"word":"porch","pronunciation":"/pɔːtʃ/","meaning":"n.门廊,走廊","seq":19,"isStar":false,"memo":"构词 port(门，同 portal 门户)+-ch→门前有遮檐的那块地→门廊，走廊","example":"We sat on the porch all evening. 我们整晚都坐在门廊上。"},{"id":1392,"unit":5,"lesson":3,"word":"portfolio","pronunciation":"/pɔːtˈfəʊliəʊ/","meaning":"n.文件夹;公文包;投资组合;作品集","seq":20,"isStar":false,"memo":"构词 port(拿)+folio(纸页)→用来夹纸页的东西→文件夹，公文包；投资组合，作品集","example":"She showed us her design portfolio. 她给我们看了她的设计作品集。"},{"id":1393,"unit":5,"lesson":3,"word":"deem","pronunciation":"/diːm/","meaning":"v.认为,相信","seq":21,"isStar":false,"memo":"联想 与 doom(厄运、判决)形近：被“判”为……→认为，相信","example":"The project was deemed a success. 这个项目被认为是成功的。"},{"id":1394,"unit":5,"lesson":3,"word":"assert","pronunciation":"/əˈsɜːt/","meaning":"v.(坚决)主张;断言","seq":22,"isStar":false,"memo":"as-sert → ‘啊嘶特！’（拍桌起身状）——不是生气，是理直气壮把观点‘坚称’出来，自带BGM！","example":"She asserted her right to speak at the meeting. 她坚称自己有权在会上发言。"},{"id":1395,"unit":5,"lesson":3,"word":"assertive","pronunciation":"/əˈsɜːtɪv/","meaning":"adj.果断的,自信的","seq":23,"isStar":false,"memo":"构词 as-(加强)+sert(放、插，同 insert 插入)+-ive(形容词后缀)→敢把自己摆出来的→果断的，自信的","example":"She is an assertive and effective manager. 她是一位果断而高效的经理。"},{"id":1396,"unit":5,"lesson":3,"word":"assertion","pronunciation":"/əˈsɜːʃ(ə)n/","meaning":"n.主张,断言,声明","seq":24,"isStar":false},{"id":1397,"unit":5,"lesson":3,"word":"insert","pronunciation":"/ɪnˈsɜːt/","meaning":"v.插入,放进","seq":25,"isStar":false,"memo":"构词 in-(向内)+sert(放、插)→放进去→插入，放进；插页广告","example":"Insert the card into the slot. 把卡插入插槽。"},{"id":1398,"unit":5,"lesson":3,"word":"insertion","pronunciation":"/ɪnˈsɜːʃn/","meaning":"n.放入,插入;插入物","seq":26,"isStar":false,"memo":"构词 insert(插入)+-ion(名词后缀)→插入的动作；插入物","example":"The insertion of a new clause delayed the vote. 新增一条条款使表决推迟了。"},{"id":1399,"unit":5,"lesson":3,"word":"claim","pronunciation":"/kleɪm/","meaning":"n.声明,宣称;索赔 v.宣称,声称","seq":27,"isStar":false,"memo":"【谐音】‘克雷姆’→ 你抢（claim）走我的奶茶？我立刻‘克雷姆’（claim）索赔！声调上扬像抗议。","example":"The researcher claimed priority in discovering the new enzyme. 研究员声称自己最先发现这种新酶。"},{"id":1400,"unit":5,"lesson":3,"word":"exclaim","pronunciation":"/ɪkˈskleɪm/","meaning":"v.(尤因强烈的情感或痛苦而)惊叫,呼喊","seq":28,"isStar":false,"memo":"【构词】ex-（出）+ claim（喊，同claim‘宣称’）→ 声音‘喊出来’！不是慢慢说，是突然‘啊！’一声蹦出口～","example":"She exclaimed in surprise when she saw the unexpected gift. 她看到意外礼物时惊叫起来。"},{"id":1401,"unit":5,"lesson":3,"word":"exclamation","pronunciation":"/ˌekskləˈmeɪʃ(ə)n/","meaning":"n.感叹;感叹词","seq":29,"isStar":false},{"id":1402,"unit":5,"lesson":3,"word":"exclamatory","pronunciation":"/ɪkˈsklæmətri; ekˈsklæmətri/","meaning":"adj.表示感叹的;惊叹的","seq":30,"isStar":false,"memo":"构词 ex-(向外)+clam(喊，同 claim 大声主张)+-atory(形容词后缀)→大声喊出来的→表示感叹的，惊叹的","example":"What a lovely day is an exclamatory sentence. What a lovely day 是一个感叹句。"},{"id":1403,"unit":5,"lesson":3,"word":"acclaim","pronunciation":"/əˈkleɪm/","meaning":"v.称赞,为……喝彩;推崇","seq":31,"isStar":false,"memo":"构词 ac-(加强)+claim(喊)→对着某人使劲喊好→称赞，为……喝彩，推崇","example":"The film was acclaimed by critics. 这部电影受到评论家的称赞。"},{"id":1404,"unit":5,"lesson":3,"word":"proclaim","pronunciation":"/prəˈkleɪm/","meaning":"v.宣布,宣告;声明","seq":32,"isStar":false,"memo":"【构词】pro-（向前）+ claim（喊叫）→往前一喊，全城都听见！就像校长站主席台大喇叭宣布放假。","example":"The government proclaimed a state of emergency after the earthquake. 地震后，政府宣布进入紧急状态。"},{"id":1405,"unit":5,"lesson":3,"word":"proclamation","pronunciation":"/ˌprɒkləˈmeɪʃ(ə)n/","meaning":"n.宣言;公告;声明","seq":33,"isStar":false},{"id":1406,"unit":5,"lesson":3,"word":"declare","pronunciation":"/dɪˈkleə(r)/","meaning":"v.公布,宣布,宣告","seq":34,"isStar":false,"memo":"de-（完全）+clare（清晰，词根clara=clear）→把事情‘彻底说清’，就是宣布！","example":"The government declared a state of emergency after the severe flood. 政府在严重洪灾后宣布进入紧急状态。"},{"id":1407,"unit":5,"lesson":3,"word":"declaration","pronunciation":"/ˌdekləˈreɪʃ(ə)n/","meaning":"n.公告;宣言","seq":35,"isStar":false},{"id":1408,"unit":5,"lesson":3,"word":"declarative","pronunciation":"/dɪˈklærətɪv/","meaning":"adj.陈述的","seq":36,"isStar":false},{"id":1409,"unit":5,"lesson":3,"word":"allege","pronunciation":"/əˈledʒ/","meaning":"v.(未经证实的)宣称,指控","seq":37,"isStar":false,"memo":"【构词】al-（加强）+ leg（法律，词根leg-表‘说’）→‘正式开口说’，但没证据！就像同学说‘我看见他抄答案’——allege，不等于 proven！","example":"The report alleges serious misconduct by senior management. 报告指控高级管理层存在严重失当行为。"},{"id":1410,"unit":5,"lesson":3,"word":"allegation","pronunciation":"/ˌæləˈɡeɪʃn/","meaning":"n.(无证据的)说法,指控","seq":38,"isStar":false},{"id":1411,"unit":5,"lesson":3,"word":"alleged","pronunciation":"/əˈledʒd/","meaning":"adj.被指控的,涉嫌的","seq":39,"isStar":false,"memo":"构词 al-(加强)+leg(法律，同 legal 合法的)+-ed→照法律“声称”但尚未证实的→被指控的，涉嫌的","example":"He denied the alleged crime. 他否认了被指控的罪行。"},{"id":1412,"unit":5,"lesson":3,"word":"allegedly","pronunciation":"/əˈledʒɪdli/","meaning":"adv.据说","seq":40,"isStar":false,"memo":"构词 alleged(被指控的)+-ly(副词后缀)→据称，据说","example":"He allegedly took money from the company. 据称他拿了公司的钱。"},{"id":1413,"unit":5,"lesson":3,"word":"pledge","pronunciation":"/pledʒ/","meaning":"v.作保证,发誓 n.保证,诺言","seq":41,"isStar":false,"memo":"ple-（please请）+ dge（像‘姐’）→‘请姐’作证！拉钩发誓，郑重承诺！","example":"The company pledged to reduce its carbon emissions by 2030. 该公司承诺于2030年前降低碳排放量。"},{"id":1414,"unit":5,"lesson":3,"word":"swear","pronunciation":"/sweə(r)/","meaning":"v.发誓,宣誓;诅咒","seq":42,"isStar":false,"memo":"联想 与 answer 押韵：被人问起时要“发誓”→发誓，宣誓；也指咒骂","example":"He swore to tell the truth. 他发誓要说真话。"},{"id":1415,"unit":5,"lesson":3,"word":"vow","pronunciation":"/vaʊ/","meaning":"n.誓言;誓约 v.发誓,立誓","seq":43,"isStar":false,"memo":"联想 与 vote(投票)形近：投下选票前先立个“誓”→誓言，誓约；发誓，立誓","example":"They vowed to stay together. 他们发誓要在一起。"},{"id":1416,"unit":5,"lesson":3,"word":"assure","pronunciation":"/əˈʃʊə(r)/","meaning":"v.使确信,向……保证;确保","seq":44,"isStar":false,"memo":"【构词】a（加强）+ sure（确定）→ 双sure！向你打包票‘sure sure’，保证没跑儿～","example":"The manager assured employees that layoffs would not affect their departments. 经理向员工保证裁员不会影响他们的部门。"},{"id":1417,"unit":5,"lesson":3,"word":"assurance","pronunciation":"/əˈʃʊərəns/","meaning":"n.保证,确信","seq":45,"isStar":false},{"id":1418,"unit":5,"lesson":3,"word":"reassure","pronunciation":"/ˌriːəˈʃʊə(r)/","meaning":"v.使……安心;打消……的疑虑","seq":46,"isStar":false,"memo":"re-（再）+assure（确保）→‘再保你稳’！就像妈拍拍你肩：‘别慌，妈在！’——双重保险，焦虑秒变安心。","example":"The doctor reassured her that the test results were normal. 医生让她放心，检查结果正常。"},{"id":1419,"unit":5,"lesson":3,"word":"reassurance","pronunciation":"/ˌriːəˈʃʊərəns; ˌriːəˈʃɔːrəns/","meaning":"n.(能消除疑虑等的)肯定,保证","seq":47,"isStar":false},{"id":1420,"unit":5,"lesson":3,"word":"ensure","pronunciation":"/ɪnˈʃʊə(r)/","meaning":"v.保证,确保","seq":48,"isStar":false,"memo":"en-（使）+ sure（确定）→ 让某事‘sure’起来！不是‘insure’（投保），别被‘保险’带跑偏～","example":"The university uses AI tools to ensure exam fairness and prevent cheating. 该校使用人工智能工具确保考试公平并防止作弊。"},{"id":1421,"unit":5,"lesson":3,"word":"insure","pronunciation":"/ɪnˈʃʊə(r)/","meaning":"v.投保,给……保险;接受投保,承保","seq":49,"isStar":false,"memo":"in（进入）+ sure（稳）→ 让风险‘进’来变‘稳’！投保险就是花钱买心安——sure不等于sure，但insure之后，sure多了！","example":"Students are advised to insure their laptops against accidental damage. 学生被建议为笔记本电脑投保意外损坏险。"},{"id":1422,"unit":5,"lesson":3,"word":"insurance","pronunciation":"/ɪnˈʃʊərəns/","meaning":"n.保险;保险费","seq":50,"isStar":false},{"id":1423,"unit":5,"lesson":3,"word":"guarantee","pronunciation":"/ˌɡærənˈtiː/","meaning":"n.保证;担保;保证金;抵押品 v.保证","seq":51,"isStar":false,"memo":"guar-（=war，战争）+ -antee（保证人）→战前签‘保命协议’！v./n.保证，带法律效力的‘不翻车承诺’。","example":"The warranty guarantees repair service for three years. 保修期保证三年内提供维修服务。"},{"id":1424,"unit":5,"lesson":3,"word":"persuade","pronunciation":"/pəˈsweɪd/","meaning":"v.劝说,说服;使信服","seq":52,"isStar":false,"memo":"per-（彻底）+ suade（劝→拉丁suadere）→‘彻底劝到服’！记成‘怕说服’——怕你嘴太强，一说我就缴械投降。","example":"She persuaded the committee to fund the environmental project. 她说服委员会为环保项目提供资金。"},{"id":1425,"unit":5,"lesson":3,"word":"persuasion","pronunciation":"/pəˈsweɪʒ(ə)n/","meaning":"n.说服;劝说","seq":53,"isStar":false},{"id":1426,"unit":5,"lesson":3,"word":"persuasive","pronunciation":"/pəˈsweɪsɪv/","meaning":"adj.有说服力的","seq":54,"isStar":false},{"id":1427,"unit":5,"lesson":3,"word":"promise","pronunciation":"/ˈprɒmɪs/","meaning":"n.保证,诺言,承诺;迹象 v.承诺","seq":55,"isStar":false,"memo":"构词 pro-(向前)+mis(送，同 mission 派遣)+-e→把话先送出去→承诺，诺言；迹象","example":"He promised to call me tonight. 他答应今晚给我打电话。"},{"id":1428,"unit":5,"lesson":3,"word":"promising","pronunciation":"/ˈprɒmɪsɪŋ/","meaning":"adj.大有希望的,很有前途的","seq":56,"isStar":false,"memo":"构词 promise(承诺、前景)+-ing(形容词后缀)→前景可期的→大有希望的，很有前途的","example":"She is a promising young singer. 她是一位很有前途的年轻歌手。"},{"id":1429,"unit":5,"lesson":3,"word":"premise","pronunciation":"/ˈpremɪs/","meaning":"n.前提","seq":57,"isStar":false,"memo":"构词 pre-(在前)+mis(送、放)+-e→放在最前面的那句话→前提","example":"The argument rests on a false premise. 这个论证建立在一个错误的前提之上。"},{"id":1430,"unit":5,"lesson":3,"word":"compromise","pronunciation":"/ˈkɒmprəmaɪz/","meaning":"n.妥协,折中","seq":58,"isStar":false,"memo":"构词 com-(共同)+promis(承诺)+-e→双方共同许下让步的承诺→妥协，折中；放弃(原则)","example":"Both sides had to compromise. 双方都不得不作出让步。"},{"id":1431,"unit":5,"lesson":3,"word":"infinite","pronunciation":"/ˈɪnfɪnət/","meaning":"adj.无限的,无穷的","seq":59,"isStar":false,"memo":"构词 in-(否定)+fin(界限，同 finish 结束)+-ite(形容词后缀)→没有界限的→无限的，无穷的","example":"Space seems infinite. 太空似乎是无限的。"},{"id":1432,"unit":5,"lesson":3,"word":"infinity","pronunciation":"/ɪnˈfɪnəti/","meaning":"n.无限,无穷","seq":60,"isStar":false,"memo":"构词 in-(否定)+fin(界限)+-ity(名词后缀)→没有界限的状态→无限，无穷","example":"Parallel lines meet at infinity. 平行线在无穷远处相交。"},{"id":1433,"unit":5,"lesson":3,"word":"infinitive","pronunciation":"/ɪnˈfɪnətɪv/","meaning":"n.不定式","seq":61,"isStar":false,"memo":"构词 in-(否定)+fin(界限)+-itive(形容词后缀)→不受人称限定的动词形式→不定式","example":"In English the infinitive is usually formed with to. 英语中的不定式通常由 to 构成。"},{"id":1434,"unit":5,"lesson":3,"word":"finite","pronunciation":"/ˈfaɪnaɪt/","meaning":"adj.有限制的,有限的;限定的","seq":62,"isStar":false,"memo":"构词 fin(界限，同 finish 结束)+-ite(形容词后缀)→有界限的→有限的，有限制的","example":"The earth has finite resources. 地球的资源是有限的。"},{"id":1435,"unit":5,"lesson":3,"word":"define","pronunciation":"/dɪˈfaɪn/","meaning":"v.解释,说明;给……下定义;阐明,界定","seq":63,"isStar":false,"memo":"de-（完全）+fine（界限）→给概念划出‘完全清晰的界限’，就是下定义！","example":"Philosophers continue to define what constitutes genuine artificial intelligence. 哲学家们仍在界定何为真正的人工智能。"},{"id":1436,"unit":5,"lesson":3,"word":"definite","pronunciation":"/ˈdefɪnət/","meaning":"adj.肯定的,确定的;明显的,清楚的","seq":64,"isStar":false,"memo":"构词 de-(加强)+fin(界限)+-ite(形容词后缀)→界限划得很清的→肯定的，确定的，明显的","example":"We need a definite answer. 我们需要一个明确的答复。"},{"id":1437,"unit":5,"lesson":3,"word":"definitely","pronunciation":"/ˈdefɪnətli/","meaning":"adv.确切地;明确地;清楚地","seq":65,"isStar":false,"memo":"构词 definite(确定的)+-ly(副词后缀)→确切地，明确地；口语中也表示“当然”","example":"I will definitely be there. 我一定会到场。"},{"id":1438,"unit":5,"lesson":3,"word":"definition","pronunciation":"/ˌdefɪˈnɪʃ(ə)n/","meaning":"n.解释;定义","seq":66,"isStar":false},{"id":1439,"unit":5,"lesson":3,"word":"indefinite","pronunciation":"/ɪnˈdefɪnət/","meaning":"adj.模糊不清的,不明确的;无限期的","seq":67,"isStar":false,"memo":"构词 in-(否定)+definite(确定的)→不确定的→模糊不清的，不明确的；无限期的","example":"He is on indefinite leave. 他请了无限期的假。"},{"id":1440,"unit":5,"lesson":3,"word":"refine","pronunciation":"/rɪˈfaɪn/","meaning":"v.精炼,提炼;改进","seq":68,"isStar":false,"memo":"拆解：re-（再次）+ fine（精细）→ 再次弄‘精细’！谐音‘瑞饭’——米其林大厨瑞饭（再饭）？不，是再‘炼’饭（精炼食材）！","example":"Engineers continue to refine the algorithm for better accuracy. 工程师持续优化算法以提高准确性。"},{"id":1441,"unit":5,"lesson":3,"word":"refinement","pronunciation":"/rɪˈfaɪnmənt/","meaning":"n.精炼,提炼,提纯;改进,改善","seq":69,"isStar":false},{"id":1442,"unit":5,"lesson":3,"word":"refinery","pronunciation":"/rɪˈfaɪnəri/","meaning":"n.炼油厂,提炼厂,精炼厂,精制厂","seq":70,"isStar":false,"memo":"构词 re-(再)+fin(精细，同 refine 提炼)+-ery(表场所)→反复提炼的地方→炼油厂，提炼厂","example":"The refinery processes crude oil. 这家炼油厂加工原油。"},{"id":1443,"unit":5,"lesson":3,"word":"distil(l)","pronunciation":"/dɪˈstɪl/","meaning":"v.蒸馏;用蒸馏法提取;提炼;浓缩","seq":71,"isStar":false,"memo":"构词 di-(向下)+stil(滴，同 instil 滴入)→让液体一滴滴落下来→蒸馏，提炼，浓缩","example":"Salt water can be distilled into fresh water. 海水可以蒸馏成淡水。"},{"id":1444,"unit":5,"lesson":3,"word":"confine","pronunciation":"/kənˈfaɪn/","meaning":"v.约束,限定,限制;使离不开","seq":72,"isStar":false,"memo":"【谐音+构词】'康芬'→康师傅方便面被‘限定口味’！con-（共同）+ fine（界限）→一起划条线，把你框住。","example":"Remote learning should not confine students' creativity to digital platforms. 远程学习不应将学生的创造力局限在数字平台上。"},{"id":1445,"unit":5,"lesson":3,"word":"confinement","pronunciation":"/kənˈfaɪnmənt/","meaning":"n.禁闭,监禁,关押","seq":73,"isStar":false},{"id":1446,"unit":5,"lesson":3,"word":"restrain","pronunciation":"/rɪˈstreɪn/","meaning":"v.阻止,制止,约束","seq":74,"isStar":false,"memo":"【构词】re-(再)+strain(拉紧)→反复勒紧缰绳→抑制冲动，像拽住狂奔的马！","example":"Judges must restrain personal bias when evaluating evidence. 法官在评估证据时必须克制个人偏见。"},{"id":1447,"unit":5,"lesson":3,"word":"restraint","pronunciation":"/rɪˈstreɪnt/","meaning":"n.约束力;限制,克制","seq":75,"isStar":false},{"id":1448,"unit":5,"lesson":3,"word":"constrain","pronunciation":"/kənˈstreɪn/","meaning":"v.阻止;限制","seq":76,"isStar":false,"memo":"构词 con-(一起)+strain(拉紧，同 strain 拉紧)→把绳子拉紧绑住→阻止，限制","example":"Lack of money constrained our plans. 资金不足限制了我们的计划。"},{"id":1449,"unit":5,"lesson":3,"word":"constraint","pronunciation":"/kənˈstreɪnt/","meaning":"n.限制,限定,约束","seq":77,"isStar":false,"memo":"构词 constrain(限制)+-t(名词后缀)→限制的条件→限制，约束","example":"Time constraints forced us to stop. 时间限制迫使我们停了下来。"},{"id":1450,"unit":5,"lesson":3,"word":"stifle","pronunciation":"/ˈstaɪf(ə)l/","meaning":"v.阻止,抑制,压抑(感情)","seq":78,"isStar":false,"memo":"记 (谐音) 单词发音类似“死大夫”→大夫为了“阻止”病人死去,做了很多努力。","example":"Stiff rules and regulations stifle innovation.僵化的规章制度扼杀了创新。"},{"id":1451,"unit":5,"lesson":3,"word":"strain","pronunciation":"/streɪn/","meaning":"n.焦虑,紧张;负担;拉力 v.拉伤","seq":79,"isStar":false,"memo":"st(联想 street)+rain(雨)→雨后街上变冷,我“拉紧”了衣服领子。","example":"The woman may be suffering from repetitive strain injury. 这位女士可能患有重复性劳损。"},{"id":1452,"unit":5,"lesson":3,"word":"chill","pronunciation":"/tʃɪl/","meaning":"adj.寒冷的,冷飕飕的 n.寒冷;寒战","seq":80,"isStar":false,"memo":"chi(联想“吃”)+ll(形似两支冰棍)→数九寒天,我吃了两支冰棍,“寒冷的”感觉直冲心底。","example":"A small fire was burning to take the chill off the room. 房间里生着一个小火炉驱寒。"},{"id":1453,"unit":5,"lesson":3,"word":"chilly","pronunciation":"/ˈtʃɪli/","meaning":"adj.寒冷的;阴冷的","seq":81,"isStar":false,"memo":"构词 chill(寒冷)+-y(形容词后缀)→冷飕飕的→寒冷的，阴冷的","example":"It was a chilly autumn morning. 那是一个寒冷的秋日早晨。"},{"id":1454,"unit":5,"lesson":3,"word":"thermal","pronunciation":"/ˈθɜːm(ə)l/","meaning":"adj.热的,保暖的,温暖的","seq":82,"isStar":false,"memo":"单词发音类似“塞毛”→天冷了,往衣服里面塞些毛可起到“保暖的”作用。","example":"The thermal springs are popular tourist attractions. 温泉是受欢迎的旅游景点。"},{"id":1455,"unit":5,"lesson":3,"word":"cosy/cozy","pronunciation":"/ˈkəʊzi/","meaning":"adj.暖和舒适的;密切的,亲密无间的","seq":83,"isStar":false,"memo":"联想 与“小屋”义同源：小屋里又暖和又亲密→暖和舒适的；密切的，轻松的","example":"The room was warm and cosy. 这个房间温暖又舒适。"},{"id":1456,"unit":5,"lesson":3,"word":"cosily/cozily","pronunciation":"/ˈkəʊzɪli/","meaning":"adv.温暖舒适地;密切地","seq":84,"isStar":false,"memo":"构词 cosy(舒适的)+-ly(副词后缀)→温暖舒适地；密切地","example":"They sat cosily by the fire. 他们舒适地坐在炉火旁。"},{"id":1457,"unit":5,"lesson":4,"word":"block","pronunciation":"/blɒk/","meaning":"n.大块;街区;大楼;障碍物 v.阻碍","seq":1,"isStar":false,"memo":"谐音 单词发音类似“不唠嗑”→他俩不唠嗑了,因为有人“阻碍”了他们的交流。","example":"After today's heavy snow, many roads are still blocked. 今天下过大雪,很多道路仍然堵塞。"},{"id":1458,"unit":5,"lesson":4,"word":"bloc","pronunciation":"/blɒk/","meaning":"n.集团,阵营","seq":2,"isStar":false,"memo":"记 (对照) 这个街区(block)是该集团(bloc)的地盘。","example":"This will not solve the bloc's larger problem.这并不能解决这个集团更大的问题。"},{"id":1459,"unit":5,"lesson":4,"word":"company","pronunciation":"/ˈkʌmpəni/","meaning":"n.公司;陪伴;剧团;同伴","seq":3,"isStar":false,"memo":"构词 com-(一起)+pan(面包，同 pantry 食品储藏室)+-y→一起吃面包的人→公司；陪伴；同伴","example":"She'll have been with the company for 25 years next week. 到下周,她就在公司工作25年了。"},{"id":1460,"unit":5,"lesson":4,"word":"accompany","pronunciation":"/əˈkʌmpəni/","meaning":"v.陪伴;伴随;为……伴奏","seq":4,"isStar":false,"memo":"构词 ac-(=to)+company(陪伴)→陪伴(……去)→陪伴;伴随","example":"Bad weather is accompanied by strong winds. 坏天气伴有强风。"},{"id":1461,"unit":5,"lesson":4,"word":"companion","pronunciation":"/kəmˈpænjən/","meaning":"n.伴侣,同伴;伙伴","seq":5,"isStar":false,"memo":"对照 公司(company)的陪伴(companion)使我梦想渐近,未来可期。","example":"He was my companion on the journey. 他是我旅途中的伙伴。"},{"id":1462,"unit":5,"lesson":4,"word":"companionship","pronunciation":"/kəmˈpænjənʃɪp/","meaning":"n.友情,交谊","seq":6,"isStar":false},{"id":1463,"unit":5,"lesson":4,"word":"multiply","pronunciation":"/ˈmʌltɪplaɪ/","meaning":"v.乘;(使)成倍增加;(使)大大增加","seq":7,"isStar":false,"memo":"联想 multi-(多)+ply(音似“扑来”)→多地扑来→繁殖","example":"A species must be able to multiply quickly in order to survive. 一个物种必须能够迅速繁殖才能生存。"},{"id":1464,"unit":5,"lesson":4,"word":"multiplication","pronunciation":"/ˌmʌltɪplɪˈkeɪʃ(ə)n/","meaning":"n.乘;相乘;增加","seq":8,"isStar":false,"memo":"构词 multi(多，同 multiple 多种的)+plic(折叠，同 complex 复杂的)+-ation(名词后缀)→多次相加→乘法；增加","example":"She is learning her multiplication tables. 她正在背乘法口诀。"},{"id":1465,"unit":5,"lesson":4,"word":"multiple","pronunciation":"/ˈmʌltɪp(ə)l/","meaning":"adj.数量多的;多种的 n.倍数","seq":9,"isStar":false,"memo":"构词 multi(多)+-ple(折叠)→叠了很多层的→数量多的，多种的；倍数","example":"The shape appears multiple times within each painting.该形状在每幅画中出现多次。"},{"id":1466,"unit":5,"lesson":4,"word":"multitude","pronunciation":"/ˈmʌltɪtjuːd/","meaning":"n.众多,大量;群众,民众","seq":10,"isStar":false,"memo":"构词 multi(多)+-tude(名词后缀)→多到成群的数量→众多，大量；群众，民众","example":"The English language contains a multitude of words which are seldom used in ordinary conversation.英语中有大量在普通对话中很少使用的词汇。"},{"id":1467,"unit":5,"lesson":4,"word":"affiliate","pronunciation":"/əˈfɪlieɪt/","meaning":"n.附属机构,分公司 v.使隶属,使并入","seq":11,"isStar":false,"memo":"联想 af-(=to)+fili(联想“费力”)+-ate(后缀)→使费力地依附到→附属机构;使隶属","example":"The World Chess Federation has affiliates in around 120 countries.世界国际象棋联合会在大约120个国家拥有附属机构。"},{"id":1468,"unit":5,"lesson":4,"word":"affiliation","pronunciation":"/əˌfɪliˈeɪʃ(ə)n/","meaning":"n.隶属关系;隶属,从属","seq":12,"isStar":false},{"id":1469,"unit":5,"lesson":4,"word":"auxiliary","pronunciation":"/ɔːɡˈzɪliəri/","meaning":"adj.辅助的;备用的 n.助动词","seq":13,"isStar":false,"memo":"联想 aux(联想“奥克斯”)+i(我)+li(音似“里”)+-ary(后缀)→奥克斯空调在我屋里起到“辅助的”降温作用。","example":"Nursing auxiliaries provide basic care, but are not qualified nurses.助理护士提供基本护理,但不具备护士资格。"},{"id":1470,"unit":5,"lesson":4,"word":"affix","pronunciation":"/əˈfɪks/","meaning":"n.词缀 v.粘上,贴上;附上","seq":14,"isStar":false,"memo":"构词 af-(加强，ad- 的变体)+fix(固定)→固定在词上或物上的东西→词缀；粘上，附上","example":"The stamp is affixed to the envelope. 邮票贴在信封上。"},{"id":1471,"unit":5,"lesson":4,"word":"affixation","pronunciation":"/ˌæfɪksˈeɪʃ(ə)n/","meaning":"n.附加;加词缀法","seq":15,"isStar":false,"memo":"构词 affix(词缀)+-ation(名词后缀)→添加词缀的构词方式→附加；加词缀法","example":"Affixation is a common way of forming new words. 加词缀是常见的构词方式。"},{"id":1472,"unit":5,"lesson":4,"word":"firm","pronunciation":"/fɜːm/","meaning":"n.商行,公司 adj.牢固的,坚固的","seq":16,"isStar":false,"memo":"对照 公司(firm)需要形成(form)一个牢固的(firm)支撑体系。","example":"I know that your firm has a very good reputation.我知道贵公司声誉很好。"},{"id":1473,"unit":5,"lesson":4,"word":"affirm","pronunciation":"/əˈfɜːm/","meaning":"v.肯定属实;申明;断言","seq":17,"isStar":false,"memo":"构词 af-(=to)+firm(坚定的)→对……是肯定的→肯定属实;断言","example":"Both sides affirmed their commitment to the ceasefire.双方均申明答应停火。"},{"id":1474,"unit":5,"lesson":4,"word":"affirmation","pronunciation":"/ˌæfəˈmeɪʃ(ə)n/","meaning":"n.断言;肯定","seq":18,"isStar":false},{"id":1475,"unit":5,"lesson":4,"word":"affirmative","pronunciation":"/əˈfɜːmətɪv/","meaning":"n.肯定;同意 adj.肯定的;同意的","seq":19,"isStar":false},{"id":1476,"unit":5,"lesson":4,"word":"enterprise","pronunciation":"/ˈentəpraɪz/","meaning":"n.公司,企业","seq":20,"isStar":false,"memo":"联想 enter(进来)+prise(联想 praise)→“公司”的老板一进来就表扬他。","example":"The middle class used to be loyal to the free enterprise system.中产阶级曾经对自由企业制度忠心耿耿。"},{"id":1477,"unit":5,"lesson":4,"word":"enterprising","pronunciation":"/ˈentəpraɪzɪŋ/","meaning":"adj.有事业心的;有进取心的","seq":21,"isStar":false},{"id":1478,"unit":5,"lesson":4,"word":"entrepreneur","pronunciation":"/ˌɒntrəprəˈnɜː(r)/","meaning":"n.创业者,企业家","seq":22,"isStar":false,"example":"An entrepreneur is more than just a risk taker.企业家不仅仅是一个冒险者。"},{"id":1479,"unit":5,"lesson":4,"word":"entrepreneurial","pronunciation":"/ˌɒntrəprəˈnɜːriəl/","meaning":"adj.创业的;企业家的","seq":23,"isStar":false},{"id":1480,"unit":5,"lesson":4,"word":"commerce","pronunciation":"/ˈkɒmɜːs/","meaning":"n.商业,贸易","seq":24,"isStar":false,"memo":"[联想] com-(都) + merce(音似“没死”)→商场如大海,一旦翻船就都会被淹没→商业,贸易","example":"During this decade new forms of commerce became commonplace in the US. 在这十年中,新的商业形式在美国变得司空见惯。"},{"id":1481,"unit":5,"lesson":4,"word":"commercial","pronunciation":"/kəˈmɜːʃ(ə)l/","meaning":"n.商业广告 adj.商业的,贸易的","seq":25,"isStar":false,"memo":"【谐音】‘康麦休尔’→超市里卖康师傅、麦当劳、休眠熊（？）→全是商业品牌！广告也叫commercial～","example":"The TV channel interrupted the documentary with three commercial breaks. 电视频道插播了三次广告打断了纪录片。"},{"id":1482,"unit":5,"lesson":4,"word":"commercialise/-ize","pronunciation":"/kəˈmɜːʃəlaɪz/","meaning":"v.利用……牟利;商业化","seq":26,"isStar":false,"memo":"构词 commercial(商业的)+-ise/-ize(使…化)→使变成商业行为→商业化，利用……牟利","example":"They commercialised the traditional festival. 他们把这个传统节日商业化了。"},{"id":1483,"unit":5,"lesson":4,"word":"commodity","pronunciation":"/kəˈmɒdəti/","meaning":"n.商品;有用的东西,有使用价值的事物","seq":27,"isStar":false,"memo":"构词 commod(合用、方便，同 accommodate 容纳)+-ity(名词后缀)→合用又能交易之物→商品；有使用价值的事物","example":"Money as a tangible commodity has largely been replaced by credit. 货币作为一种有形的商品在很大程度上已被信贷取代。"},{"id":1484,"unit":5,"lesson":4,"word":"merchant","pronunciation":"/ˈmɜːtʃənt/","meaning":"n.商人,批发商","seq":28,"isStar":false,"memo":"[谐音] 单词发音类似“摸钱他”→他是个“商人”,每天攒钱,和钱打交道。","example":"Venice was once a city of rich merchants. 威尼斯曾是富商云集的城市。"},{"id":1485,"unit":5,"lesson":4,"word":"merchandise","pronunciation":"/ˈmɜːtʃəndaɪs/","meaning":"n.商品,货品","seq":29,"isStar":false,"memo":"merch（=market市场）+andise→市场上卖的东西！谐音‘卖钱的易死’——商品太卷，不卖钱就易死。","example":"Online platforms revolutionize how we browse merchandise. 在线平台彻底改变了我们浏览商品的方式。"},{"id":1486,"unit":5,"lesson":4,"word":"sale","pronunciation":"/seɪl/","meaning":"n.出售,销售;销售量;特价销售","seq":30,"isStar":false,"memo":"[对照] sell v.出售,售卖→sale n.","example":"Its production and sales reached record levels. 它的生产和销售量达到了创纪录的水平。"},{"id":1487,"unit":5,"lesson":4,"word":"wholesale","pronunciation":"/ˈhəʊlseɪl/","meaning":"n.批发 adj.大规模的","seq":31,"isStar":false,"memo":"构词 whole(整个的) + sale(出售)→整个出售→批发","example":"We sell wholesale to several chains that sell retail to the public.我们向几家批发商供货，他们再向公众零售。"},{"id":1488,"unit":5,"lesson":4,"word":"retail","pronunciation":"/ˈriːteɪl/","meaning":"n.零售 v.零售 adv.以零售方式","seq":32,"isStar":false,"memo":"[构词] re-(再,重复) + tail(= cut,切,割)→重复切割单卖→零售","example":"It poses a potential threat to the retail business in the US. 这对美国的零售业务构成了潜在威胁。"},{"id":1489,"unit":5,"lesson":4,"word":"retailer","pronunciation":"/ˈriːteɪlə(r)/","meaning":"n.零售商","seq":33,"isStar":false},{"id":1490,"unit":5,"lesson":4,"word":"entail","pronunciation":"/ɪnˈteɪl/","meaning":"v.牵涉;需要,使必要","seq":34,"isStar":false,"memo":"[联想] en-(使) + tail(切)→使切分成……的一部分→牵涉;使必要","example":"The job entails a lot of travel. 这份工作需要经常出差。"},{"id":1491,"unit":5,"lesson":4,"word":"afford","pronunciation":"/əˈfɔːd/","meaning":"v.买得起;(有时间)做","seq":35,"isStar":false,"memo":"联想 af-(一再地)+ford(音似“福特”)→他一再地提福特车是因为“买得起”它。","example":"She can't afford the time for the trip. 她抽不出时间去旅行。"},{"id":1492,"unit":5,"lesson":4,"word":"affordable","pronunciation":"/əˈfɔːdəb(ə)l/","meaning":"adj.便宜的;负担得起的","seq":36,"isStar":false},{"id":1493,"unit":5,"lesson":4,"word":"affordability","pronunciation":"/əˌfɔːdəˈbɪləti/","meaning":"n.负担能力","seq":37,"isStar":false},{"id":1494,"unit":5,"lesson":4,"word":"purchase","pronunciation":"/ˈpɜːtʃəs/","meaning":"n.买;购买的物品 v.买,购买","seq":38,"isStar":false,"memo":"谐音 单词发音类似“破车子”→既然车子破旧了，那就“买”辆新的吧。","example":"The tickets can only be purchased in advance from our website. 门票只能在我们的网站上提前购买。"},{"id":1495,"unit":5,"lesson":4,"word":"board","pronunciation":"/bɔːd/","meaning":"n.板,木板;董事会 v.登上(公共汽车","seq":39,"isStar":false,"memo":"对照 黑板(blackboard)就是黑色的板(board)。","example":"He's on the board of directors. 他是董事会成员。"},{"id":1496,"unit":5,"lesson":4,"word":"corporation","pronunciation":"/ˌkɔːpəˈreɪʃ(ə)n/","meaning":"n.(大)公司,企业","seq":40,"isStar":false,"memo":"联想 cor-(联想 con-，一起)+por(音似“破”)+-ation(名词后缀)→“公司”领导要求大家一起攻破难关。","example":"The corporation is rejecting more and more candidates applying for jobs. 公司正在拒绝越来越多的求职者。"},{"id":1497,"unit":5,"lesson":4,"word":"corporate","pronunciation":"/ˈkɔːpərət/","meaning":"adj.公司的;团体的;全体的","seq":41,"isStar":false},{"id":1498,"unit":5,"lesson":4,"word":"incorporate","pronunciation":"/ɪnˈkɔːpəreɪt/","meaning":"v.将……并入,包含","seq":42,"isStar":false,"memo":"联想 in(入)+corporate(公司的)→使进入公司的里面→将……并入","example":"Many of your suggestions have been incorporated in the plan. 你的很多建议已被纳入计划中。"},{"id":1499,"unit":5,"lesson":4,"word":"incorporation","pronunciation":"/ɪnˌkɔːpəˈreɪʃn/","meaning":"n.纳入,合并;公司;团体组织","seq":43,"isStar":false},{"id":1500,"unit":5,"lesson":4,"word":"compete","pronunciation":"/kəmˈpiːt/","meaning":"v.参加比赛;竞争","seq":44,"isStar":false,"memo":"联想 com(联想 company)+pete(联想 pk)→公司之间pk，就是“竞争”。","example":"Ten teams competed for the prize. 十支队伍角逐这个奖项。"},{"id":1501,"unit":5,"lesson":4,"word":"competitor","pronunciation":"/kəmˈpetɪtə(r)/","meaning":"n.竞争者","seq":45,"isStar":false},{"id":1502,"unit":5,"lesson":4,"word":"competition","pronunciation":"/ˌkɒmpəˈtɪʃ(ə)n/","meaning":"n.竞争;比赛","seq":46,"isStar":false},{"id":1503,"unit":5,"lesson":4,"word":"competitive","pronunciation":"/kəmˈpetətɪv/","meaning":"adj.竞争的;有竞争力的;好胜的","seq":47,"isStar":false},{"id":1504,"unit":5,"lesson":4,"word":"competent","pronunciation":"/ˈkɒmpɪtənt/","meaning":"adj.有能力的,能胜任的","seq":48,"isStar":false,"memo":"com-（一起）+pet（寻求，如petition）+ent→大家一起‘求’出来的能力？不！其实是com（完全）+pet（追求）+ent→追求到位=胜任！","example":"A competent engineer must balance theory and practice. 合格的工程师必须兼顾理论与实践。"},{"id":1505,"unit":5,"lesson":4,"word":"competence","pronunciation":"/ˈkɒmpɪtəns/","meaning":"n.能力;技能","seq":49,"isStar":false,"example":"Poetry is no substitute for courage or competence.诗歌不能替代勇气或能力。"},{"id":1506,"unit":5,"lesson":4,"word":"versus","pronunciation":"/ˈvɜːsəs/","meaning":"prep.(比赛或诉讼中)……对……","seq":50,"isStar":false,"memo":"联想 各种比赛中经常出现的 vs 就是 versus 的缩写。","example":"It is France versus Brazil in the final.决赛是法国对巴西。"},{"id":1507,"unit":5,"lesson":4,"word":"operate","pronunciation":"/ˈɒpəreɪt/","meaning":"v.经营,营业;操作;动手术","seq":51,"isStar":false,"example":"The airline operates flights to 25 countries.这家航空公司运营飞往25个国家的航班。"},{"id":1508,"unit":5,"lesson":4,"word":"operative","pronunciation":"/ˈɒpərətɪv/","meaning":"n.工人,(尤指)技术工人","seq":52,"isStar":false},{"id":1509,"unit":5,"lesson":4,"word":"operation","pronunciation":"/ˌɒpəˈreɪʃ(ə)n/","meaning":"n.手术;(有组织的)活动,行动;企业","seq":53,"isStar":false},{"id":1510,"unit":5,"lesson":4,"word":"operational","pronunciation":"/ˌɒpəˈreɪʃən(ə)l/","meaning":"adj.操作的,运转的,运营的;业务的","seq":54,"isStar":false},{"id":1511,"unit":5,"lesson":4,"word":"operator","pronunciation":"/ˈɒpəreɪtə(r)/","meaning":"n.操作人员","seq":55,"isStar":false},{"id":1512,"unit":5,"lesson":4,"word":"cooperate","pronunciation":"/kəʊˈɒpəreɪt/","meaning":"v.合作,协作","seq":56,"isStar":false,"memo":"构词 co-(一起)+operate(经营)→合作","example":"We must cooperate and work toward common goals. 我们必须合作,朝着共同的目标努力。"},{"id":1513,"unit":5,"lesson":4,"word":"cooperation","pronunciation":"/kəʊˌɒpəˈreɪʃ(ə)n/","meaning":"n.合作,协作","seq":57,"isStar":false},{"id":1514,"unit":5,"lesson":4,"word":"cooperative","pronunciation":"/kəʊˈɒpərətɪv/","meaning":"n.合作企业;合作性组织 adj.合作的","seq":58,"isStar":false,"memo":"构词 co-(一起)+operat(e)(经营)+-ive (后缀)→一起经营的→合作的(企业)","example":"The local fishing cooperative decided to reduce its catch. 当地渔业合作社决定减少捕鱼量。"},{"id":1515,"unit":5,"lesson":4,"word":"collaborate","pronunciation":"/kəˈlæbəreɪt/","meaning":"v.合作,协作","seq":59,"isStar":false,"memo":"构词 col-(=con-,一起)+labor(劳动)+ -ate(动词后缀)→一起劳动→合作,协作","example":"We have collaborated on many projects over the years. 这些年来我们合作搞了许多项目。"},{"id":1516,"unit":5,"lesson":4,"word":"collaboration","pronunciation":"/kəˌlæbəˈreɪʃ(ə)n/","meaning":"n.合作,协作","seq":60,"isStar":false},{"id":1517,"unit":5,"lesson":4,"word":"collaborative","pronunciation":"/kəˈlæbərətɪv/","meaning":"adj.合作的,协作的,协力的","seq":61,"isStar":false},{"id":1518,"unit":5,"lesson":4,"word":"elaborate","pronunciation":"/ɪˈlæbərət/","meaning":"adj.精心制作的;详细的 v.详细描述","seq":62,"isStar":false,"memo":"联想 e-(出)+labor(劳动)+-ate(后缀)→辛苦做出(的)→精心制作(的)","example":"The elaborate patterns were believed to offer protection against evil. 人们相信这些精心制作的图案可以保护人们对抗邪恶。"},{"id":1519,"unit":5,"lesson":4,"word":"elaboration","pronunciation":"/ɪˌlæbəˈreɪʃ(ə)n/","meaning":"n.精心制作(或计划);精致;详尽阐述","seq":63,"isStar":false},{"id":1520,"unit":5,"lesson":4,"word":"subsidy","pronunciation":"/ˈsʌbsədi/","meaning":"n.补贴,补助金,津贴","seq":64,"isStar":false,"memo":"联想 sub(联想“叔伯”) + si(联想“死”) + dy→叔伯在战争中牺牲，国家给家属发放了一些“补贴”。","example":"Renewable energy deserves a subsidy. 可再生能源应该得到补贴。"},{"id":1521,"unit":5,"lesson":4,"word":"subsidise/-ize","pronunciation":"/ˈsʌbsɪdaɪz/","meaning":"v.资助,补助,给……发津贴","seq":65,"isStar":false,"memo":"构词 sub-(在下面)+sid(坐，同 preside 主持)+-ise/-ize(使…化)→在下面垫着托一把→资助，补助，发津贴","example":"The government subsidises public transport. 政府补贴公共交通。"},{"id":1522,"unit":5,"lesson":4,"word":"allowance","pronunciation":"/əˈlaʊəns/","meaning":"n.津贴,补贴;零用钱","seq":66,"isStar":false,"memo":"联想 allow(允许) + an(一) + ce(联想“侧”) →领导允许员工在办公室一侧领“津贴”。","example":"The job-seekers’ allowance has met their actual needs. 求职者津贴满足了他们的实际需要。"},{"id":1523,"unit":5,"lesson":4,"word":"bonus","pronunciation":"/ˈbəʊnəs/","meaning":"n.奖金,红利;意外收获,额外的好处","seq":67,"isStar":false,"memo":"联想 bo(形似 60) + nus(联想 nuts)→公司发了 60 包坚果作为大家的年终“奖金”。","example":"The firm recognised his outstanding work by giving him a bonus. 公司通过给他发放一笔奖金来认可他出色的工作表现。"},{"id":1524,"unit":5,"lesson":4,"word":"dole","pronunciation":"/dəʊl/","meaning":"n.失业救济金 v.(~out)发放","seq":68,"isStar":false,"memo":"谐音 单词发音类似“逗哦”→他说这周给每人“发放”一辆自行车却没发,真逗哦。","example":"He had to live in the uncertainty on the dole.他不得不靠救济金过着不确定的生活。"},{"id":1525,"unit":5,"lesson":4,"word":"dividend","pronunciation":"/ˈdɪvɪdend/","meaning":"n.红利;股息,股利","seq":69,"isStar":false,"memo":"联想 divid(e)(分配)+end(最后)→公司最后总得分配点“红利”。","example":"The company has not yet declared its dividends for this year.该公司今年尚未宣布分红。"},{"id":1526,"unit":5,"lesson":4,"word":"privilege","pronunciation":"/ˈprɪvəlɪdʒ/","meaning":"n.特殊待遇;权势 v.给予特权","seq":70,"isStar":false,"memo":"联想 pri-(联想 pre-,提前) + vi(音似“为”) + le(联想“了”) + ge(联想“哥”)→为了让哥哥满意，提前给他“特殊待遇”。","example":"The prisoner has been deprived of many privileges that average citizens enjoy. 这个囚犯被剥夺了普通公民享有的许多优待。"},{"id":1527,"unit":5,"lesson":4,"word":"privileged","pronunciation":"/ˈprɪvəlɪdʒd/","meaning":"adj.有特权的,受特别优待的;荣幸的","seq":71,"isStar":false,"memo":"构词 priv(个别，同 private 私人的)+-ilege+-ed→只给个别人的待遇→有特权的，受特别优待的；荣幸的","example":"It mainly caters to the needs of the privileged.它主要满足特权阶层的需求。"},{"id":1528,"unit":5,"lesson":4,"word":"avenue","pronunciation":"/ˈævənjuː/","meaning":"n.大街;林荫道","seq":72,"isStar":false,"memo":"a(一个)+venue(联想 venus,维纳斯)→我今天在“大街”上遇见了一个像维纳斯一样美丽的人。","example":"He walked up Fifth Avenue to clear his head. 他沿着第五大道走了走,好让大脑清醒清醒。"},{"id":1529,"unit":5,"lesson":4,"word":"revenue","pronunciation":"/ˈrevənjuː/","meaning":"n.税收收入;收入,收益","seq":73,"isStar":false,"memo":"re(字母音似“阿姨”)+venue(联想 venus,维纳斯)→阿姨想变成像维纳斯一样美丽的女人,于是利用“收入”提升自己的形象。","example":"Financial incentives ensure companies meet specific revenue goals. 财务激励措施确保公司实现特定的收入目标。"},{"id":1530,"unit":5,"lesson":4,"word":"inventory","pronunciation":"/ˈɪnvəntri/","meaning":"n.清单;存货,库存 v.开列清单","seq":74,"isStar":false,"memo":"invent(发明)+-ory(表示场所的后缀)→他发明了一个放“存货”的智能仓库。","example":"The inventory will be disposed of over the next twelve weeks. 在未来的十二个星期中将进行清库存处理。"},{"id":1531,"unit":5,"lesson":4,"word":"revenge","pronunciation":"/rɪˈvendʒ/","meaning":"n.报复,报仇 v.报复,为……报仇","seq":75,"isStar":false,"memo":"re-(回)+venge(音似“文姬”,人名)→文姬被伤害了,多年后回来“报仇”。","example":"In the face of resentment, it is human to revenge. 面对怨恨,想要报复是人之常情。"},{"id":1532,"unit":5,"lesson":4,"word":"revengeful","pronunciation":"/rɪˈvendʒf(ə)l/","meaning":"adj.渴望报复的,一心报复的","seq":76,"isStar":false},{"id":1533,"unit":5,"lesson":4,"word":"bypass","pronunciation":"/ˈbaɪpɑːs/","meaning":"n.旁路 v.避开,绕……而行","seq":77,"isStar":false,"memo":"by-(在旁边)+pass(通过)→在旁边通过→避开;绕过","example":"More roads were built to bypass the heavy traffic. 为了避开繁忙的交通,修建了更多的道路。"},{"id":1534,"unit":5,"lesson":4,"word":"whereby","pronunciation":"/weəˈbaɪ/","meaning":"adv.凭此,借以,由于","seq":78,"isStar":false,"memo":"构词 where(哪里)+by(凭借)→凭此，借以，由于","example":"He gave me a pass whereby I would be allowed into the conference. 他给了我一张通行证,我可以凭此参加这场会议。"},{"id":1535,"unit":5,"lesson":4,"word":"freeway","pronunciation":"/ˈfriːweɪ/","meaning":"n.(美国)高速公路","seq":79,"isStar":false,"memo":"构词 free（自由的）+ way（道路）→ 自由通行、可以高速行驶的道路 → 高速公路","example":"The speed limit on the freeway is 55 mph.高速公路的限速是每小时55英里。"},{"id":1536,"unit":5,"lesson":4,"word":"aisle","pronunciation":"/aɪl/","meaning":"n.走道,过道","seq":80,"isStar":false,"memo":"联想 ai（联想“挨”）+ s（联想“试”）+ le（联想“了”）→ 学生们站在“过道”里，一个挨着一个，准备进考场考试了。","example":"She walked down the aisle of the church on her wedding day.她在婚礼当天沿着教堂的过道走去。"},{"id":1537,"unit":5,"lesson":4,"word":"underlie","pronunciation":"/ˌʌndəˈlaɪ/","meaning":"v.构成……的基础;作为……的原因","seq":81,"isStar":false,"memo":"under(在……下面)+lie(位于)→位于……的下面→构成……的基础","example":"These ideas underlie much of his work. 他的作品大部分都以这些思想为基础。"},{"id":1538,"unit":5,"lesson":4,"word":"underlying","pronunciation":"/ˌʌndəˈlaɪɪŋ/","meaning":"adj.根本的,潜在的,隐含的","seq":82,"isStar":false},{"id":1539,"unit":5,"lesson":4,"word":"underline","pronunciation":"/ˌʌndəˈlaɪn/","meaning":"v.在(词语等下)画线;强调,使突出","seq":83,"isStar":false,"memo":"构词 under(在下面)+line(线)→在下面画线；引申为强调，使突出","example":"It underlines just how much things have changed in the last generation. 这突显了上一代人的生活发生了多么大的变化。"},{"id":1540,"unit":5,"lesson":4,"word":"undermine","pronunciation":"/ˌʌndəˈmaɪn/","meaning":"v.逐渐削弱;从根基处破坏","seq":84,"isStar":false,"memo":"（构词）under(在……下面) + mine(挖掘) → 在下方挖掘 → 从根基处破坏","example":"In fact, they do much to undermine the teaching. 事实上，他们做了很多损害教学的事情。"},{"id":1541,"unit":5,"lesson":4,"word":"undergo","pronunciation":"/ˌʌndəˈɡəʊ/","meaning":"v.经历,遭受","seq":85,"isStar":false,"memo":"（构词）under(在……下面) + go(走) → 在下面走过 → 经历，遭受","example":"Some children undergo a complete transformation when they become teenagers. 一些儿童进入青春期会完全变成另一个人。"},{"id":1542,"unit":5,"lesson":4,"word":"undertake","pronunciation":"/ˌʌndəˈteɪk/","meaning":"v.承担,担任;从事;答应","seq":86,"isStar":false,"memo":"（构词）under(在……下面) + take(拿着) → 在下边拿着 → 承担","example":"The directors of the company refused to undertake such a risky venture. 公司董事拒绝承担这样一个高风险的经营项目。"},{"id":1543,"unit":5,"lesson":4,"word":"deadline","pronunciation":"/ˈdedlaɪn/","meaning":"n.截止日期,最后期限","seq":87,"isStar":false,"memo":"（构词）dead(死) + line(线) → 死亡的线，禁止越过 → 截止日期","example":"This deadline will be extended only in exceptional circumstances. 只有在特殊情况下才会延长最后期限。"},{"id":1544,"unit":5,"lesson":4,"word":"guideline","pronunciation":"/ˈɡaɪdlaɪn/","meaning":"n.指导方针,指导原则,行动纲领,准则","seq":88,"isStar":false,"memo":"（构词）guide(指导) + line(线) → 指导原则，准则","example":"Those guidelines are outdated and extremely inadequate. 那些指导方针已经过时，而且极不充分。"},{"id":1545,"unit":5,"lesson":4,"word":"skyline","pronunciation":"/ˈskaɪlaɪn/","meaning":"n.轮廓线,天际线","seq":89,"isStar":false,"memo":"记 (构词) sky(天空) + line(线)→天空与地面(或海面)在视野中相交形成的分界线→天际线","example":"We are attracted by the skyline of the distant mountains.我们被远处群山的天际线所吸引。"},{"id":1546,"unit":5,"lesson":4,"word":"streamline","pronunciation":"/ˈstriːmlaɪn/","meaning":"v.使成流线型","seq":90,"isStar":false,"memo":"（构词）stream(流) + line(线) → 使成流线型","example":"We need to streamline the production process. 我们需要简化生产流程。"},{"id":1547,"unit":5,"lesson":4,"word":"align","pronunciation":"/əˈlaɪn/","meaning":"v.(尤指)成一直线;使一致;与……结盟","seq":91,"isStar":false,"memo":"（联想）a-(表示强调) + lign(联想 line, 线) → 成一直线；使一致","example":"The house is aligned along an east-west axis. 这幢房屋沿东西轴线成一直线。"},{"id":1548,"unit":5,"lesson":4,"word":"alignment","pronunciation":"/əˈlaɪnmənt/","meaning":"n.排成直线;结盟","seq":92,"isStar":false},{"id":1549,"unit":6,"lesson":1,"word":"recipe","pronunciation":"/ˈresəpi/","meaning":"n.烹饪法,食谱;秘诀","seq":1,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + ci(联想“此”) + pe(音似“批”) → 此批菜是新上的，阿姨的“食谱”上没有。","example":"What's her recipe for success? 她成功的秘诀是什么？"},{"id":1550,"unit":6,"lesson":1,"word":"reciprocal","pronunciation":"/rɪˈsɪprək(ə)l/","meaning":"adj.互惠的,相互的","seq":2,"isStar":false,"memo":"对照 美食社区里，大家本着互惠的(reciprocal)精神分享食谱(recipe)。","example":"The two colleges have a reciprocal arrangement. 两所学院有一项互惠协定。"},{"id":1551,"unit":6,"lesson":1,"word":"edible","pronunciation":"/ˈedəb(ə)l/","meaning":"adj.可以食用的","seq":3,"isStar":false,"memo":"谐音 单词发音类似“俺爹饱”→俺爹食用了太多食物，吃饱了→可以食用的","example":"It is said seaweed is edible. 据说，海藻是可以吃的。"},{"id":1552,"unit":6,"lesson":1,"word":"poison","pronunciation":"/ˈpɔɪz(ə)n/","meaning":"n.毒药,毒素 v.毒害,下毒","seq":4,"isStar":false,"memo":"谐音 单词发音类似“泼一身”→他被泼了一身的“毒药”。","example":"The water had been poisoned. 水里被下了毒。"},{"id":1553,"unit":6,"lesson":1,"word":"poisonous","pronunciation":"/ˈpɔɪzənəs/","meaning":"adj.有毒的","seq":5,"isStar":false,"example":"These mushrooms contain a deadly poison. 这些蘑菇含有效命毒素。"},{"id":1554,"unit":6,"lesson":1,"word":"toxic","pronunciation":"/ˈtɒksɪk/","meaning":"adj.有毒的,引起中毒的","seq":6,"isStar":false,"memo":"谐音 单词发音类似“逃课 seek”→他逃课去寻找一种“有毒的”奇异植物。","example":"This chemical is toxic to many forms of life. 这种化学品对很多生物都有毒害。"},{"id":1555,"unit":6,"lesson":1,"word":"dioxide","pronunciation":"/daɪˈɒksaɪd/","meaning":"n.二氧化物","seq":7,"isStar":false,"memo":"构词 di-(二)+oxide(氧化物)→含两个氧原子的氧化物→二氧化物","example":"Humans take in oxygen and breathe out carbon dioxide.人类吸入氧气，呼出二氧化碳。"},{"id":1556,"unit":6,"lesson":1,"word":"cocaine","pronunciation":"/kəʊˈkeɪn/","meaning":"n.可卡因","seq":8,"isStar":false,"memo":"谐音 “可卡因”：音译词，由 cocaine 直接音译而来→可卡因","example":"The use of cocaine can lead to serious health problems and addiction.使用可卡因会导致严重的健康问题和成瘾。"},{"id":1557,"unit":6,"lesson":1,"word":"fibre/-ber","pronunciation":"/ˈfaɪbə(r)/","meaning":"n.(食物的)纤维素;(布绳的)纤维","seq":9,"isStar":false,"memo":"联想 与 fabric(织物)同源：织成布的那些细丝→纤维，纤维素","example":"Vegetables are a good source of fibre. 蔬菜是膳食纤维的良好来源。"},{"id":1558,"unit":6,"lesson":1,"word":"vitamin","pronunciation":"/ˈvɪtəmɪn/","meaning":"n.维生素","seq":10,"isStar":false,"memo":"构词 vita(生命，同 vital 至关重要的)+-min(胺类词尾)→维持生命所必需的一类物质→维生素","example":"Even a modest vitamin shortfall can be harmful to your health. 即使是少量的维生素缺乏,也会对你的健康有害。"},{"id":1559,"unit":6,"lesson":1,"word":"well-being","pronunciation":"/ˈwel biːɪŋ/","meaning":"n.健康,舒适,幸福;(国家的)繁荣","seq":11,"isStar":false,"memo":"构词 well(好)+being(存在状态)→处在良好的状态里→健康，舒适，幸福；(国家的)繁荣","example":"I ate the noodles on the well-being menu.我吃了健康菜单上的面条。"},{"id":1560,"unit":6,"lesson":1,"word":"diet","pronunciation":"/ˈdaɪət/","meaning":"n.日常饮食,日常食物 v.节食","seq":12,"isStar":false,"memo":"谐音 “呆特”：每天吃下去的东西决定身材，吃不对就白“呆”→日常饮食；节食","example":"She's always dieting but she never seems to lose any weight. 她总是在节食,但她的体重好像并未减少。"},{"id":1561,"unit":6,"lesson":1,"word":"dietary","pronunciation":"/ˈdaɪətəri/","meaning":"adj.饮食的","seq":13,"isStar":false},{"id":1562,"unit":6,"lesson":1,"word":"calorie","pronunciation":"/ˈkæləri/","meaning":"n.卡路里,热量","seq":14,"isStar":false,"memo":"谐音 “卡路里”：音译词，热量的计量单位→卡路里，热量","example":"Some iced coffees have as many calories as a hot dinner.一些冰咖啡的热量相当于一顿热晚餐。"},{"id":1563,"unit":6,"lesson":1,"word":"nutrition","pronunciation":"/njuˈtrɪʃ(ə)n/","meaning":"n.营养,滋养;营养学","seq":15,"isStar":false,"memo":"单词发音类似“牛吹神”→“营养”品再牛也不能被吹成神药。","example":"Nutrition information is now provided on the back of most food products. 现在大多数食物产品的背面都附有营养信息。"},{"id":1564,"unit":6,"lesson":1,"word":"nutrient","pronunciation":"/ˈnjuːtriənt/","meaning":"n.营养素,营养物","seq":16,"isStar":false},{"id":1565,"unit":6,"lesson":1,"word":"nurture","pronunciation":"/ˈnɜːtʃə(r)/","meaning":"v.养育,培育,培养(感情等);帮助","seq":17,"isStar":false,"memo":"构词 nurt(喂养，同 nurse 养育)+-ure(名词/动词后缀)→喂养、培育→养育，培育，培养(感情等)","example":"It's important to nurture a good working relationship. 培养良好的工作关系非常重要。"},{"id":1566,"unit":6,"lesson":1,"word":"nourish","pronunciation":"/ˈnʌrɪʃ/","meaning":"v.滋养;培养(感情、观念或信念);保持","seq":18,"isStar":false,"memo":"护士(nurse)对待病人像滋养(nourish)花一样。","example":"By investing in education, we nourish the talents of our children. 我们通过教育投资来培养孩子们的才能。"},{"id":1567,"unit":6,"lesson":1,"word":"nourishment","pronunciation":"/ˈnʌrɪʃmənt/","meaning":"n.营养;营养品","seq":19,"isStar":false},{"id":1568,"unit":6,"lesson":1,"word":"foster","pronunciation":"/ˈfɒstə(r)/","meaning":"v.促进,培养;抚育,照料","seq":20,"isStar":false,"memo":"fo(音似 four) + ster(联想 sister)→爸爸妈妈把四个姐妹“培养”得很好。","example":"They have fostered over 60 children during the past ten years. 在过去10年间,他们抚育了60多个孩子。"},{"id":1569,"unit":6,"lesson":1,"word":"rear","pronunciation":"/rɪə(r)/","meaning":"v.抚养,培养 adj.后面的 n.后面","seq":21,"isStar":false,"memo":"rea(联想 real) + r(形似花)→他衣服的“后面”真的有朵花。","example":"She reared three children on her own. 她独自抚养了三个孩子。"},{"id":1570,"unit":6,"lesson":1,"word":"cultivate","pronunciation":"/ˈkʌltɪveɪt/","meaning":"v.耕作;培育,培养","seq":22,"isStar":false,"memo":"[对照] 为了使孩子们有文化(culture),家长和老师都需要用心培养(cultivate)他们。","example":"Humanistic thinking helps cultivate students' creativity. 人文思维有助于培养学生的创造力。"},{"id":1571,"unit":6,"lesson":1,"word":"cultivation","pronunciation":"/ˌkʌltɪˈveɪʃ(ə)n/","meaning":"n.耕种,种植;(品质或技巧的)培养","seq":23,"isStar":false},{"id":1572,"unit":6,"lesson":1,"word":"breed","pronunciation":"/briːd/","meaning":"v.饲养,培育;孕育","seq":24,"isStar":false,"memo":"[谐音] 单词发音类似“哺育的”→饲养,培育;孕育","example":"The rabbits are bred for their long coats. 饲养兔子是为了获取它们的长毛。"},{"id":1573,"unit":6,"lesson":1,"word":"pasta","pronunciation":"/ˈpæstə/","meaning":"n.意大利面食","seq":25,"isStar":false,"memo":"记 (联想) pas(t)(过去的)+ta(联想“他”)→过去的他喜欢吃“意大利面食”。","example":"They stock every imaginable type of pasta.他们储备了所有能想到的面食种类。"},{"id":1574,"unit":6,"lesson":1,"word":"pastry","pronunciation":"/ˈpeɪstri/","meaning":"n.油酥面团;油酥糕点","seq":26,"isStar":false},{"id":1575,"unit":6,"lesson":1,"word":"beverage","pronunciation":"/ˈbevərɪdʒ/","meaning":"n.(除水以外的)饮料","seq":27,"isStar":false,"memo":"[联想] be(是)+ver(音似“我”)+age(年龄)→这种“饮料”是我这个年龄可以喝的。","example":"Beer is a beverage of the remotest time. 啤酒是一种最古老的饮料。"},{"id":1576,"unit":6,"lesson":1,"word":"cocktail","pronunciation":"/ˈkɒkteɪl/","meaning":"n.鸡尾酒","seq":28,"isStar":false,"memo":"记 (构词) cock(公鸡)+tail(尾巴)→鸡尾酒","example":"Why don't you mix our guests a cocktail?为什么不给我们的客人调一杯鸡尾酒呢？"},{"id":1577,"unit":6,"lesson":1,"word":"cafeteria","pronunciation":"/ˌkæfəˈtɪəriə/","meaning":"n.自助餐厅,自助食堂","seq":29,"isStar":false,"memo":"构词 cafe(咖啡)+-teria(表场所)→自己取餐的用餐处→自助餐厅，自助食堂","example":"The food served in the cafeteria usually lacks variety. 自助餐厅供应的食物通常缺乏多样性。"},{"id":1578,"unit":6,"lesson":1,"word":"relish","pronunciation":"/ˈrelɪʃ/","meaning":"n.享受,乐趣;调味汁 v.喜爱,喜欢","seq":30,"isStar":false,"memo":"[联想] re(字母音似“阿姨”)+li(联想“立”)+sh(音似“试”)→阿姨一看到这件衣服立刻来试穿,说明她很“喜欢”这件衣服。","example":"The three men ate with relish. 这三个人吃得津津有味。"},{"id":1579,"unit":6,"lesson":1,"word":"scent","pronunciation":"/sent/","meaning":"n.香味;臭气,气味 v.闻到;预感","seq":31,"isStar":false,"memo":"[对照] 他按下香薰机开关,香味(scent)便向四周发送(sent)。","example":"The dog scented a rabbit. 狗闻到了兔子的气味。"},{"id":1580,"unit":6,"lesson":1,"word":"perfume","pronunciation":"/ˈpɜːfjuːm/","meaning":"n.香水;芳香;香料","seq":32,"isStar":false,"memo":"[联想] per(每一)+fu(联想“服”)+me(我)→每一次为客户服务,我都向他们推荐这款“香水”。","example":"She always puts a bit of perfume behind her ears in the morning. 早上她总是在耳后擦点香水。"},{"id":1581,"unit":6,"lesson":1,"word":"fragrant","pronunciation":"/ˈfreɪɡrənt/","meaning":"adj.香的,芳香的","seq":33,"isStar":false,"memo":"记 (联想) fr(联想“芙蓉”)+ag(联想“阿哥”)+r(联想“让”)+ant(蚂蚁)→芙蓉和阿哥让蚂蚁吃了份很“香的”食物。","example":"The air was fragrant with scents from the sea and hills.空气中弥漫着大海和山丘的芳香。"},{"id":1582,"unit":6,"lesson":1,"word":"fragrance","pronunciation":"/ˈfreɪɡrəns/","meaning":"n.香气;香味","seq":34,"isStar":false},{"id":1583,"unit":6,"lesson":1,"word":"odo(u)r","pronunciation":"/ˈəʊdə(r)/","meaning":"n.(尤指难闻的)气味;臭味","seq":35,"isStar":false,"memo":"谐音 单词发音类似“old”→这个老人喷了难闻的香水,身上发出一种“气味”。","example":"We all smelled the distinct odour of something burning.我们都闻到了某种东西燃烧的明显气味。"},{"id":1584,"unit":6,"lesson":1,"word":"odorous","pronunciation":"/ˈəʊdərəs/","meaning":"adj.有气味的","seq":36,"isStar":false},{"id":1585,"unit":6,"lesson":1,"word":"territory","pronunciation":"/ˈterətri/","meaning":"n.领土;地盘","seq":37,"isStar":false,"memo":"[联想] te(联想“特”)+(r)ri(联想“日”)+t(联想“提”)+-ory(表示地方的后缀)→特别的日子里提到的地方是自己的“领土”。","example":"If you go into a shark's territory and threaten it, it might bite you. 如果你进入鲨鱼的领地并威胁到它,它可能会咬你。"},{"id":1586,"unit":6,"lesson":1,"word":"territorial","pronunciation":"/ˌterəˈtɔːriəl/","meaning":"adj.领土的;领域性的","seq":38,"isStar":false},{"id":1587,"unit":6,"lesson":1,"word":"dormitory","pronunciation":"/ˈdɔːmətri/","meaning":"n.集体宿舍;学生宿舍","seq":39,"isStar":false,"memo":"[联想] dor(音似“捣”)+m(联想“门”)+it+-ory(表示地方的后缀)→晚上宿管阿姨把门锁了,学生回“集体宿舍”要捣(敲)门。","example":"The dormitory for the soldiers is well-organised and clean. 士兵们的集体宿舍井井有条且干净。"},{"id":1588,"unit":6,"lesson":1,"word":"lavatory","pronunciation":"/ˈlævətri/","meaning":"n.洗手间,厕所","seq":40,"isStar":false,"memo":"[联想] la(联想“拉”)+va(音似“我”)+t(联想“吐”)+-ory(表示地方的后缀)→我吃坏东西拉肚子,还一直呕吐,赶紧跑去“洗手间”。","example":"The nearest public lavatory is at the station. 最近的公共厕所在车站。"},{"id":1589,"unit":6,"lesson":1,"word":"gallery","pronunciation":"/ˈɡæləri/","meaning":"n.画廊;走廊","seq":41,"isStar":false,"memo":"[联想] gall(音似“盖了”)+-ery(表示地方的后缀)→他盖了很长的一个地方,用作“画廊”。","example":"He declined a job offer from the gallery. 他拒绝了画廊的工作邀请。"},{"id":1590,"unit":6,"lesson":1,"word":"grocery","pronunciation":"/ˈɡrəʊsəri/","meaning":"n.食品杂货店","seq":42,"isStar":false,"memo":"[联想] gro(音似“割肉”)+c(联想“车”)+-ery(表示地方的后缀)→我开车去“食品杂货店”割一些肉。","example":"Every weekend, he goes to the grocery to buy some meat. 每个周末,他都会去食品杂货店买一些肉。"},{"id":1591,"unit":6,"lesson":1,"word":"grocer","pronunciation":"/ˈɡrəʊsə(r)/","meaning":"n.食物杂货商;食物杂货店","seq":43,"isStar":false},{"id":1592,"unit":6,"lesson":2,"word":"scenery","pronunciation":"/ˈsiːnəri/","meaning":"n.风景,景色;舞台布景","seq":1,"isStar":false,"memo":"构词 scene(景色)+-ery(名词后缀，表总称)→景色的总称→风景，景色；舞台布景","example":"He doesn't know how to describe the beautiful country scenery. 他不知道如何形容那美丽的乡村风景。"},{"id":1593,"unit":6,"lesson":2,"word":"nursery","pronunciation":"/ˈnɜːsəri/","meaning":"n.托儿所,幼儿园;儿童房","seq":2,"isStar":false,"memo":"[构词] nurs(e)(看护)+-ery(表示地方的后缀)→看护的地方→托儿所","example":"They'll need help getting up out of those little chairs in nursery school. 他们需要人帮忙才能从幼儿园的那些小椅子上站起来。"},{"id":1594,"unit":6,"lesson":2,"word":"local","pronunciation":"/ˈləʊk(ə)l/","meaning":"n.本地人 adj.当地的","seq":3,"isStar":false,"memo":"谐音：单词发音类似“唠嗑”→我在外地想找个唠嗑的人，一问都是“本地人”。","example":"Television gave another push to the local economy. 电视又一次推动了当地的经济。"},{"id":1595,"unit":6,"lesson":2,"word":"locality","pronunciation":"/ləʊˈkæləti/","meaning":"n.地区;地方,地点","seq":4,"isStar":false},{"id":1596,"unit":6,"lesson":2,"word":"locate","pronunciation":"/ləʊˈkeɪt/","meaning":"v.找出……的具体位置;把……设置在","seq":5,"isStar":false,"memo":"谐音：单词发音类似“姥剋他”→姥姥剋(打)他,要先找到他→找出……的具体位置","example":"It is located in the eastern part of China. 它位于中国的东部。"},{"id":1597,"unit":6,"lesson":2,"word":"location","pronunciation":"/ləʊˈkeɪʃn/","meaning":"n.位置,地点;定位","seq":6,"isStar":false},{"id":1598,"unit":6,"lesson":2,"word":"allocate","pronunciation":"/ˈæləkeɪt/","meaning":"v.分配,调拨","seq":7,"isStar":false,"memo":"联想:all(所有)+(l)ocate(找出……的具体位置)→找出所有人的位置,再确定把东西“分配”给谁。","example":"More resources are being allocated to the project. 更多的资源正在被分配给这个项目。"},{"id":1599,"unit":6,"lesson":2,"word":"allocation","pronunciation":"/ˌæləˈkeɪʃ(ə)n/","meaning":"n.分配;配置","seq":8,"isStar":false},{"id":1600,"unit":6,"lesson":2,"word":"situate","pronunciation":"/ˈsɪtʃueɪt/","meaning":"v.使位于……;把……跟……联系起来考虑","seq":9,"isStar":false,"memo":"构词 situ(表地点，位置)+-ate(动词后缀)→使在……地点或位置→使位于……","example":"Let me try and situate the events in their historical context.让我试着把这些事件放在它们的历史背景中。"},{"id":1601,"unit":6,"lesson":2,"word":"situation","pronunciation":"/ˌsɪtʃuˈeɪʃ(ə)n/","meaning":"n.情况,状况;位置","seq":10,"isStar":false,"memo":"构词:situat(e)(使位于……)+-ion(名词后缀)→位置","example":"These questions can predict how people actually behave in social situations. 这些问题可以预测人们在社交场合的实际行为。"},{"id":1602,"unit":6,"lesson":2,"word":"urban","pronunciation":"/ˈɜːbən/","meaning":"adj.城市的;都市的;城镇的","seq":11,"isStar":false,"memo":"联想 ur(音似“鹅”)+ban(禁止)→房东禁止租客在城市的房子里养鹅→城市的","example":"It seems reasonable to expect rapid urban growth.有理由预期城市会快速增长。"},{"id":1603,"unit":6,"lesson":2,"word":"urbanise/-ize","pronunciation":"/ˈɜːrbənˌaɪz/","meaning":"v.使都市化","seq":12,"isStar":false,"memo":"构词 urban(城市的)+-ise/-ize(使…化)→使变成城市→使都市化","example":"The area was urbanised within twenty years. 这个地区在二十年内完成了城市化。"},{"id":1604,"unit":6,"lesson":2,"word":"urbanisation/-zation","pronunciation":"/ˌɜːbənaɪˈzeɪʃn/","meaning":"n.城市化","seq":13,"isStar":false,"memo":"构词 urban(城市的)+-isation/-ization(名词后缀)→变成城市的过程→城市化","example":"Rapid urbanisation has changed the countryside. 快速的城市化改变了乡村面貌。"},{"id":1605,"unit":6,"lesson":2,"word":"suburb","pronunciation":"/ˈsʌbɜːb/","meaning":"n.市郊,郊区","seq":14,"isStar":false,"memo":"构词:sub-(=near)+urb(=city)→在城市附近→郊区","example":"They live in a quiet suburb of the city. 他们住在城里一个安静的郊区。"},{"id":1606,"unit":6,"lesson":2,"word":"suburban","pronunciation":"/səˈbɜːbən/","meaning":"adj.郊区的;平庸的","seq":15,"isStar":false,"memo":"构词 suburb(郊区)+-an(形容词后缀)→郊区的；也引申为“平淡乏味的”","example":"She grew up in a suburban neighbourhood. 她在郊区的一个社区长大。"},{"id":1607,"unit":6,"lesson":2,"word":"downtown","pronunciation":"/ˌdaʊnˈtaʊn/","meaning":"adv.在市中心 adj.市中心的","seq":16,"isStar":false,"memo":"构词 down(向下)+town(城镇)：老城地势低处最热闹→在市中心；市中心的","example":"I have to go downtown later.我一会儿得去市中心。"},{"id":1608,"unit":6,"lesson":2,"word":"metropolitan","pronunciation":"/ˌmetrəˈpɒlɪtən/","meaning":"adj.大城市的,大都会的;本土的","seq":17,"isStar":false,"memo":"联想 me(我) + tro + polit(联想 politics) + -an(形容词后缀) → 身在“大城市的”我常关注政治事务。","example":"It is highly important to expand the metropolitan areas. 扩大都市圈是非常重要的。"},{"id":1609,"unit":6,"lesson":2,"word":"continent","pronunciation":"/ˈkɒntɪnənt/","meaning":"n.大陆;洲","seq":18,"isStar":false,"memo":"联想 con-(所有) + tin(音似“听”) + ent (联想 enter) → 把所有听装的罐头都搬进这块“大陆”。","example":"The World Cup is called that because teams from every continent have played in it. 世界杯之所以被这么称呼，是因为每个洲的球队都参加过比赛。"},{"id":1610,"unit":6,"lesson":2,"word":"continental","pronunciation":"/ˌkɒntɪˈnent(ə)l/","meaning":"adj.大陆的;大洲的","seq":19,"isStar":false},{"id":1611,"unit":6,"lesson":2,"word":"current","pronunciation":"/ˈkʌrənt/","meaning":"adj.当前的","seq":20,"isStar":false,"memo":"联想 cur(联想 care) + rent(租房) → 他关心“当前的”租房价格。","example":"Oil prices are expected to remain at current levels. 油价预计将保持在当前水平。"},{"id":1612,"unit":6,"lesson":2,"word":"currently","pronunciation":"/ˈkʌrəntli/","meaning":"adv.目前,当前","seq":21,"isStar":false},{"id":1613,"unit":6,"lesson":2,"word":"currency","pronunciation":"/ˈkʌrənsi/","meaning":"n.流行;通货;货币","seq":22,"isStar":false,"memo":"构词 curren(t)(流行的) + -cy(名词后缀) → 流行","example":"Their currency has slumped. 他们的货币已经贬值。"},{"id":1614,"unit":6,"lesson":2,"word":"monetary","pronunciation":"/ˈmʌnɪtri/","meaning":"adj.货币的,钱的(尤指一国的货币)","seq":23,"isStar":false,"memo":"构词 monet(钱，同 money)+-ary(形容词后缀)→与钱币有关的→货币的，钱的","example":"The company is facing monetary difficulties due to the economic downturn.由于经济衰退，公司正面临财务困难。"},{"id":1615,"unit":6,"lesson":2,"word":"money","pronunciation":"/ˈmʌni/","meaning":"n.钱;薪水;收入","seq":24,"isStar":false},{"id":1616,"unit":6,"lesson":2,"word":"harmony","pronunciation":"/ˈhɑːməni/","meaning":"n.融洽,和谐","seq":25,"isStar":false,"memo":"构词 harm(接合，源出希腊语 harmos)+-ony(名词后缀)→各部分接合得好→融洽，和谐","example":"All life seemed to live in harmony with its surroundings there. 那里所有的生命似乎都与周围的环境和谐相处。"},{"id":1617,"unit":6,"lesson":2,"word":"harmonious","pronunciation":"/hɑːˈməʊniəs/","meaning":"adj.和谐的,协调的","seq":26,"isStar":false},{"id":1618,"unit":6,"lesson":2,"word":"loan","pronunciation":"/ləʊn/","meaning":"n.贷款","seq":27,"isStar":false,"memo":"谐音 单词发音类似“楼”→一般人买楼房需要“贷款”。","example":"They are not eligible for a student loan. 他们没有资格申请学生贷款。"},{"id":1619,"unit":6,"lesson":2,"word":"landlord","pronunciation":"/ˈlændlɔːd/","meaning":"n.地主;房东;店主","seq":28,"isStar":false,"memo":"谐音 单词发音类似“懒得劳动”→有些“地主”只收租金,懒得去劳动。","example":"The landlord gave notice of the termination of tenancy. 房东给了租期终止的通知。"},{"id":1620,"unit":6,"lesson":2,"word":"estate","pronunciation":"/ɪˈsteɪt/","meaning":"n.住宅区;工业区","seq":29,"isStar":false,"memo":"谐音 单词发音类似“爱死它的”→有些人最爱的是自己的“个人财产”。","example":"These 18-hour cities are beginning to make waves in real estate rankings. 这些“18小时城市”开始在房地产排行榜上掀起波澜。"},{"id":1621,"unit":6,"lesson":2,"word":"wealth","pronunciation":"/welθ/","meaning":"n.财产,财富;大量","seq":30,"isStar":false,"memo":"谐音 单词发音类似“威尔士”→威尔士这个国家有“大量”的城堡,“财产”丰富。","example":"It is widely accepted that everybody has the right to share in the wealth of the country. 人们普遍认为,每个人都有分享国家财富的权利。"},{"id":1622,"unit":6,"lesson":2,"word":"wealthy","pronunciation":"/ˈwelθi/","meaning":"adj.富有的,富裕的","seq":31,"isStar":false},{"id":1623,"unit":6,"lesson":2,"word":"treasure","pronunciation":"/ˈtreʒə(r)/","meaning":"n.珠宝;财富 v.珍视;珍藏","seq":32,"isStar":false,"memo":"谐音 单词发音类似“揣着”→他揣着掖着,不想让外人看见他珍爱的财宝→财富;珍视","example":"They were digging for buried treasure. 他们在挖掘埋在地下的宝藏。"},{"id":1624,"unit":6,"lesson":2,"word":"enrich","pronunciation":"/ɪnˈrɪtʃ/","meaning":"v.充实,使丰富;使富有","seq":33,"isStar":false,"memo":"构词 en-(使)+rich(富有)→使富有、使更丰满→充实，使丰富；使富有","example":"He used the knowledge to enrich himself. 他利用知识来丰富自己。"},{"id":1625,"unit":6,"lesson":2,"word":"incentive","pronunciation":"/ɪnˈsentɪv/","meaning":"n.激励;刺激;动力","seq":34,"isStar":false,"memo":"联想 in(里面)+cent(分)+-ive(名词后缀)→家里穷到只剩一分钱了,这“激励”他奋发图强。","example":"There needs to be strong economic incentives for companies to locate here. 需要有强有力的经济激励措施来鼓励企业在这里落户。"},{"id":1626,"unit":6,"lesson":2,"word":"decent","pronunciation":"/ˈdiːsnt/","meaning":"adj.体面的;像样的;正派的","seq":35,"isStar":false,"memo":"联想 de(音似“弟”)+cent(分)→弟弟捡到一分钱,把它交给警察,这是很“正派的”行为。","example":"They have a harder time getting a job with decent pay. 他们很难找到一份薪水可观的工作。"},{"id":1627,"unit":6,"lesson":2,"word":"accent","pronunciation":"/ˈæksent/","meaning":"n.口音;重音;强调;特点 v.强调","seq":36,"isStar":false,"memo":"构词 ac-(加强)+cent(唱，同 chant 吟唱)→唱歌时的腔调→口音；重音；强调","example":"His Chinese accent was quite pure. 他的中国口音很纯正。"},{"id":1628,"unit":6,"lesson":2,"word":"property","pronunciation":"/ˈprɒpəti/","meaning":"n.所有物;财产;不动产,房地产","seq":37,"isStar":false,"memo":"联想 proper(合适的)+-ty(名词后缀)→有些人觉得“财产”多的人才是合适的朋友。","example":"The chief duty of every government is to protect persons and property. 每个政府的首要职责都是保护人民和国家财产。"},{"id":1629,"unit":6,"lesson":2,"word":"proper","pronunciation":"/ˈprɒpə(r)/","meaning":"adj.正确的,恰当的;符合规则的","seq":38,"isStar":false,"memo":"构词：pro-（向前）+ per（尝试、通过）→ 向前走对路→恰当的！像穿西装打领带进校长办公室。","example":"Students must use proper citations when quoting academic sources. 学生引用学术资料时必须使用恰当的引注格式。"},{"id":1630,"unit":6,"lesson":2,"word":"appropriate","pronunciation":"/əˈprəʊpriət/","meaning":"adj.适当的,合适的","seq":39,"isStar":false,"memo":"构词 ap-(一再地)+propri(=proper)+-ate(形容词后缀)→适当的,合适的","example":"Appropriate arrangements will be made for their work and livelihood. 他们的工作和生活会得到妥善的安排。"},{"id":1631,"unit":6,"lesson":2,"word":"suitable","pronunciation":"/ˈsuːtəb(ə)l/","meaning":"adj.合适的,适宜的","seq":40,"isStar":false,"memo":"构词 suit(适合)+-able(形容词后缀)→合适的,适宜的","example":"They know best which universities are most suitable for their children. 他们最清楚哪些大学最适合自己的孩子。"},{"id":1632,"unit":6,"lesson":2,"word":"suit","pronunciation":"/suːt/","meaning":"n.套装;西服;诉讼 v.适合","seq":41,"isStar":false,"memo":"联想 与 suite(一套)同源：一套配齐的东西→套装；引申为“合某人心意”","example":"Products must be designed to suit the taste of the consumer. 产品设计必须符合消费者的口味。"},{"id":1633,"unit":6,"lesson":2,"word":"outfit","pronunciation":"/ˈaʊtfɪt/","meaning":"n.全套服装;全套装备 v.装备","seq":42,"isStar":false,"memo":"联想 out(外面)+fit(合身)→去外面时需要换一套合身的衣服→全套服装","example":"I'm looking for a necklace to complete my outfit.我在找一条项链来配我的全套衣服。"},{"id":1634,"unit":6,"lesson":2,"word":"suite","pronunciation":"/swiːt/","meaning":"n.套房(尤指酒店的豪华套房);一套家具","seq":43,"isStar":false,"memo":"联想 suit(套装)+e→套房;一套家具","example":"I suggest we fit you up with an office suite. 我建议我们为你配备一间办公套房。"},{"id":1635,"unit":6,"lesson":2,"word":"possess","pronunciation":"/pəˈzes/","meaning":"v.拥有,具有","seq":44,"isStar":false,"memo":"联想 po(联想“魄”)+ss(联想“美女”)+e+ss(联想“美女”)→即使陷入落魄的困境,这些美女内心仍“拥有”希望。","example":"I'm afraid this is the only suitcase I possess. 恐怕我只有这一个箱子。"},{"id":1636,"unit":6,"lesson":2,"word":"possession","pronunciation":"/pəˈzeʃ(ə)n/","meaning":"n.拥有;财产","seq":45,"isStar":false},{"id":1637,"unit":6,"lesson":2,"word":"possessive","pronunciation":"/pəˈzesɪv/","meaning":"adj.要求悉心关爱的;占有欲强的","seq":46,"isStar":false},{"id":1638,"unit":6,"lesson":2,"word":"fund","pronunciation":"/fʌnd/","meaning":"n.基金;资金 v.为……提供资金","seq":47,"isStar":false,"memo":"对照 他发现了(found)很多资金(fund)。","example":"This school is funded by both the local and state governments. 该学校由当地政府和州政府共同资助。"},{"id":1639,"unit":6,"lesson":2,"word":"funding","pronunciation":"/ˈfʌndɪŋ/","meaning":"n.专款,拨款","seq":48,"isStar":false},{"id":1640,"unit":6,"lesson":2,"word":"refund","pronunciation":"/ˈriːfʌnd/","meaning":"n.退款,返还款 v.退还,退(款)","seq":49,"isStar":false,"memo":"构词 re-(回)+fund(资金)→退还,退(款)","example":"Ask for a refund if the goods are faulty. 商品如有缺陷,可要求退款。"},{"id":1641,"unit":6,"lesson":2,"word":"finance","pronunciation":"/ˈfaɪnæns/","meaning":"n.资金;金融;财务 v.提供资金","seq":50,"isStar":false,"memo":"谐音 单词发音类似“犯难死”→没有足够的“资金”维持公司的运营,这让他犯了难。","example":"She felt that she should contribute to the household finances. 她觉得她应该为家庭财务做出贡献。"},{"id":1642,"unit":6,"lesson":2,"word":"financial","pronunciation":"/faɪˈnænʃ(ə)l/","meaning":"adj.财务的;金融的","seq":51,"isStar":false},{"id":1643,"unit":6,"lesson":2,"word":"crisis","pronunciation":"/ˈkraɪsɪs/","meaning":"n.危机,危急关头","seq":52,"isStar":false,"memo":"联想 cri(联想 cry)+sis(联想“死”)→他遇到了“危机”,要哭死了。","example":"At times of crisis, grain is the food of life. 在危机时期,谷物是生命之食物。"},{"id":1644,"unit":6,"lesson":2,"word":"budget","pronunciation":"/ˈbʌdʒɪt/","meaning":"n.预算 v.编入预算","seq":53,"isStar":false,"memo":"联想 bu(音似“爸”)+d+get(得到)→爸爸得到了很多“预算”。","example":"Many families struggle to balance the household budget. 许多家庭努力平衡家庭预算。"},{"id":1645,"unit":6,"lesson":2,"word":"budgetary","pronunciation":"/ˈbʌdʒɪtəri/","meaning":"adj.预算的","seq":54,"isStar":false},{"id":1646,"unit":6,"lesson":2,"word":"target","pronunciation":"/ˈtɑːɡɪt/","meaning":"n.对象,目标","seq":55,"isStar":false,"memo":"联想 ta(联想“他”)+r(联想“人”)+get(达到)→他达到了“目标”,令人刮目相看。","example":"Set yourself targets that you can reasonably hope to achieve. 给自己设定合理的有望达到的目标。"},{"id":1647,"unit":6,"lesson":2,"word":"mortgage","pronunciation":"/ˈmɔːɡɪdʒ/","meaning":"n.按揭(由银行等提供房产抵押借款)","seq":56,"isStar":false,"memo":"联想 mortga(音似“摩给”)+ge(联想“哥”)→我把最爱的摩托给哥哥,当作“抵押”。","example":"Mortgage lenders are now careful about borrowers' qualifications. 现在抵押贷款机构对借款人的资格非常谨慎。"},{"id":1648,"unit":6,"lesson":2,"word":"profit","pronunciation":"/ˈprɒfɪt/","meaning":"n.利润;好处 v.获益,得到好处","seq":57,"isStar":false,"memo":"联想 pro-(提前)+fi(音似“肥”)+t(联想“他”)→他提前比别人肥(胖)了,大概是因为他得到了很多“好处”。","example":"They want to return to the past and to invest money for profit. 他们想回到过去,投资赚钱。"},{"id":1649,"unit":6,"lesson":2,"word":"profitable","pronunciation":"/ˈprɒfɪtəb(ə)l/","meaning":"adj.有利润的;有益的","seq":58,"isStar":false},{"id":1650,"unit":6,"lesson":2,"word":"benefit","pronunciation":"/ˈbenɪfɪt/","meaning":"n.优势;益处 v.使受益","seq":59,"isStar":false,"memo":"谐音 单词发音类似“比你肥”→他找了份比你的工作肥(好处多)的工作,说明他有“优势”。","example":"It generates huge social benefits. 它产生巨大的社会效益。"},{"id":1651,"unit":6,"lesson":2,"word":"beneficial","pronunciation":"/ˌbenɪˈfɪʃ(ə)l/","meaning":"adj.有利的","seq":60,"isStar":false},{"id":1652,"unit":6,"lesson":2,"word":"beneficiary","pronunciation":"/ˌbenɪˈfɪʃəri/","meaning":"n.受益者;遗产继承人","seq":61,"isStar":false},{"id":1653,"unit":6,"lesson":2,"word":"pension","pronunciation":"/ˈpenʃ(ə)n/","meaning":"n.养老金,退休金","seq":62,"isStar":false,"memo":"谐音‘盆盛’——退休后靠‘盆’里盛的养老金过日子！pen-（关押→引申为‘积蓄’）+sion。","example":"Most citizens rely on state pension after retirement. 大多数公民退休后依赖国家养老金。"},{"id":1654,"unit":6,"lesson":2,"word":"pensioner","pronunciation":"/ˈpenʃənə(r)/","meaning":"n.领养老金(或退休金、抚恤金)者","seq":63,"isStar":false},{"id":1655,"unit":6,"lesson":2,"word":"premium","pronunciation":"/ˈpriːmiəm/","meaning":"n.保险费;额外费用","seq":64,"isStar":false,"memo":"联想 pre-(提前) + m(联想“妹”) + i(我) + u(字母音似 you) + m(联想“妈”)→妹妹、我、你和妈妈都提前交了“保险费”。","example":"Premiums are guaranteed throughout the term of the policy. 在保单的有效期内,所缴纳的保险费是有保障的。"},{"id":1656,"unit":6,"lesson":2,"word":"expense","pronunciation":"/ɪkˈspens/","meaning":"n.费用,花费","seq":65,"isStar":false,"memo":"对照 expensive adj.昂贵的;花钱多的→expense n.","example":"Living expenses there are comparatively low. 那里的生活费用相对较低。"},{"id":1657,"unit":6,"lesson":2,"word":"expensive","pronunciation":"/ɪkˈspensɪv/","meaning":"adj.昂贵的,花钱多的,价格高的","seq":66,"isStar":false},{"id":1658,"unit":6,"lesson":2,"word":"dispense","pronunciation":"/dɪˈspens/","meaning":"v.分配,分发;提供","seq":67,"isStar":false,"memo":"联想 dis-(分开) + pens(钢笔) + e→分开给钢笔→分配,分发","example":"The machine dispenses a range of drinks and snacks. 这台机器发售各种饮料和小吃。"},{"id":1659,"unit":6,"lesson":2,"word":"expenditure","pronunciation":"/ɪkˈspendɪtʃə(r)/","meaning":"n.花费,开支;耗费","seq":68,"isStar":false,"memo":"构词 expend(花费) + -iture(名词后缀)→花费,开支;耗费","example":"This study represents a major expenditure of time and effort. 这项研究意味着要耗费大量的时间和精力。"},{"id":1660,"unit":6,"lesson":2,"word":"monopoly","pronunciation":"/məˈnɒpəli/","meaning":"n.垄断;垄断者;垄断商品","seq":69,"isStar":false,"memo":"联想 mon(音似“莫”) + no(没有) + poly (音似“魄力”)→想把事业做大,形成“垄断”地位,就不能没有魄力。","example":"The company holds a monopoly of the market. 这家公司在市场上处于垄断地位。"},{"id":1661,"unit":6,"lesson":2,"word":"monopolise/-ize","pronunciation":"/məˈnɒpəlaɪz/","meaning":"v.独占,垄断","seq":70,"isStar":false,"memo":"构词 mono(单一)+pol(卖，同 monopoly 垄断)+-ise/-ize(使…化)→只让一家独卖→独占，垄断","example":"The firm monopolised the local market. 这家公司垄断了当地市场。"},{"id":1662,"unit":6,"lesson":2,"word":"policy","pronunciation":"/ˈpɒləsi/","meaning":"n.政策,方针;原则","seq":71,"isStar":false,"memo":"构词 polic(城邦管理，同 police)+-y(名词后缀)→管理城邦的办法→政策，方针；原则","example":"They defended the new policy. 他们维护新政策。"},{"id":1663,"unit":6,"lesson":2,"word":"stock","pronunciation":"/stɒk/","meaning":"n.(商店的)现货,存货;股票","seq":72,"isStar":false,"memo":"[对照] 商店(store)储存(stock)了很多现货(stock)。","example":"We stock a wide range of kitchen equipment. 我们备有各种厨房用品。"},{"id":1664,"unit":6,"lesson":2,"word":"livestock","pronunciation":"/ˈlaɪvstɒk/","meaning":"n.牲畜,家畜","seq":73,"isStar":false,"memo":"[构词] live(活着的)+stock(家畜)→牲畜,家畜","example":"The robots are not limited to herding and monitoring livestock. 机器人并不局限于放牧和监控牲畜。"},{"id":1665,"unit":6,"lesson":2,"word":"stack","pronunciation":"/stæk/","meaning":"n.一叠","seq":74,"isStar":false,"memo":"[联想] s(联想“美女”)+tack(音似“待客”)→美女结婚时要招待“大量”客人。","example":"The floor was stacked with boxes. 地板上码放着一摞摞箱子。"},{"id":1666,"unit":6,"lesson":2,"word":"valuable","pronunciation":"/ˈvæljuəb(ə)l/","meaning":"adj.宝贵的;贵重的","seq":75,"isStar":false,"memo":"构词 value(价值)+-able(可…的)→有价值可言的→宝贵的，贵重的","example":"They missed lots of valuable information. 他们错过了很多有价值的信息。"},{"id":1667,"unit":6,"lesson":2,"word":"value","pronunciation":"/ˈvæljuː/","meaning":"n.价值;价值观","seq":76,"isStar":false},{"id":1668,"unit":6,"lesson":2,"word":"evaluate","pronunciation":"/ɪˈvæljueɪt/","meaning":"v.评价,评估","seq":77,"isStar":false,"memo":"[构词] e-(出)+valu(e)(价值)+-ate(动词后缀)→说出物品的价值→评价,评估","example":"We need to learn how to evaluate them properly. 我们需要学习如何正确评估它们。"},{"id":1669,"unit":6,"lesson":2,"word":"evaluation","pronunciation":"/ɪˌvæljuˈeɪʃn/","meaning":"n.估计;评价,评估","seq":78,"isStar":false},{"id":1670,"unit":6,"lesson":2,"word":"emphasis","pronunciation":"/ˈemfəsɪs/","meaning":"n.强调;重视;重要性","seq":79,"isStar":false,"memo":"[对照] emphasise v.强调;重视→emphasis n.","example":"For the traditional home, there is too much emphasis on family continuity and stability. 传统家庭过分强调家庭的延续性和稳定性。"},{"id":1671,"unit":6,"lesson":2,"word":"emphasise/-ize","pronunciation":"/ˈemfəsaɪz/","meaning":"v.强调;重视","seq":80,"isStar":false,"memo":"构词 em-(使进入)+phas(显现，同 phase 相位)+-ise/-ize(使…化)→使显现出来→强调，重视","example":"He emphasised the need for teamwork. 他强调了团队合作的必要性。"},{"id":1672,"unit":6,"lesson":2,"word":"emphatic","pronunciation":"/ɪmˈfætɪk/","meaning":"adj.强调的,有力的","seq":81,"isStar":false},{"id":1673,"unit":6,"lesson":2,"word":"synthesis","pronunciation":"/ˈsɪnθəsɪs/","meaning":"n.综合;结合,合成","seq":82,"isStar":false,"memo":"[联想] syn(音似“神”)+the(那)+sis(联想sister)→神和那个姐姐“结合”在一起,打败了坏人。","example":"It is a synthesis of art with everyday life. 它是艺术与日常生活的结合。"},{"id":1674,"unit":6,"lesson":2,"word":"synthetic","pronunciation":"/sɪnˈθetɪk/","meaning":"adj.人造的,合成的","seq":83,"isStar":false},{"id":1675,"unit":6,"lesson":2,"word":"synthesise/-ize","pronunciation":"/ˈsɪnθɪsaɪz/","meaning":"v.合成;综合","seq":84,"isStar":false,"memo":"构词 syn-(一起)+thes(放置，同 thesis 命题)+-ise/-ize(使…化)→把各部分放到一起→合成，综合","example":"Plants synthesise sugar from sunlight. 植物利用阳光合成糖分。"},{"id":1676,"unit":6,"lesson":2,"word":"highlight","pronunciation":"/ˈhaɪlaɪt/","meaning":"n.最突出(或最精彩、最激动人心)的部分","seq":85,"isStar":false,"memo":"[构词] high(高)+light(光)→突出","example":"The highlights of the match will be shown later this evening. 本场比赛最精彩的片段将于今晚晚些时候播出。"},{"id":1677,"unit":6,"lesson":2,"word":"limelight","pronunciation":"/ˈlaɪmlaɪt/","meaning":"n.公众关注的焦点","seq":86,"isStar":false,"memo":"记 (联想) li(联想“立”)+me(我)+light(灯光)→我站立在灯光之下,成为“公众关注的焦点”。","example":"She likes being in the limelight.她喜欢成为众人瞩目的焦点。"},{"id":1678,"unit":6,"lesson":2,"word":"grave","pronunciation":"/ɡreɪv/","meaning":"n.坟墓 adj.严重的;严肃的","seq":87,"isStar":false,"memo":"gr(联想“官人”) + ave(音似“爱我”) → 官人爱我终生→“生同衾,死同穴”→坟墓","example":"The leakage of a state secret is a grave crime. 泄露国家机密是严重的罪行。"},{"id":1679,"unit":6,"lesson":2,"word":"gravity","pronunciation":"/ˈɡrævəti/","meaning":"n.重力;严重性;庄严","seq":88,"isStar":false},{"id":1680,"unit":6,"lesson":2,"word":"aggravate","pronunciation":"/ˈæɡrəveɪt/","meaning":"v.使严重,使恶化;激怒","seq":89,"isStar":false,"memo":"ag-(一再地) + grav(e)(严重的) + -ate(动词后缀)→使严重","example":"The financial problem of this company is further aggravated by the rise in interest rates. 利率上升使这家公司的财务问题进一步恶化。"},{"id":1681,"unit":6,"lesson":2,"word":"aggravation","pronunciation":"/ˌæɡrəˈveɪʃ(ə)n/","meaning":"n.恶化;加剧","seq":90,"isStar":false},{"id":1682,"unit":6,"lesson":2,"word":"grant","pronunciation":"/ɡrɑːnt/","meaning":"n.拨款,补助金 v.给予;准予;承认","seq":91,"isStar":false,"memo":"gr(联想“官人”) + ant(蚂蚁)→大雨来临,官人打开门,“准予”蚂蚁进来躲雨。","example":"He has been awarded a research grant. 他得到一笔研究经费。"},{"id":1683,"unit":6,"lesson":2,"word":"granted","pronunciation":"/ˈɡrɑːntɪd/","meaning":"adv.的确,诚然","seq":92,"isStar":false},{"id":1684,"unit":6,"lesson":2,"word":"grind","pronunciation":"/ɡraɪnd/","meaning":"v.磨碎;使锋利 n.刺耳的摩擦声","seq":93,"isStar":false,"memo":"gr(联想“官人”) + in(里面) + d(联想“刀”)→官人在家里磨刀→磨碎;使锋利","example":"The grind of heavy machines could get on their nerves. 重型机器的摩擦声让他们心烦意乱。"},{"id":1685,"unit":6,"lesson":2,"word":"grid","pronunciation":"/ɡrɪd/","meaning":"n.网格;输电网","seq":94,"isStar":false,"memo":"联想 gr(联想“官人”)+id(联想 identity)→把官人的身份输入电脑,出来很多“网格”,可以分析他的身份信息。","example":"He knew nothing about the development of the country's electricity grid.他对国家电网的发展一无所知。"},{"id":1686,"unit":6,"lesson":2,"word":"grieve","pronunciation":"/ɡriːv/","meaning":"v.悲伤,悲痛;使伤心","seq":95,"isStar":false,"memo":"gr(联想“官人”) + i(字母音似“爱”) + eve(联想 Eve,“夏娃”)→凡间的官人爱上了夏娃,这使亚当和夏娃都很“悲伤”。","example":"He grieved to death over the loss of his wife. 他因失去妻子而悲痛欲绝。"},{"id":1687,"unit":6,"lesson":2,"word":"grief","pronunciation":"/ɡriːf/","meaning":"n.悲伤,悲痛","seq":96,"isStar":false},{"id":1688,"unit":6,"lesson":2,"word":"grievous","pronunciation":"/ˈɡriːvəs/","meaning":"adj.极严重的;使人痛苦的;令人伤心的","seq":97,"isStar":false,"memo":"构词 griev(沉重，同 grief 悲伤)+-ous(形容词后缀)→压得人喘不过气的→极严重的，使人痛苦的","example":"He suffered grievous injuries in the crash. 他在撞车事故中受了重伤。"},{"id":1689,"unit":6,"lesson":2,"word":"relieve","pronunciation":"/rɪˈliːv/","meaning":"v.减轻,缓和(不快或痛苦)","seq":98,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+li(联想“立”)+eve(联想 Eve,“夏娃”)→阿姨看到夏娃很难过,就站立在夏娃身边安慰她,“缓和”她的痛苦。","example":"The new secretary will relieve us of some of the paperwork. 新来的秘书会减轻我们的一些文书工作。"},{"id":1690,"unit":6,"lesson":2,"word":"relief","pronunciation":"/rɪˈliːf/","meaning":"n.宽慰;救济;(焦虑、痛苦等的)减轻","seq":99,"isStar":false},{"id":1691,"unit":6,"lesson":2,"word":"alleviate","pronunciation":"/əˈliːvieɪt/","meaning":"v.减轻,缓解","seq":100,"isStar":false,"memo":"联想 al-(= to) + levi (联想时装品牌 Levi's,李维斯) +-ate(动词后缀)→他因考试成绩不理想很烦恼,妈妈给他买新衣服,以“缓解”他的不良情绪。","example":"Cutting trees to grow more food can hardly alleviate the shortage of food. 砍伐树木来种植更多的粮食几乎无法缓解粮食短缺问题。"},{"id":1692,"unit":6,"lesson":2,"word":"alleviation","pronunciation":"/əˌliːviˈeɪʃn/","meaning":"n.减轻,缓解","seq":101,"isStar":false},{"id":1693,"unit":6,"lesson":2,"word":"calculate","pronunciation":"/ˈkælkjuleɪt/","meaning":"v.计算,核算;估计,推测","seq":102,"isStar":false,"memo":"联想 calcu(音似“开口”)+late(晚的)→他开口晚是因为把时间“计算”错了。","example":"Mothers' devotion to children can hardly be calculated. 母亲对孩子的奉献难以计算。"},{"id":1694,"unit":6,"lesson":2,"word":"calculator","pronunciation":"/ˈkælkjuleɪtə(r)/","meaning":"n.计算机,计算器","seq":103,"isStar":false},{"id":1695,"unit":6,"lesson":2,"word":"calculation","pronunciation":"/ˌkælkjuˈleɪʃ(ə)n/","meaning":"n.计算","seq":104,"isStar":false},{"id":1696,"unit":6,"lesson":2,"word":"calculating","pronunciation":"/ˈkælkjuleɪtɪŋ/","meaning":"adj.精明的","seq":105,"isStar":false},{"id":1697,"unit":6,"lesson":2,"word":"counter","pronunciation":"/ˈkaʊntə(r)/","meaning":"n.(商店、银行等的)柜台","seq":106,"isStar":false,"memo":"构词 count(计算)+-er(表物/表处)→数钱的地方→柜台；也作“反驳”“相反地”","example":"There aren't enough staff on duty at all the service counters. 所有服务柜台都没有足够的值班人员。"},{"id":1698,"unit":6,"lesson":2,"word":"account","pronunciation":"/əˈkaʊnt/","meaning":"n.账户;账目;说明 v.认为是","seq":107,"isStar":false,"memo":"构词 ac-(加强)+count(计算)→把钱算清楚的地方与说法→账户，账目；说明，认为是","example":"I paid the cheque into my savings account. 我把支票存入我的储蓄账户。"},{"id":1699,"unit":6,"lesson":3,"word":"accounting","pronunciation":"/əˈkaʊntɪŋ/","meaning":"n.会计","seq":1,"isStar":false},{"id":1700,"unit":6,"lesson":3,"word":"accountant","pronunciation":"/əˈkaʊntənt/","meaning":"n.会计,会计师","seq":2,"isStar":false,"memo":"记 (构词) ac-(一再地)+count(计算)+-ant","example":"I was making as much money as I was as an accountant.我赚的钱和当会计时一样多。"},{"id":1701,"unit":6,"lesson":3,"word":"accountancy","pronunciation":"/əˈkaʊntənsi/","meaning":"n.会计工作;会计职业","seq":3,"isStar":false},{"id":1702,"unit":6,"lesson":3,"word":"accountable","pronunciation":"/əˈkaʊntəbl/","meaning":"adj.负有责任的","seq":4,"isStar":false,"memo":"对照 他对此事是负有责任的(accountable)，所以需要解释(account for)一下。","example":"Politicians are ultimately accountable to the voters. 从政者最终向选民负责。"},{"id":1703,"unit":6,"lesson":3,"word":"accountability","pronunciation":"/əˌkaʊntəˈbɪləti/","meaning":"n.负有责任","seq":5,"isStar":false},{"id":1704,"unit":6,"lesson":3,"word":"discount","pronunciation":"/ˈdɪskaʊnt/","meaning":"n.折扣 v.打折,打折出售","seq":6,"isStar":false,"memo":"构词 dis-(否定前缀) + count(计算)→没有计算在内的→打折","example":"They were selling everything at a discount. 他们销售的所有商品都打折。"},{"id":1705,"unit":6,"lesson":3,"word":"counterpart","pronunciation":"/ˈkaʊntəpɑːt/","meaning":"n.职位(或作用)相当的人;对应的事物","seq":7,"isStar":false,"memo":"构词 counter(相对) + part(部分)→对应的事物","example":"On average, US students study more topics within science and math than their international counterparts do. 平均而言，美国学生比他们的国际同学习更多关于科学和数学的主题。"},{"id":1706,"unit":6,"lesson":3,"word":"counterfeit","pronunciation":"/ˈkaʊntəfɪt/","meaning":"v.伪造","seq":8,"isStar":false,"memo":"记 (联想) counter(相反)+feit(音似“肥他”)→相反,他眼中的肥差竟是“伪造”的陷阱。","example":"Some criminals counterfeit money to make illegal profits.一些罪犯伪造货币牟取非法利润。"},{"id":1707,"unit":6,"lesson":3,"word":"counteract","pronunciation":"/ˌkaʊntərˈækt/","meaning":"v.抵制;抵消;抵抗","seq":9,"isStar":false,"memo":"构词 counter(相反) + act(行动，动作)→相反地行动→抵制；抵抗","example":"These exercises aim to counteract the effects of stress and tension. 这些训练动作旨在缓解压力与紧张。"},{"id":1708,"unit":6,"lesson":3,"word":"counteraction","pronunciation":"/ˌkaʊntərˈækʃən/","meaning":"n.抵制;抵消;抵抗","seq":10,"isStar":false},{"id":1709,"unit":6,"lesson":3,"word":"boycott","pronunciation":"/ˈbɔɪkɒt/","meaning":"n.抵制行动 v.拒绝购买;抵制","seq":11,"isStar":false,"memo":"联想 boy(男孩) + cott(音似“可他”)→姐姐对这个男孩很好，可他还是“抵制”跟她一起回家。","example":"They decide to boycott the products of the fashion industry. 他们决定抵制时尚行业的产品。"},{"id":1710,"unit":6,"lesson":3,"word":"encounter","pronunciation":"/ɪnˈkaʊntə(r)/","meaning":"v.遭遇;偶然碰到 n.相遇,邂逅;遭遇","seq":12,"isStar":false,"memo":"构词 en-(使) + counter(相对)→使相对→相遇","example":"It has encountered increasingly tougher challenges. 它遇到了越来越严峻的挑战。"},{"id":1711,"unit":6,"lesson":3,"word":"confront","pronunciation":"/kənˈfrʌnt/","meaning":"v.面对;对抗","seq":13,"isStar":false,"memo":"构词 con-(共同) + front(前面，面向)→面对；对抗","example":"They are unaware of the potential risks they are confronting. 他们并没有察觉到自己正面临的潜在风险。"},{"id":1712,"unit":6,"lesson":3,"word":"confrontation","pronunciation":"/ˌkɒnfrʌnˈteɪʃn/","meaning":"n.对抗;冲突","seq":14,"isStar":false},{"id":1713,"unit":6,"lesson":3,"word":"transaction","pronunciation":"/trænˈzækʃ(ə)n/","meaning":"n.交易","seq":15,"isStar":false,"memo":"构词 trans-(从……到……) + act(行动) + -ion(名词后缀)→交易","example":"Using the internet can significantly reduce transaction costs. 因特网的使用可以大大减少交易成本。"},{"id":1714,"unit":6,"lesson":3,"word":"transit","pronunciation":"/ˈtrænzɪt/","meaning":"n.运输,运送","seq":16,"isStar":false,"memo":"联想 trans-(从……到……) + it(它)→把它从这儿弄到那儿→运输,运送","example":"The goods were damaged in transit. 货物在运输中损坏了。"},{"id":1715,"unit":6,"lesson":3,"word":"transition","pronunciation":"/trænˈzɪʃ(ə)n/","meaning":"n.过渡;变迁","seq":17,"isStar":false,"memo":"【构词】trans-（跨）+ it-（走）+ -ion → ‘跨步走’→从一状态走到另一状态→过渡；联想‘转神’——考研失败后转神般进入职场。","example":"The transition from high school to university requires strong time-management skills. 从高中到大学的过渡需要强大的时间管理能力。"},{"id":1716,"unit":6,"lesson":3,"word":"transitional","pronunciation":"/trænˈzɪʃən(ə)l/","meaning":"adj.变迁的;过渡期的","seq":18,"isStar":false},{"id":1717,"unit":6,"lesson":3,"word":"transform","pronunciation":"/trænsˈfɔːm/","meaning":"v.使改变形态","seq":19,"isStar":false,"memo":"构词 trans-(从……到……) + form(形式)→从这种形式到那种形式→使改变形态","example":"Every aspect of our lives will be transformed. 我们生活的方方面面都将被改变。"},{"id":1718,"unit":6,"lesson":3,"word":"transformation","pronunciation":"/ˌtrænsfəˈmeɪʃ(ə)n/","meaning":"n.变化,改革","seq":20,"isStar":false},{"id":1719,"unit":6,"lesson":3,"word":"transplant","pronunciation":"/trænsˈplɑːnt/","meaning":"v.移种;移植;(使)迁移 n.移植","seq":21,"isStar":false,"memo":"构词 trans-(从……到……) + plant(种植)→移种;移植","example":"Surgeons have successfully transplanted a liver into a four-year-old boy. 外科医生成功地给一个四岁的男孩移植了肝脏。"},{"id":1720,"unit":6,"lesson":3,"word":"transplantation","pronunciation":"/ˌtrænsplɑːnˈteɪʃn; ˌtrænzplɑːnˈteɪʃn/","meaning":"n.移植,移种,移植","seq":22,"isStar":false},{"id":1721,"unit":6,"lesson":3,"word":"transfer","pronunciation":"/trænsˈfɜː(r)/","meaning":"v.(使)转移;搬迁;调动 n.转移","seq":23,"isStar":false,"memo":"联想 trans-(从……到……) + fer(音似“佛”)→唐僧师徒把佛经从西天取回了大唐→转移;搬迁","example":"The patient was transferred to another hospital. 患者被转送到了另一家医院。"},{"id":1722,"unit":6,"lesson":3,"word":"transference","pronunciation":"/ˈtrænsfərəns/","meaning":"n.转移;调动","seq":24,"isStar":false},{"id":1723,"unit":6,"lesson":3,"word":"transient","pronunciation":"/ˈtrænziənt/","meaning":"adj.短暂的;临时的 n.过往旅客","seq":25,"isStar":false,"memo":"联想 trans-(从……到……) + i(我) + ent (联想 enter)→我从这儿进来后很快便出去了→短暂的;临时的","example":"Money seemed to do little more than buy transient relief from their terrible moans. 金钱似乎只是暂时缓解了他们可怕的抱怨。"},{"id":1724,"unit":6,"lesson":3,"word":"transparent","pronunciation":"/trænsˈpærənt/","meaning":"adj.透明的;易懂的","seq":26,"isStar":false,"memo":"对照:父母(parent)对彼此很了解,信息是透明的(transparent)。","example":"The insect's wings are almost transparent. 这种昆虫的翅膀几乎是透明的。"},{"id":1725,"unit":6,"lesson":3,"word":"transparency","pronunciation":"/trænsˈpærənsi/","meaning":"n.透明;易懂","seq":27,"isStar":false},{"id":1726,"unit":6,"lesson":3,"word":"apparent","pronunciation":"/əˈpærənt/","meaning":"adj.明显的;显而易见的","seq":28,"isStar":false,"memo":"联想:ap(联想“安排”)+parent(父母)→父母安排他做家务,显然是想锻炼他→明显的","example":"More apparent reasonableness followed. 接下来还有一些更显而易见的合理性。"},{"id":1727,"unit":6,"lesson":3,"word":"apparently","pronunciation":"/əˈpærəntli/","meaning":"adv.可见;看来;显然地","seq":29,"isStar":false},{"id":1728,"unit":6,"lesson":3,"word":"opaque","pronunciation":"/əʊˈpeɪk/","meaning":"adj.不透明的;难理解的","seq":30,"isStar":false,"memo":"谐音:单词发音类似“欧佩克”→OPEC,石油输出国组织→石油的价格是“不透明的”。","example":"You can use opaque glass if you need to block a street view. 如果你需要挡住外面的街景,你可以使用不透明玻璃。"},{"id":1729,"unit":6,"lesson":3,"word":"consume","pronunciation":"/kənˈsjuːm/","meaning":"v.消耗,耗费","seq":31,"isStar":false,"memo":"联想:con-(所有)+sume(音似“输me”)→游戏最后所有人都输了,只有我凭“消耗”策略胜出。","example":"A grown lion can easily consume 60 pounds of meat at a single feeding. 一头成年狮子单次进食就能轻松吃掉60磅肉。"},{"id":1730,"unit":6,"lesson":3,"word":"consumer","pronunciation":"/kənˈsjuːmə(r)/","meaning":"n.消费者","seq":32,"isStar":false},{"id":1731,"unit":6,"lesson":3,"word":"consumption","pronunciation":"/kənˈsʌmpʃ(ə)n/","meaning":"n.消费;消耗量","seq":33,"isStar":false},{"id":1732,"unit":6,"lesson":3,"word":"resume","pronunciation":"/rɪˈzjuːm; ˈrezjuːmeɪ/","meaning":"v.重新开始;继续","seq":34,"isStar":false,"memo":"联想:re(字母音似“阿姨”)+sume(音似“输me”)→阿姨输给了我,然后她“重新开始”向我发起挑战。","example":"He got back in the car and resumed driving. 他回到车上,继续开车。"},{"id":1733,"unit":6,"lesson":3,"word":"resumption","pronunciation":"/rɪˈzʌmpʃn/","meaning":"n.重新开始;恢复","seq":35,"isStar":false},{"id":1734,"unit":6,"lesson":3,"word":"résumé","pronunciation":"/ˈrezjuːmeɪ; ˈrezjʊmeɪ; ˈreɪzjʊmeɪ/","meaning":"n.摘要;个人简历","seq":36,"isStar":false,"memo":"借自法语 résumé(概要)：把经历浓缩成一页纸→摘要；个人简历","example":"Please send your résumé to our office. 请把你的简历寄到我们办公室。"},{"id":1735,"unit":6,"lesson":3,"word":"presume","pronunciation":"/prɪˈzjuːm/","meaning":"v.假设,假定;设想","seq":37,"isStar":false,"memo":"pre-(提前) + su(联想“输”) + me(我)→比赛提前开始，他“假设”你会输给我。","example":"A great many people presume upon a reward when doing a good deed. 许多人在做善事时都设想得到回报。"},{"id":1736,"unit":6,"lesson":3,"word":"presumption","pronunciation":"/prɪˈzʌmpʃ(ə)n/","meaning":"n.推测,假定","seq":38,"isStar":false},{"id":1737,"unit":6,"lesson":3,"word":"presumably","pronunciation":"/prɪˈzjuːməbli/","meaning":"adv.很可能,大概","seq":39,"isStar":false},{"id":1738,"unit":6,"lesson":3,"word":"hypothesis","pronunciation":"/haɪˈpɒθəsɪs/","meaning":"n.假说,假设;猜想","seq":40,"isStar":false,"memo":"hypo(音似“害怕”) + the(那) + sis(联想 sister)→姐姐害怕那个“假说”。","example":"He confirmed the hypothesis. 他证实了那个假设。"},{"id":1739,"unit":6,"lesson":3,"word":"assume","pronunciation":"/əˈsjuːm/","meaning":"v.假定,认为;承担;就职","seq":41,"isStar":false,"memo":"as-(一再地) + su(联想“输”) + me(我)→每个人都有优缺点，对手不可能一再地输给我，这只是一种“假定”。","example":"They eat much less than people assume. 他们吃得比人们认为的要少得多。"},{"id":1740,"unit":6,"lesson":3,"word":"assumption","pronunciation":"/əˈsʌmpʃn/","meaning":"n.假设;承担;担任","seq":42,"isStar":false},{"id":1741,"unit":6,"lesson":3,"word":"resemble","pronunciation":"/rɪˈzemb(ə)l/","meaning":"v.看起来像,与……相似","seq":43,"isStar":false,"memo":"re-(重复) + sem(音似 same) + ble→与……相似","example":"He grew up to resemble his father. 他长大了，很像他父亲。"},{"id":1742,"unit":6,"lesson":3,"word":"resemblance","pronunciation":"/rɪˈzembləns/","meaning":"n.相似,相像","seq":44,"isStar":false},{"id":1743,"unit":6,"lesson":3,"word":"appease","pronunciation":"/əˈpiːz/","meaning":"v.安抚,抚慰","seq":45,"isStar":false,"memo":"构词 ap-(一再地) + peas(和平) + e → 使平静 → 安抚，抚慰","example":"The move was widely seen as an attempt to appease critics of the regime. 普遍认为，这一举措是试图安抚批评政权的人。"},{"id":1744,"unit":6,"lesson":3,"word":"appeasement","pronunciation":"/əˈpiːzmənt/","meaning":"n.安抚,抚慰","seq":46,"isStar":false},{"id":1745,"unit":6,"lesson":3,"word":"console","pronunciation":"/kənˈsəʊl/","meaning":"v.安慰,慰藉 n.操纵台,仪表板","seq":47,"isStar":false,"memo":"联想 con-(都) + sole(联想“馊了”) → 母亲留给我的好吃的都馊了，我满心愧疚地“安慰”失望的母亲。","example":"He wanted to console the two families. 他想安慰这两个家庭。"},{"id":1746,"unit":6,"lesson":3,"word":"consolation","pronunciation":"/ˌkɒnsəˈleɪʃ(ə)n/","meaning":"n.安慰,慰藉","seq":48,"isStar":false},{"id":1747,"unit":6,"lesson":3,"word":"sole","pronunciation":"/səʊl/","meaning":"adj.唯一的;独占的,专有的","seq":49,"isStar":false,"memo":"谐音 单词发音类似“馊”→他的东西馊了也不给别人吃，他要独占→独占的，专有的","example":"She has sole responsibility for the project. 这个项目由她一人负责。"},{"id":1748,"unit":6,"lesson":3,"word":"solely","pronunciation":"/ˈsəʊlli/","meaning":"adv.仅,只;单独地","seq":50,"isStar":false},{"id":1749,"unit":6,"lesson":3,"word":"solemn","pronunciation":"/ˈsɒləm/","meaning":"adj.冷峻的,表情严肃的;庄重的","seq":51,"isStar":false,"memo":"联想 so(如此) + lemn(音似“冷漠”)→他的表情如此冷漠→冷峻的，表情严肃的","example":"She was solemn, pulling at her blonde curls. 她表情严肃，拉扯着自己金黄色的卷发。"},{"id":1750,"unit":6,"lesson":3,"word":"solemnity","pronunciation":"/səˈlemnəti/","meaning":"n.庄严;庄重","seq":52,"isStar":false},{"id":1751,"unit":6,"lesson":3,"word":"solitary","pronunciation":"/ˈsɒlətri/","meaning":"adj.唯一的;单独的;孤单的","seq":53,"isStar":false,"memo":"联想 so(如此) + li(音似“累”) + tary→爬山竟如此累，我想一个人休息会儿→单独的","example":"Cultivating positive interpersonal relationships helped him expel solitary feelings. 建立积极的人际关系有助于他排解孤独感。"},{"id":1752,"unit":6,"lesson":3,"word":"solitude","pronunciation":"/ˈsɒlətjuːd/","meaning":"n.独处;隐居","seq":54,"isStar":false},{"id":1753,"unit":6,"lesson":3,"word":"solo","pronunciation":"/ˈsəʊləʊ/","meaning":"n.独唱;独奏;单人表演 adj.独自的","seq":55,"isStar":false,"memo":"构词 sol(单独，同 solitary 独自的)+-o→一个人的表演→独唱，独奏；独自的","example":"The original version featured a guitar solo. 原版以吉他独奏为特色。"},{"id":1754,"unit":6,"lesson":3,"word":"silence","pronunciation":"/ˈsaɪləns/","meaning":"n.寂静;沉默 v.使安静;压制","seq":56,"isStar":false,"memo":"对照 silent adj.沉默的；安静的→silence n.&v.","example":"It's an attempt to silence the opposition. 这是一次压制反对派的尝试。"},{"id":1755,"unit":6,"lesson":3,"word":"silent","pronunciation":"/ˈsaɪlənt/","meaning":"adj.沉默的;安静的","seq":57,"isStar":false,"memo":"【构词】sil-（安静，如silo静音仓）+ -ent → 像按下静音键的手机，sil-ent！","example":"The library requires silent study areas where even whispering is discouraged. 图书馆要求安静自习区，连耳语都不鼓励。"},{"id":1756,"unit":6,"lesson":3,"word":"mute","pronunciation":"/mjuːt/","meaning":"v.消音;减音 adj.沉默的","seq":58,"isStar":false,"memo":"构词 mut(无声，同 mutter 低声咕哝)+-e→不出声→消音，静音；沉默的，无声的","example":"They began to mute their voices, not be as assertive.他们开始压低声音，不再那么强势。"},{"id":1757,"unit":6,"lesson":3,"word":"assist","pronunciation":"/əˈsɪst/","meaning":"n.助攻 v.帮助,协助","seq":59,"isStar":false,"memo":"【构词】as-(= ad-,朝向) + sist(站)→站在旁边,提供支持→帮助","example":"We'll do all we can to assist you. 我们会尽量帮你。"},{"id":1758,"unit":6,"lesson":3,"word":"assistant","pronunciation":"/əˈsɪstənt/","meaning":"n.助手 adj.助理的;副的","seq":60,"isStar":false},{"id":1759,"unit":6,"lesson":3,"word":"assistance","pronunciation":"/əˈsɪstəns/","meaning":"n.帮助;援助;支持","seq":61,"isStar":false},{"id":1760,"unit":6,"lesson":3,"word":"persist","pronunciation":"/pəˈsɪst/","meaning":"v.坚持;维持;保持;持续存在","seq":62,"isStar":false,"memo":"联想 per(每一) + sist(站)→他每一天都站着，说明他能“坚持”。","example":"She persisted in her search for the truth.她坚持追求真相。"},{"id":1761,"unit":6,"lesson":3,"word":"persistence","pronunciation":"/pəˈsɪstəns/","meaning":"n.坚持;锲而不舍","seq":63,"isStar":false},{"id":1762,"unit":6,"lesson":3,"word":"persistent","pronunciation":"/pəˈsɪstənt/","meaning":"adj.坚持不懈的;执着的","seq":64,"isStar":false},{"id":1763,"unit":6,"lesson":3,"word":"insist","pronunciation":"/ɪnˈsɪst/","meaning":"v.坚持;强调","seq":65,"isStar":false,"memo":"【联想】in(在……里) + sist(联想 sister)→几个姐妹中,妹妹一直“坚持”自己的梦想。","example":"She insisted on his wearing a suit. 她坚持要他穿西装。"},{"id":1764,"unit":6,"lesson":3,"word":"insistence","pronunciation":"/ɪnˈsɪstəns/","meaning":"n.坚决要求;坚持","seq":66,"isStar":false},{"id":1765,"unit":6,"lesson":3,"word":"insistent","pronunciation":"/ɪnˈsɪstənt/","meaning":"adj.坚持的","seq":67,"isStar":false},{"id":1766,"unit":6,"lesson":3,"word":"consist","pronunciation":"/kənˈsɪst; ˈkɒnsɪst/","meaning":"v.由……组成(或构成)","seq":68,"isStar":false,"memo":"【构词】con-(一起) + sist(站)→站到一起→由……组成","example":"Its teaching staff consists of women only. 它的教师队伍全部由女性组成。"},{"id":1767,"unit":6,"lesson":3,"word":"resist","pronunciation":"/rɪˈzɪst/","meaning":"v.抵制;阻挡;反抗,抵抗","seq":69,"isStar":false,"memo":"【构词】re-(相反) + sist(站)→站在相反的位置→抵制;阻挡","example":"She finds it difficult to resist the temptation of ice cream. 她发现很难抵抗冰激凌的诱惑。"},{"id":1768,"unit":6,"lesson":3,"word":"resistant","pronunciation":"/rɪˈzɪstənt/","meaning":"adj.有抵抗力的","seq":70,"isStar":false,"memo":"【构词】re-（反）+ sist（站立，如 resist）+ -ant（形容词）→ ‘反着站住不动’，就是抵抗！细菌对药‘resistant’，药打不动它～","example":"Some bacteria have become resistant to common antibiotics. 某些细菌已对常用抗生素产生耐药性。"},{"id":1769,"unit":6,"lesson":3,"word":"resistance","pronunciation":"/rɪˈzɪstəns/","meaning":"n.抵制;抵抗","seq":71,"isStar":false},{"id":1770,"unit":6,"lesson":3,"word":"consistent","pronunciation":"/kənˈsɪstənt/","meaning":"adj.连续的;一致的;始终如一的","seq":72,"isStar":false,"memo":"【构词】con-(共同) + sist(站) + -ent(形容词后缀)→共同站在一起的→连续的;一致的","example":"They lack consistent support from peers. 他们缺乏同行的持续支持。"},{"id":1771,"unit":6,"lesson":3,"word":"consistency","pronunciation":"/kənˈsɪstənsi/","meaning":"n.一致性,连贯性","seq":73,"isStar":false},{"id":1772,"unit":6,"lesson":3,"word":"subsistence","pronunciation":"/səbˈsɪstəns/","meaning":"n.勉强维持生活","seq":74,"isStar":false,"memo":"构词 sub-(下面)+sist(站)+-ence(名词后缀)→站在下面的状态→勉强维持生活","example":"Many families are living below the level of subsistence.许多家庭生活在温饱线以下。"},{"id":1773,"unit":6,"lesson":3,"word":"transistor","pronunciation":"/trænˈzɪstə(r)/","meaning":"n.晶体管","seq":75,"isStar":false,"memo":"构词 trans-(转移)+sist(站立、阻挡)+-or(表物)→控制电流转移的元件→晶体管","example":"Some want to work with digital computers and transistors. 有些人想要研究数字计算机和晶体管。"},{"id":1774,"unit":6,"lesson":4,"word":"assemble","pronunciation":"/əˈsemb(ə)l/","meaning":"v.聚集;组装","seq":1,"isStar":false,"memo":"构词 as-(加强)+sembl(一起，同 similar 相似的)+-e→把零件聚到一起→聚集；组装","example":"We were requested to assemble in the lobby. 我们被要求在大厅集合。"},{"id":1775,"unit":6,"lesson":4,"word":"assembly","pronunciation":"/əˈsembli/","meaning":"n.装配;立法机构;议会","seq":2,"isStar":false},{"id":1776,"unit":6,"lesson":4,"word":"similar","pronunciation":"/ˈsɪmələ(r)/","meaning":"adj.相像的,相仿的,类似的","seq":3,"isStar":false,"memo":"构词 simil(相同，同 assimilate 同化)+-ar(形容词后缀)→长得像的→相像的，类似的","example":"There was a similar accident on the same stretch of track four years ago. 四年前，在同一段轨道上也发生过类似的事故。"},{"id":1777,"unit":6,"lesson":4,"word":"similarity","pronunciation":"/ˌsɪməˈlærəti/","meaning":"n.相像性,相似点","seq":4,"isStar":false,"memo":"构词 similar(相像的)+-ity(名词后缀)→相像之处→相像性，相似点","example":"The report highlights the similarity between the two groups.报告强调了这两组人之间的相似性。"},{"id":1778,"unit":6,"lesson":4,"word":"assimilate","pronunciation":"/əˈsɪməleɪt/","meaning":"v.透彻理解;吸收;(使)同化","seq":5,"isStar":false,"memo":"as-(一再地) + simil(联想 similar) + -ate(动词后缀)→一再地相似→吸收；(使)同化","example":"You have to assimilate the facts, not just remember them. 你需要透彻理解这些事实，而不仅仅是记住它们。"},{"id":1779,"unit":6,"lesson":4,"word":"assimilation","pronunciation":"/əˌsɪməˈleɪʃ(ə)n/","meaning":"n.吸收;接受","seq":6,"isStar":false},{"id":1780,"unit":6,"lesson":4,"word":"absorb","pronunciation":"/əbˈzɔːb/","meaning":"v.吸收;理解;使全神贯注","seq":7,"isStar":false,"memo":"构词 ab-(离开)+sorb(吸，同 sorbent 吸附剂)→把东西吸走→吸收；理解；使全神贯注","example":"They are more absorbed in what catches their eyes. 他们更专注于吸引他们目光的东西。"},{"id":1781,"unit":6,"lesson":4,"word":"absorption","pronunciation":"/əbˈzɔːpʃ(ə)n/","meaning":"n.吸收;并入;同化;专注","seq":8,"isStar":false},{"id":1782,"unit":6,"lesson":4,"word":"absurd","pronunciation":"/əbˈsɜːd/","meaning":"adj.可笑的,荒谬的","seq":9,"isStar":false,"memo":"ab-(一再地) + surd(音似“笑”)→可笑的，荒谬的","example":"That's an absurd idea. 那是一个荒谬的想法。"},{"id":1783,"unit":6,"lesson":4,"word":"absurdity","pronunciation":"/əbˈsɜːdəti/","meaning":"n.荒唐","seq":10,"isStar":false},{"id":1784,"unit":6,"lesson":4,"word":"constant","pronunciation":"/ˈkɒnstənt/","meaning":"adj.持续不断的;始终如一的 n.常量","seq":11,"isStar":false,"memo":"联想 con-(共同)+stant(联想 stand)→交警每天都站在马路上指挥交通,从不间断→持续不断的","example":"This entrance is in constant use. 此入口经常使用。"},{"id":1785,"unit":6,"lesson":4,"word":"instant","pronunciation":"/ˈɪnstənt/","meaning":"adj.立即的,立刻的;即食的 n.瞬间","seq":12,"isStar":false,"memo":"构词 in-(在…上)+st(站立，同 stand)+-ant(形容词后缀)→就站在眼前那一瞬→立即的；瞬间；即食的","example":"For an instant, he was tempted to flee. 有一瞬间,他很想逃走。"},{"id":1786,"unit":6,"lesson":4,"word":"instantaneous","pronunciation":"/ˌɪnstənˈteɪniəs/","meaning":"adj.立刻的,立即的","seq":13,"isStar":false,"memo":"构词 instant(瞬间)+-aneous(形容词后缀)→立刻的,立即的","example":"TV has conditioned us to expect instantaneous answers to difficult questions. 电视使我们习惯于期待难题的即时答案。"},{"id":1787,"unit":6,"lesson":4,"word":"immediate","pronunciation":"/ɪˈmiːdiət/","meaning":"adj.立即的,立刻的;目前的;迫切的","seq":14,"isStar":false,"memo":"构词 im-(否定前缀)+medi(中间的)+-ate(形容词后缀)→没有中间的(环节),直接的→立即的,立刻的","example":"Most of us find it hard to focus on our immediate tasks because of Internet distractions. 由于网络的干扰,我们大多数人发现很难专注于眼前的任务。"},{"id":1788,"unit":6,"lesson":4,"word":"immediately","pronunciation":"/ɪˈmiːdiətli/","meaning":"adv.立即;马上","seq":15,"isStar":false},{"id":1789,"unit":6,"lesson":4,"word":"mediate","pronunciation":"/ˈmiːdieɪt/","meaning":"v.调停;调解;找到方法","seq":16,"isStar":false,"memo":"对照 媒介(media)就是在两个事物之间进行调解(mediate)的。","example":"He was the one who mediated in the dispute. 他是调解这场纷争的人。"},{"id":1790,"unit":6,"lesson":4,"word":"mediator","pronunciation":"/ˈmiːdieɪtə(r)/","meaning":"n.调停者","seq":17,"isStar":false},{"id":1791,"unit":6,"lesson":4,"word":"mediation","pronunciation":"/ˌmiːdiˈeɪʃn/","meaning":"n.调停;调解","seq":18,"isStar":false},{"id":1792,"unit":6,"lesson":4,"word":"medium","pronunciation":"/ˈmiːdiəm/","meaning":"adj.中等的 n.媒介;手段,方法","seq":19,"isStar":false,"memo":"联想 mediu(音似“媒体”)+m→媒体是信息的传播“媒介”。","example":"The state subsidises small and medium enterprises. 国家对中小企业进行补贴。"},{"id":1793,"unit":6,"lesson":4,"word":"amid","pronunciation":"/əˈmɪd/","meaning":"prep.在……过程中;在……中","seq":20,"isStar":false,"memo":"联想 a(一)+mid(中间)→一个人在中间→在……中","example":"She kept smiling amid all the confusion. 在一片混乱中她一直微笑着。"},{"id":1794,"unit":6,"lesson":4,"word":"midst","pronunciation":"/mɪdst/","meaning":"n.中部;中间","seq":21,"isStar":false,"memo":"[联想] mid(中间) + st(联想 sit)→在“中间”坐。","example":"He finished his speech amid tremendous applause. 他在雷鸣般的掌声中结束了演讲。 We are in the midst of a fundamental change in the field of medicine. 我们正处于医学领域的根本变革之中。"},{"id":1795,"unit":6,"lesson":4,"word":"medieval","pronunciation":"/ˌmediˈiːv(ə)l/","meaning":"adj.中世纪的;古老的","seq":22,"isStar":false,"memo":"构词 medi(中间，同 medium)+ev(时代)+-al(形容词后缀)→处在中间时代的→中世纪的；古老的","example":"He began studying medieval history. 他开始学习中世纪史。"},{"id":1796,"unit":6,"lesson":4,"word":"middle-class","pronunciation":"/ˌmɪdl ˈklɑːs/","meaning":"adj.中产阶级的 n.中产阶级","seq":23,"isStar":false,"memo":"构词 middle(中间)+class(阶层)→处在社会中间阶层的人→中产阶级(的)","example":"Middle-class people will be hit hardest by these tax rises.中产阶级将受这些增税影响最大。"},{"id":1797,"unit":6,"lesson":4,"word":"midday","pronunciation":"/ˌmɪdˈdeɪ/","meaning":"n.中午;正午","seq":24,"isStar":false,"memo":"[构词] mid(中间) + day(一天)→一天的中间(时刻)→中午;正午","example":"The train arrives at midday. 列车正午到达。"},{"id":1798,"unit":6,"lesson":4,"word":"midwife","pronunciation":"/ˈmɪdwaɪf/","meaning":"n.助产士;接生员;产婆","seq":25,"isStar":false,"memo":"构词 mid(中间)+wife(妇女)：守在产妇身边接地生下来的那位妇女→助产士，接生员，产婆","example":"The midwife helped the woman give birth.助产士帮助这名妇女分娩。"},{"id":1799,"unit":6,"lesson":4,"word":"intermediate","pronunciation":"/ˌɪntəˈmiːdiət/","meaning":"adj.中间的;中等的 n.中级学生","seq":26,"isStar":false,"memo":"[联想] inter-(在……中间) + media(媒体) + te(联想“特”)→位于中间的媒体特色不鲜明,属于“中等的”媒体。","example":"Fewer than half of Americans say they cook at an intermediate level. 不到一半的美国人说他们的烹饪水平是中等的。"},{"id":1800,"unit":6,"lesson":4,"word":"intermediary","pronunciation":"/ˌɪntəˈmiːdiəri/","meaning":"n.中间人;调解人","seq":27,"isStar":false,"memo":"构词 inter-(在…之间)+medi(中间)+-ary(表人)→站在中间传话的人→中间人，调解人","example":"So far, all talks have been conducted through an intermediary.到目前为止，所有会谈都是通过中间人进行的。"},{"id":1801,"unit":6,"lesson":4,"word":"overtime","pronunciation":"/ˈəʊvətaɪm/","meaning":"n.加班(时间);加班费;加时","seq":28,"isStar":false,"memo":"构词 over(超过)+time(时间)→超过工作时间→加班(时间);加班费;加时","example":"He does mind all the overtime. 他确实介意所有加班。"},{"id":1802,"unit":6,"lesson":4,"word":"overtake","pronunciation":"/ˌəʊvəˈteɪk/","meaning":"v.超过,赶上;突然发生","seq":29,"isStar":false,"memo":"构词 over(在上面,超过)+take(拿)→“超过”对方才能从上方拿取。","example":"Some Asian countries have overtaken America in basic sciences. 一些亚洲国家在基础科学方面已经超过了美国。"},{"id":1803,"unit":6,"lesson":4,"word":"overthrow","pronunciation":"/ˌəʊvəˈθrəʊ/","meaning":"v.推翻,打倒 n.推翻,打倒","seq":30,"isStar":false,"memo":"构词 over(在上面,翻转)+throw(扔)→推翻,打倒","example":"The rebellious officers broadcast the news of the overthrow of the monarchy. 反叛的军官们播报了推翻君主制的消息。"},{"id":1804,"unit":6,"lesson":4,"word":"overflow","pronunciation":"/ˌəʊvəˈfləʊ/","meaning":"v.漫出,溢出;挤满了人","seq":31,"isStar":false,"memo":"构词 over(过度)+flow(流)→漫出,溢出","example":"The streets were overflowing with the crowds. 街上到处挤满了人。"},{"id":1805,"unit":6,"lesson":4,"word":"overall","pronunciation":"/ˌəʊvərˈɔːl/","meaning":"adj.全面的,综合的 adv.全部","seq":32,"isStar":false,"memo":"构词 over(覆盖)+all(全部)→全部覆盖→全面的,综合的","example":"Overall I was disappointed. 总的来说,我感到失望。"},{"id":1806,"unit":6,"lesson":4,"word":"oversee","pronunciation":"/ˌəʊvəˈsiː/","meaning":"v.监督;监视","seq":33,"isStar":false,"memo":"构词 over（在上面）+ see（看）→ 从上面看 → 监督；监视","example":"He personally oversaw the design of all the rooms.他亲自监督了所有房间的设计。"},{"id":1807,"unit":6,"lesson":4,"word":"overhaul","pronunciation":"/ˌəʊvəˈhɔːl/","meaning":"n.检修;改造 v.彻底检修;超过","seq":34,"isStar":false,"memo":"构词 over(在上面)+haul(拉)→从上面拉出来,从根本上改变→检修;改造","example":"The plan was completely overhauled. 这一计划已全面修订。"},{"id":1808,"unit":6,"lesson":4,"word":"overcome","pronunciation":"/ˌəʊvəˈkʌm/","meaning":"v.克服;解决;战胜","seq":35,"isStar":false,"memo":"构词 over(越过,超过)+come(来)→越过(困难)而来→克服;战胜","example":"He finally managed to overcome his fear of flying. 他终于克服了对飞行的恐惧。"},{"id":1809,"unit":6,"lesson":4,"word":"overhear","pronunciation":"/ˌəʊvəˈhɪə(r)/","meaning":"v.偶然听到;无意中听到","seq":36,"isStar":false,"memo":"构词 over(在上面,超过)+hear(听见)→超出预期范围听见→无意中听到","example":"The patient overheard the news that he was seriously ill. 病人无意中听到了他病情严重的消息。"},{"id":1810,"unit":6,"lesson":4,"word":"overseas","pronunciation":"/ˌəʊvəˈsiːz/","meaning":"adj.外国的;海外的 adv.在国外","seq":37,"isStar":false,"memo":"构词 over(越过)+seas(海)→越过海洋→外国的;海外的","example":"They suspend import of necessities from overseas. 他们暂停从海外进口必需品。"},{"id":1811,"unit":6,"lesson":4,"word":"override","pronunciation":"/ˌəʊvəˈraɪd/","meaning":"v.否决,推翻;比……更重要;凌驾于","seq":38,"isStar":false,"memo":"构词 over（在上面，翻转）+ ride（骑）→ 翻转过来骑在上面 → 凌驾于","example":"Considerations of safety override all other concerns.安全考虑优先于其他一切关注。"},{"id":1812,"unit":6,"lesson":4,"word":"overdue","pronunciation":"/ˌəʊvəˈdjuː/","meaning":"adj.延误的;(到期)未付的,未做的","seq":39,"isStar":false,"memo":"构词 over(超过)+due(到期的)→超过了到期时间还没做→延误的，过期的，未付的","example":"That's an important development, one that's long overdue.这是一个重要的进展，早就该有了。"},{"id":1813,"unit":6,"lesson":4,"word":"comprehension","pronunciation":"/ˌkɒmprɪˈhenʃ(ə)n/","meaning":"n.理解(力);理解测试","seq":40,"isStar":false,"example":"This was utterly beyond her comprehension. 这完全超出了她的理解能力。"},{"id":1814,"unit":6,"lesson":4,"word":"comprehend","pronunciation":"/ˌkɒmprɪˈhend/","meaning":"v.理解,领悟","seq":41,"isStar":false,"memo":"【构词】com-（一起）+ prehend（抓，拉丁词根）→ 把信息‘一把抓’进脑子 → 理解！就像抢答时手速快才抓得住知识点～","example":"Students must comprehend complex scientific concepts before the exam. 考试前学生必须理解复杂的科学概念。"},{"id":1815,"unit":6,"lesson":4,"word":"comprehensive","pronunciation":"/ˌkɒmprɪˈhensɪv/","meaning":"adj.综合的,全面的;详尽的","seq":42,"isStar":false,"memo":"对照 阅读理解(comprehension)考查学生的英语综合(comprehensive)运用能力。","example":"The idea was to create a comprehensive road map of the Web. 这个想法是为万维网做一个全面详细的指南。"},{"id":1816,"unit":6,"lesson":4,"word":"overnight","pronunciation":"/ˌəʊvəˈnaɪt/","meaning":"adv.在夜间;一夜之间","seq":43,"isStar":false,"memo":"构词 over(跨越)+night(夜晚)→跨过一夜之间→在夜间；一夜之间，突然","example":"The play was an overnight success. 这部剧一夜成名。"},{"id":1817,"unit":6,"lesson":4,"word":"overturn","pronunciation":"/ˌəʊvəˈtɜːn/","meaning":"v.倾倒,倾覆;推翻","seq":44,"isStar":false,"memo":"构词 over(翻过来)+turn(转)→整个翻转过来→倾倒，倾覆；推翻","example":"The car skidded and overturned.汽车打滑翻倒了。"},{"id":1818,"unit":6,"lesson":4,"word":"turnover","pronunciation":"/ˈtɜːnəʊvə(r)/","meaning":"n.营业额,成交量;人事变更率","seq":45,"isStar":false,"memo":"联想 turn(转变) + over(超过) → 他转变商业模式，超过了同行，“营业额”大涨。","example":"The city has a rapid population turnover. 这个城市的人口流动很快。"},{"id":1819,"unit":6,"lesson":4,"word":"plunge","pronunciation":"/plʌndʒ/","meaning":"v.使突然前冲(或下落),震荡;骤降","seq":46,"isStar":false,"memo":"谐音 单词发音类似“扑浪激”→他把球扑通一声“投入”水中，激起浪花。","example":"Her car plunged off the cliff. 她的车突然冲下了悬崖。"},{"id":1820,"unit":6,"lesson":4,"word":"slump","pronunciation":"/slʌmp/","meaning":"n.骤降,猛跌;萧条 v.倒下,骤降","seq":47,"isStar":false,"memo":"联想 与 jump 押韵：不是往上跳而是往下“跌”→骤降，猛跌；萧条","example":"The US housing slump has gone global.美国房地产衰退已波及全球。"},{"id":1821,"unit":6,"lesson":4,"word":"lump","pronunciation":"/lʌmp/","meaning":"n.块;肿块;隆起 v.把……归并在一起","seq":48,"isStar":false,"memo":"联想 lu(音似“拉”) + mp(联想“妹扑”)→他拉着妹妹扑过去，结果头上撞了个“肿块”。","example":"I've got a lump on my shoulder. 我的肩膀上有个肿块。"},{"id":1822,"unit":6,"lesson":4,"word":"bump","pronunciation":"/bʌmp/","meaning":"n.碰撞(声);肿块 v.碰撞;颠簸而行","seq":49,"isStar":false,"memo":"谐音 单词发音类似“梆”→他倒在桌子上，发出“梆”的“碰撞声”，头上出现了一个“肿块”。","example":"They bumped into each other over a swimming pool. 他们在游泳池上空撞到了一起。"},{"id":1823,"unit":6,"lesson":4,"word":"dump","pronunciation":"/dʌmp/","meaning":"n.垃圾场 v.丢弃,倾倒","seq":50,"isStar":false,"memo":"对照 车辆在垃圾场(dump)旁相撞(bump)。","example":"Something which goes into the dumps would be made into something useful. 进入垃圾场的一些东西会被做成有用的东西。"},{"id":1824,"unit":6,"lesson":4,"word":"slash","pronunciation":"/slæʃ/","meaning":"v.砍,劈;大幅削减 n.砍,劈;伤口","seq":51,"isStar":false,"memo":"联想 与 slice(切片)形近：一刀劈下去→砍，劈；引申为大幅削减","example":"The workforce has been slashed by half.劳动力被削减了一半。"},{"id":1825,"unit":6,"lesson":4,"word":"assign","pronunciation":"/əˈsaɪn/","meaning":"v.委派,指派;分配","seq":52,"isStar":false,"memo":"联想 as-(一再地)+sign(签字)→老板一再签字,“委派”人员去执行任务。","example":"The company assigned her to an agricultural project. 公司把她委派到一个农业项目。"},{"id":1826,"unit":6,"lesson":4,"word":"assignment","pronunciation":"/əˈsaɪnmənt/","meaning":"n.任务;分配","seq":53,"isStar":false},{"id":1827,"unit":6,"lesson":4,"word":"signify","pronunciation":"/ˈsɪɡnɪfaɪ/","meaning":"v.代表;表示;象征;要紧","seq":54,"isStar":false,"memo":"构词 sign(标记)+-ify(动词后缀)→使……标记化→代表;表示;象征","example":"Diplomas and certificates still weigh heavily in terms of signifying one's ability. 文凭和证书在表明一个人的能力方面仍然很重要。"},{"id":1828,"unit":6,"lesson":4,"word":"significant","pronunciation":"/sɪɡˈnɪfɪkənt/","meaning":"adj.重大的,重要的;显著的","seq":55,"isStar":false,"memo":"联想 sig(n)(签字)+nifi(音似“你非”)+c+-ant(形容词后缀)→这是件“重要的”的事,你非签字不可。","example":"There is a significant increase of opportunities. 机会显著增加。"},{"id":1829,"unit":6,"lesson":4,"word":"significance","pronunciation":"/sɪɡˈnɪfɪkəns/","meaning":"n.意义,重要性","seq":56,"isStar":false},{"id":1830,"unit":6,"lesson":4,"word":"resign","pronunciation":"/rɪˈzaɪn/","meaning":"v.辞职,辞去","seq":57,"isStar":false,"memo":"联想 re-(=off,离去)+sign(签字)→签字后离去→辞职,辞去","example":"She has made up her mind to resign. 她已下定决心辞职。"},{"id":1831,"unit":6,"lesson":4,"word":"resignation","pronunciation":"/ˌrezɪɡˈneɪʃ(ə)n/","meaning":"n.辞职;辞职信","seq":58,"isStar":false},{"id":1832,"unit":6,"lesson":4,"word":"appoint","pronunciation":"/əˈpɔɪnt/","meaning":"v.任命,委任,安排;确定","seq":59,"isStar":false,"memo":"联想 ap-(一再地)+point(指向)→老板一再指向他,“任命”他做某事,是在给他“安排”工作。","example":"They appointed a new manager to coordinate the work of the team. 为协调这个团队的工作,他们任用了一位新经理。"},{"id":1833,"unit":6,"lesson":4,"word":"appointment","pronunciation":"/əˈpɔɪntmənt/","meaning":"n.约会;预约;约定","seq":60,"isStar":false},{"id":1834,"unit":6,"lesson":4,"word":"designate","pronunciation":"/ˈdezɪɡneɪt/","meaning":"v.指派;指定;标明","seq":61,"isStar":false,"memo":"构词 nomin(= name) + -ate(动词后缀)→使名字出现→提名","example":"The school has been designated a specialist science academy. 这所学校被指定为专门的科学院。"},{"id":1835,"unit":6,"lesson":4,"word":"designation","pronunciation":"/ˌdezɪɡˈneɪʃn/","meaning":"n.选定;委任;名称","seq":62,"isStar":false},{"id":1836,"unit":6,"lesson":4,"word":"nominate","pronunciation":"/ˈnɒmɪneɪt/","meaning":"v.提名;任命,指派","seq":63,"isStar":false,"memo":"构词 nomin(名字，拉丁语 nomen)+-ate(动词后缀)→把名字报上去→提名；任命，指派","example":"He is eager to be nominated as the new editor. 他渴望被提名为新编辑。"},{"id":1837,"unit":6,"lesson":4,"word":"nominee","pronunciation":"/ˌnɒmɪˈniː/","meaning":"n.被任命者","seq":64,"isStar":false},{"id":1838,"unit":6,"lesson":4,"word":"nomination","pronunciation":"/ˌnɒmɪˈneɪʃn/","meaning":"n.提名;任命,指派","seq":65,"isStar":false},{"id":1839,"unit":6,"lesson":4,"word":"nominal","pronunciation":"/ˈnɒmɪn(ə)l/","meaning":"adj.名义上的;有名无实的;很小的","seq":66,"isStar":false,"memo":"构词 nomin(名字)+-al(形容词后缀)→只在名字上存在→名义上的，有名无实的；很小的","example":"He remained in nominal control of the business for another ten years. 他名义上又掌管了这家公司十年。"},{"id":1840,"unit":6,"lesson":4,"word":"culminate","pronunciation":"/ˈkʌlmɪneɪt/","meaning":"v.告终,结束","seq":67,"isStar":false,"memo":"联想 cul(音似“卡了”) + minate(联想 nominate)→他被卡在了提名环节,意味着竞选之路“结束”了。","example":"He is desperate because all his efforts culminated in failure. 他很绝望,因为他所有的努力都以失败告终。"},{"id":1841,"unit":6,"lesson":4,"word":"namely","pronunciation":"/ˈneɪmli/","meaning":"adv.即,也就是","seq":68,"isStar":false,"memo":"构词 name(名字)+-ly(副词后缀)→把名字直接点出来→即，也就是","example":"In the past, electric vehicles have their problems, namely, a limited driving range. 在过去,电动汽车也有它们存在的问题,即行驶里程有限。"},{"id":1842,"unit":6,"lesson":4,"word":"nickname","pronunciation":"/ˈnɪkneɪm/","meaning":"n.绰号,外号 v.给……起绰号","seq":69,"isStar":false,"memo":"构词 nick(古语“别名”)+name(名字)→另给的名字→绰号，外号","example":"She was nicknamed “The Ice Queen”.她的绰号叫「冰女王」。"},{"id":1843,"unit":6,"lesson":4,"word":"despatch/dispatch","pronunciation":"/dɪˈspætʃ/","meaning":"n.信件;报道;派遣;发送 v.派遣","seq":70,"isStar":false,"memo":"构词 des-/dis-(分开)+patch(古法语“脚镣”，引申为脱去羁绊去办事)→把人或物打发出去→派遣；发送；信件，报道","example":"We dispatched the goods this morning. 我们今天上午把货发出去了。"},{"id":1844,"unit":6,"lesson":4,"word":"patch","pronunciation":"/pætʃ/","meaning":"n.斑;小块;补丁","seq":71,"isStar":false,"memo":"联想 与 despatch 同根：一小块布“补”上去→补丁；斑，小块","example":"He tried to hide his bald patch by sweeping his hair over to one side.他把头发梳到一边，想遮住秃顶的那一块。"},{"id":1845,"unit":6,"lesson":4,"word":"abuse","pronunciation":"/əˈbjuːs/","meaning":"n.滥用;虐待 v.滥用;虐待","seq":72,"isStar":false,"memo":"构词 ab-(否定前缀) + use(使用)→不好好使用→滥用;虐待","example":"Abuse of medicines should be resolutely resisted. 滥用药物应当坚决抵制。"},{"id":1846,"unit":6,"lesson":4,"word":"abusive","pronunciation":"/əˈbjuːsɪv/","meaning":"adj.辱骂的;虐待的","seq":73,"isStar":false},{"id":1847,"unit":6,"lesson":4,"word":"abolish","pronunciation":"/əˈbɒlɪʃ/","meaning":"v.废除,废止","seq":74,"isStar":false,"memo":"构词 ab-(离开)+ol(生长，同 adult 成年)+-ish(动词后缀)→让制度不再生长下去→废除，废止","example":"The government was planning to abolish subsidies to farmers. 政府正在计划取消对农民的补贴。"},{"id":1848,"unit":6,"lesson":4,"word":"abolition","pronunciation":"/ˌæbəˈlɪʃ(ə)n/","meaning":"n.废除,废止","seq":75,"isStar":false},{"id":1849,"unit":6,"lesson":4,"word":"abnormal","pronunciation":"/æbˈnɔːm(ə)l/","meaning":"adj.反常的;变态的;畸形的","seq":76,"isStar":false,"memo":"ab-(否定前缀) + normal(正常的)→反常的","example":"Abnormal human behaviour may be caused by eating some substances. 人类异常行为可能是由摄入的某些物质造成的。"},{"id":1850,"unit":6,"lesson":4,"word":"abort","pronunciation":"/əˈbɔːt/","meaning":"v.(使)流产;(使)夭折;中止","seq":77,"isStar":false,"memo":"（构词）ab-(否定前缀) + (b)ort (= born, 出生) → 未出生 → 流产；夭折","example":"The virus can cause pregnant animals to abort.这种病毒可导致怀孕的动物流产。"},{"id":1851,"unit":6,"lesson":4,"word":"abortion","pronunciation":"/əˈbɔːʃ(ə)n/","meaning":"n.堕胎,人工流产","seq":78,"isStar":false},{"id":1852,"unit":6,"lesson":4,"word":"inborn","pronunciation":"/ˌɪnˈbɔːn/","meaning":"adj.天生的,先天的","seq":79,"isStar":false,"memo":"构词 in-(在内)+born(出生)→生下来就带着的→天生的，先天的","example":"Some people have an inborn tendency to put on weight.有些人天生容易发胖。"},{"id":1853,"unit":6,"lesson":4,"word":"appreciate","pronunciation":"/əˈpriːʃieɪt/","meaning":"v.欣赏;理解;感激","seq":80,"isStar":false,"memo":"ap-(一再地) + preci(联想 precious) + -ate(动词后缀)→一再说一个人珍贵,就是表达“欣赏”之情。","example":"He appreciates the sacrifice his friends have made for him. 他感激朋友们为他所做的牺牲。"},{"id":1854,"unit":6,"lesson":4,"word":"appreciation","pronunciation":"/əˌpriːʃiˈeɪʃn/","meaning":"n.欣赏;理解;感激","seq":81,"isStar":false},{"id":1855,"unit":6,"lesson":4,"word":"depreciate","pronunciation":"/dɪˈpriːʃieɪt/","meaning":"v.贬值;贬低;轻视","seq":82,"isStar":false,"memo":"（构词）de-(减少) + preci(价值) + -ate(动词后缀) → 使价值减少 → 贬值；贬低","example":"It will depreciate human's role in music composition.它将贬低人类在音乐创作中的作用。"},{"id":1856,"unit":6,"lesson":4,"word":"depreciation","pronunciation":"/dɪˌpriːʃiˈeɪʃn/","meaning":"n.贬值;贬低;轻视","seq":83,"isStar":false},{"id":1857,"unit":6,"lesson":4,"word":"approach","pronunciation":"/əˈprəʊtʃ/","meaning":"n.方式,方法;接近 v.接近;对付","seq":84,"isStar":false,"memo":"单词发音类似“饿扑肉吃”→老虎饿了想扑倒猎物吃肉,首先得“接近”猎物。","example":"We need a new approach to the problem. 我们需要用新方法处理这个问题。"},{"id":1858,"unit":6,"lesson":4,"word":"attach","pronunciation":"/əˈtætʃ/","meaning":"v.系;贴;绑;固定;附","seq":85,"isStar":false,"memo":"联想 at-(一再地)+tach(音似touch)→一再地触摸,是为了把它“系”紧。","example":"I attached a copy of my notes for your information. 我附上一份笔记供你参考。"},{"id":1859,"unit":6,"lesson":4,"word":"attachment","pronunciation":"/əˈtætʃmənt/","meaning":"n.附件;附属物;连接;依恋","seq":86,"isStar":false},{"id":1860,"unit":6,"lesson":4,"word":"detach","pronunciation":"/dɪˈtætʃ/","meaning":"v.拆卸;分开,脱离","seq":87,"isStar":false,"memo":"联想 de-(否定前缀)+tach(音似touch)→不触摸→分开","example":"The skis should detach from the boot if you fall. 要是你跌倒了,滑雪板就会脱离靴子。"},{"id":1861,"unit":6,"lesson":4,"word":"detached","pronunciation":"/dɪˈtætʃt/","meaning":"adj.单独的;冷漠的","seq":88,"isStar":false},{"id":1862,"unit":6,"lesson":4,"word":"detachment","pronunciation":"/dɪˈtætʃmənt/","meaning":"n.分离;超然;冷漠","seq":89,"isStar":false},{"id":1863,"unit":6,"lesson":4,"word":"tangible","pronunciation":"/ˈtændʒəb(ə)l/","meaning":"adj.有形的;可触摸的","seq":90,"isStar":false,"memo":"构词 tang(触摸，同 tactile 触觉的)+-ible(可…的)→能摸得到的→有形的，可触摸的","example":"Money as a tangible commodity has largely been replaced by credit. 货币作为一种有形的商品在很大程度上已被信用卡取代。"},{"id":1864,"unit":6,"lesson":4,"word":"intangible","pronunciation":"/ɪnˈtændʒəb(ə)l/","meaning":"adj.无形的","seq":91,"isStar":false,"memo":"构词 in-(否定前缀)+tangible(有形的)→无形的","example":"The benefits are intangible. 好处是难以计算的。"},{"id":1865,"unit":6,"lesson":4,"word":"stick","pronunciation":"/stɪk/","meaning":"v.粘贴;粘住;卡住;将……刺入","seq":92,"isStar":false,"memo":"谐音 单词发音类似“死提个”→他一直提着个棍子,就像被棍子“粘住”了一样。","example":"I stuck the photos into an album. 我把照片贴到相册上。"},{"id":1866,"unit":6,"lesson":4,"word":"sticky","pronunciation":"/ˈstɪki/","meaning":"adj.黏(性)的","seq":93,"isStar":false,"memo":"构词 stick(粘)+-y(形容词后缀)→会粘手的→黏(性)的","example":"The floor was sticky with juice. 地板上黏着果汁。"},{"id":1867,"unit":6,"lesson":4,"word":"strike","pronunciation":"/straɪk/","meaning":"v.击,撞;罢工;突然想到 n.罢工","seq":94,"isStar":false,"memo":"联想 st(联想street)+rike(联想rock)→摇滚乐队的鼓手在街上“击”鼓。","example":"A strike has shut the factory. 罢工使工厂停业。"},{"id":1868,"unit":6,"lesson":4,"word":"adhere","pronunciation":"/ədˈhɪə(r)/","meaning":"v.黏附;附着;坚持;遵守","seq":95,"isStar":false,"memo":"联想 ad-(一再地)+here(这里)→这里一再地有油渍黏附→黏附;坚持","example":"The bank adheres to all rules regarding the opening and closing of accounts. 该银行遵守所有关于开设和关闭账户的规定。"},{"id":1869,"unit":6,"lesson":4,"word":"adherence","pronunciation":"/ədˈhɪərəns/","meaning":"n.坚持;遵守","seq":96,"isStar":false},{"id":1870,"unit":6,"lesson":4,"word":"cling","pronunciation":"/klɪŋ/","meaning":"v.抓紧,紧抱;粘住,附着;依恋","seq":97,"isStar":false,"memo":"谐音 单词发音类似“可怜”→那个可怜的孩子“紧抱”着母亲,一刻都不肯放开。","example":"Other birds unknowingly carry seeds that cling to them for the ride. 其他鸟类在不知不觉中携带了附着在它们身上的种子,让种子搭便车。"},{"id":1871,"unit":6,"lesson":4,"word":"abide","pronunciation":"/əˈbaɪd/","meaning":"v.遵守;容忍","seq":98,"isStar":false,"memo":"联想 ab-(一再地)+i(我)+de(联想“的”)→我一再强调我会遵纪守法的→遵守","example":"We have got to abide by the rules. 我们必须遵守规则。"},{"id":1872,"unit":6,"lesson":4,"word":"comply","pronunciation":"/kəmˈplaɪ/","meaning":"v.遵守;服从,顺从","seq":99,"isStar":false,"memo":"联想 com-(都)+p(联想“趴”)+ly(音似lie,躺)→他们都趴在国王的王座下或躺在他的脚下,以示“服从”他。","example":"People who refuse to comply with the law will be punished. 拒绝遵守法律的人将受到惩罚。"},{"id":1873,"unit":6,"lesson":4,"word":"compliance","pronunciation":"/kəmˈplaɪəns/","meaning":"n.服从;遵从","seq":100,"isStar":false,"memo":"构词 com-(一起)+pli(填满，同 complete 完成)+-ance(名词后缀)→把要求逐条填满做到→服从，遵从","example":"Compliance with the safety rules is required. 必须遵守安全规定。"},{"id":1874,"unit":6,"lesson":4,"word":"obedient","pronunciation":"/əˈbiːdiənt/","meaning":"adj.顺从的,服从的","seq":101,"isStar":false,"memo":"谐音：单词发音类似“我必等他”→我服从安排，必须等他→服从的","example":"He was always obedient to his father’s wishes. 他一向顺从父亲的意愿。"},{"id":1875,"unit":6,"lesson":4,"word":"obedience","pronunciation":"/əˈbiːdiəns/","meaning":"n.顺从,服从","seq":102,"isStar":false},{"id":1876,"unit":6,"lesson":4,"word":"acupuncture","pronunciation":"/ˈækjupʌŋktʃə(r)/","meaning":"n.针刺疗法,针灸","seq":103,"isStar":false,"memo":"联想：ac-(一再) + u(字母音似“有”) + puncture(小孔)→我一再发现他身上有小孔，推测他刚做完“针灸”。","example":"Acupuncture techniques have been perfected. 针灸技术已经完善。"},{"id":1877,"unit":6,"lesson":4,"word":"accord","pronunciation":"/əˈkɔːd/","meaning":"n.符合;协议;正式协议 v.给予","seq":104,"isStar":false,"memo":"对照：according to 根据，按照→accord n. & v.","example":"The accord underlined Italy’s global reputation. 该协议突显了意大利在全球的声誉。"},{"id":1878,"unit":6,"lesson":4,"word":"accordance","pronunciation":"/əˈkɔːd(ə)ns/","meaning":"n.依照,依据","seq":105,"isStar":false},{"id":1879,"unit":6,"lesson":4,"word":"accordingly","pronunciation":"/əˈkɔːdɪŋli/","meaning":"adv.相应地;因此,从而","seq":106,"isStar":false,"memo":"构词：accord(相符) + -ing(动名词后缀) + -ly(副词后缀)→相应地","example":"Accordingly, they should not be put into jobs that are inconsistent with their needs. 因此，他们不应该从事与他们的需求不一致的工作。"},{"id":1880,"unit":6,"lesson":4,"word":"discord","pronunciation":"/ˈdɪskɔːd/","meaning":"n.不一致;不和,纷争","seq":107,"isStar":false,"memo":"（联想）dis-(否定前缀) + cord(联想 accord, 一致) → 不一致","example":"A note of discord surfaced during the proceedings.会议进行中出现了一丝不和。"},{"id":1881,"unit":6,"lesson":4,"word":"record","pronunciation":"/ˈrekɔːd; rɪˈkɔːd/","meaning":"n.记录;记载 v.记录;录制","seq":108,"isStar":false,"memo":"构词 re-(回)+cord(心，同 courage 勇气)→把事再放回心里记牢→记录，记载；录制","example":"You should keep a record of your expenses. 你应该记下你的各项开支。"},{"id":1882,"unit":6,"lesson":4,"word":"recording","pronunciation":"/rɪˈkɔːdɪŋ/","meaning":"n.录制,音像制品","seq":109,"isStar":false},{"id":1883,"unit":6,"lesson":4,"word":"recorder","pronunciation":"/rɪˈkɔːdə(r)/","meaning":"n.记录员;录音机","seq":110,"isStar":false},{"id":1884,"unit":6,"lesson":4,"word":"document","pronunciation":"/ˈdɒkjumənt/","meaning":"n.文件,公文;文档 v.记录,记载","seq":111,"isStar":false,"memo":"联想：do(音似“捣”) + cu(联想“促”) + -ment(名词后缀)→他在房间里捣鼓一上午了，被领导催促整理“文件”。","example":"I didn’t take those important documents with me. 我没把那些重要文件带走。"},{"id":1885,"unit":6,"lesson":4,"word":"documentary","pronunciation":"/ˌdɒkjuˈment(ə)ri/","meaning":"n.纪录片 adj.纪实的;文件的","seq":112,"isStar":false},{"id":1886,"unit":7,"lesson":1,"word":"accommodate","pronunciation":"/əˈkɒmədeɪt/","meaning":"v.为(某人)提供住宿;容纳;适应","seq":1,"isStar":false,"memo":"联想: ac-(一再地)+commo(联想come)+date(约会)→他一再地来跟我约会,帮我“适应”了周围环境。","example":"The new apartments can accommodate 500 students. 新公寓可容纳500名学生。"},{"id":1887,"unit":7,"lesson":1,"word":"accommodation","pronunciation":"/əˌkɒməˈdeɪʃ(ə)n/","meaning":"n.住处;办公处;住宿;和解","seq":2,"isStar":false},{"id":1888,"unit":7,"lesson":1,"word":"adapt","pronunciation":"/əˈdæpt/","meaning":"v.使适应,使适合;改造;改编","seq":3,"isStar":false,"memo":"联想: ad(联想“阿弟”)+a(一)+pt(联想“普通”)→阿弟适应了做一个普通人→使适应","example":"It takes them longer to adapt to the high beach temperature. 它们需要更长的时间来适应较高的海滩温度。"},{"id":1889,"unit":7,"lesson":1,"word":"adaptation","pronunciation":"/ˌædæpˈteɪʃn/","meaning":"n.适应;改编本","seq":4,"isStar":false},{"id":1890,"unit":7,"lesson":1,"word":"adaptive","pronunciation":"/əˈdæptɪv/","meaning":"adj.适应的;有适应能力的","seq":5,"isStar":false},{"id":1891,"unit":7,"lesson":1,"word":"adopt","pronunciation":"/əˈdɒpt/","meaning":"v.收养;采用;采取,采纳","seq":6,"isStar":false,"memo":"联想: ad(联想“阿弟”)+o(形似洞)+pt(联想“葡萄”)→阿弟发现一个小孩在山洞外吃葡萄,便“采纳”同村人的意见“收养”了他。","example":"Karen was adopted by the couple. 凯伦被这对夫妻收养了。"},{"id":1892,"unit":7,"lesson":1,"word":"adoption","pronunciation":"/əˈdɒpʃn/","meaning":"n.收养;采用;推选","seq":7,"isStar":false},{"id":1893,"unit":7,"lesson":1,"word":"accustom","pronunciation":"/əˈkʌstəm/","meaning":"v.使习惯;使适应","seq":8,"isStar":false,"memo":"联想: ac-(一再地)+custom(风俗)→一再地在一个风俗里面→使习惯;使适应","example":"You must accustom yourself to feeling more at ease when you are with strangers. 你必须使自己习惯和陌生人在一起时更加自在。"},{"id":1894,"unit":7,"lesson":1,"word":"accustomed","pronunciation":"/əˈkʌstəmd/","meaning":"adj.惯常的;习惯的","seq":9,"isStar":false},{"id":1895,"unit":7,"lesson":1,"word":"custom","pronunciation":"/ˈkʌstəm/","meaning":"n.习惯;习俗,风俗;光顾","seq":10,"isStar":false,"memo":"谐音: 单词发音类似“卡死他们”→他们被旧社会的“习俗”给卡(限制)住了。","example":"It’s a local custom to eat eggs during the Dragon Boat Festival. 端午节吃鸡蛋是当地的风俗。"},{"id":1896,"unit":7,"lesson":1,"word":"customary","pronunciation":"/ˈkʌstəməri/","meaning":"adj.习俗的;习惯的","seq":11,"isStar":false},{"id":1897,"unit":7,"lesson":1,"word":"customs","pronunciation":"/ˈkʌstəmz/","meaning":"n.海关;关税","seq":12,"isStar":false,"memo":"对照 设置海关(customs)是多数国家的习惯(custom)。","example":"You must pay customs on all imports of alcohol. 你必须为所有进口的酒缴纳关税。"},{"id":1898,"unit":7,"lesson":1,"word":"customer","pronunciation":"/ˈkʌstəmə(r)/","meaning":"n.顾客,客户,消费者","seq":13,"isStar":false,"memo":"构词 custom(光顾)+-er(表示人的后缀)→光顾的人→消费者","example":"The ability to guard customer data is the key to market value. 保护消费者信息的能力是市场价值的关键因素。"},{"id":1899,"unit":7,"lesson":1,"word":"client","pronunciation":"/ˈklaɪənt/","meaning":"n.顾客,客户","seq":14,"isStar":false,"memo":"谐音 单词发音类似“可来他”→“顾客”可来了,他终于开张了。","example":"I have scheduled an appointment with a client at dinner time. 我已经约了一位客户在晚餐时间见面。"},{"id":1900,"unit":7,"lesson":1,"word":"patron","pronunciation":"/ˈpeɪtrən/","meaning":"n.赞助人,赞助商;顾客","seq":15,"isStar":false,"memo":"（谐音）单词发音类似“赔偿”→若货物有损伤，需给“顾客”赔偿。","example":"He is a great patron of the arts.他是艺术界一位伟大的赞助人。"},{"id":1901,"unit":7,"lesson":1,"word":"patronise/-ize","pronunciation":"/ˈpætrənaɪz/","meaning":"v.赞助;光顾","seq":16,"isStar":false,"memo":"构词 patron(赞助人、老主顾)+-ise/-ize(使…化)→以主顾的身份对待→赞助；光顾","example":"She has patronised the local bookshop for years. 多年来她一直光顾这家本地书店。"},{"id":1902,"unit":7,"lesson":1,"word":"patronage","pronunciation":"/ˈpætrənɪdʒ/","meaning":"n.赞助;惠顾","seq":17,"isStar":false},{"id":1903,"unit":7,"lesson":1,"word":"sponsor","pronunciation":"/ˈspɒnsə(r)/","meaning":"n.赞助者,赞助商;倡议者 v.赞助","seq":18,"isStar":false,"memo":"联想 spon(音似“死帮”)+sor(音似sir)→作为先生的“赞助者”,他努力帮助先生。","example":"The race organizers are trying to attract sponsors. 这次比赛的组织者在想方设法吸引赞助商。"},{"id":1904,"unit":7,"lesson":1,"word":"sponsorship","pronunciation":"/ˈspɒnsəʃɪp/","meaning":"n.资助;倡议","seq":19,"isStar":false},{"id":1905,"unit":7,"lesson":1,"word":"spontaneous","pronunciation":"/spɒnˈteɪniəs/","meaning":"adj.自发的;自然的","seq":20,"isStar":false,"memo":"联想 sponta(音似“死帮他”)+neous→他努力帮助那位先生的行为是“自发的”。","example":"Creativity is spontaneous inspiration. 创造力是自发产生的灵感。"},{"id":1906,"unit":7,"lesson":1,"word":"spontaneity","pronunciation":"/ˌspɒntəˈneɪəti/","meaning":"n.自发性;自然","seq":21,"isStar":false},{"id":1907,"unit":7,"lesson":1,"word":"exhaust","pronunciation":"/ɪɡˈzɔːst/","meaning":"v.使筋疲力尽;用完,耗尽","seq":22,"isStar":false,"memo":"谐音 单词发音类似“一个早死的”→如果一个人死得早,那有可能是因为他的体力早早地“耗尽”了。","example":"A full day's work exhausted him. 一天的工作令他精疲力竭。"},{"id":1908,"unit":7,"lesson":1,"word":"exhaustion","pronunciation":"/ɪɡˈzɔːstʃən/","meaning":"n.耗尽;筋疲力尽","seq":23,"isStar":false},{"id":1909,"unit":7,"lesson":1,"word":"exhaustive","pronunciation":"/ɪɡˈzɔːstɪv/","meaning":"adj.详尽的;彻底的;全面的","seq":24,"isStar":false},{"id":1910,"unit":7,"lesson":1,"word":"weary","pronunciation":"/ˈwɪəri/","meaning":"adj.疲劳的,疲倦的,疲惫的","seq":25,"isStar":false,"memo":"对照 他穿上(wear)衣服,拖着疲惫的(weary)身躯出门了。","example":"Rachel looked pale and weary. 雷切尔看起来脸色苍白,疲惫不堪。"},{"id":1911,"unit":7,"lesson":1,"word":"weariness","pronunciation":"/ˈwɪərinəs/","meaning":"n.疲倦","seq":26,"isStar":false},{"id":1912,"unit":7,"lesson":1,"word":"labo(u)r","pronunciation":"/ˈleɪbə(r)/","meaning":"n.劳动;劳动力","seq":27,"isStar":false,"memo":"谐音 单词发音类似“累不”→他在“劳动”时满头大汗，妈妈问他累不累。","example":"The main labour force is comprised of students working part-time.主要劳动力由兼职学生组成。"},{"id":1913,"unit":7,"lesson":1,"word":"laborious","pronunciation":"/ləˈbɔːriəs/","meaning":"adj.耗时费力的;辛苦的","seq":28,"isStar":false,"memo":"【构词】labor（劳动）+ -ious（充满…的）→‘充满劳作的’！不是‘拉伯瑞厄斯’，是‘lab-or-i-ous’，每音节都像在搬砖。","example":"Translating ancient texts is a laborious but rewarding academic task. 翻译古籍是一项费力但富有回报的学术任务。"},{"id":1914,"unit":7,"lesson":1,"word":"leisure","pronunciation":"/ˈleʒə(r)/","meaning":"n.空闲,闲暇","seq":29,"isStar":false,"memo":"联想 lei(联想“累”)+sure(的确)→他的确累了,想找个“空闲”时间放松一下。","example":"These days we have increased opportunities for leisure. 如今,我们有了更多的休闲机会。"},{"id":1915,"unit":7,"lesson":1,"word":"leisurely","pronunciation":"/ˈleʒəli/","meaning":"adj.慢悠悠的 adv.从容地","seq":30,"isStar":false},{"id":1916,"unit":7,"lesson":1,"word":"fatigue","pronunciation":"/fəˈtiːɡ/","meaning":"n.疲乏,疲劳,劳累","seq":31,"isStar":false,"memo":"联想 fat(胖的)+i(我)+gue(音似“哥”)→我哥哥很胖,容易“疲劳”。","example":"Fatigue results from lack of sleep. 缺乏睡眠会导致疲劳。"},{"id":1917,"unit":7,"lesson":1,"word":"obese","pronunciation":"/əʊˈbiːs/","meaning":"adj.臃肿的,虚胖的,病态肥胖的","seq":32,"isStar":false,"memo":"谐音 单词发音类似“哦，必思”→身材“臃肿”的人必须得思考一下健康问题。","example":"Children of obese mothers are much more likely to become obese themselves later in life.肥胖母亲的子女成年后自己变肥胖的可能性要大得多。"},{"id":1918,"unit":7,"lesson":1,"word":"obesity","pronunciation":"/əʊˈbiːsəti/","meaning":"n.肥胖","seq":33,"isStar":false},{"id":1919,"unit":7,"lesson":1,"word":"feasible","pronunciation":"/ˈfiːzəb(ə)l/","meaning":"adj.可行的,行得通的","seq":34,"isStar":false,"memo":"联想 fea(音似“肥”)+si(联想“四”)+(i)ble(形容词后缀)→减肥四斤的计划是“可行的”。","example":"I would argue that this is a perfectly feasible solution. 我认为这是一个完全可行的解决方案。"},{"id":1920,"unit":7,"lesson":1,"word":"feasibility","pronunciation":"/ˌfiːzəˈbɪləti/","meaning":"n.可行性,可能性","seq":35,"isStar":false,"example":"I doubt the feasibility of the plan.我怀疑这个计划的可行性。"},{"id":1921,"unit":7,"lesson":1,"word":"ponder","pronunciation":"/ˈpɒndə(r)/","meaning":"v.沉思,考虑,琢磨","seq":36,"isStar":false,"memo":"联想 pond(音似“胖的”)+er(表示人的后缀)→有的胖人经常“沉思”该怎么减肥。","example":"The professor found himself constantly pondering the question. 这位教授发现自己经常在思考这个问题。"},{"id":1922,"unit":7,"lesson":1,"word":"response","pronunciation":"/rɪˈspɒns/","meaning":"n.回答,答复;反应,响应","seq":37,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+spon(音似“是棒”)+se→阿姨“反应”很快,是很棒的。","example":"One of the examples of how the mind can alter the immune response was discovered by chance. 关于大脑如何改变免疫反应的一个例子是偶然被发现的。"},{"id":1923,"unit":7,"lesson":1,"word":"respond","pronunciation":"/rɪˈspɒnd/","meaning":"v.回答,回应;作出反应","seq":38,"isStar":false,"memo":"【构词】re-（回）+ spond（承诺，如 sponsor=担保人），一诺千金→有回应就是守诺，所以‘回复/反应’！","example":"Students must respond promptly to the online survey about teaching quality. 学生须及时回复关于教学质量的在线问卷。"},{"id":1924,"unit":7,"lesson":1,"word":"respondent","pronunciation":"/rɪˈspɒndənt/","meaning":"n.回答问题的人;(尤指)调查对象","seq":39,"isStar":false,"memo":"构词 respond(回答)+-ent(表人)→作出回答的人→回答问题的人，调查对象","example":"Half of the respondents disagreed. 半数受访者表示不同意。"},{"id":1925,"unit":7,"lesson":1,"word":"responsive","pronunciation":"/rɪˈspɒnsɪv/","meaning":"adj.反应快的,灵敏的,积极(回应)的","seq":40,"isStar":false,"memo":"构词 respons(回应)+-ive(形容词后缀)→一叫就有回应的→反应快的，灵敏的，积极回应的","example":"The company is highly responsive to changes in demand.公司对需求变化反应迅速。"},{"id":1926,"unit":7,"lesson":1,"word":"feedback","pronunciation":"/ˈfiːdbæk/","meaning":"n.反馈意见(或信息)","seq":41,"isStar":false,"memo":"feed(喂) + back(回来) → 我喂你一口，你再喂我一口，这就是对我的行为给予的反馈→反馈意见","example":"There is a huge value in learning with instant feedback. 即时反馈在学习中有着巨大的价值。"},{"id":1927,"unit":7,"lesson":1,"word":"echo","pronunciation":"/ˈekəʊ/","meaning":"v.&n.回声;反响;共鸣","seq":42,"isStar":false,"memo":"单词发音类似“隘口”→站在狭隘的洞口大喊会有“回声”。","example":"Her footsteps echoed in the empty room. 她的脚步声在空荡荡的屋子里回响。"},{"id":1928,"unit":7,"lesson":1,"word":"correspond","pronunciation":"/ˌkɒrəˈspɒnd/","meaning":"v.相一致,符合,类似于……;通信","seq":43,"isStar":false,"memo":"cor-(一起，都) + respond(回应) → 一起回应，异口同声→相一致，符合","example":"We haven't corresponded for a long time. 我们好久没有通信了。"},{"id":1929,"unit":7,"lesson":1,"word":"correspondence","pronunciation":"/ˌkɒrəˈspɒndəns/","meaning":"n.相关;通信","seq":44,"isStar":false},{"id":1930,"unit":7,"lesson":1,"word":"correspondent","pronunciation":"/ˌkɒrəˈspɒndənt/","meaning":"n.记者;通讯员;通信者","seq":45,"isStar":false},{"id":1931,"unit":7,"lesson":1,"word":"corresponding","pronunciation":"/ˌkɒrəˈspɒndɪŋ/","meaning":"adj.符合的;相应的;相关的","seq":46,"isStar":false},{"id":1932,"unit":7,"lesson":1,"word":"restore","pronunciation":"/rɪˈstɔː(r)/","meaning":"v.恢复;修复;重新采用;归还","seq":47,"isStar":false,"memo":"re-(再，重新) + store(储存) → 文物有了损伤，要先“修复”好才能重新储存。","example":"It should be our goal to restore as much of the original beauty of nature as we can. 我们的目标应该是尽可能多地恢复大自然的原始之美。"},{"id":1933,"unit":7,"lesson":1,"word":"restoration","pronunciation":"/ˌrestəˈreɪʃ(ə)n/","meaning":"n.恢复;修复;归还","seq":48,"isStar":false},{"id":1934,"unit":7,"lesson":1,"word":"lounge","pronunciation":"/laʊndʒ/","meaning":"n.(机场等的)等候室;公共休息室","seq":49,"isStar":false,"memo":"loun(音似“劳”) + ge(联想“哥”) → 哥哥很劳累，正在“公共休息室”休息。","example":"The lounge is not a place for him to study in. 休息室不是他学习的地方。"},{"id":1935,"unit":7,"lesson":1,"word":"shelter","pronunciation":"/ˈʃeltə(r)/","meaning":"n.遮蔽,庇护;庇护所","seq":50,"isStar":false,"memo":"单词发音类似“歇了他”→他实在太累了，在“避难所”歇息了一下。","example":"The homeless man sought shelter from the rain under a bridge. 那个无家可归的人在桥下躲避雨水。"},{"id":1936,"unit":7,"lesson":1,"word":"haven","pronunciation":"/ˈheɪv(ə)n/","meaning":"n.安全的地方;避难所","seq":51,"isStar":false,"memo":"对照 这个安全的地方（haven）就像天堂（heaven）。","example":"They have unintentionally created a haven for homeless people.他们无意中为无家可归者创造了一个避风港。"},{"id":1937,"unit":7,"lesson":1,"word":"harbo(u)r","pronunciation":"/ˈhɑːbə(r)/","meaning":"n.海港,港口 v.庇护;怀有","seq":52,"isStar":false,"memo":"联想 船躲风浪的地方，引申为心里藏着(念头)→海港，港口；庇护；怀有","example":"He still harbours a grudge against her. 他对她仍心怀怨恨。"},{"id":1938,"unit":7,"lesson":1,"word":"slum","pronunciation":"/slʌm/","meaning":"n.贫民窟,贫民区;非常脏乱的地方","seq":53,"isStar":false,"memo":"slu(音似“死拉”) + m(联想“妹”) → 他拼命地拉着妹妹离开“贫民窟”。","example":"She was brought up in the slums of Leeds. 她是在利兹的贫民区长大的。"},{"id":1939,"unit":7,"lesson":1,"word":"tend","pronunciation":"/tend/","meaning":"v.往往会;趋于,倾向;照管,护理","seq":54,"isStar":false,"memo":"联想 ten(十)+d(音似“的”)→人是不可能十全十美的,只能“趋于”完美。","example":"Women tend to live longer than men. 女性往往比男性长寿。"},{"id":1940,"unit":7,"lesson":1,"word":"tendency","pronunciation":"/ˈtendənsi/","meaning":"n.倾向,趋势","seq":55,"isStar":false},{"id":1941,"unit":7,"lesson":1,"word":"attend","pronunciation":"/əˈtend/","meaning":"v.出席,参加;照顾","seq":56,"isStar":false,"memo":"联想 at-(一再地)+tend(趋于→延伸)→课堂上他一再地延伸手臂(举手),积极“参加”课堂活动。","example":"The woman doesn't want to attend the lecture. 这位女士不想参加讲座。"},{"id":1942,"unit":7,"lesson":1,"word":"attendance","pronunciation":"/əˈtendəns/","meaning":"n.出席,参加;上学","seq":57,"isStar":false},{"id":1943,"unit":7,"lesson":1,"word":"attendant","pronunciation":"/əˈtendənt/","meaning":"n.服务员;随从;护理者","seq":58,"isStar":false},{"id":1944,"unit":7,"lesson":1,"word":"contend","pronunciation":"/kənˈtend/","meaning":"v.主张;认为;竞争,争夺","seq":59,"isStar":false,"memo":"联想 con-(所有)+tend(延伸)→课堂上所有的同学都伸手表述自己“主张”的观点,同学之间的关系就是“竞争”。","example":"He contends that the ruling could have profound effects on other industries. 他认为,这项裁决可能对其他行业产生深远的影响。"},{"id":1945,"unit":7,"lesson":1,"word":"contention","pronunciation":"/kənˈtenʃ(ə)n/","meaning":"n.争吵,争执;看法,观点","seq":60,"isStar":false,"memo":"构词 con-(一起)+tent(拉紧，同 tense 紧张的)+-ion(名词后缀)→双方各拉一头不放手→争吵，争执；看法","example":"What is your contention against him?你对他的论据是什么？"},{"id":1946,"unit":7,"lesson":1,"word":"contentious","pronunciation":"/kənˈtenʃəs/","meaning":"adj.引起争论的;爱争论的","seq":61,"isStar":false},{"id":1947,"unit":7,"lesson":1,"word":"intend","pronunciation":"/ɪnˈtend/","meaning":"v.打算,计划,想要;意指","seq":62,"isStar":false,"memo":"构词 in(里面)+tend(延伸)→(想法)在里面(内心)延伸→打算","example":"She was intending to work part time. 她打算做兼职工作。"},{"id":1948,"unit":7,"lesson":1,"word":"intent","pronunciation":"/ɪnˈtent/","meaning":"n.意图,目的 adj.热切的;专注的","seq":63,"isStar":false,"memo":"构词 in-(向内)+tent(拉紧)→注意力全往一处绷紧→意图，目的；热切的，专注的","example":"She denies possessing the drug with intent to supply. 她否认拥有毒品是为了提供给别人。"},{"id":1949,"unit":7,"lesson":1,"word":"intention","pronunciation":"/ɪnˈtenʃ(ə)n/","meaning":"n.打算;意图,目的","seq":64,"isStar":false,"memo":"对照 intend v.打算→intention n.","example":"Her intentions in making this proposal are clear. 她提出这个建议的意图很明显。"},{"id":1950,"unit":7,"lesson":1,"word":"intentional","pronunciation":"/ɪnˈtenʃən(ə)l/","meaning":"adj.故意的,存心的","seq":65,"isStar":false,"memo":"构词 intent(意图)+-ional(形容词后缀)→带着意图去做的→故意的，存心的","example":"The damage was clearly intentional. 这些损坏显然是故意造成的。"},{"id":1951,"unit":7,"lesson":1,"word":"extend","pronunciation":"/ɪkˈstend/","meaning":"v.延伸;延长;扩展","seq":66,"isStar":false,"memo":"构词 ex-(向外)+tend(延伸)→延伸","example":"Careful maintenance can extend the life of your car. 精心保养可延长你的汽车寿命。"},{"id":1952,"unit":7,"lesson":1,"word":"extended","pronunciation":"/ɪkˈstendɪd/","meaning":"adj.延长了的;扩展了的","seq":67,"isStar":false},{"id":1953,"unit":7,"lesson":1,"word":"extension","pronunciation":"/ɪkˈstenʃ(ə)n/","meaning":"n.扩大;延伸","seq":68,"isStar":false},{"id":1954,"unit":7,"lesson":1,"word":"extensive","pronunciation":"/ɪkˈstensɪv/","meaning":"adj.广阔的;大量的;广泛的","seq":69,"isStar":false,"memo":"（对照）extend v. 延伸；扩展 → extensive adj.","example":"Extensive repair work is being carried out.大规模的修复工作正在进行中。"},{"id":1955,"unit":7,"lesson":1,"word":"stretch","pronunciation":"/stretʃ/","meaning":"v.伸展,舒展;拉紧;拉长 n.一片","seq":70,"isStar":false,"memo":"谐音 单词发音类似“死拽扯”→他伸出手臂拼命地拽我,拉我→伸展","example":"The exercises are designed to stretch your leg muscles. 这些活动的目的在于伸展你的腿部肌肉。"},{"id":1956,"unit":7,"lesson":1,"word":"space","pronunciation":"/speɪs/","meaning":"n.外层空间;太空;空间","seq":71,"isStar":false,"memo":"构词 spat(展开，同 spacious 宽敞的)+-e→展开来的一大片→空间，太空，外层空间","example":"I'll clear a space for your books. 我会腾出一块空间好放你的书。"},{"id":1957,"unit":7,"lesson":1,"word":"spacious","pronunciation":"/ˈspeɪʃəs/","meaning":"adj.宽敞的","seq":72,"isStar":false},{"id":1958,"unit":7,"lesson":1,"word":"spatial","pronunciation":"/ˈspeɪʃ(ə)l/","meaning":"adj.空间的","seq":73,"isStar":false},{"id":1959,"unit":7,"lesson":1,"word":"extent","pronunciation":"/ɪkˈstent/","meaning":"n.程度;大小;范围","seq":74,"isStar":false,"memo":"构词 ex-(向外)+tent(拉紧)→向外拉开的幅度→程度，大小，范围","example":"To some extent what she argues is true. 她的论证在某种程度上是符合事实的。"},{"id":1960,"unit":7,"lesson":1,"word":"scale","pronunciation":"/skeɪl/","meaning":"n.规模,程度;等级 v.攀登","seq":75,"isStar":false,"memo":"联想 与 escalator(自动扶梯)同根：一级一级的刻度→规模，程度；等级；攀登","example":"They entertain friends on a large scale. 他们举行大规模的宴会招待朋友。"},{"id":1961,"unit":7,"lesson":1,"word":"pattern","pronunciation":"/ˈpæt(ə)n/","meaning":"n.模式,方式;榜样;图案,花样;模型","seq":76,"isStar":false,"memo":"谐音 单词发音类似“怕疼”→怕疼就不要再往身上文“图案”了。","example":"This system sets the pattern for others to follow. 这个系统是他人仿效的典范。"},{"id":1962,"unit":7,"lesson":1,"word":"dimension","pronunciation":"/daɪˈmenʃ(ə)n/","meaning":"n.维(构成空间的因素);尺寸;规模","seq":77,"isStar":false,"memo":"联想 di-(两个,双)+mension(音似“门神”)→贴在门上的两个门神的“尺寸”要一样大。","example":"Our study shows that, for women, well-being has two dimensions. 我们的研究表明,对女性来说,幸福有两个维度。"},{"id":1963,"unit":7,"lesson":1,"word":"dimensional","pronunciation":"/daɪˈmenʃən(ə)l/","meaning":"adj.尺寸的;维度的","seq":78,"isStar":false},{"id":1964,"unit":7,"lesson":1,"word":"mention","pronunciation":"/ˈmenʃ(ə)n/","meaning":"v.提到;写到,说到 n.提及;说起","seq":79,"isStar":false,"memo":"谐音 单词发音类似“门神”→过年时,人们常会“提到”贴门神。","example":"He made no mention of her work. 他根本没提她的工作。"},{"id":1965,"unit":7,"lesson":1,"word":"measure","pronunciation":"/ˈmeʒə(r)/","meaning":"n.措施,方法;程度;判断","seq":80,"isStar":false,"memo":"构词 meas(量，同 dimension 尺寸)+-ure(名词后缀)→量出来的数→措施，方法；程度；测量","example":"The scientists should take effective measures to protect themselves. 科学家们应该采取有效措施保护自己。"},{"id":1966,"unit":7,"lesson":1,"word":"measurement","pronunciation":"/ˈmeʒəmənt/","meaning":"n.测量;度量","seq":81,"isStar":false},{"id":1967,"unit":7,"lesson":1,"word":"measurable","pronunciation":"/ˈmeʒərəbl/","meaning":"adj.可测量的;显著的","seq":82,"isStar":false},{"id":1968,"unit":7,"lesson":1,"word":"apt","pronunciation":"/æpt/","meaning":"adj.恰当的;易于……,有……倾向的","seq":83,"isStar":false,"memo":"谐音：单词发音类似“爱扑它”→爱扑它就是倾向于靠近某物→有……倾向的","example":"The words of this report are apt. 这份报告的措辞很恰当。"},{"id":1969,"unit":7,"lesson":1,"word":"opt","pronunciation":"/ɒpt/","meaning":"v.选择,挑选","seq":84,"isStar":false,"memo":"联想：op-(表示方向)+t(联想“它”)→有多个物品摆在他面前,他朝其中一个走去,“选择”了它。","example":"He notified the administration of his decision to opt out. 他通知了政府,决定选择退出。"},{"id":1970,"unit":7,"lesson":1,"word":"option","pronunciation":"/ˈɒpʃ(ə)n/","meaning":"n.选择;可选择的东西;选项","seq":85,"isStar":false},{"id":1971,"unit":7,"lesson":1,"word":"optional","pronunciation":"/ˈɒpʃən(ə)l/","meaning":"adj.可选择的,非强制的","seq":86,"isStar":false,"memo":"构词 option(选择) + -al(形容词后缀) → 可选择的","example":"The school provides a variety of optional courses.学校提供各种选修课。"},{"id":1972,"unit":7,"lesson":1,"word":"optical","pronunciation":"/ˈɒptɪk(ə)l/","meaning":"adj.视力的;视觉的;光学的","seq":87,"isStar":false,"memo":"联想：op-(表示方向)+ti(联想“踢”)+-(i)cal(形容词后缀)→他朝着某个方向踢到了别人,因为他视力不好→视力的","example":"The optical image is very clear. 这个视觉图像非常清晰。"},{"id":1973,"unit":7,"lesson":1,"word":"optic","pronunciation":"/ˈɒptɪk/","meaning":"adj.眼的;视觉的","seq":88,"isStar":false},{"id":1974,"unit":7,"lesson":1,"word":"optimal","pronunciation":"/ˈɒptɪməl/","meaning":"adj.最佳的;最适宜的","seq":89,"isStar":false,"memo":"联想 op(联想 opt) + timal(音似“剃毛”) → 很多人选择在二月初二剃毛发(理发)，因为这天是民俗中“最佳的”日期。","example":"The optimal temperature for the development of it is in the range 18～26℃.其生长的最适宜温度在18～26℃之间。"},{"id":1975,"unit":7,"lesson":1,"word":"optimum","pronunciation":"/ˈɒptɪməm/","meaning":"adj.最佳的;最适宜的","seq":90,"isStar":false,"memo":"构词：optim(最好的)+-um(后缀)→最佳的;最适宜的","example":"What are the optimum conditions for economic growth? 经济增长的最佳条件是什么?"},{"id":1976,"unit":7,"lesson":1,"word":"compulsory","pronunciation":"/kəmˈpʌlsəri/","meaning":"adj.强制的,强迫的","seq":91,"isStar":false,"memo":"联想：com-(所有)+pul(音似“趴”)+sory(联想 sorry)→所有护卫被迫趴在那里,跟国王说对不起→强制的,强迫的","example":"There are two main arguments for compulsory quotas. 关于强制配额有两种主要观点。"},{"id":1977,"unit":7,"lesson":1,"word":"discipline","pronunciation":"/ˈdɪsəplɪn/","meaning":"n.训练,管教;纪律;学科","seq":92,"isStar":false,"memo":"构词 discip(学习，同 disciple 门徒)+-line(名词后缀)→对门徒的管教→训练，纪律；学科","example":"Learning a language requires discipline. 学一门语言需要自律。"},{"id":1978,"unit":7,"lesson":1,"word":"disciplined","pronunciation":"/ˈdɪsəplɪnd/","meaning":"adj.受过训练的;遵守纪律的","seq":93,"isStar":false,"memo":"构词 discipline(纪律)+-ed(形容词后缀)→守得住纪律的→受过训练的，遵守纪律的","example":"She is a highly disciplined athlete. 她是一名极度自律的运动员。"},{"id":1979,"unit":7,"lesson":1,"word":"disciplinary","pronunciation":"/ˌdɪsəˈplɪnəri; ˈdɪsəplɪnəri/","meaning":"adj.有关纪律的;惩戒性的","seq":94,"isStar":false,"memo":"构词 disciplin(纪律)+-ary(形容词后缀)→与纪律有关的→有关纪律的；惩戒性的","example":"He faced disciplinary action. 他面临纪律处分。"},{"id":1980,"unit":7,"lesson":1,"word":"punctual","pronunciation":"/ˈpʌŋktʃuəl/","meaning":"adj.准时的,守时的","seq":95,"isStar":false,"memo":"联想 punct(音似“胖克他”)+-ual(形容词后缀)→他很胖,努力克服困难,每天准时锻炼→准时的","example":"He is always punctual for his class. 他总是准时上课。"},{"id":1981,"unit":7,"lesson":1,"word":"punctuality","pronunciation":"/ˌpʌŋktʃuˈæləti/","meaning":"n.准时","seq":96,"isStar":false},{"id":1982,"unit":7,"lesson":1,"word":"principle","pronunciation":"/ˈprɪnsəp(ə)l/","meaning":"n.法则,原则;行为准则","seq":97,"isStar":false,"memo":"联想 prin(联想 prince)+cip(抓)+le→王子都得抓住(遵守)“法则”。","example":"In principle, I agree with the idea. 我大体上赞成这个想法。"},{"id":1983,"unit":7,"lesson":1,"word":"principal","pronunciation":"/ˈprɪnsəp(ə)l/","meaning":"n.校长;首长 adj.最重要的,主要的","seq":98,"isStar":false,"memo":"联想 princi(联想 prince)+pal(联想“怕了”)→这个连王子都怕了的人是“首长”。","example":"We provide teachers and principals the support they need. 我们为老师和校长提供他们需要的支持。"},{"id":1984,"unit":7,"lesson":1,"word":"methodology","pronunciation":"/ˌmeθəˈdɒlədʒi/","meaning":"n.方法,原则","seq":99,"isStar":false,"memo":"构词 method(方法) + -ology(名词后缀) → 方法","example":"Together we decide on the methodology and the objectives of the research.我们一起决定研究的方法和目标。"},{"id":1985,"unit":7,"lesson":1,"word":"method","pronunciation":"/ˈmeθəd/","meaning":"n.方法;措施;条理","seq":100,"isStar":false},{"id":1986,"unit":7,"lesson":1,"word":"methodical","pronunciation":"/məˈθɒdɪkl/","meaning":"adj.有条理的;有条不紊的","seq":101,"isStar":false},{"id":1987,"unit":7,"lesson":1,"word":"ideal","pronunciation":"/aɪˈdiːəl/","meaning":"adj.完美的;理想的;最合适的","seq":102,"isStar":false,"memo":"对照 一个理想的(ideal)人是有思想(idea)的。","example":"This beach is ideal for children. 这个海滩是孩子的理想去处。"},{"id":1988,"unit":7,"lesson":1,"word":"idealism","pronunciation":"/aɪˈdiːəlɪzəm/","meaning":"n.理想主义;唯心主义","seq":103,"isStar":false},{"id":1989,"unit":7,"lesson":1,"word":"idealistic","pronunciation":"/ˌaɪdiəˈlɪstɪk/","meaning":"adj.理想主义的;空想的","seq":104,"isStar":false},{"id":1990,"unit":7,"lesson":1,"word":"doctrine","pronunciation":"/ˈdɒktrɪn/","meaning":"n.教义,主义;学说,信条","seq":105,"isStar":false,"memo":"联想 doc(联想 doctor)+trine(音似“纯”)→医生要遵守的“信条”就是“救死扶伤”,动机纯粹。","example":"He was deeply committed to political doctrines of social equality. 他深深致力于社会平等的政治学说。"},{"id":1991,"unit":7,"lesson":1,"word":"dogma","pronunciation":"/ˈdɒɡmə/","meaning":"n.教义;信条;教条","seq":106,"isStar":false,"memo":"联想 dog(小狗) + ma(联想“妈”) → 小狗妈妈的话是小狗的“信条”。","example":"People are beginning to question the old dogmas.人们开始质疑旧的教条。"},{"id":1992,"unit":7,"lesson":1,"word":"hospitable","pronunciation":"/hɒˈspɪtəb(ə)l/","meaning":"adj.好客的,热情的","seq":107,"isStar":false,"memo":"对照 医院(hospital)的医生是很热情的(hospitable)，总是耐心倾听患者的诉求。","example":"Natives there remain very kind and hospitable.那里的当地人非常友善好客。"},{"id":1993,"unit":7,"lesson":1,"word":"hospitality","pronunciation":"/ˌhɒspɪˈtæləti/","meaning":"n.好客,殷勤","seq":108,"isStar":false},{"id":1994,"unit":7,"lesson":1,"word":"cordial","pronunciation":"/ˈkɔːdiəl/","meaning":"adj.热情友好的 n.果汁","seq":109,"isStar":false,"memo":"联想 cor(音似“靠”)+dial(音似 dear)→靠着昂贵的消费,他获得了“热情友好的”服务。","example":"I am very grateful to you for the cordial hospitality you accorded me. 承蒙你的热情招待,我十分感激。"},{"id":1995,"unit":7,"lesson":1,"word":"cordially","pronunciation":"/ˈkɔːdiəli/","meaning":"adv.热诚地,诚挚地","seq":110,"isStar":false,"memo":"构词 cord(心，同 courage 勇气)+-ial+-ly(副词后缀)→从心里发出来的→热诚地，诚挚地","example":"You are cordially invited to the dinner. 诚挚地邀请您出席晚宴。"},{"id":1996,"unit":7,"lesson":2,"word":"acquire","pronunciation":"/əˈkwaɪə(r)/","meaning":"v.获得,得到","seq":1,"isStar":false,"memo":"联想 ac-(一再地) + quire(询问) → 一再地询问，终会“得到”答案。","example":"Automation will help workers acquire new skills. 自动化将帮助工人获得新技能。"},{"id":1997,"unit":7,"lesson":2,"word":"acquisition","pronunciation":"/ˌækwɪˈzɪʃ(ə)n/","meaning":"n.获得,习得;购得物;购置","seq":2,"isStar":false,"memo":"对照 acquire v.获得，得到 → acquisition n.","example":"Indeed, ease of acquisition is the problem. 确实，容易获得才是问题所在。"},{"id":1998,"unit":7,"lesson":2,"word":"inquire/enquire","pronunciation":"/ɪnˈkwaɪə(r)/","meaning":"v.询问,打听","seq":3,"isStar":false,"memo":"构词 in-(向内)+quir(寻求，同 require 需要)+-e→往里追问到底→询问，打听","example":"She inquired about the train times. 她询问了火车时刻。"},{"id":1999,"unit":7,"lesson":2,"word":"inquiry/enquiry","pronunciation":"/ɪnˈkwaɪəri/","meaning":"n.调查;打听;查询","seq":4,"isStar":false,"memo":"构词 inquir(询问)+-y(名词后缀)→打听这件事→调查，打听，查询","example":"The police opened an inquiry into the accident. 警方对这起事故展开调查。"},{"id":2000,"unit":7,"lesson":2,"word":"inquisitive","pronunciation":"/ɪnˈkwɪzətɪv/","meaning":"adj.过分好奇的,爱打听的","seq":5,"isStar":false},{"id":2001,"unit":7,"lesson":2,"word":"require","pronunciation":"/rɪˈkwaɪə(r)/","meaning":"v.需要;要求","seq":6,"isStar":false,"memo":"构词 re-(重复) + quire(询问) → 重复地询问，因为“需要”准确的信息。","example":"Breeding a wild plant into a major food crop requires much research time. 将一种野生植物培育成主要粮食作物，需要大量的研究时间。"},{"id":2002,"unit":7,"lesson":2,"word":"requirement","pronunciation":"/rɪˈkwaɪəmənt/","meaning":"n.所需的东西;规定,要求","seq":7,"isStar":false,"memo":"构词 require(要求)+-ment(名词后缀)→被要求的东西→所需的东西，规定，要求","example":"He meets all the requirements for the job. 他符合这份工作的全部要求。"},{"id":2003,"unit":7,"lesson":2,"word":"requisite","pronunciation":"/ˈrekwɪzɪt/","meaning":"adj.必需的 n.必需的事物","seq":8,"isStar":false},{"id":2004,"unit":7,"lesson":2,"word":"prerequisite","pronunciation":"/ˌpriːˈrekwəzɪt/","meaning":"n.先决条件,前提,必备条件","seq":9,"isStar":false,"memo":"构词 pre-(提前) + requisite(必需的事物) → 提前就需要的事物 → 先决条件，前提","example":"A degree is an essential prerequisite for employment at this level. 学位是做这级工作必备的先决条件。"},{"id":2005,"unit":7,"lesson":2,"word":"plea","pronunciation":"/pliː/","meaning":"n.恳求;辩解;借口","seq":10,"isStar":false,"memo":"对照 请(please)不要再恳求(plea)他了，他不会答应的。","example":"Hospital visiting hours were extended in response to pleas from patients. 应病人的恳求，医院延长了探视时间。"},{"id":2006,"unit":7,"lesson":2,"word":"plead","pronunciation":"/pliːd/","meaning":"v.恳求;为……辩护","seq":11,"isStar":false,"memo":"【谐音】‘ pleaded ’读如‘ pleading ’——‘求得’！跪求法官‘please, I plead!’；【构词】plea（恳求）+ -d，法律场景中‘认罪/辩护’都是求的态度。","example":"The defendant chose to plead not guilty in court. 被告选择在法庭上作无罪辩护。"},{"id":2007,"unit":7,"lesson":2,"word":"request","pronunciation":"/rɪˈkwest/","meaning":"v.&n.请求,要求","seq":12,"isStar":false,"memo":"构词 re-(重复) + quest(寻找，追求) → 重复地寻找或追求 → 请求，要求","example":"They made a formal request for help. 他们正式请求帮助。"},{"id":2008,"unit":7,"lesson":2,"word":"quest","pronunciation":"/kwest/","meaning":"n.探索;寻找;追求(幸福等) v.探索","seq":13,"isStar":false,"memo":"构词 quer/quaer(寻求，同 question 问题)+-st→一路追着找→探索，寻找，追求","example":"They went in quest of gold. 他们去寻找黄金了。"},{"id":2009,"unit":7,"lesson":2,"word":"questionnaire","pronunciation":"/ˌkwestʃəˈneə(r)/","meaning":"n.调查表,调查问卷,问卷","seq":14,"isStar":false,"memo":"[联想] question(问题) + naire(联想“奶”) + re (字母音似“阿姨”) → 奶奶和阿姨经常填写带有很多问题的“调查问卷”。","example":"We were asked to fill in a questionnaire. 我们被要求填写一张调查表。"},{"id":2010,"unit":7,"lesson":2,"word":"pursue","pronunciation":"/pəˈsjuː/","meaning":"v.追求;致力于;追捕","seq":15,"isStar":false,"memo":"[谐音] 单词发音类似“破书”→为了“追求”真理,他把书都翻破了。","example":"Make a commitment to pursue those things that you love most. 致力于追求那些你最热爱的事情。"},{"id":2011,"unit":7,"lesson":2,"word":"pursuit","pronunciation":"/pəˈsjuːt/","meaning":"n.追求;追赶","seq":16,"isStar":false},{"id":2012,"unit":7,"lesson":2,"word":"power","pronunciation":"/ˈpaʊə(r)/","meaning":"n.权力,权势,职权;力量,动力","seq":17,"isStar":false,"memo":"[谐音] 单词发音类似“怕我”→他怕我是因为我有“权势”。","example":"The powers of the police must be clearly defined. 警察的职权必须明确界定。"},{"id":2013,"unit":7,"lesson":2,"word":"powerful","pronunciation":"/ˈpaʊəf(ə)l/","meaning":"adj.有权势的;力量大的","seq":18,"isStar":false},{"id":2014,"unit":7,"lesson":2,"word":"willpower","pronunciation":"/ˈwɪlpaʊə(r)/","meaning":"n.意志力","seq":19,"isStar":false,"memo":"构词 will(意志)+power(力量)→意志的力量→意志力","example":"It is very important to have confidence in one's willpower.对自己的意志力有信心非常重要。"},{"id":2015,"unit":7,"lesson":2,"word":"force","pronunciation":"/fɔːs/","meaning":"n.力量;武力;影响力;部队 v.强迫","seq":20,"isStar":false,"memo":"构词 fort(强，同 effort 努力)+-e→强大的作用力→力量；武力；影响力；部队；强迫","example":"If properly handled, it may become a driving force. 若处理得当,这也有可能转化为一种推动力。"},{"id":2016,"unit":7,"lesson":2,"word":"forceful","pronunciation":"/ˈfɔːsfl/","meaning":"adj.强有力的;有说服力的;坚强的","seq":21,"isStar":false},{"id":2017,"unit":7,"lesson":2,"word":"enforce","pronunciation":"/ɪnˈfɔːs/","meaning":"v.强制执行,强行实施(法律或规定)","seq":22,"isStar":false,"memo":"[构词] en-(使……) + force(强迫) → 使强迫发生 → 强制执行,强行实施","example":"It's the job of the police to enforce the law. 警察的工作就是执法。"},{"id":2018,"unit":7,"lesson":2,"word":"enforcement","pronunciation":"/ɪnˈfɔːsmənt/","meaning":"n.执行","seq":23,"isStar":false},{"id":2019,"unit":7,"lesson":2,"word":"oblige","pronunciation":"/əˈblaɪdʒ/","meaning":"v.迫使,强制;帮忙","seq":24,"isStar":false,"memo":"单词发音类似“我不来挤”→我不来挤也逃不掉,因为这是我的责任和义务→迫使,强制","example":"The law obliges parents to send their children to school. 法律强制要求父母送子女上学。"},{"id":2020,"unit":7,"lesson":2,"word":"obligation","pronunciation":"/ˌɒblɪˈɡeɪʃ(ə)n/","meaning":"n.义务,职责","seq":25,"isStar":false},{"id":2021,"unit":7,"lesson":2,"word":"obliged","pronunciation":"/əˈblaɪdʒd/","meaning":"adj.感激的;有责任的","seq":26,"isStar":false},{"id":2022,"unit":7,"lesson":2,"word":"obligatory","pronunciation":"/əˈblɪɡətri/","meaning":"adj.(按法律、规定等)必须的,强制的","seq":27,"isStar":false},{"id":2023,"unit":7,"lesson":2,"word":"reinforce","pronunciation":"/ˌriːɪnˈfɔːs/","meaning":"v.加强,强化;加固","seq":28,"isStar":false,"memo":"re-(重复)+in(里面)+force(力量)→重复往里增加力量→加强;加固","example":"This conclusion was reinforced by another finding. 另一项发现强化了这一结论。"},{"id":2024,"unit":7,"lesson":2,"word":"reinforcement","pronunciation":"/ˌriːɪnˈfɔːsmənt/","meaning":"n.巩固,加强;援军","seq":29,"isStar":false},{"id":2025,"unit":7,"lesson":2,"word":"enhance","pronunciation":"/ɪnˈhɑːns/","meaning":"v.提高;增强;增进","seq":30,"isStar":false,"memo":"en-(使)+hance(音似“汉斯”,人名)→汉斯是我的学生,我要帮他“提高”成绩。","example":"A woman's well-being is enhanced when she takes on multiple roles. 当女性扮演多重角色时,她的幸福感会增强。"},{"id":2026,"unit":7,"lesson":2,"word":"enhancement","pronunciation":"/ɪnˈhɑːnsmənt/","meaning":"n.提高,增加;增强","seq":31,"isStar":false},{"id":2027,"unit":7,"lesson":2,"word":"advance","pronunciation":"/ədˈvɑːns/","meaning":"n.进展,进步;前进;上涨","seq":32,"isStar":false,"memo":"ad-(一再地)+vance(联想“万斯”,人名)→挫折一再地使万斯“进步”。","example":"His advance in computers should be appreciated by us. 他在计算机上的进步值得我们赞赏。"},{"id":2028,"unit":7,"lesson":2,"word":"advanced","pronunciation":"/ədˈvɑːnst/","meaning":"adj.先进的;高级的","seq":33,"isStar":false},{"id":2029,"unit":7,"lesson":2,"word":"advancement","pronunciation":"/ədˈvɑːnsmənt/","meaning":"n.促进;发展;前进","seq":34,"isStar":false},{"id":2030,"unit":7,"lesson":2,"word":"underdeveloped","pronunciation":"/ˌʌndədɪˈveləpt/","meaning":"adj.不发达的,欠发达的;发育不全的","seq":35,"isStar":false,"memo":"构词 under-(不足)+developed(发达的)→发展程度不够的→不发达的，欠发达的；发育不全的","example":"The region remains underdeveloped. 这个地区仍然欠发达。"},{"id":2031,"unit":7,"lesson":2,"word":"boost","pronunciation":"/buːst/","meaning":"n.帮助;激励;提高 v.使增长,使兴旺","seq":36,"isStar":false,"memo":"booT形似600)+st(联想street)→修600条街道助力农村经济增长→使增长","example":"The new policy gave a boost to the local tourism industry. 新政策激励了当地旅游业的发展。"},{"id":2032,"unit":7,"lesson":2,"word":"boast","pronunciation":"/bəʊst/","meaning":"n.引以为豪的事物","seq":37,"isStar":false,"memo":"他在海岸(coast)吃烧烤(roast),一边和朋友干杯(toast),一边自夸(boast)。","example":"\"I wouldn't be afraid,\" she boasted. “我才不怕呢。”她吹嘘道。"},{"id":2033,"unit":7,"lesson":2,"word":"boastful","pronunciation":"/ˈbəʊstfl/","meaning":"adj.自吹自擂的,自夸的","seq":38,"isStar":false},{"id":2034,"unit":7,"lesson":2,"word":"exaggerate","pronunciation":"/ɪɡˈzædʒəreɪt/","meaning":"v.夸张,夸大,言过其实","seq":39,"isStar":false,"memo":"ex-(向外)+agg(e)(联想egg)+rate(速度)→这只鸡向外下蛋的速度真“夸张”。","example":"Most studies exaggerate the effect of media violence on the viewers. 大多数研究夸大了媒体暴力对观众的影响。"},{"id":2035,"unit":7,"lesson":2,"word":"overstate","pronunciation":"/ˌəʊvəˈsteɪt/","meaning":"v.夸大,夸张,言过其实","seq":40,"isStar":false,"memo":"over(过度)+state(陈述)→夸大","example":"They overstate the government's interference with the food industry. 他们夸大了政府对食品行业的干预。"},{"id":2036,"unit":7,"lesson":2,"word":"state","pronunciation":"/steɪt/","meaning":"n.状态;国家;政府;州 v.陈述,说明","seq":41,"isStar":false,"memo":"对照 他对个人财产(estate)的归属作了简单陈述(state)。","example":"Your physical state and build can also affect which jobs you can do. 你的身体状况和体格也会影响你能做什么工作。"},{"id":2037,"unit":7,"lesson":2,"word":"statement","pronunciation":"/ˈsteɪtmənt/","meaning":"n.声明;观点","seq":42,"isStar":false},{"id":2038,"unit":7,"lesson":2,"word":"memory","pronunciation":"/ˈmeməri/","meaning":"n.回忆,记忆;记忆力;存储器","seq":43,"isStar":false,"memo":"构词 memor(记住，同 remember)+-y(名词后缀)→记住的能力与内容→记忆，记忆力；存储器","example":"He has a poor memory. 他记忆力不好。"},{"id":2039,"unit":7,"lesson":2,"word":"memorise/-ize","pronunciation":"/ˈmeməraɪz/","meaning":"v.记住,熟记","seq":44,"isStar":false,"memo":"构词 memor(记住)+-ise/-ize(使…化)→使牢牢记进脑子里→记住，熟记","example":"Try to memorise these ten words. 试着记住这十个单词。"},{"id":2040,"unit":7,"lesson":2,"word":"memo","pronunciation":"/ˈmeməʊ/","meaning":"n.备忘录","seq":45,"isStar":false,"memo":"对照 她把想要记住的事记录在备忘录（memo）中，供以后回忆（memory）。","example":"I have to finish this memo and put it in the mail.我得写完这份备忘录然后寄出去。"},{"id":2041,"unit":7,"lesson":2,"word":"commemorate","pronunciation":"/kəˈmeməreɪt/","meaning":"v.纪念;庆祝,为……举行纪念活动","seq":46,"isStar":false,"memo":"构词 com-(共同)+memor(=memory)+-ate(动词后缀)→共同记忆→纪念","example":"To commemorate important dates in history, countries create special holidays. 为纪念历史上重要的日子,各国设立了特别的节假日。"},{"id":2042,"unit":7,"lesson":2,"word":"commemoration","pronunciation":"/kəˌmeməˈreɪʃn/","meaning":"n.纪念;纪念仪式","seq":47,"isStar":false},{"id":2043,"unit":7,"lesson":2,"word":"memorial","pronunciation":"/məˈmɔːriəl/","meaning":"n.纪念碑;纪念物","seq":48,"isStar":false,"memo":"构词 memor(y)(记忆)+-ial(后缀)→纪念碑;纪念的","example":"The town raised a memorial to them. 这座小镇为他们建立了一座纪念碑。"},{"id":2044,"unit":7,"lesson":2,"word":"monument","pronunciation":"/ˈmɒnjumənt/","meaning":"n.纪念碑;遗址,遗迹;名胜古迹","seq":49,"isStar":false,"memo":"联想 monu(音似“牦牛”)+-ment(名词后缀)→人们修建了一座牦牛的“纪念碑”来纪念他。","example":"It is a historical monument. 它是一座历史纪念碑。"},{"id":2045,"unit":7,"lesson":2,"word":"monumental","pronunciation":"/ˌmɒnjuˈment(ə)l/","meaning":"adj.重要的;意义深远的;不朽的","seq":50,"isStar":false},{"id":2046,"unit":7,"lesson":2,"word":"recall","pronunciation":"/rɪˈkɔːl/","meaning":"n.记忆力;召回 v.回忆起,回想起","seq":51,"isStar":false,"memo":"联想 re-(再) + call(打电话)→再次打电话，把他叫回来→召回","example":"A few people with remarkable memories are said to have “total recall”. 据说，少数记性极好的人具有“完全记忆”的能力。"},{"id":2047,"unit":7,"lesson":2,"word":"remind","pronunciation":"/rɪˈmaɪnd/","meaning":"v.提醒;使想起","seq":52,"isStar":false,"memo":"构词 re-(再) + mind(头脑)→使再回到头脑中→提醒；使想起","example":"We would do well to remind ourselves that technology is a human creation. 我们最好提醒自己，技术是人类的创造。"},{"id":2048,"unit":7,"lesson":2,"word":"reminder","pronunciation":"/rɪˈmaɪndə(r)/","meaning":"n.勾起回忆的事物,起提醒作用的事物","seq":53,"isStar":false,"memo":"构词 remind(提醒)+-er(表物)→起提醒作用的东西→提示单，通知单；勾起回忆的事物","example":"This is a timely reminder of the importance of the retail sector to our economy.这及时提醒了我们零售业对经济的重要性。"},{"id":2049,"unit":7,"lesson":2,"word":"mindset","pronunciation":"/ˈmaɪndset/","meaning":"n.观念模式;思维倾向","seq":54,"isStar":false,"memo":"构词 mind(头脑)+set(固定下来的状态)→头脑里固定成型的东西→观念模式，思维倾向","example":"Employees with a growth mindset may be more likely to devise innovative ideas.具有成长型思维模式的员工更可能提出创新想法。"},{"id":2050,"unit":7,"lesson":2,"word":"represent","pronunciation":"/ˌreprɪˈzent/","meaning":"v.代表;相当于;描述","seq":55,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + present(出席)→阿姨“代表”妈妈出席我的家长会。","example":"It represented our team. 这代表了我们团队。"},{"id":2051,"unit":7,"lesson":2,"word":"representation","pronunciation":"/ˌreprɪzenˈteɪʃ(ə)n/","meaning":"n.代理,代表;描绘,表现","seq":56,"isStar":false},{"id":2052,"unit":7,"lesson":2,"word":"representative","pronunciation":"/ˌreprɪˈzentətɪv/","meaning":"n.代表,代理人 adj.典型的","seq":57,"isStar":false},{"id":2053,"unit":7,"lesson":2,"word":"replace","pronunciation":"/rɪˈpleɪs/","meaning":"v.代替,取代;以……替换;更换","seq":58,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + place(位置)→阿姨在他的位置上，因为阿姨“取代”了他。","example":"It is hard for robots to replace humans in highly professional work. 在高度专业化的工作中，机器人很难取代人类。"},{"id":2054,"unit":7,"lesson":2,"word":"replacement","pronunciation":"/rɪˈpleɪsmənt/","meaning":"n.更换,替换;替代的人或物","seq":59,"isStar":false},{"id":2055,"unit":7,"lesson":2,"word":"irreplaceable","pronunciation":"/ˌɪrɪˈpleɪsəbl/","meaning":"adj.不可替代的,独一无二的","seq":60,"isStar":false},{"id":2056,"unit":7,"lesson":2,"word":"displace","pronunciation":"/dɪsˈpleɪs/","meaning":"v.取代,替代;移动,挪开;撤职,免职","seq":61,"isStar":false,"memo":"构词 dis-(离开) + place(位置)→离开原来的位置→取代","example":"Several chemicals have displaced the oxygen. 有几种化学物质取代了氧气。"},{"id":2057,"unit":7,"lesson":2,"word":"displacement","pronunciation":"/dɪsˈpleɪsmənt/","meaning":"n.取代,替代;移位;免职","seq":62,"isStar":false},{"id":2058,"unit":7,"lesson":2,"word":"servant","pronunciation":"/ˈsɜːvənt/","meaning":"n.仆人;(公司或机构的)雇员,职员","seq":63,"isStar":false,"memo":"构词 serv(e)(服务)+-ant(表示人的后缀)→服务的人→仆人;雇员","example":"A king's servant might not be the best one to write a biography of that king. 国王的仆人可能不是为国王写传记的最佳人选。"},{"id":2059,"unit":7,"lesson":2,"word":"observe","pronunciation":"/əbˈzɜːv/","meaning":"v.注意到;观察;遵守","seq":64,"isStar":false,"memo":"联想 ob-(表方向)+serve(服务)→为我服务,要朝着我的方向,“观察”我的需求,“遵守”我的要求。","example":"Some change has been observed in today's young people. 在当今的年轻人身上观察到了一些变化。"},{"id":2060,"unit":7,"lesson":2,"word":"observer","pronunciation":"/əbˈzɜːvə(r)/","meaning":"n.观察者;目击者","seq":65,"isStar":false},{"id":2061,"unit":7,"lesson":2,"word":"observation","pronunciation":"/ˌɒbzəˈveɪʃ(ə)n/","meaning":"n.观察;观测;监视;评论","seq":66,"isStar":false},{"id":2062,"unit":7,"lesson":2,"word":"observant","pronunciation":"/əbˈzɜːvənt/","meaning":"adj.善于观察的;观察力敏锐的","seq":67,"isStar":false},{"id":2063,"unit":7,"lesson":2,"word":"reserve","pronunciation":"/rɪˈzɜːv/","meaning":"n.储备(量)","seq":68,"isStar":false,"memo":"联想 re-(重复,再)+serve(服务)→你想重复接受服务,就需要再次“预订”服务。","example":"The law requires listed firms to reserve 40% of board seats for women. 这项法规要求,上市公司必须为女性保留40%的董事会席位。"},{"id":2064,"unit":7,"lesson":2,"word":"reserved","pronunciation":"/rɪˈzɜːvd/","meaning":"adj.内向的;矜持的","seq":69,"isStar":false},{"id":2065,"unit":7,"lesson":2,"word":"reservation","pronunciation":"/ˌrezəˈveɪʃn/","meaning":"n.预订,预约;保留意见","seq":70,"isStar":false},{"id":2066,"unit":7,"lesson":2,"word":"reservoir","pronunciation":"/ˈrezəvwɑː(r)/","meaning":"n.水库,蓄水池;储备","seq":71,"isStar":false,"memo":"谐音+联想：‘瑞瑟瓦’→水库像‘瑞气储蓄罐’，存住雨水，关键时刻‘哗’地释放好运（和水）！","example":"Drought has lowered water levels in the main reservoir supplying the metropolitan area. 干旱已导致供应大都市区的主要蓄水池水位下降。"},{"id":2067,"unit":7,"lesson":2,"word":"conserve","pronunciation":"/kənˈsɜːv/","meaning":"v.节约;保护;保存,保留","seq":72,"isStar":false,"memo":"联想 con-(一起)+serve(服务)→我邀请朋友一起来家里做客,我会为大家服务,并提前“保存”一些食物。","example":"What is said to be the best way to conserve energy nowadays? 现在节约能源最好的方法是什么?"},{"id":2068,"unit":7,"lesson":2,"word":"conservation","pronunciation":"/ˌkɒnsəˈveɪʃ(ə)n/","meaning":"n.保护;保存;节约","seq":73,"isStar":false},{"id":2069,"unit":7,"lesson":2,"word":"conservative","pronunciation":"/kənˈsɜːvətɪv/","meaning":"n.保守党党员","seq":74,"isStar":false,"memo":"构词 conserv(e)(保存)+-ative(后缀)→保存原样的→保守的","example":"The campaign struck terror into many local conservative parties. 这场运动让许多地方的保守党感到害怕。"},{"id":2070,"unit":7,"lesson":2,"word":"deserve","pronunciation":"/dɪˈzɜːv/","meaning":"v.值得;应得,应受","seq":75,"isStar":false,"memo":"联想 de(音似“弟”)+serve(服务)→弟弟觉得为家人服务是应该的→值得;应得","example":"He usually doesn't get the reward he deserves. 他通常得不到应有的奖励。"},{"id":2071,"unit":7,"lesson":2,"word":"preserve","pronunciation":"/prɪˈzɜːv/","meaning":"v.保护;保存 n.专门领域;果酱;腌菜","seq":76,"isStar":false,"memo":"联想 pre-(提前)+serve(服务)→为了服务好所有人,我要提前“保存”一些食物。","example":"The ham is covered in salt to dry and preserve it. 火腿上覆盖一层盐,晾干保存。"},{"id":2072,"unit":7,"lesson":2,"word":"preservation","pronunciation":"/ˌprezəˈveɪʃ(ə)n/","meaning":"n.保护;保存;保留;保持","seq":77,"isStar":false},{"id":2073,"unit":7,"lesson":2,"word":"preservative","pronunciation":"/prɪˈzɜːvətɪv/","meaning":"adj.保护的;保存的 n.防腐剂","seq":78,"isStar":false},{"id":2074,"unit":7,"lesson":2,"word":"partner","pronunciation":"/ˈpɑːtnə(r)/","meaning":"n.配偶;搭档;合伙人","seq":79,"isStar":false,"memo":"构词 part(部分)+-ner(表人)→与你分担一份的人→配偶；搭档；合伙人","example":"The man should meet his partner's needs.男人应该满足伴侣的需求。"},{"id":2075,"unit":7,"lesson":2,"word":"partnership","pronunciation":"/ˈpɑːtnəʃɪp/","meaning":"n.伙伴关系","seq":80,"isStar":false},{"id":2076,"unit":7,"lesson":2,"word":"mate","pronunciation":"/meɪt/","meaning":"n.朋友,伙伴;伴侣","seq":81,"isStar":false},{"id":2077,"unit":7,"lesson":2,"word":"estimate","pronunciation":"/ˈestɪmət; ˈestɪmeɪt/","meaning":"n.估计,估算;估价 v.估算,估计","seq":82,"isStar":false,"memo":"联想 est(联想 best)+i(我)+mate(伙伴)→我“估算”一下最好的伙伴有多少。","example":"Give an estimate of how long it will stay in space. 估计一下它将在太空中停留多久。"},{"id":2078,"unit":7,"lesson":2,"word":"estimation","pronunciation":"/ˌestɪˈmeɪʃn/","meaning":"n.估计;判断;评价","seq":83,"isStar":false},{"id":2079,"unit":7,"lesson":2,"word":"underestimate","pronunciation":"/ˌʌndərˈestɪmeɪt/","meaning":"n.低估;轻视 v.低估;轻视","seq":84,"isStar":false,"memo":"构词 under(在……下)+estimate(估计)→低估","example":"The influence of media violence has been underestimated. 媒体暴力的影响被低估了。"},{"id":2080,"unit":7,"lesson":3,"word":"flap","pronunciation":"/flæp/","meaning":"n.拍打,振(翅) v.拍击,摆动","seq":1,"isStar":false,"memo":"联想 f(联想“飞”) + la(音似“来”) + p(联想“拍”)→蝴蝶“拍打”着翅膀飞来了。","example":"With a flap of its wings, the bird was gone. 鸟振翅飞走了。"},{"id":2081,"unit":7,"lesson":3,"word":"flip","pronunciation":"/flɪp/","meaning":"v.使快速翻转;抛掷;浏览 n.轻掷","seq":2,"isStar":false,"memo":"联想 fl(联想 fly)+i(我)+p(联想“趴”) → 到家后，我飞快趴在桌子上“浏览”那本书。","example":"It is very important to just have a quick flip through.快速翻一翻非常重要。"},{"id":2082,"unit":7,"lesson":3,"word":"grip","pronunciation":"/ɡrɪp/","meaning":"n.紧握;影响力;理解 v.紧握","seq":3,"isStar":false,"memo":"联想 g(联想“哥”) + rip(撕)→哥哥要撕扯包装袋,首先得“紧握”包装袋。","example":"Bruce gripped the steering wheel hard. 布鲁斯紧紧地抓住方向盘。"},{"id":2083,"unit":7,"lesson":3,"word":"grope","pronunciation":"/ɡrəʊp/","meaning":"v.摸索;搜索 n.摸","seq":4,"isStar":false,"memo":"联想 g(联想“哥”) + rope(绳子)→哥哥晚上伸手够绳子,需要“摸索”一番。","example":"He groped around in the dark for his other sock. 他在黑暗中到处摸索着寻找另一只袜子。"},{"id":2084,"unit":7,"lesson":3,"word":"rope","pronunciation":"/rəʊp/","meaning":"n.粗绳;绳索 v.用绳子捆","seq":5,"isStar":false,"memo":"谐音 单词发音类似“肉铺”→肉铺会把肉一片片地用“绳索”穿起来挂着。","example":"His hands were tied together with rope. 他的手被绳子绑在一起。"},{"id":2085,"unit":7,"lesson":3,"word":"groan","pronunciation":"/ɡrəʊn/","meaning":"n.呻吟声;哼声 v.呻吟;抱怨,发牢骚","seq":6,"isStar":false,"memo":"谐音 单词发音类似“割肉嗯”→被割肉时会发出“嗯嗯”的“呻吟声”。","example":"Casey let out a groan of protest. 凯西哼了一声表示抗议。"},{"id":2086,"unit":7,"lesson":3,"word":"moan","pronunciation":"/məʊn/","meaning":"n.呻吟声;抱怨 v.呻吟;抱怨","seq":7,"isStar":false,"memo":"谐音 单词发音类似“哞(牛的叫声)”→呻吟声","example":"The money seemed to do little more than buy relief from the moans of their children. 金钱似乎只是缓解了他们的孩子们的抱怨。"},{"id":2087,"unit":7,"lesson":3,"word":"complain","pronunciation":"/kəmˈpleɪn/","meaning":"v.抱怨,埋怨;投诉","seq":8,"isStar":false,"memo":"联想 com-(所有) + plain(音似“扑累”)→所有人都扑过来,不停地“抱怨”累。","example":"They have been complaining of labor shortages for several years. 他们这些年一直在抱怨劳动力不足。"},{"id":2088,"unit":7,"lesson":3,"word":"complaint","pronunciation":"/kəmˈpleɪnt/","meaning":"n.抱怨;投诉","seq":9,"isStar":false},{"id":2089,"unit":7,"lesson":3,"word":"glance","pronunciation":"/ɡlɑːns/","meaning":"n.一瞥;扫视 v.瞥一眼;扫视;浏览","seq":10,"isStar":false,"memo":"单词发音类似“哥懒死”→哥哥很懒，无论让他看什么，他都是“一瞥”了事。","example":"She glanced at her watch. 她瞥了一眼表。"},{"id":2090,"unit":7,"lesson":3,"word":"peep","pronunciation":"/piːp/","meaning":"n.偷偷一瞥 v.窥视,偷看","seq":11,"isStar":false,"memo":"（联想）p（联想“趴”）+ cc（形似两只眼睛）+ p（联想“骗”）→他趴在门缝，瞪着两只眼睛“偷看”那个骗子。","example":"He was peeping at her through his fingers.他透过指缝偷看她。"},{"id":2091,"unit":7,"lesson":3,"word":"glitter","pronunciation":"/ˈɡlɪtə(r)/","meaning":"v.闪烁,闪光 n.闪烁,闪耀","seq":12,"isStar":false,"memo":"g(联想“哥”) + litter(垃圾)→哥哥看见垃圾就想进行分类,两眼“闪光”。","example":"There was a triumphant glitter in his eyes. 他的眼睛里闪烁着胜利的光芒。"},{"id":2092,"unit":7,"lesson":3,"word":"glittering","pronunciation":"/ˈɡlɪtərɪŋ/","meaning":"adj.辉煌的;闪闪发光的","seq":13,"isStar":false},{"id":2093,"unit":7,"lesson":3,"word":"litter","pronunciation":"/ˈlɪtə(r)/","meaning":"v.使凌乱;乱扔 n.垃圾;废弃物;杂物","seq":14,"isStar":false,"memo":"小的(little)垃圾(litter)也要分类。","example":"There will be fines for people who drop litter. 乱扔垃圾的人将被罚款。"},{"id":2094,"unit":7,"lesson":3,"word":"gaze","pronunciation":"/ɡeɪz/","meaning":"n.凝视,注视 v.盯着看,凝视","seq":15,"isStar":false,"memo":"谐音 “盖兹”：视线像盖子一样罩住对方不动→凝视，注视","example":"She felt increasingly uncomfortable under the woman's gaze. 在那位女士的注视下,她觉得愈发不自在了。"},{"id":2095,"unit":7,"lesson":3,"word":"blush","pronunciation":"/blʌʃ/","meaning":"n.脸红 v.(因难为情而)脸红","seq":16,"isStar":false,"memo":"他因为错拿了别人的刷子(brush)而脸红(blush)了。","example":"Poor Anne could only blush horribly. 可怜的安妮只能羞怯得满脸通红。"},{"id":2096,"unit":7,"lesson":3,"word":"flush","pronunciation":"/flʌʃ/","meaning":"n.脸红;潮红;冲(抽水马桶) v.发红","seq":17,"isStar":false,"memo":"单词发音类似“服了师”→他上课乱说话,被老师批评了一顿,服了老师,并且羞愧得“脸红”了。","example":"His face flushed as he came in after running all the way from school. 他从学校一路跑回来,脸都红了。"},{"id":2097,"unit":7,"lesson":3,"word":"splash","pronunciation":"/splæʃ/","meaning":"n.落水声","seq":18,"isStar":false,"memo":"电影 Splash 中美人鱼扑通一声跳进海里,海水飞溅→落水声;溅在……上","example":"We heard the splash when she fell into the pool. 当她掉入泳池时,我们听到了落水声。"},{"id":2098,"unit":7,"lesson":3,"word":"glare","pronunciation":"/ɡleə(r)/","meaning":"n.刺眼的强光;怒视 v.怒目而视","seq":19,"isStar":false,"memo":"[联想] g(联想“哥”) + la(联想“拉”) + re(字母音似“阿姨”) → 哥哥在街上拉住一个阿姨,阿姨“怒视”了他一下。","example":"He didn't shout: he just glared at me silently. 他没有喊叫,他只是默默地怒视着我。"},{"id":2099,"unit":7,"lesson":3,"word":"glimpse","pronunciation":"/ɡlɪmps/","meaning":"n.一瞥,飞快的一看","seq":20,"isStar":false,"memo":"[联想] gli(联想“哥立”) + m(联想“美”) + p(联想“瞥”) + se(联想“涩”) → 哥哥站立在美女旁边,羞涩地“一瞥”。","example":"She glimpsed a group of people standing on the bank of a river. 她瞥见一群人站在河岸上。"},{"id":2100,"unit":7,"lesson":3,"word":"stare","pronunciation":"/steə(r)/","meaning":"n.&v.盯着看;凝视;注视","seq":21,"isStar":false,"memo":"[联想] st(联想 street) + a(一) + re(字母音似“阿姨”) → 她在街上盯着一个阿姨看 → 盯着看","example":"She gave him a long, cold stare. 她冷冷地盯着他看了很久。"},{"id":2101,"unit":7,"lesson":3,"word":"reckon","pronunciation":"/ˈrekən/","meaning":"v.估算,计算;想,认为","seq":22,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+ck(联想“CK品牌”)+on→阿姨在“估算”CK的这件衣服值多少钱。","example":"They reckon that their profits are down by at least 20%. 他们估算利润至少下降了20%。"},{"id":2102,"unit":7,"lesson":3,"word":"reckless","pronunciation":"/ˈrekləs/","meaning":"adj.鲁莽的,不顾后果的,轻率的","seq":23,"isStar":false,"memo":"对照 没有(less表否定)估算(reckon)的行动通常是鲁莽的(reckless)。","example":"Reckless development are plotting against the rainforest. 不顾后果的开发正在图谋破坏雨林。"},{"id":2103,"unit":7,"lesson":3,"word":"intimate","pronunciation":"/ˈɪntɪmət/","meaning":"adj.亲密的,亲近的 n.知己","seq":24,"isStar":false,"memo":"联想 in(内部)+ti(联想“提”)+mate(伙伴)→常在内心提到的伙伴,是最“亲密的”人。","example":"A face-to-face communication is the most intimate. 面对面的交流是最亲密的。"},{"id":2104,"unit":7,"lesson":3,"word":"intimacy","pronunciation":"/ˈɪntɪməsi/","meaning":"n.亲密;密切","seq":25,"isStar":false},{"id":2105,"unit":7,"lesson":3,"word":"inmate","pronunciation":"/ˈɪnmeɪt/","meaning":"n.(监狱或精神病院等的)同住者","seq":26,"isStar":false,"memo":"构词 in(在……里面) + mate(伙伴) → 在某个特定范围里面的伙伴 → 同住者；同狱犯人","example":"He was attacked by a fellow inmate.他被一名狱友袭击了。"},{"id":2106,"unit":7,"lesson":3,"word":"approximate","pronunciation":"/əˈprɒksɪmət/","meaning":"adj.大约的,近似的 v.近似,接近","seq":27,"isStar":false,"memo":"[联想] ap-(一再地)+pro(联想前缀 pro-,往前)+xi(联想“西”)+mate(伙伴)→如果他一直往西行,大约就能找到他的伙伴→大约的","example":"The total cost will approximate £ 15 billions. 总费用接近150亿英镑。"},{"id":2107,"unit":7,"lesson":3,"word":"approximately","pronunciation":"/əˈprɒksɪmətli/","meaning":"adv.大概,大约","seq":28,"isStar":false},{"id":2108,"unit":7,"lesson":3,"word":"approximation","pronunciation":"/əˌprɒksɪˈmeɪʃn/","meaning":"n.近似值;粗略估算;类似事物","seq":29,"isStar":false},{"id":2109,"unit":7,"lesson":3,"word":"proximity","pronunciation":"/prɒkˈsɪməti/","meaning":"n.(时间或空间)接近,邻近,靠近","seq":30,"isStar":false,"memo":"[联想] pro-(往前)+xi(联想“西”)+mi(联想“米”)+-ty(名词后缀)→他往西前行数百米就能“接近”目的地。","example":"The area has many schools in close proximity to each other. 这个地区有许多学校比邻而立。"},{"id":2110,"unit":7,"lesson":3,"word":"proximate","pronunciation":"/ˈprɒksɪmət/","meaning":"adj.(时间、顺序等)最接近的","seq":31,"isStar":false},{"id":2111,"unit":7,"lesson":3,"word":"ultimate","pronunciation":"/ˈʌltɪmət/","meaning":"n.最好的事物,极品","seq":32,"isStar":false,"memo":"[联想] ulti-(最后)+mate(伙伴)→留到“最后的”伙伴,一定是最好的。","example":"We will accept ultimate responsibility for whatever happens. 无论发生什么,我们都会承担最终的责任。"},{"id":2112,"unit":7,"lesson":3,"word":"ultimately","pronunciation":"/ˈʌltɪmətli/","meaning":"adv.最终;最后;根本上","seq":33,"isStar":false},{"id":2113,"unit":7,"lesson":3,"word":"imitate","pronunciation":"/ˈɪmɪteɪt/","meaning":"v.模仿,仿效","seq":34,"isStar":false,"memo":"[联想] i(我)+m(联想“门”)+it(它)+ate(eat 的过去式)→我在门口“模仿”它(小狗)吃东西。","example":"Computers can imitate life. 计算机可以模拟生活。"},{"id":2114,"unit":7,"lesson":3,"word":"imitation","pronunciation":"/ˌɪmɪˈteɪʃn/","meaning":"n.模仿;仿制品","seq":35,"isStar":false},{"id":2115,"unit":7,"lesson":3,"word":"imitative","pronunciation":"/ˈɪmɪtətɪv/","meaning":"adj.模仿的;仿制的","seq":36,"isStar":false},{"id":2116,"unit":7,"lesson":3,"word":"simulate","pronunciation":"/ˈsɪmjuleɪt/","meaning":"v.假装,装作;模仿;模拟","seq":37,"isStar":false,"memo":"[联想] simu(联想“四目”)+late(迟到)→他“假装”有四只眼睛,能抓住从各个方向跑来的迟到者。","example":"I tried to simulate surprise at the news. 听到这个消息后,我竭力装出一副吃惊的样子。"},{"id":2117,"unit":7,"lesson":3,"word":"simulation","pronunciation":"/ˌsɪmjuˈleɪʃ(ə)n/","meaning":"n.模拟;假装;冒充","seq":38,"isStar":false},{"id":2118,"unit":7,"lesson":3,"word":"stimulate","pronunciation":"/ˈstɪmjuleɪt/","meaning":"v.促进;激发,激励;刺激","seq":39,"isStar":false,"memo":"[对照] 同桌一个劲地模仿(simulate)他,他就受刺激(stimulate)了。","example":"A person who is unable to stimulate his curiosity may appear somewhat boring. 一个人如果不能激发自己的好奇心,那么他可能就会显得有些无聊。"},{"id":2119,"unit":7,"lesson":3,"word":"simultaneous","pronunciation":"/ˌsɪm(ə)lˈteɪniəs/","meaning":"adj.同时发生(或进行)的,同步的","seq":40,"isStar":false,"memo":"[联想] simul(音似“四目”)+ta(联想“他”)+ne(音似“你”)+-ous(形容词后缀)→他和你四目相对,同时行动→同时发生的","example":"With simultaneous interpreting, you start translating almost as soon as the other person starts speaking. 对于同声传译来说,你几乎需要在另一个人开始讲话时就开始翻译。"},{"id":2120,"unit":7,"lesson":3,"word":"simultaneously","pronunciation":"/ˌsɪm(ə)lˈteɪniəsli/","meaning":"adv.同时发生(或进行)地;同步地","seq":41,"isStar":false},{"id":2121,"unit":7,"lesson":3,"word":"scan","pronunciation":"/skæn/","meaning":"n.扫描检查;浏览 v.细看,审视;浏览","seq":42,"isStar":false,"memo":"[谐音] 单词发音类似“死看” → 当你死死盯着一个人看的时候,你就是在“细看”。","example":"We quickly scanned the menu. 我们快速浏览了一下菜单。"},{"id":2122,"unit":7,"lesson":3,"word":"scanner","pronunciation":"/ˈskænə(r)/","meaning":"n.扫描仪","seq":43,"isStar":false},{"id":2123,"unit":7,"lesson":3,"word":"scandal","pronunciation":"/ˈskænd(ə)l/","meaning":"n.丑行,丑闻,可耻的行为","seq":44,"isStar":false,"memo":"[谐音] 单词发音类似“死看都” → 所有人都死死地盯着他看,因为他有一桩“丑闻”。","example":"The scandal will soon blow over. 丑闻很快就会烟消云散的。"},{"id":2124,"unit":7,"lesson":3,"word":"scandalous","pronunciation":"/ˈskændələs/","meaning":"adj.可耻的;不可原谅的","seq":45,"isStar":false},{"id":2125,"unit":7,"lesson":3,"word":"dazzle","pronunciation":"/ˈdæz(ə)l/","meaning":"n.耀眼眩目 v.使目眩,使眼花","seq":46,"isStar":false,"memo":"[谐音] 单词发音类似“带走” → 这颗钻石“耀眼眩目”,大家都想带走它。","example":"I was dazzled by the car's headlights. 我被汽车前灯照得眼花。"},{"id":2126,"unit":7,"lesson":3,"word":"dazzling","pronunciation":"/ˈdæz(ə)lɪŋ/","meaning":"adj.炫目的;令人眼花缭乱的","seq":47,"isStar":false},{"id":2127,"unit":7,"lesson":3,"word":"scratch","pronunciation":"/skrætʃ/","meaning":"n.划痕;刮(或擦、抓)的刺耳声","seq":48,"isStar":false,"memo":"联想 sc(音似“四个”)+rat(老鼠)+ch(音似“吃”)→四个(只)老鼠吃东西时边“挠”边吃。","example":"He scratched his head. 他时不时地挠挠头。"},{"id":2128,"unit":7,"lesson":3,"word":"scrape","pronunciation":"/skreɪp/","meaning":"n.刮,铲;刮擦声;擦伤,擦痕 v.刮掉","seq":49,"isStar":false,"memo":"联想 sc(音似“四个”)+rape(联想reap“收割”)→这四个人用镰刀收割庄稼,很容易“擦伤”。","example":"We tried to scrape the paper off all four walls. 我们试图把纸从四面墙上刮下来了。"},{"id":2129,"unit":7,"lesson":3,"word":"scrap","pronunciation":"/skræp/","meaning":"n.碎片;一点点;废品,废弃材料","seq":50,"isStar":false,"memo":"联想 与 scrape(刮)同源：刮下来的小片→碎片，一点点，废品；放弃，报废","example":"Waterbirds can get cut by scrap metal. 水鸟可能会被废金属割伤。"},{"id":2130,"unit":7,"lesson":3,"word":"scrub","pronunciation":"/skrʌb/","meaning":"v.擦洗;刷洗 n.擦洗;刷洗;灌木丛","seq":51,"isStar":false,"memo":"联想 与 scrape(刮擦)同源：来回使劲擦→擦洗，刷洗；也指灌木丛","example":"I found him in the kitchen, scrubbing the floor.我在厨房里发现他在擦地板。"},{"id":2131,"unit":7,"lesson":3,"word":"democratic","pronunciation":"/ˌdeməˈkrætɪk/","meaning":"adj.民主的,民主政体的;民主制的","seq":52,"isStar":false,"memo":"联想 democ(音似“戴帽可”)+rat(老鼠)+ic(联想“IC卡”)→戴帽子的老鼠可以坐公交车并刷IC卡,这真是个“民主的”社会。","example":"Education is the basis of a democratic society. 教育是民主社会的基础。"},{"id":2132,"unit":7,"lesson":3,"word":"democrat","pronunciation":"/ˈdeməkræt/","meaning":"n.(美国)民主党党员,民主党人","seq":53,"isStar":false,"memo":"构词 demo(人民，同 democracy 民主)+crat(统治)→主张由人民掌权的人→民主支持者，民主党人","example":"He has been a democrat all his life. 他终生都是一个民主主义者。"},{"id":2133,"unit":7,"lesson":3,"word":"democracy","pronunciation":"/dɪˈmɒkrəsi/","meaning":"n.民主;民主政体;民主制度","seq":54,"isStar":false,"memo":"构词 demo(人民)+cracy(统治)→人民掌权的制度→民主，民主政体，民主制度","example":"The government will uphold the principles of democracy. 政府将坚持民主的原则。"},{"id":2134,"unit":7,"lesson":3,"word":"category","pronunciation":"/ˈkætəɡəri/","meaning":"n.种类,范畴","seq":55,"isStar":false,"memo":"联想 cat(猫)+e(联想“鹅”)+g(联想“鸽”)+ory(名词后缀)→猫、鹅、鸽子属于不同的动物“种类”。","example":"He competed in the youngest age category. 他参加了最小年龄组的比赛。"},{"id":2135,"unit":7,"lesson":3,"word":"cater","pronunciation":"/ˈkeɪtə(r)/","meaning":"v.提供饮食;满足,迎合","seq":56,"isStar":false,"memo":"联想 cat(猫)+er(表示人的后缀)→有些人像猫一样喜欢“迎合”别人。","example":"They only publish novels which cater to the mass market. 他们只出版迎合大众市场的小说。"},{"id":2136,"unit":7,"lesson":3,"word":"delicate","pronunciation":"/ˈdelɪkət/","meaning":"adj.易碎的,脆弱的;精巧的,精致的","seq":57,"isStar":false,"memo":"联想 deli(联想“得力”,文具品牌)+cat(e)(猫)→得力文具上刻有一只“精致的”猫。","example":"Most of them are extremely delicate. 它们大多数都特别脆弱。"},{"id":2137,"unit":7,"lesson":3,"word":"dedicate","pronunciation":"/ˈdedɪkeɪt/","meaning":"v.致力于,献身于;献给","seq":58,"isStar":false,"memo":"联想 dedi(音似 daddy)+cate(音似“剋他”)→坏人欺负他了,爸爸就去剋(打)坏人,爸爸总是“致力于”保护他。","example":"They have dedicated their lives to protecting the environment. 他们为保护环境而奉献自己的一生。"},{"id":2138,"unit":7,"lesson":3,"word":"dedication","pronunciation":"/ˌdedɪˈkeɪʃ(ə)n/","meaning":"n.热忱,奉献","seq":59,"isStar":false},{"id":2139,"unit":7,"lesson":3,"word":"catalog(ue)","pronunciation":"/ˈkætəlɒɡ/","meaning":"n.目录 v.列入目录,编目录","seq":60,"isStar":false,"memo":"构词 cata-(向下)+log(列举，同 logic 逻辑)→把条目一条条列下来→目录","example":"Look at this catalogue.看看这份目录。"},{"id":2140,"unit":7,"lesson":3,"word":"index","pronunciation":"/ˈɪndeks/","meaning":"n.索引;卡片目录;指数,标志","seq":61,"isStar":false,"memo":"联想 in(在……里面)+dex(音似“德克士”)→他在德克士里看到菜单上有“索引”和卡路里“指标”。","example":"Body mass index may be related to wages and income. 体重指数可能与工资和收入有关。"},{"id":2141,"unit":7,"lesson":3,"word":"appetite","pronunciation":"/ˈæpɪtaɪt/","meaning":"n.胃口;爱好","seq":62,"isStar":false,"memo":"联想 ap-(一再地)+pet(宠物)+-ite(后缀)→他一再地提到家里的宠物,说明很喜爱它→爱好","example":"Our short-term memory may play a role in appetite. 我们的短期记忆可能会影响胃口。"},{"id":2142,"unit":7,"lesson":3,"word":"petition","pronunciation":"/pəˈtɪʃn/","meaning":"n.请愿(书);正式请求,祈诉 v.祈求","seq":63,"isStar":false,"memo":"联想 pet(宠物)+it(它)+-ion(后缀)→宠物通常会“祈求”人们喜爱它。","example":"I signed a petition against experiments on animals. 我在一份反对用动物做实验的请愿书上签了名。"},{"id":2143,"unit":7,"lesson":4,"word":"frustrate","pronunciation":"/frʌˈstreɪt/","meaning":"v.使懊恼;使沮丧;使挫败;阻止","seq":1,"isStar":false,"memo":"联想 fru(联想“妇孺”)+st(联想 street)+rat(e)(老鼠)→一群妇孺在街上追老鼠,追不上时感觉很沮丧→使沮丧","example":"The rescue attempt was frustrated by bad weather. 营救行动因天气恶劣受阻。"},{"id":2144,"unit":7,"lesson":4,"word":"frustrating","pronunciation":"/frʌˈstreɪtɪŋ/","meaning":"adj.令人懊恼的;令人沮丧的","seq":2,"isStar":false},{"id":2145,"unit":7,"lesson":4,"word":"frustration","pronunciation":"/frʌˈstreɪʃ(ə)n/","meaning":"n.懊恼;沮丧;挫败","seq":3,"isStar":false},{"id":2146,"unit":7,"lesson":4,"word":"accomplish","pronunciation":"/əˈkʌmplɪʃ/","meaning":"v.完成;实现(尤指通过努力)","seq":4,"isStar":false,"memo":"联想 ac-(表强调)+complish(音似“看破历史”)→一再地看破历史的时候,人生就算圆满了→完成;实现","example":"Curiosity is one of the tools humans have found to accomplish that gigantic task. 好奇心是人类发现的完成那一庞大工作的工具之一。"},{"id":2147,"unit":7,"lesson":4,"word":"accomplishment","pronunciation":"/əˈkʌmplɪʃmənt/","meaning":"n.成就,成绩","seq":5,"isStar":false},{"id":2148,"unit":7,"lesson":4,"word":"achieve","pronunciation":"/əˈtʃiːv/","meaning":"v.(凭长期努力)达到","seq":6,"isStar":false,"memo":"a-(到) + chieve(= chief 首领,头)→到头的位置→达到;成功","example":"Technologies like this have helped achieve a 31% drop in vehicle-related crime. 此类技术已经帮助将与车辆相关的犯罪率下降了31%。"},{"id":2149,"unit":7,"lesson":4,"word":"achievement","pronunciation":"/əˈtʃiːvmənt/","meaning":"n.成就;完成","seq":7,"isStar":false},{"id":2150,"unit":7,"lesson":4,"word":"fulfil(l)","pronunciation":"/fʊlˈfɪl/","meaning":"v.实现;履行,执行","seq":8,"isStar":false,"memo":"[记] (联想) ful(联想full) + fill(装满)→都装满了→实现","example":"They have many responsibilities to fulfil at work.他们在工作中有许多责任要履行。"},{"id":2151,"unit":7,"lesson":4,"word":"fulfil(l)ment","pronunciation":"/fʊlˈfɪlmənt/","meaning":"n.满足感;实现","seq":9,"isStar":false,"memo":"构词 fulfil(履行，实现)+-ment(名词后缀)→目标实现后的状态→满足感；实现","example":"The job gives her a real sense of fulfilment. 这份工作给她带来真正的满足感。"},{"id":2152,"unit":7,"lesson":4,"word":"victory","pronunciation":"/ˈvɪktəri/","meaning":"n.胜利,成功","seq":10,"isStar":false,"memo":"vict(征服) + -ory(名词后缀)→胜利,成功","example":"The ruling is a victory for big chains with a presence in many states. 那项裁决对于在许多州都有实体店的大型连锁店来说是一次胜利。"},{"id":2153,"unit":7,"lesson":4,"word":"victorious","pronunciation":"/vɪkˈtɔːriəs/","meaning":"adj.胜利的;获胜的","seq":11,"isStar":false},{"id":2154,"unit":7,"lesson":4,"word":"triumph","pronunciation":"/ˈtraɪʌmf/","meaning":"n.胜利;喜悦 v.打败,战胜,成功","seq":12,"isStar":false,"memo":"单词发音类似“川姆屠”→他用实力“战胜”川姆,川姆输得心服口服。","example":"As is usual in this kind of movie, good triumphs over evil in the end. 像这类电影的一贯结局一样,善良最终战胜了邪恶。"},{"id":2155,"unit":7,"lesson":4,"word":"triumphant","pronunciation":"/traɪˈʌmfənt/","meaning":"adj.欢欣鼓舞的,耀武扬威的","seq":13,"isStar":false},{"id":2156,"unit":7,"lesson":4,"word":"tournament","pronunciation":"/ˈtʊənəmənt/","meaning":"n.锦标赛;联赛","seq":14,"isStar":false,"memo":"[记] (联想) tour(旅游) + nament(联想“拿门她”)→她知道自己拿不到这次“锦标赛”的门票,于是她就去旅游了。","example":"The BBC will cover all the major games of the tournament.英国广播公司将报道锦标赛的所有重大比赛。"},{"id":2157,"unit":7,"lesson":4,"word":"champion","pronunciation":"/ˈtʃæmpiən/","meaning":"n.冠军;第一名;优胜者","seq":15,"isStar":false,"memo":"构词 camp(战场，同 campaign 战役)+-ion(表人)→在战场上胜出的那个人→冠军，第一名，优胜者","example":"She is a former Olympic skating champion. 她是前奥运会滑冰冠军。"},{"id":2158,"unit":7,"lesson":4,"word":"championship","pronunciation":"/ˈtʃæmpiənʃɪp/","meaning":"n.锦标赛;冠军地位","seq":16,"isStar":false},{"id":2159,"unit":7,"lesson":4,"word":"feat","pronunciation":"/fiːt/","meaning":"n.业绩,功绩;壮举","seq":17,"isStar":false,"memo":"[记] (谐音) 单词发音类似“菲特”→巴菲特是一个举世闻名的投资者,其“功绩”卓著。","example":"The tunnel is a remarkable feat of engineering.这条隧道是一项了不起的工程壮举。"},{"id":2160,"unit":7,"lesson":4,"word":"defeat","pronunciation":"/dɪˈfiːt/","meaning":"n.失败;战胜,击败 v.打败,战胜","seq":18,"isStar":false,"memo":"de(音似“弟”) + feat(功绩)→弟弟的功绩是“打败”了他。","example":"The use of the Internet isn’t the only way to defeat poverty. 使用互联网并不是战胜贫困的唯一方法。"},{"id":2161,"unit":7,"lesson":4,"word":"punch","pronunciation":"/pʌntʃ/","meaning":"n.重拳击打;打孔机 v.用拳猛击","seq":19,"isStar":false,"memo":"单词发音类似“重拳击打”在很软的东西上发出的声音“乓”。","example":"She landed a punch on his chin. 她一拳打在了他的下巴上。"},{"id":2162,"unit":7,"lesson":4,"word":"technique","pronunciation":"/tekˈniːk/","meaning":"n.技术;技巧;技艺;工艺","seq":20,"isStar":false,"memo":"单词发音类似“泰克尼克”→泰克认为泰坦尼克号出事故的原因之一可能是“技术”有问题。","example":"The pianist has excellent technique. 这位钢琴家技巧精湛。"},{"id":2163,"unit":7,"lesson":4,"word":"technical","pronunciation":"/ˈteknɪk(ə)l/","meaning":"adj.技术的;技巧的;工艺的","seq":21,"isStar":false,"memo":"对照 technique n.技术;技巧;工艺→ technical adj.","example":"All the technical problems can be solved. 所有的技术问题都能得到解决。"},{"id":2164,"unit":7,"lesson":4,"word":"technician","pronunciation":"/tekˈnɪʃ(ə)n/","meaning":"n.技术员;技师","seq":22,"isStar":false},{"id":2165,"unit":7,"lesson":4,"word":"craft","pronunciation":"/krɑːft/","meaning":"n.手艺;工艺 v.精心制作","seq":23,"isStar":false,"memo":"对照 工艺(craft)决定了航空器(aircraft)在空(air)中的飞行安全。","example":"Children often sell candy and crafts in the streets. 孩子们经常在街上卖糖果和工艺品。"},{"id":2166,"unit":7,"lesson":4,"word":"handicraft","pronunciation":"/ˈhændikrɑːft/","meaning":"n.手工艺;手工艺品","seq":24,"isStar":false,"memo":"对照 手工艺(handicraft)指以手(hand)工劳动进行制作的工艺(craft)。","example":"Her job involves buying handicrafts from all over the world. 她的工作包括从世界各地购买手工艺品。"},{"id":2167,"unit":7,"lesson":4,"word":"artifact","pronunciation":"/ˈɑːtɪfækt/","meaning":"n.人工制品,手工艺品","seq":25,"isStar":false,"memo":"构词 art(i)(艺术；技艺) + fact(做) → 凭借技艺做出来的东西 → 手工艺品","example":"This ancient artifact was discovered in a tomb.这件古代文物是在一座古墓中发现的。"},{"id":2168,"unit":7,"lesson":4,"word":"jet","pronunciation":"/dʒet/","meaning":"n.喷气式飞机;喷嘴","seq":26,"isStar":false,"memo":"谐音 单词发音类似“截他”→我们开着“喷气式飞机”去拦截他。","example":"The giant jet will be forced to land. 这架巨型喷气式飞机将被迫降落。"},{"id":2169,"unit":7,"lesson":4,"word":"jerk","pronunciation":"/dʒɜːk/","meaning":"v.&n.急拉;猛推;猝然一动","seq":27,"isStar":false,"memo":"谐音 单词发音类似“杰克”→电影《泰坦尼克号》中的船进水时,男主人公杰克赶忙把露丝拉到自己身边→急拉","example":"She sat up with a jerk. 她猛地坐了起来。"},{"id":2170,"unit":7,"lesson":4,"word":"aviation","pronunciation":"/ˌeɪviˈeɪʃ(ə)n/","meaning":"n.航空(学);飞机制造业","seq":28,"isStar":false,"memo":"联想 a(-)+vi(形似罗马数字6)+-ation(名词后缀)→他研究“航空学”,一天进行6次测试。","example":"It uses the latest aviation technology. 它采用最新的航空技术。"},{"id":2171,"unit":7,"lesson":4,"word":"preside","pronunciation":"/prɪˈzaɪd/","meaning":"v.主持(会议、仪式等)","seq":29,"isStar":false,"memo":"对照 president n.总统；国家主席；会长→ preside v.","example":"Although it was his first experience as chairman, he presided over the meeting with great skill. 虽然这是他第一次担任主席，但他熟练地主持了会议。"},{"id":2172,"unit":7,"lesson":4,"word":"president","pronunciation":"/ˈprezɪdənt/","meaning":"n.总统;国家主席;会长;总裁","seq":30,"isStar":false},{"id":2173,"unit":7,"lesson":4,"word":"presidential","pronunciation":"/ˌprezɪˈdenʃl/","meaning":"adj.总统的;国家主席的","seq":31,"isStar":false},{"id":2174,"unit":7,"lesson":4,"word":"presidency","pronunciation":"/ˈprezɪdənsi/","meaning":"n.总统(或主席)的职位;任期","seq":32,"isStar":false},{"id":2175,"unit":7,"lesson":4,"word":"reside","pronunciation":"/rɪˈzaɪd/","meaning":"v.居住,定居","seq":33,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + side(面) → 阿姨“居住”在马路对面。","example":"I reside at the end of the street. 我住在这条街的尽头。"},{"id":2176,"unit":7,"lesson":4,"word":"resident","pronunciation":"/ˈrezɪdənt/","meaning":"n.居民;住户 adj.居住的,居留的","seq":34,"isStar":false},{"id":2177,"unit":7,"lesson":4,"word":"residential","pronunciation":"/ˌrezɪˈdenʃ(ə)l/","meaning":"adj.住宅的","seq":35,"isStar":false},{"id":2178,"unit":7,"lesson":4,"word":"residence","pronunciation":"/ˈrezɪdəns/","meaning":"n.住所;居住;定居;(在他国的)居住权","seq":36,"isStar":false,"memo":"构词 reside(居住) + -(e)nce(名词后缀) → 住所；居住","example":"Please state your occupation and place of residence. 请说明你的职业和住所。"},{"id":2179,"unit":7,"lesson":4,"word":"dwell","pronunciation":"/dwel/","meaning":"v.定居;居住;(~on)老是想着(详述","seq":37,"isStar":false,"memo":"联想 d(联想“定”) + well(很好地) → 很好地安定了下来 → 定居；居住","example":"He dwelt in a cottage on the hillside. 他住在山坡上的一座农舍里。"},{"id":2180,"unit":7,"lesson":4,"word":"dweller","pronunciation":"/ˈdwelə(r)/","meaning":"n.居民,居住者","seq":38,"isStar":false},{"id":2181,"unit":7,"lesson":4,"word":"dwelling","pronunciation":"/ˈdwelɪŋ/","meaning":"n.住宅,住所","seq":39,"isStar":false},{"id":2182,"unit":7,"lesson":4,"word":"inhabit","pronunciation":"/ɪnˈhæbɪt/","meaning":"v.居住在……;栖居于……","seq":40,"isStar":false,"memo":"联想 in(在里面) + habit(习惯) → 在家里面住得习惯了 → 居住在……","example":"Many old houses are not inhabited. 许多老房子无人居住。"},{"id":2183,"unit":7,"lesson":4,"word":"inhabitant","pronunciation":"/ɪnˈhæbɪtənt/","meaning":"n.居民,居住者","seq":41,"isStar":false},{"id":2184,"unit":7,"lesson":4,"word":"habitat","pronunciation":"/ˈhæbɪtæt/","meaning":"n.(动植物的)生活环境","seq":42,"isStar":false,"memo":"habitat ≈ ‘哈！比它（住）’→动物喊‘哈！这地儿比它适合我住！’指生物‘户口所在地’。","example":"Deforestation threatens the natural habitat of endangered primates. 森林砍伐威胁着濒危灵长类动物的自然栖息地。"},{"id":2185,"unit":7,"lesson":4,"word":"settle","pronunciation":"/ˈset(ə)l/","meaning":"v.安顿,定居;解决","seq":43,"isStar":false,"memo":"联想 set(t)(放置)+le(联想“了”)→把自己放下来了,不再漂泊,就是“定居”;把问题放下来了,就是把问题给“解决”。","example":"It's time you settled your differences with your father. 现在你该解决同你父亲之间的分歧了。"},{"id":2186,"unit":7,"lesson":4,"word":"settlement","pronunciation":"/ˈset(ə)lmənt/","meaning":"n.解决,处理;协议","seq":44,"isStar":false},{"id":2187,"unit":7,"lesson":4,"word":"address","pronunciation":"/əˈdres/","meaning":"n.住址;演讲 v.演说;解决,处理","seq":45,"isStar":false,"memo":"联想 ad-(一再地)+dress(裙子)→她一再地在网上买裙子,需要填写邮寄“地址”。","example":"He will give an address to the nation. 他将向全国发表演讲。"},{"id":2188,"unit":7,"lesson":4,"word":"tackle","pronunciation":"/ˈtæk(ə)l/","meaning":"v.应付,解决(难题或局面)","seq":46,"isStar":false,"memo":"谐音 单词发音类似“太抠”→“应付”那个太抠门的人很难。","example":"Nobody is willing to sacrifice their own interests to tackle the problem. 没有人愿意牺牲自己的利益来解决这个问题。"},{"id":2189,"unit":7,"lesson":4,"word":"cope","pronunciation":"/kəʊp/","meaning":"v.应付,处理","seq":47,"isStar":false,"memo":"谐音 单词发音类似“抠破”→伤口被抠破了,得“处理”一下。","example":"They are able to cope with the global climate change. 他们能够应对全球气候变化。"},{"id":2190,"unit":7,"lesson":4,"word":"solve","pronunciation":"/sɒlv/","meaning":"v.解决,处理","seq":48,"isStar":false,"memo":"构词 solv(松开，同 solution 解决办法)+-e→把结解开→解决，处理","example":"Attempts are being made to solve the problem of waste disposal. 正在想办法解决废物处理的问题。"},{"id":2191,"unit":7,"lesson":4,"word":"solution","pronunciation":"/səˈluːʃ(ə)n/","meaning":"n.解决办法;处理手段;答案;溶液","seq":49,"isStar":false},{"id":2192,"unit":7,"lesson":4,"word":"solvent","pronunciation":"/ˈsɒlvənt/","meaning":"n.溶剂 adj.可溶解的;有偿付能力的","seq":50,"isStar":false},{"id":2193,"unit":7,"lesson":4,"word":"resolve","pronunciation":"/rɪˈzɒlv/","meaning":"n.决心 v.解决(问题或困难);下决心","seq":51,"isStar":false,"memo":"构词 re-(表加强)+solve(解决)→必须解决→解决;下决心","example":"Different people resolve conflicts in different ways. 不同的人用不同的方式解决冲突。"},{"id":2194,"unit":7,"lesson":4,"word":"resolution","pronunciation":"/ˌrezəˈluːʃ(ə)n/","meaning":"n.决心;解决","seq":52,"isStar":false},{"id":2195,"unit":7,"lesson":4,"word":"resolute","pronunciation":"/ˈrezəluːt/","meaning":"adj.坚决的;有决心的","seq":53,"isStar":false},{"id":2196,"unit":7,"lesson":4,"word":"dissolve","pronunciation":"/dɪˈzɒlv/","meaning":"v.(使)溶解;解除;(使)消失","seq":54,"isStar":false,"memo":"构词 dis-(=away)+solve(解决)→解决掉→(使)溶解;解除","example":"Sugar dissolves in water. 糖溶解于水。"},{"id":2197,"unit":7,"lesson":4,"word":"soluble","pronunciation":"/ˈsɒljəb(ə)l/","meaning":"adj.可溶的,易溶解的;可解决的","seq":55,"isStar":false,"memo":"构词 solu(=solve,解决)+-ble(形容词后缀)→可解决的","example":"Vitamin C is water soluble. 维生素C可溶于水。"},{"id":2198,"unit":7,"lesson":4,"word":"trace","pronunciation":"/treɪs/","meaning":"n.踪迹,痕迹;遗迹 v.追溯","seq":56,"isStar":false,"memo":"联想 t(联想“他”)+race(比赛)→我和他比赛查找钱包的“踪迹”,最终“找到”了。","example":"It's exciting for him to discover traces of his missing dog. 当他发现走失的狗的踪迹时,他很兴奋。"},{"id":2199,"unit":7,"lesson":4,"word":"track","pronunciation":"/træk/","meaning":"n.足迹;小道;轨道;跑道 v.追踪","seq":57,"isStar":false,"memo":"谐音 单词发音类似“踹开”→他把玩具小火车从“轨道”上开了。","example":"We followed the track through the forest. 我们沿着林间小道前行。"},{"id":2200,"unit":7,"lesson":4,"word":"rail","pronunciation":"/reɪl/","meaning":"n.栏杆;铁轨,轨道,铁路","seq":58,"isStar":false,"memo":"对照 railway station 火车站→rail n.","example":"We crossed the rail track. 我们穿过了铁轨轨道。"},{"id":2201,"unit":7,"lesson":4,"word":"trail","pronunciation":"/treɪl/","meaning":"n.踪迹,痕迹;(乡间的)小路 v.跟踪","seq":59,"isStar":false,"memo":"联想 t(联想“他”)+rail(铁轨)→他沿着铁轨走,留下了“踪迹”。","example":"The police trailed Dale for days. 警方跟踪了戴尔多日。"},{"id":2202,"unit":7,"lesson":4,"word":"trailer","pronunciation":"/ˈtreɪlə(r)/","meaning":"n.拖车;活动房屋","seq":60,"isStar":false},{"id":2203,"unit":7,"lesson":4,"word":"derail","pronunciation":"/diːˈreɪl/","meaning":"v.(使)脱轨,出轨;阻挠,破坏","seq":61,"isStar":false,"memo":"构词 de-(分开)+rail(轨道)→不在铁轨上了→脱轨","example":"Policymakers should not allow low energy prices to derail the clean energy transition. 政策制定者们不应让较低的能源价格破坏清洁能源的转型。"},{"id":2204,"unit":7,"lesson":4,"word":"derailment","pronunciation":"/diːˈreɪlmənt/","meaning":"n.脱轨","seq":62,"isStar":false},{"id":2205,"unit":7,"lesson":4,"word":"logic","pronunciation":"/ˈlɒdʒɪk/","meaning":"n.思维方式;解释方法;逻辑","seq":63,"isStar":false,"memo":"谐音 单词发音类似“逻辑”。","example":"I fail to see the logic behind his argument. 我不明白他的论点背后的逻辑。"},{"id":2206,"unit":7,"lesson":4,"word":"logical","pronunciation":"/ˈlɒdʒɪk(ə)l/","meaning":"adj.合乎情理的;符合逻辑的","seq":64,"isStar":false},{"id":2207,"unit":7,"lesson":4,"word":"analogy","pronunciation":"/əˈnælədʒi/","meaning":"n.类比;比拟","seq":65,"isStar":false,"memo":"联想 a(形似乌龟)+n(形似门)+a(形似乌龟)+logy(音似“逻辑”)→门的两边各有一只小乌龟,从逻辑上讲,它俩的特征应该差不多→类比","example":"To help students understand how we see, teachers often draw an analogy between an eye and a camera. 老师经常把眼睛比作照相机,来帮助学生理解我们是怎样看东西的。"},{"id":2208,"unit":7,"lesson":4,"word":"analog(ue)","pronunciation":"/ˈænəlɒɡ/","meaning":"adj.模拟的 n.相似物","seq":66,"isStar":false,"memo":"构词 ana-(按照)+log(比例、言说)→按照原样对应出来的东西→相似物；模拟的","example":"The old recorder is an analogue device. 这台旧录音机是模拟设备。"},{"id":2209,"unit":7,"lesson":4,"word":"analogous","pronunciation":"/əˈnæləɡəs/","meaning":"adj.相似的;类似的","seq":67,"isStar":false},{"id":2210,"unit":7,"lesson":4,"word":"analyse/-yze","pronunciation":"/ˈænəlaɪz/","meaning":"v.分析","seq":68,"isStar":false,"memo":"构词 ana-(彻底)+lys(松开，同 analysis 分析)+-e→把整体彻底拆开来→分析","example":"We need to analyse the data first. 我们需要先分析这些数据。"},{"id":2211,"unit":7,"lesson":4,"word":"analysis","pronunciation":"/əˈnæləsɪs/","meaning":"n.分析;分析结果","seq":69,"isStar":false},{"id":2212,"unit":7,"lesson":4,"word":"analytical","pronunciation":"/ˌænəˈlɪtɪk(ə)l/","meaning":"adj.分析的;解析的","seq":70,"isStar":false},{"id":2213,"unit":7,"lesson":4,"word":"analyst","pronunciation":"/ˈænəlɪst/","meaning":"n.分析者;化验员","seq":71,"isStar":false,"memo":"构词 analys(分析)+-st(表人)→专门做分析的人→分析者，化验员","example":"She works as a financial analyst. 她是一名金融分析师。"},{"id":2214,"unit":7,"lesson":4,"word":"dialog(ue)","pronunciation":"/ˈdaɪəlɒɡ/","meaning":"n.对话,对白","seq":72,"isStar":false,"memo":"构词 dia-(相互)+log(说话)→双方相互说的话→对话，对白","example":"The film's dialogue is very natural. 这部电影的对白非常自然。"},{"id":2215,"unit":7,"lesson":4,"word":"ideology","pronunciation":"/ˌaɪdiˈɒlədʒi/","meaning":"n.思想(体系);思想意识","seq":73,"isStar":false,"memo":"联想 ideo(=idea,思想)+logy(音似“逻辑”)→思想逻辑→思想(体系);思想意识","example":"These businesses have a core ideology of which profit is but one ideal. 这些公司的核心理念是:利润是唯一的理想。"},{"id":2216,"unit":7,"lesson":4,"word":"ideological","pronunciation":"/ˌaɪdiəˈlɒdʒɪk(ə)l/","meaning":"adj.思想体系的;意识形态的","seq":74,"isStar":false},{"id":2217,"unit":7,"lesson":4,"word":"spirit","pronunciation":"/ˈspɪrɪt/","meaning":"n.精神;心灵;情绪,兴致","seq":75,"isStar":false,"memo":"联想 他喝完雪碧(Sprite)后瞬间有了精神(spirit)。[呼吸赋予人以精神,因此词根spir意为“呼吸”。]","example":"Paired learning cultivates the spirit of cooperation. 结对学习培养合作精神。"},{"id":2218,"unit":7,"lesson":4,"word":"spiritual","pronunciation":"/ˈspɪrɪtʃuəl/","meaning":"adj.精神的,心灵的","seq":76,"isStar":false},{"id":2219,"unit":7,"lesson":4,"word":"inspire","pronunciation":"/ɪnˈspaɪə(r)/","meaning":"v.激励,鼓励;激起,唤起","seq":77,"isStar":false,"memo":"构词 in(里面)+spir(呼吸)+e→注入生气,赋予精神力量→激励,鼓励","example":"The television repairman who wears a uniform tends to inspire more trust than one who appears in civilian clothes. 穿着制服的电视维修工往往比穿着便服的维修工更能激起信任。"},{"id":2220,"unit":7,"lesson":4,"word":"inspiration","pronunciation":"/ˌɪnspəˈreɪʃ(ə)n/","meaning":"n.灵感","seq":78,"isStar":false,"memo":"联想 in(里面)+spir(呼吸)+-ation(名词后缀)→我使劲吸一口气,“灵感”就来了。","example":"Music gives me inspiration. 音乐给我灵感。"},{"id":2221,"unit":7,"lesson":4,"word":"inspirational","pronunciation":"/ˌɪnspəˈreɪʃənl/","meaning":"adj.启发灵感的;鼓舞人心的","seq":79,"isStar":false},{"id":2222,"unit":7,"lesson":4,"word":"aspire","pronunciation":"/əˈspaɪə(r)/","meaning":"v.追求,渴望;有志于","seq":80,"isStar":false,"memo":"构词 a-(表加强)+spir(呼吸)+e→因某事而呼吸急促→渴望","example":"They aspire to managerial positions. 他们渴望管理职位。"},{"id":2223,"unit":7,"lesson":4,"word":"aspiration","pronunciation":"/ˌæspəˈreɪʃ(ə)n/","meaning":"n.渴望;抱负,志向","seq":81,"isStar":false},{"id":2224,"unit":7,"lesson":4,"word":"conspire","pronunciation":"/kənˈspaɪə(r)/","meaning":"v.共谋;密谋","seq":82,"isStar":false,"memo":"构词 con-(共同)+spir(呼吸)+e→同呼吸,共存亡→共谋","example":"There are four parties conspiring to keep you connected: the tech, your boss, your friends and you. 有四方合谋让你保持在线:科技、你的老板、你的朋友和你自己。"},{"id":2225,"unit":7,"lesson":4,"word":"expire","pronunciation":"/ɪkˈspaɪə(r)/","meaning":"v.到期,过期,失效;(任期)届满;死亡","seq":83,"isStar":false,"memo":"构词 ex-(向外)+(s)pir(呼吸)+e→向外呼出最后一口气→死亡","example":"Mike just discovered that his passport had expired three months ago. 迈克刚发现他的护照三个月前就过期了。"},{"id":2226,"unit":7,"lesson":4,"word":"expiration","pronunciation":"/ˌekspəˈreɪʃ(ə)n/","meaning":"n.(文件、协议等的)满期,到期","seq":84,"isStar":false},{"id":2227,"unit":7,"lesson":4,"word":"gasp","pronunciation":"/ɡɑːsp/","meaning":"n.喘息,倒抽气 v.喘息;气吁吁地说","seq":85,"isStar":false,"memo":"联想 gas(汽油)+p(联想“趴”)→他趴在汽油旁,闻到了刺鼻的汽油味,发出“喘息”声。","example":"The cold made her gasp. 寒冷使她倒抽了一口凉气。"},{"id":2228,"unit":7,"lesson":4,"word":"cease","pronunciation":"/siːs/","meaning":"v.停止,终止,终了","seq":86,"isStar":false,"memo":"谐音 单词发音类似“谁死”→停止,终止","example":"Welfare payments cease as soon as an individual starts a job. 一旦就业,即停发福利救济。"},{"id":2229,"unit":7,"lesson":4,"word":"suspend","pronunciation":"/səˈspend/","meaning":"v.悬,挂;暂停,中止","seq":87,"isStar":false,"memo":"联想 sus-(往下) + pen(钢笔) + d(音似“的”)→过去有钢笔的人往往会把钢笔朝下“挂”在口袋上。","example":"A lamp was suspended from the ceiling. 一盏灯悬挂在天花板上。"},{"id":2230,"unit":7,"lesson":4,"word":"suspense","pronunciation":"/səˈspens/","meaning":"n.担心;焦虑;兴奋;悬念","seq":88,"isStar":false},{"id":2231,"unit":7,"lesson":4,"word":"suspension","pronunciation":"/səˈspenʃ(ə)n/","meaning":"n.暂令停职(或停学、停赛等);暂缓","seq":89,"isStar":false},{"id":2232,"unit":7,"lesson":4,"word":"pendulum","pronunciation":"/ˈpendʒələm/","meaning":"n.钟摆;(主张、信念等的)摇摆不定","seq":90,"isStar":false,"memo":"联想 pend(悬挂) + ulum→“钟摆”挂在墙上，左右摇摆。","example":"Its tail swung back and forth like the pendulum of a clock. 它的尾巴像钟摆一样来回摆动。"},{"id":2233,"unit":7,"lesson":4,"word":"appendix","pronunciation":"/əˈpendɪks/","meaning":"n.阑尾;(书末的)附录","seq":91,"isStar":false,"memo":"联想 ap-(一再地) + pend(悬挂) + ix→书后面挂的东西是“附录”。","example":"We are not certain whether the appendix had already burst or not. 我们不能确定阑尾破了没有。"},{"id":2234,"unit":7,"lesson":4,"word":"postpone","pronunciation":"/pəˈspəʊn/","meaning":"v.延迟,延期","seq":92,"isStar":false,"memo":"联想 post(邮寄) + pone(联想 phone,手机)→邮寄手机的过程中遇到问题了，所以要“延期”派送。","example":"The game has already been postponed three times. 这场比赛已经三度延期了。"},{"id":2235,"unit":7,"lesson":4,"word":"postponement","pronunciation":"/pəˈspəʊnmənt/","meaning":"n.推迟","seq":93,"isStar":false},{"id":2236,"unit":7,"lesson":4,"word":"symphony","pronunciation":"/ˈsɪmfəni/","meaning":"n.交响乐,交响曲","seq":94,"isStar":false,"memo":"联想 sym(音似 same) + phon(声音) + y→不同声音的乐器同时演奏同一首乐曲→交响乐","example":"It's the first performance of the States Symphony Orchestra in our city. 这是国家交响乐团在我们这个城市的首次演出。"},{"id":2237,"unit":7,"lesson":4,"word":"melody","pronunciation":"/ˈmelədi/","meaning":"n.旋律,曲调;悦耳的音乐","seq":95,"isStar":false,"memo":"谐音 单词发音类似“买了笛”→他买了一支笛子，吹奏出美妙的“旋律”。","example":"The melody of this song is really beautiful. 这首歌的旋律非常优美。"},{"id":2238,"unit":7,"lesson":4,"word":"melodious","pronunciation":"/məˈləʊdiəs/","meaning":"adj.悦耳的;优美动听的","seq":96,"isStar":false},{"id":2239,"unit":7,"lesson":4,"word":"symptom","pronunciation":"/ˈsɪmptəm/","meaning":"n.征兆;症状","seq":97,"isStar":false,"memo":"联想 sym(音似 same) + p + tom(音似“童木”)→他和阿童木长得一样,有同样的特征→症状","example":"Flu symptoms include fever and chills. 流感症状包括发烧和寒战。"},{"id":2240,"unit":7,"lesson":4,"word":"symposium","pronunciation":"/sɪmˈpəʊziəm/","meaning":"n.专题讨论会;研讨会","seq":98,"isStar":false,"memo":"联想 sym(音似 same) + pos(联想 pose,提出) + -ium(名词后缀)→一群相同身份的人聚在一起提出各种观点的场合→研讨会","example":"He will take part in an international symposium on population. 他将参加一个有关人口的国际研讨会。"},{"id":2241,"unit":7,"lesson":4,"word":"sympathy","pronunciation":"/ˈsɪmpəθi/","meaning":"n.同情;赞同,支持","seq":99,"isStar":false,"memo":"联想 sym(音似 same) + path(道路) + y→同道中人最能相互“同情”。","example":"He didn't get much sympathy from anyone. 他没有从别人那里得到多少同情。"},{"id":2242,"unit":7,"lesson":4,"word":"sympathise/-ize","pronunciation":"/ˈsɪmpəθaɪz/","meaning":"v.同情;赞同,支持","seq":100,"isStar":false,"memo":"构词 sym-(共同)+path(感受，同 sympathy 同情)+-ise/-ize(使…化)→与他人的感受相同→同情；赞同，支持","example":"I sympathise with your situation. 我同情你的处境。"},{"id":2243,"unit":7,"lesson":4,"word":"sympathetic","pronunciation":"/ˌsɪmpəˈθetɪk/","meaning":"adj.同情的,有同情心的;赞同的","seq":101,"isStar":false,"memo":"对照 sympathy n.同情;赞同→sympathetic adj.","example":"They felt sympathetic to the other child. 他们很同情另一个孩子。"},{"id":2244,"unit":7,"lesson":4,"word":"mercy","pronunciation":"/ˈmɜːsi/","meaning":"n.仁慈,宽容;幸运,恩惠","seq":102,"isStar":false,"memo":"联想 me(我) + rcy(联想 cry)→“仁慈”的我特别容易被感动哭。","example":"Virtue, mercy and justice are taken as the skills of successful leaders. 美德、仁慈和正义被认为是成功领导者的技能。"},{"id":2245,"unit":7,"lesson":4,"word":"merciful","pronunciation":"/ˈmɜːsɪf(ə)l/","meaning":"adj.仁慈的,宽大的","seq":103,"isStar":false},{"id":2246,"unit":7,"lesson":4,"word":"pathetic","pronunciation":"/pəˈθetɪk/","meaning":"adj.可怜的,可悲的;令人怜悯的","seq":104,"isStar":false,"memo":"对照 那些可怜的(pathetic)人让她产生了同情的(sympathetic)心理。","example":"People were saddened when they watched the pathetic sight on TV. 当人们在电视上看到这可悲的场景时,他们都很难过。"},{"id":2247,"unit":7,"lesson":4,"word":"naive","pronunciation":"/naɪˈiːv/","meaning":"adj.幼稚的,轻信的;天真的,率直的","seq":105,"isStar":false,"memo":"联想 nai(联想“奶”) + ve(联想“喂”)→还在被喂奶的孩子的特点是“幼稚的”。","example":"I can't believe you were so naive as to trust him! 真是难以相信,你会幼稚到信任他!"},{"id":2248,"unit":7,"lesson":4,"word":"naively","pronunciation":"/naɪˈiːvli/","meaning":"n.天真;幼稚","seq":106,"isStar":false,"memo":"构词 naive(天真的)+-ly(副词后缀)→天真地；提示 本词条释义“天真；幼稚”是形容词 naive 的含义","example":"He naively believed every word she said. 他天真地相信了她说的每一个字。"},{"id":2249,"unit":7,"lesson":4,"word":"innocent","pronunciation":"/ˈɪnəs(ə)nt/","meaning":"adj.清白的,无辜的;天真的;无知的","seq":107,"isStar":false,"memo":"联想 in(里面) + no(没有) + cent(分币)→“天真的”小孩口袋里没有一分钱。","example":"I am convinced that she is innocent of any crime. 我坚信她是清白无罪的。"},{"id":2250,"unit":7,"lesson":4,"word":"innocence","pronunciation":"/ˈɪnəs(ə)ns/","meaning":"n.清白;天真","seq":108,"isStar":false},{"id":2251,"unit":8,"lesson":1,"word":"fold","pronunciation":"/fəʊld/","meaning":"v.折叠,对折;包,裹 n.褶,褶皱","seq":1,"isStar":false,"memo":"联想 f(联想“父”)+old(年老的)→父亲老了,脸上有了“褶”。","example":"It has wings that can fold. 它有可以折叠的翅膀。"},{"id":2252,"unit":8,"lesson":1,"word":"unfold","pronunciation":"/ʌnˈfəʊld/","meaning":"v.(使)展开,打开;展示;发生,发展","seq":2,"isStar":false,"memo":"构词 un-(否定前缀)+fold(折叠;包,裹)→(使)展开,打开","example":"The most remarkable part of the story unfolded only last week. 这个故事最引人注目的部分在上周刚刚展开。"},{"id":2253,"unit":8,"lesson":1,"word":"undo","pronunciation":"/ʌnˈduː/","meaning":"v.打开;消除,取消,废止;打败","seq":3,"isStar":false,"memo":"构词 un-(相反)+do(做)→把做过的事反过来做→打开；消除，取消，废止；打败","example":"I undid the package and took out the books. 我打开包裹取出书来。"},{"id":2254,"unit":8,"lesson":1,"word":"wrinkle","pronunciation":"/ˈrɪŋk(ə)l/","meaning":"n.皱纹;褶皱","seq":4,"isStar":false,"memo":"联想 wr(联想 write)+ink(墨水)+le(联想“了”)→他用墨水写写画画,给画中人画了很多“皱纹”。","example":"Her face was a mass of wrinkles. 她的脸上布满了皱纹。"},{"id":2255,"unit":8,"lesson":1,"word":"zigzag","pronunciation":"/ˈzɪɡzæɡ/","meaning":"n.锯齿形线条(或形状)","seq":5,"isStar":false,"memo":"联想 over(在……上面) + lap(音似“来扑”) → 一群小孩玩叠罗汉游戏，接连扑来趴在上面→部分重叠","example":"The path descended the hill in a series of zigzags.小路以一连串之字形曲折下坡。"},{"id":2256,"unit":8,"lesson":1,"word":"overlap","pronunciation":"/ˌəʊvəˈlæp/","meaning":"v.部分重叠,交叠 n.重叠部分","seq":6,"isStar":false,"memo":"联想 over(在……上面)+lap(音似“来扑”)→一群小孩玩叠罗汉游戏,接连扑来趴在上面→部分重叠","example":"There is considerable overlap between the girls’ and boys’ test results. 女孩和男孩的测试结果有相当多的重叠。"},{"id":2257,"unit":8,"lesson":1,"word":"lay","pronunciation":"/leɪ/","meaning":"v.安放,放置;下(蛋),产(卵);提出","seq":7,"isStar":false,"memo":"谐音 单词发音类似“累”→如果你累了,可以把头靠在我的肩膀上→安放,放置","example":"Fishes are caught when they are on the way upstream to lay eggs. 鱼类在去上游产卵时被捕获。"},{"id":2258,"unit":8,"lesson":1,"word":"lay-off","pronunciation":"/ˈleɪ ɒf/","meaning":"n.解雇,裁员","seq":8,"isStar":false,"memo":"构词 lay(放)+off(离开)→把人先放下、让他离开→解雇，裁员","example":"Cost-cutting lay-offs in the 1980s sharply reduced the workforce. 20世纪80年代削减成本的裁员大幅减少了就业人数。"},{"id":2259,"unit":8,"lesson":1,"word":"layer","pronunciation":"/ˈleɪə(r)/","meaning":"n.层,表层;层次","seq":9,"isStar":false,"memo":"构词 lay(铺、放)+-er(名词后缀)→一层层铺上去的东西→层，表层；层次，阶层","example":"Ducks have a thick layer of fat to keep them warm. 鸭子有一层厚厚的脂肪来保暖。"},{"id":2260,"unit":8,"lesson":1,"word":"layman","pronunciation":"/ˈleɪmən/","meaning":"n.非专业人员,门外汉,外行人","seq":10,"isStar":false,"memo":"联想 lay(lie“躺”的过去式)+man(人)→躺平的人不可能成为行业的精英，也就是个“外行人”。","example":"Where the law is concerned, I am only a layman. 谈到法律，我不过是个门外汉。"},{"id":2261,"unit":8,"lesson":1,"word":"amateur","pronunciation":"/ˈæmətə(r)/","meaning":"n.业余爱好者,外行 adj.业余的","seq":11,"isStar":false,"memo":"联想 ama(音似“爱莫”)+t(联想“他”)+eur→他爱莫能助，因为他是“外行”，水平不够。","example":"She is an amateur photographer. 她是一名业余摄影师。"},{"id":2262,"unit":8,"lesson":1,"word":"veteran","pronunciation":"/ˈvetərən/","meaning":"n.老兵,退伍军人;经验丰富的人,老手","seq":12,"isStar":false,"memo":"联想 v(形似罗马数字5)+cte(形似人脸)+ran(run的过去式)→战争期间，五个“老兵”跑去了前线。","example":"He is a seasoned veteran of the political establishment. 他是位经验丰富的政坛老手。"},{"id":2263,"unit":8,"lesson":1,"word":"sophisticated","pronunciation":"/səˈfɪstɪkeɪtɪd/","meaning":"adj.见多识广的;老练的;复杂的","seq":13,"isStar":false,"memo":"联想 so(非常)+phisticated(音似“费时啃它”)→这是个“复杂”的问题，攻克它非常费时。","example":"He is a smart and sophisticated young man. 他是一个聪明、老练的年轻人。"},{"id":2264,"unit":8,"lesson":1,"word":"sophistication","pronunciation":"/səˌfɪstɪˈkeɪʃn/","meaning":"n.老练,世故;复杂巧妙;高水平","seq":14,"isStar":false},{"id":2265,"unit":8,"lesson":1,"word":"layout","pronunciation":"/ˈleɪaʊt/","meaning":"n.布局;设计;版面编排,版面设计","seq":15,"isStar":false,"memo":"构词 lay(放置)+out(出去)→布局","example":"The woman would like to help with the exhibition layout. 这位女士想帮忙布置展览。"},{"id":2266,"unit":8,"lesson":1,"word":"relay","pronunciation":"/ˈriːleɪ/","meaning":"n.轮班,轮换;接力赛","seq":16,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+lay(lie“躺”的过去式)→阿姨作为“轮班”人员，累得躺下了。","example":"They raced to a thrilling victory in the relay. 他们在接力赛中奋力冲刺，取得了激动人心的胜利。"},{"id":2267,"unit":8,"lesson":1,"word":"delay","pronunciation":"/dɪˈleɪ/","meaning":"n.延期;耽搁,延误","seq":17,"isStar":false,"memo":"构词 de-(向下)+lay(放置)→往下面放→延期，推迟","example":"It's also a good idea to delay the conversation if you are in a meeting. 如果你在开会，推迟谈话也是个好主意。"},{"id":2268,"unit":8,"lesson":1,"word":"deputy","pronunciation":"/ˈdepjuti/","meaning":"n.副手,副职;代理","seq":18,"isStar":false,"memo":"构词 de-(向下)+put(指派，同 compute 计算)+-y(表人)→被指派到下面代行职务的人→副手，副职，代理","example":"Deputy chiefs may be more willing to make the decisions. 副职主管可能更愿意作出决定。"},{"id":2269,"unit":8,"lesson":1,"word":"vice","pronunciation":"/vaɪs/","meaning":"adj.代理的;副的 n.罪行,邪恶行径","seq":19,"isStar":false,"memo":"联想 与 vice(恶习)同形：站在正职旁边那一位→代理的，副的；另一种含义是罪行，恶习","example":"Greed is a terrible vice.贪婪是一种可怕的恶习。"},{"id":2270,"unit":8,"lesson":1,"word":"outline","pronunciation":"/ˈaʊtlaɪn/","meaning":"n.提纲,纲要;梗概;轮廓 v.概述","seq":20,"isStar":false,"memo":"(构词) out(外面)+line(线)→外部线条→轮廓","example":"The outline of the changes needed is clear.变更所需要的提纲是很清晰的。"},{"id":2271,"unit":8,"lesson":1,"word":"outlook","pronunciation":"/ˈaʊtlʊk/","meaning":"n.景色;前景;观点;世界观;人生观","seq":21,"isStar":false,"memo":"(构词) out(往外)+look(看)→往外看到的是“景色”。","example":"The outlook for jobs is pretty bright.就业市场前景十分光明。"},{"id":2272,"unit":8,"lesson":1,"word":"outlet","pronunciation":"/ˈaʊtlet/","meaning":"n.专营店,经销店;折扣店;出路","seq":22,"isStar":false,"memo":"(构词) out(出去)+let(让)→让……出去→出口","example":"The business has 34 retail outlets in this state alone.那家公司仅在这个州就有34个零售店。"},{"id":2273,"unit":8,"lesson":1,"word":"inner","pronunciation":"/ˈɪnə(r)/","meaning":"adj.里面的,向内的,内部的","seq":23,"isStar":false,"memo":"构词 in(在内)+-ner(比较级词尾)→更靠里的→里面的，内部的；内心的","example":"She doesn't reveal much of her inner self.她不大流露她内心的自我。"},{"id":2274,"unit":8,"lesson":1,"word":"outer","pronunciation":"/ˈaʊtə(r)/","meaning":"adj.外表的,外边的,外部的","seq":24,"isStar":false,"memo":"(构词) out(外面)+-er(后缀)→外边的,外部的","example":"It consists of an inner and an outer tent.它包括里外两个帐篷。"},{"id":2275,"unit":8,"lesson":1,"word":"indoor","pronunciation":"/ˈɪndɔː(r)/","meaning":"adj.室内的;在户内进行的,在室内用的","seq":25,"isStar":false,"memo":"构词 in(里面)+door(门)→在门里面→室内的","example":"Poor indoor air quality can result in increased risk of allergies.室内空气质量差会增加过敏的风险。"},{"id":2276,"unit":8,"lesson":1,"word":"indoors","pronunciation":"/ˌɪnˈdɔːz/","meaning":"adv.在室内","seq":26,"isStar":false},{"id":2277,"unit":8,"lesson":1,"word":"outdoor","pronunciation":"/ˈaʊtdɔː(r)/","meaning":"adj.户外的,室外的","seq":27,"isStar":false,"memo":"(构词) out(在……外面)+door(门)→在门外面→户外的,室外的","example":"They sell camping equipment, hiking gear and outdoor clothing.他们出售露营装备、徒步旅行装备和户外服装。"},{"id":2278,"unit":8,"lesson":1,"word":"outdoors","pronunciation":"/ˌaʊtˈdɔːz/","meaning":"adv.在户外,在野外 n.野外,旷野","seq":28,"isStar":false},{"id":2279,"unit":8,"lesson":1,"word":"turnout","pronunciation":"/ˈtɜːnaʊt/","meaning":"n.出席人数,到场人数;投票人数","seq":29,"isStar":false,"memo":"[记] (谐音) 单词发音类似“特闹腾”→因为“出席人数”很多，活动现场变得特别闹腾。","example":"This year's festival attracted a record turnout.今年的节日吸引了创纪录的参与人数。"},{"id":2280,"unit":8,"lesson":1,"word":"inward","pronunciation":"/ˈɪnwəd/","meaning":"adj.内心的,精神的","seq":30,"isStar":false,"memo":"构词：in(里面) + -ward(向……的)→内心的;向内(的)","example":"The door opens inward.门向里开。"},{"id":2281,"unit":8,"lesson":1,"word":"outward","pronunciation":"/ˈaʊtwəd/","meaning":"adj.表面的,外表的;外出的","seq":31,"isStar":false,"memo":"构词：out(外面) + -ward(向……的)→外表的;向外(的)","example":"The top door opened outward.最上面的门向外开着。"},{"id":2282,"unit":8,"lesson":1,"word":"interior","pronunciation":"/ɪnˈtɪəriə(r)/","meaning":"n.内部 adj.内部的,里面的","seq":32,"isStar":false,"memo":"构词：inter(内部) + -ior(后缀)→内部的,里面的","example":"The original interior of the hotel has been replaced.旅馆原来的内部装潢已被更换掉了。"},{"id":2283,"unit":8,"lesson":1,"word":"exterior","pronunciation":"/ɪkˈstɪəriə(r)/","meaning":"n.(尤指建筑物的)外部","seq":33,"isStar":false,"memo":"对照：这栋建筑的外部(exterior)设计得很低调,内部(interior)装修得很豪华。","example":"The exterior lights of the house came on as I approached the door.当我走近门的时候,房子外面的灯亮了。"},{"id":2284,"unit":8,"lesson":1,"word":"internal","pronunciation":"/ɪnˈtɜːn(ə)l/","meaning":"adj.内部的;内政的;国内的","seq":34,"isStar":false,"memo":"构词：inter-(内部) + n + -al(形容词后缀)→内部的","example":"She was on an internal flight from London to Manchester.她在从伦敦到曼彻斯特的国内航班上。"},{"id":2285,"unit":8,"lesson":1,"word":"external","pronunciation":"/ɪkˈstɜːn(ə)l/","meaning":"adj.外部的,外面的,外来的;对外的","seq":35,"isStar":false,"memo":"构词 extern(外，同 exterior 外部的)+-al(形容词后缀)→外面的→外部的，外来的，对外的","example":"What is the response of many educators to external rewards for their students?许多教育工作者对学生获得外部奖励的反应是什么?"},{"id":2286,"unit":8,"lesson":1,"word":"outcome","pronunciation":"/ˈaʊtkʌm/","meaning":"n.结果,成果","seq":36,"isStar":false,"memo":"构词：out(往外) + come(来)→往外出来→结果,成果","example":"Consider the person that you're dealing with in advance and what will get you to your desired outcome.事先考虑一下你要与之打交道的人,以及什么会让你达到你想要的结果。"},{"id":2287,"unit":8,"lesson":1,"word":"outbreak","pronunciation":"/ˈaʊtbreɪk/","meaning":"n.(暴力、疾病等坏事的)爆发,突然发生","seq":37,"isStar":false,"memo":"[记] (构词) out(出去，往外) + break(断裂) → 断裂喷出 → 爆发","example":"The local business was not much hampered by the sudden outbreak of the flu.突发的流感疫情没有对当地生意造成太大影响。"},{"id":2288,"unit":8,"lesson":1,"word":"output","pronunciation":"/ˈaʊtpʊt/","meaning":"n.(人、机器、机构的)产量","seq":38,"isStar":false,"memo":"构词：out(往外) + put(放)→输出","example":"In order to maximize profit, the firm would seek to maximize output.为了获得最大利润,这家公司会把产量增至最大。"},{"id":2289,"unit":8,"lesson":1,"word":"input","pronunciation":"/ˈɪnpʊt/","meaning":"n.投入资源(指时间、知识、思想等)","seq":39,"isStar":false,"memo":"in（进）+ put（放）→‘放进去’！键盘敲字是输入信息，熬夜赶PPT也是‘put time in’——双关秒懂！","example":"Teachers’ feedback is a crucial input for curriculum redesign. 教师的反馈是课程重新设计的关键投入。"},{"id":2290,"unit":8,"lesson":1,"word":"yield","pronunciation":"/jiːld/","meaning":"n.产量;利润 v.出产;产生;屈服","seq":40,"isStar":false,"memo":"联想 yi(联想“一”)+eld(联想 old)→有一个爷爷年纪很大,但仍然关心粮食“产量”。","example":"What does it yield? 它会产生什么?"},{"id":2291,"unit":8,"lesson":1,"word":"vacant","pronunciation":"/ˈveɪkənt/","meaning":"adj.空着的,未被占用的","seq":41,"isStar":false,"memo":"谐音 单词发音类似“未垦的”→一片土地尚未被开垦→空着的,未被占用的","example":"Only a few apartments were still vacant. 只有几套公寓仍然空着。"},{"id":2292,"unit":8,"lesson":1,"word":"vacancy","pronunciation":"/ˈveɪkənsi/","meaning":"n.空缺,空额;空房间;空虚","seq":42,"isStar":false},{"id":2293,"unit":8,"lesson":1,"word":"blank","pronunciation":"/blæŋk/","meaning":"adj.空白的,空的","seq":43,"isStar":false,"memo":"谐音 单词发音类似“不来客”→那家面馆晚上不来客人,总是“空的”。","example":"Leave the last page blank. 最后一页空着。"},{"id":2294,"unit":8,"lesson":1,"word":"vacuum","pronunciation":"/ˈvækjuːm/","meaning":"n.真空;(用真空吸尘器所做的)清洁","seq":44,"isStar":false,"memo":"构词 vac(空,无)+u+-um(名词后缀)→真空;空白","example":"His resignation has created a vacuum which cannot easily be filled. 他的辞职造成了难以填补的空白。"},{"id":2295,"unit":8,"lesson":1,"word":"evacuate","pronunciation":"/ɪˈvækjueɪt/","meaning":"v.(把people从危险的地方)疏散","seq":45,"isStar":false,"memo":"构词 e-(出,向外)+vac(空,无)+u+-ate(动词后缀)→使……向外变空→撤离;排泄","example":"All the sick and wounded were evacuated. 所有生病和受伤的人员都被疏散了。"},{"id":2296,"unit":8,"lesson":1,"word":"evacuation","pronunciation":"/ɪˌvækjuˈeɪʃ(ə)n/","meaning":"n.疏散,撤离;排泄","seq":46,"isStar":false},{"id":2297,"unit":8,"lesson":1,"word":"vacation","pronunciation":"/veɪˈkeɪʃ(ə)n/","meaning":"n.假期,休假 v.度假,休假","seq":47,"isStar":false,"memo":"谐音 单词发音类似“我开心”→“假期”的时候我很开心。","example":"A vacation will be affordable if one saves 20 dollars a week. 如果一个人每周存 20 美元,就可以负担得起一次度假。"},{"id":2298,"unit":8,"lesson":1,"word":"vocation","pronunciation":"/vəʊˈkeɪʃ(ə)n/","meaning":"n.工作,职业;使命感;天职","seq":48,"isStar":false,"memo":"对照 在假期(vacation)不要提工作(vocation)。","example":"He argued that attaining a vocation is one of the best ways to mature. 他认为,获得一份职业是走向成熟的最佳途径之一。"},{"id":2299,"unit":8,"lesson":1,"word":"vocational","pronunciation":"/vəʊˈkeɪʃən(ə)l/","meaning":"adj.职业的","seq":49,"isStar":false},{"id":2300,"unit":8,"lesson":1,"word":"excursion","pronunciation":"/ɪkˈskɜːʃn/","meaning":"n.(尤指集体度假时的)远足,短途旅行","seq":50,"isStar":false,"memo":"联想 ex-(出去)+cursion(音似“开心”)→出去“远足”会使人开心。","example":"They went on a day excursion to the mountains. 他们到山里去了一日短途旅行。"},{"id":2301,"unit":8,"lesson":1,"word":"expedition","pronunciation":"/ˌekspəˈdɪʃ(ə)n/","meaning":"n.远征,探险;考察队,探险队;短途出行","seq":51,"isStar":false,"memo":"联想 ex-(往外)+pedi(音似“盆地”)+-tion (名词后缀)→我外出去塔里木盆地“探险”。","example":"Our expedition included many highly successful people. 我们的探险队中有许多非常成功的人。"},{"id":2302,"unit":8,"lesson":1,"word":"commute","pronunciation":"/kəˈmjuːt/","meaning":"n.上下班的路程,通勤 v.上下班往返","seq":52,"isStar":false,"memo":"对照 交流(communicate)有来有往,通勤(commute)也是有去有回。","example":"If you are attending a local college, you'll probably live at home and commute to classes. 如果你要上当地的大学,你可能会住在家里,通勤去上课。"},{"id":2303,"unit":8,"lesson":1,"word":"commuter","pronunciation":"/kəˈmjuːtə(r)/","meaning":"n.长途上下班往返的人,通勤者","seq":53,"isStar":false},{"id":2304,"unit":8,"lesson":1,"word":"shuttle","pronunciation":"/ˈʃʌt(ə)l/","meaning":"v.穿梭","seq":54,"isStar":false,"memo":"联想 shut(关闭)+t+le(联想“了”)→车门关闭了,他在车站来回“穿梭”,等下一班车。","example":"A bus shuttles passengers back and forth from the station to the terminal. 一辆公共汽车在火车站和航站楼之间往返运送旅客。"},{"id":2305,"unit":8,"lesson":1,"word":"trek","pronunciation":"/trek/","meaning":"n.艰苦长途旅行","seq":55,"isStar":false,"memo":"联想 ex-（往外）+ pedi（音似“盆地”）+ -tion（名词后缀）→我外出去塔里木盆地“探险”。","example":"Our expedition included many highly successful people.我们的考察队中有许多非常成功的人士。"},{"id":2306,"unit":8,"lesson":1,"word":"wreck","pronunciation":"/rek/","meaning":"n.沉船,失事船","seq":56,"isStar":false,"memo":"联想 w(联想“我”)+reck(联想 neck)→我遭遇了“沉船”事故,现场“破坏”严重,我的脖子也受伤了。","example":"The wreck is lying at the bottom of the sea. 这艘失事船沉在海底。"},{"id":2307,"unit":8,"lesson":1,"word":"wreckage","pronunciation":"/ˈrekɪdʒ/","meaning":"n.残骸;残余","seq":57,"isStar":false},{"id":2308,"unit":8,"lesson":1,"word":"voyage","pronunciation":"/ˈvɔɪɪdʒ/","meaning":"n.航行;(尤指)航海,航天 v.航行","seq":58,"isStar":false,"memo":"联想 vo(音似“我”)+yage(联想 yoga)→我练瑜伽时会冥想,就像思想在“航行”。","example":"He saw life as a voyage of discovery. 他把生活看作是一场发现之旅。"},{"id":2309,"unit":8,"lesson":1,"word":"yoga","pronunciation":"/ˈjəʊɡə/","meaning":"n.瑜伽","seq":59,"isStar":false,"memo":"对照 做完瑜伽（yoga）可以来杯酸奶（yogurt）。","example":"More and more people seem to be turning to yoga, or meditation, or tai chi.越来越多的人似乎转向瑜伽、冥想或太极。"},{"id":2310,"unit":8,"lesson":1,"word":"tread","pronunciation":"/tred/","meaning":"n.步态,脚步声 v.踩,踏;行走","seq":60,"isStar":false,"memo":"谐音 单词发音类似“踹的”→用脚踹的→步态，脚步声","example":"I heard his heavy tread on the stairs.我听到他上楼梯时沉重的脚步声。"},{"id":2311,"unit":8,"lesson":1,"word":"wander","pronunciation":"/ˈwɒndə(r)/","meaning":"v.徘徊,闲逛,漫步;走神","seq":61,"isStar":false,"memo":"谐音：单词发音类似“玩的”→不知道去哪里玩的人，可以去街上“闲逛”。","example":"My thought started to wander. 我开始走神。"},{"id":2312,"unit":8,"lesson":1,"word":"linger","pronunciation":"/ˈlɪŋɡə(r)/","meaning":"v.继续存留;逗留,徘徊;拖延,磨蹭","seq":62,"isStar":false,"memo":"谐音 “零格”：赖着不走、进度一直停在零格→继续存留；逗留，徘徊；拖延","example":"Elisabeth did not enter the museum at once, but lingered in the courtyard. 伊丽莎白没有马上进博物馆，而是在院子里徘徊。"},{"id":2313,"unit":8,"lesson":1,"word":"stroll","pronunciation":"/strəʊl/","meaning":"n.&v.散步,闲逛,溜达","seq":63,"isStar":false,"memo":"联想 st(联想 street) + roll(滚动) → 在街上“散步”时，一个皮球滚动到我的脚边。","example":"They strolled down to the waterside.他们漫步走到水边。"},{"id":2314,"unit":8,"lesson":1,"word":"dart","pronunciation":"/dɑːt/","meaning":"v.猛冲,突进,飞奔;瞥一眼 n.镖","seq":64,"isStar":false,"memo":"谐音 单词发音类似“打他”→一群人“猛冲”过去打他。","example":"She made a dart for the door.她冲向门口。"},{"id":2315,"unit":8,"lesson":1,"word":"sneak","pronunciation":"/sniːk/","meaning":"v.偷偷地走,溜;偷偷地做","seq":65,"isStar":false,"memo":"对照 蛇(snake)偷偷溜(sneak)进了房间。","example":"I sneaked up the stairs.我蹑手蹑脚地上了楼。"},{"id":2316,"unit":8,"lesson":1,"word":"crawl","pronunciation":"/krɔːl/","meaning":"n.缓慢移动,徐行;自由泳,爬泳 v.爬","seq":66,"isStar":false,"memo":"谐音：单词发音类似“可弱”→他身体可弱了，走路只能“缓慢移动”。","example":"Our baby is just starting to crawl. 我们的宝宝刚开始会爬。"},{"id":2317,"unit":8,"lesson":1,"word":"creep","pronunciation":"/kriːp/","meaning":"v.蹑手蹑脚地移动;匍匐行进,爬行;蔓延","seq":67,"isStar":false,"memo":"联想：cr(联想“超人”) + ee(形似两只眼睛) + p(联想“趴”)→超人瞪着两只眼睛，趴在地上“爬行”。","example":"I saw a shadow creep across the floor. 我看见一个影子在地板上悄悄移动。"},{"id":2318,"unit":8,"lesson":1,"word":"cripple","pronunciation":"/ˈkrɪp(ə)l/","meaning":"v.使残废;使成瘸子","seq":68,"isStar":false,"memo":"对照：一场意外让他差点成了瘸子（cripple），康复初期只能爬行（creep）。","example":"He was crippled by polio as a child. 他幼年患过小儿麻痹症，结果腿就瘸了。"},{"id":2319,"unit":8,"lesson":1,"word":"climb","pronunciation":"/klaɪm/","meaning":"v.攀登;上升 n.攀登;增值","seq":69,"isStar":false,"memo":"联想：c(音似“可”) + limb(肢)→“攀登”可要靠四肢发力。","example":"She climbed up the stairs. 她爬上了楼梯。"},{"id":2320,"unit":8,"lesson":1,"word":"chase","pronunciation":"/tʃeɪs/","meaning":"v.&n.努力获取;追赶;追求","seq":70,"isStar":false,"memo":"联想：cha(联想“叉”) + se(音似“死”)→他在“追赶”一个臭虫，试图用叉子扎死它。","example":"The dog chased the cat around the garden. 狗在花园里追着猫跑。"},{"id":2321,"unit":8,"lesson":1,"word":"prey","pronunciation":"/preɪ/","meaning":"n.猎物;受害者 v.捕食;欺凌,坑骗","seq":71,"isStar":false,"memo":"[谐音] 单词发音类似“扑弱”→动物界中的强者在“捕食”时会扑咬弱者,弱者通常被称为“猎物”。","example":"They have fallen prey to wolves. 它们成了狼的猎物。"},{"id":2322,"unit":8,"lesson":1,"word":"predator","pronunciation":"/ˈpredətə(r)/","meaning":"n.捕食性动物;掠夺者;弱肉强食者","seq":72,"isStar":false,"memo":"构词 pred(掠夺，同 prey 猎物)+-ator(表物/人)→专靠掠夺别的生物生存者→捕食性动物；掠夺者","example":"Animals protect themselves against predators. 动物保护自己不受捕食者的伤害。"},{"id":2323,"unit":8,"lesson":1,"word":"predatory","pronunciation":"/ˈpredət(ə)ri/","meaning":"adj.捕食性的;欺负弱小的","seq":73,"isStar":false},{"id":2324,"unit":8,"lesson":1,"word":"stumble","pronunciation":"/ˈstʌmb(ə)l/","meaning":"v.跌跌撞撞地走,蹒跚而行;绊脚","seq":74,"isStar":false,"memo":"[联想] stu(音似“厮打”) + m(联想“妹”) + ble→妹妹与他厮打时崴到了脚,现在只能“蹒跚而行”。","example":"We were stumbling around in the dark looking for a candle. 黑暗中,我们东跌西撞地找蜡烛。"},{"id":2325,"unit":8,"lesson":1,"word":"stump","pronunciation":"/stʌmp/","meaning":"n.树桩;残根,残段","seq":75,"isStar":false,"memo":"[联想] stu(音似“厮打”) + m(联想“妹”) + p(联想“扑”)→妹妹与他厮打时不慎扑到了“树桩”上。","example":"The rock could almost be mistaken for the stump of an enormous tree. 这块石头差点被误认为是一棵大树的树桩。"},{"id":2326,"unit":8,"lesson":1,"word":"stun","pronunciation":"/stʌn/","meaning":"v.使昏迷;使震惊","seq":76,"isStar":false,"memo":"（谐音）单词发音类似“死打”→把人往死里打会把人打昏→使昏迷","example":"The news stunned everyone in the room. 这个消息让屋里所有人都惊呆了。"},{"id":2327,"unit":8,"lesson":2,"word":"supply","pronunciation":"/səˈplaɪ/","meaning":"n.供应,供给 v.供应","seq":1,"isStar":false,"memo":"构词 sup-(在下面)+ply(填满，同 complete 完成)→在下面不断填上来→供应，供给","example":"The abundant food supply is not expected to last.充足的粮食供应预计不会持续下去。"},{"id":2328,"unit":8,"lesson":2,"word":"supplier","pronunciation":"/səˈplaɪə(r)/","meaning":"n.供应者;供货商","seq":2,"isStar":false},{"id":2329,"unit":8,"lesson":2,"word":"supplement","pronunciation":"/ˈsʌplɪmənt/","meaning":"n.增补物,补充物;附录,增刊 v.增补","seq":3,"isStar":false,"memo":"联想 supple(联想 supply)+-ment(后缀)→这是我们提供给他的“补充物”。","example":"He supplements his income by giving private lessons.他通过教授私人课程来补充收入。"},{"id":2330,"unit":8,"lesson":2,"word":"supplementary","pronunciation":"/ˌsʌplɪˈmentri/","meaning":"adj.增补的,附加的","seq":4,"isStar":false},{"id":2331,"unit":8,"lesson":2,"word":"complement","pronunciation":"/ˈkɒmplɪment/","meaning":"n.补充物;补充 v.补充;使相配","seq":5,"isStar":false,"memo":"构词 com-(共同)+ple(填满)+-ment(后缀)→共同填满→补充","example":"The green wallpaper is the perfect complement to the old pine of the dresser.绿色墙纸与旧松木梳妆台完美互补。"},{"id":2332,"unit":8,"lesson":2,"word":"complementary","pronunciation":"/ˌkɒmplɪˈment(ə)ri/","meaning":"adj.互补的,补充的,相互补足的","seq":6,"isStar":false,"memo":"构词 com-(一起)+ple(填满)+-ment+-ary(形容词后缀)→互相把对方补满的→互补的，补充的","example":"These two skills are complementary. 这两项技能互为补充。"},{"id":2333,"unit":8,"lesson":2,"word":"implement","pronunciation":"/ˈɪmplɪment/","meaning":"v.执行,贯彻,实施 n.工具","seq":7,"isStar":false,"memo":"构词 im-(进入)+ple(填满)+-ment(后缀)→使某事进入填满(完善)状态的手段→执行,贯彻,实施","example":"Universal health care is to be implemented throughout the country.全民医保将在全国范围内实施。"},{"id":2334,"unit":8,"lesson":2,"word":"implementation","pronunciation":"/ˌɪmplɪmenˈteɪʃ(ə)n/","meaning":"n.实施,施行","seq":8,"isStar":false},{"id":2335,"unit":8,"lesson":2,"word":"compensate","pronunciation":"/ˈkɒmpenseɪt/","meaning":"v.偿还,补偿","seq":9,"isStar":false,"memo":"联想 com-(所有)+pens(钢笔)+-ate(动词后缀)→他把我的所有钢笔都弄坏了,我要求“补偿”。","example":"To compensate for the fast-shrinking labour force, the country would need large numbers of immigrants from overseas.为了弥补劳动力的快速萎缩,该国需要大量的海外移民。"},{"id":2336,"unit":8,"lesson":2,"word":"compensation","pronunciation":"/ˌkɒmpenˈseɪʃ(ə)n/","meaning":"n.补偿物;赔偿金","seq":10,"isStar":false},{"id":2337,"unit":8,"lesson":2,"word":"compensatory","pronunciation":"/ˌkɒmpenˈseɪtəri/","meaning":"adj.补偿性的","seq":11,"isStar":false},{"id":2338,"unit":8,"lesson":2,"word":"addict","pronunciation":"/ˈædɪkt/","meaning":"n.吸毒成瘾的人;对……着迷的人","seq":12,"isStar":false,"memo":"联想 ad-(一再地) + dict(说) → 一再地说一件事，说明对它着迷了 → 对……着迷的人","example":"He used to be a social media addict.他曾是一个社交媒体上瘾者。"},{"id":2339,"unit":8,"lesson":2,"word":"addiction","pronunciation":"/əˈdɪkʃ(ə)n/","meaning":"n.瘾;入迷;嗜好","seq":13,"isStar":false},{"id":2340,"unit":8,"lesson":2,"word":"addictive","pronunciation":"/əˈdɪktɪv/","meaning":"adj.使人上瘾的","seq":14,"isStar":false},{"id":2341,"unit":8,"lesson":2,"word":"indulge","pronunciation":"/ɪnˈdʌldʒ/","meaning":"v.(使)沉溺于,放纵;参与","seq":15,"isStar":false,"memo":"联想 in(里面)+dul(联想“读了”)+ge(联想“哥”)→哥哥每天在家里“沉溺于”读书。","example":"He has indulged in fake listening many times. 他已经有很多次沉溺于假装倾听的经历。"},{"id":2342,"unit":8,"lesson":2,"word":"indulgence","pronunciation":"/ɪnˈdʌldʒəns/","meaning":"n.沉溺,放纵","seq":16,"isStar":false},{"id":2343,"unit":8,"lesson":2,"word":"indulgent","pronunciation":"/ɪnˈdʌldʒənt/","meaning":"adj.纵容的,放纵的","seq":17,"isStar":false},{"id":2344,"unit":8,"lesson":2,"word":"obsess","pronunciation":"/əbˈses/","meaning":"v.使痴迷;使……心神不宁","seq":18,"isStar":false,"memo":"联想 ob-(表方向)+se(联想“色”)+ss(联想“美女”)→人们都朝着一个方向看那位出色的女性,她让人着迷→使痴迷","example":"Don't obsess about your weight. 不要过分担心你的体重。"},{"id":2345,"unit":8,"lesson":2,"word":"obsession","pronunciation":"/əbˈseʃ(ə)n/","meaning":"n.痴迷;困扰","seq":19,"isStar":false},{"id":2346,"unit":8,"lesson":2,"word":"obsessive","pronunciation":"/əbˈsesɪv/","meaning":"adj.着迷的","seq":20,"isStar":false},{"id":2347,"unit":8,"lesson":2,"word":"predict","pronunciation":"/prɪˈdɪkt/","meaning":"v.预言,预测","seq":21,"isStar":false,"memo":"构词 pre-(在……之前)+dict(说)→提前说→预言,预测","example":"Nobody could predict the outcome. 谁也无法预测结果如何。"},{"id":2348,"unit":8,"lesson":2,"word":"prediction","pronunciation":"/prɪˈdɪkʃ(ə)n/","meaning":"n.预言,预测","seq":22,"isStar":false},{"id":2349,"unit":8,"lesson":2,"word":"predictable","pronunciation":"/prɪˈdɪktəb(ə)l/","meaning":"adj.可预见的","seq":23,"isStar":false},{"id":2350,"unit":8,"lesson":2,"word":"dictate","pronunciation":"/dɪkˈteɪt/","meaning":"n.命令,规定 v.口述;强制规定;支配","seq":24,"isStar":false,"memo":"构词 dict(说)+-ate(后缀)→命令;口述","example":"I've got a long report I must dictate. 我有一个很长的报告,必须口述。"},{"id":2351,"unit":8,"lesson":2,"word":"dictation","pronunciation":"/dɪkˈteɪʃ(ə)n/","meaning":"n.口述;听写","seq":25,"isStar":false},{"id":2352,"unit":8,"lesson":2,"word":"dictator","pronunciation":"/dɪkˈteɪtə(r)/","meaning":"n.独裁者;霸道的人","seq":26,"isStar":false,"memo":"构词 dictat(e)(强制规定；支配) + -or(表示人的后缀) → 独裁者；霸道的人","example":"The people of that faraway country have been cruelly oppressed by a dictator.那个遥远国度的人民一直遭受独裁者的残酷压迫。"},{"id":2353,"unit":8,"lesson":2,"word":"contradict","pronunciation":"/ˌkɒntrəˈdɪkt/","meaning":"v.反驳,驳斥;与……矛盾","seq":27,"isStar":false,"memo":"构词 contra-(反对)+dict(说)→反驳","example":"He contradicted his own earlier statement. 他推翻了自己先前的说法。"},{"id":2354,"unit":8,"lesson":2,"word":"contradiction","pronunciation":"/ˌkɒntrəˈdɪkʃ(ə)n/","meaning":"n.矛盾,不一致;反驳","seq":28,"isStar":false,"memo":"构词 contradict(与……矛盾;反驳) + -ion (名词后缀)→矛盾;反驳","example":"The evidence contradicts the claim that we're mainly suffering from structural unemployment. 证据与我们主要遭受结构性失业的说法相矛盾。"},{"id":2355,"unit":8,"lesson":2,"word":"contradictory","pronunciation":"/ˌkɒntrəˈdɪktəri/","meaning":"adj.矛盾的","seq":29,"isStar":false,"memo":"构词 contra-(相反)+dict(说)+-ory(形容词后缀)→说的和说的正好相反→矛盾的","example":"The two reports are contradictory. 这两份报告相互矛盾。"},{"id":2356,"unit":8,"lesson":2,"word":"contrary","pronunciation":"/ˈkɒntrəri/","meaning":"n.相反,对立面 adj.相反的,相对的","seq":30,"isStar":false,"memo":"构词 contra-(相反)+-ary(形容词后缀)→站在对立面上的→相反，对立面；相反的","example":"I don't find him funny at all. Quite the contrary. 正相反,我觉得他一点儿也不有趣。"},{"id":2357,"unit":8,"lesson":2,"word":"contrast","pronunciation":"/ˈkɒntrɑːst/","meaning":"n.明显的差异;对比 v.对比,对照","seq":31,"isStar":false,"memo":"构词 contra-(对立) + st(= stand)→站在对立的方向→对比","example":"Give learners the chance to contrast good and bad solutions to the problems. 给学习者提供机会,让他们对比解决这些问题的好方法和坏方法。"},{"id":2358,"unit":8,"lesson":2,"word":"deny","pronunciation":"/dɪˈnaɪ/","meaning":"v.否认;拒绝","seq":32,"isStar":false,"memo":"谐音 单词发音类似“抵赖”→抵赖可以引申为“否认”。","example":"She denied any involvement in the affair. 她否认与此事有任何牵连。"},{"id":2359,"unit":8,"lesson":2,"word":"denial","pronunciation":"/dɪˈnaɪəl/","meaning":"n.否认;拒绝给予","seq":33,"isStar":false},{"id":2360,"unit":8,"lesson":2,"word":"defy","pronunciation":"/dɪˈfaɪ/","meaning":"v.违抗(法律或规则)","seq":34,"isStar":false,"memo":"谐音 单词发音类似“抵罚”→一个人闯红灯后抵抗罚款,就是“违抗”法律。","example":"You shouldn't openly defy the law. 你不应该公然违抗法律。"},{"id":2361,"unit":8,"lesson":2,"word":"defiance","pronunciation":"/dɪˈfaɪəns/","meaning":"n.违抗,拒绝服从","seq":35,"isStar":false},{"id":2362,"unit":8,"lesson":2,"word":"defiant","pronunciation":"/dɪˈfaɪənt/","meaning":"adj.公然违抗的,反抗的;挑衅的","seq":36,"isStar":false},{"id":2363,"unit":8,"lesson":2,"word":"envy","pronunciation":"/ˈenvi/","meaning":"v.&n.忌妒;羡慕","seq":37,"isStar":false,"memo":"谐音 单词发音类似“恩威”→他“羡慕”领导管理有方,恩威并施。","example":"The man's unique talents are the envy of many people. 这个人的独特才能令许多人羡慕。"},{"id":2364,"unit":8,"lesson":2,"word":"envious","pronunciation":"/ˈenviəs/","meaning":"adj.羡慕的;忌妒的","seq":38,"isStar":false},{"id":2365,"unit":8,"lesson":2,"word":"jealous","pronunciation":"/ˈdʒeləs/","meaning":"adj.妒羡的;忌妒的;珍惜的","seq":39,"isStar":false,"memo":"谐音 单词发音类似“姐乐死”→姐姐说太快乐时不能公开,以免让他人忌妒→忌妒的","example":"He's only talking to her to make you jealous. 他跟她讲话只是让你忌妒。"},{"id":2366,"unit":8,"lesson":2,"word":"jealousy","pronunciation":"/ˈdʒeləsi/","meaning":"n.忌妒;羡慕","seq":40,"isStar":false},{"id":2367,"unit":8,"lesson":2,"word":"resent","pronunciation":"/rɪˈzent/","meaning":"v.对……感到愤恨(不满)","seq":41,"isStar":false,"memo":"[联想] re-(重复) + sent(send 的过去式)→他重复把一些玩具送出去,说明不喜欢这些玩具→对……感到愤恨(不满)","example":"It is only natural that he should resent you. 他会怨恨你是很自然的。"},{"id":2368,"unit":8,"lesson":2,"word":"resentment","pronunciation":"/rɪˈzentmənt/","meaning":"n.愤恨,怨恨,不满","seq":42,"isStar":false},{"id":2369,"unit":8,"lesson":2,"word":"consent","pronunciation":"/kənˈsent/","meaning":"v.&n.同意,准许","seq":43,"isStar":false,"memo":"[联想] con-(都) + sent(send 的过去式)→我问他能不能把玩具都送给我,他“同意”了。","example":"The written consent of a parent is required. 要求有家长的书面同意。"},{"id":2370,"unit":8,"lesson":2,"word":"recognise/-ize","pronunciation":"/ˈrekəɡnaɪz/","meaning":"v.认识;辨认出;承认;意识到","seq":44,"isStar":false,"memo":"构词 re-(再)+cogn(知道，同 cognition 认知)+-ise/-ize(使…化)→再次认出来→认识；辨认出；承认","example":"I recognised her voice at once. 我一下子就听出了她的声音。"},{"id":2371,"unit":8,"lesson":2,"word":"recognition","pronunciation":"/ˌrekəɡˈnɪʃn/","meaning":"n.认识;承认,认可","seq":45,"isStar":false},{"id":2372,"unit":8,"lesson":2,"word":"cognitive","pronunciation":"/ˈkɒɡnətɪv/","meaning":"adj.认知的;感知的","seq":46,"isStar":false,"memo":"cogn（知道，词根）+ -itive（形容词）→‘能知道的’→认知的！联想‘考你five’：考试考你五感+脑子怎么认东西。","example":"Cognitive development is crucial during early childhood education. 认知发展对早期教育至关重要。"},{"id":2373,"unit":8,"lesson":2,"word":"cognition","pronunciation":"/kɒɡˈnɪʃ(ə)n/","meaning":"n.认识,认知","seq":47,"isStar":false},{"id":2374,"unit":8,"lesson":2,"word":"aware","pronunciation":"/əˈweə(r)/","meaning":"adj.意识到的,察觉到的","seq":48,"isStar":false,"memo":"[联想] a(一) + war(战争) + e(字母音似“姨”)→一场战争让阿姨意识到了和平是多么重要→意识到的","example":"Parents should be aware of children’s health hazards. 父母应该意识到孩子们的健康隐患。"},{"id":2375,"unit":8,"lesson":2,"word":"awareness","pronunciation":"/əˈweənəs/","meaning":"n.认识,意识","seq":49,"isStar":false},{"id":2376,"unit":8,"lesson":2,"word":"beware","pronunciation":"/bɪˈweə(r)/","meaning":"v.当心;注意,谨防","seq":50,"isStar":false,"memo":"联想 be(是) + ware(联想 aware) → 一个人出门在外，是应该意识到危险的 → 当心，注意，谨防","example":"Motorists were warned to beware of slippery conditions.司机们被提醒注意路面湿滑。"},{"id":2377,"unit":8,"lesson":2,"word":"conscious","pronunciation":"/ˈkɒnʃəs/","meaning":"adj.意识到的,注意到的;清醒的","seq":51,"isStar":false,"memo":"[谐音] 单词发音类似“靠心思”→靠(用)心思考就能意识到事物变化→意识到的","example":"We must be conscious of how technology is changing us. 我们要意识到技术正在如何改变我们。"},{"id":2378,"unit":8,"lesson":2,"word":"consciousness","pronunciation":"/ˈkɒnʃəsnəs/","meaning":"n.神志清醒;意识","seq":52,"isStar":false},{"id":2379,"unit":8,"lesson":2,"word":"identify","pronunciation":"/aɪˈdentɪfaɪ/","meaning":"v.认出,识别;确定;表明身份","seq":53,"isStar":false,"memo":"构词 ident(同一，同 identity 身份)+-ify(使…化)→确认是不是同一个→认出，识别；确定","example":"Identify how your skills can apply to your desired occupation. 确定一下如何将你的技能应用于你期望的职业中。"},{"id":2380,"unit":8,"lesson":2,"word":"identification","pronunciation":"/aɪˌdentɪfɪˈkeɪʃ(ə)n/","meaning":"n.鉴定,识别;身份证明(文件)","seq":54,"isStar":false},{"id":2381,"unit":8,"lesson":2,"word":"identity","pronunciation":"/aɪˈdentəti/","meaning":"n.身份;特性;一致,相同","seq":55,"isStar":false,"memo":"构词 ident(同一)+-ity(名词后缀)→证明自己是同一个人的依据→身份；特性；一致","example":"He meant that we gain personal identity as we communicate with others. 他的意思是,我们在与他人交流的过程中获得个人身份。"},{"id":2382,"unit":8,"lesson":2,"word":"identical","pronunciation":"/aɪˈdentɪk(ə)l/","meaning":"adj.完全相同的","seq":56,"isStar":false,"memo":"[联想] ident(联想 identity) + -ical(形容词后缀)→完全相同的","example":"It is nearly identical to our own planet. 它与我们的地球几乎完全相同。"},{"id":2383,"unit":8,"lesson":2,"word":"journal","pronunciation":"/ˈdʒɜːn(ə)l/","meaning":"n.期刊,日报;日记","seq":57,"isStar":false,"memo":"谐音：单词发音类似“窝心”→这个“版本”的电视剧看得我很窝心。","example":"This journal is available in paper and electronic form. 这份期刊有印刷版本和电子版本。"},{"id":2384,"unit":8,"lesson":2,"word":"journalist","pronunciation":"/ˈdʒɜːnəlɪst/","meaning":"n.新闻记者,新闻工作者","seq":58,"isStar":false},{"id":2385,"unit":8,"lesson":2,"word":"journalism","pronunciation":"/ˈdʒɜːnəlɪz(ə)m/","meaning":"n.新闻业;新闻工作","seq":59,"isStar":false,"memo":"构词：journal(期刊) + -ism(主义,思想) → 新闻业;新闻工作","example":"Science journalism is the main channel for the popularization of scientific information among the public. 科学新闻是向公众普及科学信息的主要渠道。"},{"id":2386,"unit":8,"lesson":2,"word":"coverage","pronunciation":"/ˈkʌvərɪdʒ/","meaning":"n.新闻报道;覆盖范围","seq":60,"isStar":false,"example":"There was blanket coverage of the world cup.世界杯得到了铺天盖地的报道。"},{"id":2387,"unit":8,"lesson":2,"word":"edit","pronunciation":"/ˈedɪt/","meaning":"n.编辑 v.编辑,校订","seq":61,"isStar":false,"memo":"构词 e-(向外)+dit(给予，同 tradition 传统)→把内容整理好再交出来→编辑，校订","example":"I had time to do a quick edit of my essay before handing it in. 我呈交论文之前有点时间,很快地校订了一遍。"},{"id":2388,"unit":8,"lesson":2,"word":"editor","pronunciation":"/ˈedɪtə(r)/","meaning":"n.主编;编辑","seq":62,"isStar":false},{"id":2389,"unit":8,"lesson":2,"word":"editorial","pronunciation":"/ˌedɪˈtɔːriəl/","meaning":"adj.编辑的 n.(报刊的)社论","seq":63,"isStar":false},{"id":2390,"unit":8,"lesson":2,"word":"edition","pronunciation":"/ɪˈdɪʃ(ə)n/","meaning":"n.版本","seq":64,"isStar":false},{"id":2391,"unit":8,"lesson":2,"word":"version","pronunciation":"/ˈvɜːʃ(ə)n/","meaning":"n.样式;版本;说法","seq":65,"isStar":false,"memo":"构词 vers(转)+-ion(名词后缀)→转出来的另一种说法→版本，样式；说法","example":"I don't accept his version of events. 我不相信他对事件的说法。"},{"id":2392,"unit":8,"lesson":2,"word":"novel","pronunciation":"/ˈnɒv(ə)l/","meaning":"adj.新颖的","seq":66,"isStar":false,"memo":"对照：小说(novel)更新需要创新(innovation)。","example":"The always-on Internet devices raise some novel possibilities. 这种永远在线的互联网设备带来了一些新奇的可能性。"},{"id":2393,"unit":8,"lesson":2,"word":"novelty","pronunciation":"/ˈnɒv(ə)lti/","meaning":"n.新奇,新颖","seq":67,"isStar":false},{"id":2394,"unit":8,"lesson":2,"word":"novelist","pronunciation":"/ˈnɒvəlɪst/","meaning":"n.小说家","seq":68,"isStar":false},{"id":2395,"unit":8,"lesson":2,"word":"fiction","pronunciation":"/ˈfɪkʃ(ə)n/","meaning":"n.小说;虚构的事","seq":69,"isStar":false,"memo":"谐音：单词发音类似“飞可神”→科幻“小说”里的人物可以飞来飞去,可神奇了。","example":"I read everything from fiction to history. 我从小说到历史,什么书都读。"},{"id":2396,"unit":8,"lesson":2,"word":"fictional","pronunciation":"/ˈfɪkʃən(ə)l/","meaning":"adj.虚构的;小说(中)的","seq":70,"isStar":false},{"id":2397,"unit":8,"lesson":2,"word":"episode","pronunciation":"/ˈepɪsəʊd/","meaning":"n.插曲;一段情节;一集","seq":71,"isStar":false,"memo":"联想：epi(音似“爱陪”) + sode → 家人爱陪着他看“一集”连续剧。","example":"The pre-release images are a hint to the next episode. 预告片是下一集的一个线索。"},{"id":2398,"unit":8,"lesson":2,"word":"literary","pronunciation":"/ˈlɪtərəri/","meaning":"adj.文学的;适于文学作品的","seq":72,"isStar":false,"memo":"[构词] liter(文字,字母)+-ary(形容词后缀)→文学的","example":"It was Chaucer who really turned English into a literary language. 正是乔叟使英语真正地变成了一门文学语言。"},{"id":2399,"unit":8,"lesson":2,"word":"literature","pronunciation":"/ˈlɪtrətʃə(r); ˈlɪtərətʃə/","meaning":"n.文学,文学作品;文献","seq":73,"isStar":false},{"id":2400,"unit":8,"lesson":2,"word":"literate","pronunciation":"/ˈlɪtərət/","meaning":"adj.有读写能力的;有文化的","seq":74,"isStar":false},{"id":2401,"unit":8,"lesson":2,"word":"literacy","pronunciation":"/ˈlɪtərəsi/","meaning":"n.读写能力","seq":75,"isStar":false},{"id":2402,"unit":8,"lesson":2,"word":"literal","pronunciation":"/ˈlɪtərəl/","meaning":"adj.字面意义的;完全按原文的","seq":76,"isStar":false,"memo":"[谐音] 单词发音类似“李特弱”→李同学的英语基础特别弱,只能按字面意思翻译→字面意义的","example":"This idiom also has a literal meaning. 这个习语还有字面意思。"},{"id":2403,"unit":8,"lesson":2,"word":"literally","pronunciation":"/ˈlɪtərəli/","meaning":"adv.字面上;确实地;简直","seq":77,"isStar":false},{"id":2404,"unit":8,"lesson":2,"word":"press","pronunciation":"/pres/","meaning":"n.出版社;印刷(机);新闻界 v.压","seq":78,"isStar":false,"memo":"构词 press(压)→用机器压印出来的东西→出版社，印刷机，新闻界；也作“压、催促”","example":"For two weeks they evaded the press. 他们两周以来一直对新闻媒体避而不见。"},{"id":2405,"unit":8,"lesson":2,"word":"pressure","pronunciation":"/ˈpreʃə(r)/","meaning":"n.压力;紧张;催促","seq":79,"isStar":false},{"id":2406,"unit":8,"lesson":2,"word":"pressing","pronunciation":"/ˈpresɪŋ/","meaning":"adj.紧急的,急迫的","seq":80,"isStar":false},{"id":2407,"unit":8,"lesson":2,"word":"oppress","pronunciation":"/əˈpres/","meaning":"v.压迫,压制;使烦恼,压抑","seq":81,"isStar":false,"memo":"[构词] op-(表方向)+press(压)→朝着某个方向压某人或某物→压迫,压制","example":"The gloomy atmosphere in the office oppressed her. 办公室低沉的气氛使她感到压抑。"},{"id":2408,"unit":8,"lesson":2,"word":"oppression","pronunciation":"/əˈpreʃn/","meaning":"n.压迫;压抑;镇压","seq":82,"isStar":false},{"id":2409,"unit":8,"lesson":2,"word":"oppressive","pronunciation":"/əˈpresɪv/","meaning":"adj.压迫的;压制的","seq":83,"isStar":false},{"id":2410,"unit":8,"lesson":2,"word":"impress","pronunciation":"/ɪmˈpres/","meaning":"v.使钦佩,使敬仰;给……留下深刻印象","seq":84,"isStar":false,"memo":"[构词] im-(入,里面)+press(压)→压进脑海去→给……留下深刻印象","example":"I was so impressed by how selfless she was. 她的无私给我留下了深刻的印象。"},{"id":2411,"unit":8,"lesson":2,"word":"impressive","pronunciation":"/ɪmˈpresɪv/","meaning":"adj.给人深刻印象的","seq":85,"isStar":false},{"id":2412,"unit":8,"lesson":2,"word":"impression","pronunciation":"/ɪmˈpreʃ(ə)n/","meaning":"n.印象","seq":86,"isStar":false},{"id":2413,"unit":8,"lesson":2,"word":"repress","pronunciation":"/rɪˈpres/","meaning":"v.克制,抑制;压制,镇压","seq":87,"isStar":false,"memo":"构词 re-(重新，再)+press(压)→重新压，再压→压制","example":"Brenda repressed the urge to shout at him.布伦达压抑住了对他喊叫的冲动。"},{"id":2414,"unit":8,"lesson":2,"word":"repression","pronunciation":"/rɪˈpreʃ(ə)n/","meaning":"n.压制,镇压;克制","seq":88,"isStar":false,"memo":"构词 re-(回)+press(压)+-ion(名词后缀)→往回压住不让出来→压制，镇压；克制","example":"The repression of dissent grew harsher. 对异见的压制变得更加严厉。"},{"id":2415,"unit":8,"lesson":2,"word":"repressive","pronunciation":"/rɪˈpresɪv/","meaning":"adj.抑制的;压制的;严苛的","seq":89,"isStar":false,"memo":"构词 re-(回)+press(压)+-ive(形容词后缀)→习惯往回压的→抑制的；压制的，严苛的","example":"They lived under a repressive government. 他们生活在一个压制性的政府之下。"},{"id":2416,"unit":8,"lesson":2,"word":"depress","pronunciation":"/dɪˈpres/","meaning":"v.使沮丧;使萧条;按下;降低","seq":90,"isStar":false,"memo":"构词 de-(往下) + press(压)→使沮丧；降低","example":"High interest rates are continuing to depress the economy. 高利率正在继续抑制经济。"},{"id":2417,"unit":8,"lesson":2,"word":"depression","pronunciation":"/dɪˈpreʃn/","meaning":"n.沮丧;抑郁症;萧条期","seq":91,"isStar":false},{"id":2418,"unit":8,"lesson":2,"word":"suppress","pronunciation":"/səˈpres/","meaning":"v.镇压,压制;抑制","seq":92,"isStar":false,"memo":"构词 sup-(=sub-,往下) + press(压)→镇压","example":"Men who suppress their emotions may develop stress-related disorders. 压抑自己情绪的人可能会发展出与压力有关的疾病。"},{"id":2419,"unit":8,"lesson":2,"word":"suppression","pronunciation":"/səˈpreʃ(ə)n/","meaning":"n.镇压,压制;抑制","seq":93,"isStar":false},{"id":2420,"unit":8,"lesson":2,"word":"suppressive","pronunciation":"/səˈpresɪv/","meaning":"adj.抑制的;镇压的","seq":94,"isStar":false},{"id":2421,"unit":8,"lesson":2,"word":"distress","pronunciation":"/dɪˈstres/","meaning":"n.悲痛,痛苦;忧虑;困苦 v.使痛苦","seq":95,"isStar":false,"memo":"联想 di-(两个) + stress(压力)→一种压力是压力，两种压力就会变成“痛苦”。","example":"To her distress, she found that her prayers did not calm her excitement. 令她痛苦的是，她发现她的祈祷并没有平复她的激动情绪。"},{"id":2422,"unit":8,"lesson":2,"word":"distressful","pronunciation":"/dɪˈstresfəl/","meaning":"adj.苦恼的;不幸的","seq":96,"isStar":false},{"id":2423,"unit":8,"lesson":2,"word":"agony","pronunciation":"/ˈæɡəni/","meaning":"n.极大的痛苦;苦难","seq":97,"isStar":false,"memo":"谐音 单词发音类似“爱割你”→把爱好割舍掉，对你来说是“极大的痛苦”。","example":"He was screaming in agony from the severe stomach pain. 他因剧烈的腹痛而痛苦地尖叫。"},{"id":2424,"unit":8,"lesson":2,"word":"misery","pronunciation":"/ˈmɪzəri/","meaning":"n.痛苦,悲惨;穷困","seq":98,"isStar":false,"memo":"联想 mis(联想 miss) + ery(联想 very)→非常想念一个人却见不到，一定很“痛苦”。","example":"Fame brought her nothing but misery. 名声只给她带来了痛苦。"},{"id":2425,"unit":8,"lesson":2,"word":"miserable","pronunciation":"/ˈmɪzrəbl/","meaning":"adj.痛苦的,可怜的;令人不快的","seq":99,"isStar":false},{"id":2426,"unit":8,"lesson":2,"word":"withstand","pronunciation":"/wɪðˈstænd/","meaning":"v.承受,经受住;抵挡","seq":100,"isStar":false,"memo":"构词 with(反对) + stand(站)→经受住；抵挡","example":"The flooring needs to be tough enough to withstand wear. 地板要坚固耐磨。"},{"id":2427,"unit":8,"lesson":2,"word":"notwithstanding","pronunciation":"/ˌnɒtwɪθˈstændɪŋ/","meaning":"prep.尽管 adv.&conj.尽管","seq":101,"isStar":false,"memo":"联想 not(没有) + withstand(经受住) + -ing(后缀)→“尽管”你没有取胜，但你经受住了考验。","example":"He was found guilty, notwithstanding that the evidence was very weak. 尽管证据很薄弱，他还是被判有罪。"},{"id":2428,"unit":8,"lesson":2,"word":"withdraw","pronunciation":"/wɪðˈdrɔː/","meaning":"v.(使)退出;取消;撤回;提取(存款)","seq":102,"isStar":false,"memo":"构词 with(向后) + draw(拉)→向后拉→撤回","example":"Many multinational enterprises are withdrawing from this country. 许多跨国企业正在从该国撤出。"},{"id":2429,"unit":8,"lesson":2,"word":"withdrawal","pronunciation":"/wɪðˈdrɔːəl/","meaning":"n.提款;撤走;收回","seq":103,"isStar":false},{"id":2430,"unit":8,"lesson":2,"word":"withhold","pronunciation":"/wɪðˈhəʊld/","meaning":"v.拒绝给;隐瞒;抑制","seq":104,"isStar":false,"memo":"构词 with(向后) + hold(拿着)→拒绝给；抑制","example":"The government was threatening to withhold future financial aid. 政府在威胁停止未来的财政援助。"},{"id":2431,"unit":8,"lesson":3,"word":"rim","pronunciation":"/rɪm/","meaning":"n.(圆形物的)边沿","seq":1,"isStar":false,"memo":"对照 戒指(ring)放在盘子边沿(rim)。","example":"He looked at them over the rim of his glass. 他从杯子的边沿看着他们。"},{"id":2432,"unit":8,"lesson":3,"word":"grim","pronunciation":"/ɡrɪm/","meaning":"adj.严肃的;令人沮丧的","seq":2,"isStar":false,"memo":"联想 g(联想“哥”) + rim(边沿)→在边沿(疆)的哥哥守卫国家,是很“严肃的”。","example":"She looked grim. 她表情严肃。"},{"id":2433,"unit":8,"lesson":3,"word":"trim","pronunciation":"/trɪm/","meaning":"adj.整齐的;苗条的 v.修剪","seq":3,"isStar":false,"memo":"联想 t(联想 take) + rim(边沿)→拿掉纸张边沿,就是把参差不齐的部分“修剪”整齐。","example":"I trimmed two centimetres off the skirt. 我把裙子剪短了两厘米。"},{"id":2434,"unit":8,"lesson":3,"word":"mow","pronunciation":"/məʊ/","meaning":"v.割,修剪","seq":4,"isStar":false,"memo":"谐音 单词发音类似“猫”→猫的毛需要定期“修剪”。","example":"She mowed the lawn herself that morning.那天早上她自己割了草坪。"},{"id":2435,"unit":8,"lesson":3,"word":"clip","pronunciation":"/klɪp/","meaning":"n.夹子;回形针;片段;修剪 v.夹住","seq":5,"isStar":false,"memo":"联想 c(形似夹子) + lip(嘴唇)→他的嘴唇被“夹子”给“夹住”了。","example":"He fastened the papers together with a paper clip. 他用回形针把文件固定在一起。"},{"id":2436,"unit":8,"lesson":3,"word":"chop","pronunciation":"/tʃɒp/","meaning":"v.切碎,砍,劈;削减","seq":6,"isStar":false,"memo":"谐音 单词发音类似“敲破”→买的大骨头要使劲“砍”,用力敲破。","example":"He was chopping logs for firewood. 他在把原木劈成柴火。"},{"id":2437,"unit":8,"lesson":3,"word":"boundary","pronunciation":"/ˈbaʊndri/","meaning":"n.边界,分界线;界限","seq":7,"isStar":false,"memo":"联想 bound(音似“邦德”) + -ary(名词后缀)→电影《007》里的詹姆斯·邦德是很有“边界”感的人。","example":"The river is the boundary between the two countries. 这条河是两国的分界线。"},{"id":2438,"unit":8,"lesson":3,"word":"margin","pronunciation":"/ˈmɑːdʒɪn/","meaning":"n.页边空白;利润;差额;余地","seq":8,"isStar":false,"memo":"谐音 单词发音类似“码近”→临近页码的地方就是“页边空白”。","example":"Margins are low and many companies are struggling. 利润很少,很多公司在苦苦挣扎。"},{"id":2439,"unit":8,"lesson":3,"word":"marginal","pronunciation":"/ˈmɑːdʒɪn(ə)l/","meaning":"adj.微不足道的,不重要的;边缘的","seq":9,"isStar":false,"memo":"构词 margin(边缘)+-al(形容词后缀)→只落在边缘上的→边缘的；微不足道的，不重要的","example":"The change had only a marginal effect. 这一变化只带来很小的影响。"},{"id":2440,"unit":8,"lesson":3,"word":"edge","pronunciation":"/edʒ/","meaning":"n.边缘;刀刃;(微弱的)优势","seq":10,"isStar":false,"memo":"单词发音类似“挨挤”→大海“边缘”有很多人都挨着挤在一起。","example":"It is going to lose its competitive edge in higher education. 它将在高等教育中失去其竞争优势。"},{"id":2441,"unit":8,"lesson":3,"word":"verge","pronunciation":"/vɜːdʒ/","meaning":"n.路缘;濒于 v.接近,濒于","seq":11,"isStar":false,"memo":"单词发音类似“我急”→“接近”迟到时，我很着急。","example":"They were on the verge of breaking up. 他们处于分手的边缘。"},{"id":2442,"unit":8,"lesson":3,"word":"average","pronunciation":"/ˈævərɪdʒ/","meaning":"n.平均水平","seq":12,"isStar":false,"memo":"构词 aver(源自海损“分摊”)+-age(名词后缀)→把损失平摊到各家→平均数；平均的；平常的","example":"The average temperature in summer here is very high. 这里夏天的平均气温很高。"},{"id":2443,"unit":8,"lesson":3,"word":"bound","pronunciation":"/baʊnd/","meaning":"n.界限,限度;跳跃 adj.肯定的","seq":13,"isStar":false,"memo":"单词发音类似“蹦跶”→你可以在我忙的时候到处蹦跶，但是不能超过我容忍的“限度”。","example":"There are no bounds to his ambition. 他的野心没有止境。"},{"id":2444,"unit":8,"lesson":3,"word":"prejudice","pronunciation":"/ˈpredʒədɪs/","meaning":"n.偏见,成见,歧视 v.使有偏见;损害","seq":14,"isStar":false,"memo":"pre-(预先) + judi(联想 Judy，人名) + ce → 这个人在见到朱迪之前，就对她存有“偏见”。","example":"Their decision was based on ignorance and prejudice. 他们的决定是基于无知和偏见。"},{"id":2445,"unit":8,"lesson":3,"word":"bias","pronunciation":"/ˈbaɪəs/","meaning":"n.偏心,偏见,偏爱 v.使有偏见","seq":15,"isStar":false,"memo":"bi-(两个) + as(音似“儿子”) → 他有两个儿子，从不“偏心”。","example":"The article examines gender bias in our schools. 这篇文章调查了我们学校的性别偏见。"},{"id":2446,"unit":8,"lesson":3,"word":"ambiguous","pronunciation":"/æmˈbɪɡjuəs/","meaning":"adj.模棱两可的,不明确的","seq":16,"isStar":false,"memo":"am(是) + bi-(两个) + gu(联想“姑”) + -ous(形容词后缀) → 这是两个姑姑的东西，但究竟归谁仍是“模棱两可的”。","example":"You need to rewrite this sentence because it is ambiguous. 你需要重写一下这个句子，因为它不明确。"},{"id":2447,"unit":8,"lesson":3,"word":"ambiguity","pronunciation":"/ˌæmbɪˈɡjuːəti; ˌæmbɪˈɡjuːɪti/","meaning":"n.模棱两可,不明确","seq":17,"isStar":false},{"id":2448,"unit":8,"lesson":3,"word":"equity","pronunciation":"/ˈekwəti/","meaning":"n.公平,公正;股票;资产净值","seq":18,"isStar":false,"memo":"构词 equ(= equal) + -ity(名词后缀)→公平","example":"We base this call on grounds of social justice and equity.我们的这一呼吁是基于社会公正和平等。"},{"id":2449,"unit":8,"lesson":3,"word":"equitable","pronunciation":"/ˈekwɪtəb(ə)l/","meaning":"adj.公平合理的;公正的","seq":19,"isStar":false},{"id":2450,"unit":8,"lesson":3,"word":"equate","pronunciation":"/ɪˈkweɪt/","meaning":"v.等同","seq":20,"isStar":false,"memo":"构词 equ(= equal) + -ate(动词后缀) → 使相等，使平等 → 等同","example":"It is a mistake to simply equate longevity with issues of old age.把长寿与老年问题混为一谈是错误的。"},{"id":2451,"unit":8,"lesson":3,"word":"adequate","pronunciation":"/ˈædɪkwət/","meaning":"adj.足够的,充分的;合乎需要的","seq":21,"isStar":false,"memo":"联想 ad-(一再地) + equate(等同)→如果一个人的英语水平一再地等同于老师的水平,那么他很可能拥有“足够的”英语知识储备。","example":"It is under adequate control. 它得到了充分的控制。"},{"id":2452,"unit":8,"lesson":3,"word":"adequately","pronunciation":"/ˈædɪkwətli/","meaning":"adv.足够地,充分地","seq":22,"isStar":false,"memo":"构词 adequ(足够，同 adequate 足够的)+-ate+-ly(副词后缀)→足够地，充分地","example":"The room was not adequately heated. 这个房间供暖不足。"},{"id":2453,"unit":8,"lesson":3,"word":"equivalent","pronunciation":"/ɪˈkwɪvələnt/","meaning":"adj.等值的;等同的 n.等同物","seq":23,"isStar":false,"memo":"构词 equi (= equal) + val (ue) (价值) + -ent(后缀)→具有相等的价值→等值的","example":"I'll be getting the equivalent of about 22,000 pounds a year there. 我将在那里获得的年薪相当于2.2万英镑。"},{"id":2454,"unit":8,"lesson":3,"word":"equation","pronunciation":"/ɪˈkweɪʒ(ə)n/","meaning":"n.方程式,等式;相等","seq":24,"isStar":false,"memo":"构词 equa(= equal) + -tion(名词后缀)→相等→等式","example":"The other side of that equation is that the US needs to save more. 等式的另一边则是美国需要增加储蓄。"},{"id":2455,"unit":8,"lesson":3,"word":"arrogant","pronunciation":"/ˈærəɡənt/","meaning":"adj.傲慢的,自大的","seq":25,"isStar":false,"memo":"联想 arro(音似“哎哟”) + gan(联想“干”) + t(联想“他”) → 哎哟，他为什么要干(做)这么“傲慢的”事？","example":"Many people may view him as an arrogant man.很多人可能认为他是个傲慢的人。"},{"id":2456,"unit":8,"lesson":3,"word":"arrogance","pronunciation":"/ˈærəɡəns/","meaning":"n.傲慢,自大","seq":26,"isStar":false},{"id":2457,"unit":8,"lesson":3,"word":"eloquent","pronunciation":"/ˈeləkwənt/","meaning":"adj.雄辩的,能言善辩的","seq":27,"isStar":false,"memo":"谐音 单词发音类似“爱唠嗑的”→爱唠嗑的人一般都很能说→雄辩的","example":"They are smart and eloquent. 他们聪明、能言善辩。"},{"id":2458,"unit":8,"lesson":3,"word":"eloquence","pronunciation":"/ˈeləkwəns/","meaning":"n.雄辩;口才","seq":28,"isStar":false},{"id":2459,"unit":8,"lesson":3,"word":"hostile","pronunciation":"/ˈhɒstaɪl/","meaning":"adj.敌意的,敌视的","seq":29,"isStar":false,"memo":"构词 host(敌人，拉丁语 hostis)+-ile(形容词后缀)→把对方当敌人的→敌意的，敌视的","example":"The boy feels hostile towards his father. 那个男孩对父亲怀有敌意。"},{"id":2460,"unit":8,"lesson":3,"word":"hostility","pronunciation":"/hɒˈstɪləti/","meaning":"n.敌意,对抗","seq":30,"isStar":false},{"id":2461,"unit":8,"lesson":3,"word":"anxious","pronunciation":"/ˈæŋkʃəs/","meaning":"adj.焦虑的;渴望的","seq":31,"isStar":false,"memo":"构词 anx(勒紧，同 anxiety 焦虑)+-ious(形容词后缀)→心里被勒得发紧→焦虑的；渴望的","example":"Many of us are weighed down by the past or anxious about the future. 我们中的许多人都被过去压得喘不过气来,或者对未来感到焦虑。"},{"id":2462,"unit":8,"lesson":3,"word":"anxiety","pronunciation":"/æŋˈzaɪəti/","meaning":"n.忧虑,担忧;渴望","seq":32,"isStar":false},{"id":2463,"unit":8,"lesson":3,"word":"dreadful","pronunciation":"/ˈdredf(ə)l/","meaning":"adj.可怕的,令人畏惧的","seq":33,"isStar":false,"memo":"联想 dread(音似“拽的”) + -ful(形容词后缀) → 一个人学习时，总有人拽他的后腿，这是很“可怕的”。","example":"I feel absolutely dreadful about what has happened.对发生的事我感到非常糟心。"},{"id":2464,"unit":8,"lesson":3,"word":"dread","pronunciation":"/dred/","meaning":"v.非常害怕","seq":34,"isStar":false,"memo":"联想 与 dead(死)形近：一想到死就发怵→非常害怕；极为担心；恐惧","example":"She has an irrational dread of hospitals. 她对医院有莫名的恐惧。"},{"id":2465,"unit":8,"lesson":3,"word":"shrewd","pronunciation":"/ʃruːd/","meaning":"adj.善于判断的;敏锐的,精明的","seq":35,"isStar":false,"memo":"谐音 单词发音类似“洗褥的”→这个洗褥子的人是很“精明的”,他知道怎么洗省时省力。","example":"It was a shrewd move to buy your house just before property prices started to rise. 你正好在房价开始上涨之前买房子,真是精明之举。"},{"id":2466,"unit":8,"lesson":3,"word":"critic","pronunciation":"/ˈkrɪtɪk/","meaning":"n.批评家,评论家","seq":36,"isStar":false,"example":"He was knighted in 1967, the first music critic to be so honored. 他于1967年被授予爵士头衔,是第一位获得如此殊荣的音乐评论家。"},{"id":2467,"unit":8,"lesson":3,"word":"criticise/-ize","pronunciation":"/ˈkrɪtɪsaɪz/","meaning":"v.批评,指责","seq":37,"isStar":false,"memo":"构词 critic(批评家)+-ise/-ize(使…化)→以批评家的身份说话→批评，指责","example":"He was criticised for his delay. 他因拖延而受到批评。"},{"id":2468,"unit":8,"lesson":3,"word":"criticism","pronunciation":"/ˈkrɪtɪsɪzəm/","meaning":"n.批评,批判;评论","seq":38,"isStar":false},{"id":2469,"unit":8,"lesson":3,"word":"critical","pronunciation":"/ˈkrɪtɪk(ə)l/","meaning":"adj.关键的;批评的","seq":39,"isStar":false,"memo":"构词 critic(评判)+-al(形容词后缀)→能做判断的，也指最要紧的关口→关键的；批评的","example":"This is a critical moment for the project. 这是项目的关键时刻。"},{"id":2470,"unit":8,"lesson":3,"word":"criterion","pronunciation":"/kraɪˈtɪəriən/","meaning":"n.(批评判断的)标准,准则","seq":40,"isStar":false,"memo":"联想 crit(联想 criticise) + er(联想“表示人的后缀”) +-ion(名词后缀)→批评别人时需要参照特定的“标准”。","example":"Practice is the sole criterion for testing truth. 实践是检验真理的唯一标准。"},{"id":2471,"unit":8,"lesson":3,"word":"confident","pronunciation":"/ˈkɒnfɪdənt/","meaning":"adj.自信的;有把握的","seq":41,"isStar":false,"memo":"构词 con-(完全)+fid(信任，同 faith 信念)+-ent(形容词后缀)→完全相信自己→自信的，有把握的","example":"They will feel more confident in competing with their rivals. 他们在与对手竞争时会感到更有自信。"},{"id":2472,"unit":8,"lesson":3,"word":"confidence","pronunciation":"/ˈkɒnfɪdəns/","meaning":"n.信心;自信","seq":42,"isStar":false},{"id":2473,"unit":8,"lesson":3,"word":"cynical","pronunciation":"/ˈsɪnɪk(ə)l/","meaning":"adj.愤世嫉俗的;悲观的;怀疑的","seq":43,"isStar":false,"memo":"对照 有些人看待问题是悲观的(cynical),认为生活就是简单的循环(cycle),悲剧不断上演。","example":"I've always been cynical about politicians. 我对政客们总是持怀疑态度。"},{"id":2474,"unit":8,"lesson":3,"word":"cynicism","pronunciation":"/ˈsɪnɪsɪzəm/","meaning":"n.愤世嫉俗;犬儒主义","seq":44,"isStar":false},{"id":2475,"unit":8,"lesson":3,"word":"confidential","pronunciation":"/ˌkɒnfɪˈdenʃ(ə)l/","meaning":"adj.机密的,保密的;神秘的,隐秘的","seq":45,"isStar":false,"memo":"联想 confident(自信的)+-ial(形容词后缀)→枪打出头鸟,即使自信,也要隐秘一些→隐秘的","example":"Companies need to impose restrictions on confidential information. 公司需要对机密信息施加限制。"},{"id":2476,"unit":8,"lesson":3,"word":"courageous","pronunciation":"/kəˈreɪdʒəs/","meaning":"adj.勇敢的,有胆量的","seq":46,"isStar":false,"memo":"[记] (构词) courage(勇气)+-ous(形容词后缀)→勇敢的，有胆量的","example":"Youthful idealism is often courageous, and no one likes to give up dreams.青年人的理想主义往往很勇敢，没有人愿意放弃梦想。"},{"id":2477,"unit":8,"lesson":3,"word":"encourage","pronunciation":"/ɪnˈkʌrɪdʒ/","meaning":"v.支持;鼓励,激励","seq":47,"isStar":false,"memo":"构词 en-(使) + courage(勇气) → 使有勇气 → 鼓励","example":"She encouraged many young writers and artists. 她鼓励了许多年轻的作家和艺术家。"},{"id":2478,"unit":8,"lesson":3,"word":"encouragement","pronunciation":"/ɪnˈkʌrɪdʒmənt/","meaning":"n.鼓舞,鼓励","seq":48,"isStar":false},{"id":2479,"unit":8,"lesson":3,"word":"encouraging","pronunciation":"/ɪnˈkʌrɪdʒɪŋ/","meaning":"adj.鼓舞的,激励的","seq":49,"isStar":false},{"id":2480,"unit":8,"lesson":3,"word":"discourage","pronunciation":"/dɪsˈkʌrɪdʒ/","meaning":"v.使气馁,使灰心;阻止","seq":50,"isStar":false,"memo":"构词 dis-(否定前缀) + courage(勇气) → 使没有勇气 → 使气馁","example":"His parents tried to discourage him from being a singer. 他的父母试图阻止他去当歌星。"},{"id":2481,"unit":8,"lesson":3,"word":"discouraged","pronunciation":"/dɪsˈkʌrɪdʒd/","meaning":"adj.气馁的,灰心的","seq":51,"isStar":false},{"id":2482,"unit":8,"lesson":3,"word":"coward","pronunciation":"/ˈkaʊəd/","meaning":"n.懦夫,胆怯者","seq":52,"isStar":false,"memo":"谐音 单词发音类似“靠我的”→他是个“懦夫”，遇到事情只能靠我。","example":"My husband is really a coward. 我的丈夫真是一个懦夫。"},{"id":2483,"unit":8,"lesson":3,"word":"cowardly","pronunciation":"/ˈkaʊədli/","meaning":"adj.胆小的","seq":53,"isStar":false},{"id":2484,"unit":8,"lesson":3,"word":"cowardice","pronunciation":"/ˈkaʊədɪs/","meaning":"n.胆小,懦弱","seq":54,"isStar":false},{"id":2485,"unit":8,"lesson":3,"word":"timid","pronunciation":"/ˈtɪmɪd/","meaning":"adj.胆小的,羞怯的","seq":55,"isStar":false,"memo":"联想 ti(联想“提”) + mi(联想 me) + d(联想“的”) → 他是个“胆小的人”，不敢提到我。","example":"Deer are naturally timid creatures. 鹿是生性胆小的动物。"},{"id":2486,"unit":8,"lesson":3,"word":"intimidate","pronunciation":"/ɪnˈtɪmɪdeɪt/","meaning":"v.恐吓;威胁;使害怕,使失去信心","seq":56,"isStar":false,"memo":"构词 in-(使)+timid(胆小的)+-ate(动词后缀)→把人弄得胆小畏缩→恐吓，威胁，使害怕","example":"They tried to intimidate the young people into voting for them. 他们试图胁迫年轻人投票给他们。"},{"id":2487,"unit":8,"lesson":3,"word":"intimidation","pronunciation":"/ɪnˌtɪmɪˈdeɪʃn/","meaning":"n.威胁;恐吓","seq":57,"isStar":false},{"id":2488,"unit":8,"lesson":3,"word":"threat","pronunciation":"/θret/","meaning":"n.威胁,恐吓;凶兆","seq":58,"isStar":false,"memo":"构词 threat(压迫，同 threaten 威胁)→压过来的危险→威胁，恐吓；凶兆","example":"Drugs pose a major threat to our society. 毒品对社会构成重大威胁。"},{"id":2489,"unit":8,"lesson":3,"word":"threaten","pronunciation":"/ˈθret(ə)n/","meaning":"v.恐吓;预示凶兆;危及","seq":59,"isStar":false},{"id":2490,"unit":8,"lesson":3,"word":"elegant","pronunciation":"/ˈelɪɡənt/","meaning":"adj.优美的,高雅的;巧妙的","seq":60,"isStar":false,"memo":"联想 e-(出)+leg(腿)+ant(蚂蚁)→蚂蚁露出大腿,动作非常优雅→优美的,高雅的","example":"A child may grow up elegant due to his/her name. 一个孩子可能会因为他/她的名字而优雅地成长。"},{"id":2491,"unit":8,"lesson":3,"word":"elegance","pronunciation":"/ˈelɪɡəns/","meaning":"n.优雅,雅致","seq":61,"isStar":false},{"id":2492,"unit":8,"lesson":3,"word":"grace","pronunciation":"/ɡreɪs/","meaning":"n.优雅,体面;宽限期","seq":62,"isStar":false,"memo":"联想 g(联想“哥”)+race(比赛)→哥哥比赛时的动作真“优雅”。","example":"It is wise to take such gifts with gratitude and grace. 心怀感激地大方接受这些礼物才是明智的。"},{"id":2493,"unit":8,"lesson":3,"word":"graceful","pronunciation":"/ˈɡreɪsf(ə)l/","meaning":"adj.优美的;得体的","seq":63,"isStar":false},{"id":2494,"unit":8,"lesson":3,"word":"gracious","pronunciation":"/ˈɡreɪʃəs/","meaning":"adj.和蔼的,慈祥的,有礼貌的","seq":64,"isStar":false},{"id":2495,"unit":8,"lesson":3,"word":"luxury","pronunciation":"/ˈlʌkʃəri/","meaning":"n.奢华,奢侈;奢侈品","seq":65,"isStar":false,"memo":"对照 汽车品牌雷克萨斯(Lexus)以奢华(luxury)为特点。","example":"Some critics say it is a luxury and shouldn't be free to families able to pay. 一些批评人士说,这是一种奢侈品,对有支付能力的家庭不应免费。"},{"id":2496,"unit":8,"lesson":3,"word":"luxurious","pronunciation":"/lʌɡˈʒʊəriəs/","meaning":"adj.奢侈的,豪华的","seq":66,"isStar":false,"memo":"构词 lux(过度、奢侈，同 luxury 奢侈)+-urious(形容词后缀)→奢侈成性的→奢侈的，豪华的","example":"They stayed in a luxurious hotel. 他们住在一家豪华酒店。"},{"id":2497,"unit":8,"lesson":3,"word":"extravagant","pronunciation":"/ɪkˈstrævəɡənt/","meaning":"adj.奢侈的;挥霍的;过度的","seq":67,"isStar":false,"memo":"联想 ex-(往外)+trav(联想 travel)+agan(联想 again)+t(联想“他”)→他外出旅游,去了一次又一次,是很“奢侈的”。","example":"I could not have imagined how fabulous and extravagant a real Chinese banquet could be. 我没想到一场真正的中式宴会能如此的美妙和奢华。"},{"id":2498,"unit":8,"lesson":3,"word":"extravagance","pronunciation":"/ɪkˈstrævəɡəns/","meaning":"n.奢侈;挥霍,铺张浪费","seq":68,"isStar":false},{"id":2499,"unit":8,"lesson":3,"word":"reliable","pronunciation":"/rɪˈlaɪəb(ə)l/","meaning":"adj.可靠的,可信赖的","seq":69,"isStar":false,"memo":"构词 reli(=rely,依靠)+-able(形容词后缀)→可靠的","example":"We are looking for someone who is reliable and hard-working. 我们在物色可靠而又勤奋的人。"},{"id":2500,"unit":8,"lesson":3,"word":"reliance","pronunciation":"/rɪˈlaɪəns/","meaning":"n.依靠,依赖","seq":70,"isStar":false},{"id":2501,"unit":8,"lesson":3,"word":"liable","pronunciation":"/ˈlaɪəb(ə)l/","meaning":"adj.可能(易于)……的","seq":71,"isStar":false,"memo":"联想 li(音似 lie,躺)+able(音似“饿饱”)→我半夜饿了时,继续躺一会儿可能就不饿了→可能……的","example":"Being a human creation, technology is liable to errors. 作为人类创造物的技术很容易出错。"},{"id":2502,"unit":8,"lesson":3,"word":"liability","pronunciation":"/ˌlaɪəˈbɪləti/","meaning":"n.责任;累赘;负债","seq":72,"isStar":false,"memo":"构词 li(绑，同 ligature 捆扎)+-ability(名词后缀)→把你绑住的东西→责任；累赘；负债","example":"The old factory is a financial liability. 这座旧厂是财务上的负担。"},{"id":2503,"unit":8,"lesson":3,"word":"credible","pronunciation":"/ˈkredəb(ə)l/","meaning":"adj.可信的,可靠的","seq":73,"isStar":false,"memo":"cred(联想 credit,相信)+-ible(形容词后缀)→可信的,可靠的","example":"The results are hardly credible.这些结果几乎不可信。"},{"id":2504,"unit":8,"lesson":3,"word":"credibility","pronunciation":"/ˌkredəˈbɪləti/","meaning":"n.可信性,可靠性","seq":74,"isStar":false},{"id":2505,"unit":8,"lesson":3,"word":"incredible","pronunciation":"/ɪnˈkredəb(ə)l/","meaning":"adj.难以置信的;极好的;极大的","seq":75,"isStar":false,"memo":"in-（不）+cred（相信）+ible（能）→‘不能信’？结果发现太牛了反而‘难以置信’！比如室友三天背完六级词——你惊呼：‘Incredible！’（不是不信，是跪了！）","example":"The team’s comeback victory was truly incredible. 这支队伍的逆转胜利确实令人难以置信。"},{"id":2506,"unit":8,"lesson":3,"word":"sceptical/skeptical","pronunciation":"/ˈskeptɪk(ə)l/","meaning":"adj.表示怀疑的;不相信的","seq":76,"isStar":false,"memo":"构词 scept(审视，源自希腊语“观察、思辨”)+-ical(形容词后缀)→凡事都要审视的→表示怀疑的，不相信的","example":"I am sceptical about his promises. 我对他的承诺持怀疑态度。"},{"id":2507,"unit":8,"lesson":3,"word":"sceptic/sceptic","pronunciation":"/ˈskeptɪk/","meaning":"n.怀疑论者","seq":77,"isStar":false,"memo":"构词 scept(审视)+-ic(表人)→事事都要审视的人→怀疑论者","example":"He is a sceptic about online news. 他对网络新闻持怀疑态度。"},{"id":2508,"unit":8,"lesson":4,"word":"radiate","pronunciation":"/ˈreɪdieɪt/","meaning":"v.(使热、光、能量)辐射,放射;散发","seq":1,"isStar":false,"memo":"[对照] 雷达(radar)工作的时候会放射(radiate)电磁波。","example":"The metal plate behind my head radiated heat. 我脑后的金属盘散发出热量。"},{"id":2509,"unit":8,"lesson":4,"word":"radiation","pronunciation":"/ˌreɪdiˈeɪʃn/","meaning":"n.辐射;放射线","seq":2,"isStar":false,"memo":"构词 radi(光、射线，同 radio)+-ation(名词后缀)→像光线一样射出去的东西→辐射，放射线","example":"The radiation level here is still high. 这里的辐射水平仍然很高。"},{"id":2510,"unit":8,"lesson":4,"word":"radiator","pronunciation":"/ˈreɪdieɪtə(r)/","meaning":"n.散热器;暖气片","seq":3,"isStar":false},{"id":2511,"unit":8,"lesson":4,"word":"radiant","pronunciation":"/ˈreɪdiənt/","meaning":"adj.喜气洋洋的,容光焕发的;灿烂的","seq":4,"isStar":false,"memo":"构词 radi(光)+-ant(形容词后缀)→向外发光的→灿烂的；喜气洋洋的，容光焕发的；辐射的","example":"On her wedding day the bride looked truly radiant. 在她婚礼那天,新娘看起来真的是容光焕发。"},{"id":2512,"unit":8,"lesson":4,"word":"radioactive","pronunciation":"/ˌreɪdiəʊˈæktɪv/","meaning":"adj.放射性的,有辐射的","seq":5,"isStar":false,"memo":"构词 radi(射线)+-o+-active(活跃的)→自己在不断放出射线的→放射性的，有辐射的","example":"The nuclear waste is highly radioactive. 这些核废料具有高度放射性。"},{"id":2513,"unit":8,"lesson":4,"word":"radioactivity","pronunciation":"/ˌreɪdiəʊækˈtɪvəti/","meaning":"n.放射性","seq":6,"isStar":false},{"id":2514,"unit":8,"lesson":4,"word":"silicon","pronunciation":"/ˈsɪlɪkən/","meaning":"n.硅","seq":7,"isStar":false,"memo":"联想 与 silicone(硅酮)形近：做芯片的那种元素→硅","example":"The new kind of intelligent life is more likely to be made of silicon. 这种新型智能生命更有可能是由硅制成的。"},{"id":2515,"unit":8,"lesson":4,"word":"spark","pronunciation":"/spɑːk/","meaning":"n.火花,火星;一丁点 v.引发,触发","seq":8,"isStar":false,"memo":"[联想] s(音似“嘶”)+park(公园)→有人在公园里放烟花,“火花”发出嘶嘶声。","example":"This spark is the strength of conviction. 这个火花就是信念的力量。"},{"id":2516,"unit":8,"lesson":4,"word":"sparkle","pronunciation":"/ˈspɑːk(ə)l/","meaning":"n.闪烁的光;亮点 v.闪烁;生气勃勃","seq":9,"isStar":false,"memo":"[谐音] 单词发音类似“四百颗”→四百颗星星在“闪烁”。","example":"There was a sparkle of excitement in her eyes. 她眼里闪烁着激动的光芒。"},{"id":2517,"unit":8,"lesson":4,"word":"gleam","pronunciation":"/ɡliːm/","meaning":"n.微光;少量 v.发微光,闪烁;流露出","seq":10,"isStar":false,"memo":"[联想] glea(音似“隔离”)+m(联想“门”)→我路过隔离门的时候,发现门缝中透出一点儿“微光”。","example":"A few gleams of sunshine lit up the gloomy afternoon. 几缕阳光使阴暗的下午明亮起来。"},{"id":2518,"unit":8,"lesson":4,"word":"polish","pronunciation":"/ˈpɒlɪʃ/","meaning":"n.光亮剂;擦亮,磨光 v.擦亮,抛光","seq":11,"isStar":false,"memo":"[联想] pol(音似“抛”)+-ish(后缀)→抛光就是“擦亮”。","example":"I give it a polish yesterday. 昨天我把它抛光了。"},{"id":2519,"unit":8,"lesson":4,"word":"enlighten","pronunciation":"/ɪnˈlaɪt(ə)n/","meaning":"v.启发,开导;阐明","seq":12,"isStar":false,"memo":"[构词] en-(使) + light(光) + -en(动词后缀)→使有光→启发，开导","example":"It was an elite that believed its task was to enlighten the multitude. 精英人物都会认为自己的职责就是启迪民众。"},{"id":2520,"unit":8,"lesson":4,"word":"enlightenment","pronunciation":"/ɪnˈlaɪt(ə)nmənt/","meaning":"n.启迪,启发;开导","seq":13,"isStar":false},{"id":2521,"unit":8,"lesson":4,"word":"enlightening","pronunciation":"/ɪnˈlaɪt(ə)nɪŋ/","meaning":"adj.有启迪的,使人感悟的","seq":14,"isStar":false},{"id":2522,"unit":8,"lesson":4,"word":"delight","pronunciation":"/dɪˈlaɪt/","meaning":"n.高兴 v.(使)高兴;使愉快","seq":15,"isStar":false,"memo":"[联想] de(音似“弟”) + light(光)→弟弟在黑暗中突然看到一束光，非常“高兴”。","example":"He looked up at his father, his features overflowing with energy and delight. 他抬头看着父亲，脸上洋溢着活力和喜悦。"},{"id":2523,"unit":8,"lesson":4,"word":"delightful","pronunciation":"/dɪˈlaɪtf(ə)l/","meaning":"adj.使人快乐的,令人愉快的;宜人的","seq":16,"isStar":false},{"id":2524,"unit":8,"lesson":4,"word":"plight","pronunciation":"/plaɪt/","meaning":"n.苦难,困境","seq":17,"isStar":false,"memo":"联想 p(联想“扑”) + light(光) → 他的希望之光被扑灭，又陷入“困境”。","example":"The African elephant is in a desperate plight.非洲象正陷入绝境。"},{"id":2525,"unit":8,"lesson":4,"word":"dilemma","pronunciation":"/dɪˈlemə/","meaning":"n.(进退两难的)窘境,困境","seq":18,"isStar":false,"memo":"[谐音] 单词发音类似“弟来吗”→弟弟也不知道来不来→(进退两难的)窘境","example":"I could see no way of resolving this moral dilemma. 我想不出解决这一道德困境的办法。"},{"id":2526,"unit":8,"lesson":4,"word":"trap","pronunciation":"/træp/","meaning":"v.使陷入困境 n.陷阱,圈套;诡计","seq":19,"isStar":false,"memo":"[谐音] 单词发音类似“踹扑”→他被人踹了一脚，扑到“陷阱”里了。\n[对照] 他们去山区旅行(trip)，结果因为大雪陷入困境(trap)之中了。","example":"We became trapped by the rising floodwater. 我们被上涨的洪水困住了。"},{"id":2527,"unit":8,"lesson":4,"word":"strap","pronunciation":"/stræp/","meaning":"n.带子 v.用带子系(或捆、扎、扣)好","seq":20,"isStar":false,"memo":"[联想] s(联想“美女”) + trap(陷阱)→一个美女不慎落入陷阱，被人用“带子”救上来了。","example":"The bag comes with removable straps. 这种包有可拆卸的带子。"},{"id":2528,"unit":8,"lesson":4,"word":"strip","pronunciation":"/strɪp/","meaning":"v.脱光衣服;除去","seq":21,"isStar":false,"memo":"[联想] st(联想 street) + rip(撕扯)→在大街上撕扯衣服→除去，剥去","example":"He tied a strip of silk to the kite line. 他把一条丝绸系在风筝线上。"},{"id":2529,"unit":8,"lesson":4,"word":"stripe","pronunciation":"/straɪp/","meaning":"n.条纹;线条","seq":22,"isStar":false,"memo":"[联想] st(联想 street) + rip(撕扯) + e(字母音似“衣”)→她在大街上撕扯一件“条纹”衣服。","example":"The butterfly is black and white with a blue stripe running down each wing. 这蝴蝶黑白相间，每只翅膀纵贯着一道蓝色条纹。"},{"id":2530,"unit":8,"lesson":4,"word":"ignite","pronunciation":"/ɪɡˈnaɪt/","meaning":"v.点燃,(使)燃烧,着火","seq":23,"isStar":false,"memo":"[联想] ig(音似“一个”) + nite(联想 night)→在一个没有电的夜晚，我“点燃”了一根蜡烛。","example":"The fuel of the continental missile is supposed to be ignited by this device. 这枚洲际导弹的燃料应该由这个装置点燃。"},{"id":2531,"unit":8,"lesson":4,"word":"ignition","pronunciation":"/ɪɡˈnɪʃ(ə)n/","meaning":"n.点燃;点火装置","seq":24,"isStar":false,"memo":"构词 ign(火，同 ignite 点燃)+-ition(名词后缀)→起火、打火→点燃；点火装置","example":"The ignition key was still in the lock. 点火钥匙还插在锁孔里。"},{"id":2532,"unit":8,"lesson":4,"word":"illuminate","pronunciation":"/ɪˈluːmɪneɪt/","meaning":"v.照明,照亮;阐明,解释","seq":25,"isStar":false,"memo":"谐音 单词发音类似“一路明你的”→如果你的前方一路都是明亮的,说明有人在默默地给你“照亮”前路。","example":"The Earth is illuminated by the sun. 太阳照亮地球。"},{"id":2533,"unit":8,"lesson":4,"word":"illumination","pronunciation":"/ɪˌluːmɪˈneɪʃn/","meaning":"n.启示;阐明;照明","seq":26,"isStar":false},{"id":2534,"unit":8,"lesson":4,"word":"illusion","pronunciation":"/ɪˈluːʒ(ə)n/","meaning":"n.幻想,错觉","seq":27,"isStar":false,"memo":"谐音 单词发音类似“一路引”→想要人生一直有人引路,只能是“幻想”。","example":"Mirrors in a room often give an illusion of space. 房间里的镜子经常给人一种空间增大的错觉。"},{"id":2535,"unit":8,"lesson":4,"word":"illusory","pronunciation":"/ɪˈluːsəri/","meaning":"adj.虚假的,幻觉的","seq":28,"isStar":false},{"id":2536,"unit":8,"lesson":4,"word":"fantasy","pronunciation":"/ˈfæntəsi/","meaning":"n.幻想,想象","seq":29,"isStar":false,"memo":"谐音 单词发音类似“范特西”→范特西是一个爱“幻想”的人。","example":"Children use fantasy to explore worrying aspects of real life. 孩子们用幻想来探索实际生活中令人不安的各种事情。"},{"id":2537,"unit":8,"lesson":4,"word":"fantastic","pronunciation":"/fænˈtæstɪk/","meaning":"adj.极好的,了不起的;不切实际的","seq":30,"isStar":false,"memo":"构词 fant(想象，同 fantasy 幻想)+-astic(形容词后缀)→只存在于想象里的→极好的，了不起的；不切实际的","example":"This was a fantastic opportunity for students. 这对学生来说是一个极好的机会。"},{"id":2538,"unit":8,"lesson":4,"word":"fancy","pronunciation":"/ˈfænsi/","meaning":"v.认为,想象;想要","seq":31,"isStar":false,"memo":"谐音 单词发音类似“烦死”→一个人在很烦的时候可以“想象”一些美好的场景。","example":"Do you fancy going out this evening? 今晚你想不想出去?"},{"id":2539,"unit":8,"lesson":4,"word":"consider","pronunciation":"/kənˈsɪdə(r)/","meaning":"v.仔细考虑;认为","seq":32,"isStar":false,"memo":"构词 con-(一起)+sider(星星，同 sidereal 恒星的)→把星星连起来仔细端详→仔细考虑；认为","example":"I did briefly consider going on my own. 我确实短暂考虑过自己去。"},{"id":2540,"unit":8,"lesson":4,"word":"considering","pronunciation":"/kənˈsɪdərɪŋ/","meaning":"prep.&conj.考虑到;就……而言","seq":33,"isStar":false},{"id":2541,"unit":8,"lesson":4,"word":"consideration","pronunciation":"/kənˌsɪdəˈreɪʃ(ə)n/","meaning":"n.仔细考虑","seq":34,"isStar":false},{"id":2542,"unit":8,"lesson":4,"word":"considerate","pronunciation":"/kənˈsɪdərət/","meaning":"adj.体贴的,体谅的;考虑周到的","seq":35,"isStar":false,"memo":"联想 consider(考虑) + ate(eat 的过去式)→连吃都考虑到了→考虑周到的","example":"She is always polite and considerate towards her employees. 她对待雇员总是客客气气,关心体谅。"},{"id":2543,"unit":8,"lesson":4,"word":"considerable","pronunciation":"/kənˈsɪdərəb(ə)l/","meaning":"adj.相当大(或多、重要等)的","seq":36,"isStar":false,"memo":"联想 consider(考虑) + able(能够)→当回报足够多时,条件也是能够考虑的→相当大(或多、重要等)的","example":"Growing grass require considerable amounts of water. 牧草生长需要大量的水。"},{"id":2544,"unit":8,"lesson":4,"word":"negotiate","pronunciation":"/nɪˈɡəʊʃieɪt/","meaning":"v.谈判,协商;达成(协议)","seq":37,"isStar":false,"memo":"ne(音似“你”) + go(去) + ti(联想“提”) + ate(eat的过去式) → 如果你想就吃什么提建议，需要跟食堂负责人“谈判”。","example":"It is easier to negotiate initial salary requirement. 协商初始的工资要求更容易。"},{"id":2545,"unit":8,"lesson":4,"word":"negotiable","pronunciation":"/nɪˈɡəʊʃiəb(ə)l/","meaning":"adj.可协商的,可讨论的","seq":38,"isStar":false},{"id":2546,"unit":8,"lesson":4,"word":"negotiation","pronunciation":"/nɪˌɡəʊʃiˈeɪʃn/","meaning":"n.谈判,磋商,协商","seq":39,"isStar":false},{"id":2547,"unit":8,"lesson":4,"word":"hesitate","pronunciation":"/ˈhezɪteɪt/","meaning":"v.犹豫;顾虑,疑虑","seq":40,"isStar":false,"memo":"he(他) + sit(坐) + ate(eat的过去式) → 他坐在餐桌旁，“犹豫”要不要吃点东西。","example":"He was still hesitating over whether to leave or not. 他还在犹豫要不要离开。"},{"id":2548,"unit":8,"lesson":4,"word":"hesitation","pronunciation":"/ˌhezɪˈteɪʃn/","meaning":"n.犹豫,迟疑不决","seq":41,"isStar":false},{"id":2549,"unit":8,"lesson":4,"word":"hesitant","pronunciation":"/ˈhezɪtənt/","meaning":"adj.犹豫的,踌躇的","seq":42,"isStar":false},{"id":2550,"unit":8,"lesson":4,"word":"tentative","pronunciation":"/ˈtentətɪv/","meaning":"adj.试探性的;犹豫不决的,不确定的","seq":43,"isStar":false,"memo":"tent(帐篷) + (t)a(联想“他”) + ti(联想“踢”) + ve(音似“我”) → 我和同学露营时住在帐篷里，晚上他踢我，试探我睡着了没有 → 试探性的","example":"We made a tentative arrangement to meet on Friday. 我们暂定星期五见面。"},{"id":2551,"unit":8,"lesson":4,"word":"raw","pronunciation":"/rɔː/","meaning":"adj.生的,未烹制的;原始的;不熟练的","seq":44,"isStar":false,"memo":"单词发音类似“肉”→肉在最开始都是“生的”。","example":"These fish are often eaten raw. 这些鱼常常被生吃。"},{"id":2552,"unit":8,"lesson":4,"word":"crude","pronunciation":"/kruːd/","meaning":"adj.粗略的;粗鲁的,粗俗的;天然的","seq":45,"isStar":false,"memo":"单词发音类似“可辱德”→他“粗鲁的”行为可真是有辱品德。","example":"Crude oil is the world’s most important commodity. 原油是世界上最重要的商品。"},{"id":2553,"unit":8,"lesson":4,"word":"virgin","pronunciation":"/ˈvɜːdʒɪn/","meaning":"n.处女;童男;新手 adj.未开发的","seq":46,"isStar":false,"memo":"单词发音类似“我进”→我进入了一个“未开发的”原始森林。","example":"This is a virgin forest. 这是一片原始森林。"},{"id":2554,"unit":8,"lesson":4,"word":"virginity","pronunciation":"/vəˈdʒɪnəti/","meaning":"n.处女状态;童贞;原始状态","seq":47,"isStar":false},{"id":2555,"unit":8,"lesson":4,"word":"desire","pronunciation":"/dɪˈzaɪə(r)/","meaning":"n.愿望;欲望;渴望 v.渴望,期望","seq":48,"isStar":false,"memo":"de(音似“弟”) + sir(先生) + e(联想“鹅”) → 弟弟“渴望”先生讲鹅的故事。","example":"The flower scent stimulated people’s desire to buy. 花香激发了人们的购买欲。"},{"id":2556,"unit":8,"lesson":4,"word":"desirous","pronunciation":"/dɪˈzaɪərəs/","meaning":"adj.渴望的,希望的","seq":49,"isStar":false},{"id":2557,"unit":8,"lesson":4,"word":"desirable","pronunciation":"/dɪˈzaɪərəb(ə)l/","meaning":"adj.理想的;值得拥有的;值得做的","seq":50,"isStar":false,"example":"Principle is an essential and desirable element of human societies.原则是人类社会中必要且可取的要素。"},{"id":2558,"unit":8,"lesson":4,"word":"desirability","pronunciation":"/dɪˌzaɪərəˈbɪləti/","meaning":"n.希求;欲求","seq":51,"isStar":false,"memo":"构词 de-(加强)+sir(渴望，同 desire 欲望)+-ability(名词后缀)→令人想得到的性质→希求，欲求","example":"Nobody questioned the desirability of the reform. 没有人质疑这项改革的可取性。"},{"id":2559,"unit":8,"lesson":4,"word":"radical","pronunciation":"/ˈrædɪk(ə)l/","meaning":"n.激进分子 adj.激进的;根本的","seq":52,"isStar":false,"memo":"ra(联想“让”)+di(联想“弟”)+cal (音似“扣”)→弟弟那么小,你就让他学扣篮,这是一种“激进的”做法。","example":"College education should be improved through radical measures. 大学教育应该通过根本性的措施来改善。"},{"id":2560,"unit":8,"lesson":4,"word":"extreme","pronunciation":"/ɪkˈstriːm/","meaning":"adj.极度的,极端的;严重的 n.极端","seq":53,"isStar":false,"memo":"ex-(往外)+tre(音似“锤”)+me (我)→他挥舞着大锤把我往外轰,这种行为是很“严重的”,太过“极端”。","example":"They were reduced to extreme poverty. 他们沦落到极度贫困的地步。"},{"id":2561,"unit":8,"lesson":4,"word":"extremity","pronunciation":"/ɪkˈstreməti/","meaning":"n.极端,末端;尽头","seq":54,"isStar":false},{"id":2562,"unit":8,"lesson":4,"word":"despair","pronunciation":"/dɪˈspeə(r)/","meaning":"n.绝望 v.绝望,感到无望","seq":55,"isStar":false,"memo":"de(音似“弟”)+s(联想“失”)+pair (一双)→弟弟丢失了一双限量款鞋子,他快“绝望”了。","example":"I looked at my boss in despair. 我绝望地看着我的老板。"},{"id":2563,"unit":8,"lesson":4,"word":"impair","pronunciation":"/ɪmˈpeə(r)/","meaning":"v.损害;削弱","seq":56,"isStar":false,"memo":"i(我)+m(联想“妹”)+pair(一双)→我妹妹长期看手机,一双眼睛都受到了“损害”。","example":"It's well known that obesity impairs sleep. 众所周知,肥胖会损害睡眠。"},{"id":2564,"unit":8,"lesson":4,"word":"dismay","pronunciation":"/dɪsˈmeɪ/","meaning":"n.灰心,丧气;惊愕 v.使失望,使惊愕","seq":57,"isStar":false,"memo":"di(联想“弟”)+s(联想“似”)+may (音似“妹”)→弟弟听说他和妹妹很相似,十分“惊愕”。","example":"To her dismay, her name was not on the list. 令她惊愕的是,名单上没有她的名字。"},{"id":2565,"unit":8,"lesson":4,"word":"diminish","pronunciation":"/dɪˈmɪnɪʃ/","meaning":"v.减少,(使)减弱,降低;贬低","seq":58,"isStar":false,"memo":"di(联想“弟”)+mi(音似“妹”)+ni (联想“你”)+sh(音似“失”)→有了弟弟妹妹的陪伴,你的烦恼“减少”,痛苦消失。","example":"The world's resources are rapidly diminishing. 世界资源正在迅速减少。"},{"id":2566,"unit":8,"lesson":4,"word":"desperate","pronunciation":"/ˈdespərət/","meaning":"adj.拼命的;绝望的;非常需要的","seq":59,"isStar":false,"memo":"构词 de-(去掉)+sper(希望，同 prosper 繁荣)+-ate(形容词后缀)→把希望都丢掉了→绝望的；拼命的；危急的","example":"I was lucky that my last desperate attempt led to a job. 很幸运,最后一次绝望的尝试让我找到了一份工作。"},{"id":2567,"unit":8,"lesson":4,"word":"discrepancy","pronunciation":"/dɪˈskrepənsi/","meaning":"n.差异;不符合,不一致","seq":60,"isStar":false,"memo":"构词 dis-(分开)+crep(不一致，源自“发出不同声响”)+-ancy(名词后缀)→两边对不上口径→差异，不符合，不一致","example":"Why is there such a discrepancy between the ideal and the reality? 为什么理想与现实之间存在如此大的差异呢?"},{"id":2568,"unit":8,"lesson":4,"word":"destiny","pronunciation":"/ˈdestəni/","meaning":"n.命运,天命,天数","seq":61,"isStar":false,"memo":"de(联想“的”)+s(形似弯曲的路)+tiny(小的)→走的每条弯路,做的每个微小选择,共同构成了一个人的“命运”。","example":"It was extremely important to the destiny of humankind. 这对人类的命运至关重要。"},{"id":2569,"unit":8,"lesson":4,"word":"destined","pronunciation":"/ˈdestɪnd/","meaning":"adj.预定;注定的","seq":62,"isStar":false,"memo":"联想 de(音似“弟”) + liberate(解放，使自由) → 弟弟能不能零食自由需要妈妈“仔细考虑”。","example":"She seemed destined for a successful career.她似乎注定会事业有成。"},{"id":2570,"unit":8,"lesson":4,"word":"deliberate","pronunciation":"/dɪˈlɪbərət/","meaning":"adj.故意的,蓄意的","seq":63,"isStar":false,"memo":"de(音似“弟”)+liberate(解放,使自由)→弟弟能不能零食自由需要妈妈“仔细考虑”。","example":"Witnesses said the firing was deliberate and sustained.目击者说枪击是蓄意的,而且持续了很长时间。"},{"id":2571,"unit":8,"lesson":4,"word":"deliberation","pronunciation":"/dɪˌlɪbəˈreɪʃ(ə)n/","meaning":"n.审议,考虑;审慎","seq":64,"isStar":false},{"id":2572,"unit":8,"lesson":4,"word":"liberate","pronunciation":"/ˈlɪbəreɪt/","meaning":"v.解放;使自由,使摆脱约束(或限制)","seq":65,"isStar":false,"memo":"liber(音似“隶搏”)+-ate(动词后缀)→奴隶努力拼搏来争取自由→解放;使自由","example":"Their mission was to liberate the thousands who had been enslaved.他们的任务是解放成千上万被奴役的人。"},{"id":2573,"unit":8,"lesson":4,"word":"liberal","pronunciation":"/ˈlɪbərəl/","meaning":"adj.开明的;自由的,开放的","seq":66,"isStar":false,"memo":"liber（自由）+al→自由派！联想‘李伯尔’老师上课从不点名，超liberal～","example":"She holds liberal views on gender equality. 她在性别平等问题上持开明观点。"},{"id":2574,"unit":8,"lesson":4,"word":"liberty","pronunciation":"/ˈlɪbəti/","meaning":"n.自由","seq":67,"isStar":false},{"id":2575,"unit":8,"lesson":4,"word":"liberation","pronunciation":"/ˌlɪbəˈreɪʃ(ə)n/","meaning":"n.解放","seq":68,"isStar":false},{"id":2576,"unit":8,"lesson":4,"word":"statue","pronunciation":"/ˈstætʃuː/","meaning":"n.雕塑,雕像","seq":69,"isStar":false,"memo":"sta(联想 stand)+tue(音似“矗”)→站立、矗立的建筑物→雕像","example":"He illuminated the Statue of Liberty.他点亮了自由女神像。"},{"id":2577,"unit":8,"lesson":4,"word":"contemplate","pronunciation":"/ˈkɒntəmpleɪt/","meaning":"v.考虑;沉思,深思熟虑","seq":70,"isStar":false,"memo":"con-(所有)+templ(联想 temple)+ate→听闻这一切,寺庙里的所有人都陷入了“沉思”。","example":"The government has contemplated reforming the entire tax system.政府已经考虑改革整个税收制度。"},{"id":2578,"unit":8,"lesson":4,"word":"contemplation","pronunciation":"/ˌkɒntəmˈpleɪʃ(ə)n/","meaning":"n.深思,沉思,冥想,默默注视","seq":71,"isStar":false},{"id":2579,"unit":8,"lesson":4,"word":"contemplative","pronunciation":"/kənˈtemplətɪv/","meaning":"adj.深思熟虑的,冥想的","seq":72,"isStar":false},{"id":2580,"unit":8,"lesson":4,"word":"digest","pronunciation":"/daɪˈdʒest/","meaning":"n.文摘,摘要 v.消化;领悟,理解","seq":73,"isStar":false,"memo":"di-(两个)+ge(联想“哥”)+st(联想 street)→两个哥哥吃了太多,要去街上散步,“消化”一下。","example":"The child can't digest complex information yet.这个孩子还不能领悟复杂的信息。"},{"id":2581,"unit":8,"lesson":4,"word":"digestion","pronunciation":"/daɪˈdʒestʃən; dɪˈdʒestʃən/","meaning":"n.消化,消化能力","seq":74,"isStar":false},{"id":2582,"unit":8,"lesson":4,"word":"digestive","pronunciation":"/daɪˈdʒestɪv/","meaning":"adj.消化的,和消化有关的","seq":75,"isStar":false},{"id":2583,"unit":9,"lesson":1,"word":"vulgar","pronunciation":"/ˈvʌlɡə(r)/","meaning":"adj.粗俗的,粗野的;庸俗的","seq":1,"isStar":false,"memo":"谐音：单词发音类似“哇哥”→哥哥穿了一件没有品位的衣服，我大吃一惊，觉得他是“庸俗的”。","example":"They told some vulgar jokes. 他们讲了一些低俗的笑话。"},{"id":2584,"unit":9,"lesson":1,"word":"garment","pronunciation":"/ˈɡɑːmənt/","meaning":"n.(一件)衣服","seq":2,"isStar":false,"memo":"联想：gar(音似“尬”) + m(联想“妹”) + ent →妹妹的“衣服”破了，很尴尬。","example":"He hired a garment. 他租了一件衣服。"},{"id":2585,"unit":9,"lesson":1,"word":"glory","pronunciation":"/ˈɡlɔːri/","meaning":"n.荣誉;赞美;辉煌","seq":3,"isStar":false,"memo":"谐音：单词发音类似“哥捞日”→哥哥要是能把太阳打捞上来，那可是无上的“荣誉”。","example":"The brave soldiers earned everlasting glory. 英勇的战士们赢得了永恒的荣誉。"},{"id":2586,"unit":9,"lesson":1,"word":"glorious","pronunciation":"/ˈɡlɔːriəs/","meaning":"adj.光荣的;辉煌的;壮丽的","seq":4,"isStar":false,"memo":"构词 glori(光荣，同 glory 荣耀)+-ous(形容词后缀)→充满荣耀的→光荣的；辉煌的，壮丽的","example":"Human civilization remains glorious, though it is affected by climate change. 人类文明虽然受到气候变化的影响，但依然辉煌。"},{"id":2587,"unit":9,"lesson":1,"word":"hono(u)r","pronunciation":"/ˈɒnə(r)/","meaning":"n.尊敬;荣幸;荣誉 v.尊重(某人)","seq":5,"isStar":false,"memo":"构词 hon(尊敬，同 honest 诚实的)+-our(名词后缀)→对人的敬意与荣誉→尊敬；荣誉；尊重，给予表扬","example":"You deserve the honour.这份荣誉你当之无愧。"},{"id":2588,"unit":9,"lesson":1,"word":"hono(u)rable","pronunciation":"/ˈɒnərəb(ə)l/","meaning":"adj.可敬的,值得钦佩的","seq":6,"isStar":false,"memo":"构词 honour(荣誉)+-able(可…的)→配得上荣誉的→可敬的，值得钦佩的","example":"He is an honourable man who always keeps his word. 他是个恪守诺言的可敬之人。"},{"id":2589,"unit":9,"lesson":1,"word":"honorary","pronunciation":"/ˈɒnərəri/","meaning":"adj.荣誉的;名誉的","seq":7,"isStar":false},{"id":2590,"unit":9,"lesson":1,"word":"challenge","pronunciation":"/ˈtʃælɪndʒ/","meaning":"v.挑战;对……怀疑(或质疑) n.挑战","seq":8,"isStar":false,"memo":"联想：cha(联想“叉”) + lle(联想“了”) + n(联想“牛”) + ge(联想“哥”) →弟弟吃饭时用叉子叉了哥哥的牛排，这是在“挑战”他的耐心。","example":"Its validity was challenged by many communities. 它的有效性受到了许多社区的质疑。"},{"id":2591,"unit":9,"lesson":1,"word":"challenging","pronunciation":"/ˈtʃælɪndʒɪŋ/","meaning":"adj.挑战性的","seq":9,"isStar":false},{"id":2592,"unit":9,"lesson":1,"word":"trigger","pronunciation":"/ˈtrɪɡə(r)/","meaning":"v.引发,引起,触发 n.扳机;起因","seq":10,"isStar":false,"memo":"谐音 单词发音类似“捶哥”→他捶了哥哥，“引发”了矛盾。","example":"Even a tiny amount of food may trigger an allergic reaction. 即使是极少量的食物也可能引发过敏反应。"},{"id":2593,"unit":9,"lesson":1,"word":"lag","pronunciation":"/læɡ/","meaning":"v.发展缓慢;滞后,落后于","seq":11,"isStar":false,"memo":"谐音 单词发音类似“拉哥”→哥哥落后了，需要我拉着他跑→落后于","example":"She did well in her first year at school but then started to lag behind. 她在校第一年成绩很好,但后来就开始落后了。"},{"id":2594,"unit":9,"lesson":1,"word":"lame","pronunciation":"/leɪm/","meaning":"adj.跛的;没有说服力的","seq":12,"isStar":false,"memo":"联想 la(联想“拉”) + me(我)→你需要拉我一下,因为我有点跛足→跛的","example":"He didn't agree with her lame arguments. 他不同意她蹩脚的观点。"},{"id":2595,"unit":9,"lesson":1,"word":"tame","pronunciation":"/teɪm/","meaning":"adj.(动物)驯服的;温顺的 v.驯服","seq":13,"isStar":false,"memo":"联想 ta(联想“她”) + me(我)→她“制服”了顽劣的我,并帮助我变得更好。","example":"Asian elephants are easier to tame than African elephants. 亚洲象比非洲象更容易驯服。"},{"id":2596,"unit":9,"lesson":1,"word":"melt","pronunciation":"/melt/","meaning":"v.(使)融化,(使)熔化","seq":14,"isStar":false,"memo":"联想 me(我) + l(联想“了”) + t(联想“他”)→我“融化”了他内心的坚冰。","example":"The sun melted the snow. 阳光融化了积雪。"},{"id":2597,"unit":9,"lesson":1,"word":"range","pronunciation":"/reɪndʒ/","meaning":"n.一系列;范围;种类","seq":15,"isStar":false,"memo":"联想 ran(run 的过去式) + ge(联想“哥”)→哥哥一般在一定的“范围”内跑步。","example":"The average age range is between 35 and 55. 平均年龄范围是35岁至55岁。"},{"id":2598,"unit":9,"lesson":1,"word":"arrange","pronunciation":"/əˈreɪndʒ/","meaning":"v.安排;整理,排列","seq":16,"isStar":false,"memo":"联想 ar-(一再地) + range(范围)→我们的能力都是有限的,只能在一定的范围内“安排”事情。","example":"She helped him arrange the furniture. 她帮他整理家具。"},{"id":2599,"unit":9,"lesson":1,"word":"arrangement","pronunciation":"/əˈreɪndʒmənt/","meaning":"n.安排;整理;约定","seq":17,"isStar":false},{"id":2600,"unit":9,"lesson":1,"word":"engage","pronunciation":"/ɪnˈɡeɪdʒ/","meaning":"v.参加;吸引(某人的兴趣);雇用,聘用","seq":18,"isStar":false,"memo":"构词 en-(使)+gage(抵押、保证)→使作出保证并投入进去→参加；吸引(兴趣)；雇用","example":"It is a movie that engages both the mind and the eye. 这是一部令人赏心悦目的影片。"},{"id":2601,"unit":9,"lesson":1,"word":"engagement","pronunciation":"/ɪnˈɡeɪdʒmənt/","meaning":"n.订婚;约定","seq":19,"isStar":false},{"id":2602,"unit":9,"lesson":1,"word":"pregnant","pronunciation":"/ˈpreɡnənt/","meaning":"adj.怀孕的;意味深长的","seq":20,"isStar":false,"memo":"构词 pre-(在前)+gn(出生，同 generate 产生)+-ant(形容词后缀)→孩子出生之前的状态→怀孕的；意味深长的","example":"My sister is pregnant with twins. 我妹妹怀了一对双胞胎。"},{"id":2603,"unit":9,"lesson":1,"word":"pregnancy","pronunciation":"/ˈpreɡnənsi/","meaning":"n.妊娠,怀孕","seq":21,"isStar":false},{"id":2604,"unit":9,"lesson":1,"word":"divorce","pronunciation":"/dɪˈvɔːs/","meaning":"n.&v.离婚;分离","seq":22,"isStar":false,"memo":"谐音 单词发音类似“敌我死”→他们视对方如仇敌,每天斗个你死我活,最后“离婚”了。\n联想 di-(分开) + vorce(音似 voice)→夫妻双方经常表达两种声音,这可能会导致“离婚”。","example":"Financial stress is a chief reason for divorce. 经济压力是离婚的一个首要原因。"},{"id":2605,"unit":9,"lesson":1,"word":"single","pronunciation":"/ˈsɪŋɡ(ə)l/","meaning":"adj.单一的;单人的","seq":23,"isStar":false,"memo":"构词 singl(单个，同 singular 单数的)+-e→只有一个的→单一的；单人的，单身的；单程票","example":"They organize parties for singles.他们为单身人士组织聚会。"},{"id":2606,"unit":9,"lesson":1,"word":"dual","pronunciation":"/ˈdjuːəl/","meaning":"adj.双重的,两部分的","seq":24,"isStar":false,"memo":"构词 du(二，同 duo 二重奏)+-al(形容词后缀)→涉及两方面的→双重的，两部分的","example":"The piece of furniture serves a dual purpose as a cupboard and as a table. 这件家具有两个用途，既作橱柜，也作饭桌。"},{"id":2607,"unit":9,"lesson":1,"word":"duplicate","pronunciation":"/ˈdjuːplɪkeɪt/","meaning":"v.复制,复印 adj.复制的","seq":25,"isStar":false,"memo":"对照：复印（duplicate）可实现一份变双（double）份。","example":"Is this a duplicate or the original? 这是副本还是正本？"},{"id":2608,"unit":9,"lesson":1,"word":"duplication","pronunciation":"/ˌdjuːplɪˈkeɪʃ(ə)n/","meaning":"n.复制;重复","seq":26,"isStar":false},{"id":2609,"unit":9,"lesson":1,"word":"reproduce","pronunciation":"/ˌriːprəˈdjuːs/","meaning":"v.复制;再生产,再现;繁殖","seq":27,"isStar":false,"memo":"构词 re-(再)+produce(生产)→再产生一遍→复制；再生产，再现；繁殖","example":"There was no method to reproduce the results. 过去没有能够再现成果的方法。"},{"id":2610,"unit":9,"lesson":1,"word":"reproduction","pronunciation":"/ˌriːprəˈdʌkʃn/","meaning":"n.生殖,繁殖;复制","seq":28,"isStar":false},{"id":2611,"unit":9,"lesson":1,"word":"reproductive","pronunciation":"/ˌriːprəˈdʌktɪv/","meaning":"adj.生殖的,繁殖的","seq":29,"isStar":false},{"id":2612,"unit":9,"lesson":1,"word":"couple","pronunciation":"/ˈkʌp(ə)l/","meaning":"n.两人;一对,夫妇;几个 v.连接","seq":30,"isStar":false,"memo":"谐音：单词发音类似“靠谱”→她认为，只有“两人”都觉得对方靠谱，他们才有可能结为“夫妇”。","example":"They are a couple in the real world as well as in the movie. 他们在电影和现实生活中都是一对夫妇。"},{"id":2613,"unit":9,"lesson":1,"word":"coupon","pronunciation":"/ˈkuːpɒn/","meaning":"n.优惠券","seq":31,"isStar":false,"memo":"谐音 “苦胖”：靠优惠券省下钱才不至于又苦又胖→优惠券","example":"Coupons can help you save money.优惠券能帮你省钱。"},{"id":2614,"unit":9,"lesson":1,"word":"prestige","pronunciation":"/preˈstiːʒ/","meaning":"n.威望,声望","seq":32,"isStar":false,"memo":"联想：pre-(……前的，预先) + s(联想“死”) + ti(联想“提”) + ge(联想“哥”) → 在我们见面前，他死(一直)提自己的哥哥，是因为他哥哥有“声望”。","example":"He was admitted to a university of high prestige. 他被一所声望很高的大学录取了。"},{"id":2615,"unit":9,"lesson":1,"word":"prestigious","pronunciation":"/preˈstɪdʒəs/","meaning":"adj.有威望的;声誉高的","seq":33,"isStar":false},{"id":2616,"unit":9,"lesson":1,"word":"reputation","pronunciation":"/ˌrepjuˈteɪʃ(ə)n/","meaning":"n.名声,名誉","seq":34,"isStar":false,"memo":"联想：re-(重复) + put(放) + -ation(名词后缀) → 反复把他的名字放到最前面，说明他的“名声”最大。","example":"The hotel has a good reputation for service. 这家酒店以服务好而闻名。"},{"id":2617,"unit":9,"lesson":1,"word":"renown","pronunciation":"/rɪˈnaʊn/","meaning":"n.名誉,声誉","seq":35,"isStar":false,"memo":"[联想] re-(重复) + nown(联想 known)→重复地被知道，表明这个人很有“声誉”。","example":"He won renown as a fair judge. 他赢得了公正裁判的荣誉。"},{"id":2618,"unit":9,"lesson":1,"word":"renowned","pronunciation":"/rɪˈnaʊnd/","meaning":"adj.有名望的,著名的","seq":36,"isStar":false},{"id":2619,"unit":9,"lesson":1,"word":"notable","pronunciation":"/ˈnəʊtəb(ə)l/","meaning":"adj.值得注意的;显著的,显要的","seq":37,"isStar":false,"memo":"[构词] not(e)(注意) + -able(形容词后缀)→值得注意的；显著的，显要的","example":"It cannot be said that the dinner was a notable success socially. 不能说那次晚宴在社交方面取得了显著的成功。"},{"id":2620,"unit":9,"lesson":1,"word":"notation","pronunciation":"/nəʊˈteɪʃn/","meaning":"n.符号,记号","seq":38,"isStar":false},{"id":2621,"unit":9,"lesson":1,"word":"noteworthy","pronunciation":"/ˈnəʊtwɜːði/","meaning":"adj.值得注意的;显著的,重要的","seq":39,"isStar":false,"memo":"[构词] note(注意) + worthy(值得的)→值得注意的","example":"The bridge is noteworthy for its sheer size. 这座桥以宏伟闻名。"},{"id":2622,"unit":9,"lesson":1,"word":"anonymous","pronunciation":"/əˈnɒnɪməs/","meaning":"adj.匿名的,不知姓名的;无特色的","seq":40,"isStar":false,"memo":"[联想] a-(一个) + no(没有) + nym(音似 name) + -ous(形容词后缀)→一个没有名字的→匿名的","example":"The money was donated by a local businessman who wishes to remain anonymous. 这笔款项是当地一位不愿透露姓名的企业家捐赠的。"},{"id":2623,"unit":9,"lesson":1,"word":"anonymity","pronunciation":"/ˌænəˈnɪməti/","meaning":"n.匿名;无特色","seq":41,"isStar":false},{"id":2624,"unit":9,"lesson":1,"word":"notorious","pronunciation":"/nəʊˈtɔːriəs/","meaning":"adj.声名狼藉的,臭名昭著的","seq":42,"isStar":false,"memo":"构词 not(知道，同 notice 注意)+-orious(形容词后缀)→人人都知道的(坏名声)→声名狼藉的，臭名昭著的","example":"The country is notorious for its appalling prison conditions. 这个国家因监狱状况恶劣而臭名远扬。"},{"id":2625,"unit":9,"lesson":1,"word":"notoriety","pronunciation":"/ˌnəʊtəˈraɪəti/","meaning":"n.恶名,坏名声","seq":43,"isStar":false},{"id":2626,"unit":9,"lesson":1,"word":"esteem","pronunciation":"/ɪˈstiːm/","meaning":"n.&v.尊重;敬重","seq":44,"isStar":false,"memo":"谐音 单词发音类似“一丝提门”→ 他很有力气，用一根丝就能把门提起来，很受人“尊重”。","example":"He is a highly esteemed scientist.他是一位备受尊敬的科学家。"},{"id":2627,"unit":9,"lesson":1,"word":"dignity","pronunciation":"/ˈdɪɡnəti/","meaning":"n.尊严;庄重,体面;自尊心","seq":45,"isStar":false,"memo":"[联想] dig(挖) + nity(联想“泥土”)→想赢得“尊严”，最好从底层干起，就像盖房子要先从挖泥土开始一样，一步步走向成功。","example":"Workers should be treated with dignity. 工人应该受到有尊严的对待。"},{"id":2628,"unit":9,"lesson":1,"word":"dignify","pronunciation":"/ˈdɪɡnɪfaɪ/","meaning":"v.使有尊严;使崇高","seq":46,"isStar":false},{"id":2629,"unit":9,"lesson":1,"word":"indignant","pronunciation":"/ɪnˈdɪɡnənt/","meaning":"adj.愤怒的,愤愤不平的","seq":47,"isStar":false,"memo":"[联想] in-(否定前缀) + dign(联想 dignity) + -ant(形容词后缀)→别人让我们没有尊严的时候，我们往往是“愤怒的”。","example":"He became very indignant when his son made a mistake. 当儿子犯错时，他变得非常气愤。"},{"id":2630,"unit":9,"lesson":1,"word":"indignation","pronunciation":"/ˌɪndɪɡˈneɪʃ(ə)n/","meaning":"n.愤慨,愤怒","seq":48,"isStar":false},{"id":2631,"unit":9,"lesson":1,"word":"indigenous","pronunciation":"/ɪnˈdɪdʒənəs/","meaning":"adj.土生土长的,本地的","seq":49,"isStar":false,"memo":"[联想] in(里面) + dig(挖) + enous→能在这座山里挖东西的人，大概率是“本地的”居民。","example":"Are blueberries indigenous to America? 蓝莓原产于美国吗？"},{"id":2632,"unit":9,"lesson":1,"word":"reveal","pronunciation":"/rɪˈviːl/","meaning":"v.揭示;透露,展现,显露","seq":50,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + veal(音似“围殴”)→阿姨报警说一群人在围殴一个老人,并帮警察揭开了那群人的真面目→揭示","example":"He revealed that the man who saved him was a stranger. 他透露,救他的人是一个陌生人。"},{"id":2633,"unit":9,"lesson":1,"word":"revelation","pronunciation":"/ˌrevəˈleɪʃ(ə)n/","meaning":"n.被揭露的真相;披露,揭露","seq":51,"isStar":false,"memo":"构词 reve(a) l(揭示;透露) + -ation(名词后缀)→披露,揭露","example":"He feared the revelation of the truth. 他害怕真相被披露。"},{"id":2634,"unit":9,"lesson":1,"word":"release","pronunciation":"/rɪˈliːs/","meaning":"v.&n.释放;发布,发行","seq":52,"isStar":false,"memo":"联想 re-(再) + lease(音似“立誓”)→他再次立誓要减肥,并“发布”了这一消息。","example":"The police arrested several men, who were released later. 警察逮捕了几个人,他们后来被释放了。"},{"id":2635,"unit":9,"lesson":1,"word":"veil","pronunciation":"/veɪl/","meaning":"n.面纱;薄薄的遮盖层 v.戴面纱;遮掩","seq":53,"isStar":false,"memo":"联想 与 reveal(揭开)互为反义：reveal 就是“去掉(re-)面纱(veil)”→面纱；遮掩","example":"As the mountains were covered with a veil of cloud, we couldn't see their tops. 因为群山被一层云覆盖,所以我们看不见山顶。"},{"id":2636,"unit":9,"lesson":1,"word":"unveil","pronunciation":"/ˌʌnˈveɪl/","meaning":"v.为……揭幕;将……公之于众,展示","seq":54,"isStar":false,"memo":"构词 un-(否定前缀) + veil(戴面纱)→不戴面纱→将……公之于众","example":"The European Union unveiled a plan to cut energy use.欧盟公布了一项削减能源使用的计划。"},{"id":2637,"unit":9,"lesson":1,"word":"mask","pronunciation":"/mɑːsk/","meaning":"n.面具;伪装,掩饰 v.掩饰,遮盖","seq":55,"isStar":false,"memo":"联想 m(联想“妹”) + ask(问)→妹妹很害羞,问问题总是遮遮掩掩→掩饰,遮盖","example":"She masked her anger with a smile. 她用微笑掩饰愤怒。"},{"id":2638,"unit":9,"lesson":1,"word":"disclose","pronunciation":"/dɪsˈkləʊz/","meaning":"v.揭露,透露,泄露","seq":56,"isStar":false,"memo":"构词 dis-(否定前缀) + close(关闭) → 揭露，透露，泄露","example":"Neither side would disclose details of the transaction. 双方都不会透露交易的细节。"},{"id":2639,"unit":9,"lesson":1,"word":"disclosure","pronunciation":"/dɪsˈkləʊʒə(r)/","meaning":"n.揭露,透露,公开","seq":57,"isStar":false},{"id":2640,"unit":9,"lesson":1,"word":"enclose","pronunciation":"/ɪnˈkləʊz/","meaning":"v.把……围起来;随信附上","seq":58,"isStar":false,"memo":"构词 en-(使……) + close(关闭) → 使关上 → 把……围起来","example":"Seconds later, the car was enclosed in flames. 几秒钟后，汽车被火焰包围。"},{"id":2641,"unit":9,"lesson":1,"word":"enclosure","pronunciation":"/ɪnˈkləʊʒə(r)/","meaning":"n.围场;(信中的)附件","seq":59,"isStar":false},{"id":2642,"unit":9,"lesson":1,"word":"closet","pronunciation":"/ˈklɒzɪt/","meaning":"n.壁橱 adj.隐藏(身份等)的","seq":60,"isStar":false,"memo":"联想 close(关闭) + t(联想“它”) → 关闭“壁橱”的门。","example":"In department stores and closets all over the world, they are waiting. 在世界各地的百货商店以及壁橱里，它们一直在等待。"},{"id":2643,"unit":9,"lesson":1,"word":"conceal","pronunciation":"/kənˈsiːl/","meaning":"v.隐藏,隐瞒;掩盖","seq":61,"isStar":false,"memo":"联想 con-(都) + ceal(联想 seal,封上) → 都封上了 → 隐藏，隐瞒；掩盖","example":"He wanted to conceal something from his parents. 他想对父母隐瞒一些事情。"},{"id":2644,"unit":9,"lesson":1,"word":"concealment","pronunciation":"/kənˈsiːlmənt/","meaning":"n.隐藏,隐瞒;掩盖","seq":62,"isStar":false},{"id":2645,"unit":9,"lesson":1,"word":"disguise","pronunciation":"/dɪsˈɡaɪz/","meaning":"v.伪装,掩饰 n.伪装物","seq":63,"isStar":false,"memo":"联想 dis-(音似“弟似”) + gui(联想“鬼”) + se→万圣节晚上，弟弟把自己装扮成鬼的样子→伪装","example":"It's an obligation disguised as an option. 它是一项伪装成选项的义务。"},{"id":2646,"unit":9,"lesson":1,"word":"fabricate","pronunciation":"/ˈfæbrɪkeɪt/","meaning":"v.编造,捏造;制造","seq":64,"isStar":false,"memo":"联想 fabri(联想“发布日”) + cate(音似“剋他”)→在他的新专辑发布日，会有一群人去现场剋(打)他，这是有人“捏造”的谣言。","example":"It angers me that people would fabricate a story like that. 人们会编造这样的故事，这让我感到愤怒。"},{"id":2647,"unit":9,"lesson":1,"word":"fabrication","pronunciation":"/ˌfæbrɪˈkeɪʃ(ə)n/","meaning":"n.捏造的信息","seq":65,"isStar":false},{"id":2648,"unit":9,"lesson":1,"word":"fabric","pronunciation":"/ˈfæbrɪk/","meaning":"n.织物,布料","seq":66,"isStar":false,"memo":"构词 fabr(制作，同 fabricate 制造)+-ic→织造出来的东西→织物，布料；结构","example":"Individual sins affect the entire fabric of society. 个人的罪行影响整个社会的结构。"},{"id":2649,"unit":9,"lesson":1,"word":"texture","pronunciation":"/ˈtekstʃə(r)/","meaning":"n.质地;手感;口感","seq":67,"isStar":false,"memo":"联想 text(课本) + (t)ure(联想 true)→课本的“质地”真的很好。","example":"They would not be able to tell the texture of objects. 他们将无法分辨物体的质地。"},{"id":2650,"unit":9,"lesson":1,"word":"lubricate","pronunciation":"/ˈluːbrɪkeɪt/","meaning":"v.给……上润滑油;使润滑","seq":68,"isStar":false,"memo":"对照 lube n.润滑油→lubricate v.","example":"Training can make muscles stronger and keep joints lubricated. 训练可以使肌肉更强壮并保持关节的润滑。"},{"id":2651,"unit":9,"lesson":1,"word":"lubrication","pronunciation":"/ˌluːbrɪˈkeɪʃn/","meaning":"n.润滑","seq":69,"isStar":false},{"id":2652,"unit":9,"lesson":1,"word":"grease","pronunciation":"/ɡriːs/","meaning":"n.油脂 v.给……加润滑油","seq":70,"isStar":false,"memo":"联想 gr(联想“官人”) + ease(放松)→官人要去做推拿放松一下，做之前在身上涂“油脂”。","example":"Her hands were covered with oil and grease. 她满手油垢。"},{"id":2653,"unit":9,"lesson":1,"word":"greasy","pronunciation":"/ˈɡriːsi/","meaning":"adj.多油的;油污的,沾油脂的","seq":71,"isStar":false},{"id":2654,"unit":9,"lesson":1,"word":"temporary","pronunciation":"/ˈtemprəri/","meaning":"adj.暂时的,临时的;短暂的","seq":72,"isStar":false,"memo":"[构词] tempor(时间)+-ary(后缀)→暂时的,临时的","example":"The woman needs a temporary replacement for her assistant. 这位女士需要一个临时工代替她的助理。"},{"id":2655,"unit":9,"lesson":1,"word":"temporarily","pronunciation":"/ˈtemprərəli/","meaning":"adv.临时地;短暂地","seq":73,"isStar":false},{"id":2656,"unit":9,"lesson":1,"word":"contemporary","pronunciation":"/kənˈtemp(ə)rəri/","meaning":"n.同代人;同龄人 adj.同时代的","seq":74,"isStar":false,"memo":"[联想] con-(所有的)+temporary(暂时的)→所有人只能暂时跟上“当代的”节奏。","example":"He was a contemporary of Freud. 他是弗洛伊德的同代人。"},{"id":2657,"unit":9,"lesson":1,"word":"temporal","pronunciation":"/ˈtempərəl/","meaning":"adj.时间的;短暂的;世俗的","seq":75,"isStar":false,"memo":"构词 tempor(时间，同 temporary 暂时的)+-al(形容词后缀)→与时间相关的→时间的；短暂的；世俗的","example":"One is also able to see how specific acts are related to a temporal and spatial context.人们还能看到特定行为与时间空间背景的关系。"},{"id":2658,"unit":9,"lesson":1,"word":"occasion","pronunciation":"/əˈkeɪʒ(ə)n/","meaning":"n.特殊场合;时机","seq":76,"isStar":false,"memo":"构词 oc-(加强)+cas(落下，同 casual 偶然的)+-ion(名词后缀)→事情恰好落下的那一刻→时机，特殊场合","example":"It is natural to desire to do so for special occasions. 在特殊场合想这样做是很正常的。"},{"id":2659,"unit":9,"lesson":1,"word":"occasional","pronunciation":"/əˈkeɪʒən(ə)l/","meaning":"adj.偶尔的;临时的","seq":77,"isStar":false},{"id":2660,"unit":9,"lesson":1,"word":"occasionally","pronunciation":"/əˈkeɪʒnəli/","meaning":"adv.偶然,偶尔,有时候","seq":78,"isStar":false},{"id":2661,"unit":9,"lesson":1,"word":"coincide","pronunciation":"/ˌkəʊɪnˈsaɪd/","meaning":"v.同时发生;相符,一致","seq":79,"isStar":false,"memo":"构词 co-(共同)+in-(在…上)+cid(落下，同 accident 事故)+-e→一起落在同一点上→同时发生；相符，一致","example":"Let the time for learning coincide with the time when your memory is at its best. 要让学习的时间与你记忆力最好的时间相吻合。"},{"id":2662,"unit":9,"lesson":1,"word":"coincidence","pronunciation":"/kəʊˈɪnsɪdəns/","meaning":"n.巧合;同时发生","seq":80,"isStar":false,"memo":"[联想] coin(硬币)+cide(联想 side)+nce→抛硬币连续多次出现正面,这是“巧合”。","example":"It was such a coincidence when Pat and Mike met each other in Tokyo. 帕特和迈克在东京相遇,真是太巧了。"},{"id":2663,"unit":9,"lesson":1,"word":"incidence","pronunciation":"/ˈɪnsɪdəns/","meaning":"n.发生率","seq":81,"isStar":false,"memo":"构词 in-(在…上)+cid(落下)+-ence(名词后缀)→事情落下来的频次→发生率","example":"It helps reduce the incidence of heart disease. 它有助于减少心脏病的发病率。"},{"id":2664,"unit":9,"lesson":1,"word":"incident","pronunciation":"/ˈɪnsɪdənt/","meaning":"n.事件;(两国间的)冲突","seq":82,"isStar":false,"memo":"构词 in-(在…上)+cid(落下)+-ent(名词后缀)→落到你头上的那件事→事件；冲突","example":"Similar incidents have occurred before. 类似的事件以前也发生过。"},{"id":2665,"unit":9,"lesson":1,"word":"incidental","pronunciation":"/ˌɪnsɪˈdent(ə)l/","meaning":"adj.附带发生的,次要的","seq":83,"isStar":false,"memo":"构词 incident(事件)+-al(形容词后缀)→顺带发生的→附带发生的，次要的；非有意的","example":"The discovery was incidental to their main research.这一发现是她们主要研究的附带产物。"},{"id":2666,"unit":9,"lesson":1,"word":"incidentally","pronunciation":"/ˌɪnsɪˈdent(ə)li/","meaning":"adv.偶然地;顺便提一句","seq":84,"isStar":false},{"id":2667,"unit":9,"lesson":2,"word":"complex","pronunciation":"/ˈkɒmpleks/","meaning":"adj.复杂的","seq":1,"isStar":false,"memo":"构词 com-(一起)+plex(折叠，同 multiply 乘)→多股折在一起→复杂的；建筑群","example":"The causes of real-world violence are complex. 现实世界存在暴力的原因是复杂的。"},{"id":2668,"unit":9,"lesson":2,"word":"complexity","pronunciation":"/kəmˈpleksəti/","meaning":"n.复杂性;复杂之处","seq":2,"isStar":false},{"id":2669,"unit":9,"lesson":2,"word":"complexion","pronunciation":"/kəmˈplekʃ(ə)n/","meaning":"n.面色,气色","seq":3,"isStar":false,"memo":"联想 complex(复杂的)+-ion(名词后缀)","example":"His muscles are turning to fat and his complexion is fading.他的肌肉正在变成脂肪，气色也在衰退。"},{"id":2670,"unit":9,"lesson":2,"word":"perplex","pronunciation":"/pəˈpleks/","meaning":"v.使困惑,使费解","seq":4,"isStar":false,"memo":"联想 per(每) + plex(联想 complex) → 每个问题都很复杂，这使我很困惑→使困惑","example":"It perplexed him because he was tackling the problem the wrong way. 这令他困惑，因为他解决问题的方式是错误的。"},{"id":2671,"unit":9,"lesson":2,"word":"perplexity","pronunciation":"/pəˈpleksəti/","meaning":"n.困惑;迷惘","seq":5,"isStar":false},{"id":2672,"unit":9,"lesson":2,"word":"complicate","pronunciation":"/ˈkɒmplɪkeɪt/","meaning":"v.使复杂化","seq":6,"isStar":false,"memo":"联想 complic(联想 complex) + -ate(动词后缀) → 使复杂化","example":"Don't complicate your life. 不要让你的生活变得复杂。"},{"id":2673,"unit":9,"lesson":2,"word":"complicated","pronunciation":"/ˈkɒmplɪkeɪtɪd/","meaning":"adj.复杂的;难懂的","seq":7,"isStar":false},{"id":2674,"unit":9,"lesson":2,"word":"complication","pronunciation":"/ˌkɒmplɪˈkeɪʃ(ə)n/","meaning":"n.使复杂化的问题(情况);并发症","seq":8,"isStar":false},{"id":2675,"unit":9,"lesson":2,"word":"intricate","pronunciation":"/ˈɪntrɪkət/","meaning":"adj.错综复杂的;难理解的","seq":9,"isStar":false,"memo":"联想 in(里面) + tri(音似“纯”) + cate(音似“剋他”) → 内心纯洁的那个人竟然要去他，这是让人“难理解的”。","example":"You develop in-depth knowledge of the intricate structure of the language. 你对该语言错综复杂的结构有了深入的了解。"},{"id":2676,"unit":9,"lesson":2,"word":"intricacy","pronunciation":"/ˈɪntrɪkəsi/","meaning":"n.错综复杂的事物(或细节)","seq":10,"isStar":false,"memo":"构词 in-(在内)+tric(纠缠)+-acy(名词后缀)→缠在里面绕不清的东西→错综复杂的事物","example":"He explained the intricacies of the tax system. 他解释了税制的种种复杂之处。"},{"id":2677,"unit":9,"lesson":2,"word":"intrinsic","pronunciation":"/ɪnˈtrɪnzɪk/","meaning":"adj.固有的,内在的,本质的","seq":11,"isStar":false,"memo":"构词 intr(在内，同 internal 内部的)+-insic(形容词后缀)→生在里面本来就有的→固有的，内在的，本质的","example":"It is crucial to recognize the intrinsic value of education. 认识到教育的固有价值至关重要。"},{"id":2678,"unit":9,"lesson":2,"word":"intrinsically","pronunciation":"/ɪnˈtrɪnzɪkli; ɪnˈtrɪnsɪkli/","meaning":"adv.本质上","seq":12,"isStar":false},{"id":2679,"unit":9,"lesson":2,"word":"instinct","pronunciation":"/ˈɪnstɪŋkt/","meaning":"n.本能,天性;直觉","seq":13,"isStar":false,"memo":"[谐音] 单词发音类似“鹰死盯着它”→老鹰死盯着猎物是一种“本能”。","example":"Their instincts warned them something was wrong. 他们的本能提醒他们有些事情不对劲。"},{"id":2680,"unit":9,"lesson":2,"word":"distinguish","pronunciation":"/dɪˈstɪŋɡwɪʃ/","meaning":"v.区分;使出众","seq":14,"isStar":false,"memo":"[谐音] 单词发音类似“弟似听故事”→弟弟似乎在努力地听老师讲故事，试图“区分”故事里的好人和坏人。","example":"Culture is still used as a mark to distinguish one social class from another. 文化仍被用作区分不同社会阶层的标志。"},{"id":2681,"unit":9,"lesson":2,"word":"distinguishable","pronunciation":"/dɪˈstɪŋɡwɪʃəbl/","meaning":"adj.可区分的,可辨认的","seq":15,"isStar":false},{"id":2682,"unit":9,"lesson":2,"word":"distinction","pronunciation":"/dɪˈstɪŋkʃn/","meaning":"n.差别,区别;特点,特质;不同凡响","seq":16,"isStar":false,"memo":"构词 distinct(区分开的)+-ion(名词后缀)→把两者分开的那一点→差别，区别；特点；不同凡响","example":"We need to draw a distinction between the two events. 我们得把两起事件区别开来。"},{"id":2683,"unit":9,"lesson":2,"word":"distinct","pronunciation":"/dɪˈstɪŋkt/","meaning":"adj.清晰的,明白的;截然不同的","seq":17,"isStar":false,"memo":"构词 dis-(分开)+stinct(刺，同 instinct 本能)→刺得清楚能分开→清晰的，明白的；截然不同的","example":"The results of the survey fell into two distinct groups. 调查结果分为截然不同的两组。"},{"id":2684,"unit":9,"lesson":2,"word":"distinctive","pronunciation":"/dɪˈstɪŋktɪv/","meaning":"adj.独特的,有特色的","seq":18,"isStar":false,"memo":"构词 distinct(区别)+-ive(形容词后缀)→能把自己区别出来的→独特的，有特色的","example":"She follows a rock band with a distinctive sound on social media.她在社交媒体上关注一支音色独特的摇滚乐队。"},{"id":2685,"unit":9,"lesson":2,"word":"extinguish","pronunciation":"/ɪkˈstɪŋɡwɪʃ/","meaning":"v.熄灭,扑灭;使破灭","seq":19,"isStar":false,"memo":"构词 ex-(向外)+tingu(扑打)+-ish(动词后缀)→把火扑打出去→熄灭，扑灭；使破灭","example":"Smoking is forbidden. Please extinguish your cigarettes. 禁止吸烟。请熄灭你们的烟。"},{"id":2686,"unit":9,"lesson":2,"word":"extinct","pronunciation":"/ɪkˈstɪŋkt/","meaning":"adj.不再存在的,绝种的;绝迹的","seq":20,"isStar":false,"memo":"构词 ex-(向外)+tinct(扑灭)→火彻底灭了→不再存在的，绝种的，绝迹的","example":"A species once extinct is gone forever. 一个物种一旦灭绝就永远消失了。"},{"id":2687,"unit":9,"lesson":2,"word":"extinction","pronunciation":"/ɪkˈstɪŋkʃn/","meaning":"n.灭绝,消亡","seq":21,"isStar":false},{"id":2688,"unit":9,"lesson":2,"word":"bewilder","pronunciation":"/bɪˈwɪldə(r)/","meaning":"v.使糊涂,使迷惑","seq":22,"isStar":false,"memo":"[联想] be-（使处于某种状态）+ wild（野外）+ er → 使你在野外迷路 → 使糊涂，使迷惑","example":"She was totally bewildered by his sudden change of mood. 他的情绪突变搞得她全然不知所措。"},{"id":2689,"unit":9,"lesson":2,"word":"bewilderment","pronunciation":"/bɪˈwɪldəmənt/","meaning":"n.迷惘;困惑","seq":23,"isStar":false},{"id":2690,"unit":9,"lesson":2,"word":"baffle","pronunciation":"/ˈbæf(ə)l/","meaning":"v.使困惑;难住","seq":24,"isStar":false,"memo":"[谐音] 单词发音类似“拜佛”→孙悟空遇到困惑后，偶尔会找佛祖指点迷津→使困惑","example":"One of the examination questions baffled me completely. 有一道考题完全把我难住了。"},{"id":2691,"unit":9,"lesson":2,"word":"confuse","pronunciation":"/kənˈfjuːz/","meaning":"v.使糊涂,使迷惑;(将……)混淆","seq":25,"isStar":false,"memo":"[构词] con-（一起）+ fuse（流）→ 流到一起 → 混合，混淆 → 使迷惑","example":"They were confused by the infinite options their money presented them with. 他们被金钱所提供的无穷无尽的选择迷惑了。"},{"id":2692,"unit":9,"lesson":2,"word":"confusion","pronunciation":"/kənˈfjuːʒn/","meaning":"n.困惑;混淆","seq":26,"isStar":false},{"id":2693,"unit":9,"lesson":2,"word":"fuse","pronunciation":"/fjuːz/","meaning":"n.保险丝;导火线 v.(使)融合","seq":27,"isStar":false,"memo":"联想 与 fusion(融合)同根：烧熔到一起→(使)融合，(使)熔化；也指保险丝、导火线","example":"Our different ideas fused into a plan. 我们不同的想法融合成一项计划。"},{"id":2694,"unit":9,"lesson":2,"word":"fusion","pronunciation":"/ˈfjuːʒ(ə)n/","meaning":"n.融合;核聚变,热核反应","seq":28,"isStar":false},{"id":2695,"unit":9,"lesson":2,"word":"diffuse","pronunciation":"/dɪˈfjuːs/","meaning":"v.普及;散布;渗透 adj.扩散的","seq":29,"isStar":false,"memo":"构词 dif-(分开) + fuse(流)→散布","example":"The pollutants diffuse into the soil. 污染物渗进土壤中。"},{"id":2696,"unit":9,"lesson":2,"word":"diffusion","pronunciation":"/dɪˈfjuːʒn/","meaning":"n.传播,散布","seq":30,"isStar":false},{"id":2697,"unit":9,"lesson":2,"word":"refute","pronunciation":"/rɪˈfjuːt/","meaning":"v.驳斥;反驳,否认","seq":31,"isStar":false,"memo":"构词 re-(往回) + fute ( = beat, 击) → 回击→反驳,否认","example":"This can be refuted by scholarly research. 学术研究结果可以反驳这种说法。"},{"id":2698,"unit":9,"lesson":2,"word":"refutation","pronunciation":"/ˌrefjuˈteɪʃ(ə)n/","meaning":"n.反驳","seq":32,"isStar":false},{"id":2699,"unit":9,"lesson":2,"word":"disperse","pronunciation":"/dɪˈspɜːs/","meaning":"v.(使)分散;传播,散布","seq":33,"isStar":false,"memo":"联想 dis-(否定前缀) + perse(音似“婆撕”)→不要到处“传播”她和她的婆婆撕破脸的虚假消息。","example":"The seeds are dispersed by the wind. 种子是通过风传播的。"},{"id":2700,"unit":9,"lesson":2,"word":"authority","pronunciation":"/ɔːˈθɒrəti/","meaning":"n.权威;权力;批准","seq":34,"isStar":false,"memo":"联想 author(作者) + -ity(名词后缀)→作者是写作领域的“权威”。","example":"Don't raise the stakes by challenging her authority. 不要通过挑战她的权威来增加风险。"},{"id":2701,"unit":9,"lesson":2,"word":"authoritative","pronunciation":"/ɔːˈθɒrətətɪv/","meaning":"adj.命令式的;权威性的","seq":35,"isStar":false},{"id":2702,"unit":9,"lesson":2,"word":"authorise/-ize","pronunciation":"/ˈɔːθəraɪz/","meaning":"v.批准;授权","seq":36,"isStar":false,"memo":"构词 author(作者、发起人)+-ise/-ize(使…化)→给某人发起者的权力→批准，授权","example":"Only the manager can authorise a refund. 只有经理才有权批准退款。"},{"id":2703,"unit":9,"lesson":2,"word":"authorisation/-zation","pronunciation":"/ˌɔ:θəraɪˈzeɪʃən/","meaning":"n.批准;授权","seq":37,"isStar":false,"memo":"构词 authoris(授权)+-ation(名词后缀)→批准或授权这一行为","example":"You need written authorisation to enter the building. 进入这栋楼需要书面授权。"},{"id":2704,"unit":9,"lesson":2,"word":"copyright","pronunciation":"/ˈkɒpiraɪt/","meaning":"n.版权;著作权","seq":38,"isStar":false,"memo":"构词 copy(复制) + right(权利) → 版权","example":"They were sued for breach of copyright.他们因侵犯版权被起诉。"},{"id":2705,"unit":9,"lesson":2,"word":"authentic","pronunciation":"/ɔːˈθentɪk/","meaning":"adj.真正的,真实的;逼真的","seq":39,"isStar":false,"memo":"联想 authen(联想 author) + -tic(形容词后缀)→作者的思想通常是“真实的”。","example":"They claim that their account is the “authentic” one. 他们声称他们的叙述是“真实的”。"},{"id":2706,"unit":9,"lesson":2,"word":"authenticity","pronunciation":"/ˌɔːθenˈtɪsəti/","meaning":"n.真实性;确实性","seq":40,"isStar":false},{"id":2707,"unit":9,"lesson":2,"word":"entitle","pronunciation":"/ɪnˈtaɪt(ə)l/","meaning":"v.使……有权利或资格","seq":41,"isStar":false,"memo":"构词 en-(使) + title(标题;头衔)→使……有权利或资格","example":"Everyone is entitled to their own opinion. 每个人都有权发表自己的意见。"},{"id":2708,"unit":9,"lesson":2,"word":"virtual","pronunciation":"/ˈvɜːtʃuəl/","meaning":"adj.事实上的;虚拟的","seq":42,"isStar":false,"memo":"谐音 单词发音类似“龌”→他看起来很龌龊,但实际上很正经→事实上的","example":"Those products can also do well in the virtual environment. 那些产品在虚拟环境中也能有不错的销量。"},{"id":2709,"unit":9,"lesson":2,"word":"virtually","pronunciation":"/ˈvɜːtʃuəli/","meaning":"adv.虚拟地;实际上,几乎","seq":43,"isStar":false},{"id":2710,"unit":9,"lesson":2,"word":"absolute","pronunciation":"/ˈæbsəluːt/","meaning":"adj.完全的;绝对的","seq":44,"isStar":false,"memo":"联想 ab-(一再地)+so(如此)+lute(联想late)→一再地如此晚→完全晚了→完全的","example":"If you love your mate, you need absolute confidence and trust in him/her. 如果你爱你的配偶,你就需要完全地信任他/她。"},{"id":2711,"unit":9,"lesson":2,"word":"sheer","pronunciation":"/ʃɪə(r)/","meaning":"adj.完全的,纯粹的","seq":45,"isStar":false,"memo":"联想 she(她)+er(表示人的后缀)→她是个“纯粹”人。","example":"It can't be solved by the sheer force of activity. 它无法单凭行动就能得到解决。"},{"id":2712,"unit":9,"lesson":2,"word":"complete","pronunciation":"/kəmˈpliːt/","meaning":"adj.完全的,彻底的;完整的 v.完成","seq":46,"isStar":false,"memo":"构词 com-(完全)+plete(填满)→完全填满了→完全的,彻底的","example":"We were in complete agreement. 我们意见完全一致。"},{"id":2713,"unit":9,"lesson":2,"word":"practicable","pronunciation":"/ˈpræktɪkəbl/","meaning":"adj.可行的,行得通的","seq":47,"isStar":false,"memo":"构词 practic(e)(实践)+-able(形容词后缀)→可行的,行得通的","example":"It offers practicable advice to businessmen. 它为商人提供了切实可行的建议。"},{"id":2714,"unit":9,"lesson":2,"word":"malpractice","pronunciation":"/ˌmælˈpræktɪs/","meaning":"n.渎职,玩忽职守","seq":48,"isStar":false,"memo":"构词 mal-(不良)+practice(实践;行为)→不良的行为→渎职,玩忽职守","example":"He was unable to alert his students to corporate malpractice. 他未能向他的学生警示公司的违规行为。"},{"id":2715,"unit":9,"lesson":2,"word":"practical","pronunciation":"/ˈpræktɪkl/","meaning":"adj.实际的;实用的 n.实践课","seq":49,"isStar":false,"memo":"对照 多做练习(practice)就会积累更多实用的(practical)经验。","example":"This is a practical little car, ideal for the city. 这是一款实用的小汽车,非常适合在城市中使用。"},{"id":2716,"unit":9,"lesson":2,"word":"practicality","pronunciation":"/ˌpræktɪˈkæləti/","meaning":"n.可行性","seq":50,"isStar":false},{"id":2717,"unit":9,"lesson":2,"word":"genuine","pronunciation":"/ˈdʒenjuɪn/","meaning":"adj.真的;真诚的","seq":51,"isStar":false,"memo":"谐音 单词发音类似“真牛”→姐姐“真的”很牛,是个强者。","example":"She showed genuine interest in the project. 她对这个项目表现出真正的兴趣。"},{"id":2718,"unit":9,"lesson":2,"word":"generous","pronunciation":"/ˈdʒenərəs/","meaning":"adj.慷慨的,大方的;宽宏大量的","seq":52,"isStar":false,"memo":"谐音：单词发音类似“真弄肉丝”→“慷慨的”姐姐真给我弄了一大盘肉丝。","example":"She is a generous woman by nature. 她天生就是个慷慨的女人。"},{"id":2719,"unit":9,"lesson":2,"word":"genius","pronunciation":"/ˈdʒiːniəs/","meaning":"n.天才;天资","seq":53,"isStar":false,"memo":"联想：ge(联想“哥”) + nius(音似“牛死”) → 哥哥牛死了，是个“天才”。","example":"It's undoubtedly a work of genius. 这无疑是一部天才之作。"},{"id":2720,"unit":9,"lesson":2,"word":"elite","pronunciation":"/eɪˈliːt; ɪˈliːt/","meaning":"n.社会精英 adj.精英的","seq":54,"isStar":false,"memo":"联想：e(字母音似“姨”) + li(联想“离”) + te(音似“他”) → 阿姨离开他后成了“社会精英”。","example":"A new managerial elite was replacing the old aristocracy. 新的管理精英阶层正在取代旧的贵族阶层。"},{"id":2721,"unit":9,"lesson":2,"word":"ingenious","pronunciation":"/ɪnˈdʒiːniəs/","meaning":"adj.巧妙的;心灵手巧的","seq":55,"isStar":false,"memo":"联想：in(里面) + genious(联想 genius) → 天才的内心→心灵手巧的","example":"He is an ingenious cook. 他是一名心灵手巧的厨师。"},{"id":2722,"unit":9,"lesson":2,"word":"ingenuity","pronunciation":"/ˌɪndʒəˈnjuːəti/","meaning":"n.独创力;聪明才智;心灵手巧","seq":56,"isStar":false},{"id":2723,"unit":9,"lesson":2,"word":"nuisance","pronunciation":"/ˈnjuːsns/","meaning":"n.令人讨厌的人或事物","seq":57,"isStar":false,"memo":"谐音：单词发音类似“牛绅士”→他老是感觉自己很牛，装成个绅士，令人讨厌→令人讨厌的人或事物","example":"I hope you're not making a nuisance of yourself. 我希望你没有讨人嫌。"},{"id":2724,"unit":9,"lesson":2,"word":"intelligent","pronunciation":"/ɪnˈtelɪdʒənt/","meaning":"adj.聪明的;智能的","seq":58,"isStar":false,"memo":"联想：intel(联想 Internet) + lig + ent(联想 enter) → 能进入因特网行业的人是“聪明的”。","example":"Black-haired women were judged to be intelligent. 黑发女性被认为是聪明的。"},{"id":2725,"unit":9,"lesson":2,"word":"intellect","pronunciation":"/ˈɪntəlekt/","meaning":"n.智力高的人;(尤指高等的)智力","seq":59,"isStar":false,"example":"Einstein was one of the greatest intellects of his time. 爱因斯坦是他的时代里最有才智的人之一。"},{"id":2726,"unit":9,"lesson":2,"word":"intellectual","pronunciation":"/ˌɪntəˈlektʃuəl/","meaning":"n.知识分子;脑力劳动者 adj.智力的","seq":60,"isStar":false,"memo":"【构词】intellect（智力）+ -ual（形容词后缀）→‘脑力在线的’！别记成‘因特尔芯片’，是‘in-tel-lect’（在思考中）。","example":"Intellectual curiosity drives students to question assumptions in academic debates. 智力好奇心驱使学生在学术辩论中质疑既有假设。"},{"id":2727,"unit":9,"lesson":2,"word":"intelligence","pronunciation":"/ɪnˈtelɪdʒəns/","meaning":"n.智力;情报","seq":61,"isStar":false,"memo":"构词 intel-(在…之间)+lig(挑选，同 elect 选出)+-ence(名词后缀)→在信息之间挑选判断的能力→智力；情报","example":"Artificial intelligence is key to future technological innovations. 人工智能是未来技术创新的关键。"},{"id":2728,"unit":9,"lesson":2,"word":"intelligible","pronunciation":"/ɪnˈtelɪdʒəb(ə)l/","meaning":"adj.易懂的,容易理解的","seq":62,"isStar":false,"memo":"[联想] in-(否定前缀) + tell(说) + igible→不用说就能让人明白→易懂的","example":"His lecture was readily intelligible to all the students. 学生们都能轻松地听懂他的讲座。"},{"id":2729,"unit":9,"lesson":2,"word":"sharp","pronunciation":"/ʃɑːp/","meaning":"adj.锋利的;清晰的;敏锐的","seq":63,"isStar":false,"memo":"[对照] 鲨鱼(shark)的牙齿是锋利的(sharp)。","example":"His mind is as sharp as ever. 他思维敏锐，一如既往。"},{"id":2730,"unit":9,"lesson":2,"word":"sharpen","pronunciation":"/ˈʃɑːpən/","meaning":"v.(使)变锋利","seq":64,"isStar":false},{"id":2731,"unit":9,"lesson":2,"word":"blunt","pronunciation":"/blʌnt/","meaning":"adj.不锋利的,钝的;直言不讳的","seq":65,"isStar":false,"memo":"[谐音] 单词发音类似“不烂它”→拿刀切了半天肉也切不烂它，因为刀子是“不锋利的”。","example":"Sharpen all your blunt knives. 把你所有的钝刀都磨一磨。"},{"id":2732,"unit":9,"lesson":3,"word":"blunder","pronunciation":"/ˈblʌndə(r)/","meaning":"n.愚蠢的错误 v.犯愚蠢的错误","seq":1,"isStar":false,"memo":"[对照] 直言不讳的(blunt)人可能会犯愚蠢的错误(blunder)。","example":"It was really a blunder to lay him off. 当时开除他真是一个愚蠢的错误。"},{"id":2733,"unit":9,"lesson":3,"word":"straightforward","pronunciation":"/ˌstreɪtˈfɔːwəd/","meaning":"adj.简单的;坦率的,诚实的","seq":2,"isStar":false,"memo":"[构词] straight(直的) + forward(向前)→坦率的","example":"He presents his arguments in a straightforward way. 他以直截了当的方式提出了他的论点。"},{"id":2734,"unit":9,"lesson":3,"word":"giant","pronunciation":"/ˈdʒaɪənt/","meaning":"adj.巨大的;伟大的 n.巨人;大公司","seq":3,"isStar":false,"memo":"[联想] GIANT 是自行车品牌捷安特的英文名称→捷安特想做自行车行业的“巨人”。","example":"Today it is a giant advertising company. 如今，它是一家巨型广告公司。"},{"id":2735,"unit":9,"lesson":3,"word":"gigantic","pronunciation":"/dʒaɪˈɡæntɪk/","meaning":"adj.巨大的,庞大的","seq":4,"isStar":false,"memo":"构词 gigant(巨人，同 giant)+-ic(形容词后缀)→像巨人一样的→巨大的，庞大的","example":"The gigantic natural harbour is a haven for boats. 这个巨大的天然海港是船舶的避风港。"},{"id":2736,"unit":9,"lesson":3,"word":"immense","pronunciation":"/ɪˈmens/","meaning":"adj.极大的,巨大的","seq":5,"isStar":false,"memo":"[联想] i(我) + mmense(音似“闷死”)→天热得像一个“巨大的”火炉，简直要把我闷死了。","example":"They are often admired for their immense enjoyment of the arts. 他们常常因其对艺术的无限热爱而备受赞赏。"},{"id":2737,"unit":9,"lesson":3,"word":"immensely","pronunciation":"/ɪˈmensli/","meaning":"adv.非常;极大地","seq":6,"isStar":false},{"id":2738,"unit":9,"lesson":3,"word":"immensity","pronunciation":"/ɪˈmensəti/","meaning":"n.巨大;广大","seq":7,"isStar":false},{"id":2739,"unit":9,"lesson":3,"word":"immerse","pronunciation":"/ɪˈmɜːs/","meaning":"v.(使)深陷于,沉浸在","seq":8,"isStar":false,"memo":"联想 i(我)+mmerse(音似“没死”)→我被淹没了→(使)深陷于,沉浸在","example":"Some netizens are immersed in the virtual world. 一些网民沉浸在虚拟世界。"},{"id":2740,"unit":9,"lesson":3,"word":"immersion","pronunciation":"/ɪˈmɜːʃn/","meaning":"n.沉浸;专心;陷入","seq":9,"isStar":false},{"id":2741,"unit":9,"lesson":3,"word":"commence","pronunciation":"/kəˈmens/","meaning":"v.开始;着手","seq":10,"isStar":false,"memo":"联想 com-(都)+mence(音似“闷死”)→他的鸡鸭都因闷热窒息而死,他得重新“开始”养。","example":"If everyone has arrived, we may now commence the meeting. 如果大家都到齐了,我们现在就开始会议了。"},{"id":2742,"unit":9,"lesson":3,"word":"commencement","pronunciation":"/kəˈmensmənt/","meaning":"n.开始;开端","seq":11,"isStar":false},{"id":2743,"unit":9,"lesson":3,"word":"enormous","pronunciation":"/ɪˈnɔːməs/","meaning":"adj.巨大的,庞大的","seq":12,"isStar":false,"memo":"构词 e-(往外)+norm(规范)+-ous(形容词后缀)→超出规范的→巨大的","example":"He is under enormous pressure. 他面临着巨大的压力。"},{"id":2744,"unit":9,"lesson":3,"word":"mighty","pronunciation":"/ˈmaɪti/","meaning":"adj.强有力的;巨大的 adv.非常","seq":13,"isStar":false,"memo":"对照 一切皆有可能(might)，并且有些事可能性非常(mighty)大。","example":"The mighty empire finally crumbled.这个强大的帝国终于崩溃了。"},{"id":2745,"unit":9,"lesson":3,"word":"almighty","pronunciation":"/ɔːlˈmaɪti/","meaning":"adj.全能的;极大的;全能的","seq":14,"isStar":false,"memo":"构词 al-(=all)+mighty(巨大的)→全能的；极大的","example":"We heard an almighty crash from the kitchen.我们听到厨房传来一声巨响。"},{"id":2746,"unit":9,"lesson":3,"word":"lofty","pronunciation":"/ˈlɒfti/","meaning":"adj.巍峨的;崇高的,高尚的","seq":15,"isStar":false,"memo":"谐音 单词发音类似“老夫式”→他自称老夫,觉得自己太高尚了→崇高的,高尚的","example":"The company likes to present itself as having lofty, utopian aspirations. 该公司喜欢将自己描绘成拥有崇高的、乌托邦式追求的企业。"},{"id":2747,"unit":9,"lesson":3,"word":"fragment","pronunciation":"/ˈfræɡmənt/","meaning":"n.碎片;片段 v.使破裂","seq":16,"isStar":false,"memo":"fr(联想“芙蓉”)+ag(联想“阿哥”)+m(联想“门”)+ent→芙蓉把阿哥赶出了门,阿哥的心变成了“碎片”。","example":"The wood was so rotten that, when we pulled, it broke up into fragments.这块木头已经腐朽不堪,我们一拉,它就碎成了片。"},{"id":2748,"unit":9,"lesson":3,"word":"fragmentary","pronunciation":"/ˈfræɡmənt(ə)ri/","meaning":"adj.残缺不全的,不完整的","seq":17,"isStar":false},{"id":2749,"unit":9,"lesson":3,"word":"fragmentation","pronunciation":"/ˌfræɡmenˈteɪʃn/","meaning":"n.分裂,破裂","seq":18,"isStar":false},{"id":2750,"unit":9,"lesson":3,"word":"fragile","pronunciation":"/ˈfrædʒaɪl/","meaning":"adj.脆弱的,易碎的;虚弱的","seq":19,"isStar":false,"memo":"frag(打碎,破碎)+-ile(形容词后缀)→易碎的","example":"Her father is now 86 and in fragile health.她的父亲现在86岁,身体虚弱。"},{"id":2751,"unit":9,"lesson":3,"word":"frantic","pronunciation":"/ˈfræntɪk/","meaning":"adj.紧张忙乱的,手忙脚乱的;发狂似的","seq":20,"isStar":false,"memo":"谐音 “弗兰提克”：急得团团转→紧张忙乱的，手忙脚乱的；发狂似的","example":"She made a frantic search for her keys. 她手忙脚乱地找钥匙。"},{"id":2752,"unit":9,"lesson":3,"word":"frantically","pronunciation":"/ˈfræntɪkli/","meaning":"adv.疯狂地;紧张忙乱地","seq":21,"isStar":false,"memo":"构词 frantic(狂乱的)+-al+-ly(副词后缀)→疯狂地；紧张忙乱地","example":"He was typing frantically to meet the deadline. 为了赶上截止时间，他疯狂地打着字。"},{"id":2753,"unit":9,"lesson":3,"word":"fraction","pronunciation":"/ˈfrækʃn/","meaning":"n.小部分;少量","seq":22,"isStar":false,"memo":"fr(联想“芙蓉”)+action(行为)→芙蓉的行为只有“小部分”人可以接受。","example":"She paused for a fraction of a second.她略微停顿了一下。"},{"id":2754,"unit":9,"lesson":3,"word":"fracture","pronunciation":"/ˈfræktʃə(r)/","meaning":"v.折断,破裂 n.骨折,断裂","seq":23,"isStar":false,"memo":"fr(联想“芙蓉”)+acture(联想structure)→芙蓉的骨骼结构比较脆弱,有“骨折”的风险。","example":"Old people's bones are more prone to fracture.老人更易骨折。"},{"id":2755,"unit":9,"lesson":3,"word":"frame","pronunciation":"/freɪm/","meaning":"n.框架;骨架 v.(给)装框架;制定","seq":24,"isStar":false,"memo":"构词 fram(向前、搭构)+-e→把材料搭起来→框架，骨架；装框架；制定","example":"The frame is made of wood.框架是用木头做的。"},{"id":2756,"unit":9,"lesson":3,"word":"framework","pronunciation":"/ˈfreɪmwɜːk/","meaning":"n.构架,框架","seq":25,"isStar":false,"memo":"构词 frame(框架)+work(构造)→整体的构架→构架，框架","example":"The theory provides a framework for analysis. 这一理论提供了分析的框架。"},{"id":2757,"unit":9,"lesson":3,"word":"flame","pronunciation":"/fleɪm/","meaning":"n.火焰 v.燃烧;(因强烈情绪而)变红","seq":26,"isStar":false,"memo":"构词 flam(燃烧，同 flammable 易燃的)+-e→燃烧的样子→火焰；燃烧；(因情绪)变红","example":"The flame flickered in the wind. 火焰在风中摇曳。"},{"id":2758,"unit":9,"lesson":3,"word":"flare","pronunciation":"/fleə(r)/","meaning":"n.(短暂的)旺火;闪光 v.燃烧;闪耀","seq":27,"isStar":false,"memo":"联想 与 flame 同族：突然窜起的一股火→(短暂的)旺火，闪光；燃烧，闪耀","example":"The match flared in the dark. 火柴在黑暗中闪出火光。"},{"id":2759,"unit":9,"lesson":3,"word":"fluid","pronunciation":"/ˈfluːɪd/","meaning":"n.液体,流体 adj.流动的","seq":28,"isStar":false,"memo":"构词 flu(流，同 fluent 流利的)+-id(形容词后缀)→会流动的→液体，流体；流动的","example":"Drink plenty of fluids when you have a fever. 发烧时要多喝流质。"},{"id":2760,"unit":9,"lesson":3,"word":"solid","pronunciation":"/ˈsɒlɪd/","meaning":"adj.固体的;结实的,坚实的 n.固体","seq":29,"isStar":false,"memo":"构词 sol(坚实，同 consolidate 巩固)+-id(形容词后缀)→结实成块的→固体的；结实的；固体","example":"The ice became solid overnight. 冰在一夜之间冻得结实。"},{"id":2761,"unit":9,"lesson":3,"word":"solidity","pronunciation":"/səˈlɪdəti/","meaning":"n.固态;坚固性","seq":30,"isStar":false,"memo":"构词 solid(固体的)+-ity(名词后缀)→结成一块的性质→固态；坚固性","example":"The solidity of the bridge impressed us. 这座桥的坚固令人印象深刻。"},{"id":2762,"unit":9,"lesson":3,"word":"solidify","pronunciation":"/səˈlɪdɪfaɪ/","meaning":"v.巩固;(使)变成固体","seq":31,"isStar":false,"memo":"构词 solid(固体的)+-ify(使…化)→使变成固体并更稳固→(使)变成固体；巩固","example":"Lava solidifies as it cools. 熔岩冷却后就会凝固。"},{"id":2763,"unit":9,"lesson":3,"word":"watertight","pronunciation":"/ˈwɔːtətaɪt/","meaning":"adj.防水的;无懈可击的","seq":32,"isStar":false,"memo":"构词 water(水)+tight(紧密的)→水都钻不进去的→防水的；引申为无懈可击的","example":"The case against him was watertight. 指控他的理由无懈可击。"},{"id":2764,"unit":9,"lesson":3,"word":"consolidate","pronunciation":"/kənˈsɒlɪdeɪt/","meaning":"v.使加强,使巩固;合并","seq":33,"isStar":false,"memo":"con-（一起）+ solid（坚固）+ -ate → 把散沙捏成solid砖！复习三遍=知识 consolidate，牢得像水泥～","example":"The company consolidated its overseas offices to cut costs. 公司整合海外办事处以降低成本。"},{"id":2765,"unit":9,"lesson":3,"word":"consolidation","pronunciation":"/kənˌsɒlɪˈdeɪʃ(ə)n/","meaning":"n.巩固;合并","seq":34,"isStar":false},{"id":2766,"unit":9,"lesson":3,"word":"solidarity","pronunciation":"/ˌsɒlɪˈdærəti/","meaning":"n.团结","seq":35,"isStar":false,"memo":"构词 solid(坚实的)+-arity(名词后缀)→彼此紧紧连成一体→团结","example":"Workers marched to show solidarity. 工人们游行以示团结。"},{"id":2767,"unit":9,"lesson":3,"word":"flatter","pronunciation":"/ˈflætə(r)/","meaning":"v.讨好,奉承","seq":36,"isStar":false,"memo":"构词 flat(平)+-er(动词后缀)→把人“捧”得平坦舒服→讨好，奉承","example":"He flattered her on her cooking. 他夸她的厨艺好。"},{"id":2768,"unit":9,"lesson":3,"word":"flattery","pronunciation":"/ˈflætəri/","meaning":"n.奉承,讨好","seq":37,"isStar":false,"memo":"构词 flatter(奉承)+-y(名词后缀)→奉承的话→奉承，讨好","example":"Flattery will get you nowhere. 奉承是没有用的。"},{"id":2769,"unit":9,"lesson":3,"word":"flutter","pronunciation":"/ˈflʌtə(r)/","meaning":"v.&n.飘动;挥动","seq":38,"isStar":false,"memo":"构词 flut(飘，与 fly、fleet 同族)+-er(表反复动作)→来来回回轻轻飘动→飘动；挥动","example":"A butterfly fluttered past. 一只蝴蝶翩翩飞过。"},{"id":2770,"unit":9,"lesson":3,"word":"fluent","pronunciation":"/ˈfluːənt/","meaning":"adj.流利的,熟练的,流畅的","seq":39,"isStar":false,"memo":"构词 flu(流，同 fluid 流体)+-ent(形容词后缀)→话像流水一样出来→流利的，熟练的，流畅的","example":"She is fluent in three languages. 她能流利地说三种语言。"},{"id":2771,"unit":9,"lesson":3,"word":"fluency","pronunciation":"/ˈfluːənsi/","meaning":"n.流利,流畅","seq":40,"isStar":false,"memo":"构词 fluent(流利的)+-cy(名词后缀)→流利的程度→流利，流畅","example":"Reading aloud improves fluency. 朗读能提高流利度。"},{"id":2772,"unit":9,"lesson":3,"word":"affluent","pronunciation":"/ˈæfluənt/","meaning":"adj.富裕的","seq":41,"isStar":false,"memo":"谐音+构词：'a-fluent'→ '啊！流金'！钱像河水哗哗流，富裕得自带BGM～","example":"Affluent families often invest heavily in private education for their children. 富裕家庭通常会大力投资子女的私立教育。"},{"id":2773,"unit":9,"lesson":3,"word":"affluence","pronunciation":"/ˈæfluəns/","meaning":"n.富裕","seq":42,"isStar":false},{"id":2774,"unit":9,"lesson":3,"word":"original","pronunciation":"/əˈrɪdʒən(ə)l/","meaning":"adj.起初的;首创的 n.原件","seq":43,"isStar":false},{"id":2775,"unit":9,"lesson":3,"word":"originality","pronunciation":"/əˌrɪdʒəˈnæləti/","meaning":"n.独创性,创意,独特构思","seq":44,"isStar":false,"memo":"构词 origin(起源、本源)+-al+-ity(名词后缀)→从本源里长出来的新东西→独创性，创意","example":"The design shows great originality. 这项设计表现出很强的独创性。"},{"id":2776,"unit":9,"lesson":3,"word":"originate","pronunciation":"/əˈrɪdʒɪneɪt/","meaning":"v.起源,发源;创立","seq":45,"isStar":false,"memo":"构词：ori-（升起，如orient东方即太阳升起处）+ -gin-（开始）+ -ate（动词）→'日出之地开始'！万物皆从'起源'那一刻冉冉升起～","example":"The tradition originates from a 19th-century rural festival. 这一传统起源于19世纪的一场乡村节日。"},{"id":2777,"unit":9,"lesson":3,"word":"region","pronunciation":"/ˈriːdʒən/","meaning":"n.地区,区域","seq":46,"isStar":false,"memo":"构词 reg(统治，同 reign 君主统治)+-ion(名词后缀)→受同一管辖的一片地→地区，区域","example":"This region is famous for its tea. 这个地区以茶叶闻名。"},{"id":2778,"unit":9,"lesson":3,"word":"regional","pronunciation":"/ˈriːdʒən(ə)l/","meaning":"adj.地区的,区域的","seq":47,"isStar":false,"memo":"构词 region(地区)+-al(形容词后缀)→与地区有关的→地区的，区域的","example":"They spoke in a regional dialect. 他们说的是地方的方言。"},{"id":2779,"unit":9,"lesson":3,"word":"sacred","pronunciation":"/ˈseɪkrɪd/","meaning":"adj.神圣的","seq":48,"isStar":false,"memo":"谐音+联想：‘赛克瑞德’→‘赛’场上最‘克’制的‘瑞’士钟表匠，把每秒都当‘神圣’仪式来做！sacr-（神圣）+ -ed→被神化的。","example":"Mountains are sacred sites for many indigenous communities. 对许多原住民社群而言，山脉是神圣场所。"},{"id":2780,"unit":9,"lesson":3,"word":"worship","pronunciation":"/ˈwɜːʃɪp/","meaning":"n.&v.崇拜;爱慕","seq":49,"isStar":false,"memo":"拆解：wor-（= worth 值得）+ -ship（状态）→ 值得你‘跪着送ship’（送礼/敬意）的状态！本义就是‘敬拜’。","example":"Many students worship tech entrepreneurs as modern-day heroes. 许多学生将科技企业家奉为当代英雄。"},{"id":2781,"unit":9,"lesson":3,"word":"cult","pronunciation":"/kʌlt/","meaning":"n.狂热,风尚,热潮","seq":50,"isStar":false,"memo":"构词 cult(耕作、崇拜，同 culture 文化)→被一群人狂热崇拜的东西→狂热，风尚，热潮；异教团体","example":"The film became a cult classic. 这部电影成了一部被狂热追捧的经典。"},{"id":2782,"unit":9,"lesson":3,"word":"idol","pronunciation":"/ˈaɪdl/","meaning":"n.偶像","seq":51,"isStar":false,"memo":"构词 idol(影像、偶像，同 idolize 崇拜)→被供起来膜拜的形象→偶像","example":"He was the idol of millions of fans. 他是数百万粉丝的偶像。"},{"id":2783,"unit":9,"lesson":3,"word":"athlete","pronunciation":"/ˈæθliːt/","meaning":"n.运动员","seq":52,"isStar":false,"memo":"构词 athl(竞赛，同 athletics 田径运动)+-ete(表人)→参加竞技的人→运动员","example":"She is a professional athlete. 她是一名职业运动员。"},{"id":2784,"unit":9,"lesson":3,"word":"athletic","pronunciation":"/æθˈletɪk/","meaning":"adj.健壮的;田径运动的","seq":53,"isStar":false,"memo":"构词 athlet(运动员)+-ic(形容词后缀)→像运动员那样的→健壮的；田径运动的","example":"He has an athletic build. 他体格健壮如运动员。"},{"id":2785,"unit":9,"lesson":3,"word":"derive","pronunciation":"/dɪˈraɪv/","meaning":"v.起源于;来自","seq":54,"isStar":false,"memo":"de-（下）+ riv（拉丁‘rivus’溪流）+ -e → ‘从溪流源头往下引水’，引申为‘从某处源头获得’，知识如活水，得‘溯流而上’才能derive！","example":"Scientists derive new hypotheses from unexpected experimental data. 科学家从意外的实验数据中提出新假设。"},{"id":2786,"unit":9,"lesson":3,"word":"derivative","pronunciation":"/dɪˈrɪvətɪv/","meaning":"adj.模仿他人的 n.派生词;衍生物","seq":55,"isStar":false},{"id":2787,"unit":9,"lesson":3,"word":"derivation","pronunciation":"/ˌderɪˈveɪʃ(ə)n/","meaning":"n.(尤指词语的)起源,派生","seq":56,"isStar":false},{"id":2788,"unit":9,"lesson":3,"word":"deprive","pronunciation":"/dɪˈpraɪv/","meaning":"v.剥夺,使丧失","seq":57,"isStar":false,"memo":"【构词】de-(去掉)+priv(e)-(私有，源自拉丁privare)→硬把你的‘私有’拿走→剥夺。","example":"Children deprived of adequate sleep often struggle academically. 睡眠不足的儿童常在学业上表现吃力。"},{"id":2789,"unit":9,"lesson":3,"word":"strive","pronunciation":"/straɪv/","meaning":"v.努力,奋斗;力求","seq":58,"isStar":false,"memo":"【谐音】'死追'——拼了命也要追上目标！striv(e) 和 strive 同源，过去式strove/striken，像‘strive to survive’（为活命而搏）。","example":"Students must strive for excellence while balancing mental health. 学生必须在追求卓越的同时兼顾心理健康。"},{"id":2790,"unit":9,"lesson":3,"word":"thrive","pronunciation":"/θraɪv/","meaning":"v.兴旺发达,繁荣;茁壮成长","seq":59,"isStar":false,"memo":"谐音‘三活’——活三次？不，是‘三’倍努力后终于 thrive（茁壮成长）！","example":"Remote students thrive when given flexible deadlines and clear feedback. 当获得弹性截止时间和清晰反馈时，在线学生蓬勃发展。"},{"id":2791,"unit":9,"lesson":3,"word":"contrive","pronunciation":"/kənˈtraɪv/","meaning":"v.设法做到;策划;发明,设计","seq":60,"isStar":false,"memo":"【构词】con-（共同）+ triv（转，拉丁trivere）→ 暗中‘转着圈儿想办法’！不是直球解决，是绞尽脑汁‘搞出个法子’，比如用回形针修耳机～","example":"Engineers contrived an ingenious solution to reduce energy consumption. 工程师设计出一种巧妙方案以降低能耗。"},{"id":2792,"unit":9,"lesson":3,"word":"retrieve","pronunciation":"/rɪˈtriːv/","meaning":"v.取回;挽回","seq":61,"isStar":false,"memo":"【构词】re-（回）+ triev(e)（=try尝试，古义‘寻找’），拼命往回找→取回、找回！像狗叼回飞盘一样精准。","example":"IT staff retrieved the lost data from backup servers within two hours. 技术人员两小时内从备份服务器中找回了丢失的数据。"},{"id":2793,"unit":9,"lesson":3,"word":"retrieval","pronunciation":"/rɪˈtriːv(ə)l/","meaning":"n.取回;数据检索","seq":62,"isStar":false},{"id":2794,"unit":9,"lesson":3,"word":"peculiar","pronunciation":"/pɪˈkjuːliə(r)/","meaning":"adj.怪异的,奇怪的;特殊的","seq":63,"isStar":false,"memo":"【构词】peculi-（私有，拉丁语peculium=私产）+ -ar →‘只属于你的怪癖’！比如室友坚持用Excel记奶茶订单，peculiar but harmless～","example":"The professor has a peculiar habit of quoting Shakespeare during physics lectures. 教授有个怪癖：物理课上动不动引用莎士比亚。"},{"id":2795,"unit":9,"lesson":3,"word":"peculiarity","pronunciation":"/pɪˌkjuːliˈærəti/","meaning":"n.特点;奇怪","seq":64,"isStar":false},{"id":2796,"unit":9,"lesson":3,"word":"exotic","pronunciation":"/ɪɡˈzɒtɪk/","meaning":"adj.异国情调的;奇异的","seq":65,"isStar":false,"memo":"【谐音】‘一个锁踢’——外国货被锁在海关踢来踢去，太‘异域’啦！【构词】ex-（外）+ otic（=otic, 来自希腊语‘外来’）→外来的。","example":"Students showed great curiosity about exotic plants in the botanical garden. 学生们对植物园里的异域植物表现出极大好奇。"},{"id":2797,"unit":9,"lesson":3,"word":"weird","pronunciation":"/wɪəd/","meaning":"adj.怪异的","seq":66,"isStar":false,"memo":"谐音‘畏惧’——见到‘奇怪’东西，本能‘畏惧’！w+eird= weird，eird像‘eerie’（怪异的）","example":"It feels weird to take online exams without proctors. 没有监考员进行线上考试，感觉很奇怪。"},{"id":2798,"unit":9,"lesson":3,"word":"acquaint","pronunciation":"/əˈkweɪnt/","meaning":"v.使熟悉,使了解","seq":67,"isStar":false,"memo":"构词 ac-(加强)+quaint(知道)→使人知道→使熟悉，使了解","example":"Please acquaint yourself with the rules. 请先熟悉一下这些规则。"},{"id":2799,"unit":9,"lesson":3,"word":"acquaintance","pronunciation":"/əˈkweɪntəns/","meaning":"n.熟人;认识","seq":68,"isStar":false,"memo":"构词 acquaint(使熟悉)+-ance(名词后缀)→熟悉的状态或熟悉的人→熟人；认识","example":"She is an old acquaintance of mine. 她是我的一位老相识。"},{"id":2800,"unit":9,"lesson":3,"word":"alien","pronunciation":"/ˈeɪliən/","meaning":"n.外星人;外国人 adj.陌生的","seq":69,"isStar":false,"memo":"【谐音+联想】'额里恩'→‘额头上长外星触角’！ali-（其他）+ -en（形容词），本义‘他者’，引申为‘陌生的/外国的’。","example":"The sudden policy shift made the regulatory environment feel alien to small businesses. 突然的政策转向让监管环境对小企业而言变得陌生。"},{"id":2801,"unit":9,"lesson":3,"word":"alienate","pronunciation":"/ˈeɪliəneɪt/","meaning":"v.使疏远;离间","seq":70,"isStar":false},{"id":2802,"unit":9,"lesson":3,"word":"alienation","pronunciation":"/ˌeɪliəˈneɪʃ(ə)n/","meaning":"n.离间;疏远","seq":71,"isStar":false},{"id":2803,"unit":9,"lesson":3,"word":"isolate","pronunciation":"/ˈaɪsəleɪt/","meaning":"v.(使)隔离,孤立","seq":72,"isStar":false,"memo":"谐音+对照：‘爱锁来特’→病毒来了，医生立刻‘爱’上你、‘锁’进单间、‘来特’（let）你独处！和insulate比：isolate重人，insulate重物。","example":"Hospitals isolate patients with contagious diseases immediately. 医院立即隔离传染病患者。"},{"id":2804,"unit":9,"lesson":3,"word":"isolation","pronunciation":"/ˌaɪsəˈleɪʃn/","meaning":"n.隔离;隔离状态,孤立状态","seq":73,"isStar":false},{"id":2805,"unit":9,"lesson":3,"word":"drama","pronunciation":"/ˈdrɑːmə/","meaning":"n.戏剧;戏剧性事件","seq":74,"isStar":false,"memo":"构词 dram(做、演，同 drastic 激烈的)+-a→演出来给人看的故事→戏剧；戏剧性事件","example":"The play is a powerful drama. 这部戏是一部很有力量的戏剧。"},{"id":2806,"unit":9,"lesson":3,"word":"dramatic","pronunciation":"/drəˈmætɪk/","meaning":"adj.戏剧性的;引人注目的","seq":75,"isStar":false,"memo":"构词 drama(戏剧)+-tic(形容词后缀)→像戏一样抓人的→戏剧性的；引人注目的","example":"There was a dramatic change in the weather. 天气发生了剧烈的变化。"},{"id":2807,"unit":9,"lesson":3,"word":"dramatically","pronunciation":"/drəˈmætɪkli/","meaning":"adv.戏剧性地;剧烈地;明显地","seq":76,"isStar":false,"memo":"构词 dramatic(戏剧性的)+-al+-ly(副词后缀)→戏剧性地；剧烈地，明显地","example":"Prices rose dramatically last year. 去年物价大幅上涨。"},{"id":2808,"unit":9,"lesson":3,"word":"comedy","pronunciation":"/ˈkɒmədi/","meaning":"n.喜剧;幽默","seq":77,"isStar":false,"memo":"构词 com(宴饮、欢闹，同 comic 滑稽的)+-edy→欢闹的戏→喜剧；幽默","example":"We watched a comedy last night. 昨晚我们看了一部喜剧。"},{"id":2809,"unit":9,"lesson":3,"word":"tragedy","pronunciation":"/ˈtrædʒədi/","meaning":"n.悲惨的事,悲剧","seq":78,"isStar":false,"memo":"tra-（穿越）+ gedy（≈‘give it up’谐音梗）→ 穿越过去想拯救结局，结果还是‘悲剧’降临…莎士比亚式叹气。","example":"The oil spill was an environmental tragedy. 这起漏油事件是一场生态悲剧。"},{"id":2810,"unit":9,"lesson":3,"word":"tragic","pronunciation":"/ˈtrædʒɪk/","meaning":"adj.悲惨的,悲剧的","seq":79,"isStar":false},{"id":2811,"unit":9,"lesson":3,"word":"tragically","pronunciation":"/ˈtrædʒɪkli/","meaning":"adv.悲惨地,不幸地","seq":80,"isStar":false,"memo":"构词 trag(山羊歌→悲剧，同 tragedy 悲剧)+-ical+-ly(副词后缀)→悲惨地，不幸地","example":"He died tragically young. 他不幸英年早逝。"},{"id":2812,"unit":9,"lesson":3,"word":"disaster","pronunciation":"/dɪˈzɑːstə(r)/","meaning":"n.灾难;不幸","seq":81,"isStar":false,"memo":"谐音+构词：'弟砸他'→弟弟一砸，灾难来了！di-（否定）+aster（星，古指吉星）→凶星降临即灾难。","example":"The software bug caused a major disaster in the university's registration system. 这个软件漏洞导致学校选课系统严重瘫痪。"},{"id":2813,"unit":9,"lesson":3,"word":"disastrous","pronunciation":"/dɪˈzɑːstrəs/","meaning":"adj.极糟糕的;灾难性的","seq":82,"isStar":false},{"id":2814,"unit":9,"lesson":3,"word":"feeble","pronunciation":"/ˈfiːb(ə)l/","meaning":"adj.虚弱的,衰弱的","seq":83,"isStar":false,"memo":"fee（费）+ble（能）→‘缴费都费劲’？太虚弱啦！谐音‘废脖’→脖子都废了，站都站不稳～","example":"His feeble voice barely carried across the lecture hall. 他虚弱的声音几乎传不到讲堂对面。"},{"id":2815,"unit":9,"lesson":3,"word":"lean","pronunciation":"/liːn/","meaning":"v.倾斜;倚靠 adj.瘦且健康的","seq":84,"isStar":false,"memo":"谐音‘临’——你靠墙‘临’着站，就是lean！v.倚靠；adj.瘦得只剩骨架，像‘临’风而立的竹子。","example":"She leaned against the lab bench while reviewing the data. 她靠在实验台边审阅数据。"},{"id":2816,"unit":9,"lesson":3,"word":"shiver","pronunciation":"/ˈʃɪvə(r)/","meaning":"v.&n.(因寒冷、恐惧、激动等)颤抖","seq":85,"isStar":false,"memo":"联想 与 shake(摇动)同族：冷得轻轻发抖→(因寒冷、恐惧、激动)颤抖，哆嗦","example":"She shivered in the cold wind. 她在寒风中瑟瑟发抖。"},{"id":2817,"unit":9,"lesson":4,"word":"tremble","pronunciation":"/ˈtremb(ə)l/","meaning":"v.&n.(因紧张、激动、惊慌等)颤抖","seq":1,"isStar":false,"memo":"构词 trem(抖动，同 tremor 颤抖)+-ble(表反复动作)→不停地抖→颤抖，哆嗦；极担心","example":"His hands trembled with anger. 他的手气得发抖。"},{"id":2818,"unit":9,"lesson":4,"word":"tender","pronunciation":"/ˈtendə(r)/","meaning":"adj.温柔的;(食物)嫩的;脆弱的","seq":2,"isStar":false,"memo":"构词 tend(柔软、伸展)+-er→柔软易断的→温柔的；(食物)嫩的；脆弱的","example":"The meat was tender and juicy. 这肉又嫩又多汁。"},{"id":2819,"unit":9,"lesson":4,"word":"vulnerable","pronunciation":"/ˈvʌlnərəbl/","meaning":"adj.脆弱的;易受……伤害的","seq":3,"isStar":false,"memo":"构词：vulner-（伤口）+ -able（能…的）→ 能被划伤的→脆弱的。像没穿铠甲的脆皮战士。","example":"Children are especially vulnerable to online misinformation. 儿童尤其容易受到网络虚假信息的伤害。"},{"id":2820,"unit":9,"lesson":4,"word":"vulnerability","pronunciation":"/ˌvʌlnərəˈbɪləti/","meaning":"n.脆弱性;弱点","seq":4,"isStar":false},{"id":2821,"unit":9,"lesson":4,"word":"feature","pronunciation":"/ˈfiːtʃə(r)/","meaning":"n.特色,特点,特征 v.以……为特色","seq":5,"isStar":false,"memo":"构词 feat(做、造，同 fact 事实)+-ure(名词后缀)→造出来最显眼的那部分→特色，特征；以……为特色","example":"The main feature of the house is its garden. 这栋房子最大的特色是它的花园。"},{"id":2822,"unit":9,"lesson":4,"word":"trait","pronunciation":"/treɪt/","meaning":"n.(人的个性的)特征,特点","seq":6,"isStar":false,"memo":"trait ≈ ‘trace’（痕迹）→ 一个人身上留下的性格‘特征’，比如爱拖延、爱记笔记、爱偷偷改PPT配色…都是trait！","example":"Patience is a key trait for effective teachers. 耐心是优秀教师的关键特质。"},{"id":2823,"unit":9,"lesson":4,"word":"bacteria","pronunciation":"/bækˈtɪəriə/","meaning":"n.细菌","seq":7,"isStar":false,"memo":"拆成 bac-（棒）+teria（小东西）→显微镜下像小棒子的细菌，谐音‘罢课它’——细菌一闹，全班罢课！","example":"Proper handwashing helps prevent the spread of bacteria in schools. 正确洗手有助于防止细菌在校园传播。"},{"id":2824,"unit":9,"lesson":4,"word":"virus","pronunciation":"/ˈvaɪrəs/","meaning":"n.病毒","seq":8,"isStar":false,"memo":"【联想】‘Virus = Virus（维若斯）→维系网络的‘若斯’（罗斯）？错！它是偷偷‘维’护自己、‘若’无其事搞破坏的数字病毒！","example":"The IT department isolated the infected computer to prevent the virus from spreading across the network. IT部门隔离了受感染电脑以防病毒在网络中蔓延。"},{"id":2825,"unit":9,"lesson":4,"word":"germ","pronunciation":"/dʒɜːm/","meaning":"n.细菌,微生物,病菌","seq":9,"isStar":false,"memo":"构词 germ(芽、种子，同 germinate 发芽)→能长成病的小种子→细菌，微生物，病菌","example":"Wash your hands to kill germs. 洗手可以杀灭细菌。"},{"id":2826,"unit":9,"lesson":4,"word":"allergic","pronunciation":"/əˈlɜːdʒɪk/","meaning":"adj.过敏的","seq":10,"isStar":false,"memo":"谐音‘哦乐鸡’——‘哦！乐鸡（过敏）’！看到鸡毛就喊哦乐鸡！/ 构词：allerg(y)（过敏）+ -ic（形容词）。","example":"Many students are allergic to peanuts in the cafeteria. 许多学生对食堂的花生过敏。"},{"id":2827,"unit":9,"lesson":4,"word":"allergy","pronunciation":"/ˈælədʒi/","meaning":"n.过敏反应","seq":11,"isStar":false},{"id":2828,"unit":9,"lesson":4,"word":"chemical","pronunciation":"/ˈkemɪk(ə)l/","meaning":"n.化学品 adj.化学的","seq":12,"isStar":false,"memo":"构词 chem(化学)+-ical(形容词后缀)→与化学有关的→化学的；化学品","example":"The factory produces chemicals. 这家工厂生产化学制品。"},{"id":2829,"unit":9,"lesson":4,"word":"chemistry","pronunciation":"/ˈkemɪstri/","meaning":"n.化学","seq":13,"isStar":false,"memo":"构词 chem(化学)+-istry(学科后缀)→化学","example":"She studied chemistry at university. 她在大学学的是化学。"},{"id":2830,"unit":9,"lesson":4,"word":"chemist","pronunciation":"/ˈkemɪst/","meaning":"n.药剂师;药店","seq":14,"isStar":false,"memo":"构词 chem(化学)+-ist(表人)→懂化学的人；在英国指药剂师、药店","example":"Ask the chemist for advice. 去问问药剂师的意见。"},{"id":2831,"unit":9,"lesson":4,"word":"initiate","pronunciation":"/ɪˈnɪʃieɪt/","meaning":"v.开始,发起,创始,使了解","seq":15,"isStar":false,"memo":"构词：in-（入）+ iti（走，如exit）+ -ate→‘走进’一件事开头，即‘发起’！Initiate = in + it + i + ate（吃进去？不，是‘踏进去’！）","example":"The government will initiate a new policy on green education next term. 政府将于下学期启动绿色教育新政策。"},{"id":2832,"unit":9,"lesson":4,"word":"initiation","pronunciation":"/ɪˌnɪʃiˈeɪʃn/","meaning":"n.开始,发起,创始","seq":16,"isStar":false},{"id":2833,"unit":9,"lesson":4,"word":"initiative","pronunciation":"/ɪˈnɪʃətɪv/","meaning":"n.主动性,积极性;主动权;倡议","seq":17,"isStar":false,"memo":"构词 init(开始，同 initial 最初的)+-iative(名词后缀)→主动开头的本事→主动性，积极性；主动权；倡议","example":"She took the initiative to call first. 她主动先打了电话。"},{"id":2834,"unit":9,"lesson":4,"word":"initial","pronunciation":"/ɪˈnɪʃ(ə)l/","meaning":"adj.最初的,开始的","seq":18,"isStar":false,"memo":"【构词】in-（进入）+ iti-（开始，源自ire‘去’）+ -al → ‘刚进去’的状态→最初的；联想‘英式茶’——第一杯initial tea最提神！","example":"Her initial reaction to the policy change was confusion and skepticism. 她对政策变动的最初反应是困惑与怀疑。"},{"id":2835,"unit":9,"lesson":4,"word":"embark","pronunciation":"/ɪmˈbɑːk/","meaning":"v.上船;开始","seq":19,"isStar":false,"memo":"构词 em-(使进入)+bark(船，同 barge 驳船)→上船→上船；开始(新的行动)","example":"He embarked on a new career at forty. 他四十岁时开始了新的职业生涯。"},{"id":2836,"unit":9,"lesson":4,"word":"launch","pronunciation":"/lɔːntʃ/","meaning":"v.开始从事,发起","seq":20,"isStar":false,"memo":"【构词】l-（lift）+ aunch（≈ lunge猛冲）→ ‘抬升+猛冲’→ 发射！火箭点火那刻：‘浪冲！’","example":"They will launch the new app next Monday. 他们将于下周一上线新应用。"},{"id":2837,"unit":9,"lesson":4,"word":"minimum","pronunciation":"/ˈmɪnɪməm/","meaning":"n.最小值;最少量 adj.最低的","seq":21,"isStar":false,"memo":"min-（小）+ -imum（最…）→ 最小值！记成‘民imum’：老百姓只求最低生活保障～","example":"The lab requires a minimum of three peer-reviewed sources for each thesis. 实验室要求每篇论文至少引用三篇同行评议文献。"},{"id":2838,"unit":9,"lesson":4,"word":"maximum","pronunciation":"/ˈmæksɪməm/","meaning":"n.最大量;最大限度 adj.最高的","seq":22,"isStar":false,"memo":"max（最大缩写）+ -imum（名词后缀）→ 就是‘max值’！考试卷面分100，你考99？抱歉，maximum是100！","example":"The lab set the maximum safe voltage for the experiment. 实验室设定了该实验的安全最高电压。"},{"id":2839,"unit":9,"lesson":4,"word":"maximal","pronunciation":"/ˈmæksɪml/","meaning":"adj.最大的;最高的","seq":23,"isStar":false,"memo":"构词 maxim(最大，同 maximum 最大值)+-al(形容词后缀)→最大的，最高的","example":"The test measures maximal effort. 这项测试测量的是最大的用力程度。"},{"id":2840,"unit":9,"lesson":4,"word":"minimal","pronunciation":"/ˈmɪnɪm(ə)l/","meaning":"adj.极小的,极少的","seq":24,"isStar":false,"memo":"构词 minim(最小，同 minimum 最小值)+-al(形容词后缀)→极小的，极少的","example":"The damage was minimal. 损失极小。"},{"id":2841,"unit":9,"lesson":4,"word":"miniature","pronunciation":"/ˈmɪnɪtʃə(r)/","meaning":"adj.微型的,小型的 n.微型画","seq":25,"isStar":false,"memo":"【谐音+联想】‘迷你’+‘ature’（像nature自然）→迷你得像大自然缩微版！小到能放掌心的模型～","example":"The museum displayed a hand-painted miniature of the Forbidden City. 博物馆展出了手绘的紫禁城微缩模型。"},{"id":2842,"unit":9,"lesson":4,"word":"minority","pronunciation":"/maɪˈnɒrəti/","meaning":"n.少数;少数民族","seq":26,"isStar":false,"memo":"构词 minor(较小的)+-ity(名词后缀)→数量上居少的一方→少数；少数民族","example":"Only a small minority voted against. 只有少数人投了反对票。"},{"id":2843,"unit":9,"lesson":4,"word":"minimise/-ize","pronunciation":"/ˈmɪnɪmaɪz/","meaning":"v.使减少到最低限度,使最小化;低估","seq":27,"isStar":false,"memo":"构词 minim(最小)+-ise/-ize(使…化)→使变得最小→使减少到最低限度；低估","example":"We must minimise the risks. 我们必须把风险降到最低。"},{"id":2844,"unit":9,"lesson":4,"word":"maximise/-ize","pronunciation":"/ˈmæksɪmaɪz/","meaning":"v.使增加到最大限度,充分利用","seq":28,"isStar":false,"memo":"构词 maxim(最大)+-ise/-ize(使…化)→使变得最大→使增加到最大限度，充分利用","example":"You should maximise your study time. 你应该充分利用学习时间。"},{"id":2845,"unit":9,"lesson":4,"word":"major","pronunciation":"/ˈmeɪdʒə(r)/","meaning":"adj.主要的","seq":29,"isStar":false,"memo":"构词 maj(大，同 magnify 放大)+-or(比较级词尾)→更大的那一个→主要的，重大的；主修科目","example":"Safety is a major concern. 安全是主要顾虑。"},{"id":2846,"unit":9,"lesson":4,"word":"majority","pronunciation":"/məˈdʒɒrəti/","meaning":"n.大部分,大多数","seq":30,"isStar":false,"memo":"构词 major(较大的)+-ity(名词后缀)→占多数的一方→大部分，大多数","example":"The majority of students agree. 大多数学生表示同意。"},{"id":2847,"unit":9,"lesson":4,"word":"mass","pronunciation":"/mæs/","meaning":"n.大量;群众 v.聚集 adj.大批的","seq":31,"isStar":false,"memo":"谐音‘麻丝’——一堆乱麻缠成团，就是‘一堆/大量’！物理里是质量，社会里是群众（mass media大众媒体），adj.大规模的——麻丝太多，剪不断理还乱！","example":"The company launched a mass production of eco-friendly batteries. 公司启动了环保电池的大规模生产。"},{"id":2848,"unit":9,"lesson":4,"word":"massive","pronunciation":"/ˈmæsɪv/","meaning":"adj.大而重的;巨大的,强大的","seq":32,"isStar":false},{"id":2849,"unit":9,"lesson":4,"word":"tiny","pronunciation":"/ˈtaɪni/","meaning":"adj.极小的,微小的","seq":33,"isStar":false,"memo":"构词 tin(小，与 teeny 同源)+-y(形容词后缀)→小不点儿的→极小的，微小的","example":"She lives in a tiny flat. 她住在一间极小的公寓里。"},{"id":2850,"unit":9,"lesson":4,"word":"parameter","pronunciation":"/pəˈræmɪtə(r)/","meaning":"n.范围,界限;参数","seq":34,"isStar":false,"memo":"para-（旁边）+meter（测量）→在旁边划出的测量边界，即‘参数’或‘决定因素’！","example":"Age and education level are key parameters in this study. 年龄和教育程度是本研究的关键参数。"},{"id":2851,"unit":9,"lesson":4,"word":"metric","pronunciation":"/ˈmetrɪk/","meaning":"adj.米制的;公制的 n.度量工具","seq":35,"isStar":false,"memo":"构词 metr(测量，同 meter 米)+-ic(形容词后缀)→与测量有关的→米制的，公制的；衡量指标","example":"The country uses the metric system. 这个国家使用公制。"},{"id":2852,"unit":9,"lesson":4,"word":"geometry","pronunciation":"/dʒiˈɒmətri/","meaning":"n.几何(学);几何形状","seq":36,"isStar":false,"memo":"构词 geo(土地)+metr(测量)+-y(学科后缀)→古人丈量土地之学→几何(学)；几何形状","example":"Geometry is my favourite subject. 几何是我最喜欢的科目。"},{"id":2853,"unit":9,"lesson":4,"word":"geometric","pronunciation":"/ˌdʒiːəˈmetrɪk/","meaning":"adj.几何(学)的;几何图形的","seq":37,"isStar":false,"memo":"构词 geometr(几何)+-ic(形容词后缀)→几何(学)的；几何图形的","example":"The carpet has a geometric pattern. 这块地毯是几何图案。"},{"id":2854,"unit":9,"lesson":4,"word":"geometrically","pronunciation":"/ˌdʒiːəˈmetrɪkli/","meaning":"adv.几何上","seq":38,"isStar":false,"memo":"构词 geometric(几何的)+-al+-ly(副词后缀)→从几何上讲，几何上","example":"The two shapes are geometrically similar. 这两个图形在几何上相似。"},{"id":2855,"unit":9,"lesson":4,"word":"symmetry","pronunciation":"/ˈsɪmətri/","meaning":"n.对称","seq":39,"isStar":false,"memo":"构词 sym-(共同)+metr(测量)+-y(名词后缀)→两边量出来一样→对称","example":"The building has perfect symmetry. 这座建筑完全对称。"},{"id":2856,"unit":9,"lesson":4,"word":"symmetric(al)","pronunciation":"/sɪˈmetrɪk/","meaning":"adj.对称的","seq":40,"isStar":false,"memo":"构词 symmetr(对称)+-ic(形容词后缀)→对称的","example":"The face is almost symmetrical. 这张脸几乎是对称的。"},{"id":2857,"unit":9,"lesson":4,"word":"cemetery","pronunciation":"/ˈsemətri/","meaning":"n.墓地,公墓","seq":41,"isStar":false,"memo":"构词 cemet(安睡，源出希腊语“睡眠之地”)+-ery(表场所)→让人长睡的地方→墓地，公墓","example":"He was buried in a small cemetery. 他被安葬在一处小公墓里。"},{"id":2858,"unit":9,"lesson":4,"word":"diameter","pronunciation":"/daɪˈæmɪtə(r)/","meaning":"n.直径","seq":42,"isStar":false,"memo":"构词 dia-(穿过)+metr(测量)+-er→穿过圆心量出来的长度→直径","example":"The pipe is ten centimetres in diameter. 这根管子的直径是十厘米。"},{"id":2859,"unit":9,"lesson":4,"word":"thermometer","pronunciation":"/θəˈmɒmɪtə(r)/","meaning":"n.温度计","seq":43,"isStar":false,"memo":"构词 thermo(热)+metr(测量)+-er(表物)→测量热度的东西→温度计","example":"The thermometer reads thirty degrees. 温度计显示三十度。"},{"id":2860,"unit":9,"lesson":4,"word":"paradise","pronunciation":"/ˈpærədaɪs/","meaning":"n.天堂;乐园(指美好的环境)","seq":44,"isStar":false,"memo":"构词 para-(周围)+dise(围墙)→围墙围绕的花园，源出波斯语→天堂；乐园(美好的环境)","example":"This island is a holiday paradise. 这座岛是度假天堂。"},{"id":2861,"unit":9,"lesson":4,"word":"paradox","pronunciation":"/ˈpærədɒks/","meaning":"n.悖论;矛盾的人(或事物、情况)","seq":45,"isStar":false,"memo":"para-（相反）+ dox（希腊语‘观点’）→ ‘相反的观点’，即自相矛盾的结论，比如‘越减肥越胖’这种让人挠头的悖论。","example":"Climate change presents a paradox: economic growth often harms environmental sustainability. 气候变化呈现悖论：经济增长常损害环境可持续性。"},{"id":2862,"unit":9,"lesson":4,"word":"paradoxical","pronunciation":"/ˌpærəˈdɒksɪk(ə)l/","meaning":"adj.自相矛盾的;出乎意料的","seq":46,"isStar":false},{"id":2863,"unit":9,"lesson":4,"word":"orthodox","pronunciation":"/ˈɔːθədɒks/","meaning":"adj.传统的,正统的","seq":47,"isStar":false,"memo":"谐音+联想：‘奥特斗克思’→奥特曼打怪前先‘ orthodox ’（正统套路）：光之国规定动作不能乱改！ortho=正+dox=观点→正统观点。","example":"Many students challenge orthodox teaching methods in digital classrooms. 许多学生在数字课堂中挑战传统教学方法。"},{"id":2864,"unit":9,"lesson":4,"word":"parade","pronunciation":"/pəˈreɪd/","meaning":"n.游行;阅兵;炫耀 v.游行;炫耀","seq":48,"isStar":false,"memo":"构词 par(准备、展示，同 prepare)+-ade(名词后缀)→摆出来给人看→游行；阅兵；炫耀","example":"The soldiers paraded through the city. 士兵们列队穿过城市。"},{"id":2865,"unit":9,"lesson":4,"word":"patrol","pronunciation":"/pəˈtrəʊl/","meaning":"n.&v.巡逻,巡查","seq":49,"isStar":false,"memo":"构词 patr(父亲→守护者，同 patron 保护人)+-ol(表反复动作)→像家长一样来回巡视→巡逻，巡查","example":"Guards patrol the building at night. 保安夜里在大楼里巡逻。"},{"id":2866,"unit":9,"lesson":4,"word":"cruise","pronunciation":"/kruːz/","meaning":"v.乘船游览 n.乘船游览;航行","seq":50,"isStar":false,"memo":"构词 cru(十字，同 cross)→船在海上像画十字一样巡游→乘船游览；航行","example":"They cruised around the Mediterranean. 他们乘船游览了地中海。"},{"id":2867,"unit":9,"lesson":4,"word":"cruiser","pronunciation":"/ˈkruːzə(r)/","meaning":"n.巡洋舰;警车","seq":51,"isStar":false,"memo":"构词 cruise(巡游)+-er(表物)→在海上巡游的舰船→巡洋舰；警车","example":"A police cruiser stopped beside us. 一辆警车停在我们旁边。"},{"id":2868,"unit":9,"lesson":4,"word":"patriot","pronunciation":"/ˈpætriət/","meaning":"n.爱国者","seq":52,"isStar":false,"memo":"构词 patr(父亲、祖国)+-iot(表人)→把祖国当父亲一样爱的人→爱国者","example":"He was a patriot to the end. 他至死都是一个爱国者。"},{"id":2869,"unit":9,"lesson":4,"word":"patriotism","pronunciation":"/ˈpætriətɪzəm; ˈpeɪtriətɪzəm/","meaning":"n.爱国主义;爱国精神","seq":53,"isStar":false,"memo":"构词 patriot(爱国者)+-ism(主义)→爱国者的主张→爱国主义，爱国精神","example":"The speech stirred up patriotism. 这番讲话激起了爱国热情。"},{"id":2870,"unit":9,"lesson":4,"word":"patriotic","pronunciation":"/ˌpætriˈɒtɪk/","meaning":"adj.爱国的","seq":54,"isStar":false,"memo":"构词 patriot(爱国者)+-ic(形容词后缀)→与爱国者相符的→爱国的","example":"They sang patriotic songs. 他们唱起了爱国歌曲。"},{"id":2871,"unit":9,"lesson":4,"word":"parasite","pronunciation":"/ˈpærəsaɪt/","meaning":"n.寄生虫;靠他人为生的人","seq":55,"isStar":false,"memo":"联想 para-(旁边) + sit(坐) + e → 他总是坐在别人旁边,依附着别人,看起来就像个“寄生虫”。","example":"These flies carry a dangerous parasite. 这些苍蝇携带着一种危险的寄生虫。"},{"id":2872,"unit":9,"lesson":4,"word":"paradigm","pronunciation":"/ˈpærədaɪm/","meaning":"n.范例,典范,样式","seq":56,"isStar":false,"memo":"构词 para-(并列)+deigm(展示)→并列展示出来的样板→范例，典范，样式","example":"This became the paradigm for later research. 这成了后来研究的范例。"},{"id":2873,"unit":9,"lesson":4,"word":"sense","pronunciation":"/sens/","meaning":"n.(对重大事情的)感觉,意识;见识","seq":57,"isStar":false,"memo":"谐音 单词发音类似“神似”→神似是一种“感觉”。","example":"Even an imagined companion can give the bird a sense of security. 即使是想象中的同伴也能给鸟儿一种安全感。"},{"id":2874,"unit":9,"lesson":4,"word":"sensible","pronunciation":"/ˈsensəb(ə)l/","meaning":"adj.明智的,合理的;可感觉到的","seq":58,"isStar":false},{"id":2875,"unit":9,"lesson":4,"word":"sensitive","pronunciation":"/ˈsensətɪv/","meaning":"adj.善解人意的;敏感的","seq":59,"isStar":false,"memo":"sen-（感觉）+ -sitive（易…的）→ 感觉太‘敏’，风吹草动都‘感’觉得到！","example":"She is highly sensitive to cultural differences in classroom discussions. 她对课堂讨论中的文化差异极为敏感。"},{"id":2876,"unit":9,"lesson":4,"word":"sensitivity","pronunciation":"/ˌsensəˈtɪvəti/","meaning":"n.体贴;敏感性;灵敏度","seq":60,"isStar":false},{"id":2877,"unit":9,"lesson":4,"word":"sensation","pronunciation":"/senˈseɪʃ(ə)n/","meaning":"n.知觉,感觉;轰动","seq":61,"isStar":false,"memo":"构词 sens(感觉，同 sense 感觉)+-ation(名词后缀)→感觉；引起众人感觉的事→知觉，感觉；轰动","example":"There wasn't any discomfort, just a mild warming sensation. 没有任何不适,只有轻微发热的感觉。"},{"id":2878,"unit":9,"lesson":4,"word":"sensational","pronunciation":"/senˈseɪʃən(ə)l/","meaning":"adj.轰动的;耸人听闻的","seq":62,"isStar":false},{"id":2879,"unit":9,"lesson":4,"word":"sentiment","pronunciation":"/ˈsentɪmənt/","meaning":"n.(基于情感的)观点,看法;情绪","seq":63,"isStar":false,"memo":"联想 sent(send 的过去式) + i(我) + m(联想“妹”) + ent → 假如你把我妹妹送出去,我是会闹“情绪”的。","example":"This is a sentiment I wholeheartedly agree with. 这种观点我完全赞同。"},{"id":2880,"unit":9,"lesson":4,"word":"sentimental","pronunciation":"/ˌsentɪˈment(ə)l/","meaning":"adj.情感的;伤感的;多愁善感的","seq":64,"isStar":false},{"id":2881,"unit":9,"lesson":4,"word":"nonsense","pronunciation":"/ˈnɒns(ə)ns/","meaning":"n.胡扯,胡言乱语;毫无意义的话","seq":65,"isStar":false,"memo":"构词 non-(无)+sense(意义)→一点意义都没有的话→胡扯，胡言乱语","example":"You're talking nonsense! 你在胡说八道!"},{"id":2882,"unit":9,"lesson":4,"word":"intensive","pronunciation":"/ɪnˈtensɪv/","meaning":"adj.加强的;密集的;彻底的","seq":66,"isStar":false,"memo":"构词 in-(向内)+tens(拉紧，同 tense)+-ive(形容词后缀)→把力量往里绷紧的→加强的；密集的；十分细致的","example":"They are intensive studies of people's spending habits. 它们是对人们消费习惯的细致研究。"},{"id":2883,"unit":9,"lesson":4,"word":"intense","pronunciation":"/ɪnˈtens/","meaning":"adj.很大的,十分强烈的;激烈的","seq":67,"isStar":false,"example":"He is under intense pressure to resign.他承受着很大的辞职压力。"},{"id":2884,"unit":9,"lesson":4,"word":"intensity","pronunciation":"/ɪnˈtensəti/","meaning":"n.强烈;紧张","seq":68,"isStar":false},{"id":2885,"unit":9,"lesson":4,"word":"intensify","pronunciation":"/ɪnˈtensɪfaɪ/","meaning":"v.增强,加剧","seq":69,"isStar":false,"memo":"in（加强）+ tens（拉紧）+ ify（使…）→ 把弦越拉越紧！紧张感爆棚→增强。考试前心跳 intensify？弦快断了！","example":"Global warming has intensified extreme weather events in recent years. 全球变暖近年来加剧了极端天气事件。"},{"id":2886,"unit":9,"lesson":4,"word":"dense","pronunciation":"/dens/","meaning":"adj.密集的,稠密的","seq":70,"isStar":false,"memo":"构词 dens(稠密，同 condense 浓缩)+-e→挤得很紧的→密集的，稠密的","example":"The forest was dark and dense. 这片森林又暗又密。"},{"id":2887,"unit":9,"lesson":4,"word":"density","pronunciation":"/ˈdensəti/","meaning":"n.密度","seq":71,"isStar":false},{"id":2888,"unit":9,"lesson":4,"word":"condense","pronunciation":"/kənˈdens/","meaning":"v.凝结;压缩;浓缩","seq":72,"isStar":false,"memo":"con-(共同,一起)+dense(稠密的)→压缩;浓缩","example":"The mayor condensed his speech to allow time for his audience to raise questions.市长缩短了发言时间,以便给听众留出提问的时间。"},{"id":2889,"unit":9,"lesson":4,"word":"condensation","pronunciation":"/ˌkɒndenˈseɪʃ(ə)n/","meaning":"n.冷凝,凝结","seq":73,"isStar":false},{"id":2890,"unit":9,"lesson":4,"word":"capital","pronunciation":"/ˈkæpɪt(ə)l/","meaning":"n.首都;资本,资金 adj.大写的","seq":74,"isStar":false,"memo":"【谐音+联想】‘凯皮托尔’——首都（如华盛顿Capitol）像盖大楼一样‘凯’旋立‘皮’厚‘托’起国家核心！","example":"Beijing serves as China's political and cultural capital. 北京是中国的政治与文化首都。"},{"id":2891,"unit":9,"lesson":4,"word":"capitalist","pronunciation":"/ˈkæpɪtəlɪst/","meaning":"n.资本主义者","seq":75,"isStar":false},{"id":2892,"unit":9,"lesson":4,"word":"capitalism","pronunciation":"/ˈkæpɪtəlɪzəm/","meaning":"n.资本主义","seq":76,"isStar":false},{"id":2893,"unit":9,"lesson":4,"word":"capacity","pronunciation":"/kəˈpæsəti/","meaning":"n.容量;能力","seq":77,"isStar":false,"memo":"cap（帽子，象征‘容纳’）+ acity（状态）→ 帽子能装几颗糖？就是‘容量’！脑子能装多少知识？就是‘能力’！一词双关，帽子真能装！","example":"His mental capacity impressed the neurologist during the test. 他在测试中展现的认知能力给神经科医生留下深刻印象。"},{"id":2894,"unit":9,"lesson":4,"word":"capable","pronunciation":"/ˈkeɪpəb(ə)l/","meaning":"adj.有能力的;能力强的","seq":78,"isStar":false,"memo":"cap-（头，引申为‘能力顶点’）+ -able（能…的）→ 头脑在线，就能干！谐音‘开炮able’——火力全开，稳稳能行！","example":"She is highly capable of leading complex research projects. 她完全有能力领导复杂的科研项目。"},{"id":2895,"unit":9,"lesson":4,"word":"capability","pronunciation":"/ˌkeɪpəˈbɪləti/","meaning":"n.能力,才能","seq":79,"isStar":false},{"id":2896,"unit":9,"lesson":4,"word":"capture","pronunciation":"/ˈkæptʃə(r)/","meaning":"v.捕获 n.(被)捕获","seq":80,"isStar":false,"memo":"【谐音】‘开扑彻’——警察开扑彻（扑上去）抓坏人！动词本义就是‘捕捉’。","example":"The drone captured stunning aerial footage of the campus. 无人机拍摄了校园震撼的空中影像。"},{"id":2897,"unit":9,"lesson":4,"word":"captive","pronunciation":"/ˈkæptɪv/","meaning":"adj.被监禁的 n.囚徒","seq":81,"isStar":false,"memo":"构词 capt(抓，同 capture 俘获)+-ive(形容词后缀)→被抓住的→被监禁的；囚徒","example":"The captive animals were finally released. 那些被圈养的动物终于被放归了。"},{"id":2898,"unit":9,"lesson":4,"word":"capsule","pronunciation":"/ˈkæpsjuːl/","meaning":"n.(装药物的)胶囊;太空舱","seq":82,"isStar":false,"memo":"构词 caps(盒子，同 case 箱)+-ule(小词后缀)→小盒子→胶囊；太空舱","example":"Take one capsule after each meal. 每餐后服一粒胶囊。"},{"id":2899,"unit":9,"lesson":4,"word":"caption","pronunciation":"/ˈkæpʃ(ə)n/","meaning":"n.(图片、漫画等的)说明文字","seq":83,"isStar":false,"memo":"构词 capt(抓取)+-ion(名词后缀)→抓住画面要点的文字→说明文字；字幕；标题","example":"The photo had a funny caption. 这张照片配了一句搞笑的说明。"},{"id":2900,"unit":9,"lesson":4,"word":"clutch","pronunciation":"/klʌtʃ/","meaning":"v.紧握,抓紧 n.控制;离合器","seq":84,"isStar":false,"memo":"联想 与 catch(抓住)形近：一把抓住→紧握，抓紧；控制；离合器","example":"She clutched the letter in her hand. 她把信紧紧攥在手里。"},{"id":2901,"unit":9,"lesson":4,"word":"cape","pronunciation":"/keɪp/","meaning":"n.披风,斗篷;岬角","seq":85,"isStar":false,"memo":"构词 cap(头，同 cap 帽子)+-e→从头上披到背后的一件→披风，斗篷；也指伸入海中的岬角","example":"He wore a red cape. 他披着一件红色的斗篷。"},{"id":2902,"unit":9,"lesson":4,"word":"escape","pronunciation":"/ɪˈskeɪp/","meaning":"v.逃跑;逃避,摆脱 n.逃跑","seq":86,"isStar":false,"memo":"构词 es-(向外)+cap(斗篷，同 cape)→甩开斗篷就跑→逃跑；逃避，摆脱","example":"They escaped through the back door. 他们从后门逃走了。"},{"id":2903,"unit":9,"lesson":4,"word":"cabin","pronunciation":"/ˈkæbɪn/","meaning":"n.小木屋;船舱;客舱","seq":87,"isStar":false,"memo":"构词 cab(小屋，同 cabinet)+-in→小屋子→小木屋；船舱，客舱","example":"We stayed in a wooden cabin by the lake. 我们住在湖边的小木屋里。"},{"id":2904,"unit":9,"lesson":4,"word":"cabinet","pronunciation":"/ˈkæbɪnət/","meaning":"n.内阁;储藏柜,陈列柜","seq":88,"isStar":false,"memo":"构词 cabin(小屋)+-et(小词后缀)→放小物件的柜子；也指在小屋里开会的班子→储藏柜，陈列柜；内阁","example":"The files are kept in the cabinet. 文件都存放在柜子里。"},{"id":2905,"unit":9,"lesson":4,"word":"cable","pronunciation":"/ˈkeɪb(ə)l/","meaning":"n.缆绳;电缆","seq":89,"isStar":false,"memo":"谐音‘凯布尔’→‘凯旋的缆绳’！海底电缆扛着数据大军凯旋登陆～","example":"Fiber-optic cables now carry most international internet traffic. 光纤电缆现承载大部分国际互联网流量。"},{"id":2906,"unit":10,"lesson":1,"word":"collide","pronunciation":"/kəˈlaɪd/","meaning":"v.碰撞,相撞;抵触,冲突","seq":1,"isStar":false,"memo":"构词 col-(共同)+lid(撞击，同 lesion 损伤)+-e→两者撞到一起→碰撞，相撞；抵触，冲突","example":"The two cars collided at the junction. 两辆车在路口相撞。"},{"id":2907,"unit":10,"lesson":1,"word":"collision","pronunciation":"/kəˈlɪʒ(ə)n/","meaning":"n.碰撞事故;冲突","seq":2,"isStar":false,"memo":"构词 col-(共同)+lis(撞击)+-ion(名词后缀)→撞在一起这件事→碰撞事故；冲突","example":"The collision damaged both vehicles. 这次碰撞损坏了两辆车。"},{"id":2908,"unit":10,"lesson":1,"word":"clash","pronunciation":"/klæʃ/","meaning":"n.冲突;不协调;撞击声 v.冲突;争论","seq":3,"isStar":false,"memo":"联想 与 crash(撞击)形近：金属相撞的刺耳声→冲突；不协调；撞击声","example":"The two teams clashed in the final. 两队在决赛中交锋。"},{"id":2909,"unit":10,"lesson":1,"word":"crash","pronunciation":"/kræʃ/","meaning":"v.碰撞,撞击,坠毁;暴跌 n.撞车","seq":4,"isStar":false,"memo":"联想 与 clash 形近：轰的一声撞上去→碰撞，撞击，坠毁；暴跌","example":"The plane crashed into the hillside. 飞机撞上了山坡。"},{"id":2910,"unit":10,"lesson":1,"word":"crush","pronunciation":"/krʌʃ/","meaning":"v.压碎,捣碎","seq":5,"isStar":false,"memo":"联想 与 crash 形近：压过去把它碾碎→压碎，捣碎；镇压","example":"The box was crushed in the post. 这个盒子在邮寄途中被压扁了。"},{"id":2911,"unit":10,"lesson":1,"word":"smash","pronunciation":"/smæʃ/","meaning":"n.破碎 v.打碎;猛击;粉碎","seq":6,"isStar":false,"memo":"拟声 哗啦一声打得粉碎→打碎；猛击；粉碎","example":"The ball smashed the window. 球把窗户打碎了。"},{"id":2912,"unit":10,"lesson":1,"word":"shatter","pronunciation":"/ˈʃætə(r)/","meaning":"v.(使)破碎,碎裂;使极为惊愕难过","seq":7,"isStar":false,"memo":"联想 与 scatter(散开)形近：碎成一片片散开→(使)破碎，碎裂；使极为惊愕难过","example":"The glass shattered on the floor. 玻璃在地板上碎成了片。"},{"id":2913,"unit":10,"lesson":1,"word":"crumble","pronunciation":"/ˈkrʌmb(ə)l/","meaning":"v.(使)粉碎;碎裂,崩裂,坍塌;崩溃","seq":8,"isStar":false,"memo":"构词 crum(碎屑，同 crumb 面包屑)+-ble(表反复动作)→碎成渣往下掉→(使)粉碎；坍塌；崩溃","example":"The old wall crumbled away. 那堵老墙渐渐坍塌剥落。"},{"id":2914,"unit":10,"lesson":1,"word":"ashamed","pronunciation":"/əˈʃeɪmd/","meaning":"adj.惭愧的,羞愧的;尴尬的","seq":9,"isStar":false,"memo":"联想 ash(灰) + a + me(我) + d(联想“的”) → 她说我的脸上有灰,我顿感“羞愧的”。","example":"He was ashamed of having asked such a silly question. 他因问了这样一个愚蠢的问题而感到羞愧。"},{"id":2915,"unit":10,"lesson":1,"word":"collapse","pronunciation":"/kəˈlæps/","meaning":"n.&v.倒塌,坍塌;崩溃","seq":10,"isStar":false,"memo":"联想 col-(都,一起) + lap(音似“来扑”) + se → 大家都来扑向这张床,结果床“坍塌”了。","example":"To our surprise, the roof collapsed under the weight of snow. 令我们惊讶的是,房顶在雪的重压下坍塌了。"},{"id":2916,"unit":10,"lesson":1,"word":"elapse","pronunciation":"/ɪˈlæps/","meaning":"v.(时间)消逝,流逝","seq":11,"isStar":false,"memo":"联想 e(字母音似“姨”) + lap(音似“来扑”) + se → 时光“流逝”,阿姨也长出了皱纹,原来谁也抓(留)不住时间。","example":"Many years had elapsed before they returned to their original urban areas. 多年以后,他们才回到原来的市区。"},{"id":2917,"unit":10,"lesson":1,"word":"dome","pronunciation":"/dəʊm/","meaning":"n.穹顶,圆屋顶;圆顶状物","seq":12,"isStar":false,"memo":"谐音‘兜米’——兜住一‘米’阳光的圆顶！dome = dom（统治，如domain）+ -e → 原指‘主宰性建筑’，今指穹顶，罩得住全场！","example":"The museum's glass dome allows natural light to flood the central hall. 博物馆的玻璃圆顶让自然光倾泻入中央大厅。"},{"id":2918,"unit":10,"lesson":1,"word":"Catholic","pronunciation":"/ˈkæθlɪk/","meaning":"adj.天主教的 n.天主教徒","seq":13,"isStar":false,"memo":"构词 cathol(普遍，源出希腊语“全体的”)+-ic(形容词后缀)→主张普世教会的→天主教的；天主教徒","example":"She was raised in a Catholic family. 她在一个天主教家庭长大。"},{"id":2919,"unit":10,"lesson":1,"word":"chapel","pronunciation":"/ˈtʃæp(ə)l/","meaning":"n.小教堂","seq":14,"isStar":false,"memo":"构词 chap(斗篷，圣马丁的斗篷曾被视为圣物)+-el(小词后缀)→存放圣物的小教堂→小教堂","example":"They married in a small chapel. 他们在一座小教堂里结了婚。"},{"id":2920,"unit":10,"lesson":1,"word":"domestic","pronunciation":"/dəˈmestɪk/","meaning":"adj.本国的,国内的;家用的;家庭的","seq":15,"isStar":false,"memo":"【构词】dom-（家，拉丁 domus）+ -estic →‘家里的’！联想到‘domestic helper’（家政帮手）、‘domestic flight’（国内航班）。","example":"Domestic demand plays a crucial role in sustaining national economic growth. 国内需求在支撑国民经济增长中起关键作用。"},{"id":2921,"unit":10,"lesson":1,"word":"dominate","pronunciation":"/ˈdɒmɪneɪt/","meaning":"v.支配,统治,控制,影响","seq":16,"isStar":false,"memo":"构词 domin(主人，同 domineer 专横)+-ate(动词后缀)→以主人的姿态压住对方→支配，统治，控制；占优势","example":"One company dominates the whole market. 一家公司垄断着整个市场。"},{"id":2922,"unit":10,"lesson":1,"word":"domination","pronunciation":"/ˌdɒmɪˈneɪʃn/","meaning":"n.支配,控制,影响","seq":17,"isStar":false,"memo":"构词 dominat(支配)+-ion(名词后缀)→被支配的状态→支配，控制，影响","example":"They resisted foreign domination. 他们抵抗外来的统治。"},{"id":2923,"unit":10,"lesson":1,"word":"dominance","pronunciation":"/ˈdɒmɪnəns/","meaning":"n.优势;支配,控制","seq":18,"isStar":false,"memo":"构词 domin(主人)+-ance(名词后缀)→处在主人地位→优势；支配，控制","example":"Sometimes, the dominance of the parents over their children causes communication problems.有时父母对孩子的支配会造成沟通问题。"},{"id":2924,"unit":10,"lesson":1,"word":"predominate","pronunciation":"/prɪˈdɒmɪneɪt/","meaning":"v.(在数量上)占优势;占主导地位","seq":19,"isStar":false,"memo":"[构词] pre-(提前) + dominate(支配)→提前占据支配地位→占主导地位","example":"A person's life is predominated by traditional custom. 一个人的一生都受传统习俗的支配。"},{"id":2925,"unit":10,"lesson":1,"word":"predominant","pronunciation":"/prɪˈdɒmɪnənt/","meaning":"adj.显著的;盛行的;占优势的;主导的","seq":20,"isStar":false,"memo":"构词 pre-(在前)+dominant(支配的)→在前面起支配作用的→显著的；盛行的，占优势的，主导的","example":"Information services will be predominant in the future. 未来,信息服务将占据主导地位。"},{"id":2926,"unit":10,"lesson":1,"word":"predominance","pronunciation":"/prɪˈdɒmɪnəns/","meaning":"n.(数量上的)优势;主导地位","seq":21,"isStar":false},{"id":2927,"unit":10,"lesson":1,"word":"control","pronunciation":"/kənˈtrəʊl/","meaning":"v.指挥,控制,支配 n.管理;控制","seq":22,"isStar":false,"memo":"构词 contra-(相反)+rol(辊子，同 roll)→用反向的辊子把速度刹住→控制，支配；管理；指挥","example":"Man can't be controlled by computers. 人不能被电脑控制。"},{"id":2928,"unit":10,"lesson":1,"word":"manipulate","pronunciation":"/məˈnɪpjuleɪt/","meaning":"v.操纵,控制;(熟练地)操作,使用","seq":23,"isStar":false,"memo":"[谐音] 单词发音类似“摸你扑了它”→工作的时候,你一会儿摸摸这台机器,一会儿扑向那台机器,说明你能“熟练地操作”它们。","example":"The technology uses a pen to manipulate a computer. 这项技术使用一支笔来操作计算机。"},{"id":2929,"unit":10,"lesson":1,"word":"manipulation","pronunciation":"/məˌnɪpjuˈleɪʃn/","meaning":"n.操纵,(暗中)控制","seq":24,"isStar":false},{"id":2930,"unit":10,"lesson":1,"word":"manipulative","pronunciation":"/məˈnɪpjələtɪv/","meaning":"adj.善于操纵的,会控制的","seq":25,"isStar":false},{"id":2931,"unit":10,"lesson":1,"word":"moderate","pronunciation":"/ˈmɒdərət/","meaning":"v.(使)缓和;(使)减轻;节制","seq":26,"isStar":false,"memo":"[联想] mode(联想 model) + rate(速度)→模特走路的速度是“适度的”。","example":"Moderate levels of conflict can motivate people. 适度的争论可以激励人们。"},{"id":2932,"unit":10,"lesson":1,"word":"moderation","pronunciation":"/ˌmɒdəˈreɪʃ(ə)n/","meaning":"n.适度,适中","seq":27,"isStar":false},{"id":2933,"unit":10,"lesson":1,"word":"moderator","pronunciation":"/ˈmɒdəreɪtə(r)/","meaning":"n.调解人,调停人","seq":28,"isStar":false},{"id":2934,"unit":10,"lesson":1,"word":"accelerate","pronunciation":"/əkˈseləreɪt/","meaning":"v.(使)加速,加快","seq":29,"isStar":false,"memo":"[联想] ac-(一再地)+cele(音似“赛了”)+rate(速度)→一再地比赛,到了最后阶段需要“加速”。","example":"It would accelerate the progress of AI research. 这将加速人工智能研究的进展。"},{"id":2935,"unit":10,"lesson":1,"word":"tolerate","pronunciation":"/ˈtɒləreɪt/","meaning":"v.容忍,容许;忍受,忍耐","seq":30,"isStar":false,"memo":"联想 tole(音似“逃了”) + rate(速度)→他以很快的速度逃跑了,因为“忍受”不了了。","example":"Reporters can tolerate rejection of their ideas if they get a fair hearing. 如果记者们的观点得到了公平的听取,那么他们就可以容忍别人的反对。"},{"id":2936,"unit":10,"lesson":1,"word":"tolerant","pronunciation":"/ˈtɒlərənt/","meaning":"adj.容忍的;宽容的","seq":31,"isStar":false},{"id":2937,"unit":10,"lesson":1,"word":"tolerance","pronunciation":"/ˈtɒlərəns/","meaning":"n.忍受;宽容","seq":32,"isStar":false},{"id":2938,"unit":10,"lesson":1,"word":"tolerable","pronunciation":"/ˈtɒlərəb(ə)l/","meaning":"adj.可接受的;可忍受的","seq":33,"isStar":false},{"id":2939,"unit":10,"lesson":1,"word":"endure","pronunciation":"/ɪnˈdjʊə(r)/","meaning":"v.忍受;持续存在","seq":34,"isStar":false,"memo":"联想 end(最后) + u(字母音同 you) + re (字母音似“阿姨”)→最后你实在“忍受”不了阿姨的唠叨了。","example":"It's never a question of whether you enjoy your job and your life, but only how much you can endure. 问题从来不在于你是否喜欢自己的工作和生活,而仅仅在于你能忍受多少。"},{"id":2940,"unit":10,"lesson":1,"word":"endurance","pronunciation":"/ɪnˈdjʊərəns/","meaning":"n.忍耐力,耐久力","seq":35,"isStar":false},{"id":2941,"unit":10,"lesson":1,"word":"duration","pronunciation":"/djuˈreɪʃn/","meaning":"n.持续,持续时间","seq":36,"isStar":false,"memo":"构词 dur(持续,持久) + -ation(名词后缀)→持续,持续时间","example":"His wounds knocked him out of combat for the duration. 在整个战斗期间,他的伤一直令他无法参战。"},{"id":2942,"unit":10,"lesson":1,"word":"tenure","pronunciation":"/ˈtenjə(r)/","meaning":"n.任期,任职","seq":37,"isStar":false,"memo":"构词 ten(持有，同 tenant 房客)+-ure(名词后缀)→持有职位的时间→任期，任职","example":"Tenure of high political office was beyond her.高层政治职位对她来说遥不可及。"},{"id":2943,"unit":10,"lesson":1,"word":"evaporate","pronunciation":"/ɪˈvæpəreɪt/","meaning":"v.(使)蒸发,挥发;(逐渐)消失","seq":38,"isStar":false,"memo":"构词 e-(向外) + vapor(蒸汽) + -ate(动词后缀)→(使)蒸发,挥发","example":"Water evaporates and rises as visible drops to form clouds. 水蒸发后上升,变成可见的水滴进而形成云。"},{"id":2944,"unit":10,"lesson":1,"word":"evaporation","pronunciation":"/ɪˌvæpəˈreɪʃ(ə)n/","meaning":"n.蒸发;(逐渐)消失","seq":39,"isStar":false},{"id":2945,"unit":10,"lesson":1,"word":"vanish","pronunciation":"/ˈvænɪʃ/","meaning":"v.突然消失,不存在","seq":40,"isStar":false,"memo":"谐音 单词发音类似“哇,你失”→哇,你“突然消失”不见了。","example":"My glasses seem to have vanished. 我的眼镜似乎不翼而飞了。"},{"id":2946,"unit":10,"lesson":1,"word":"hamper","pronunciation":"/ˈhæmpə(r)/","meaning":"v.妨碍;阻止","seq":41,"isStar":false,"memo":"[联想] ham(联想“汉姆”,人名)+p(联想“扑”)+er(联想“表示人的后缀”)→汉姆扑在一个人身上,“阻止”对方进球。","example":"The program has been hampered by lack of funds. 该计划因缺乏资金而受到阻碍。"},{"id":2947,"unit":10,"lesson":1,"word":"hinder","pronunciation":"/ˈhɪndə(r)/","meaning":"v.妨碍,阻碍","seq":42,"isStar":false,"memo":"[谐音] 单词发音类似“恨得”→她恨这个人恨得牙痒痒,想要“阻碍”他继续行事。","example":"Climate change hinders economic development. 气候变化阻碍了经济发展。"},{"id":2948,"unit":10,"lesson":1,"word":"hindrance","pronunciation":"/ˈhɪndrəns/","meaning":"n.妨碍;造成妨碍的人(或物)","seq":43,"isStar":false},{"id":2949,"unit":10,"lesson":1,"word":"obstacle","pronunciation":"/ˈɒbstək(ə)l/","meaning":"n.障碍,阻碍","seq":44,"isStar":false,"memo":"[谐音] 单词发音类似“哦,不是特抠”→我不是特别抠,我只是面临经济“障碍”。","example":"Age is not a major obstacle to their employment. 年龄并不是他们就业的主要障碍。"},{"id":2950,"unit":10,"lesson":1,"word":"prevent","pronunciation":"/prɪˈvent/","meaning":"v.阻止,阻碍","seq":45,"isStar":false,"memo":"[联想] pre-(前面)+vent(联想 went)→他走到我们前面,试图“阻止”我们。","example":"The new system helps to prevent hackers from breaking into websites. 这个新系统有助于防止黑客入侵网站。"},{"id":2951,"unit":10,"lesson":1,"word":"prevention","pronunciation":"/prɪˈvenʃn/","meaning":"n.预防;防止","seq":46,"isStar":false},{"id":2952,"unit":10,"lesson":1,"word":"preventive","pronunciation":"/prɪˈventɪv/","meaning":"adj.预防性的,防备的","seq":47,"isStar":false},{"id":2953,"unit":10,"lesson":1,"word":"exclude","pronunciation":"/ɪkˈskluːd/","meaning":"v.不包括,不放在考虑之列","seq":48,"isStar":false,"memo":"[构词] ex-(外)+clud(=close)+e→把……关在外面→不包括;把……排斥在外","example":"They exclude those who have stopped looking for a job. 他们排除了那些已经停止找工作的人。"},{"id":2954,"unit":10,"lesson":1,"word":"exclusive","pronunciation":"/ɪkˈskluːsɪv/","meaning":"n.独家新闻,独家报道 adj.独有的","seq":49,"isStar":false},{"id":2955,"unit":10,"lesson":1,"word":"exclusion","pronunciation":"/ɪkˈskluːʒ(ə)n/","meaning":"n.排斥;排除在外","seq":50,"isStar":false},{"id":2956,"unit":10,"lesson":1,"word":"conclude","pronunciation":"/kənˈkluːd/","meaning":"v.得出结论;总结;结束","seq":51,"isStar":false,"memo":"[构词] con-(所有)+clud(=close)+e→所有的都关闭了→结束","example":"Before the conference was over, I would conclude another 10 points. 会议结束前,我再总结十点。"},{"id":2957,"unit":10,"lesson":1,"word":"conclusive","pronunciation":"/kənˈkluːsɪv/","meaning":"adj.结论性的","seq":52,"isStar":false},{"id":2958,"unit":10,"lesson":1,"word":"conclusion","pronunciation":"/kənˈkluːʒn/","meaning":"n.结论;结束","seq":53,"isStar":false},{"id":2959,"unit":10,"lesson":1,"word":"eliminate","pronunciation":"/ɪˈlɪmɪneɪt/","meaning":"v.排除,消除;(比赛中)淘汰","seq":54,"isStar":false,"memo":"[构词] e-(出)+limin(限制)+-ate(动词后缀)→从限制中出去→排除,消除","example":"In the first round of the competition, three teams were eliminated. 比赛的第一轮淘汰了三支队伍。"},{"id":2960,"unit":10,"lesson":1,"word":"elimination","pronunciation":"/ɪˌlɪmɪˈneɪʃn/","meaning":"n.排除,淘汰;消灭","seq":55,"isStar":false},{"id":2961,"unit":10,"lesson":1,"word":"discharge","pronunciation":"/dɪsˈtʃɑːdʒ/","meaning":"v.排出;释放;解雇","seq":56,"isStar":false,"memo":"[构词] dis-(否定前缀)+charge(使承担责任)→不用承担责任→释放;准许离开","example":"The child had been treated and was being prepared for discharge. 这个孩子已经接受了治疗,目前正在准备出院。"},{"id":2962,"unit":10,"lesson":1,"word":"convenience","pronunciation":"/kənˈviːniəns/","meaning":"n.方便,便利;便利设施","seq":57,"isStar":false,"memo":"[联想] con-(所有,都)+venien(音似“为您”)+ce→所有服务都是为了您的“方便”。","example":"It's no accident that most gas stations have convenience stores attached. 大多数加油站都有便利店，这不是偶然现象。"},{"id":2963,"unit":10,"lesson":1,"word":"convenient","pronunciation":"/kənˈviːniənt/","meaning":"adj.方便的","seq":58,"isStar":false,"memo":"构词 con-(一起)+ven(来，同 invent 发明)+-ient(形容词后缀)→各种条件正好凑到一起来的→方便的","example":"convenience stores attached. 大多数加油站都有便利店,这不是偶然现象。"},{"id":2964,"unit":10,"lesson":1,"word":"handy","pronunciation":"/ˈhændi/","meaning":"adj.手边的,就近的;方便的,便利的","seq":59,"isStar":false,"memo":"【构词】hand（手）+ -y（形容词后缀）→手边的；方便的","example":"The girl is hurt, but we have no handy substitute. 这个女孩受伤了，但我们手边没有替补。"},{"id":2965,"unit":10,"lesson":1,"word":"convince","pronunciation":"/kənˈvɪns/","meaning":"v.使确信;使信服;说服","seq":60,"isStar":false,"memo":"【联想】con-（一起，都）+ vince（音似“吻死”）→我们都使劲地亲吻你，想使你确信，我们真的爱你→使确信","example":"You will be pleased to convince people with good arguments. 你会很乐意用有力的论据来说服人们。"},{"id":2966,"unit":10,"lesson":1,"word":"convincing","pronunciation":"/kənˈvɪnsɪŋ/","meaning":"adj.令人信服的,有说服力的","seq":61,"isStar":false},{"id":2967,"unit":10,"lesson":1,"word":"automate","pronunciation":"/ˈɔːtəmeɪt/","meaning":"v.使自动化","seq":62,"isStar":false,"memo":"【联想】auto-（自动的）+ m（联想 move）+ -ate（动词后缀）→使自动化","example":"They would need to automate its manufacturing and service industries. 他们需要实现制造业和服务业的自动化。"},{"id":2968,"unit":10,"lesson":1,"word":"automation","pronunciation":"/ˌɔːtəˈmeɪʃ(ə)n/","meaning":"n.自动化","seq":63,"isStar":false},{"id":2969,"unit":10,"lesson":1,"word":"automatic","pronunciation":"/ˌɔːtəˈmætɪk/","meaning":"n.自动换挡汽车 adj.自动的","seq":64,"isStar":false,"memo":"【对照】automate v.使自动化→automatic n. & adj.","example":"My camera has manual and automatic functions. 我的照相机有手调和自动两种功能。"},{"id":2970,"unit":10,"lesson":1,"word":"automatically","pronunciation":"/ˌɔːtəˈmætɪkli/","meaning":"adv.自动地;无意识地","seq":65,"isStar":false},{"id":2971,"unit":10,"lesson":1,"word":"vehicle","pronunciation":"/ˈviːəkl/","meaning":"n.交通工具,车辆;手段,工具","seq":66,"isStar":false,"memo":"【谐音】单词发音类似“违要扣”→“车辆”等“交通工具”违规行驶要扣分。","example":"Motor vehicles are important contributors to urban air pollution. 机动车是造成城市空气污染的重要因素。"},{"id":2972,"unit":10,"lesson":1,"word":"saddle","pronunciation":"/ˈsæd(ə)l/","meaning":"n.马鞍","seq":67,"isStar":false,"memo":"【谐音】单词发音类似“赛道”→在赛道上骑马要配备“马鞍”。","example":"Raise your head a little bit and hold the saddle. 稍微抬起头，握住马鞍。"},{"id":2973,"unit":10,"lesson":1,"word":"pedal","pronunciation":"/ˈped(ə)l/","meaning":"n.(自行车等的)踏板","seq":68,"isStar":false,"memo":"【谐音】单词发音类似“拍打”→拍打的节奏和“踩踏板”的节奏类似。","example":"She pressed her foot down sharply on the brake pedal. 她猛踩刹车踏板。"},{"id":2974,"unit":10,"lesson":1,"word":"pedestrian","pronunciation":"/pəˈdestriən/","meaning":"n.行人,步行者 adj.行人的","seq":69,"isStar":false,"memo":"【联想】pede（联想 pedal）+ str（联想 street）+ -ian（表示人的后缀）→他骑自行车穿过大街，“行人”纷纷避让。","example":"His style is so pedestrian that the book becomes a real bore. 他的文风很平庸，以致那本书成了一本真正乏味的书。"},{"id":2975,"unit":10,"lesson":1,"word":"array","pronunciation":"/əˈreɪ/","meaning":"n.大量;排列 v.排列","seq":70,"isStar":false,"memo":"联想 ar-(一再)+ray(光线)→一再地将“大量”珠宝“排列”在光线下。","example":"We saw arrays of fruit and vegetables. 我们看到了大量水果蔬菜。"},{"id":2976,"unit":10,"lesson":1,"word":"display","pronunciation":"/dɪˈspleɪ/","meaning":"v.陈列,展出,展示;显露","seq":71,"isStar":false,"memo":"联想 dis(音似“弟死”)+play(玩)→弟弟死活要玩玩具,因为他想给客人“展示”一下。","example":"They have a better view of what are on display. 他们对所展示的物品有更好的看法。"},{"id":2977,"unit":10,"lesson":1,"word":"exhibit","pronunciation":"/ɪɡˈzɪbɪt/","meaning":"n.展览品,陈列品 v.展出,陈列","seq":72,"isStar":false,"memo":"联想 ex-(向外)+hibi(联想 Hebe,人名)+t(联想“她”)→Hebe 把她的作品向外展示→展出","example":"I heard the recent sculpture exhibit was kind of disappointing. 我听说最近的雕塑展有点令人失望。"},{"id":2978,"unit":10,"lesson":1,"word":"exhibition","pronunciation":"/ˌeksɪˈbɪʃ(ə)n/","meaning":"n.展览(品);显示","seq":73,"isStar":false},{"id":2979,"unit":10,"lesson":1,"word":"inhibit","pronunciation":"/ɪnˈhɪbɪt/","meaning":"v.阻止,阻碍;抑制;使拘束","seq":74,"isStar":false,"memo":"联想 in(里面)+hibi(联想 Hebe,人名)+t(联想“他”)→Hebe 在里面“阻止”他出来。","example":"The managing director's presence inhibited them from asking questions. 总经理的在场使他们不便问问题。"},{"id":2980,"unit":10,"lesson":1,"word":"inhibition","pronunciation":"/ˌɪnhɪˈbɪʃ(ə)n/","meaning":"n.阻止,禁止","seq":75,"isStar":false},{"id":2981,"unit":10,"lesson":1,"word":"prohibit","pronunciation":"/prəˈhɪbɪt/","meaning":"v.禁止,阻止","seq":76,"isStar":false,"memo":"联想 pro-(前面)+hibi(联想 Hebe,人名)+t(联想“他”)→Hebe 站在他的前面,“阻止”他离开。","example":"The high cost of equipment prohibits many people from taking up this sport. 昂贵的装备令许多人对这项运动望而却步。"},{"id":2982,"unit":10,"lesson":1,"word":"prohibition","pronunciation":"/ˌprəʊɪˈbɪʃ(ə)n/","meaning":"n.(尤指通过法律的)禁止,阻止","seq":77,"isStar":false},{"id":2983,"unit":10,"lesson":1,"word":"prohibitive","pronunciation":"/prəˈhɪbətɪv/","meaning":"adj.(以法令)禁止的;贵得买不起的","seq":78,"isStar":false},{"id":2984,"unit":10,"lesson":1,"word":"choke","pronunciation":"/tʃəʊk/","meaning":"v.(使)窒息,卡住;(使)哽咽","seq":79,"isStar":false,"memo":"谐音 单词发音类似“撬开”→医生撬开婴儿的嘴,取出了“卡住”的鱼刺。","example":"Very small toys can choke a baby. 很小的玩具可使婴儿窒息。"},{"id":2985,"unit":10,"lesson":1,"word":"embrace","pronunciation":"/ɪmˈbreɪs/","meaning":"v.拥抱;包括,包含;欣然接受","seq":80,"isStar":false,"memo":"构词 em-(使,进入)+brace(手臂)→使进入手臂→拥抱","example":"It's imperative for us to embrace a workplace revolution. 我们必须迎接一场职场变革。"},{"id":2986,"unit":10,"lesson":1,"word":"mobile","pronunciation":"/ˈməʊbaɪl/","meaning":"adj.可移动的","seq":81,"isStar":false,"memo":"构词 mob(= move) + -ile(形容词后缀)→可移动的","example":"It's illegal to chat into a hand-held mobile phone while driving. 开车时使用手持移动电话聊天是违法的。"},{"id":2987,"unit":10,"lesson":1,"word":"mobilise/-ize","pronunciation":"/ˈməʊbəlaɪz/","meaning":"v.组织,动员;调用","seq":82,"isStar":false,"memo":"构词 mobil(移动，同 mobile 移动的)+-ise/-ize(使…化)→使全部动起来→组织，动员；调用","example":"The government mobilised the army. 政府动员了军队。"},{"id":2988,"unit":10,"lesson":1,"word":"emotion","pronunciation":"/ɪˈməʊʃ(ə)n/","meaning":"n.情感,情绪","seq":83,"isStar":false,"memo":"构词 e-(向外) + motion(移动)→向外移动、流露出来的东西→情感,情绪","example":"Suppressed emotions can contribute to stress-related disorders. 情绪压抑会导致与压力相关的疾病。"},{"id":2989,"unit":10,"lesson":1,"word":"emotional","pronunciation":"/ɪˈməʊʃən(ə)l/","meaning":"adj.情绪的;情绪激动的;有感染力的","seq":84,"isStar":false},{"id":2990,"unit":10,"lesson":1,"word":"rational","pronunciation":"/ˈræʃ(ə)nəl/","meaning":"adj.合理的,理性的;理智的","seq":85,"isStar":false,"memo":"联想 ratio(比率) + n(a)(联想“拿”) + -al(形容词后缀)→他总是拿比率作依据,是个很“理性的”人。","example":"I suggest that students should be more rational when it comes to certificates. 我建议学生在证书问题上应该更加理性。"},{"id":2991,"unit":10,"lesson":1,"word":"irrational","pronunciation":"/ɪˈræʃən(ə)l/","meaning":"adj.不合理的,不理性的","seq":86,"isStar":false,"memo":"构词 ir-(否定前缀)+rational(合理的，理性的)→不合理的，不理性的","example":"They have found it irrational to remain childless.他们认为不要孩子是不理性的。"},{"id":2992,"unit":10,"lesson":1,"word":"motivate","pronunciation":"/ˈməʊtɪveɪt/","meaning":"v.成为……的动机;激发,激励","seq":87,"isStar":false,"memo":"构词 motiv(e)(动机) + -ate(动词后缀)→使有动机→成为……的动机;激发","example":"The murder was motivated by hatred. 这起谋杀是由仇恨激起的。"},{"id":2993,"unit":10,"lesson":1,"word":"motivation","pronunciation":"/ˌməʊtɪˈveɪʃ(ə)n/","meaning":"n.动机;动力","seq":88,"isStar":false},{"id":2994,"unit":10,"lesson":1,"word":"motel","pronunciation":"/məʊˈtel/","meaning":"n.汽车旅馆","seq":89,"isStar":false,"memo":"构词 mo(= motor,汽车) + tel(= hotel,旅馆)→汽车旅馆","example":"Let's find a motel so that we can get an early start tomorrow. 我们去找个汽车旅馆,这样明天就可以早点出发了。"},{"id":2995,"unit":10,"lesson":1,"word":"promote","pronunciation":"/prəˈməʊt/","meaning":"v.促进,推动;提升;推销","seq":90,"isStar":false,"memo":"构词 pro-(向前) + mot(= move) + e→向前移动→促进,推动","example":"The campaign aims to promote healthy eating. 这项活动旨在促进健康饮食。"},{"id":2996,"unit":10,"lesson":1,"word":"promotion","pronunciation":"/prəˈməʊʃ(ə)n/","meaning":"n.提升,晋升;推销","seq":91,"isStar":false},{"id":2997,"unit":10,"lesson":1,"word":"remote","pronunciation":"/rɪˈməʊt/","meaning":"adj.遥远的;疏远的;远程的","seq":92,"isStar":false,"memo":"【构词】re-(回) + mot( = move) + e→往回移动,离目标越来越远→遥远的","example":"In remote mountain areas, voters arrived on horseback. 在偏远山区,选民们骑马赶来。"},{"id":2998,"unit":10,"lesson":1,"word":"prompt","pronunciation":"/prɒmpt/","meaning":"adj.立即的 v.促使;激励 n.提示","seq":93,"isStar":false,"memo":"【联想】pro-(在前) + m(联想“妹”) + pt(联想“扑他”)→妹妹看到面前的哥哥,立即扑向他→立即的","example":"Professors can give prompt feedback to students' homework. 教授可以对学生的家庭作业给予及时的反馈。"},{"id":2999,"unit":10,"lesson":1,"word":"impromptu","pronunciation":"/ɪmˈprɒmptjuː/","meaning":"adj.&adv.无准备的(地)","seq":94,"isStar":false,"memo":"联想 im-(不) + prompt(提示) + u(字母音同 you) → 不给你提示就让你自己做，你是“无准备的”。"},{"id":3000,"unit":10,"lesson":1,"word":"agitate","pronunciation":"/ˈædʒɪteɪt/","meaning":"v.鼓动,煽动;使焦虑不安;搅动","seq":95,"isStar":false,"memo":"【谐音】单词发音类似“爱激他的”→你总是爱用话语激他→煽动","example":"The speaker is agitating for the repeal of a tax. 这位演讲者在鼓动废除一项征税。"},{"id":3001,"unit":10,"lesson":1,"word":"agitation","pronunciation":"/ˌædʒɪˈteɪʃ(ə)n/","meaning":"n.焦虑不安;煽动","seq":96,"isStar":false},{"id":3002,"unit":10,"lesson":1,"word":"antagonism","pronunciation":"/ænˈtæɡənɪzəm/","meaning":"n.对抗情绪;敌对;敌意","seq":97,"isStar":false,"memo":"【联想】ant(i)-(对抗) + agon(联想 agony,痛苦) + -ism(名词后缀)→痛苦源于“对抗情绪”。","example":"The antagonism he felt towards his old enemy was still very strong. 他对宿敌的敌意仍然十分强烈。"},{"id":3003,"unit":10,"lesson":1,"word":"impetus","pronunciation":"/ˈɪmpɪtəs/","meaning":"n.动力;推动","seq":98,"isStar":false,"memo":"【联想】im-( = in-,里面) + pet(宠物) + us(我们)→在家里养宠物,可以“推动”我们责任感的培养。","example":"The debate seems to have lost much of its initial impetus. 辩论会似乎没有开始时那么大的冲劲了。"},{"id":3004,"unit":10,"lesson":1,"word":"impulse","pronunciation":"/ˈɪmpʌls/","meaning":"n.冲动,心血来潮;推动力;刺激","seq":99,"isStar":false,"memo":"【联想】im-( = in-,里面) + pul(联想“扑了”) + se→内心的“冲动”让我想要扑过去。","example":"Natural impulses of anger are expressed through acts of violence. 愤怒的自然冲动会通过暴力行为表现出来。"},{"id":3005,"unit":10,"lesson":1,"word":"impulsive","pronunciation":"/ɪmˈpʌlsɪv/","meaning":"adj.凭冲动行事的;易冲动的","seq":100,"isStar":false},{"id":3006,"unit":10,"lesson":1,"word":"pulse","pronunciation":"/pʌls/","meaning":"n.脉搏 v.搏动,跳动","seq":101,"isStar":false,"memo":"【对照】人在冲动(impulse)时,脉搏(pulse)跳得很快。","example":"His heart pulsed with excitement. 他的心激动地怦怦直跳。"},{"id":3007,"unit":10,"lesson":1,"word":"locomotive","pronunciation":"/ˌləʊkəˈməʊtɪv/","meaning":"n.机车;火车头 adj.移动的,运动的","seq":102,"isStar":false,"memo":"【联想】loco(音似“唠嗑”) + mot( = move) + -ive(后缀)→他们在“移动的”“火车头”里唠。","example":"Energy to drive a steam locomotive can be stored. 驱动蒸汽机车的能量可以被储存。"},{"id":3008,"unit":10,"lesson":1,"word":"loom","pronunciation":"/luːm/","meaning":"v.隐约出现;(尤指)令人惊恐地隐现","seq":103,"isStar":false,"memo":"联想 loo(形似100)+m(联想“妹”)→100米外有个妹妹，在人群中“显得突出”。","example":"Today Mars looms as humanity's next area to explore. 如今，火星隐约成为人类下一个要探索的领域。"},{"id":3009,"unit":10,"lesson":1,"word":"boom","pronunciation":"/buːm/","meaning":"n.繁荣,激增;流行 v.繁荣;隆隆作响","seq":104,"isStar":false,"memo":"联想 boo(形似600)+m(联想meter)→方圆600米内都是一派“繁荣”的景象。","example":"The thunder boomed like a cannon. 雷声隆隆，像大炮一样。"},{"id":3010,"unit":10,"lesson":1,"word":"baby boom","pronunciation":"/ˈbeɪbi buːm/","meaning":"n.生育高峰(期)","seq":105,"isStar":false,"memo":"构词 baby(婴儿)+boom(激增)→婴儿数量激增的时期→生育高峰(期)","example":"The baby boom lasted about twenty years. 生育高峰持续了大约二十年。"},{"id":3011,"unit":10,"lesson":1,"word":"baby boomer","pronunciation":"/ˈbeɪbi buːmə(r)/","meaning":"n.生育高峰期出生的人","seq":106,"isStar":false,"memo":"构词 baby boom(生育高峰)+-er(表人)→生育高峰期出生的人","example":"Many baby boomers are now retiring. 许多婴儿潮一代的人如今正在退休。"},{"id":3012,"unit":10,"lesson":1,"word":"flourish","pronunciation":"/ˈflʌrɪʃ/","meaning":"v.繁荣;兴旺;茁壮成长","seq":107,"isStar":false,"memo":"构词 flour(=flower)+-ish(动词后缀)→像开花一样→繁荣；茁壮成长","example":"The company has continued to flourish over the years. 该公司多年来一直蓬勃发展。"},{"id":3013,"unit":10,"lesson":1,"word":"bloom","pronunciation":"/bluːm/","meaning":"v.开花;兴旺 n.花朵","seq":108,"isStar":false,"memo":"联想 bloo(形似6,100)+m(联想“妹”)→花园里的6,100朵花在妹妹的精心照料下“开花”了。","example":"With the development in science and technology, man can make various flowers bloom before their time. 随着科学技术的发展，人们可以使各种各样的花提前绽放。"},{"id":3014,"unit":10,"lesson":1,"word":"gloom","pronunciation":"/ɡluːm/","meaning":"n.忧郁,郁闷,无望;幽暗,黑暗;昏暗","seq":109,"isStar":false,"memo":"联想 g(联想“哥”) + loo(形似100) + m (联想“妹”) → 哥哥和妹妹相距百里，无法相见，于是两人心情有些“忧郁”。","example":"One could present him in terms of his lonely gloom.人们可以从他孤独忧郁的角度来描绘他。"},{"id":3015,"unit":10,"lesson":1,"word":"gloomy","pronunciation":"/ˈɡluːmi/","meaning":"adj.忧郁的;阴暗的","seq":110,"isStar":false},{"id":3016,"unit":10,"lesson":2,"word":"elect","pronunciation":"/ɪˈlekt/","meaning":"v.选举,推选;选择,决定(做某事)","seq":1,"isStar":false,"memo":"构词 e-(出) + lect(选择) → 选择出 → 选举;选择","example":"He has been successfully elected Prime Minister. 他已成功当选首相。"},{"id":3017,"unit":10,"lesson":2,"word":"election","pronunciation":"/ɪˈlekʃ(ə)n/","meaning":"n.选举,推选(尤指从政)","seq":2,"isStar":false},{"id":3018,"unit":10,"lesson":2,"word":"elective","pronunciation":"/ɪˈlektɪv/","meaning":"adj.选举的;可选择的","seq":3,"isStar":false},{"id":3019,"unit":10,"lesson":2,"word":"select","pronunciation":"/sɪˈlekt/","meaning":"v.选择;挑选","seq":4,"isStar":false,"memo":"构词 se-(分开) + lect(选择) → 挑选","example":"He hasn't been selected for the team. 他未能入选该队。"},{"id":3020,"unit":10,"lesson":2,"word":"selection","pronunciation":"/sɪˈlekʃ(ə)n/","meaning":"n.选择;挑选;选拔","seq":5,"isStar":false},{"id":3021,"unit":10,"lesson":2,"word":"selective","pronunciation":"/sɪˈlektɪv/","meaning":"adj.选择性的,有选择的","seq":6,"isStar":false},{"id":3022,"unit":10,"lesson":2,"word":"collective","pronunciation":"/kəˈlektɪv/","meaning":"adj.集体的,共有的,共同的","seq":7,"isStar":false,"memo":"构词 collect(收集) + -ive(形容词后缀) → 收集在一起的 → 集体的,共有的","example":"It was a collective decision. 这是集体的决定。"},{"id":3023,"unit":10,"lesson":2,"word":"neglect","pronunciation":"/nɪˈɡlekt/","meaning":"v.疏于照顾;忽视,不予重视;疏漏","seq":8,"isStar":false,"memo":"构词 neg-(未) + lect(选择) → 未选 → 忽视;疏漏","example":"They tend to neglect training in analytical skills. 他们往往会忽视分析技能的训练。"},{"id":3024,"unit":10,"lesson":2,"word":"neglectful","pronunciation":"/nɪˈɡlektfl/","meaning":"adj.马虎的;不重视的,忽视的","seq":9,"isStar":false},{"id":3025,"unit":10,"lesson":2,"word":"negligible","pronunciation":"/ˈneɡlɪdʒəb(ə)l/","meaning":"adj.可以忽视的,微不足道的","seq":10,"isStar":false,"memo":"对照 neglect v.&n.忽视 → negligible adj.","example":"Although most birds have only a negligible sense of smell, they have acute vision. 虽然大多数鸟类只有微弱的嗅觉,但它们的视力却非常敏锐。"},{"id":3026,"unit":10,"lesson":2,"word":"negligent","pronunciation":"/ˈneɡlɪdʒənt/","meaning":"adj.疏忽的;放松的;漫不经心的","seq":11,"isStar":false,"memo":"构词 neg(不)+lig(在意，同 diligent 勤勉的)+-ent(形容词后缀)→该在意却不在意→疏忽的，漫不经心的","example":"He waved his hand in a negligent gesture. 他漫不经心地挥了挥手。"},{"id":3027,"unit":10,"lesson":2,"word":"ignore","pronunciation":"/ɪɡˈnɔː(r)/","meaning":"v.忽视,对……不予理会,不予理睬","seq":12,"isStar":false,"memo":"谐音 单词发音类似“一个闹”→他面对一个吵闹的人所采取的行动就是“忽视”对方。","example":"It ignores the fact that you are now beginning to be responsible for yourself. 它忽略了一个事实,那就是你现在开始要对自己负责了。"},{"id":3028,"unit":10,"lesson":2,"word":"ignorant","pronunciation":"/ˈɪɡnərənt/","meaning":"adj.无知的,愚昧的;很无礼的","seq":13,"isStar":false,"memo":"构词 i-(不)+gnor(知道，同 know)+-ant(形容词后缀)→不知道的→无知的，愚昧的；很无礼的","example":"It is not so bad being ignorant if you are totally ignorant. 如果你完全无知，那么无知也不是坏事。"},{"id":3029,"unit":10,"lesson":2,"word":"ignorance","pronunciation":"/ˈɪɡnərəns/","meaning":"n.无知","seq":14,"isStar":false},{"id":3030,"unit":10,"lesson":2,"word":"annoy","pronunciation":"/əˈnɔɪ/","meaning":"v.使恼怒,使生气;打扰","seq":15,"isStar":false,"memo":"[联想] an(一个) + noy(音似“闹”) → 这个小孩一个劲地闹，着实让家长生气 → 使生气","example":"Her twin sister often brings friends home and this annoys her. 她的双胞胎妹妹经常带朋友回家，这让她很恼火。"},{"id":3031,"unit":10,"lesson":2,"word":"notion","pronunciation":"/ˈnəʊʃ(ə)n/","meaning":"n.观念,想法","seq":16,"isStar":false,"memo":"[谐音] 单词发音类似“闹心”→女儿错误的“想法”使我很闹心。","example":"We should form the notion that waste is quite shameful. 我们应该形成浪费非常可耻的观念。"},{"id":3032,"unit":10,"lesson":2,"word":"notional","pronunciation":"/ˈnəʊʃənl/","meaning":"adj.猜测的;理论上的","seq":17,"isStar":false,"memo":"构词 not(知道、标记，同 notion 概念)+-ional(形容词后缀)→只停留在概念里的→猜测的；理论上的","example":"The figures were purely notional. 这些数字纯属理论上的假设。"},{"id":3033,"unit":10,"lesson":2,"word":"lecture","pronunciation":"/ˈlektʃə(r)/","meaning":"n.(通常指大学里的)讲座,讲课","seq":18,"isStar":false,"memo":"[构词] lect(说，讲) + -ure(后缀) → 讲座，讲课，演讲","example":"She gave lectures on how to become a public speaker. 她举办了关于如何成为一名公众演说家的讲座。"},{"id":3034,"unit":10,"lesson":2,"word":"lecturer","pronunciation":"/ˈlektʃərə(r)/","meaning":"n.讲课者,演讲者","seq":19,"isStar":false},{"id":3035,"unit":10,"lesson":2,"word":"dialect","pronunciation":"/ˈdaɪəlekt/","meaning":"n.方言,土话","seq":20,"isStar":false,"memo":"[联想] dia(联想“嗲”) + lect(说) → 他们说的“方言”听起来很嗲。","example":"It was difficult to understand the local dialect. 这种当地的方言很难懂。"},{"id":3036,"unit":10,"lesson":2,"word":"dispute","pronunciation":"/dɪˈspjuːt/","meaning":"n.争论,辩论","seq":21,"isStar":false,"memo":"[构词] dis-(分开) + put(思考) + e → 不同的思考，想法不一 → 争论","example":"It could lead to more out-of-court settlements of such disputes. 这可能会导致更多此类纠纷的庭外和解。"},{"id":3037,"unit":10,"lesson":2,"word":"disputable","pronunciation":"/dɪˈspjuːtəb(ə)l/","meaning":"adj.可质疑的;可商榷的","seq":22,"isStar":false},{"id":3038,"unit":10,"lesson":2,"word":"debate","pronunciation":"/dɪˈbeɪt/","meaning":"n.&v.争论,辩论","seq":23,"isStar":false,"memo":"[构词] de-(往下) + bat(= beat) + e → 把对手往下打 → 争论，辩论","example":"There was a most irritating end to every one of these debates. 每次这样的辩论都以一种极其令人恼火的方式收场。"},{"id":3039,"unit":10,"lesson":2,"word":"beat","pronunciation":"/biːt/","meaning":"v.打败(某人);敲打 n.跳动(声)","seq":24,"isStar":false,"memo":"联想 与 battle(战斗)同源：把对手打败，心跳也像敲鼓→打败；敲打；跳动(声)","example":"You almost beat the world's champions. 你差点就打败了世界冠军。"},{"id":3040,"unit":10,"lesson":2,"word":"whip","pronunciation":"/wɪp/","meaning":"n.鞭子 v.鞭策;鞭打","seq":25,"isStar":false,"memo":"联想 whi(音似we)+p(音似“扑”)→我们扑上去“鞭打”它。","example":"The rider cracked his whip to make the horse run faster. 骑马的人甩动鞭子让马跑得更快。"},{"id":3041,"unit":10,"lesson":2,"word":"bat","pronunciation":"/bæt/","meaning":"n.球棒,球拍,球板","seq":26,"isStar":false,"memo":"联想 不要用球拍(bat)击打蝙蝠(bat)。","example":"Do you have a baseball bat? 你有棒球棒吗?"},{"id":3042,"unit":10,"lesson":2,"word":"combat","pronunciation":"/ˈkɒmbæt/","meaning":"n.战斗,搏斗;打仗 v.与……搏斗","seq":27,"isStar":false,"memo":"构词 com-(一起)+bat(=beat)→战斗","example":"He was killed in combat. 他在战斗中阵亡。"},{"id":3043,"unit":10,"lesson":2,"word":"combative","pronunciation":"/ˈkɒmbətɪv/","meaning":"adj.好战的;好争论的","seq":28,"isStar":false},{"id":3044,"unit":10,"lesson":2,"word":"battle","pronunciation":"/ˈbæt(ə)l/","meaning":"n.战斗,战争;较量 v.搏斗;奋斗","seq":29,"isStar":false,"memo":"构词 bat(=beat)+t+-le(后缀)→战斗","example":"There exists the eternal battle between good and evil in the world. 世界上善恶之间存在永无休止的较量。"},{"id":3045,"unit":10,"lesson":2,"word":"conflict","pronunciation":"/ˈkɒnflɪkt/","meaning":"n.抵触,冲突,矛盾;战争 v.矛盾","seq":30,"isStar":false,"memo":"联想 con-(所有)+flict(音似“飞来剋他”)→所有人飞奔过来(打)他,因为发生了“冲突”。","example":"The results of the new research would seem to conflict with existing theories. 这项新的研究结果似乎与现有的理论相冲突。"},{"id":3046,"unit":10,"lesson":2,"word":"impart","pronunciation":"/ɪmˈpɑːt/","meaning":"v.传授,告知","seq":31,"isStar":false,"memo":"联想 i(我)+m(联想“妹”)+part(音似“怕他”)→我妹妹胆小,害怕那个“传授”知识的老师提问她。","example":"We can absorb information for the purpose of imparting it to others. 我们可以为了向他人告知信息而吸收信息。"},{"id":3047,"unit":10,"lesson":2,"word":"tuition","pronunciation":"/tjuˈɪʃ(ə)n/","meaning":"n.学费;教学","seq":32,"isStar":false,"memo":"谐音 单词发音类似“吐一身”→他交“学费”的时候正好胃部不适,吐了一身。","example":"The students have been protesting against the increased tuition. 学生们一直在抗议学费上涨。"},{"id":3048,"unit":10,"lesson":2,"word":"intuition","pronunciation":"/ˌɪntjuˈɪʃ(ə)n/","meaning":"n.直觉力;(一种)直觉","seq":33,"isStar":false,"memo":"in(里面) + tuition(学费)→他在家里就知道今年的学费会涨,他的“直觉”太准了。","example":"His intuition was telling him that something was wrong. 他的直觉告诉他有些不对劲。"},{"id":3049,"unit":10,"lesson":2,"word":"intuitive","pronunciation":"/ɪnˈtjuːɪtɪv/","meaning":"adj.直觉的;易懂的","seq":34,"isStar":false},{"id":3050,"unit":10,"lesson":2,"word":"depart","pronunciation":"/dɪˈpɑːt/","meaning":"v.离开;出发,启程","seq":35,"isStar":false,"memo":"单词发音类似“弟怕他”→弟弟因为怕他所以“离开”了。","example":"Flights for Rome depart from Terminal 3. 飞往罗马的航班从3号航站楼出发。"},{"id":3051,"unit":10,"lesson":2,"word":"departure","pronunciation":"/dɪˈpɑːtʃə(r)/","meaning":"n.离开;背离","seq":36,"isStar":false},{"id":3052,"unit":10,"lesson":2,"word":"quit","pronunciation":"/kwɪt/","meaning":"v.停止,放弃;离职","seq":37,"isStar":false,"memo":"qui(音似“快”) + t(联想“踢”)→快把他踢出去→放弃;离职","example":"The man has decided to quit his computer class. 这个人决定放弃他的计算机课。"},{"id":3053,"unit":10,"lesson":2,"word":"partial","pronunciation":"/ˈpɑːʃ(ə)l/","meaning":"adj.部分的,局部的;偏袒的","seq":38,"isStar":false,"memo":"构词 part(部分) + -ial(形容词后缀) → 部分的，局部的","example":"I might be accused of being partial.我可能会被指责有偏袒。"},{"id":3054,"unit":10,"lesson":2,"word":"partially","pronunciation":"/ˈpɑːʃəli/","meaning":"adv.部分地;不完全地","seq":39,"isStar":false},{"id":3055,"unit":10,"lesson":2,"word":"impartial","pronunciation":"/ɪmˈpɑːʃ(ə)l/","meaning":"adj.公正的,不偏不倚的","seq":40,"isStar":false},{"id":3056,"unit":10,"lesson":2,"word":"department","pronunciation":"/dɪˈpɑːtmənt/","meaning":"n.部;司;局;处;系;(医院的)科","seq":41,"isStar":false,"memo":"de-(分开) + part(部分) + -ment(名词后缀)→分开的各个部分→部门","example":"He works in the Physical Education Department. 他在体育系工作。"},{"id":3057,"unit":10,"lesson":2,"word":"apartment","pronunciation":"/əˈpɑːtmənt/","meaning":"n.公寓","seq":42,"isStar":false,"memo":"a(一) + part(部分) + -ment(名词后缀)→一个个分开的部分(单间)就是“公寓”。","example":"We sat down in the apartment and watched the game in near silence. 我们在公寓里坐下来,静静地观看比赛。"},{"id":3058,"unit":10,"lesson":2,"word":"flat","pronunciation":"/flæt/","meaning":"adj.平坦的,平的;无趣的 n.公寓","seq":43,"isStar":false,"memo":"fl(联想“飞来”) + at(在)→一只鸟飞来,落在一个“平坦的”地方。","example":"He felt very flat after his friends had gone home. 他的朋友们回家后,他感到兴味索然。"},{"id":3059,"unit":10,"lesson":2,"word":"terrace","pronunciation":"/ˈterəs/","meaning":"n.露天平台,阳台","seq":44,"isStar":false,"memo":"ter(音似“特”) + race(比赛)→这个“露天平台”特别大,能在上面举办跑步比赛。","example":"They want a terrace on the roof. 他们想在屋顶上建个露台。"},{"id":3060,"unit":10,"lesson":2,"word":"pasture","pronunciation":"/ˈpɑːstʃə(r)/","meaning":"n.牧场 v.放牧","seq":45,"isStar":false,"memo":"坐车路过(pass)的牧场(pasture)如同画(picture)一般美丽。","example":"You can use sensors looking down at the ground to check pasture quality. 你可以使用传感器朝下对准地面,以检测牧场的质量。"},{"id":3061,"unit":10,"lesson":2,"word":"ranch","pronunciation":"/rɑːntʃ/","meaning":"n.牧场,大农场","seq":46,"isStar":false,"memo":"联想 ran(run 的过去式) + ch(音似“驰”) → 在“牧场”上，马儿可以自由地奔跑、驰骋。","example":"What is special about the ranch?这个牧场有什么特别之处？"},{"id":3062,"unit":10,"lesson":2,"word":"particle","pronunciation":"/ˈpɑːtɪk(ə)l/","meaning":"n.颗粒,微粒;极少量","seq":47,"isStar":false,"memo":"对照 微粒(particle)是物质的重要组成部分(part)。","example":"A dust particle floated in the air.一粒尘埃漂浮在空气中。"},{"id":3063,"unit":10,"lesson":2,"word":"particular","pronunciation":"/pəˈtɪkjələ(r)/","meaning":"adj.特别的;特定的;挑剔的 n.细节","seq":48,"isStar":false,"memo":"谐音 单词发音类似“怕踢哭了”→他怕自己“特别的”脚法把别人踢哭了。","example":"They are particular about the quality of toilet paper. 他们对卫生纸的质量很挑剔。 particularly /pəˈtɪkjələli/ adv.特别;尤其"},{"id":3064,"unit":10,"lesson":2,"word":"particularly","pronunciation":"/pəˈtɪkjələli/","meaning":"adv.特别;尤其","seq":49,"isStar":false},{"id":3065,"unit":10,"lesson":2,"word":"apart","pronunciation":"/əˈpɑːt/","meaning":"adv.相隔,分开 adj.分离的","seq":50,"isStar":false,"memo":"联想 a(一)+part(部分)→一个一个部分地→分开","example":"The thing that sets children apart from adults is not their ignorance. 孩子和成年人的区别不在于他们的无知。"},{"id":3066,"unit":10,"lesson":2,"word":"compartment","pronunciation":"/kəmˈpɑːtmənt/","meaning":"n.(客车车厢内的)隔间","seq":51,"isStar":false,"memo":"构词 com-(共同)+part(部分)+-ment(名词后缀)→共同把一个整体分割成的各个部分→隔间;分隔间","example":"With the help of my brother, I opened the door of the compartment. 在我哥哥的帮助下,我打开了隔间的门。"},{"id":3067,"unit":10,"lesson":2,"word":"partition","pronunciation":"/pɑːˈtɪʃ(ə)n/","meaning":"n.隔断;分割 v.将……隔开;分割","seq":52,"isStar":false,"memo":"构词 part(部分,分开)+-ition(后缀)→隔断;分割","example":"The room is partitioned into three sections. 这间屋子被隔为三小间。"},{"id":3068,"unit":10,"lesson":2,"word":"decorate","pronunciation":"/ˈdekəreɪt/","meaning":"v.装饰,装修","seq":53,"isStar":false,"memo":"联想 de(音似“弟”)+cor(联想 core)+-ate(动词后缀)→弟弟的核心想法就是将新房子“装修”得漂漂亮亮的。","example":"They decorated the room with flowers and balloons. 他们用花和气球装饰了房间。"},{"id":3069,"unit":10,"lesson":2,"word":"decoration","pronunciation":"/ˌdekəˈreɪʃ(ə)n/","meaning":"n.装饰,装潢","seq":54,"isStar":false},{"id":3070,"unit":10,"lesson":2,"word":"decorative","pronunciation":"/ˈdekərətɪv/","meaning":"adj.装饰性的,作装饰用的","seq":55,"isStar":false},{"id":3071,"unit":10,"lesson":2,"word":"core","pronunciation":"/kɔː(r)/","meaning":"n.核儿;核心 adj.最重要的;主要的","seq":56,"isStar":false,"memo":"谐音 单词发音类似“靠”→大家都依靠的那个人就是“核心”。","example":"This report goes to the core of the argument. 这没有到不了的彼岸,没有行不至的远方。"},{"id":3072,"unit":10,"lesson":2,"word":"ornament","pronunciation":"/ˈɔːnəmənt/","meaning":"n.装饰;装饰品 v.装饰,点缀","seq":57,"isStar":false,"memo":"谐音 单词发音类似“哦那美特”→哦,那座房子真美,“装饰”得特别豪华。","example":"The baroque style is rich in ornament. 巴洛克风格以丰富的装饰为特色。"},{"id":3073,"unit":10,"lesson":2,"word":"ornamental","pronunciation":"/ˌɔːnəˈment(ə)l/","meaning":"adj.装饰性的,点缀的","seq":58,"isStar":false},{"id":3074,"unit":10,"lesson":2,"word":"cosmetic","pronunciation":"/kɒzˈmetɪk/","meaning":"adj.表面的;装门面的;化妆用的","seq":59,"isStar":false,"memo":"对照 角色扮演（cosplay）需要用化妆品（cosmetic）化妆。","example":"She found a job selling cosmetics.她找到了一份销售化妆品的工作。"},{"id":3075,"unit":10,"lesson":2,"word":"make-up","pronunciation":"/ˈmeɪk ʌp/","meaning":"n.化妆品;组成,构成;性格特点","seq":60,"isStar":false,"memo":"联想 正确使用化妆品（make-up）能弥补（make up）面部缺陷。","example":"I don't usually wear much make-up.我通常不怎么化妆。"},{"id":3076,"unit":10,"lesson":2,"word":"structure","pronunciation":"/ˈstrʌktʃə(r)/","meaning":"n.结构,构造 v.系统安排;精心组织","seq":61,"isStar":false,"memo":"谐音 单词发音类似“死抓可扯”→死抓着一个物品,可能会扯坏它的“结构”。","example":"Bees have a complex social structure. 蜜蜂有着复杂的社会结构。"},{"id":3077,"unit":10,"lesson":2,"word":"structural","pronunciation":"/ˈstrʌktʃərəl/","meaning":"adj.结构(或构造)上的","seq":62,"isStar":false},{"id":3078,"unit":10,"lesson":2,"word":"construct","pronunciation":"/kənˈstrʌkt/","meaning":"v.修建;建造","seq":63,"isStar":false,"memo":"联想 con-(所有)+struct(联想 structure)→所有建筑的结构都是工人“修建”的。","example":"The building was constructed in 1993. 这座建筑建造于1993年。"},{"id":3079,"unit":10,"lesson":2,"word":"construction","pronunciation":"/kənˈstrʌkʃn/","meaning":"n.建筑;建造","seq":64,"isStar":false},{"id":3080,"unit":10,"lesson":2,"word":"instruct","pronunciation":"/ɪnˈstrʌkt/","meaning":"v.命令,指示;教授,传授(技能等)","seq":65,"isStar":false,"memo":"联想 in(里面)+struct(音似“死抓个他”)→他们在里面死死抓着他的衣领,“命令”他别再执迷不悟了。","example":"She arrived at 10 o'clock as instructed. 她依照指示于10点钟到达。"},{"id":3081,"unit":10,"lesson":2,"word":"instruction","pronunciation":"/ɪnˈstrʌkʃ(ə)n/","meaning":"n.用法说明;命令,指示","seq":66,"isStar":false},{"id":3082,"unit":10,"lesson":2,"word":"instructor","pronunciation":"/ɪnˈstrʌktə(r)/","meaning":"n.教练;导师","seq":67,"isStar":false},{"id":3083,"unit":10,"lesson":2,"word":"instructive","pronunciation":"/ɪnˈstrʌktɪv/","meaning":"adj.富有教益的;增长知识的","seq":68,"isStar":false},{"id":3084,"unit":10,"lesson":2,"word":"establish","pronunciation":"/ɪˈstæblɪʃ/","meaning":"v.建立,创立,设立","seq":69,"isStar":false,"memo":"联想 e-(联想前缀 en-,使)+stabl(联想 stable)+-ish(动词后缀)→他的才能使他能平稳地“创立”了该学校。","example":"They plan to establish a new school in this area. 他们计划在这个地区创立一所新学校。"},{"id":3085,"unit":10,"lesson":2,"word":"establishment","pronunciation":"/ɪˈstæblɪʃmənt/","meaning":"n.建立;企业","seq":70,"isStar":false},{"id":3086,"unit":10,"lesson":2,"word":"erect","pronunciation":"/ɪˈrekt/","meaning":"v.建造;创立;竖立 adj.垂直的","seq":71,"isStar":false,"memo":"对照 城市里建造(erect)很多路和桥是正确的(correct)。","example":"The church was erected in 1582. 此教堂建造于1582年。"},{"id":3087,"unit":10,"lesson":2,"word":"erection","pronunciation":"/ɪˈrekʃn/","meaning":"n.建造;竖立","seq":72,"isStar":false},{"id":3088,"unit":10,"lesson":2,"word":"architecture","pronunciation":"/ˈɑːkɪtektʃə(r)/","meaning":"n.建筑学;建筑风格;结构","seq":73,"isStar":false,"memo":"联想 ar(联想 art)+chi+tecture(联想 structure)→“建筑学”是一种结构的艺术。","example":"The building is a prime example of the 1960s architecture. 这座大楼是20世纪60年代的典型建筑。"},{"id":3089,"unit":10,"lesson":2,"word":"architect","pronunciation":"/ˈɑːkɪtekt/","meaning":"n.建筑师,设计师;创造者","seq":74,"isStar":false,"memo":"构词 archi(首要)+tect(建造，同 technical 技术的)→主持建造的人→建筑师，设计师；创造者","example":"He is an architect practising in Texas. 他是个在得克萨斯州执业的建筑师。"},{"id":3090,"unit":10,"lesson":2,"word":"infrastructure","pronunciation":"/ˈɪnfrəstrʌktʃə(r)/","meaning":"n.基础设施;基础建设","seq":75,"isStar":false,"memo":"联想 in(里面)+fra+structure(结构)→一定要重视房子里面的结构,搞好“基础设施”的建设。","example":"They lack a suitable economic infrastructure. 它们缺乏合适的经济基础设施。"},{"id":3091,"unit":10,"lesson":2,"word":"tank","pronunciation":"/tæŋk/","meaning":"n.坦克","seq":76,"isStar":false,"memo":"谐音 单词发音类似“坦克”。","example":"Both dolphins were put in the same tank. 两只海豚都被放在同一个水箱里。"},{"id":3092,"unit":10,"lesson":2,"word":"bullet","pronunciation":"/ˈbʊlɪt/","meaning":"n.子弹,弹丸","seq":77,"isStar":false,"memo":"谐音 单词发音类似“崩了他”→“子弹”已上膛,如果他再作恶,警察必会崩了他。","example":"He had fired five bullets from his gun. 他开枪射击了五发子弹。"},{"id":3093,"unit":10,"lesson":2,"word":"navy","pronunciation":"/ˈneɪvi/","meaning":"n.海军;海军部队","seq":78,"isStar":false,"memo":"谐音 单词发音类似“那位”→那位哥哥是一名“海军”军官。","example":"The North had an established army, navy, and government. 北方已经建立了陆军、海军和政府。"},{"id":3094,"unit":10,"lesson":2,"word":"naval","pronunciation":"/ˈneɪv(ə)l/","meaning":"adj.海军的","seq":79,"isStar":false},{"id":3095,"unit":10,"lesson":2,"word":"corps","pronunciation":"/kɔː(r)/","meaning":"n.军,兵团;一群人","seq":80,"isStar":false,"memo":"谐音 单词发音类似“靠”→他们靠着“一群人”赢得了战争。","example":"The Marine Corps is on a mission. 海军陆战队在执行任务。"},{"id":3096,"unit":10,"lesson":2,"word":"military","pronunciation":"/ˈmɪlətri/","meaning":"n.军人;军队;军方 adj.军事的","seq":81,"isStar":false,"memo":"联想 mili(音似“没了”)+tary(音似 tree)→敌人“军方”经过的地方,连树都没有留下。","example":"The government increased military spending this year. 政府今年增加了军费开支。"},{"id":3097,"unit":10,"lesson":2,"word":"militant","pronunciation":"/ˈmɪlɪtənt/","meaning":"adj.好战的;激进的 n.激进分子","seq":82,"isStar":false,"memo":"(谐音) 单词发音类似“灭了他的”→这个常说“灭了他的”的“激进分子”是“好战的”。","example":"Militant groups have been blamed for a series of attacks in the region. 武装组织被指应为该地区发生的一系列袭击事件负责。"},{"id":3098,"unit":10,"lesson":2,"word":"militancy","pronunciation":"/ˈmɪlɪtənsi/","meaning":"n.战斗性,交战状态","seq":83,"isStar":false},{"id":3099,"unit":10,"lesson":2,"word":"siege","pronunciation":"/siːdʒ/","meaning":"n.包围,围攻;封锁","seq":84,"isStar":false,"memo":"联想 si(联想“四”) + e(联想“鹅”) + ge(联想“哥”) → 四只鹅“围攻”哥哥。","example":"The siege was finally ended after six months.围困终于在六个月后结束。"},{"id":3100,"unit":10,"lesson":2,"word":"besiege","pronunciation":"/bɪˈsiːdʒ/","meaning":"v.围困;包围","seq":85,"isStar":false,"memo":"发音请以词条的已核验音标及词典来源为准；原巧记含未核验读音，已停用。","example":"The professor was besieged by students asking for grade reviews. 教授被要求复核成绩的学生团团围住。"},{"id":3101,"unit":10,"lesson":2,"word":"attack","pronunciation":"/əˈtæk/","meaning":"v.&n.袭击,攻击;批评","seq":86,"isStar":false,"memo":"(联想) a(一个) + ttack(音似tank)→一辆坦克正在“袭击”敌人。","example":"The soldier was accused of running away when the enemy attacked. 这个士兵被指控在敌人进攻时逃跑。"},{"id":3102,"unit":10,"lesson":2,"word":"tactic","pronunciation":"/ˈtæktɪk/","meaning":"n.策略,手段;战术","seq":87,"isStar":false,"memo":"(联想) tac(音似 tank) + tic→用坦克进攻需要“策略”。","example":"They use effective tactics to defeat their competitors. 他们使用有效的战术来击败竞争对手。"},{"id":3103,"unit":10,"lesson":2,"word":"tact","pronunciation":"/tækt/","meaning":"n.(处事、言谈等)老练,圆通,得体","seq":88,"isStar":false,"memo":"对照 有策略(tactic)的人做事老练(tact)。","example":"With great tact, he persuaded her to apologise.他以极大的圆滑说服了她道歉。"},{"id":3104,"unit":10,"lesson":2,"word":"tactful","pronunciation":"/ˈtæktfl/","meaning":"adj.圆通的,得体的","seq":89,"isStar":false},{"id":3105,"unit":10,"lesson":2,"word":"contact","pronunciation":"/ˈkɒntækt/","meaning":"v.联系,联络 n.联系,联络;触摸","seq":90,"isStar":false,"memo":"(构词) con-(共同) + tact (= touch)→共同触碰→联系","example":"They have little close contact with adults. 他们几乎不与成年人密切接触。"},{"id":3106,"unit":10,"lesson":2,"word":"intact","pronunciation":"/ɪnˈtækt/","meaning":"adj.完好无损的,完整的","seq":91,"isStar":false,"memo":"(构词) in-(没有) + tact (= touch)→没有被触摸过的→完好无损的","example":"Most of the house remains intact even after two hundred years. 即使过了两百年,这房子的大部分还保持完好。"},{"id":3107,"unit":10,"lesson":2,"word":"assault","pronunciation":"/əˈsɔːlt/","meaning":"v.猛烈攻击,袭击 n.攻击,袭击","seq":92,"isStar":false,"memo":"(联想) as-(一再地) + saul(音似“骚”) + t(联想“他”)→一再地骚扰他→攻击,袭击","example":"Assaults often happen on school campuses in the war. 在战争中,校园里经常发生袭击事件。"},{"id":3108,"unit":10,"lesson":2,"word":"insult","pronunciation":"/ɪnˈsʌlt; ˈɪnsʌlt/","meaning":"n.辱骂;侮辱 v.辱骂;冒犯","seq":93,"isStar":false,"memo":"(联想) in(音似“言”) + sult(联想 result)→意见不合时不能用语言“辱骂”得到结果。","example":"He took her remark as a personal insult. 他把她的那句话当成了对自己的侮辱。"},{"id":3109,"unit":10,"lesson":2,"word":"consult","pronunciation":"/kənˈsʌlt/","meaning":"v.咨询;请教;商议;商量;查阅","seq":94,"isStar":false,"memo":"con-(所有的)+sult(联想 result)→通过“咨询”,所有的问题都有了结果。","example":"If the pain continues, consult your doctor. 如果疼痛持续不消退,要请医生诊治。"},{"id":3110,"unit":10,"lesson":2,"word":"consultation","pronunciation":"/ˌkɒns(ə)lˈteɪʃ(ə)n/","meaning":"n.咨询;商讨","seq":95,"isStar":false},{"id":3111,"unit":10,"lesson":2,"word":"consultative","pronunciation":"/kənˈsʌltətɪv/","meaning":"adj.咨询的;顾问的","seq":96,"isStar":false},{"id":3112,"unit":10,"lesson":2,"word":"consultant","pronunciation":"/kənˈsʌltənt/","meaning":"n.顾问","seq":97,"isStar":false},{"id":3113,"unit":10,"lesson":2,"word":"counsel","pronunciation":"/ˈkaʊnsl/","meaning":"n.律师;法律顾问 v.提供专业咨询","seq":98,"isStar":false,"memo":"coun-(= com-,所有)+sel(联想 sell)→你最好找个“律师”寻求“建议”,别轻易把你所有的家产都变卖了。","example":"The court then heard counsel for the woman. 法庭接着听取了这位女士所请的辩护律师的陈述。"},{"id":3114,"unit":10,"lesson":2,"word":"condolence","pronunciation":"/kənˈdəʊləns/","meaning":"n.吊唁,哀悼","seq":99,"isStar":false,"memo":"联想 con-(所有) + do(做) + lence(音似“愣死”) → 所有能做的都做了，他愣是死了，我们要去“吊唁”他。","example":"Please accept my sincere condolences. 请接受我诚挚的哀悼。"},{"id":3115,"unit":10,"lesson":2,"word":"convention","pronunciation":"/kənˈvenʃ(ə)n/","meaning":"n.习俗,惯例;大会","seq":100,"isStar":false,"memo":"con-(所有)+vention(音似“文身”)→这里的所有人都文身,这是当地的“习俗”。","example":"Convention demands that a club member should resign in such a situation. 惯例要求俱乐部成员在这种情况下应该辞职。"},{"id":3116,"unit":10,"lesson":2,"word":"conventional","pronunciation":"/kənˈvenʃən(ə)l/","meaning":"adj.墨守成规的;传统的","seq":101,"isStar":false},{"id":3117,"unit":10,"lesson":2,"word":"convene","pronunciation":"/kənˈviːn/","meaning":"v.聚集,集合;开会","seq":102,"isStar":false,"memo":"con-(所有)+vene(音似 went)→所有人都去“开会”了。","example":"The committee will convene at 11:30 AM next Thursday. 委员会将在下星期四上午11:30开会。"},{"id":3118,"unit":10,"lesson":2,"word":"convey","pronunciation":"/kənˈveɪ/","meaning":"v.表达,传递;传送,运送","seq":103,"isStar":false,"memo":"con-(所有)+vey(音似 way)→所有东西都已在路上“运送”。","example":"A good teacher must know how to convey his ideas. 一个好老师必须知道如何表达他的思想。"},{"id":3119,"unit":10,"lesson":2,"word":"conveyance","pronunciation":"/kənˈveɪəns/","meaning":"n.传送,运送","seq":104,"isStar":false},{"id":3120,"unit":10,"lesson":2,"word":"survey","pronunciation":"/ˈsɜːveɪ/","meaning":"n.调查;测量 v.调查;审视","seq":105,"isStar":false,"memo":"sur-(上面)+vey(音似 way)→他们正在路上“调查”真相。","example":"He surveyed 165 households. 他调查了165户家庭。"},{"id":3121,"unit":10,"lesson":2,"word":"invest","pronunciation":"/ɪnˈvest/","meaning":"v.投资,投入","seq":106,"isStar":false,"memo":"in-(进入)+vest(联想 west)→深入西部大开发,需要很多“投资”。","example":"They need to invest more in hospital staff and facilities. 他们需要在医院人员和设施方面加大投资。"},{"id":3122,"unit":10,"lesson":2,"word":"investor","pronunciation":"/ɪnˈvestə(r)/","meaning":"n.投资者;投资机构","seq":107,"isStar":false},{"id":3123,"unit":10,"lesson":2,"word":"investment","pronunciation":"/ɪnˈvestmənt/","meaning":"n.投资","seq":108,"isStar":false},{"id":3124,"unit":10,"lesson":2,"word":"investigate","pronunciation":"/ɪnˈvestɪɡeɪt/","meaning":"v.调查,侦查;研究","seq":109,"isStar":false,"memo":"invest(投资) + i(我) + gate(大门) → 我投资之前会在对方大门口“调查”清楚背景。","example":"We are better able to investigate social phenomena than physical phenomena. 我们更擅长研究社会现象而不是物理现象。"},{"id":3125,"unit":10,"lesson":2,"word":"investigation","pronunciation":"/ɪnˌvestɪˈɡeɪʃ(ə)n/","meaning":"n.调查","seq":110,"isStar":false},{"id":3126,"unit":10,"lesson":2,"word":"investigator","pronunciation":"/ɪnˈvestɪɡeɪtə(r)/","meaning":"n.调查者,侦查员","seq":111,"isStar":false},{"id":3127,"unit":10,"lesson":2,"word":"census","pronunciation":"/ˈsensəs/","meaning":"n.(官方的)统计,人口普查,人口调查","seq":112,"isStar":false,"memo":"构词 cens(评估、登记，同 censor 审查)+-us(名词后缀)→对全体人口的登记评估→统计，人口普查","example":"A national census is taken every ten years. 每十年进行一次全国人口普查。"},{"id":3128,"unit":10,"lesson":2,"word":"consensus","pronunciation":"/kənˈsensəs/","meaning":"n.共同意见,一致看法,共识","seq":113,"isStar":false,"memo":"con-(共同) + sens(感觉) + -us(名词后缀) → 共同的感觉 → 共同意见，共识","example":"The consensus among economists is that immigration should not be encouraged. 经济学家的共识是，不应该鼓励移民。"},{"id":3129,"unit":10,"lesson":2,"word":"unanimous","pronunciation":"/juˈnænɪməs/","meaning":"adj.(决定或意见)一致的,一致同意的","seq":114,"isStar":false,"memo":"u(音似 you) + na(音似“奶”) + nim(联想“你妹”) + -ous(形容词后缀) → 你奶奶和你妹妹的意见是“一致的”。","example":"The decision was not unanimous. 这项决定没有得到一致同意。"},{"id":3130,"unit":10,"lesson":2,"word":"reconcile","pronunciation":"/ˈrekənsaɪl/","meaning":"v.使和谐一致,协调;使和解,和好;将就","seq":115,"isStar":false,"memo":"re(字母音似“阿姨”) + con(联想前缀，所有) + cile(联想“吃了”) → 阿姨和所有人吃过饭就和解了 → 使和解，和好","example":"The couple could not reconcile their differences. 这对夫妇无法调和他们之间的分歧。"},{"id":3131,"unit":10,"lesson":2,"word":"reconciliation","pronunciation":"/ˌrekənsɪliˈeɪʃ(ə)n/","meaning":"n.和解;协调","seq":116,"isStar":false},{"id":3132,"unit":10,"lesson":2,"word":"reconciliatory","pronunciation":"/ˌrekənˈsɪlɪətəri/","meaning":"adj.调解的;和解的","seq":117,"isStar":false},{"id":3133,"unit":10,"lesson":2,"word":"retreat","pronunciation":"/rɪˈtriːt/","meaning":"v.&n.撤退;退却","seq":118,"isStar":false,"memo":"re-(回) + treat(处理) → 处理回去 → 撤退；退却","example":"The army was in full retreat. 部队全线撤退。"},{"id":3134,"unit":10,"lesson":3,"word":"repel","pronunciation":"/rɪˈpel/","meaning":"v.击退,驱逐;推开,赶走,驱除","seq":1,"isStar":false,"memo":"[联想] re-(重复) + pel(音似“迫”)→重复地压迫出去→驱逐;赶走","example":"This kind of material can repel heat and moisture. 这种材料能够耐热防潮。"},{"id":3135,"unit":10,"lesson":3,"word":"expel","pronunciation":"/ɪkˈspel/","meaning":"v.把……开除;驱逐出境;排出","seq":2,"isStar":false,"memo":"[联想] ex-(往外) + pel(音似“迫”)→把……压迫出去→驱逐出境;排出","example":"Cultivating positive interpersonal relationships helped him expel solitary feelings. 培养积极的人际关系帮助他摆脱孤独感。"},{"id":3136,"unit":10,"lesson":3,"word":"propel","pronunciation":"/prəˈpel/","meaning":"v.推动,驱动;迫使,驱使","seq":3,"isStar":false,"memo":"[联想] pro-(往前) + pel (音似“迫”)→迫使……往前走→推动,驱动","example":"Anger propelled her into action. 怒火驱使她行动起来。"},{"id":3137,"unit":10,"lesson":3,"word":"propeller","pronunciation":"/prəˈpelə(r)/","meaning":"n.螺旋桨","seq":4,"isStar":false},{"id":3138,"unit":10,"lesson":3,"word":"compel","pronunciation":"/kəmˈpel/","meaning":"v.强迫,迫使;引起(反应)","seq":5,"isStar":false,"memo":"[联想] com-(所有,一起) + pel(音似“迫”)→时间紧迫,他“迫使”所有人一起加快行动。","example":"He spoke with an authority that compelled the attention of the whole crowd. 他用权威的口气讲话,引起了整个人群的注意。"},{"id":3139,"unit":10,"lesson":3,"word":"compelling","pronunciation":"/kəmˈpelɪŋ/","meaning":"adj.引人入胜的,令人信服的","seq":6,"isStar":false,"memo":"构词 com-(加强)+pell(推动，同 pulse 脉搏)+-ing(形容词后缀)→推着你不得不信、不得不看→令人信服的；引人入胜的","example":"She gave a compelling argument. 她给出了一个令人信服的论证。"},{"id":3140,"unit":10,"lesson":3,"word":"squeeze","pronunciation":"/skwiːz/","meaning":"n.&v.压,挤,捏","seq":7,"isStar":false,"memo":"[谐音] 单词发音类似“死贵死”→这件衣服死(很)贵,你要死死地往下“压”价。","example":"Cut the lemon in half and squeeze the juice into the bowl. 把柠檬一切为二,将汁挤到碗里。"},{"id":3141,"unit":10,"lesson":3,"word":"direct","pronunciation":"/dəˈrekt/","meaning":"v.指导,指挥 adj.笔直的;直接的","seq":8,"isStar":false,"memo":"[联想] di(联想“弟”) + re(字母音似“阿姨”) + ct(音似“他”)→弟弟试图“指挥”阿姨干这干那,气得阿姨装要剋(打)他。","example":"Now we have the most direct evidence yet that he is right. 现在我们有了最直接的证据证明他是对的。"},{"id":3142,"unit":10,"lesson":3,"word":"direction","pronunciation":"/dəˈrekʃ(ə)n/","meaning":"n.方向;方位","seq":9,"isStar":false},{"id":3143,"unit":10,"lesson":3,"word":"director","pronunciation":"/dəˈrektə(r); daɪˈrektə(r)/","meaning":"n.董事;理事;经理","seq":10,"isStar":false},{"id":3144,"unit":10,"lesson":3,"word":"directory","pronunciation":"/dəˈrektəri/","meaning":"n.名录;电话簿;(计算机的)目录","seq":11,"isStar":false},{"id":3145,"unit":10,"lesson":3,"word":"connect","pronunciation":"/kəˈnekt/","meaning":"v.(使)连接;联结;接通","seq":12,"isStar":false,"memo":"联想 con-(所有)+ne(音似“奶”)+ct(音似“剋他”)→所有的奶奶都“联结”起来去剋(打)他。","example":"It is a great way to connect with the community. 这是与社区建立联系的好方法。"},{"id":3146,"unit":10,"lesson":3,"word":"connection","pronunciation":"/kəˈnekʃn/","meaning":"n.联系;联结","seq":13,"isStar":false},{"id":3147,"unit":10,"lesson":3,"word":"associate","pronunciation":"/əˈsəʊsieɪt; əˈsəʊʃieɪt/","meaning":"n.同事;伙伴 adj.副的 v.联想","seq":14,"isStar":false,"memo":"联想 as-(一再地)+so(如此)+ci(音似“吸”)+ate(后缀)→他们的优点如此吸引对方,于是他们开始“联系”。","example":"His son has got some sincere associates. 他的儿子有一些真诚的伙伴。"},{"id":3148,"unit":10,"lesson":3,"word":"association","pronunciation":"/əˌsəʊsiˈeɪʃn; əˌsəʊʃiˈeɪʃn/","meaning":"n.协会,社团;关联;联想,联系","seq":15,"isStar":false},{"id":3149,"unit":10,"lesson":3,"word":"link","pronunciation":"/lɪŋk/","meaning":"v.连接,联系 n.环节","seq":16,"isStar":false,"memo":"谐音 单词发音类似“拎个”→他拎出一条线索,“联系”起全文脉络。","example":"The two factors are directly linked. 这两个因素直接联系在一起。"},{"id":3150,"unit":10,"lesson":3,"word":"linkage","pronunciation":"/ˈlɪŋkɪdʒ/","meaning":"n.连接,联系","seq":17,"isStar":false,"memo":"构词 link(连接)+-age(名词后缀)→连接起来的关系→连接，联系","example":"There is a clear linkage between diet and health. 饮食与健康之间存在明显的联系。"},{"id":3151,"unit":10,"lesson":3,"word":"junction","pronunciation":"/ˈdʒʌŋkʃ(ə)n/","meaning":"n.(公路或铁路的)交叉路口;汇合处","seq":18,"isStar":false,"memo":"构词 junct(连接，同 join)+-ion(名词后缀)→道路接在一起的地方→交叉路口；汇合处","example":"The police have installed cameras at dangerous road junctions. 警察在危险的交叉路口安装了摄像头。"},{"id":3152,"unit":10,"lesson":3,"word":"conjunction","pronunciation":"/kənˈdʒʌŋkʃ(ə)n/","meaning":"n.连词;结合,同时发生","seq":19,"isStar":false,"memo":"联想 conj.是 conjunction 的缩写。","example":"All were grown in conjunction with mouse cells. 它们都是与小鼠细胞一起生长的。"},{"id":3153,"unit":10,"lesson":3,"word":"mingle","pronunciation":"/ˈmɪŋɡ(ə)l/","meaning":"v.(使)与……结合;使混合;使联结","seq":20,"isStar":false,"memo":"联想 min(联想“敏”,人名)+g(联想“哥”)+le(联想“了”)→阿敏和朋友的哥哥结为夫妻了→与……结合","example":"If we mingle with the crowd, we shall not be noticed. 如果我们混在人群里,就不会被注意到了。"},{"id":3154,"unit":10,"lesson":3,"word":"combine","pronunciation":"/kəmˈbaɪn/","meaning":"v.(使)联合,(使)结合","seq":21,"isStar":false,"memo":"联想 com(联想 company)+bine(联想“并”)→公司合并就是指公司“联合”。","example":"She combines work with study. 她把工作和学习结合起来。"},{"id":3155,"unit":10,"lesson":3,"word":"combination","pronunciation":"/ˌkɒmbɪˈneɪʃ(ə)n/","meaning":"n.联合(体),结合(体)","seq":22,"isStar":false,"memo":"构词 combin(结合)+-ation(名词后缀)→结合起来的那一组→联合(体)，结合(体)","example":"The two countries combined against their common enemy. 这两个国家联合起来对抗它们共同的敌人。"},{"id":3156,"unit":10,"lesson":3,"word":"tie","pronunciation":"/taɪ/","meaning":"n.领带;联系 v.系;使紧密结合","seq":23,"isStar":false,"memo":"联想 本义就是把两样东西系在一起→联系；领带；使紧密结合","example":"The firm has close ties with an American corporation. 这家公司与一家美国的公司关系密切。"},{"id":3157,"unit":10,"lesson":3,"word":"relevant","pronunciation":"/ˈreləvənt/","meaning":"adj.紧密相关的,切题的;有意义的","seq":24,"isStar":false,"memo":"联想 re-(重复)+le(音似“了”)+vant(音似“问他”)→人们重复地问了他,因为这件事跟他是“紧密相关的”。","example":"We try to make the experience relevant to individual lives. 我们努力让该体验与个人生活息息相关。"},{"id":3158,"unit":10,"lesson":3,"word":"relevance","pronunciation":"/ˈreləvəns/","meaning":"n.相关性;意义","seq":25,"isStar":false},{"id":3159,"unit":10,"lesson":3,"word":"integrate","pronunciation":"/ˈɪntɪɡreɪt/","meaning":"v.(使)合并,(使)结合","seq":26,"isStar":false,"memo":"联想 inte(音似“音体”)+grate(音同great)→音乐、体育“结合”好,全面发展促成长。","example":"They have not made any effort to integrate with the local community. 他们完全没有尝试融入本地社区。"},{"id":3160,"unit":10,"lesson":3,"word":"integration","pronunciation":"/ˌɪntɪˈɡreɪʃ(ə)n/","meaning":"n.结合;一体化","seq":27,"isStar":false},{"id":3161,"unit":10,"lesson":3,"word":"integral","pronunciation":"/ˈɪntɪɡrəl/","meaning":"adj.必需的;不可或缺的","seq":28,"isStar":false,"memo":"联想 integr(联想 integrate)+-al(形容词后缀)→使成为一体的→必需的;不可或缺的","example":"Practical experience is integral to the course. 实践经验是这门课程不可缺少的部分。"},{"id":3162,"unit":10,"lesson":3,"word":"integrity","pronunciation":"/ɪnˈteɡrəti/","meaning":"n.诚实正直;完整,完好","seq":29,"isStar":false,"memo":"联想 integr(联想 integrate)+-ity(名词后缀)→成为一体→完整","example":"A man of integrity is the one of integrity. 一个诚实正直的人才是完整的人。"},{"id":3163,"unit":10,"lesson":3,"word":"disintegrate","pronunciation":"/dɪsˈɪntɪɡreɪt/","meaning":"v.解体;分裂;瓦解","seq":30,"isStar":false,"memo":"构词 dis-(分开)+integr(完整，同 integer 整数)+-ate(动词后缀)→把完整的东西拆散→解体；分裂；瓦解","example":"An increasing number of companies have disintegrated.越来越多的公司解体了。"},{"id":3164,"unit":10,"lesson":3,"word":"disintegration","pronunciation":"/dɪsˌɪntɪˈɡreɪʃ(ə)n/","meaning":"n.分裂;瓦解","seq":31,"isStar":false},{"id":3165,"unit":10,"lesson":3,"word":"concrete","pronunciation":"/ˈkɒŋkriːt/","meaning":"adj.具体的;有形的 n.混凝土","seq":32,"isStar":false,"memo":"构词 con-(所有)+cret(=create)+-e→所有创造的东西都是“具体的”。","example":"The concrete was ready mixed. 混凝土是搅拌好的。"},{"id":3166,"unit":10,"lesson":3,"word":"emigrate","pronunciation":"/ˈemɪɡreɪt/","meaning":"v.移居国外;移民","seq":33,"isStar":false,"memo":"构词 e-(向外)+migr(迁移)+-ate(动词后缀)→迁出去→移居国外，移民","example":"The men emigrate to work as seamen.这些男人移居国外当海员。"},{"id":3167,"unit":10,"lesson":3,"word":"migrate","pronunciation":"/maɪˈɡreɪt/","meaning":"v.迁徙;移居,迁移","seq":34,"isStar":false,"memo":"构词 migr(迁移)+-ate(动词后缀)→搬到别处去→迁徙；移居，迁移","example":"We find that some birds migrate twice a year. 我们发现,一些鸟类每年都会迁徙两次。"},{"id":3168,"unit":10,"lesson":3,"word":"migration","pronunciation":"/maɪˈɡreɪʃn/","meaning":"n.迁徙;移居,迁移","seq":35,"isStar":false},{"id":3169,"unit":10,"lesson":3,"word":"immigrate","pronunciation":"/ˈɪmɪɡreɪt/","meaning":"v.(从外地)移居;移民","seq":36,"isStar":false,"memo":"构词 im-(向内)+migr(迁移)+-ate(动词后缀)→迁进来→(从外地)移居，移民","example":"About 6.6 million people immigrated to the United States then.当时大约有660万人移居美国。"},{"id":3170,"unit":10,"lesson":3,"word":"immigration","pronunciation":"/ˌɪmɪˈɡreɪʃ(ə)n/","meaning":"n.移居(入境);移民人数","seq":37,"isStar":false},{"id":3171,"unit":10,"lesson":3,"word":"immigrant","pronunciation":"/ˈɪmɪɡrənt/","meaning":"n.(外来)移民;外侨","seq":38,"isStar":false,"memo":"[构词] im-(= in-,入) + migrant(移民)→(外来)移民;外侨","example":"Immigrants from all over the world populate this city. 来自世界各地的移民居住在这个城市。"},{"id":3172,"unit":10,"lesson":3,"word":"emigrant","pronunciation":"/ˈemɪɡrənt/","meaning":"n.移居外国的人;移民","seq":39,"isStar":false,"memo":"构词 e-(向外)+migr(迁移)+-ant(表人)→迁出去的人→移居外国的人，移民","example":"During the reign, there was a flood of emigrants to North America.那个朝代统治期间，大量移民涌向北美洲。"},{"id":3173,"unit":10,"lesson":3,"word":"migrant","pronunciation":"/ˈmaɪɡrənt/","meaning":"n.移居者,移民;候鸟","seq":40,"isStar":false,"memo":"构词 migr(迁移)+-ant(表人或物)→迁徙的人或动物→移居者，移民；候鸟，迁徙动物","example":"The area was an important resting place for many types of migrant birds.这一带是许多候鸟的重要栖息地。"},{"id":3174,"unit":10,"lesson":3,"word":"candidate","pronunciation":"/ˈkændɪdət/","meaning":"n.候选人;应试者","seq":41,"isStar":false,"memo":"[联想] can(能够) + did(做) + ate(eat 的过去式)→“候选人”太紧张了,他能做的就是先吃点东西缓解情绪。","example":"There are some presidential candidates running for their first term in office. 有一些总统候选人在参加他们的第一个任期竞选。"},{"id":3175,"unit":10,"lesson":3,"word":"candidacy","pronunciation":"/ˈkændɪdəsi/","meaning":"n.候选人的资格(或身份)","seq":42,"isStar":false},{"id":3176,"unit":10,"lesson":3,"word":"recruit","pronunciation":"/rɪˈkruːt/","meaning":"n.新兵,新成员 v.招募(新兵)","seq":43,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + cru(音似“可入”) + it(它) → 阿姨可以加入这个俱乐部(它),即阿姨可以被“吸收”为“新成员”。","example":"New teachers and staff have to be recruited. 必须招聘新的教师和工作人员。"},{"id":3177,"unit":10,"lesson":3,"word":"recruitment","pronunciation":"/rɪˈkruːtmənt/","meaning":"n.吸收(新成员);征募(新兵)","seq":44,"isStar":false},{"id":3178,"unit":10,"lesson":3,"word":"enrol(l)","pronunciation":"/ɪnˈrəʊl/","meaning":"v.招(生),吸收(成员);注册,登记","seq":45,"isStar":false,"memo":"构词 en-(使)+ rol(l)(名单)→使加入名单→招（生），吸收（成员）","example":"The centre will soon be ready to enrol candidates for the new programme.该中心很快将准备好为这个新项目招收学员。"},{"id":3179,"unit":10,"lesson":3,"word":"enrol(l)ment","pronunciation":"/ɪnˈrəʊlmənt/","meaning":"n.入学,注册,登记","seq":46,"isStar":false,"memo":"构词 enrol(登记入册)+-ment(名词后缀)→入册这件事→入学，注册，登记","example":"Enrolment for the course closes on Friday. 这门课的注册周五截止。"},{"id":3180,"unit":10,"lesson":3,"word":"roll","pronunciation":"/rəʊl/","meaning":"n.卷;名单 v.滚动","seq":47,"isStar":false,"memo":"联想 与 enrol(登记)同根：把名单卷起来→名单；卷；滚动","example":"They bought a roll of toilet paper. 他们买了一卷卫生纸。"},{"id":3181,"unit":10,"lesson":3,"word":"roller","pronunciation":"/ˈrəʊlə(r)/","meaning":"n.滚筒;巨浪","seq":48,"isStar":false},{"id":3182,"unit":10,"lesson":3,"word":"register","pronunciation":"/ˈredʒɪstə(r)/","meaning":"n.名册,登记簿 v.登记,注册","seq":49,"isStar":false,"memo":"联想 re-(重复,再) + g(联想“哥”) + ister (联想 sister) → 那个哥哥和那个姐姐再次“登记”结婚了。","example":"The property register will say whether the property is freehold or leasehold. 房产登记簿会注明房产是永久产权还是租赁产权。"},{"id":3183,"unit":10,"lesson":3,"word":"registration","pronunciation":"/ˌredʒɪˈstreɪʃ(ə)n/","meaning":"n.注册,登记","seq":50,"isStar":false},{"id":3184,"unit":10,"lesson":3,"word":"registrar","pronunciation":"/ˌredʒɪˈstrɑː(r); ˈredʒɪstrɑː(r)/","meaning":"n.登记员;户籍管理员","seq":51,"isStar":false},{"id":3185,"unit":10,"lesson":3,"word":"participate","pronunciation":"/pɑːˈtɪsɪpeɪt/","meaning":"v.参与,参加","seq":52,"isStar":false,"memo":"联想 parti(音似“怕他”)+ ci(p)(抓)+ pate(音似“陪他”)→我怕他抓我去那个俱乐部，于是主动陪他“参加”该俱乐部的活动。","example":"Over half of the staff in the company participate in a strike.公司一半以上的员工参加了罢工。"},{"id":3186,"unit":10,"lesson":3,"word":"participant","pronunciation":"/pɑːˈtɪsɪpənt/","meaning":"n.参与者","seq":53,"isStar":false},{"id":3187,"unit":10,"lesson":3,"word":"participation","pronunciation":"/pɑːˌtɪsɪˈpeɪʃn/","meaning":"n.参加","seq":54,"isStar":false},{"id":3188,"unit":10,"lesson":3,"word":"anticipate","pronunciation":"/ænˈtɪsɪpeɪt/","meaning":"v.预料,预期;预见;期望","seq":55,"isStar":false,"memo":"谐音 单词发音类似“俺提吸陪她”→俺提着一兜可以吸的果冻去医院陪她,“期望”她会很高兴。","example":"We anticipate that sales will rise next year. 我们预料明年销售量将会增加。"},{"id":3189,"unit":10,"lesson":3,"word":"anticipation","pronunciation":"/ænˌtɪsɪˈpeɪʃ(ə)n/","meaning":"n.预料,预计","seq":56,"isStar":false},{"id":3190,"unit":10,"lesson":3,"word":"antique","pronunciation":"/ænˈtiːk/","meaning":"n.古物,古董 adj.古老的;古董的","seq":57,"isStar":false,"memo":"谐音 单词发音类似“俺提个”→俺提个“古董”去给行家看看。","example":"They found the antiques there more valuable. 他们发现那里的古董更有价值。"},{"id":3191,"unit":10,"lesson":3,"word":"ancient","pronunciation":"/ˈeɪnʃənt/","meaning":"adj.古代的;古老的","seq":58,"isStar":false,"memo":"谐音 单词发音类似“俺神仙”→俺喜欢那个神仙,他经常出现在“古老的”神话里。","example":"The pyramids were built in ancient times. 金字塔建造于古代。"},{"id":3192,"unit":10,"lesson":3,"word":"explode","pronunciation":"/ɪkˈspləʊd/","meaning":"v.爆炸;激增","seq":59,"isStar":false,"memo":"联想 ex-(向外) + plo(联想爆炸的声音) + de(联想前缀,往下)→烟花朝外“爆炸”后又坠落下来。","example":"A second bomb exploded. 第二枚炸弹爆炸了。"},{"id":3193,"unit":10,"lesson":3,"word":"explosion","pronunciation":"/ɪkˈspləʊʒ(ə)n/","meaning":"n.爆炸;激增","seq":60,"isStar":false},{"id":3194,"unit":10,"lesson":3,"word":"explosive","pronunciation":"/ɪkˈspləʊsɪv/","meaning":"n.爆炸物,炸药 adj.能引起爆炸的","seq":61,"isStar":false},{"id":3195,"unit":10,"lesson":3,"word":"explore","pronunciation":"/ɪkˈsplɔː(r)/","meaning":"v.勘查;探索;研究,探讨","seq":62,"isStar":false,"memo":"联想 ex-(向外) + plore(音似“扑姥”)→他朝外扑向来做客的姥姥,同她“探索”过去的事情。","example":"This book explores the musical interest and needs of children. 这本书探讨了儿童对音乐的兴趣和需求。"},{"id":3196,"unit":10,"lesson":3,"word":"exploration","pronunciation":"/ˌekspləˈreɪʃ(ə)n/","meaning":"n.探索,勘查","seq":63,"isStar":false},{"id":3197,"unit":10,"lesson":3,"word":"exploit","pronunciation":"/ɪkˈsplɔɪt/","meaning":"v.利用;开发,开采 n.英勇事迹,壮举","seq":64,"isStar":false,"memo":"联想 ex-(向外) + plo(音似“扑落”) + it(它)→猫咪向外扑落杂物,“开发”了它的专属领地。","example":"The studio is exploiting public opinion. 该工作室在利用公众舆论。"},{"id":3198,"unit":10,"lesson":3,"word":"tap","pronunciation":"/tæp/","meaning":"n.水龙头;阀门;轻拍 v.轻敲,轻拍","seq":65,"isStar":false,"memo":"联想 ta(联想“他”) + p(联想“拍”)→他“轻拍”了一下我的肩。","example":"It is a waste to leave the tap running. 让水龙头一直开着流水真是浪费。"},{"id":3199,"unit":10,"lesson":3,"word":"tub","pronunciation":"/tʌb/","meaning":"n.盆;盆,缸;浴缸","seq":66,"isStar":false,"memo":"谐音 单词发音类似“踏步”→他们拿着饭“盒”踏步,排队打饭。","example":"There were tubs of flowers on the balcony. 阳台上有一盆盆的花。"},{"id":3200,"unit":10,"lesson":3,"word":"utilise/-ize","pronunciation":"/ˈjuːtəlaɪz/","meaning":"v.使用,利用","seq":67,"isStar":false,"memo":"构词 util(有用，同 utility 效用)+-ise/-ize(使…化)→使其发挥作用→使用，利用","example":"We utilise solar energy to heat water. 我们利用太阳能来加热水。"},{"id":3201,"unit":10,"lesson":3,"word":"utilisation/-zation","pronunciation":"/ˌjuːtəlaɪˈzeɪʃ(ə)n/","meaning":"n.使用,利用","seq":68,"isStar":false,"memo":"构词 utilis(利用)+-ation(名词后缀)→利用这一行为","example":"Land utilisation here is very efficient. 这里的土地利用率非常高。"},{"id":3202,"unit":10,"lesson":3,"word":"utility","pronunciation":"/juːˈtɪləti/","meaning":"n.公用事业;实用,效用;实用程序","seq":69,"isStar":false,"memo":"对照 utilise/-ize v.使用,利用→utility n.","example":"The utility ends up abandoning the plant anyway. 最终公用事业公司还是放弃了这座发电厂。"},{"id":3203,"unit":10,"lesson":3,"word":"appliance","pronunciation":"/əˈplaɪəns/","meaning":"n.家用器具;家用电器","seq":70,"isStar":false,"memo":"[对照] apply v.应用→y变i加ance→appliance n.","example":"Don't turn on any electric appliance without permission.未经许可,不得擅自打开任何电器设备。"},{"id":3204,"unit":10,"lesson":3,"word":"mechanic","pronunciation":"/məˈkænɪk; mɪˈkænɪk/","meaning":"n.机械师;机械修理工;技工","seq":71,"isStar":false,"memo":"[对照] 他是一名机械修理工(mechanic),负责修理各种机器(machine)。","example":"I took my car to the mechanic to get it fixed.我把车送到修理工那里修理。"},{"id":3205,"unit":10,"lesson":3,"word":"mechanical","pronunciation":"/məˈkænɪkl/","meaning":"adj.机动的;机械的","seq":72,"isStar":false},{"id":3206,"unit":10,"lesson":3,"word":"mechanics","pronunciation":"/məˈkænɪks/","meaning":"n.机械学","seq":73,"isStar":false},{"id":3207,"unit":10,"lesson":3,"word":"mechanism","pronunciation":"/ˈmekənɪzəm/","meaning":"n.机械装置;机制","seq":74,"isStar":false},{"id":3208,"unit":10,"lesson":3,"word":"equip","pronunciation":"/ɪˈkwɪp/","meaning":"v.配备;装备;使有所准备;使有能力","seq":75,"isStar":false,"memo":"[谐音] 单词发音类似“一块布”→每个仆人都“配备”有一块布。","example":"When cars are equipped with such systems, thefts may drop by one third.当汽车配备了这样的系统,盗窃可能会减少三分之一。"},{"id":3209,"unit":10,"lesson":3,"word":"equipment","pronunciation":"/ɪˈkwɪpmənt/","meaning":"n.设备,装备","seq":76,"isStar":false},{"id":3210,"unit":10,"lesson":3,"word":"gadget","pronunciation":"/ˈɡædʒɪt/","meaning":"n.小器具;小装置","seq":77,"isStar":false,"memo":"[谐音] 单词发音类似“改进它”→大产品的升级离不开对一些“小装置”的改进。","example":"We'll observe how students use the gadgets.我们会观察学生们如何使用这些小装置。"},{"id":3211,"unit":10,"lesson":3,"word":"gadgetry","pronunciation":"/ˈɡædʒɪtri/","meaning":"n.小器具,小装置","seq":78,"isStar":false},{"id":3212,"unit":10,"lesson":3,"word":"instal(l)","pronunciation":"/ɪnˈstɔːl/","meaning":"v.安装,设置","seq":79,"isStar":false,"memo":"(记) (联想) in(里面)+s(音似“四”)+tall(高的)→他在院里踩着一个四米高的梯子“安装”设备。","example":"They installed a new heating system. 他们安装了一套新的供暖系统。"},{"id":3213,"unit":10,"lesson":3,"word":"screw","pronunciation":"/skruː/","meaning":"n.螺丝(钉) v.用螺丝钉固定;拧紧","seq":80,"isStar":false,"memo":"[谐音] 单词发音类似“四个儒”→四个儒雅的书生拧成一股绳,力量不可小觑→拧紧","example":"A screw is stronger than a nail.螺丝钉比普通钉子更牢固。"},{"id":3214,"unit":10,"lesson":3,"word":"scrutiny","pronunciation":"/ˈskruːtəni/","meaning":"n.仔细检查;认真彻底的审查","seq":81,"isStar":false,"memo":"[联想] scru(音似“四个儒”)+tiny(微小的)→四个儒生“仔细检查”那些微小的物件。","example":"Her argument doesn't really stand up to scrutiny.她的论点经不起认真推敲。"},{"id":3215,"unit":10,"lesson":3,"word":"employ","pronunciation":"/ɪmˈplɔɪ/","meaning":"v.雇用;应用,运用","seq":82,"isStar":false,"memo":"构词 em-(使进入)+ploy(折叠，同 ploy 计谋)→把人卷进工作里→雇用；应用，运用","example":"The plants employ chemical warfare to protect themselves. 这些植物采取化学战的方式保护自己。"},{"id":3216,"unit":10,"lesson":3,"word":"employment","pronunciation":"/ɪmˈplɔɪmənt/","meaning":"n.工作;雇用","seq":83,"isStar":false},{"id":3217,"unit":10,"lesson":3,"word":"employer","pronunciation":"/ɪmˈplɔɪə(r)/","meaning":"n.雇主;老板","seq":84,"isStar":false},{"id":3218,"unit":10,"lesson":3,"word":"employee","pronunciation":"/ɪmˈplɔɪiː/","meaning":"n.受雇者;雇员","seq":85,"isStar":false},{"id":3219,"unit":10,"lesson":3,"word":"deploy","pronunciation":"/dɪˈplɔɪ/","meaning":"v.部署,调度(军队或武器);有效地利用","seq":86,"isStar":false,"memo":"谐音 单词发音类似“弟捕捞一”→弟弟要去大海里捕捞，一定要好好“部署”。","example":"They can abstract precious medicines from ordinary substances.他们能从普通物质中提取珍贵的药物。"},{"id":3220,"unit":10,"lesson":3,"word":"deployment","pronunciation":"/dɪˈplɔɪmənt/","meaning":"n.部署","seq":87,"isStar":false,"memo":"构词 deploy(部署)+-ment(名词后缀)→展开兵力的安排→部署","example":"The deployment of troops began at dawn. 部队的部署在黎明时分开始。"},{"id":3221,"unit":10,"lesson":3,"word":"plausible","pronunciation":"/ˈplɔːzəb(ə)l/","meaning":"adj.似乎有道理的;似乎可信的","seq":88,"isStar":false,"memo":"[联想] plaus(音似“扑老死”) + -ible(形容词后缀)→武松扑向老虎并把老虎打死了，这个故事是“似乎可信的”。","example":"Her story sounded perfectly plausible. 她的说辞听起来完全合理。"},{"id":3222,"unit":10,"lesson":3,"word":"abstract","pronunciation":"/ˈæbstrækt/","meaning":"n.摘要","seq":89,"isStar":false,"memo":"[联想] abs-(=ab-,离开) + tract(音似“拽个它”)→拽着它离开→摘要;提取","example":"They can abstract precious medicines from ordinary substances. 他们能从普通物质中提取珍贵药物。"},{"id":3223,"unit":10,"lesson":3,"word":"extract","pronunciation":"/ˈekstrækt; ɪkˈstrækt/","meaning":"v.取出;提取 n.提取,摘录;提取物","seq":90,"isStar":false,"memo":"[构词] ex-(向外) + tract(拽,拉)→向外拽→取出","example":"The following extract is taken from her new novel. 下面一段摘自她的新小说。"},{"id":3224,"unit":10,"lesson":3,"word":"extraction","pronunciation":"/ɪkˈstrækʃn/","meaning":"n.提取;拔出","seq":91,"isStar":false},{"id":3225,"unit":10,"lesson":3,"word":"contract","pronunciation":"/ˈkɒntrækt; kənˈtrækt/","meaning":"n.合同,契约 v.与……订立合同;缩小","seq":92,"isStar":false,"memo":"[构词] con-(一起,相互) + tract(拽,拉)→拉到一起→合同,契约","example":"He mailed me the contract. 他把合同寄给了我。"},{"id":3226,"unit":10,"lesson":3,"word":"contraction","pronunciation":"/kənˈtrækʃ(ə)n/","meaning":"n.收缩;缩小","seq":93,"isStar":false},{"id":3227,"unit":10,"lesson":3,"word":"subtract","pronunciation":"/səbˈtrækt/","meaning":"v.减去,减掉","seq":94,"isStar":false,"memo":"[构词] sub-(往下) + tract(拽,拉)→往下拽→减去,减掉","example":"This subtracts loss in value of factories and equipment. 这减去了工厂和设备的价值损失。"},{"id":3228,"unit":10,"lesson":3,"word":"attract","pronunciation":"/əˈtrækt/","meaning":"v.吸引;引起","seq":95,"isStar":false,"memo":"联想 at-(一再地)+tract(拽,拉)→吸引;引起","example":"All the key words are printed in bold type so as to attract readers' attention. 所有的关键词都用粗体字印刷,以吸引读者的注意。"},{"id":3229,"unit":10,"lesson":3,"word":"attraction","pronunciation":"/əˈtrækʃ(ə)n/","meaning":"n.吸引,吸引力","seq":96,"isStar":false},{"id":3230,"unit":10,"lesson":3,"word":"attractive","pronunciation":"/əˈtræktɪv/","meaning":"adj.有吸引力的","seq":97,"isStar":false},{"id":3231,"unit":10,"lesson":3,"word":"distract","pronunciation":"/dɪˈstrækt/","meaning":"v.转移(注意力),使分心","seq":98,"isStar":false,"memo":"构词 dis-(分开,分散)+tract(拽,拉)→转移(注意力);使分心","example":"You're distracting me from my work. 你使我不能专心工作。"},{"id":3232,"unit":10,"lesson":3,"word":"distraction","pronunciation":"/dɪˈstrækʃn/","meaning":"n.使人分心的事物","seq":99,"isStar":false},{"id":3233,"unit":10,"lesson":3,"word":"drag","pronunciation":"/dræɡ/","meaning":"v.拖,拉,拽 n.累赘","seq":100,"isStar":false,"memo":"谐音 单词发音类似“拽个”→拖,拉,拽","example":"The luggage is too heavy to lift—you'll have to drag it. 这件行李太重了,提不起来——你得拖着走。"},{"id":3234,"unit":10,"lesson":3,"word":"tow","pronunciation":"/təʊ/","meaning":"n.(车、船等的)牵引","seq":101,"isStar":false,"memo":"谐音 单词发音类似“拖”。","example":"Our car was towed away by the police. 我们的汽车被警察拖走了。"},{"id":3235,"unit":10,"lesson":3,"word":"haul","pronunciation":"/hɔːl/","meaning":"v.拉,拖,拽","seq":102,"isStar":false,"memo":"谐音 单词发音类似“嚎”→纤夫拉船时发出的声音像“嚎”,拖得很长→拉,拖,拽","example":"The car was hauled out of the river. 汽车被拖出了河。"},{"id":3236,"unit":10,"lesson":3,"word":"accumulate","pronunciation":"/əˈkjuːmjəleɪt/","meaning":"v.积累,积聚;(数量)逐渐增加","seq":103,"isStar":false,"memo":"联想 ac-(一再地)+cumu(音似“可莫”)+late(晚)→我一再强调,六级可莫准备晚了,要提前“积累”词汇。","example":"Dust soon accumulates if the rooms are not swept. 如果不打扫房间,灰尘很快就会越积越多。"},{"id":3237,"unit":10,"lesson":3,"word":"accumulation","pronunciation":"/əˌkjuːmjəˈleɪʃn/","meaning":"n.积累","seq":104,"isStar":false},{"id":3238,"unit":10,"lesson":3,"word":"accumulative","pronunciation":"/əˈkjuːmjələtɪv/","meaning":"adj.累积的","seq":105,"isStar":false},{"id":3239,"unit":10,"lesson":3,"word":"cumulative","pronunciation":"/ˈkjuːmjələtɪv/","meaning":"adj.累积的,积累的;累计的","seq":106,"isStar":false,"memo":"构词 cumul(堆积，同 accumulate 积累)+-ative(形容词后缀)→一层层堆起来的→累积的，积累的，累计的","example":"Depression is often caused by the cumulative effects of stress and overwork. 抑郁症通常是压力和过度劳累的累积效应造成的。"},{"id":3240,"unit":10,"lesson":3,"word":"centralise/-ize","pronunciation":"/ˈsentrəlaɪz/","meaning":"v.使……处于中央的控制之下,集权控制","seq":107,"isStar":false,"memo":"构词 central(中心的)+-ise/-ize(使…化)→使归到中心→使处于中央的控制之下，集权控制","example":"The company centralised all its purchasing. 公司把所有采购都集中管理。"},{"id":3241,"unit":10,"lesson":3,"word":"concentrate","pronunciation":"/ˈkɒns(ə)ntreɪt/","meaning":"n.浓缩物 v.集中,专心于","seq":108,"isStar":false,"memo":"构词 con-(共同)+centr(=centre)+-ate(动词后缀)→共同以……为中心→集中","example":"Many studies reveal that eating breakfast helps people concentrate. 许多研究表明,吃早餐有助于人们集中注意力。"},{"id":3242,"unit":10,"lesson":3,"word":"concentration","pronunciation":"/ˌkɒns(ə)nˈtreɪʃ(ə)n/","meaning":"n.专心,专注;重视;浓度","seq":109,"isStar":false},{"id":3243,"unit":10,"lesson":4,"word":"dynamic","pronunciation":"/daɪˈnæmɪk/","meaning":"n.动力 adj.精力充沛的,充满活力的","seq":1,"isStar":false,"memo":"联想 dy(联想“大雁”)+na(联想“拿”)+mic(音似“麦克”)→大雁是个内向的人,但只要拿起麦克风,她就充满活力→充满活力的","example":"He was a dynamic young advertising executive. 他是一位充满活力的年轻广告主管。"},{"id":3244,"unit":10,"lesson":4,"word":"dynamics","pronunciation":"/daɪˈnæmɪks/","meaning":"n.动力学;力度","seq":2,"isStar":false},{"id":3245,"unit":10,"lesson":4,"word":"energy","pronunciation":"/ˈenədʒi/","meaning":"n.精力;活力;干劲;力量;能量","seq":3,"isStar":false,"memo":"谐音 单词发音类似“俺奶鸡”→俺奶奶还抓鸡呢,“精力”特别旺盛。","example":"That is a waste of time and energy. 那是对时间和精力的浪费。"},{"id":3246,"unit":10,"lesson":4,"word":"energetic","pronunciation":"/ˌenəˈdʒetɪk/","meaning":"adj.精力充沛的,充满活力的","seq":4,"isStar":false},{"id":3247,"unit":10,"lesson":4,"word":"energetically","pronunciation":"/ˌenəˈdʒetɪkli/","meaning":"adv.精力充沛地,充满活力地","seq":5,"isStar":false},{"id":3248,"unit":10,"lesson":4,"word":"animate","pronunciation":"/ˈænɪmeɪt/","meaning":"v.使具活力","seq":6,"isStar":false,"memo":"构词 anim(生命、气息，同 animal)+-ate(动词后缀)→给东西注入气息→使具活力，使生气勃勃；有生命的","example":"A smile animated her face. 一个微笑让她脸上有了生气。"},{"id":3249,"unit":10,"lesson":4,"word":"animated","pronunciation":"/ˈænɪmeɪtɪd/","meaning":"adj.兴致勃勃的;栩栩如生的","seq":7,"isStar":false,"memo":"构词 animat(使有生气)+-ed(形容词后缀)→充满生气的→兴致勃勃的；栩栩如生的","example":"They had an animated discussion. 他们进行了一场热烈的讨论。"},{"id":3250,"unit":10,"lesson":4,"word":"animation","pronunciation":"/ˌænɪˈmeɪʃ(ə)n/","meaning":"n.动画片;活力","seq":8,"isStar":false,"memo":"构词 animat(使有生气)+-ion(名词后缀)→让画面动起来→动画片；活力","example":"The film uses computer animation. 这部电影使用了电脑动画。"},{"id":3251,"unit":10,"lesson":4,"word":"activate","pronunciation":"/ˈæktɪveɪt/","meaning":"v.使活动;激活;使活化","seq":9,"isStar":false,"memo":"对照 act v.&n.行动→active adj.活跃的→activate v.","example":"Researchers succeeded in determining how coffee activated different areas of the brain. 研究人员成功确定了咖啡是如何激活大脑的不同区域的。"},{"id":3252,"unit":10,"lesson":4,"word":"battery","pronunciation":"/ˈbætri/","meaning":"n.电池","seq":10,"isStar":false,"memo":"对照 她试图在市面上寻找一款更好的(better)电池(battery),但结果让她大失所望。","example":"They have long believed in the promise of batteries to change the world. 长期以来,他们一直相信电池能够改变世界。"},{"id":3253,"unit":10,"lesson":4,"word":"enthusiastic","pronunciation":"/ɪnˌθjuːziˈæstɪk/","meaning":"adj.热心的,热情的","seq":11,"isStar":false,"example":"He wasn't discouraged and soon got as enthusiastic as ever. 他并不气馁，很快就恢复了一如既往的热情。"},{"id":3254,"unit":10,"lesson":4,"word":"enthusiast","pronunciation":"/ɪnˈθjuːziæst/","meaning":"n.爱好者","seq":12,"isStar":false},{"id":3255,"unit":10,"lesson":4,"word":"enthusiasm","pronunciation":"/ɪnˈθjuːziæzəm/","meaning":"n.热情,热心","seq":13,"isStar":false,"memo":"en（进入）+ thusi（神）+ asm（状态）→ 进入‘神’附体的状态！像追星现场狂热打call～","example":"Students showed genuine enthusiasm during the robotics workshop. 学生们在机器人工作坊中表现出真正的热情。"},{"id":3256,"unit":10,"lesson":4,"word":"enthusiastically","pronunciation":"/ɪnˌθjuːziˈæstɪkli/","meaning":"adv.热心地,热情地","seq":14,"isStar":false},{"id":3257,"unit":10,"lesson":4,"word":"indifferent","pronunciation":"/ɪnˈdɪfrənt/","meaning":"adj.冷漠的,不关心的","seq":15,"isStar":false,"memo":"[联想] in-(否定前缀) + different(不同的) →对于没有什么不同的事物，人们的态度通常是“冷漠的”。","example":"They are indifferent and keep on throwing garbage into the river. 他们漠不关心，并继续往河里扔垃圾。"},{"id":3258,"unit":10,"lesson":4,"word":"indifference","pronunciation":"/ɪnˈdɪfrəns/","meaning":"n.冷漠,漠不关心","seq":16,"isStar":false},{"id":3259,"unit":10,"lesson":4,"word":"differentiate","pronunciation":"/ˌdɪfəˈrenʃieɪt/","meaning":"v.区分,区别","seq":17,"isStar":false,"memo":"[对照] 他擅长区分(differentiate)不同的(different)事物，找出它们的不同(difference)。","example":"I can't differentiate one variety from another. 我无法区分不同的品种。"},{"id":3260,"unit":10,"lesson":4,"word":"differentiation","pronunciation":"/ˌdɪfəˌrenʃiˈeɪʃn/","meaning":"n.区分,区别","seq":18,"isStar":false},{"id":3261,"unit":10,"lesson":4,"word":"sober","pronunciation":"/ˈsəʊbə(r)/","meaning":"adj.未喝醉的,清醒的 v.使清醒","seq":19,"isStar":false,"memo":"[对照] 喝完苏打水(soda)你会很清醒的(sober)。","example":"I turn to eccentric measures to try to keep my mind sober. 我开始采取一些古怪的方法来努力保持头脑清醒。"},{"id":3262,"unit":10,"lesson":4,"word":"soda","pronunciation":"/ˈsəʊdə/","meaning":"n.苏打汽水","seq":20,"isStar":false,"memo":"[谐音] 单词发音类似“苏打”。","example":"Add some soda to the whisky, please. 请在威士忌中加点苏打水。"},{"id":3263,"unit":10,"lesson":4,"word":"passion","pronunciation":"/ˈpæʃ(ə)n/","meaning":"n.激情,热情","seq":21,"isStar":false,"memo":"构词 pass(承受、强烈情感)+-ion(名词后缀)→强烈到让人承受不住的情感→激情，热情","example":"She has a passion for music. 她对音乐有极大的热情。"},{"id":3264,"unit":10,"lesson":4,"word":"passionate","pronunciation":"/ˈpæʃənət/","meaning":"adj.激情的,热情的","seq":22,"isStar":false,"memo":"构词 passion(激情)+-ate(形容词后缀)→被激情填满的→激情的，热情的","example":"He is passionate about protecting the environment. 他热忱于保护环境。"},{"id":3265,"unit":10,"lesson":4,"word":"compassion","pronunciation":"/kəmˈpæʃ(ə)n/","meaning":"n.同情;怜悯","seq":23,"isStar":false,"memo":"[联想] com-(所有，都) + passion(激情)→该事件使人们群情激愤，对受害者充满了“同情”。","example":"She felt great compassion for the refugees. 她对难民深表同情。"},{"id":3266,"unit":10,"lesson":4,"word":"compassionate","pronunciation":"/kəmˈpæʃənət/","meaning":"adj.有同情心的","seq":24,"isStar":false,"memo":"构词 com-(共同)+passion(情感)+-ate(形容词后缀)→能与人共情的→有同情心的","example":"The nurse was kind and compassionate. 这位护士善良而有同情心。"},{"id":3267,"unit":10,"lesson":4,"word":"compass","pronunciation":"/ˈkʌmpəs/","meaning":"n.指南针;范围","seq":25,"isStar":false,"memo":"联想 com(联想 come) + pass(通过) → 通过森林时容易迷路，需要用“指南针”才能确认方向。","example":"We had to rely on a compass and a lot of luck to get here. 我们只得靠指南针和很多的好运才来到这里。"},{"id":3268,"unit":10,"lesson":4,"word":"compact","pronunciation":"/kəmˈpækt/","meaning":"adj.紧密的;密集的;敦实的 v.压紧","seq":26,"isStar":false,"memo":"联想 com-(所有，都) + pact (音似“拍个它”) → 做年糕时，所有人都过来拍它，把它“压紧”。","example":"Their bodies are sleek and compact. 它们的身体光滑而紧实。"},{"id":3269,"unit":10,"lesson":4,"word":"impact","pronunciation":"/ˈɪmpækt/","meaning":"n.作用;影响","seq":27,"isStar":false,"memo":"联想 im-(= in-, 进入) + pact (音似“拍个它”) → 进入房间拍它会对其产生“影响”。","example":"The new policy will impact the economic development of the country. 新政策将会对这个国家的经济发展产生影响。"},{"id":3270,"unit":10,"lesson":4,"word":"influence","pronunciation":"/ˈɪnfluəns/","meaning":"n.影响(力),作用","seq":28,"isStar":false,"memo":"构词 in-(入) + flu(= flow) + -ence(后缀) → 流入某物(从而波及) → 影响","example":"Some experts are suggesting that we turn peer influence to good use in education. 一些专家建议我们在教育中充分利用同伴影响的积极作用。"},{"id":3271,"unit":10,"lesson":4,"word":"influential","pronunciation":"/ˌɪnfluˈenʃ(ə)l/","meaning":"adj.有影响力的","seq":29,"isStar":false,"memo":"对照 influence n. & v.影响 → influential adj.","example":"She is one of the most influential figures in local politics. 她是本地政坛最有影响力的人物之一。"},{"id":3272,"unit":10,"lesson":4,"word":"compatible","pronunciation":"/kəmˈpætəb(ə)l/","meaning":"adj.兼容的,可共用的;可共存的","seq":30,"isStar":false,"memo":"联想 com-(一起，相互) + pat (音似“拍打”) + -ible(形容词后缀) → 那两个人可以相互拍打肩膀，他们是“关系好的”朋友。","example":"His political views weren't compatible with mine. 他的政治观点和我的政治观点不相容。"},{"id":3273,"unit":10,"lesson":4,"word":"compatibility","pronunciation":"/kəmˌpætəˈbɪləti/","meaning":"n.和睦相处;并存;相容","seq":31,"isStar":false},{"id":3274,"unit":10,"lesson":4,"word":"tedious","pronunciation":"/ˈtiːdiəs/","meaning":"adj.枯燥乏味的;冗长的","seq":32,"isStar":false,"memo":"[联想] tedi(联想“特地”)+o(形似甜甜圈)+us(我们)→我们特地去到奶奶家和她一起做甜甜圈,以消解她“枯燥乏味”的情绪。","example":"It is really tedious to sit in the office reading newspapers and drinking tea. 坐在办公室读报纸、喝茶真是一件乏味的事情。"},{"id":3275,"unit":10,"lesson":4,"word":"dull","pronunciation":"/dʌl/","meaning":"v.减轻;(使)变麻木","seq":33,"isStar":false,"memo":"[联想] du(联想“读”)+ll(形似罗马数字2)→她今天读了两本“无聊的”书。","example":"Life in a small town could be deadly dull. 小城镇的生活可能乏味至极。"},{"id":3276,"unit":10,"lesson":4,"word":"routine","pronunciation":"/ruːˈtiːn/","meaning":"n.常规,惯例;例行公事;例行程序","seq":34,"isStar":false,"memo":"[谐音] 单词发音类似“路听”→虽然老板比较忙,但也会按照“惯例”在路上听秘书汇报工作。","example":"I have to handle some routine tasks. 我不得不处理一些日常工作。"},{"id":3277,"unit":10,"lesson":4,"word":"agenda","pronunciation":"/əˈdʒendə/","meaning":"n.(会议的)议程表,议事日程","seq":35,"isStar":false,"memo":"[联想] a(一)+gen(音似“件”)+da(联想“大”)→一件大(事)→大事必须放在“议程表”里。","example":"Playing cards was on the agenda. 打牌被提上了日程。"},{"id":3278,"unit":10,"lesson":4,"word":"summary","pronunciation":"/ˈsʌməri/","meaning":"n.总结;概括,概要 adj.总结性的","seq":36,"isStar":false,"memo":"构词 summ(总数，同 sum)+-ary(名词后缀)→把所有内容加总起来→总结，概要；总结性的，概括的","example":"The following is a summary of our conclusions. 现将我们的几点结论综述如下。"},{"id":3279,"unit":10,"lesson":4,"word":"summarise/-ize","pronunciation":"/ˈsʌməraɪz/","meaning":"v.总结;概括","seq":37,"isStar":false,"memo":"构词 summar(概要)+-ise/-ize(使…化)→做成概要→总结，概括","example":"Please summarise the article in one paragraph. 请用一段话概括这篇文章。"},{"id":3280,"unit":10,"lesson":4,"word":"sum","pronunciation":"/sʌm/","meaning":"n.金额,款项;总数 v.总结,概括","seq":38,"isStar":false,"example":"He has been donating a large sum of money to charity. 他一直在向慈善机构捐赠大笔款项。"},{"id":3281,"unit":10,"lesson":4,"word":"audit","pronunciation":"/ˈɔːdɪt/","meaning":"n.审计,稽核;(质量或标准的)审查","seq":39,"isStar":false,"memo":"构词 aud(听，同 audio 音频)+-it(名词后缀)→最初指“一听账”→审计，稽核；审查，检查","example":"Each year they audit our accounts.每年他们都审计我们的账目。"},{"id":3282,"unit":10,"lesson":4,"word":"auditing","pronunciation":"/ˈɔːdɪtɪŋ/","meaning":"n.审计;检查","seq":40,"isStar":false},{"id":3283,"unit":10,"lesson":4,"word":"auditor","pronunciation":"/ˈɔːdɪtə(r)/","meaning":"n.审计员;稽核员","seq":41,"isStar":false},{"id":3284,"unit":10,"lesson":4,"word":"arithmetic","pronunciation":"/əˈrɪθmətɪk/","meaning":"n.算术;算术运算","seq":42,"isStar":false,"memo":"[谐音] 单词发音类似“阿瑞斯没听课”→阿瑞斯没听“算术”课,所以“算术运算”得了零分。","example":"It is just as important as a knowledge of the basic arithmetic formulas. 它和掌握基本的算术公式一样重要。"},{"id":3285,"unit":10,"lesson":4,"word":"atlas","pronunciation":"/ˈætləs/","meaning":"n.地图册;地图集","seq":43,"isStar":false,"memo":"联想 源自希腊神话中托举天空的巨人 Atlas，地图册封面常画他→地图册，地图集","example":"They are exactly the same as those shown in the atlas.它们与地图集上显示的完全相同。"},{"id":3286,"unit":10,"lesson":4,"word":"brochure","pronunciation":"/ˈbrəʊʃə(r)/","meaning":"n.手册,小册子","seq":44,"isStar":false,"memo":"联想 bro(联想 brother)+chu(联想“出”)+re(字母音似“阿姨”)→哥哥出去递给过路的阿姨一个“小册子”。","example":"They can find the application forms in the brochure. 他们可以在小册子里找到申请表。"},{"id":3287,"unit":10,"lesson":4,"word":"leaflet","pronunciation":"/ˈliːflət/","meaning":"n.传单;小册子","seq":45,"isStar":false,"memo":"构词 leaf(叶→页)+-let(小)→传单;小册子","example":"She had 500 leaflets to stuff into envelopes. 她要把500份传单装进信封里。"},{"id":3288,"unit":10,"lesson":4,"word":"graph","pronunciation":"/ɡrɑːf/","meaning":"n.图,图表,曲线图","seq":46,"isStar":false,"memo":"构词 graph(写、画)→画出来的线→图，图表，曲线图","example":"In the graph, the population of farmers has decreased sharply in the past 10 years. 在图表中,农民的数量在过去10年内急剧减少。"},{"id":3289,"unit":10,"lesson":4,"word":"graphic","pronunciation":"/ˈɡræfɪk/","meaning":"adj.绘画的;图样的 n.图表,图形","seq":47,"isStar":false},{"id":3290,"unit":10,"lesson":4,"word":"graphically","pronunciation":"/ˈɡræfɪkli/","meaning":"adv.以书画(或图表)形式;形象地","seq":48,"isStar":false},{"id":3291,"unit":10,"lesson":4,"word":"career","pronunciation":"/kəˈrɪə(r)/","meaning":"n.生涯,职业;经历;事业","seq":49,"isStar":false,"memo":"联想 car(车)+-eer(名词后缀)→他们是从事不同“职业”的人,坐的车也不同;车走过的路就是他们的“经历”。","example":"He is at the peak of his career. 他正处在事业的巅峰。"},{"id":3292,"unit":10,"lesson":4,"word":"carpenter","pronunciation":"/ˈkɑːpəntə(r)/","meaning":"n.木工;木匠","seq":50,"isStar":false,"memo":"联想 car(车)+pen(音似“棚”)+t+-er(表示人的后缀)→古时候,制作车和车棚的人是“木匠”。","example":"They were skilled carpenters themselves. 他们自己就是技术熟练的木匠。"},{"id":3293,"unit":10,"lesson":4,"word":"carriage","pronunciation":"/ˈkærɪdʒ/","meaning":"n.(火车的)客车厢;四轮马车;运输","seq":51,"isStar":false,"memo":"构词 carri(=carry)+-age(名词后缀)→与“运送”相关的事物→客车厢;四轮马车","example":"There are workers pushing carriages. 有推着四轮马车的工人。"},{"id":3294,"unit":10,"lesson":4,"word":"carrier","pronunciation":"/ˈkæriə(r)/","meaning":"n.运输工具;运载工具;携带者","seq":52,"isStar":false,"memo":"对照 carry v.运送;携带→carrier n.","example":"He is a water carrier. 他是一个送水员。"},{"id":3295,"unit":10,"lesson":4,"word":"cart","pronunciation":"/kɑːt/","meaning":"n.手推车;购物车;运货马车","seq":53,"isStar":false,"memo":"谐音 单词发音类似“卡他”→他推“购物车”上扶梯时,车卡住了。","example":"He pushed the cart around the supermarket. 他推着购物车在超市里转。"},{"id":3296,"unit":10,"lesson":4,"word":"caravan","pronunciation":"/ˈkærəvæn/","meaning":"n.旅行拖车;大篷车","seq":54,"isStar":false,"memo":"构词 car(车)+avan(队)→连成一队的车→旅行拖车，大篷车；旅行队，车队","example":"The caravan travelled slowly eastwards.大篷车队缓慢地向东行进。"},{"id":3297,"unit":10,"lesson":4,"word":"cargo","pronunciation":"/ˈkɑːɡəʊ/","meaning":"n.(船或飞机装载的)货物","seq":55,"isStar":false,"memo":"联想 car(车)+go(走了)→车装满“货物”就走了。","example":"You can contract with us to deliver your cargo. 你可以和我们签订合同,由我们负责运输货物。"},{"id":3298,"unit":10,"lesson":4,"word":"charge","pronunciation":"/tʃɑːdʒ/","meaning":"n.收费;控告;责任 v.收(费);控告","seq":56,"isStar":false,"memo":"联想 cha(联想“叉”)+r(形似叉子)+ge(联想“哥”)→你用叉子叉到哥哥的手了,哥哥开玩笑说,你得负“责任”,否则就要“控告”你。","example":"He faces trial on several charges. 他面临针对多项指控的审判。"},{"id":3299,"unit":10,"lesson":4,"word":"numerical","pronunciation":"/njuːˈmerɪk(ə)l/","meaning":"adj.数字的;用数字表示的","seq":57,"isStar":false,"memo":"构词 numer(=number)+-ical(形容词后缀)→数字的;用数字表示的","example":"The results are expressed in descending numerical order. 结果按数字降序列出。"},{"id":3300,"unit":10,"lesson":4,"word":"numerous","pronunciation":"/ˈnjuːmərəs/","meaning":"adj.众多的,许多的","seq":58,"isStar":false,"memo":"构词 numer(=number)+-ous(形容词后缀)→数量多的→许多的","example":"This scale took numerous factors into consideration. 这个量表考虑了许多因素。"},{"id":3301,"unit":10,"lesson":4,"word":"innumerable","pronunciation":"/ɪˈnjuːmərəb(ə)l/","meaning":"adj.无数的,大量的,多得数不清的","seq":59,"isStar":false,"memo":"构词 in-(否定前缀)+numer(=number)+-able(形容词后缀)→不能用数量衡量的→无数的,大量的","example":"This mountain was the home of innumerable birds. 这座山是无数鸟儿的家园。"},{"id":3302,"unit":10,"lesson":4,"word":"biology","pronunciation":"/baɪˈɒlədʒi/","meaning":"n.生物学","seq":60,"isStar":false,"memo":"构词 bio(生物)+-logy(名词后缀,表学科)→有关生物的学科→生物学","example":"Biology is one of my favourite subjects. 生物是我最喜欢的学科之一。"},{"id":3303,"unit":10,"lesson":4,"word":"antibiotic","pronunciation":"/ˌæntibaɪˈɒtɪk/","meaning":"n.抗生素 adj.抗生的;抗菌的","seq":61,"isStar":false,"example":"The doctor put her on antibiotics.医生让她服用抗生素。"},{"id":3304,"unit":10,"lesson":4,"word":"biochemistry","pronunciation":"/ˌbaɪəʊˈkemɪstri/","meaning":"n.生物化学","seq":62,"isStar":false,"memo":"构词 bio-(生物)+chemistry(化学)→生物化学","example":"Joan and her friends are studying biochemistry at university.琼和她的朋友们在大学学习生物化学。"},{"id":3305,"unit":10,"lesson":4,"word":"biotechnology","pronunciation":"/ˌbaɪəʊtekˈnɒlədʒi/","meaning":"n.生物科技","seq":63,"isStar":false,"memo":"构词 bio-(生物)+technology(科学技术)→生物科技","example":"Biotechnology can improve crop yields.生物技术可以提高作物产量。"},{"id":3306,"unit":10,"lesson":4,"word":"biography","pronunciation":"/baɪˈɒɡrəfi/","meaning":"n.传记","seq":64,"isStar":false,"memo":"[构词] bio-(生物,生命) + graph(写) + -y(名词后缀)→对生命的书写→传记","example":"The book gives potted biographies of all the major painters. 这本书简述了所有重要画家的生平。"},{"id":3307,"unit":10,"lesson":4,"word":"autobiography","pronunciation":"/ˌɔːtəbaɪˈɒɡrəfi/","meaning":"n.自传","seq":65,"isStar":false,"memo":"构词 auto-(自己)+biography(传记)→自己的传记→自传","example":"In his autobiography, he recalls the poverty he grew up in.在他的自传中，他回忆起自己成长过程中的贫困。"},{"id":3308,"unit":10,"lesson":4,"word":"expressway","pronunciation":"/ɪkˈspresweɪ/","meaning":"n.(美国)高速公路","seq":66,"isStar":false,"memo":"构词 express(快速的)+way(路)→高速公路","example":"There was an immense network of paved roads and expressways.当时有一个庞大的铺装公路和高速公路网络。"},{"id":3309,"unit":10,"lesson":4,"word":"halfway","pronunciation":"/ˌhɑːfˈweɪ/","meaning":"adv.&adj.半途(的),中间(的)","seq":67,"isStar":false,"memo":"构词 half(一半)+way(道路)→半途(的),中间(的)","example":"Because of the dense fog, we have to stop our journey halfway.由于大雾，我们不得不中途停下行程。"},{"id":3310,"unit":10,"lesson":4,"word":"subway","pronunciation":"/ˈsʌbweɪ/","meaning":"n.地铁;地下通道","seq":68,"isStar":false,"memo":"[构词] sub-(在……下面) + way(路)→在地下的路→地铁;地下通道","example":"I've never been on the subway. 我从来没坐过地铁。"},{"id":3311,"unit":10,"lesson":4,"word":"convoy","pronunciation":"/ˈkɒnvɔɪ/","meaning":"n.(尤指有士兵护送的)车队","seq":69,"isStar":false,"memo":"联想 con-(共同,一起)+voy(音似“我”)→他们一起“护送”我到车站。","example":"A warship convoyed the merchant ships across the dangerous waters.一艘军舰护送商船穿越危险水域。"},{"id":3312,"unit":10,"lesson":4,"word":"envoy","pronunciation":"/ˈenvɔɪ/","meaning":"n.使者,使节;(谈判等的)代表","seq":70,"isStar":false,"memo":"构词 en-(使进入)+voy(路，同 voyage 航行)→被派上路的人→使者，使节；代表","example":"The envoy delivered the message in person. 使者亲自递交了信件。"},{"id":3313,"unit":10,"lesson":4,"word":"tailor","pronunciation":"/ˈteɪlə(r)/","meaning":"n.裁缝 v.定做;调整","seq":71,"isStar":false,"memo":"构词 tail(切,剪)+-or(后缀)→进行切和剪的人→裁缝","example":"He works as a tailor. 他是一个裁缝。"},{"id":3314,"unit":10,"lesson":4,"word":"curtail","pronunciation":"/kɜːˈteɪl/","meaning":"v.缩短;缩减","seq":72,"isStar":false,"memo":"构词 cur(短，同 curt 简短的)+tail(尾巴)→把尾巴剪短→缩短；缩减","example":"Spending on books has been severely curtailed.图书开支被大幅削减。"},{"id":3315,"unit":10,"lesson":4,"word":"detail","pronunciation":"/ˈdiːteɪl/","meaning":"n.细节,详情","seq":73,"isStar":false,"memo":"构词 de-(表加强)+tail(切)→切开(成很小的份);切碎→细节","example":"Can you tell me the story in detail? 你能详细地给我讲下这个故事吗?"},{"id":3316,"unit":10,"lesson":4,"word":"detailed","pronunciation":"/ˈdiːteɪld/","meaning":"adj.详细的;细致的","seq":74,"isStar":false},{"id":3317,"unit":10,"lesson":4,"word":"stitch","pronunciation":"/stɪtʃ/","meaning":"n.(缝纫的)一针,针脚;缝 v.缝补","seq":75,"isStar":false,"memo":"谐音 单词发音类似“撕地契”→地契被撕碎了,得“一针”一针地“缝”起来。","example":"Put a stitch in the corner of the pocket to keep it in place. 在口袋角那儿缝一针把它固定住。"},{"id":3318,"unit":10,"lesson":4,"word":"stigma","pronunciation":"/ˈstɪɡmə/","meaning":"n.耻辱;羞耻","seq":76,"isStar":false,"memo":"构词 stig(刺、烙印，同 stick 刺)+-ma(名词后缀)→烫在身上的印记→耻辱；羞耻","example":"She overcame the stigma attached to mental illness.她克服了与精神疾病相关的耻辱。"},{"id":3319,"unit":10,"lesson":4,"word":"lipstick","pronunciation":"/ˈlɪpstɪk/","meaning":"n.口红;唇膏","seq":77,"isStar":false,"memo":"构词 lip(嘴唇)+stick(小棒)→抹在嘴唇上的小棒→口红，唇膏","example":"She was wearing bright red lipstick.她涂着鲜红色的口红。"},{"id":3320,"unit":10,"lesson":4,"word":"matter","pronunciation":"/ˈmætə(r)/","meaning":"n.物质;问题 v.重要","seq":78,"isStar":false,"memo":"谐音 单词发音类似“买它”→这种“物质”很“重要”,买下它吧。","example":"Somehow it didn't seem to matter much any more. 不知怎么地,这似乎已经不大重要了。"},{"id":3321,"unit":10,"lesson":4,"word":"maternal","pronunciation":"/məˈtɜːn(ə)l/","meaning":"adj.母亲的;母系的","seq":79,"isStar":false,"memo":"构词 mater(母亲，同 mother)+-nal(形容词后缀)→与母亲有关的→母亲的；母系的","example":"She felt a strong maternal instinct. 她感到强烈的母性本能。"},{"id":3322,"unit":10,"lesson":4,"word":"maternity","pronunciation":"/məˈtɜːnəti/","meaning":"n.母性;母亲身份;怀孕","seq":80,"isStar":false,"memo":"构词 mater(母亲)+-ity(名词后缀)→做母亲的状态→母性；母亲身份；怀孕","example":"She is on maternity leave. 她正在休产假。"},{"id":3323,"unit":10,"lesson":4,"word":"metaphor","pronunciation":"/ˈmetəfə(r)/","meaning":"n.暗喻;隐喻","seq":81,"isStar":false,"memo":"构词 meta-(超越)+phor(携带，同 transfer 转移)→把意思“搬”到另一个词上→暗喻，隐喻","example":"The poem uses the sea as a metaphor for life. 这首诗用大海隐喻人生。"},{"id":3324,"unit":10,"lesson":4,"word":"metaphorical","pronunciation":"/ˌmetəˈfɒrɪk(ə)l/","meaning":"adj.隐喻的;比喻性的","seq":82,"isStar":false}];